local P = LoreForeverPacks.Begin("LoreForever_Lang_itIT")
P.entries["quest:6387"] = {n="Studenti modello",s="Brock Scrutarocce invia da Thelsamar a Forgiardente un ordine per gli Honorary Picks. Ti chiede di incaricare Thorgrum Borrelson di portarlo lì.",h="Brock Scrutarocce invia da Thelsamar a Forgiardente un ordine per gli Honorary Picks.",kw={"brock scrutarocce","golnir granditone","grifone","studenti d'onore","forgiardente","loch modan","estrazione mineraria","thelsamar","thorgrum borrelson"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza a Loch Modan, incontri i maestri di volo e i corrieri aerei che collegano i suoi insediamenti.",["profession:Mining"]="Come minatore, vedi come i nani rendono onore all'abilità nel mestiere. Padroneggiare la pietra e trovare filoni può farti guadagnare il riconoscimento di un istruttore.",["race:Dwarf"]="Come nano, vedi il legame tra gli insediamenti di frontiera come Thelsamar e le sale della capitale, nel cuore delle montagne."},sec={{t="Il dovuto di un minatore",b="Brock insegna ai nuovi minatori la composizione delle rocce e la sicurezza nei tunnel. Ricompensa gli apprendisti che si distinguono con gli Honorary Picks. L'attività mineraria sostiene Thelsamar e i nani sono fieri di questo mestiere. Le scorte locali sono limitate, quindi i picconi devono arrivare da Forgiardente, oltre Khaz Modan."},{t="Verso i cieli",b="Thorgrum si occupa del Gryphon Roost accanto a Thelsamar, collegando la frontiera a Forgiardente tramite la rete di corrieri aerei del regno. Portagli l'ordine di Brock e potrà organizzare una rapida consegna alla capitale."}},faq={{q="Chi è Brock Scrutarocce?",a="Brock Scrutarocce insegna l'attività mineraria a Thelsamar. Addestra i novizi negli scavi e nella lavorazione della pietra.",al={"brock scrutarocce","chi è brock","istruttore minerario thelsamar"}},{q="Perché Brock ha bisogno dei picconi da Forgiardente?",a="Brock ha bisogno di Honorary Picks per gli studenti che eccellono nell'attività mineraria, ma le scorte locali sono limitate. Il suo ordine deve arrivare a Golnir Granditone, un venditore di forniture minerarie a Forgiardente.",al={"perché forgiaardente","perché i picconi","brock's list"}},{q="Quale ruolo svolge Thorgrum Borrelson in questo compito?",a="Thorgrum Borrelson si occupa del Gryphon Roost di Thelsamar. Brock ti chiede di portargli l'ordine, così potrà organizzare il trasporto aereo fino a Forgiardente.",al={"thorgrum borrelson","chi è thorgrum","maestro dei grifoni thelsamar"}},{q="Chi riceve la lista a Forgiardente?",a="Golnir Granditone riceve la lista a Forgiardente. Prepara gli Honorary Picks per gli studenti più meritevoli di Brock.",al={"chi riceve la lista","golnir granditone","contatto a forgiardente"}},{q="Dove porta questa commissione dopo?",a="Dopo aver parlato con Thorgrum Borrelson, questi organizza un volo in grifone per Forgiardente. Lì puoi consegnare l'ordine di Brock a Golnir Granditone.",al={"passo successivo","cosa segue studenti d'onore","dopo brock's list"}},{q="Dove si svolge questo compito?",a="Parti e fai ritorno a Thelsamar, un insediamento sulle colline di Loch Modan.",al={"luogo della missione","dov'è thelsamar","dove iniziare studenti d'onore"}}},fx={["7a941756"]={q="Perché Brock Scrutarocce chiede a un avventuriero di consegnare la lista invece di portarla lui stesso?",a="Brock è impegnato qui a Thelsamar ad addestrare aspiranti minatori, insegnando il mestiere alle nuove reclute e occupandosi della sua forgia. Lasciare il suo posto per andare fino a Forgiardente interromperebbe le lezioni degli apprendisti locali, perciò un avventuriero in viaggio è il corriere perfetto per portare la sua lista in città.",al={"perché chiedere a me, brock","perché brock non va a forgiardente","perché brock non può portare la lista"}}},fp="14,147,13.290.0,19.225.0,25.94.0,41.171.0,52.138.0,35.111.0,33.142.0,32.75.0"}
P.entries["quest:6388"] = {n="Gryth Thurden",s="A Forgiardente, Gryth Thurden può riportarti a Loch Modan con un pacco. Porti gli Honorary Picks di Golnir Granditone agli apprendisti minatori di Brock Scrutarocce, e il nido cittadino dei grifoni offre un passaggio oltre i valichi montani.",h="A Forgiardente, Gryth Thurden può riportarti a Loch Modan con un pacco.",kw={"mastro di volo","golnir granditone","gryth thurden","honorary picks","forgiardente","loch modan","thelsamar","thorgrum borrelson"},ang={["faction:Alliance"]="Come membro dell'Alleanza, puoi affidarti ai nidi dei grifoni di Forgiardente per trasportare gli emissari tra Dun Morogh, Loch Modan e i regni circostanti.",["profession:Mining"]="Come minatore, aiuti gli apprendisti di Brock Scrutarocce a Loch Modan con picconi cerimoniali forgiati a Forgiardente per rendere onore al loro mestiere.",["race:Dwarf"]="Come nano, ti affidi ai grifoni per attraversare vette insidiose. Sono una necessità pratica e una fonte di orgoglio ancestrale che unisce le sale montane."},sec={{t="Un corriere per i minatori",b="Hai viaggiato da Loch Modan alla Grande Forgia, dove Golnir Granditone ti consegna gli Honorary Picks per gli apprendisti minatori di Brock Scrutarocce. Ti indica la rete dei grifoni di Forgiardente invece dei passi montani da attraversare a piedi. Porta il pacco dall'altra parte della città fino al maestro dei grifoni, che può organizzare il tuo volo di ritorno."},{t="In volo verso Thelsamar",b="Gryth Thurden supervisiona i nidi dei grifoni di Forgiardente, nella grande sala montana. Le rotte dei grifoni collegano la città agli insediamenti nanici in tutto Khaz Modan. Dopo aver esplorato il percorso e parlato con il responsabile locale, puoi chiedere a Gryth di organizzare il trasporto di ritorno da Thorgrum Borrelson a Thelsamar. Gli attrezzi sono destinati agli apprendisti di Brock Scrutarocce, e la rotta collega per via aerea gli insediamenti montani."}},faq={{q="A cosa servono gli Honorary Picks?",a="Golnir Granditone ha fabbricato gli Honorary Picks a Forgiardente come strumenti cerimoniali per gli studenti di Brock Scrutarocce, un istruttore minerario di stanza a Thelsamar.",al={"honorary picks","a cosa servono gli honorary picks","honorary picks per brock"}},{q="Chi è Gryth Thurden?",a="Gryth Thurden supervisiona le rotte di volo dalla capitale nanica di Forgiardente agli insediamenti in tutto Khaz Modan e oltre.",al={"chi è gryth thurden","mastro grifoniere di forgiardente","storia di gryth thurden"}},{q="Dove si trova Gryth Thurden a Forgiardente?",a="Gryth Thurden si trova al nido dei grifoni della Grande Forgia, vicino all'arteria centrale principale e alle porte di Forgiardente.",al={"posizione di gryth thurden","dove trovare gryth thurden","mastro di volo di forgiardente"}},{q="Perché devo parlare prima con Thorgrum Borrelson?",a="Gryth Thurden può mandare un cavaliere a Thelsamar solo dopo che hai parlato con Thorgrum Borrelson, il responsabile di stanza a Loch Modan. I responsabili inviano cavalieri lungo rotte tracciate.",al={"requisito thorgrum borrelson","perché serve la rotta di volo per thelsamar","non posso volare a thelsamar"}},{q="Cosa succede dopo aver dato gli Honorary Picks a Gryth Thurden?",a="Dopo aver ispezionato il pacco, Gryth prepara un volo in grifone che ti permetterà di tornare a Thelsamar e consegnare gli attrezzi direttamente a Brock Scrutarocce.",al={"cosa fare dopo gryth thurden","prossima missione dopo gryth thurden"}},{q="Chi ti manda da Gryth Thurden?",a="Golnir Granditone, un artigiano che lavora nei pressi della Grande Forgia di Forgiardente, ti consegna gli attrezzi e ti indica Gryth.",al={"chi inizia gryth thurden","chi assegna questa missione"}}},fx={["05b277d3"]={q="Perché Golnir Granditone ti manda da Gryth Thurden?",a="Golnir Granditone ha preparato i picconi onorari destinati agli studenti di miniera di Brock Scrutarocce a Thelsamar. Invece di farti tornare a piedi lungo il passo innevato, Golnir ti indirizza da Gryth Thurden, il maestro dei grifoni di Forgiardente, così puoi imparare a organizzare un volo in grifone direttamente attraverso le montagne.",al={"perché mandare da gryth","motivo di golnir granditone","perché gryth thurden vuole i picconi"}}},fp="13,241,24.321.0,24.397.0,32.160.0,21.118.0,44.105.0,50.179.0,53.144.0,31.115.0"}
P.entries["quest:639"] = {n="Sigillo di Strom",s="A Requie del Martello, Zengu cerca i sigilli che proteggono Trol'kalar, la spada di Lord Ignaeus Trollbane. La Lega dei Tagliagole ha preso il Sigil of Strom, che probabilmente è in mano a un suo agente a Stromgarde.",h="A Requie del Martello, Zengu cerca i sigilli che proteggono Trol'kalar, la spada di Lord Ignaeus Trollbane.",kw={"altopiani d'arathi","requie del martello","ignaeus","sigil of strom","stromgarde","lega dei tagliagole","trol'kalar","trollbane","zengu"},sec={{t="L'eredità di Trollbane",b="Molto tempo fa, Lord Ignaeus di Strom, detto Trollbane, fu il più abile avversario dell'Impero Arathorian nella guerra contro i troll. In battaglia brandiva Trol'kalar. Nell'antica lingua dei troll, il suo nome significa uccisore di troll. Ora i figli di Trollbane sono indeboliti e la loro roccaforte giace in rovina."},{t="Il Primo Sigillo",b="Diversi sigilli proteggono Trol'kalar e i superstiti di Stromgarde ne presero alcuni ciascuno. Zengu dice che devono essere recuperati tutti. La Lega dei Tagliagole si è impadronita del primo, il Sigil of Strom. Zengu crede che lo abbia un suo agente a Stromgarde. Riporta il sigillo a Zengu a Requie del Martello."}},faq={{q="Chi è Zengu?",a="A Requie del Martello, ad Arathi, Zengu sta raccogliendo i sigilli che proteggono Trol'kalar, la spada di Lord Ignaeus Trollbane.",al={"chi consegna il sigil of strom","zengu requie del martello"}},{q="Cos'è Trol'kalar?",a="Trol'kalar significa uccisore di troll nell'antica lingua dei troll. Lord Ignaeus di Strom, detto Trollbane, cavalcò in battaglia contro i troll con la spada.",al={"cosa è trol'kalar","significato di trol'kalar","spada di trollbane"}},{q="Perché serve il Sigil of Strom?",a="Diversi sigilli proteggono Trol'kalar e i superstiti di Stromgarde se li divisero. Zengu li vuole tutti, a cominciare dal Sigil of Strom.",al={"perché prendere il sigillo","a cosa serve il sigil of strom"}},{q="Chi ha il Sigil of Strom?",a="La Lega dei Tagliagole ha preso il Sigil of Strom. Probabilmente lo porta con sé uno dei suoi agenti a Stromgarde.",al={"chi ha il sigil of strom","dove si trova il sigil of strom","sigillo della lega dei tagliagole"}}},fp="14,186,23.280.0,15.268.0,13.109.0,19.153.0,33.147.0,29.98.0"}
P.entries["quest:6391"] = {n="In volo verso Forgiardente",s="Brock Scrutarocce ti manda da Thelsamar a Forgiardente con i nomi dei suoi migliori allievi minatori. Porti la sua lista a Golnir Granditone, alla Grande Forgia.",h="Brock Scrutarocce ti manda da Thelsamar a Forgiardente con i nomi dei suoi migliori allievi minatori.",kw={"brock's list","deep mountain mining guild","golnir granditone","grande forgia","grifone","kharanos","viaggio verso forgiardente","thorgrum borrelson"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza, puoi fare affidamento sulle rotte dei grifoni per collegare le guarnigioni in prima linea di Khaz Modan con la sua capitale.",["profession:Mining"]="Come minatore, vedi come la Deep Mountain Mining Guild onori i minatori promettenti delle cave di Loch Modan, incidendone i nomi sui picconi.",["race:Dwarf"]="Da giovane nano Bronzebeard, il volo in grifone verso la Grande Forgia segna il tuo fiero passaggio dagli avamposti rurali al cuore del regno."},sec={{t="Prendi il Volo",b="Thorgrum Borrelson ti porta da Thelsamar, sopra le creste innevate di Dun Morogh, fino alla fortezza montana. Per molti giovani alpinisti e viaggiatori, è il primo volo in grifone."},{t="Onori della Deep Mountain Mining Guild",b="Alla Grande Forgia, Golnir Granditone incide i nomi degli studenti su Honorary Picks cerimoniali. Questo riconoscimento premia il loro duro lavoro nelle cave e nelle miniere di Loch Modan."}},faq={{q="Dove inizia e finisce questo volo?",a="Thorgrum Borrelson ti porta da Thelsamar, a Loch Modan, al posatoio di volo presso la Grande Forgia di Forgiardente.",al={"rotta del percorso di volo","dove posso volare","destinazione del viaggio"}},{q="Cos'è la Brock's List?",a="La lista di Brock Scrutarocce riporta i nomi dei suoi migliori allievi minatori di Thelsamar, così la gilda di Forgiardente può premiarne la dedizione.",al={"lore della brock's list","chi è brock","cos'è il documento"}},{q="Chi è Golnir Granditone?",a="Golnir Granditone rappresenta la Deep Mountain Mining Guild alla Grande Forgia di Forgiardente. Riceve gli elenchi dagli istruttori locali e incide i nomi degli studenti su Honorary Picks.",al={"ruolo di golnir","dove si trova golnir","chi è golnir granditone"}},{q="Cosa succede dopo aver consegnato la lista?",a="Dopo aver ricevuto l'elenco, Golnir ti manda da Gryth Thurden, il maestro dei grifoni di Forgiardente, per farti conoscere le rotte aeree del regno.",al={"missione successiva","cosa fare dopo","missione di collegamento"}},{q="Perché usare un grifone invece di camminare?",a="La strada di montagna e i tunnel raggiungono le Gates di Forgiardente, ma il volo in grifone mostra quanto rapidamente i viaggiatori dell'Alleanza possano spostarsi tra gli insediamenti.",al={"perché volare","posso camminare fino a forgiardente","perché il grifone"}},{q="Cos'è un Honorary Pick?",a="Un Honorary Pick è uno strumento cerimoniale che la Deep Mountain Mining Guild dona agli studenti di estrazione mineraria più meritevoli. Gli istruttori regionali insegnano loro le basi degli scavi e della geologia.",al={"honorary picks","ricompensa del piccone","cerimonia del piccone da minatore"}}},fx={d8819fd3={q="Perché Thorgrum Borrelson vuole che tu voli a Forgiardente?",a="Thorgrum Borrelson è il maestro dei grifoni di Thelsamar, a Loch Modan, e il suo mestiere dipende dai viaggiatori che prendono il volo dal suo posatoio. Organizzando il tuo volo verso Forgiardente per consegnare a Golnir Granditone la lista degli aspiranti minatori di Brock, ti fa conoscere la rapidità e la comodità dei viaggi in grifone e assicura che un'importante comunicazione della gilda raggiunga la capitale senza ritardi.",al={"motivo di thorgrum borrelson","perché mandare a forgiardente","perché consegnare la lista di brock"}}},fp="17,161,19.186.0,33.171.0,37.107.0,21.124.0,25.179.0,40.143.0,37.143.0,25.179.0"}
P.entries["quest:6392"] = {n="Return to Brock",s="Porti la missiva di Brock Scrutarocce a Forgiardente e ricevi degli Honorary Picks per i suoi apprendisti. Gryth Thurden può riportarti in volo a Thelsamar.",h="Porti la missiva di Brock Scrutarocce a Forgiardente e ricevi degli Honorary Picks per i suoi apprendisti.",kw={"brock scrutarocce","maestro di volo","grifone","gryth thurden","honorary picks","forgiardente","return to brock","thelsamar"},ang={["profession:Mining"]="Consegnare gli Honorary Picks fornisce ai nuovi minatori del Loch Modan gli attrezzi per il loro lavoro e porta avanti la tradizione nanica di scavo e prospezione.",["race:Dwarf"]="Da nano, sai che i grifoni dei Wildhammer e i gestori di Forgiardente collegano per via aerea le roccaforti naniche."},sec={{t="Prendere il volo",b="Gryth Thurden supervisiona i voli dei grifoni di Forgiardente dalla piattaforma centrale della città. Per volare a Thelsamar, devi prima aver incontrato il suo gestore, Thorgrum Borrelson. Poi Gryth può portare te e i picconi oltre le montagne, riportando la missiva e gli attrezzi di Brock al Loch."},{t="Picconi per gli apprendisti",b="Brock Scrutarocce insegna estrazione mineraria a Thelsamar e ha bisogno di attrezzi per i suoi apprendisti. Gli Honorary Picks permetteranno ai giovani minatori di lavorare i ricchi filoni di rame e stagno sulle colline intorno al Loch."}},faq={{q="Chi è Brock Scrutarocce?",a="Brock Scrutarocce è un istruttore nano di estrazione mineraria a Thelsamar, nel Loch Modan. Insegna ai nuovi minatori a raccogliere minerali e pietre dalle colline circostanti.",al={"brock scrutarocce","chi è brock","brock a thelsamar"}},{q="Perché devo volare su un grifone per completare questa missione?",a="Gryth Thurden può portarti in volo a Thelsamar perché hai già visitato il suo nido e parlato con Thorgrum Borrelson. I grifoni portano i viaggiatori solo ai nidi che hanno già visitato.",al={"perché volare","missione rotta di volo","viaggio in grifone"}},{q="A cosa servono gli Honorary Picks?",a="Gli Honorary Picks sono attrezzi da minatore di cui Brock Scrutarocce ha bisogno per i suoi nuovi allievi nel Loch Modan.",al={"honorary picks","cosa sono i picconi"}},{q="Chi è Gryth Thurden?",a="Gryth Thurden è il maestro dei grifoni di Forgiardente e si trova presso la Grande Forgia. Gestisce i voli da e verso la capitale, attraverso Khaz Modan e oltre.",al={"gryth thurden","maestro di volo forgardente"}},{q="Posso semplicemente tornare a piedi a Thelsamar invece di volare?",a="Puoi tornare a piedi a Thelsamar e consegnare gli Honorary Picks a Brock Scrutarocce. Il viaggio ti fa conoscere le rotte dei grifoni, e Brock ha bisogno che gli attrezzi arrivino sani e salvi nelle sue mani.",al={"posso tornare a piedi","devo prendere il grifone"}},{q="Dove si trova Brock a Thelsamar?",a="Brock Scrutarocce si trova all'aperto, vicino alla forgia e all'incudine di Thelsamar, dove aiuta i minatori del Loch Modan.",al={"dove si trova brock","posizione brock scrutarocce","trovare brock"}}},fx={c8277dbd={q="Perché Gryth Thurden vuole che consegni i picconi?",a="Gryth Thurden gestisce i posatoi dei grifoni di Forgiardente e mantiene collegati gli itinerari di volo del regno. Brock Scrutarocce, a Thelsamar, attende con urgenza una fornitura di picconi onorari per i suoi studenti di miniera. Poiché hai già percorso la via tra Forgiardente e il posatoio di Thorgrum Borrelson, Gryth si serve di questa consegna per soddisfare le necessità di Brock e assicurarsi che tu impari a viaggiare in grifone attraverso Khaz Modan.",al={"perché gryth vuole questo","motivo di gryth thurden","perché mandare i picconi a brock"}},be2b1abc={q="Perché Gryth Thurden manda un avventuriero invece di occuparsene lui stesso?",a="Gryth Thurden non può abbandonare il suo posto presso la Grande Forgia, dove supervisiona il continuo via vai dei cavalieri e si prende cura dei preziosi grifoni di Forgiardente. Hai portato personalmente in città il messaggio di Brock e hai sbloccato la rotta di volo per Thelsamar, quindi sei il corriere ideale per mettere alla prova il collegamento appena istituito e riportare le provviste direttamente al minatore.",al={"perché gryth ha bisogno di me","perché mandare un avventuriero a thelsamar","perché non mandare un corriere"}}},fp="15,145,19.279.0,20.188.0,25.143.0,55.176.0,32.95.0,21.149.0,52.176.0,36.102.0"}
P.entries["quest:6393"] = {n="Elemental War",s="Nelle Vette di Petrartiglio, Tsunaman ti manda a combattere gli elementali del fuoco in nome di Neptulon il Cacciatore di Maree. L’emissario dell’acqua al Rifugio Roccia del Sole ti chiede di entrare nella Valle Bruciata e raccogliere nuclei di Incendrite dagli elementali in fiamme che sconfiggi. La loro lotta supera i confini mortali ed è legata all’antica rivalità tra le forze elementali.",h="Nelle Vette di Petrartiglio, Tsunaman ti manda a combattere gli elementali del fuoco in nome di Neptulon il...",kw={"valle bruciata","elemental war","elementali del fuoco","incendrite","neptulon","vette di petrartiglio","rifugio roccia del sole","tribunale delle maree","tsunaman"},ang={["class:Shaman"]="Come sciamano, assisti allo scontro tra le forze primordiali mentre i servitori di Neptulon combattono gli elementali del fuoco.",["faction:Horde"]="Come membro dell’Orda, puoi aiutare nella lotta elementale mentre attraversi le Vette di Petrartiglio. Tsunaman è di stanza al Rifugio Roccia del Sole."},sec={{t="Rivalità Primordiale nelle Montagne",b="Al Rifugio Roccia del Sole, nelle Vette di Petrartiglio, Tsunaman parla per il Tribunale delle Maree. Tu esegui la volontà di Neptulon il Cacciatore di Maree contro i parenti infuocati dei suoi Water Elementals. La loro ostilità va ben oltre i confini mortali. È un’antica lotta tra le forze primordiali di Azeroth."},{t="La Cenere e la Fiamma",b="Nelle Vette di Petrartiglio meridionali si trova la Valle Bruciata, dove cenere e fumo segnano la terra. Gli elementali del fuoco si radunano lì e minacciano le regioni circostanti. Tsunaman ti manda a distruggerli e a raccogliere le Incendrite che lasciano dietro di sé. Questi nuclei ardenti dimostrano al Tribunale che gli elementali sono stati eliminati."}},faq={{q="Chi è Tsunaman?",a="Tsunaman è un emissario del Tribunale delle Maree al Rifugio Roccia del Sole, nelle Vette di Petrartiglio. Sotto l’autorità di Neptulon il Cacciatore di Maree, combatte gli elementali del fuoco e ti manda a distruggerli.",al={"chi è tsunaman","tsunaman datore di missioni","rifugio roccia del sole elementale"}},{q="Perché Neptulon vuole che gli elementali del fuoco vengano distrutti?",a="Neptulon il Cacciatore di Maree nutre un’antica ostilità verso gli elementali del fuoco e ne vuole la distruzione. Il Tribunale delle Maree ha inviato Tsunaman nelle Vette di Petrartiglio per condurre questa campagna.",al={"perché combattere gli elementali del fuoco","motivo elemental war","neptulon elementali del fuoco"}},{q="Dove si trova la Valle Bruciata?",a="La Valle Bruciata si trova nelle Vette di Petrartiglio meridionali. Elementali infuocati e altre bestie pericolose, nate dalle fiamme e dalla rovina, infestano il suo bacino coperto di cenere.",al={"dove si trova valle bruciata","posizione elementali del fuoco petrartiglio","dove trovare incendrite"}},{q="Cosa sono le Incendrite?",a="Le Incendrite sono resti ardenti lasciati dalla distruzione degli elementali del fuoco della Valle Bruciata. Tsunaman raccoglie questi nuclei come prova della loro distruzione e per guadagnarsi il favore del Tribunale delle Maree.",al={"cosa sono le incendrite","bottino elementale del fuoco","lore incendrite"}},{q="Cos'è il Tribunale delle Maree?",a="Il Tribunale delle Maree è un’autorità tra gli elementali dell’acqua che serve Neptulon il Cacciatore di Maree. Dirige le forze elementali e gli emissari come Tsunaman affinché attuino la volontà del Cacciatore di Maree contro i domini elementali rivali.",al={"lore tribunale delle maree","chi sono il tribunale delle maree","fazione water elementals"}},{q="Chi è Neptulon il Cacciatore di Maree?",a="Neptulon il Cacciatore di Maree è il Signore Elementale dell’acqua e governa gli oceani, i mari e tutti gli elementali dell’acqua. Come gli altri signori elementali, combatte un’antica guerra senza fine contro gli elementi rivali, soprattutto il fuoco.",al={"chi è neptulon","signore elementale dell'acqua","neptulon cacciatore di maree"}}},fp="13,330,31.297.0,21.307.0,16.202.0,53.191.0,34.153.0,21.205.0,34.227.0,31.223.0"}
P.entries["quest:6394"] = {n="Piccone di Thazz'ril",s="Il Caposquadra Thazz'ril ha bisogno che tu recuperi il suo piccone incantato dalla caverna settentrionale. Bestie feroci si aggirano nel Covo delle Lame Ardenti, dove si trova l'attrezzo luminoso.",h="Il Caposquadra Thazz'ril ha bisogno che tu recuperi il suo piccone incantato dalla caverna settentrionale.",kw={"covo delle lame ardenti","durotar","caposquadra thazz'ril","miniera","piccone","thazz'ril","valle delle sfide","cascata"},ang={["faction:Horde"]="In quanto membro dell'Orda, aiuti a mettere al sicuro gli attrezzi di base e a scacciare minacce come il Covo delle Lame Ardenti. Così rafforzi la presenza dell'Orda nella Valle delle Sfide.",["profession:Mining"]="In quanto minatore, sai perché il Caposquadra Thazz'ril si affida al suo piccone incantato per cercare minerali nel Durotar. Spera di aprire nuovi siti minerari dopo che sarà stato sgomberato il legname locale."},sec={{t="Un attrezzo perduto",b="Il Caposquadra Thazz'ril dirige i lavori nella Valle delle Sfide. Entrò nella caverna settentrionale per cercare filoni minerari, ma vi lasciò il suo piccone preferito. Al suo ritorno, bestie feroci e abitanti ostili avevano preso il controllo. Ora cerca mani esperte che gli riportino l'attrezzo."},{t="Luce nell'oscurità",b="Thazz'ril ha incantato il suo piccone preferito perché brillasse al buio e fosse più facile da usare nelle caverne poco illuminate. La sua luce segnala l'attrezzo in una camera con cascate all'interno del Covo delle Lame Ardenti. Creature pericolose si aggirano nell'ombra. Thazz'ril spera di rimettere al lavoro il piccone e di trovare nuovi filoni da estrarre nella valle."}},faq={{q="Chi è il Caposquadra Thazz'ril?",a="Il Caposquadra Thazz'ril supervisiona il lavoro e la raccolta di risorse nella Valle delle Sfide. Dirige i peoni mentre abbattono gli alberi e preparano il terreno per le attività minerarie.",al={"chi è thazzril","ruolo di thazzril","caposquadra thazz'ril"}},{q="Perché il piccone di Thazz'ril brilla?",a="Thazz'ril ha incantato il suo piccone preferito perché brillasse al buio e fosse più facile da individuare nelle caverne più buie.",al={"perché il piccone è speciale","piccone luminoso","piccone incantato"}},{q="Dov'è il Covo delle Lame Ardenti?",a="Il Covo delle Lame Ardenti è una rete di caverne oscure a nord del campo di taglialegna dei peoni nella Valle delle Sfide.",al={"dov'è il covo delle lame ardenti","posizione del covo","caverna del piccone"}},{q="Come ha fatto Thazz'ril a perdere il suo piccone?",a="Thazz'ril lasciò il suo piccone preferito nella caverna settentrionale mentre cercava minerali. Al suo ritorno, bestie feroci e cultisti oscuri avevano infestato la caverna.",al={"come ha perso il piccone thazzril","perché lasciare il piccone","piccone dimenticato"}},{q="Dove all'interno della caverna è stato lasciato il piccone?",a="Thazz'ril lasciò il piccone nel profondo della caverna, in una camera sotterranea con cascate, dove stava esaminando le pareti rocciose.",al={"dove dentro la caverna","stanza del piccone","camera con cascata"}},{q="Cosa intende fare Thazz'ril dopo aver riavuto il suo piccone?",a="Thazz'ril ha intenzione di trovare una caverna adatta all'estrazione mineraria dopo che i suoi peoni avranno finito di abbattere gli alberi circostanti nella Valle delle Sfide.",al={"progetti futuri di thazzril","cosa minerà thazzril"}}},fp="16,144,11.273.0,16.311.0,25.151.0,31.106.0,33.101.0,32.163.0,40.128.0,59.133.0"}
P.entries["quest:6395"] = {n="Marla's Last Wish",s="Ad Albamorta, Marla's Last Wish riunisce un marito e una moglie nella morte. La Novizia Elreth ti chiede di trovare Samuel Fipps, ancora asservito al Flagello, perché possa essere sepolto accanto a Marla. I Reietti onorano i legami della vita e si distinguono dal Flagello.",h="Ad Albamorta, Marla's Last Wish riunisce un marito e una moglie nella morte.",kw={"albamorta","tomba","marla fipps","marla's last wish","novizia elreth","resti","samuel fipps","flagello"},ang={["class:Priest"]="In quanto sacerdote Reietta, la Novizia Elreth insiste sui riti funebri appropriati, richiamando il tuo dovere spirituale di fronte alla mortalità, al dolore e alla profanazione dei defunti di Lordaeron.",["race:Undead"]="Come Reietto appena risorto, esaudire il desiderio di Marla può legarti alla tua vita umana precedente. Dimostra che compassione e onore sono sopravvissuti alla caduta di Lordaeron."},sec={{t="Una tragica riunione",b="Prima della Terza Guerra, Marla e Samuel Fipps erano marito e moglie a Lordaeron. La guerra devastò la loro casa e, quando la piaga si diffuse nelle loro terre, Samuel soccombette. Risorse come schiavo senza volontà del Flagello. Marla sfuggì alla non-morte, ma Samuel la uccise in preda alla frenesia. Lei non gli portava rancore. La Novizia Elreth ricorda l'ultimo desiderio di Marla: riposare accanto a Samuel nel cimitero di Albamorta."},{t="Rispetto per i morti",b="La Novizia Elreth ti manda a nord-est di Albamorta, dove Samuel Fipps vaga ancora tra i resti di un accampamento. Porre fine al suo tormento elimina un servitore del Flagello dalla valle. Poi i suoi resti possono essere riportati al luogo di riposo di Marla. Elreth crede che onorare i defunti e i loro ultimi desideri distingua i Reietti appena liberati dal Flagello."}},faq={{q="Chi era Marla Fipps?",a="Marla Fipps viveva a Lordaeron e sopravvisse alla piaga, ma Samuel la uccise dopo essere diventato uno schiavo senza volontà del Flagello. Desiderava riposare accanto a lui.",al={"lore marla fipps","chi è marla","background di marla"}},{q="Chi è Samuel Fipps?",a="Samuel Fipps era il marito di Marla prima della piaga. Cadde sotto il controllo del Flagello e perse la ragione, poi uccise Marla. Finché gli avventurieri Reietti non pongono fine al suo tormento, vaga per un accampamento in rovina a nord-est di Albamorta.",al={"lore samuel fipps","chi è samuel fipps","dove si trova samuel fipps"}},{q="Perché alla Novizia Elreth importa che vengano sepolti insieme?",a="La Novizia Elreth era amica di Marla quando era in vita. Elreth crede che onorare i defunti e trattarne i resti con dignità dimostri che i Reietti hanno conservato la loro umanità e moralità, a differenza del Flagello senza volontà.",al={"perché aiutare marla","motivazioni della novizia elreth","perché seppellire samuel"}},{q="Marla è risorta come Reietta?",a="No. La Novizia Elreth dice che Marla fu risparmiata dalla non-morte. Samuel la uccise quando era ancora mortale, e fu sepolta nel cimitero di Albamorta.",al={"marla è non-morta","marla è diventata reietta","marla fipps non-morta"}},{q="Dove si trova la tomba di Marla?",a="La tomba di Marla si trova nella prima fila del cimitero, appena fuori dalla cappella principale di Albamorta.",al={"posizione tomba di marla","dove è sepolta marla","dove seppellisco samuel"}},{q="Dove si può trovare Samuel Fipps?",a="Samuel Fipps vaga per un accampamento in rovina lungo la strada a nord-est di Albamorta.",al={"posizione di samuel fipps","trovare samuel fipps","dove si trova samuel"}}},fx={e919b4a2={q="A cosa servono i Resti di Samuel?",a="Raccogli i resti terreni di Samuel perché possano finalmente essere sepolti accanto a sua moglie, Marla. Anche se Samuel fu trasformato in un flagello privo di senno e le tolse la vita, l'ultimo desiderio di Marla era che riposassero insieme per l'eternità nel cimitero di Albamorta.",al={"resti di samuel","perché raccogliere i resti di samuel","scopo dei resti di samuel"}},["74d32be4"]={q="Chi è Samuel Fipps e perché devi sconfiggerlo?",a="Samuel Fipps era un abitante vivente delle Radure di Tirisfal, ma soccombette alla peste della non morte e divenne un servitore senza senno del Flagello. Dopo aver ucciso sua moglie nel suo stato privo di coscienza, ora vaga come ghoul nell'accampamento in rovina a nord-est di Albamorta, incapace di trovare pace finché non sarà distrutto.",al={"perché uccidere samuel fipps","chi devo affrontare nell'ultimo desiderio di marla","storia di samuel fipps"}}},fp="17,263,16.400.0,19.346.0,20.151.0,20.210.0,56.207.0,27.142.0,31.90.0,32.78.0"}
P.entries["quest:64"] = {n="The Forgotten Heirloom",s="Nelle Marche Occidentali, The Forgotten Heirloom è un orologio da taschino lasciato indietro quando i Ciglioarcuato fuggirono dalla loro fattoria. Recuperarlo offre loro la possibilità di riavere qualcosa di personale nel caos.",h="Nelle Marche Occidentali, The Forgotten Heirloom è un orologio da taschino lasciato indietro quando i...",kw={"benny blaanco","defias","ciglioarcuato","orologio da taschino","campo di zucche","verna ciglioarcuato","armadio","marche occidentali"},ang={["faction:Alliance"]="La difficile situazione dei Ciglioarcuato mostra quanto sia crollato l'ordine nel granaio del regno. Come viaggiatore dell'Alleanza, ti ritrovi a gestire ciò che la corona ha trascurato.",["race:Human"]="Da umano di Roccavento, vedi onesti contadini cacciati dalle loro terre da fuorilegge a meno di un giorno di marcia dalla capitale. La loro difficile situazione rivela i problemi interni del regno."},sec={{t="Uno sfratto a mezzanotte",b="Il Contadino Ciglioarcuato e Verna furono cacciati dalla loro fattoria nelle Marche Occidentali dalla violenza. Le grida provenienti dai campi di zucche li svegliarono nella notte, lasciando loro poco tempo per raccogliere ciò che potevano trasportare. Nella fuga, Ciglioarcuato lasciò indietro l'orologio da taschino che il padre di Verna gli aveva regalato il giorno del loro matrimonio. È ancora nell'armadio della loro fattoria occupata."},{t="Teppisti nei campi",b="I teppisti e i ladri Defias, tra cui Benny Blaanco, ora rovistano nella fattoria abbandonata dei Ciglioarcuato. Tornare a recuperare un ricordo potrebbe significare la morte per la gente comune. Puoi prendere l'orologio da taschino dall'armadio e restituire un po' di dignità a una famiglia che ha perso quasi tutto a causa dell'illegalità che regna nelle Marche Occidentali."}},faq={{q="Perché l'orologio da taschino è così importante per il Contadino Ciglioarcuato?",a="Il padre di Verna regalò l'orologio da taschino al Contadino Ciglioarcuato il giorno del loro matrimonio. Ora rifugiati che hanno perso i mezzi di sostentamento, i Ciglioarcuato custodiscono in quell'orologio un legame affettuoso con la loro vita passata e le tradizioni di famiglia.",al={"perché l'orologio è importante","significato dell'orologio dei ciglioarcuato","chi ha dato l'orologio a ciglioarcuato"}},{q="Chi ha scacciato i Ciglioarcuato dalla loro fattoria?",a="Briganti e saccheggiatori Defias cacciarono i Ciglioarcuato dalla loro fattoria durante la notte. Il loro attacco riflette l'illegalità che costringe molte famiglie di contadini ad abbandonare case e campi sotto la minaccia della violenza.",al={"chi ha attaccato la fattoria","chi ha preso la fattoria dei ciglioarcuato","cosa è successo ai ciglioarcuato"}},{q="Dov'è nascosto l'orologio?",a="L'orologio da taschino si trova in un armadio della camera da letto della fattoria dei Ciglioarcuato, nei campi di zucche a ovest dell'accampamento lungo la strada dei Ciglioarcuato, nel nord delle Marche Occidentali. La fattoria è occupata da abusivi e fuorilegge Defias.",al={"dov'è l'orologio da taschino","trova orologio","posizione armadio"}},{q="Chi è Benny Blaanco?",a="Benny Blaanco è un fuorilegge nella fattoria dei Ciglioarcuato, insieme ai suoi compagni Defias. Saccheggiano la casa abbandonata e la sorvegliano contro chiunque voglia riprendersela.",al={"storia di benny blaanco","chi è il tizio in casa"}},{q="Dove alloggiano ora i Ciglioarcuato?",a="Il Contadino Ciglioarcuato e Verna sono bloccati sul ciglio della strada nelle Marche Occidentali. Si riparano vicino al loro carro e cercano di sopravvivere al collasso della regione.",al={"dove sono i ciglioarcuato","dov'è il contadino ciglioarcuato"}},{q="Roccavento invia guardie per aiutare a recuperare fattorie come questa?",a="La presenza militare ufficiale di Roccavento nelle Marche Occidentali è quasi inesistente, tra l'indifferenza politica e la mancanza di una guida nella capitale. La People's Militia a Guardiacolle non ha la forza di riprendersi le singole fattorie, lasciando i coloni indifesi.",al={"roccavento aiuta marche occidentali","perché non ci sono guardie alla fattoria"}}},fx={["028db52d"]={q="Cos'è l'Orologio da Tasca dei Ciglioarcuato?",a="È un normale orologio, ma un cimelio di famiglia di inestimabile valore. Il padre di Verna lo regalò al Contadino Ciglioarcuato il giorno delle loro nozze. Dopo aver perso in una sola notte la terra, il raccolto e la casa a causa dei briganti, recuperare questo unico ricordo è tutto ciò che alla coppia anziana resta da salvare dalle rovine della vita che conduceva un tempo.",al={"orologio dei ciglioarcuato","orologio da tasca cimelio","cos'è l'orologio dei ciglioarcuato"}}},fp="22,179,19.341.0,23.309.0,56.205.0,45.209.0,26.205.0,21.162.0,36.139.0,59.247.0"}
P.entries["quest:640"] = {n="The Broken Sigil",s="Zengu ti manda a recuperare i sigilli dalla milizia di Stromgarde. Galen, figlio di Thoras Trollbane, ha spezzato il Sigil of Thoradin in undici pezzi, che porterai a Tor'gan a Requie del Martello.",h="Zengu ti manda a recuperare i sigilli dalla milizia di Stromgarde.",kw={"altopiani d'arathi","sigillo infranto","galen trollbane","requie del martello","sigil of thoradin","stromgarde","thoras trollbane","tor'gan","zengu"},sec={{t="Un sigillo in pezzi",b="Tre sigilli proteggono la tomba di Thoras Trollbane. Hai sottratto il primo alla Lega dei Tagliagole. La milizia di Stromgarde, saldamente trincerata, custodisce gli altri due. Galen, figlio di Thoras, ha spezzato il Sigil of Thoradin in undici pezzi e li ha sparsi tra i difensori."},{t="Da Tor'gan",b="Zengu ti chiede di raccogliere i pezzi dai difensori di Stromgarde. Poi portali a Tor'gan, lo sciamano troll di Requie del Martello. Può riunirli in un sigillo intero."},{t="A Requie del Martello",b="Tor'gan dice che Zengu gli ha riferito che avevi bisogno d'aiuto. Esamina i pezzi e giudica il lavoro fattibile. Ci sono tutti e undici, e la struttura magica del sigillo è facile da ripristinare. Tor'gan ti dice di chiudere gli occhi. Poco dopo, dichiara che il Sigil of Thoradin è di nuovo intero."}},faq={{q="Che cos'è il Sigil of Thoradin?",a="Il Sigil of Thoradin è uno dei tre sigilli che proteggono la tomba di Thoras Trollbane. Galen l'ha spezzato in undici pezzi e li ha sparsi tra i difensori di Stromgarde.",al={"storia del sigil of thoradin","significato sigillo infranto","cos'è il sigillo infranto"}},{q="Chi ha diviso il sigillo?",a="Galen, figlio di Thoras Trollbane, ha spezzato il Sigil of Thoradin in undici pezzi e li ha sparsi tra i difensori di Stromgarde.",al={"chi ha rotto il sigillo","perché il sigillo è rotto","galen trollbane sigillo"}},{q="Dove sono conservati i frammenti del sigillo?",a="I difensori di Stromgarde custodiscono i pezzi tra le fila della milizia saldamente trincerata che protegge i sigilli rimanenti.",al={"dove trovare i frammenti","chi ha i frammenti","sigillo difensori stromgarde"}},{q="Chi può riassemblare il sigillo infranto?",a="Tor'gan, lo sciamano troll di Requie del Martello, può riunire i pezzi in un sigillo intero.",al={"chi ripara il sigillo","torgan sigillo","chi unisce i frammenti"}},{q="Cosa precede questa missione?",a="Segue Sigil of Strom, dove hai recuperato il primo sigillo dalla Lega dei Tagliagole.",al={"missione precedente","quale missione precede il sigillo infranto","inizio catena sigillo"}}},fp="16,187,17.257.0,10.161.0,13.268.1,30.161.0,22.127.0,35.105.0,30.80.0,22.82.0"}
P.entries["quest:6401"] = {n="Kaya's Alive",s="Makaba Zoccolo Piatto ha saputo che Kaya Zoccolo Piatto è sopravvissuta all'attacco dei Totem Truce nelle Vette di Petrartiglio. Ti manda al Rifugio Roccia del Sole, dove sua zia Tammra Vento Piatto attende con ansia.",h="Makaba Zoccolo Piatto ha saputo che Kaya Zoccolo Piatto è sopravvissuta all'attacco dei Totem Truce nelle...",kw={"zoccolo piatto","totem truce","kaya","makaba","protect kaya","vette di petrartiglio","rifugio roccia del sole","tammra","tauren","vento piatto"},ang={["faction:Horde"]="Nelle terre selvagge contese delle Vette di Petrartiglio, le forze dell'Orda sono disperse e sotto pressione. Sapere che i sopravvissuti sono al sicuro aiuta gli accampamenti isolati a restare uniti.",["race:Tauren"]="Da tauren, sai che la minaccia dei Totem Truce alimenta una dolorosa frattura tra gli Shu'halo. Proteggere familiari innocenti come Kaya è molto importante."},sec={{t="Un sospiro di sollievo",b="I Totem Truce colpiscono lungo i sentieri contesi delle Vette di Petrartiglio. Quando il loro villaggio fu attaccato, si temeva che la giovane Kaya Zoccolo Piatto fosse morta o fosse stata presa dai rinnegati. Il suo salvataggio porta sollievo, mentre le tribù continuano a combattersi tra le rupi."},{t="Raggiungere il Rifugio Roccia del Sole",b="Makaba Zoccolo Piatto ti manda da Kaya al Rifugio Roccia del Sole per portare la notizia che è salva. Sua zia, Tammra Vento Piatto, attende lì con ansia notizie dai sentieri. Il tuo messaggio conforta la famiglia e mantiene in contatto il remoto avamposto dell'Orda."}},faq={{q="Chi è Kaya Zoccolo Piatto?",a="Kaya Zoccolo Piatto è una giovane tauren separata dalla sua gente quando le forze rinnegate dei Totem Truce attaccarono il suo insediamento nelle Vette di Petrartiglio.",al={"chi è kaya","kaya zoccolo piatto","kaya"}},{q="Chi è Tammra Vento Piatto?",a="Tammra Vento Piatto è la zia di Kaya e vive al Rifugio Roccia del Sole, nelle Vette di Petrartiglio. Temeva che sua nipote fosse morta nell'attacco dei Totem Truce.",al={"tammra vento piatto","chi è tammra","zia di kaya"}},{q="Chi ha attaccato il villaggio di Kaya?",a="Le forze dei Totem Truce hanno attaccato il villaggio di Kaya. Questa fazione tauren isolazionista dà la caccia alle tribù rivali e ai viaggiatori tra le montagne.",al={"chi ha attaccato kaya","attacco al villaggio","attacco dei totem truce"}},{q="Cosa viene prima di questa missione?",a="Hai appena aiutato Kaya Zoccolo Piatto a fuggire dai suoi rapitori e a tornare al sicuro nella missione «Protect Kaya».",al={"prerequisito","protect kaya","missione di scorta"}},{q="Dove si trova il Rifugio Roccia del Sole?",a="Il Rifugio Roccia del Sole sorge in alto, nella parte centrale delle Vette di Petrartiglio. Segui la strada principale verso ovest, attraverso una stretta gola montana, fino a un bacino riparato.",al={"posizione rifugio roccia del sole","dov'è rifugio roccia del sole","trovare rifugio roccia del sole"}},{q="Perché Makaba Zoccolo Piatto manda te invece di andare di persona?",a="Makaba è ancora al suo accampamento, vicino al margine sud-orientale delle Vette di Petrartiglio. Ti manda a portare in fretta la notizia alla sua famiglia, al Rifugio Roccia del Sole.",al={"perché makaba resta","perché manda me"}}},fx={["10e83b92"]={q="Perché Makaba Zoccolo Piatto vuole che questa notizia venga consegnata?",a="Il loro villaggio ha subito un attacco brutale e i sopravvissuti credevano che la giovane Kaya Zoccolo Piatto fosse morta nel massacro. Ora che è al sicuro, Makaba vuole inviare subito la notizia per alleviare il dolore della zia di Kaya, Tammra Vento Piatto, che attende con ansia al Rifugio Roccia del Sole senza sapere che sua nipote è sopravvissuta.",al={"perché mandare notizie a tammra","motivo di makaba zoccolo piatto","perché consegnare la notizia"}}},fp="12,171,18.225.0,25.235.0,21.134.0,24.141.0,28.132.0,29.91.0,34.146.0,59.133.0"}
P.entries["quest:641"] = {n="Sigillo di Thoradin",s="Tor'gan ha restaurato il Sigil of Thoradin e Zengu ne attende il ritorno a Requie del Martello. Il sigillo può aprire la tomba di Trollbane.",h="Tor'gan ha restaurato il Sigil of Thoradin e Zengu ne attende il ritorno a Requie del Martello.",kw={"altopiani d'arathi","requie del martello","sigil of thoradin","tor'gan","trol'kalar","tomba di trollbane","zengu"},sec={{t="Il Sigillo Restaurato",b="La ricostruzione di Tor'gan ha funzionato. Il Sigil of Thoradin può aprire il sigillo sulla tomba di Trollbane, così Tor'gan ti rimanda da Zengu a Requie del Martello. Zengu ha altro da farti fare."},{t="A metà strada",b="Zengu ti chiede se hai il secondo sigillo. Con quello, dice, sei a metà strada dal prendere la Trol'kalar dalla tomba di Trollbane. Il terzo sigillo è ancora difficile da trovare, perché i suoi custodi si spostano per le Arathi. Zengu ha fiducia che riuscirai a trovarlo."}},faq={{q="A cosa serve il Sigil of Thoradin?",a="Il sigillo restaurato può aprire il sigillo sulla tomba di Trollbane.",al={"a cosa serve il sigil of thoradin","cosa fa il sigil of thoradin","perché ci serve il sigillo"}},{q="A chi porti il Sigil of Thoradin?",a="Porta il sigillo restaurato a Zengu a Requie del Martello. Tor'gan ti rimanda da lui.",al={"dove porto il sigillo","a chi consegnare il sigil of thoradin","consegnare il sigil of thoradin"}},{q="Dove si colloca questo passaggio nella ricerca della Trol'kalar?",a="Questo passaggio segue Broken Sigil, quando Tor'gan ha ricostruito il sigillo con i pezzi che gli hai portato.",al={"progresso della serie del sigillo","a che punto è questa missione","quale missione precede questa"}}},fp="17,138,18.172.0,13.230.1,39.57.0,42.79.0,54.105.0"}
P.entries["quest:642"] = {n="The Princess Trapped",s="Negli Altopiani d'Arathi, un frammento iridescente porta la supplica di Myzrael dalle profondità sotterranee. Si dice una principessa della terra, imprigionata dai giganti, e chiede ai viaggiatori di rafforzare un gruppo di cristalli nella Gola dei Baffosecco.",h="Negli Altopiani d'Arathi, un frammento iridescente porta la supplica di Myzrael dalle profondità sotterranee.",kw={"altopiani d'arathi","gola dei baffosecco","coboldi baffosecco","principessa della terra","frammenti iridescenti","particelle di myzrael","myzrael","the princess trapped"},ang={["class:Mage"]="Da mago, potresti trovare curiosi i frammenti risonanti e le particelle di energia della terra, un modo per comunicare e incanalare potere a grandi distanze.",["class:Shaman"]="Da sciamano, comunichi con gli spiriti elementali e potresti riconoscere la pretesa di Myzrael di essere una principessa della terra. La sua prigionia sotterranea richiede un attento esame degli elementi.",["profession:Mining"]="Da minatore, potresti incontrare i coboldi Baffosecco vicino alla gola e nelle vene sotterranee di Arathi. Potresti anche trovare i frammenti di cristallo incantati legati alla principessa."},sec={{t="Una Voce dalla Pietra",b="Strani frammenti sono sparsi per gli Altopiani d'Arathi e vibrano di un potere lontano. Nei loro pressi, la voce di Myzrael emerge dalle profondità sotterranee. Si dice una principessa della terra, precipitata e incatenata sottoterra da antichi giganti. Tagliata fuori dalle terre in superficie, usa i cristalli per far giungere la sua supplica a chiunque sia disposto ad ascoltare."},{t="Il Collegamento dei Baffosecco",b="Myzrael ti indirizza a est, verso la Gola dei Baffosecco, dove ti chiede di rafforzare il contatto con lei. I coboldi Baffosecco infestano la gola, e lei li definisce alleati dei giganti che la tengono prigioniera. Portano con sé Particelle di Myzrael e sorvegliano un gruppo di frammenti iridescenti. Prendi le particelle dai coboldi e usane l'energia sulla formazione. Così rafforzerai il gruppo di cristalli e approfondirai la comunicazione con la principessa intrappolata."}},faq={{q="Chi è Myzrael?",a="Myzrael è la voce che parla attraverso il cristallo. Si dice una principessa della terra, imprigionata nelle profondità sotterranee degli Altopiani d'Arathi, e invoca l'aiuto dei viaggiatori di passaggio per raggiungere la superficie.",al={"chi è la principessa intrappolata","chi parla attraverso il cristallo","chi è myzrael"}},{q="Chi ha imprigionato Myzrael sotto gli altipiani?",a="Myzrael dice che i giganti l'hanno imprigionata sotto Arathi. L'hanno incatenata nelle profondità sotterranee, così si affida ai frammenti sparsi per la regione per parlare con chi si trova in superficie.",al={"chi ha imprigionato myzrael","chi ha intrappolato la principessa","perché myzrael è nel sottosuolo"}},{q="Cosa sono le Particelle di Myzrael?",a="Le Particelle di Myzrael sono frammenti cristallini o elementali trasportati dai coboldi Baffosecco. Myzrael dice che racchiudono abbastanza potere latente della terra da attivare i gruppi di frammenti e rafforzare il suo legame con la superficie.",al={"perché i coboldi hanno le particelle","particelle gola dei baffosecco","cosa sono le particelle di myzrael"}},{q="Come sono collegati i coboldi Baffosecco ai carcerieri di Myzrael?",a="Myzrael dice che i coboldi Baffosecco della Gola dei Baffosecco sono alleati dei giganti che l'hanno imprigionata. Sorvegliano un gruppo di frammenti di cristallo nella gola, tra la principessa e la superficie.",al={"perché i coboldi sono coinvolti","coboldi baffosecco giganti","coboldi che lavorano con i giganti"}},{q="Come riesce Myzrael a parlare dal sottosuolo?",a="Myzrael fa viaggiare la sua voce attraverso frammenti di cristallo iridescenti che affiorano dal suolo degli Altopiani d'Arathi. I frammenti trasportano la sua voce attraverso le profondità fino a chi si trova in superficie.",al={"come parla myzrael","frammenti iridescenti arathi","cosa sono i frammenti di cristallo"}},{q="Dove si trova la Gola dei Baffosecco?",a="La Gola dei Baffosecco è una gola impervia nella parte orientale degli Altopiani d'Arathi. Vi abitano i coboldi Baffosecco, che circondano il gruppo di frammenti iridescenti che Myzrael ti chiede di potenziare con le particelle raccolte.",al={"dove si trova la gola dei baffosecco","dove porto le particelle","posizione frammenti baffosecco"}}},fp="20,233,22.343.0,25.439.0,15.201.0,42.162.0,30.206.0,62.187.0,46.182.0,34.188.0"}
P.entries["quest:6421"] = {n="Gola dei Franamassi",s="Mor'rogal teme il tumulto della terra dal Rifugio Roccia del Sole, mentre i coboldi scavano Resonite nelle Vette di Petrartiglio.",h="Mor'rogal teme il tumulto della terra dal Rifugio Roccia del Sole, mentre i coboldi scavano Resonite nelle...",kw={"gola dei franamassi","terrigeni","coboldo","mor'rogal","resonite","cristallo di resonite","vette di petrartiglio","rifugio roccia del sole","titani"},ang={["class:Shaman"]="Come sciamano che ascolta la terra, puoi percepire nella roccia una risonanza innaturale, mentre i coboldi portano alla luce reliquie dell'antica arte elementale dei Titani.",["profession:Mining"]="Come minatore, capisci che la Resonite dei Franamassi non è un minerale comune. La sua struttura contiene residui arcani lasciati da antichi costruttori sotterranei.",["race:Tauren"]="Come tauren che venera la Earth Mother, potresti vedere le antiche opere dei Titani sotto le montagne come un pericoloso squilibrio nella natura delle Vette di Petrartiglio."},sec={{t="Tensione nella pietra",b="Al Rifugio Roccia del Sole, Mor'rogal osserva le cime delle Vette di Petrartiglio e sente la terra agitarsi. Un'agitazione innaturale sale da sud-est. Nella Gola dei Franamassi, i coboldi hanno abbandonato il consueto foraggiamento e ora scavano con foga in cerca di Resonite, un minerale raro che si trova nel sottosuolo. Mor'rogal manda esploratori dell'Orda oltre i coboldi, fino alle profondità della caverna. Chiede loro di riportare campioni grezzi e scoprire perché i coboldi scavino con tanta frenesia."},{t="Risvegliare gli Antichi",b="I cristalli grezzi di Resonite vibrano di antica magia dei Terrigeni. I coboldi hanno scavato nella roccia profonda e dissotterrato un Terrigeno, uno degli esseri di pietra primordiali che i Titani modellarono per formare le fondamenta sotterranee di Kalimdor. I loro scavi hanno disturbato una reliquia della storia primordiale. I tauren devono agire prima che l'essere sepolto si liberi."}},faq={{q="Dove si trova la Gola dei Franamassi?",a="A sud-est del Rifugio Roccia del Sole, la Gola dei Franamassi si addentra nelle Vette di Petrartiglio. I coboldi dei Franamassi infestano le sue tortuose caverne.",al={"posizione gola dei franamassi","dove si trova gola dei franamassi","come trovare gola dei franamassi"}},{q="Chi assegna la missione Gola dei Franamassi?",a="Mor'rogal, un tauren del Rifugio Roccia del Sole, assegna l'incarico. Il Rifugio Roccia del Sole è il principale avamposto dell'Orda nelle Vette di Petrartiglio.",al={"chi inizia gola dei franamassi","chi assegna la missione gola dei franamassi","missione mor'rogal"}},{q="Cosa sono i cristalli di Resonite?",a="La Resonite è un minerale raro che si trova nelle profondità del sistema di caverne dei Franamassi. Reca tracce di magia dei Terrigeni forgiata dai Titani, segno che i cristalli si sono formati vicino a reliquie sotterranee dei Terrigeni.",al={"cos'è la resonite","tradizione resonite","cristalli di resonite"}},{q="Perché i coboldi estraggono la Resonite così freneticamente?",a="I coboldi hanno trovato Resonite mentre scavavano alla ricerca di minerali scintillanti. Gli scavi li hanno portati nelle profondità delle montagne, dove hanno disturbato un antico Terrigeno sepolto nella roccia.",al={"perché i coboldi scavano","obiettivo dei coboldi della gola dei franamassi","complotto dei coboldi nelle vette di petrartiglio"}},{q="Cos'è un Terrigeno secondo la tradizione tauren?",a="Secondo l'antico sapere di Mor'rogal, i Terrigeni sono creature scolpite nella pietra che i Titani forgiarono molto tempo fa per scavare e modellare il basamento del mondo.",al={"cosa sono i terrigeni","collegamento terrigeni titani","chi sono i terrigeni"}},{q="Cosa succede dopo aver completato questa missione?",a="Dopo aver trovato tracce di magia dei Terrigeni nei cristalli di Resonite, Mor'rogal prepara una contromisura incantata. Ti rimanda nella caverna per affrontare la minaccia risvegliata.",al={"missione successiva dopo gola dei franamassi","cosa segue gola dei franamassi","seguito di gola dei franamassi"}}},fx={["574c7326"]={q="Perché Mor'rogal vuole che si indaghi?",a="Mor'rogal percepisce una tensione inquietante nelle Vette di Petrartiglio e teme che un male sconosciuto si agiti sotto le cime. I koboldi hanno cominciato a scavare freneticamente per estrarre strani cristalli di resonite, e Mor'rogal ha bisogno di campioni e ricognizioni dalle profondità della caverna per capire quali forze antiche potrebbero star disturbando.",al={"perché indagare nella gola dei franamassi","motivo di mor'rogal","perché interessa a mor'rogal"}},["6ccd8309"]={q="Contro chi vieni mandato nella Gola dei Franamassi?",a="Vieni mandato contro i koboldi della Gola dei Franamassi che infestano il burrone a sud-est del Rifugio Roccia del Sole. Di solito sono semplici saccheggiatori, ma questi koboldi sono stati sopraffatti da un'ossessione frenetica e scavano senza sosta in profondità sottoterra per estrarre minerale di resonite, per ragioni che minacciano la pace delle alture rocciose.",al={"chi c'è nella gola dei franamassi","nemici della gola dei franamassi","koboldi nella gola dei franamassi"}}},fp="19,126,20.449.0,22.329.1,37.134.0,40.128.0,27.177.1,51.171.1,44.128.0,41.164.1"}
P.entries["quest:643"] = {n="Sigillo di Arathor",s="Zengu ti manda da Requie del Martello a cercare un sigillo portato dalla cavalleria umana negli Altopiani d'Arathi. Trova il suo comandante, il Luogotenente Valorcall, e riportagli il sigillo.",h="Zengu ti manda da Requie del Martello a cercare un sigillo portato dalla cavalleria umana negli Altopiani...",kw={"altopiani d'arathi","requie del martello","luogotenente valorcall","sigil of arathor","stromgarde","trol'kalar","valorcall","zengu"},sec={{t="La cavalleria del principe",b="Zengu dubita che gli umani possano rivendicare Stromgarde, figuriamoci tutti gli Altopiani d'Arathi. Eppure il loro principe manda ancora gli ultimi cavalieri a percorrere la campagna. Zengu non capisce perché. Sa che il Luogotenente Valorcall guida quei cavalieri e porta con sé uno dei sigilli. Trova Valorcall e riportalo a Requie del Martello."},{t="A cavallo",b="Zengu ti avverte che è difficile raggiungere Valorcall, perché il suo cavallo lo porta rapidamente attraverso la regione. Se Valorcall scomparisse, i difensori di Stromgarde subirebbero un duro colpo. A quel punto, all'Orda mancherebbe un solo sigillo per reclamare Trol'kalar."}},faq={{q="Chi ti manda a cercare il Sigil of Arathor?",a="Zengu ti manda da Requie del Martello a cercare il Sigil of Arathor.",al={"incaricato della missione sigil of arathor","chi dà il sigil of arathor","dove trovare il sigil of arathor"}},{q="Chi possiede il Sigil of Arathor?",a="Il Luogotenente Valorcall guida la cavalleria umana e possiede il Sigil of Arathor. Il principe umano gliel'ha consegnato. Zengu dice che Valorcall cavalca e che è difficile rintracciarlo.",al={"chi ha il sigil of arathor","dove si trova valorcall","posizione luogotenente valorcall"}},{q="Perché il Luogotenente Valorcall ha il sigillo?",a="Zengu dice che il principe umano ha consegnato uno dei sigilli al Luogotenente Valorcall, ma non spiega perché.",al={"perché valorcall ha il sigillo","chi ha dato il sigillo a valorcall"}},{q="Dove si inserisce questo nella catena di Trol'kalar?",a="Il Sigil of Arathor è il quinto passaggio della catena di Trol'kalar. Viene dopo il Sigil of Thoradin, e il Sigil of Trollbane è il successivo.",al={"catena missioni trolkalar arathor","cosa viene prima del sigil of arathor","cosa viene dopo il sigil of arathor"}},{q="Dove porti il sigillo una volta trovato?",a="Riporta il sigillo a Zengu a Requie del Martello.",al={"dove consegnare il sigil of arathor","consegna del sigil of arathor"}}},fp="16,164,20.312.0,12.231.1,43.61.0,31.175.0,45.100.0,44.136.0,46.44.0"}
P.entries["quest:644"] = {n="Sigillo di Cacciatroll",s="A Requie del Martello, Zengu ti manda nel cuore di Stromgarde a prendere il Sigil of Trollbane. Il Principe Galen custodisce l'ultimo sigillo, necessario per reclamare Trol'kalar.",h="A Requie del Martello, Zengu ti manda nel cuore di Stromgarde a prendere il Sigil of Trollbane.",kw={"galen trollbane","requie del martello","sigil of arathor","stromgarde","trol'kalar","zengu","zul'gurub"},sec={{t="L'Ultimo Sigillo",b="Il Principe Galen, figlio di Thoras Trollbane, custodisce l'ultimo sigillo a Stromgarde. Ti aspetta in una cappella nel cuore dei distretti controllati dalla milizia. Zengu ti avverte che Galen è ben protetto ed è un abile combattente. Devi uccidere il principe e riportare il sigillo a Zengu a Requie del Martello."},{t="Il Verdetto di Zengu",b="Zengu ti chiede se la stirpe di Ignaeus Trollbane è stata spezzata. Quando lo sarà, dichiara che il sangue dei Trollbane non tormenterà più la sua gente. Ora hanno tutti i sigilli necessari per reclamare Trol'kalar. Zengu giura che presto colpiranno i troll di Zul'gurub, che odia."}},faq={{q="Chi ti manda a recuperare il Sigil of Trollbane?",a="Zengu ti manda da Requie del Martello a recuperare il Sigil of Trollbane.",al={"chi dà la missione del sigil of trollbane","chi dà il sigil of trollbane","dove inizia la missione del sigil of trollbane"}},{q="Dove si trova il Principe Galen Trollbane?",a="Il Principe Galen Trollbane ti aspetta in una cappella nel cuore di Stromgarde, nei distretti controllati dalla milizia.",al={"posizione principe galen trollbane","dove si trova galen trollbane","galen trollbane stromgarde"}},{q="Perché serve il Sigil of Trollbane?",a="Il Sigil of Trollbane è l'ultimo sigillo che serve a Zengu per aprire la tomba di Thoras Trollbane. Lo custodisce suo figlio, il Principe Galen.",al={"a cosa serve il sigil of trollbane","perché ottenere il sigil of trollbane"}},{q="Cosa succede dopo aver ottenuto il Sigil of Trollbane?",a="Dopo aver ottenuto il Sigil of Trollbane, la catena prosegue con Trol'kalar.",al={"missione successiva al sigil of trollbane","cosa segue il sigil of trollbane"}}},fp="18,151,14.273.0,15.267.1,49.67.0,40.101.0,37.131.0,50.77.0"}
P.entries["quest:6441"] = {n="Corna di Satiro",s="All'Avamposto di Troncorotto, le Corna di Satiro offrono a Pixel l'occasione di commerciare a Porto Paranco. Il goblin viaggiatore le cerca per il viaggio verso sud, fino alla città portuale.",h="All'Avamposto di Troncorotto, le Corna di Satiro offrono a Pixel l'occasione di commerciare a Porto Paranco.",kw={"valtetra","jorxian","pixel","porto paranco","corna di satiro","satirnaar","avamposto di troncorotto","xavian"},ang={["class:Hunter"]="Seguire umanoidi demoniaci tra rovine boschive corrotte come Satirnaar e Jorxian mette a dura prova le tue abilità nella natura selvaggia.",["class:Warlock"]="I satiri sono portatori di potente magia vil, e i loro resti interessano a chi studia il potere demoniaco.",["faction:Horde"]="Eliminare gli insediamenti dei satiri nel centro di Valtetra indebolisce le minacce demoniache alle fragili linee di rifornimento dell'Avamposto di Troncorotto."},sec={{t="Un'opportunità redditizia",b="All'Avamposto di Troncorotto, Pixel intravede un'occasione di guadagno mentre si riposa tra un viaggio e l'altro. A Porto Paranco le corna di satiro valgono molto, e Pixel le vuole per il viaggio di ritorno verso sud, fino alla città portuale. Invece di affrontare le creature corrotte, Pixel assolda gli avventurieri di passaggio perché riportino sedici corna intatte."},{t="I covi dei corrotti",b="Satiri demoniaci infestano rovine sparse, contaminate dal vilpotere, in tutta Valtetra. Sono i resti di un tradimento avvenuto durante l'antico cataclisma. Puoi cercarli nelle loro roccaforti di Jorxian, nell'accampamento fortificato di Satirnaar e nei boschetti ombrosi di Xavian. Pixel cerca corna in uno qualsiasi di questi luoghi per le banchine mercantili di Porto Paranco."}},faq={{q="Chi è Pixel?",a="Pixel è un goblin viaggiatore che fa tappa all'Avamposto di Troncorotto, a Valtetra, prima di dirigersi a sud verso Porto Paranco, un porto neutrale.",al={"chi è chi assegna la missione","storia di pixel","goblin all'avamposto di troncorotto"}},{q="Perché Porto Paranco vuole le corna di satiro?",a="Pixel dice che le corna di satiro valgono molto a Porto Paranco. Mercanti, alchimisti e collezionisti di merci esotiche pagano bene per reagenti demoniaci grezzi e curiosità provenienti dai boschi del nord.",al={"perché corna di satiro","a cosa servono le corna","corna di satiro porto paranco"}},{q="Dove si possono trovare le corna di satiro a Valtetra?",a="I satiri infestano i luoghi contaminati di Valtetra, tra cui Jorxian, a nord-ovest dell'Avamposto di Troncorotto, Satirnaar, appena fuori dalla strada principale verso Azshara, e Xavian, nella parte nord-orientale di Valtetra.",al={"posizioni dei satiri","dove trovare i satiri","jorxian xavian satirnaar"}},{q="Cosa sono i satiri?",a="I satiri sono antichi elfi della notte corrotti dalla Legione Infuocata migliaia di anni fa. Ora hanno zoccoli biforcuti e corna, servono poteri oscuri e corrompono la foresta circostante.",al={"cos'è un satiro","storia dei satiri","i satiri sono demoni"}},{q="Perché questo contratto viene gestito all'Avamposto di Troncorotto?",a="L'Avamposto di Troncorotto è la principale fortezza dell'Orda nel centro di Valtetra. Pixel vi si riposa tra una rotta commerciale e l'altra, e assolda i guerrieri dell'Orda che si trovano nei dintorni e già affrontano i pericoli della foresta.",al={"missione satiri avamposto di troncorotto","perché solo l'orda"}},{q="Pixel è fedele all'Orda?",a="No. Pixel è un mercante goblin indipendente in cerca di profitto. Come molti goblin che hanno base a Porto Paranco, commercia con chiunque possa procurargli merci di valore, a prescindere dalle rivalità tra fazioni.",al={"pixel è dell'orda","fazione di pixel"}}},fx={["22d423d7"]={q="Perché Pixel vuole le corna di satiro?",a="Pixel è una viaggiatrice intraprendente diretta a Porto Paranco, con un occhio agli affari. Sapendo che le corna di satiro raggiungono un buon prezzo nel porto dei goblin, vuole ricavarne un discreto profitto prima di completare il viaggio. Invece di affrontare personalmente le bestie pericolose, è disposta a pagare avventurieri capaci perché facciano il lavoro sporco e le consegnino la merce.",al={"perché pixel vuole questo","motivo di pixel per le corna di satiro","perché raccogliere le corna di satiro"}},fc903cbf={q="Perché Pixel non dà la caccia ai satiri da sola?",a="Pixel ammette senza esitazione di non poter competere con i feroci satiri che brandiscono la magia e si aggirano tra le rovine di Valtetra. Non avendo l'abilità in combattimento necessaria per sopravvivere a uno scontro in luoghi come Satirnaar o Xavian, si affida interamente ai mercenari esperti di passaggio all'Avamposto di Troncorotto per procurarle la merce.",al={"perché pixel ha bisogno di me","perché pixel non può prendere le corna","perché ingaggiare un avventuriero"}}},fp="11,147,23.301.0,23.319.0,13.120.0,34.177.0,44.184.0,16.175.0,50.176.0,44.188.0"}
P.entries["quest:6442"] = {n="Naga sulla Spiaggia di Zoram",s="Sulla costa di Valtetra, i naga minacciano il controllo dell'Orda sulla Spiaggia di Zoram. Dall'Avamposto di Zoram'gar, Marukai cerca di scacciare i Coda d'Ira dalle rovine sommerse dell'antica Zoram.",h="Sulla costa di Valtetra, i naga minacciano il controllo dell'Orda sulla Spiaggia di Zoram.",kw={"valtetra","marukai","naga","coda d'ira","teste coda d'ira","spiaggia di zoram","avamposto di zoram'gar"},ang={["faction:Horde"]="Come membro dell'Orda, aiuti a difendere l'Avamposto di Zoram'gar e a consolidare una posizione a Valtetra. Scacciare i naga è una questione di sopravvivenza militare.",["race:Orc"]="Da orco, conosci il valore dell'approccio diretto e risoluto di Marukai nel difendere una frontiera."},sec={{t="Una Precarietà Instabile",b="Il controllo dell'Orda sulla Spiaggia di Zoram è precario. L'avamposto sorge in territorio ostile degli Elfi della Notte, tra aspri scontri nei boschi, ma la costa offre all'Orda un collegamento con il mare. Ora, aggressivi naga sono strisciati a riva. Potrebbero interrompere quella rotta e sopraffare la piccola guarnigione prima che le difese siano pronte."},{t="Echi della Zoram Condannata",b="Sotto i bassifondi sabbiosi della Spiaggia di Zoram giacciono i resti frantumati di Zoram, un'antica città elfica inghiottita dal Grangorgo migliaia di anni fa. Marukai e i difensori dell'avamposto non sanno perché i Coda d'Ira siano emersi ora dalle profonde fosse oceaniche. Il loro improvviso interesse per le rovine sommerse minaccia chiunque cammini in superficie."},{t="Il Prezzo della Sopravvivenza",b="Per Marukai è una semplice lotta per la sopravvivenza. Con spade e tridenti sguainati, la ragione conta poco. Esige venti teste mozzate dai Coda d'Ira. Spera che la forza ricacci i naga negli abissi e metta in sicurezza la costa per l'Orda."}},faq={{q="Chi assegna la missione Naga alla Spiaggia di Zoram?",a="Marukai, una troll Puntascura, assegna l'incarico dall'avamposto dell'Orda di Zoram'gar, sulla Spiaggia di Zoram, nella parte nord-occidentale di Valtetra.",al={"chi dà la missione","chi inizia questa","posizione di marukai"}},{q="Qual è la storia dietro la Spiaggia di Zoram?",a="La Spiaggia di Zoram si trova lungo il luogo in cui riposa l'antica città di Zoram. Il Grangorgo la distrusse e la sommerse sotto il Grande Mare molto tempo fa. Ora le sue rovine giacciono in parte sott'acqua lungo la costa di Valtetra.",al={"cos'è zoram","storia di zoram","città sommersa"}},{q="Perché i naga stanno attaccando la riva?",a="La guarnigione dell'Orda non sa perché siano arrivati i Coda d'Ira. I naga sono emersi dalle profondità dell'oceano per reclamare le rovine sommerse e scacciare gli abitanti della terraferma.",al={"perché i naga sono qui","movente coda d'ira","obiettivo dei naga"}},{q="Quali nemici devo combattere per questa missione?",a="Affronti i membri della tribù dei Coda d'Ira, che strisciano sulle spiagge e tra le onde della Spiaggia di Zoram. Marukai ti chiede di portarle venti delle loro teste mozzate.",al={"quali naga","teste coda d'ira","nemici da eliminare"}},{q="Quale missione segue Naga alla Spiaggia di Zoram?",a="Dopo questo incarico, Marukai non te ne affida altri. Ti ringrazia e chiede che altri della tua gente la aiutino a difendere la Spiaggia di Zoram.",al={"prossima missione","seguito","prossimo passo marukai"}},{q="Perché all'Orda interessa questa spiaggia isolata?",a="Valtetra è contesa con ferocia dall'Orda e dagli Elfi della Notte. Una testa di ponte sicura sulla Spiaggia di Zoram offre all'Orda accesso al mare e linee di rifornimento oltre le fitte foreste dell'entroterra.",al={"perché l'orda è qui","scopo dell'avamposto di zoram'gar"}}},fx={b1ee6e7c={q="Perché Marukai vuole che i naga vengano uccisi?",a="Marukai considera i naga una minaccia concreta alla presenza dell'Orda sulla spiaggia. L'Orda ha combattuto duramente per conquistare e mettere in sicurezza questo avamposto lungo la costa di Valtetra. Qualunque sia il misterioso motivo che spinge gli invasori serpentini a sbarcare, il loro numero crescente rischia di travolgere l'accampamento, a meno che non vengano decimati e ricacciati nelle profondità oceaniche.",al={"perché marukai lo vuole","motivo di marukai","perché uccidere i naga sulla spiaggia di zoram"}},["7626cdcb"]={q="Chi sono i naga Codatruce e perché si trovano sulla Spiaggia di Zoram?",a="La tribù dei naga Codatruce è emersa dal mare per occupare le rovine di Zoram, un'antica città kaldorei distrutta e sommersa durante il Grangorgo. Le loro intenzioni più profonde restano ignote ai difensori dell'Orda, ma la loro presenza sempre più invadente e le incursioni ostili lungo la costa sono una minaccia immediata per chiunque si avvicini alla spiaggia.",al={"chi sono i codatruce","storia dei naga codatruce","perché i codatruce sono qui"}}},fp="24,178,21.310.0,22.333.0,21.242.0,45.121.0,44.207.0,37.160.0,48.151.0,44.119.0,48.177.0"}
P.entries["quest:645"] = {n="Trol'kalar",s="A Stromgarde, Zengu ti manda a cercare Trol'kalar, ora che i quattro sigilli si sono uniti.",h="A Stromgarde, Zengu ti manda a cercare Trol'kalar, ora che i quattro sigilli si sono uniti.",kw={"cripta","santuario","sigillo di ignaeus","stromgarde","trol'kalar","trollbane","zengu"},sec={{t="Un Sigillo da Quattro",b="Zengu ha visto i quattro sigilli unirsi nel Sigillo di Ignaeus. Crede che la loro unione possa spezzare le protezioni sulla tomba di Trollbane. La tomba si trova nel Santuario dietro la cappella di Stromgarde, e Zengu ti manda lì a recuperare Trol'kalar. Un sentiero recintato a destra dell'ingresso della cappella scende verso la cripta."},{t="La Tomba si Apre",b="Le incisioni sulla tomba di Trollbane corrispondono alle linee luminose del sigillo. Quando si incontrano, un lampo di luce inghiotte il sigillo. Trol'kalar, la leggendaria spada, viene liberata dalle mani di pietra che la trattenevano."}},faq={{q="Chi ti manda a recuperare Trol'kalar?",a="Zengu ti manda a recuperare Trol'kalar dopo che i quattro sigilli si sono uniti nel Sigillo di Ignaeus.",al={"chi assegna questa missione","assegnatore missione","zengu"}},{q="Dove si trova la tomba di Trollbane?",a="I resti di Trollbane si trovano nel Santuario dietro la cappella di Stromgarde. Un sentiero recintato a destra dell'ingresso della cappella scende verso la cripta.",al={"dove si trova la tomba","posizione tomba","posizione cripta"}},{q="Cosa succede ai quattro sigilli?",a="I quattro sigilli si uniscono nel Sigillo di Ignaeus. Zengu crede che possa spezzare le protezioni sulla tomba di Trollbane.",al={"cosa è successo ai sigilli","sigillo di ignaeus"}},{q="Qual è il passaggio precedente in questa serie?",a="Prima di questo viene il Sigillo di Trollbane, l'ultimo dei quattro sigilli.",al={"missione precedente","missione anteriore","sigillo di trollbane"}}},fp="10,89,19.309.0,14.196.1,37.91.0,34.139.0,32.108.0,40.67.0"}
P.entries["quest:646"] = {n="Trol'kalar",s="Alla Tomba di Trollbane, Trol'kalar scivola fuori dal suo fodero di pietra mentre la luce svanisce. Porti la spada a Zengu a Requie del Martello.",h="Alla Tomba di Trollbane, Trol'kalar scivola fuori dal suo fodero di pietra mentre la luce svanisce.",kw={"arathi","requie del martello","nimboya","trol'kalar","trollbane","zengu","zul'gurub"},sec={{t="Una spada liberata",b="Alla Tomba di Trollbane, trovi Trol'kalar fuori dal suo fodero di pietra. Porti la spada nel fodero a Zengu a Requie del Martello, negli Altopiani d'Arathi."},{t="Cosa dice Zengu",b="Zengu dice che le forze di Strom e Arathor hanno predato i troll per generazioni. Ora il suo popolo possiede la sua arma più potente, e la lenta avanzata nelle foreste umide di Zul'gurub non sarà più una lotta. Dice che i troll Puntascura ti sono debitori. Porterà la spada a Nimboya a Grom'gol."}},faq={{q="Dove deve andare Trol'kalar?",a="Porta la spada, ancora nel suo fodero di pietra, a Zengu a Requie del Martello, negli Altopiani d'Arathi.",al={"dove porto trolkalar","consegna di trol'kalar","consegna trolkalar"}},{q="Dove trovo la spada?",a="Trova la spada alla Tomba di Trollbane, dove la luce che svanisce l'ha liberata dal suo fodero di pietra.",al={"dove si trova trol'kalar","posizione trolkalar"}},{q="Cosa è successo prima di questo passo?",a="Questo segue il passaggio precedente di Trol'kalar ed è l'ultimo passaggio della lunga serie.",al={"precedente di trolkalar","serie di missioni di trolkalar"}}},fp="10,126,16.144.0,15.298.1,33.92.0,26.94.0,27.80.0"}
P.entries["quest:6461"] = {n="Blood Feeders",s="A Malaka'jin, Blood Feeders comincia con la selvaggina macellata che attira i ragni Muschioprofondo verso gli accampamenti dei troll. Xen'zilla chiede all'Orda di ricacciare i predatori lontano dall'insediamento.",h="A Malaka'jin, Blood Feeders comincia con la selvaggina macellata che attira i ragni Muschioprofondo verso gli...",kw={"blood feeders","strisciatore muschioprofondo","sputaveleno muschioprofondo","malaka'jin","canyon di sishir","ragni","vette di petrartiglio","xen'zilla"},ang={["class:Hunter"]="Per un cacciatore esperto che attraversa i dirupi, seguire le tracce di predatori pericolosi, capaci di cacciare meglio di lui e di tormentare gli insediamenti alleati, è un lavoro naturale.",["faction:Horde"]="In quanto membro dell'Orda, aiuti a proteggere Malaka'jin. Il villaggio presidia la via d'accesso dell'Orda alle Vette di Petrartiglio, dalle Savane settentrionali, e difende l'intero passo meridionale.",["race:Troll"]="In quanto troll, condividi un legame di parentela con i cacciatori di Malaka'jin. Si impegnano a ritagliarsi un territorio autosufficiente sugli aspri altopiani di Kalimdor, senza soccombere alla natura selvaggia."},sec={{t="Ospiti indesiderati",b="I troll fondarono Malaka'jin come avamposto di frontiera nelle Vette di Petrartiglio sud-orientali, dove potevano andare a caccia. I pendii scoscesi offrono molta selvaggina, ma la carne attira predatori notturni nell'accampamento. I ragni Muschioprofondo sono aracnidi aggressivi originari dei dirupi e dei canyon a nord. Col favore delle tenebre, si intrufolano per frugare tra le scorte dei troll o cacciare i cacciatori stessi."},{t="Ripulire i dirupi",b="Xen'zilla ti chiede di seguire le tracce dei predatori verso nord, tra i passi montani. Così aiuterai a tenere al sicuro Malaka'jin e a proteggere le sue provviste. Gli Strisciatori Muschioprofondo e gli Sputaveleno si radunano soprattutto presso i burroni rocciosi e le ragnatele del Canyon di Sishir. Riducine il numero e la covata si ritirerà dall'insediamento. Allora i cacciatori potranno riposare senza temere imboscate nell'ombra."}},faq={{q="Chi offre la missione Blood Feeders?",a="Xen'zilla, un troll Puntascura di Malaka'jin, nelle Vette di Petrartiglio sud-orientali, offre il contratto di caccia ai campioni dell'Orda di passaggio.",al={"chi dà blood feeders","chi assegna blood feeders","missione xen'zilla"}},{q="Perché i ragni attaccano Malaka'jin?",a="Di notte, l'odore delle prede appena uccise e della carne messa a essiccare attira i ragni Muschioprofondo giù dai passi montani. I troll di Malaka'jin cacciano la selvaggina locale, e i ragni arrivano per rubare le provviste e dare la caccia agli abitanti.",al={"perché i ragni attaccano","attacchi dei ragni a malaka'jin","perché i ragni invadono"}},{q="Dove si trovano i ragni Muschioprofondo?",a="Gli Strisciatori Muschioprofondo e gli Sputaveleno si aggirano tra i passi e i dirupi centrali a nord di Malaka'jin. Si radunano soprattutto nel burrone ricoperto di ragnatele del Canyon di Sishir.",al={"dove sono i ragni muschioprofondo","posizione strisciatori muschioprofondo","posizione sputaveleno muschioprofondo"}},{q="Cos'è Malaka'jin?",a="Malaka'jin è un accampamento di troll Puntascura all'ingresso meridionale delle Vette di Petrartiglio, vicino al confine con le Savane. È una base di caccia e un avamposto di frontiera dell'Orda.",al={"cos'è malaka'jin","lore malaka'jin","villaggio troll vette di petrartiglio"}},{q="C'è una minaccia maggiore legata a questi ragni?",a="Una gigantesca e letale matriarca dei ragni vive nelle profondità del Canyon di Sishir, tra le ragnatele. Un cartello di avvertimento fuori dal canyon segnala il pericolo ai viaggiatori e li esorta ad abbatterla in gruppo.",al={"ragno grande vette di petrartiglio","ragno élite canyon di sishir","matriarca ragno vette di petrartiglio"}},{q="Cosa succede dopo che i ragni vengono abbattuti?",a="Decimare gli Strisciatori e gli Sputaveleno dà un po' di respiro a Malaka'jin. I cacciatori troll possono mettere al sicuro le scorte di carne e sorvegliare di notte i loro accampamenti senza temere continue imboscate.",al={"conseguenze blood feeders","malaka'jin diventa sicura"}}},fx={["5b921468"]={q="Che cosa ci fanno i ragni Muschiofondo nelle Vette di Petrartiglio?",a="I rampicanti e gli sputa-veleno Muschiofondo sono aracnidi nativi che si aggirano tra le rupi e i canyon delle Vette di Petrartiglio. Hanno sempre abitato queste rupi, ma l'odore della selvaggina fresca portata a Malaka'jin dai cacciatori troll li ha attirati più vicino alla civiltà. Ora, sempre più audaci, questi predatori aggressivi escono dalle colline rocciose per razziare gli accampamenti del villaggio col favore delle tenebre.",al={"ragni muschiofondo nelle vette di petrartiglio","rampicanti e sputa-veleno muschiofondo","perché ci sono i ragni"}}},fp="13,179,22.391.0,18.377.0,35.138.0,41.210.0,39.164.0,19.173.0,48.179.0,42.169.0"}
P.entries["quest:6462"] = {n="Talismano Troll",s="Talismano Troll è una missione dell'Orda offerta dal troll Lanciascura Mitsuwa presso l'Avamposto di Zoram'gar a Valtetra. Dopo che un gruppo di troll in viaggio è stato vittima di un'imboscata e massacrato dai furbolg Mantocardo, Mitsuwa chiede agli avventurieri di addentrarsi nella loro tana per recuperare i talismani sacri rubati ai defunti.",h="Talismano Troll è una missione dell'Orda offerta dal troll Lanciascura Mitsuwa presso l'Avamposto di...",kw={"valtetra","lanciascura","furbolg","mitsuwa","rifugio dei mantocardo","villaggio dei mantocardo","talismano troll","avamposto di zoram'gar"},ang={["faction:Horde"]="Spingersi nel territorio dei Mantocardo significa contrattaccare le minacce boschive che tendono imboscate alle linee di rifornimento dell'Orda e ai viaggiatori che attraversano Valtetra.",["race:Troll"]="Recuperare i talismani è un dovere spirituale per i troll Lanciascura, per assicurare che gli oggetti ancestrali sacri vengano sottratti dalle grinfie dei furbolg selvaggi."},sec={{t="Una Carovana in Agguato",b="L'Avamposto di Zoram'gar funge da rifugio occidentale remoto per l'Orda sulla costa di Valtetra, rendendo i viaggi lungo i sentieri boschivi pieni di pericoli. Un gruppo di troll Lanciascura in viaggio verso l'avamposto non è mai arrivato, essendo caduto vittima di una violenta imboscata da parte della tribù territoriale dei furbolg Mantocardo. Sebbene Mitsuwa accetti la morte dei suoi simili come un'eventuale riunione nell'aldilà, la profanazione e il furto dei loro talismani sacri sono un insulto intollerabile."},{t="Ninnoli Sacri",b="Nella cultura dei troll, i talismani e gli amuleti sono profondamente legati all'identità, alla protezione spirituale e alla connessione con i Loa. Mitsuwa considera un troll senza il proprio talismano vuoto e senza valore quanto un orco privo di cicatrici di battaglia. I furbolg Mantocardo hanno trascinato questi artefatti rubati all'interno del Rifugio dei Mantocardo, in profondità nei sistemi di caverne oltre il Villaggio dei Mantocardo, nascondendoli in forzieri lontano dai loro legittimi proprietari."}},faq={{q="Chi assegna questa missione e dove si trova?",a="La missione è assegnata da Mitsuwa, un troll Lanciascura di stanza all'Avamposto di Zoram'gar lungo la Spiaggia di Zoram sulla costa nord-occidentale di Valtetra.",al={"datore di missione","dove si trova mitsuwa","chi inizia talismano troll"}},{q="Perché i talismani dei troll sono così importanti per Mitsuwa?",a="Per i troll, i talismani sacri hanno un profondo significato spirituale e culturale. Mitsuwa paragona un troll senza il proprio talismano a un orco senza cicatrici di battaglia, vedendo il possesso di queste reliquie da parte di furbolg ostili come un'oltraggiosa profanazione dei suoi simili uccisi.",al={"importanza talismani","perché i talismani troll sono importanti","significato dei talismani"}},{q="Dove si trovano i talismani dei troll?",a="I talismani sono conservati all'interno di forzieri nel Rifugio dei Mantocardo, un complesso di caverne profonde situato al margine settentrionale del Villaggio dei Mantocardo, a nord dell'insediamento di Elfi della Notte di Astranaar.",al={"posizione talismani","dove sono i forzieri","trovare talismani"}},{q="Chi ha rubato i talismani?",a="I furbolg Mantocardo hanno teso un'imboscata e ucciso i parenti di Mitsuwa mentre viaggiavano verso l'Avamposto di Zoram'gar, saccheggiando i loro averi e trasportando i talismani sacri nelle loro caverne.",al={"chi ha preso i talismani","responsabili imboscata"}},{q="Cosa è successo ai troll che originariamente portavano i talismani?",a="Sono stati uccisi dai furbolg Mantocardo lungo il sentiero. Mitsuwa piange la loro perdita ma crede che alla fine si ricongiungerà con loro nell'aldilà, dando priorità al recupero delle loro reliquie sacre.",al={"destino carovana","troll uccisi","parenti di mitsuwa"}},{q="Questa missione è disponibile per l'Alleanza?",a="No. La missione ha origine all'Avamposto di Zoram'gar ed è disponibile esclusivamente per i giocatori dell'Orda che aiutano la tribù Lanciascura.",al={"alleanza talismano troll","l'alleanza può farla"}}},fx={["3db0517e"]={q="Che cos'è il Talismano Troll?",a="Questi talismani sono reliquie profondamente sacre portate dai troll Lanciascura. Nella loro cultura, un talismano rappresenta onore, identità e appartenenza spirituale: come dice Mitsuwa, un troll senza il suo talismano è vuoto e senza valore quanto un orco privo di cicatrici di battaglia. Anche se i proprietari caduti si ricongiungeranno ai loro simili nell'aldilà, lasciare che questi venerati simboli restino sporchi nelle mani di bestie selvagge è un oltraggio intollerabile alla loro memoria.",al={"storia del talismano troll","a cosa serve il talismano troll","cosa sono i talismani troll"}}},fp="11,292,19.467.0,15.422.0,48.142.0,49.253.0,35.190.0,21.181.0,62.205.0,40.117.0"}
P.entries["quest:647"] = {n="Torcibudella di MacKreel",s="Foggy MacKreel ha bisogno che il suo Torcibudella di MacKreel venga portato dal Viadotto di Thandol in rovina fino a Riva del Sud. Ha bevuto troppo durante la guardia e ora ha poco tempo per consegnare una nuova partita al Mastro Birraio Bilger e saldare il suo debito.",h="Foggy MacKreel ha bisogno che il suo Torcibudella di MacKreel venga portato dal Viadotto di Thandol in rovina...",kw={"bilger","foggy","treccialunga","mackreel","menethil","torcibudella","riva del sud"},ang={["faction:Alliance"]="Come viaggiatore dell'Alleanza, percorri la strada terrestre che collega il Viadotto di Thandol a Riva del Sud, controllata dall'Alleanza, a Colletorto.",["race:Dwarf"]="Da nano, conosci la sofferenza di una tremenda sbornia, aggravata da un debito non saldato per la birra con un tuo parente."},sec={{t="I postumi di una guardia",b="Sul Viadotto di Thandol in frantumi, Foggy MacKreel fa la guardia per ore umide, fredde e noiose. Beve il suo Torcibudella fatto in casa per sopportare il freddo e l'umidità. La bevanda è così forte che paragona i postumi a macchine d'assedio che gli martellano il cranio. Un bicchiere di troppo lo lascia addormentato durante il turno. Treccialunga il Macabro comanda i nani che difendono il Viadotto, e Foggy non può permettersi un'altra mancanza di disciplina."},{t="Una corsa contro il tempo",b="Foggy ha un debito di lunga data con il Mastro Birraio Bilger a Riva del Sud. Ha promesso una partita della sua birra personale per saldare il conto, ma tra i postumi della sbornia e i suoi doveri di guardia, mancano pochi minuti alla scadenza. Attraversi di corsa gli Altopiani d'Arathi con la brocca, in grifone e a passo svelto. Raggiungi Riva del Sud prima che Bilger decida che Foggy è di nuovo scappato senza pagare il conto."}},faq={{q="Chi è Foggy MacKreel?",a="Foggy MacKreel è un nano nella parte in rovina del Viadotto di Thandol, raggiungibile dal lato degli Altopiani d'Arathi. Prepara un Torcibudella estremamente forte e spesso beve troppo mentre è di turno.",al={"foggy mackreel","chi è foggy","datore missione mackreel"}},{q="Perché questa consegna è così urgente?",a="Foggy è svenuto ubriaco durante la guardia e ha accumulato un grave ritardo. Gli resta a malapena un quarto d'ora per portare il Torcibudella dal Viadotto di Thandol a Riva del Sud e saldare il suo conto scaduto con il Mastro Birraio Bilger.",al={"perché c'è un timer","perché 15 minuti","timer torcibudella mackreel"}},{q="Chi è il Mastro Birraio Bilger?",a="Il Mastro Birraio Bilger è un maestro birraio nano nell'insediamento costiero di Riva del Sud, nelle Alture di Colletorto. Apprezza gli alcolici forti e ha un accordo commerciale in sospeso con Foggy MacKreel.",al={"mastro birraio bilger","chi è bilger","bilger riva del sud"}},{q="Come si porta il Torcibudella a Riva del Sud in tempo?",a="Non ci sono barche dal Viadotto a Riva del Sud. Se conosci la rotta di volo per Fosso dei Rifugiati, prendi un grifone da Fosso dei Rifugiati a Riva del Sud, poi trova il Mastro Birraio Bilger in città prima che scada il tempo.",al={"come consegnare il torcibudella","via più veloce mackreel riva del sud","rotta consegna torcibudella"}},{q="Chi è Treccialunga?",a="Treccialunga il Macabro è il comandante nano fuori da Dun Modr, nelle Paludi Grigie. Guida i difensori del Viadotto di Thandol, e Foggy teme che Treccialunga scopra che si è ubriacato fino a svenire durante la guardia.",al={"capitano treccialunga","treccialunga menethil"}}},fx={d39890fd={q="Perché Foggy MacKreel non può consegnare il distillato da solo?",a="La sera prima Foggy MacKreel ha esagerato parecchio con il suo stesso distillato ed è finito svenuto durante il turno di guardia. Con un mal di testa martellante, il suo incarico ufficiale di guardia di cui rispondere a Treccialunga il Macabro e una scadenza ormai vicina per saldare i debiti con Mastro Birraio Bilger, non è nelle condizioni né nella posizione di partire da solo per Riva del Sud.",al={"perché io per mackreel","perché consegnare il distillato","perché io per il distillato di foggy"}}},fp="20,211,18.422.0,24.368.0,22.183.0,31.217.0,26.206.0,53.196.0,17.208.0"}
P.entries["quest:648"] = {n="Salva OOX-17/TN!",s="A Porto degli Spargifumo, OOX-17/TN ha bisogno di tempo e spazio aperto per decollare. La voce di Oglethorpe arriva dal robot danneggiato: ti chiede di scortarlo al sicuro fin lì, poi di raggiungerlo a Baia del Bottino.",h="A Porto degli Spargifumo, OOX-17/TN ha bisogno di tempo e spazio aperto per decollare.",kw={"baia del bottino","robot trasmittente","pollo meccanico","oglethorpe obnoticus","oox-17/tn","porto degli spargifumo","tanaris"},sec={{t="Una scorta verso il porto",b="La voce di Oglethorpe gracchia ancora una volta dal robot OOX-17/TN. Il robot ha un dispositivo di occultamento integrato, ma Oglethorpe ha bisogno di tempo per ripristinarlo. Gli serve un luogo aperto e sicuro dove iniziare il lungo decollo. Oglethorpe ha scelto Porto degli Spargifumo, e il viaggio gli darà il tempo di ripristinare l'occultamento. Ti viene chiesto di scortare il robot al sicuro."},{t="Rapporto a Baia del Bottino",b="Quando OOX-17/TN raggiunge Porto degli Spargifumo, cerca Oglethorpe Obnoticus a Baia del Bottino. È un maestro inventore."},{t="Un inventore riconoscente",b="Oglethorpe ti accoglie come colui che ha salvato OOX-17/TN. La serie di robot trasmittenti ha ancora bisogno di molto lavoro, ma riportare questo robot ha risparmiato innumerevoli ore di ricostruzione e molti pezzi d'oro in costi di rilegatura. Oglethorpe dice che i robot e il loro inventore sono in debito con te."}},faq={{q="Dove deve essere scortato il robot?",a="Scorta OOX-17/TN fino a Porto degli Spargifumo, dove potrà iniziare il lungo decollo al sicuro.",al={"dove va oox-17","percorso scorta oox-17","destinazione robot"}},{q="Chi sta parlando attraverso il robot?",a="Oglethorpe Obnoticus, gnomo e maestro inventore, parla attraverso il suo robot trasmittente. Puoi trovarlo a Baia del Bottino.",al={"chi ha creato oox-17","creatore oox-17","chi parla attraverso il robot"}},{q="Perché il robot deve essere spostato?",a="Al robot serve un luogo aperto e sicuro dove iniziare il lungo decollo. Anche il suo dispositivo di occultamento integrato ha bisogno di tempo per tornare a funzionare.",al={"perché spostare oox-17","perché porto degli spargifumo"}},{q="Dove devi fare rapporto dopo la scorta?",a="Riferisci a Oglethorpe Obnoticus a Baia del Bottino.",al={"dove si trova oglethorpe obnoticus","a chi devo consegnare questo","luogo di consegna oox-17"}}},fp="17,190,21.343.0,19.106.0,19.271.1,41.86.0,34.114.0,36.119.0,37.44.0"}
P.entries["quest:6481"] = {n="Earthen Arise",s="Nella Gola dei Franamassi, Mor'rogal trova Goggeroc addormentato in un barile di Resonite. Lo sciamano tauren teme che gli antichi Earthen possano minacciare tutta Kalimdor, così invia un campione a rompere il barile e uccidere Goggeroc prima che recuperi le forze.",h="Nella Gola dei Franamassi, Mor'rogal trova Goggeroc addormentato in un barile di Resonite.",kw={"gola dei franamassi","earthen","earthen arise","goggeroc","mor'rogal","barile di resonite","sciamano","vette di petrartiglio"},ang={["class:Shaman"]="In quanto sciamano, vedi Mor'rogal usare il potere sciamanico per alterare i cristalli di Resonite e sconvolgere l'equilibrio elementale che tiene Goggeroc nel barile.",["faction:Horde"]="In quanto membro dell'Orda, aiuti a consolidare la presenza della fazione nelle gole contese delle Vette di Petrartiglio sconfiggendo Goggeroc. Ti guadagni il rispetto duraturo dei leader del Picco del Tuono.",["race:Tauren"]="In quanto tauren, sai che le Vette di Petrartiglio sono un territorio di caccia ancestrale per le tribù del Picco del Tuono. Sconfiggere un antico essere distruttivo sulle sue vette protegge la terra dalla rovina."},sec={{t="Un sonno di pietra",b="Gli esploratori in cerca di parassiti nella Gola dei Franamassi hanno trovato una reliquia strana tra i kobold. Un barile di Resonite custodiva una forza ultraterrena. Mor'rogal, uno sciamano tauren delle Vette di Petrartiglio, ha capito che era al tempo stesso prigione e rifugio per Goggeroc, un Earthen dormiente. Questi antichi esseri di pietra possono superare in forza i guerrieri mortali, e la libertà di Goggeroc potrebbe mettere in pericolo l'intera regione."},{t="Il Cristallo di Resonite",b="Mor'rogal teme ciò che Goggeroc potrebbe fare se si risvegliasse con tutta la sua forza. Modifica la miscela di cristalli di Resonite che gli hanno portato, infondendoli di magia sciamanica. Il Cristallo di Resonite Incantato può spezzare il barile di Resonite e risvegliare Goggeroc mentre è ancora debole. I guerrieri dell'Orda devono abbattere l'essere forgiato dai Titani e disorientato prima che si scrolli di dosso secoli di torpore."}},faq={{q="Chi è Mor'rogal?",a="Mor'rogal è uno sciamano tauren di stanza nelle Vette di Petrartiglio. Studia i fenomeni insoliti della regione e usa la magia elementale per valutare gli antichi artefatti e le minacce scoperte dai parassiti locali.",al={"mor rogal","chi è il datore di missione","sciamano orco morrogal"}},{q="Cos'è un Earthen?",a="Gli Earthen sono antichi esseri forgiati nella pietra vivente, lasciati dai Titani all'alba del mondo. Legati alla terra, possiedono una forza immensa. Per millenni hanno dormito sepolti in tutta Kalimdor e nei Regni Orientali.",al={"cos'è un earthen","tradizione earthen","chi sono gli earthen"}},{q="Perché Mor'rogal vuole che Goggeroc muoia?",a="Mor'rogal teme che la forza di Goggeroc possa portare una catastrofe alle Vette di Petrartiglio e a tutta Kalimdor. Crede che l'unico modo per proteggere la terra sia distruggere Goggeroc mentre il sonno lo mantiene debole.",al={"perché uccidere goggeroc","goggeroc è malvagio","perché uccidere l'earthen"}},{q="Dove si trova Goggeroc?",a="Goggeroc giace in un barile di Resonite, nel profondo delle grotte della Gola dei Franamassi, nel sud-est delle Vette di Petrartiglio. I kobold di Boulderslide scavano le caverne circostanti.",al={"dov'è il barile","posizione di goggeroc","trovare barile di resonite"}},{q="Come si risveglia Goggeroc?",a="Risvegli Goggeroc usando il Cristallo di Resonite Incantato di Mor'rogal sul barile di Resonite nella grotta. La sua magia spezza il contenitore e costringe l'Earthen addormentato a uscire allo scoperto.",al={"come evocare goggeroc","usare cristallo di resonite incantato","aprire barile"}},{q="Cosa succede dopo che Goggeroc viene ucciso?",a="Quando torni da Mor'rogal con la notizia della morte di Goggeroc, il timore dello sciamano svanisce. Ti acclama come l'eroe che ha scongiurato una grave catastrofe, guadagnandoti onore e prestigio tra i tauren del Picco del Tuono.",al={"storia ricompensa missione","reazione di morrogal","consegna earthen arise"}}},fx={["7cc06600"]={q="Chi è Goggeroc e perché si trova nelle Vette di Petrartiglio?",a="Goggeroc è un antico Terrigeno, un essere di pietra vivente forgiato dai Titani in tempi remoti. Sigillato in un barile di Resonite nelle profondità di una grotta della Gola dei Franamassi, ha dormito sotto le Vette di Petrartiglio. Mor'rogal avverte che, se un Terrigeno si risvegliasse con tutti i suoi poteri, la sua forza ineguagliabile rappresenterebbe una minaccia catastrofica per le Vette di Petrartiglio e per tutto Kalimdor. Spaccare il barile lo coglie ancora disorientato e indebolito dal lungo sonno, offrendoti l'unica possibilità di sconfiggerlo.",al={"chi è goggeroc","storia di goggeroc","cos'è goggeroc"}},["9f2ce835"]={q="Perché Mor'rogal ha bisogno che tu sconfigga Goggeroc invece di affrontarlo lui stesso?",a="Mor'rogal usa i suoi poteri sciamanici al Rifugio Roccia del Sole per alterare i cristalli di Resonite che hai raccolto. Ti rimanda alla grotta con il cristallo incantato per aprire il barile di Goggeroc e colpire mentre il Terrigeno è indebolito dal lungo sonno.",al={"perché mor'rogal non combatte goggeroc","perché io","perché mandare me contro goggeroc"}}},fp="13,240,18.369.0,20.369.1,17.197.0,19.223.0,38.193.0,26.172.0,27.179.0,37.204.1"}
P.entries["quest:6482"] = {n="La liberazione di Ruul",s="Nella Valtetra settentrionale, Ruul attende in gabbia nel cuore del Rifugio dei Mantocardo. Ha bisogno di un alleato dell'Orda che lo aiuti a farsi strada nella tana dei furbolg corrotti e a raggiungere un luogo sicuro.",h="Nella Valtetra settentrionale, Ruul attende in gabbia nel cuore del Rifugio dei Mantocardo.",kw={"valtetra","scorta druido","furbolg","avamposto di troncorotto","rifugio dei mantocardo","yama zoccolo nevoso"},ang={["class:Druid"]="Da druido, conosci i rischi di attraversare terre selvagge in forma animale, dove gli abitanti corrotti potrebbero scambiarti per una preda.",["faction:Horde"]="Come membro dell'Orda, rafforzi il precario avamposto dell'Avamposto di Troncorotto con ogni anima salvata dalle tane corrotte della Valtetra settentrionale.",["race:Tauren"]="Come tauren, onori i legami con la Madre Terra e con l'Orda quando salvi un fratello cenariano e allevi la preoccupazione dei suoi cari all'Avamposto di Troncorotto."},sec={{t="Un druido in catene",b="Ruul Zoccolo Nevoso, un druido, è prigioniero nel Rifugio dei Mantocardo. Mentre esplorava i boschi corrotti della Valtetra settentrionale in forma d'orso, si è avvicinato troppo alla tana. I furbolg corrotti avevano perduto la loro saggezza ancestrale e, spinti da una paranoia ferina, lo hanno scambiato per una bestia comune. Invece di onorarlo, lo hanno rinchiuso in gabbia e affamato, prosciugando la sua magia finché non è più riuscito a liberarsi da solo."},{t="Fuga dall'Antro del Tirocinio",b="Dopo che la fame e la prigionia hanno indebolito Ruul, non può cambiare forma né farsi strada da solo nell'insediamento dei furbolg. Un alleato dell'Orda lo libera e apre un varco tra gli ostili Mantocardo. Quando raggiungono i confini dell'Avamposto di Troncorotto, Ruul assume per un breve momento la sua forma tauren e lo ringrazia di cuore. Poi torna nella natura selvaggia per riposare e riprendersi dalla stanchezza."}},faq={{q="Perché Ruul Zoccolo Nevoso è stato rinchiuso dai furbolg?",a="Ruul stava esplorando la foresta in forma d'orso quando i furbolg Mantocardo corrotti lo hanno scambiato per una bestia selvatica anziché per un druido. Lo hanno rinchiuso in gabbia e affamato finché non è stato troppo debole per fuggire.",al={"perché ruul è intrappolato","come è stato catturato ruul","perché è in gabbia"}},{q="Chi è Yama Zoccolo Nevoso?",a="Yama Zoccolo Nevoso è la sorella di Ruul e si trova all'Avamposto di Troncorotto, nella Valtetra. Si è molto preoccupata quando Ruul è scomparso nella foresta, giorni fa, senza fare ritorno.",al={"sorella di ruul","yama avamposto di troncorotto","chi è yama"}},{q="Perché Ruul non poteva semplicemente cambiare forma per scappare?",a="I furbolg Mantocardo hanno indebolito Ruul tenendolo prigioniero a lungo e affamandolo di proposito. Senza cibo né forze, ha esaurito la sua energia naturale ed è rimasto inerme finché qualcuno non lo ha salvato.",al={"perché ruul non ha cambiato forma","druido orso trappola"}},{q="Cosa succede dopo che Ruul raggiunge la salvezza?",a="Ai confini dell'Avamposto di Troncorotto, Ruul assume per un breve momento la sua forma tauren naturale per esprimere la propria gratitudine. Poi torna in forma d'orso e cerca un luogo tranquillo dove dormire e riprendersi.",al={"dove va ruul","finale di ruul"}},{q="Tutti i furbolg nella Valtetra sono ostili come i Mantocardo?",a="No. Molte tribù di furbolg hanno un nobile retaggio e profondi legami con la natura, ma i Mantocardo della Valtetra settentrionale sono caduti sotto influenze corruttrici che li hanno resi aggressivi e imprevedibili.",al={"i furbolg sono malvagi","corruzione dei mantocardo"}},{q="Dove ha luogo il salvataggio?",a="Ruul è prigioniero nel Rifugio dei Mantocardo, una tana di furbolg tra le colline a nord-ovest dell'Avamposto di Troncorotto e a nord di Astranaar, nella Valtetra.",al={"dove si trova ruul","posizione di ruul zoccolo nevoso"}}},fx={cd4f3bf3={q="Perché Ruul Zoccolo Nevoso ha bisogno che tu lo scorti invece di fuggire da solo?",a="Ruul è rimasto intrappolato per giorni in una gabbia dei Mantocardo, patendo la fame e la prigionia per mano dei furbolg corrotti. Le sue forze fisiche sono ormai quasi del tutto esaurite. Debole, malnutrito e intrappolato nelle profondità dell'ostile Rifugio dei Mantocardo, non può farsi strada da solo tra i membri della tribù e conta su di te per aprirsi un varco verso la libertà.",al={"perché ruul ha bisogno di aiuto","perché ruul non può fuggire da solo","perché io per ruul zoccolo nevoso"}}},fp="15,164,17.394.0,19.363.1,48.194.0,21.171.1,56.196.0,39.186.1,59.197.0,33.131.0"}
P.entries["quest:65"] = {n="The Defias Brotherhood",s="Da Guardiacolle, Gryan Stoutmantle ti manda a est, a Borgolago, dove un contatto potrebbe sapere dove si nasconde la Fratellanza dei Defias.",h="Da Guardiacolle, Gryan Stoutmantle ti manda a est, a Borgolago, dove un contatto potrebbe sapere dove si...",kw={"defias","gryan stoutmantle","borgolago","crestarossa","guardiacolle","marche occidentali","wiley lo scuro"},ang={["class:Rogue"]="Da furfante, sai che fare affidamento solo sui soldati non basta a smascherare un'organizzazione criminale. Stoutmantle si rivolge a chi conosce l'ombra e i favori di strada: Wiley lo Scuro.",["faction:Alliance"]="Da viaggiatore dell'Alleanza, attraversi le Marche Occidentali e raggiungi le Montagne Crestarossa, dove i territori periferici dipendono gli uni dagli altri mentre Roccavento li trascura."},sec={{t="La minaccia nella polvere",b="La People's Militia non riesce a scoprire chi dirige i banditi. Gryan Stoutmantle deve smascherare il circolo interno del cartello e il suo comandante prima di fermare i ladri."},{t="Un contatto fuori città",b="Wiley lo Scuro ti aspetta al piano superiore della locanda di Borgolago. Stoutmantle confida che i suoi legami con la malavita rivelino i nascondigli della Fratellanza. Non è ancora certo che Wiley possa darti una pista."}},faq={{q="Chi è Gryan Stoutmantle?",a="Gryan Stoutmantle guida la People's Militia, una forza di difesa improvvisata stanziata a Guardiacolle, nelle Marche Occidentali. Mentre Roccavento trascura le terre di confine, coordina la difesa dei pochi contadini e profughi rimasti lì.",al={"gryan stoutmantle","chi assegna questa missione","datore missione marche occidentali"}},{q="Perché Stoutmantle ti manda a Borgolago?",a="La People's Militia non ha informatori nella malavita delle Marche Occidentali. Gryan Stoutmantle riscuote un vecchio favore da Wiley lo Scuro, un furfante alla locanda di Borgolago, sperando che i suoi legami criminali rivelino chi guida i ladri.",al={"perché borgolago","perché andare a crestarossa","perché wiley"}},{q="Chi è Wiley lo Scuro?",a="Wiley lo Scuro è un furfante che alloggia al secondo piano della Lakeshire Inn, nelle Montagne Crestarossa. Deve un favore a Gryan Stoutmantle e potrebbe condividere voci sulla malavita e contatti criminali.",al={"chi è wiley","wiley borgolago","wiley lo scuro"}},{q="Cos'è la Fratellanza dei Defias?",a="Nelle Marche Occidentali, i ladri della Fratellanza dei Defias indossano bandane rosse e hanno occupato fattorie, strade e miniere abbandonate. Scacciano i coloni e sfidano l'autorità di Roccavento.",al={"fratellanza dei defias","cos'è la fratellanza dei defias","banditi bandana rossa"}},{q="Dove posso trovare Wiley a Borgolago?",a="Wiley lo Scuro è al piano superiore, al secondo piano della Lakeshire Inn, vicino al ponte nel borgo di Borgolago, nelle Montagne Crestarossa.",al={"dove si trova wiley","trova wiley","posizione di wiley"}},{q="Questa missione comporta dei combattimenti?",a="No. Viaggi da Guardiacolle, nelle Marche Occidentali, attraversi la Foresta di Elwynn e raggiungi la locanda di Borgolago per incontrare Wiley lo Scuro.",al={"questa missione è difficile","combattimento nella missione fratellanza dei defias","nemici"}}},fx={e3561313={q="Perché Gryan Stoutmantle ha bisogno di un avventuriero invece che della propria Milizia Popolare?",a="La Milizia Popolare di Gryan Stoutmantle è già impegnata al massimo nel difendere Guardiacolle e proteggere i pochi contadini rimasti nelle Marche Occidentali. Roccavento si rifiuta di inviare rinforzi reali, lasciando le difese locali disperatamente sguarnite. Inoltre, Stoutmantle ha bisogno proprio di un forestiero capace di infiltrarsi di nascosto, invece che di miliziani locali riconoscibili, che verrebbero individuati subito dalle vedette dei Defias.",al={"perché mandare me","perché non mandare la milizia","perché stoutmantle ha bisogno di un avventuriero"}}},fp="22,127,22.168.0,22.188.0,25.219.0,43.215.0,23.194.0,31.179.0,36.130.0,35.102.0"}
P.entries["quest:6503"] = {n="Staffette di Valtetra",s="A Valtetra, Kuray'bin manda l'Orda contro gli esploratori elfi della notte che partono di nascosto dall'Avamposto degli Alargentea. Raccolgono informazioni sugli accampamenti e sulle difese dell'Orda prima di poter fare rapporto.",h="A Valtetra, Kuray'bin manda l'Orda contro gli esploratori elfi della notte che partono di nascosto...",kw={"alleanza","valtetra","pattugliatori di valtetra","orda","kuray'bin","esploratori elfi della notte","avamposto degli alargentea"},ang={["class:Hunter"]="Da cacciatore, usi il tuo istinto affinato, i tuoi sensi acuti e la mira precisa per trovare i pattugliatori nascosti nel fitto dei boschi.",["class:Rogue"]="Da ladro, sfrutti contro di loro la furtività degli elfi della notte. Neutralizzando i loro pattugliatori, aiuti gli infiltrati dell'Orda a mantenere il controllo delle ombre della foresta.",["faction:Horde"]="Per l'Orda, ogni esploratore elfo della notte che abbatti aiuta a proteggere gli accampamenti locali e le attività di taglio del legname dai contrattacchi coordinati dell'Alleanza."},sec={{t="Occhi tra le fronde",b="Gli esploratori elfi della notte dell'Avamposto degli Alargentea si muovono nei boschi a est della loro base e a sud dei vicini possedimenti dell'Orda. Sorvegliano sentieri e crinali, mappano le fortificazioni e seguono gli spostamenti delle truppe.\n\nKuray'bin ha scoperto che questi esploratori, chiamati Pattugliatori di Valtetra, si sono addentrati nella natura selvaggia per raccogliere informazioni."},{t="Accecare l'Alleanza",b="L'Orda attacca gli esploratori nemici prima che possano tornare all'Avamposto degli Alargentea. Dare la caccia ai pattugliatori impedisce ai loro comandanti di scoprire la forza delle truppe dell'Orda e le difese dell'avamposto.\n\nSenza i loro occhi in avanscoperta, gli elfi della notte sono disorientati e meno propensi a rischiare manovre aggressive nei boschi contesi."}},faq={{q="Chi assegna la missione Pattugliatori di Valtetra?",a="Kuray'bin, coordinatore degli esploratori dell'Orda di stanza a Valtetra, dà l'ordine. Segue e contrasta gli spostamenti degli elfi della notte in tutta la foresta.",al={"datore di missione","chi assegna la missione","missione di kuray'bin"}},{q="Dove si trovano i Pattugliatori di Valtetra?",a="I pattugliatori perlustrano i boschi a est dell'Avamposto degli Alargentea e a sud dell'accampamento di Kuray'bin. Raccolgono informazioni tra il sottobosco.",al={"posizione dei pattugliatori","dove si trovano i pattugliatori","dove trovare i pattugliatori"}},{q="Perché i pattugliatori sono una minaccia per l'Orda?",a="I pattugliatori sono esploratori avanzati che operano dall'Avamposto degli Alargentea. Se mappano gli accampamenti dell'Orda e ne contano le truppe, l'Alleanza può pianificare incursioni mirate contro le posizioni vulnerabili.",al={"perché uccidere i pattugliatori","minaccia dei pattugliatori","scopo dei pattugliatori"}},{q="Cos'è l'Avamposto degli Alargentea?",a="L'Avamposto degli Alargentea è un'importante installazione militare degli elfi della notte a Valtetra. Le forze dell'Alleanza lo usano come base in prima linea per difendere la foresta e contrastare l'espansione dell'Orda.",al={"storia dell'avamposto degli alargentea","cos'è l'avamposto degli alargentea","alargentea alleanza"}},{q="Questa missione fa parte di una storia più lunga?",a="Questa operazione mira a ridurre le ricognizioni dell'Alleanza nella zona. I combattenti che aiutano Kuray'bin a mettere in sicurezza il perimetro ricevono una ricompensa.",al={"catena di missioni","missione successiva","catena dei pattugliatori"}},{q="I personaggi dell'Alleanza possono completare questa missione?",a="No. A Valtetra, Kuray'bin lavora solo per l'Orda sulle linee del fronte.",al={"è solo per l'orda","versione alleanza","l'alleanza può farla"}}},fx={["2873db73"]={q="Perché Kuray'bin vuole che gli Esploratori di Valtetra vengano uccisi?",a="Kuray'bin vuole accecare l'Alleanza e impedirle di sferrare un attacco organizzato sul territorio dell'Orda. Di recente gli esploratori si sono allontanati furtivamente dall'Avamposto degli Alargentea per aggirarsi vicino alle linee dell'Orda e, se riusciranno a mappare le difese e i movimenti delle truppe del tuo accampamento, è quasi certo che seguirà un'offensiva dell'Alleanza. Eliminarli impedisce al nemico di ottenere informazioni cruciali sul campo di battaglia.",al={"motivo di kuray'bin","perché uccidere gli esploratori"}},["884af179"]={q="Chi sono gli Esploratori di Valtetra?",a="Sono esploratori elfi della Notte inviati dalla vicina roccaforte dell'Alleanza, l'Avamposto degli Alargentea. Muovendosi sotto la fitta volta della foresta, queste agili avanguardie si avvicinano furtivamente ai confini dell'Orda per sorvegliare le fortificazioni, osservare i percorsi delle pattuglie e preparare il terreno per future incursioni dell'Alleanza.",al={"chi sono gli esploratori di valtetra","chi sono gli esploratori","bersaglio degli esploratori di valtetra"}}},fp="20,189,20.332.0,21.325.0,41.141.0,43.140.0,45.183.0,27.172.0,41.144.0,41.66.0"}
P.entries["quest:6504"] = {n="The Lost Pages",s="Una raffica ha sparso The Lost Pages per Valtetra, lasciando Gurda Sfregiarabbia bloccata vicino all'Avamposto di Troncorotto. Senza il manuale, non può usare lo sminuzzatore che trasporta da Porto Paranco al Campo di Taglio dei Cantaguerra.",h="Una raffica ha sparso The Lost Pages per Valtetra, lasciando Gurda Sfregiarabbia bloccata vicino...",kw={"valtetra","gurda sfregiarabbia","porto paranco","sminuzzatore","manuale operativo sminuzzatore","avamposto di troncorotto","the lost pages","campo di taglio dei cantaguerra"},ang={["faction:Horde"]="Come membro dell'Orda, sai che ogni sminuzzatore al Campo di Taglio dei Cantaguerra aiuta a raccogliere legname per mura, capanne e navi da guerra a Durotar.",["profession:Engineering"]="Da ingegnere, puoi capire il problema di Gurda. Usare uno sminuzzatore goblin senza le istruzioni del costruttore rischia di causare un guasto alla caldaia.",["race:Orc"]="Da orco, potresti condividere la frustrazione di Gurda per aver perso pagine tecniche. Il lavoro manuale e le tradizioni guerriere lasciano poca pazienza per la burocrazia goblin."},sec={{t="Una raffica di sfortuna",b="Il Clan Cantaguerra acquista sminuzzatori a vapore a Porto Paranco per tagliare legname in tutta Valtetra. Le loro delicate componenti possono essere difficili da padroneggiare per un guerriero orco. Mentre Gurda Sfregiarabbia trasportava a nord uno sminuzzatore appena acquistato, una raffica improvvisa le strappò di mano il libretto di istruzioni. Dodici fogli di pergamena si sparsero sul suolo della foresta."},{t="Pagine nella natura selvaggia",b="Il vento ha sparso le pagine del manuale per Valtetra. Creature erranti, cultisti e abitanti della foresta le hanno raccolte. Lo sminuzzatore non può funzionare senza tutti e tre i capitoli. Gurda è bloccata sulla strada per l'Avamposto di Troncorotto e non può presentarsi al lavoro di taglio."}},faq={{q="Chi è Gurda Sfregiarabbia?",a="Gurda Sfregiarabbia è una lavoratrice dell'Orda che trasporta uno sminuzzatore goblin da Porto Paranco a Valtetra per il lavoro di taglio del Campo di Taglio dei Cantaguerra.",al={"gurda","sfregiarabbia","chi assegna la missione"}},{q="Perché Gurda ha bisogno di un manuale di istruzioni per guidare lo sminuzzatore?",a="I macchinari goblin sono capricciosi e difficili da capire. Neanche un orco impaziente può usare lo sminuzzatore in sicurezza senza il manuale del costruttore.",al={"perché il manuale","perché non può guidarlo","manuale operativo sminuzzatore"}},{q="Come sono finite sparse le pagine del manuale per tutta Valtetra?",a="Una raffica violenta strappò il libro dalle mani di Gurda mentre viaggiava verso nord lungo la strada nella foresta. Le pagine sciolte si sparsero tra gli alberi, lasciandole soltanto la copertina vuota.",al={"come si sono perse le pagine","il vento ha soffiato via le pagine"}},{q="Dove deve andare lo sminuzzatore?",a="Lo sminuzzatore è diretto al Campo di Taglio dei Cantaguerra, dove l'Orda abbatte alberi per rifornire Orgrimmar e Durotar di legname.",al={"dove va lo sminuzzatore","destinazione sminuzzatore cantaguerra"}},{q="Dove si possono trovare le pagine mancanti?",a="Le pagine si sono sparse per Valtetra e sono state raccolte da umanoidi e abitanti ostili della foresta che vagano per la regione.",al={"dove trovare le pagine","chi lascia cadere le pagine"}},{q="Perché l'Orda compra macchinari a Porto Paranco?",a="Porto Paranco è il porto neutrale più vicino con collegamenti commerciali ai cartelli goblin. L'Orda vi acquista attrezzature ingegneristiche specializzate, strumenti da demolizione e veicoli a vapore per la logistica militare.",al={"macchinari goblin dell'orda","commercio dell'orda a porto paranco"}}},fx={["63589195"]={q="Perché Gurda Sfregiarabbia ha bisogno che tu trovi le pagine del manuale?",a="Gurda è bloccata sulla strada vicino all'Avamposto di Troncorotto con uno sfibratore goblin fermo che non sa usare. Le è stato affidato il compito di riportare la costosa macchina da Porto Paranco al Campo di Taglio dei Cantaguerra per prendere servizio. Senza il manuale non ha idea di come guidarla e abbandonare il veicolo nelle terre selvagge per cercare a piedi nella foresta lascerebbe incustodito un prezioso equipaggiamento dell'Orda.",al={"perché gurda ha bisogno di aiuto","perché gurda non può trovare le pagine","perché io per le pagine perdute"}}},fp="14,213,18.331.0,23.258.0,22.130.0,64.132.0,61.182.0,42.111.0,37.118.0,51.189.0"}
P.entries["quest:651"] = {n="Stones of Binding",s="Ad Arathi, quattro Stones of Binding tengono Myzrael sottoterra. Una voce proveniente dai frammenti iridescenti dice che la pietra più potente ha bisogno delle chiavi delle altre tre.",h="Ad Arathi, quattro Stones of Binding tengono Myzrael sottoterra.",kw={"altopiani d'arathi","chiave ardente","chiave burrascosa","frammenti iridescenti","myzrael","stone of inner binding","stones of binding","chiave tonante"},sec={{t="Quattro pietre",b="Ad Arathi, dice una voce, quattro pietre tengono Myzrael sottoterra. La Stone of Inner Binding è la più potente, e le chiavi delle Stones of West, East and Outer Binding possono aprirla. Raccogli la Chiave Ardente, la Chiave Burrascosa e la Chiave Tonante. Dei guardiani sorvegliano le pietre, ma qualcuno astuto o fortunato potrebbe trovare un modo per bandirli. Porta le chiavi alla Stone of Inner Binding."},{t="Presso la Inner Stone",b="La voce di Myzrael proviene dalla pietra. Le Stones of Binding sono aperte, i vincoli si stanno allentando e la libertà si avvicina. Myzrael ti acclama come un nobile salvatore."}},faq={{q="Da dove proviene questo passaggio?",a="Questo passaggio viene dopo Princess Trapped. La sua voce proviene dai frammenti iridescenti.",al={"datore missione stones of binding","chi assegna stones of binding","dove iniziare stones of binding"}},{q="Quali sono le quattro Stones of Binding?",a="Le quattro sono la Stone of West Binding, la Stone of East Binding, la Stone of Outer Binding e la più potente, la Stone of Inner Binding.",al={"quali stones of binding","stones of binding arathi","quattro pietre"}},{q="Quali chiavi sono necessarie per sbloccare la pietra interna?",a="La Chiave Ardente, la Chiave Burrascosa e la Chiave Tonante si raccolgono dalle Stones of West, East and Outer Binding.",al={"chiavi del vincolo","quali chiavi servono","chiavi per la stone of inner binding"}},{q="Chi sorveglia le pietre del vincolo?",a="Dei guardiani sorvegliano le pietre, anche se un avventuriero astuto o fortunato potrebbe trovare un modo per bandirli.",al={"guardiani delle pietre","chi sorveglia le pietre","protettori delle stones of binding"}},{q="Dove devono essere consegnate le chiavi?",a="Porta le chiavi alla pietra più potente, la Stone of Inner Binding. Va aperta prima che si aprano le altre.",al={"dove porto le chiavi","consegna stones of binding","posizione stone of inner binding"}}},fp="17,159,11.387.0,18.163.1,31.83.0,36.140.0,48.118.0,30.99.0,33.115.0"}
P.entries["quest:652"] = {n="Breaking the Keystone",s="La voce ha ora più libertà, anche se la Chiave di Pietra la tiene ancora legata. La Chiave di Pietra giace tra un cerchio di pietre, e Fozruk custodisce la chiave che i guardiani chiamano Verga dell'Ordine.",h="La voce ha ora più libertà, anche se la Chiave di Pietra la tiene ancora legata.",kw={"altopiani d'arathi","fozruk","chiave di pietra","verga dell'ordine","pietra del vincolo interiore","guardiano di pietra"},sec={{t="L'Ultimo Sigillo",b="Aprire le Stones of Binding ha alleviato la prigionia della voce, ma una serratura trattiene ancora la Chiave di Pietra. Giace tra il cerchio di pietre che ti circonda. Fozruk, un guardiano di pietra e uno dei suoi carcerieri, custodisce la chiave che i guardiani chiamano Verga dell'Ordine. Porta la verga alla Chiave di Pietra e apri la serratura. La voce promette una gratitudine che scuoterà la terra fin dalle radici. La Chiave di Pietra è colma di energia geomantica."},{t="Alla Chiave di Pietra",b="Quando inserisci la verga nella Chiave di Pietra, un tremito corre sotto di te."}},faq={{q="Cosa precede questa fase?",a="Le Stones of Binding vennero per prime. Aprirle ha alleviato gran parte della prigionia della voce.",al={"prerequisito","missione precedente","prerequisito stones of binding"}},{q="Chi è Fozruk?",a="Fozruk è un guardiano di pietra e uno dei carcerieri della voce. Custodisce la chiave della Chiave di Pietra.",al={"chi è fozruk","storia di fozruk","guardiano di pietra fozruk"}},{q="Cos'è la Verga dell'Ordine?",a="I guardiani chiamano la chiave della Chiave di Pietra Verga dell'Ordine. Fozruk la custodisce.",al={"verga dell'ordine","cos'è la verga dell'ordine","chiave della chiave di pietra"}},{q="Dov'è la Chiave di Pietra?",a="La Chiave di Pietra giace tra un cerchio di pietre negli Altopiani d'Arathi.",al={"dove si trova breaking the keystone","posizione chiave di pietra","cerchio pietroso arathi"}}},fp="21,170,13.399.0,15.66.1,28.85.0,14.91.0,25.82.0,22.67.0"}
P.entries["quest:6523"] = {n="Protect Kaya",s="Nelle Vette di Petrartiglio, Kaya Zoccolo Piatto è prigioniera dei tauren ostili dei Totem Truce. Gli avventurieri dell'Orda la guidano lungo sentieri pericolosi fino all'Accampamento Aparaje, poi avvisano il suo ansioso padre, Makaba Zoccolo Piatto, che è sopravvissuta.",h="Nelle Vette di Petrartiglio, Kaya Zoccolo Piatto è prigioniera dei tauren ostili dei Totem Truce.",kw={"accampamento aparaje","scorta","totem truce","kaya zoccolo piatto","makaba zoccolo piatto","protect kaya","vette di petrartiglio","tauren"},ang={["faction:Horde"]="Come membro dell'Orda, aiuti a proteggere le famiglie in viaggio e a rafforzare i presidi e le rotte di rifornimento dell'Orda nelle Vette di Petrartiglio.",["race:Tauren"]="Come tauren, aiuti una del tuo popolo, vittima dell'aggressività del clan dei Totem Truce."},sec={{t="Una prigioniera tra le vette",b="Kaya Zoccolo Piatto è stata catturata nel cuore del territorio dei Totem Truce, nelle Vette di Petrartiglio. I clan tauren sono divisi da aspre rivalità, e pochi suscitano un'ostilità maggiore dei Totem Truce. Kaya è riuscita a fuggire, ma i sentieri sorvegliati da nemici e predatori la separano ancora da un luogo sicuro. Una scorta armata è la sua migliore speranza per riuscire a passare."},{t="Fuga verso l'Accampamento Aparaje",b="Kaya punta all'Accampamento Aparaje, nella parte orientale delle Vette di Petrartiglio. Da lì conosce la strada di casa e può proseguire da sola. La guidi lungo sentieri dove incombe il pericolo di imboscate, aiutandola a evitare di essere catturata di nuovo mentre raggiunge un luogo sicuro."},{t="Il sollievo di un padre",b="Makaba Zoccolo Piatto aspetta vicino al confine sud-orientale delle Vette di Petrartiglio, temendo il peggio per la figlia scomparsa. Dei corrieri gli portano la notizia che Kaya ha raggiunto sana e salva l'Accampamento Aparaje. La disperazione di Makaba lascia il posto alla gratitudine per i campioni che hanno protetto sua figlia dai carcerieri."}},faq={{q="Chi è Kaya Zoccolo Piatto?",a="Kaya Zoccolo Piatto è una giovane tauren catturata dalle forze ostili dei Totem Truce nelle Vette di Petrartiglio. Per fuggire e raggiungere un luogo sicuro, dipende dagli avventurieri dell'Orda di passaggio.",al={"chi è kaya","lore di kaya zoccolo piatto","kaya"}},{q="Dove deve essere scortata Kaya?",a="Kaya ha bisogno di una scorta lungo i sentieri che portano all'Accampamento Aparaje, nella parte orientale delle Vette di Petrartiglio. Punta al campo, dove conosce la strada di casa.",al={"destinazione scorta kaya","dove portare kaya","dove va kaya"}},{q="Chi è Makaba Zoccolo Piatto?",a="Makaba Zoccolo Piatto è il padre di Kaya e aspetta ansiosamente vicino all'ingresso sud-orientale delle Vette di Petrartiglio. Teme per la figlia scomparsa finché gli avventurieri non gli portano la notizia che è stata salvata.",al={"chi è makaba","lore di makaba zoccolo piatto","padre di kaya"}},{q="Chi ha catturato Kaya?",a="I tauren ostili dei Totem Truce hanno catturato Kaya. I loro accampamenti e le loro imboscate si trovano tra le rupi di Petrartiglio.",al={"chi ha preso kaya","chi ha rapito kaya","rapitori di kaya"}},{q="Cosa succede dopo che Kaya raggiunge l'Accampamento Aparaje?",a="Quando Kaya raggiunge l'Accampamento Aparaje, può trovare da sola la strada di casa. Poi torni da Makaba Zoccolo Piatto per dargli la lieta notizia che è sopravvissuta.",al={"dopo protect kaya","cosa fare dopo la scorta","proseguimento protect kaya"}},{q="Questa missione è disponibile per i giocatori dell'Alleanza?",a="No. La famiglia Zoccolo Piatto è composta da tauren pacifici legati all'Orda, quindi solo gli avventurieri dell'Orda possono aiutare in questo salvataggio.",al={"l'alleanza può fare protect kaya","kaya è solo per l'orda"}}},fx={ee59f589={q="Perché Kaya Zoccolo Piatto ha bisogno della tua protezione?",a="Kaya è appena riuscita a liberarsi dai suoi carcerieri, ma è ancora intrappolata dietro le linee nemiche tra le montagne. Se i suoi carcerieri si accorgessero della fuga prima che raggiunga un luogo sicuro, verrebbe catturata di nuovo o uccisa. Raggiungere l'Accampamento Aparaje è la sua unica possibilità di mettersi al sicuro e mandare notizie a suo padre, Makaba, che teme il peggio per lei.",al={"perché proteggere kaya","motivo di kaya zoccolo piatto","perché kaya ha bisogno di una scorta"}},["87bb92ff"]={q="Perché Kaya Zoccolo Piatto non può fuggire da sola?",a="Kaya è debole, disarmata e completamente circondata dal territorio nemico. Senza un combattente capace di proteggerla dalle pattuglie in giro mentre fugge, non può percorrere in sicurezza la strada verso l'Accampamento Aparaje prima che venga scoperta la sua assenza.",al={"perché kaya ha bisogno di me","perché kaya non può andarsene da sola","perché serve una scorta"}}},fp="12,224,22.345.0,22.228.0,17.265.1,21.180.0,36.129.0,23.198.0,18.100.0,45.137.0,44.120.0"}
P.entries["quest:653"] = {n="Myzrael's Allies",s="Myzrael è libera, ma deve recuperare le forze prima di poter affrontare i suoi carcerieri. Ti considera un nobile alleato e ti manda da Gerrig Morsaossa, in un negozio nella Caverna degli Inganni di Forgiardente, perché lui sa come evocarla.",h="Myzrael è libera, ma deve recuperare le forze prima di poter affrontare i suoi carcerieri.",kw={"altopiani d'arathi","caverna degli inganni","gerrig morsaossa","giganti","forgiardente","pietra angolare","myzrael"},sec={{t="Libera di raccogliere le forze",b="Myzrael è libera, ma non è abbastanza forte da affrontare i suoi carcerieri. Ora la sopraffarebbero e la rinchiuderebbero di nuovo. Perciò recupererà le forze nascondendosi. Quando sarà pronta, intende affrontare i giganti e far loro rimpiangere il giorno in cui l'hanno tenuta prigioniera. Ti considera un nobile alleato e dice che avrà bisogno del tuo aiuto per evocarla in superficie."},{t="Parola per Gerrig Morsaossa",b="Myzrael ti manda da Gerrig Morsaossa, il cui negozio si trova nella Caverna degli Inganni di Forgiardente. Lui sa come evocarla."}},faq={{q="Dove si può trovare Gerrig Morsaossa?",a="Gerrig Morsaossa ha un negozio nella Caverna degli Inganni di Forgiardente.",al={"posizione gerrig morsaossa","dove si trova gerrig morsaossa","trovare gerrig morsaossa"}},{q="Perché Myzrael rimane nascosta?",a="Myzrael deve prima recuperare le forze. Se i suoi carcerieri la affrontassero ora, la sopraffarebbero e la imprigionerebbero di nuovo.",al={"perché myzrael si nasconde","dove sta andando myzrael"}},{q="Chi sono i carcerieri di cui parla Myzrael?",a="Myzrael si riferisce ai giganti che la tenevano sotto custodia. Dice che li affronterà a tempo debito e farà loro rimpiangere di averla tenuta prigioniera.",al={"carcerieri di myzrael","chi ha imprigionato myzrael","giganti di myzrael"}},{q="Perché Myzrael ti manda a Forgiardente?",a="Myzrael ti manda da Gerrig Morsaossa perché lui sa come evocarla. Quando sarà pronta, avrà bisogno del tuo aiuto per evocarla in superficie.",al={"perché andare a forgiardente","scopo della visita a gerrig"}}},fp="16,213,23.331.0,24.110.0,35.59.0,35.114.0,38.124.0,39.150.0"}
P.entries["quest:654"] = {n="Tanaris Field Sampling",s="La prova sul campo a Tanaris inizia quando accendi la fonte di energia del kit. Da allora hai due ore per raccogliere campioni.",h="La prova sul campo a Tanaris inizia quando accendi la fonte di energia del kit.",kw={"basilisco","segachiodi","kit di prova sul campo","meccania","iena","fonte di energia","scorpione","tanaris","compagnia dell'acqua"},sec={{t="Una Fonte di Energia Ticchettante",b="Il Capo Ingegnere Segachiodi si aspettava che il kit si illuminasse e vibrasse una volta attivata la fonte di energia. Ora hai due ore per raccogliere campioni accettabili da otto basilischi, otto iene e otto scorpioni nel deserto di Tanaris.\n\nSe il tempo scade, tutti i dati andranno perduti. Dovrai acquistare un'altra fonte di energia da Segachiodi, poi riportargli il kit a Meccania prima che si scarichi."},{t="Il Profitto della Compagnia",b="Segachiodi non mostra solidarietà quando un kit si scarica. Il profitto della Gadgetzan Water Company è tutto ciò che gli importa.\n\nContinuerà a vendere fonti di energia finché la compagnia non potrà permettersi di importare acqua dalle sorgenti ghiacciate di Dun Morogh."}},faq={{q="Quali creature devono essere campionate per il kit di prova?",a="Raccogli campioni accettabili da otto basilischi di Tanaris, otto iene e otto scorpioni.",al={"quali animali testare","obiettivi di campionamento","cosa devo uccidere"}},{q="Quanto tempo è disponibile per completare il campionamento?",a="Hai due ore dal momento in cui accendi la fonte di energia.",al={"limite di tempo","quanto tempo ho","timer"}},{q="Cosa succede se la fonte di energia si esaurisce?",a="Tutti i dati nel kit andranno perduti. Per ricominciare, acquista un'altra fonte di energia dal Capo Ingegnere Segachiodi a Meccania.",al={"se il timer scade","missione fallita","energia esaurita"}},{q="Dove va portato il kit di prova una volta pieno?",a="Riporta il kit completo per i test al Capo Ingegnere Segachiodi a Meccania prima che si scarichi.",al={"a chi devo consegnare","luogo di consegna","dov'è segachiodi"}},{q="Perché Segachiodi continua a vendere fonti di energia?",a="Segachiodi vuole che la Gadgetzan Water Company realizzi un profitto. Continuerà a vendere fonti di energia finché la compagnia non potrà permettersi di importare acqua dalle sorgenti ghiacciate di Dun Morogh.",al={"obiettivo di segachiodi","obiettivo della gadgetzan water company","perché campionare"}}},fp="22,120,22.403.0,20.237.0,54.89.0,52.67.0,42.120.0,40.99.0,49.164.0"}
P.entries["quest:6541"] = {n="Report to Kadrak",s="Al Crocevia, Thork invia a nord i combattenti più esperti dell'Orda, alla torre di guardia di Kadrak. L'orco prepara le reclute agli scontri che le attendono vicino al confine di Valtetra.",h="Al Crocevia, Thork invia a nord i combattenti più esperti dell'Orda, alla torre di guardia di Kadrak.",kw={"valtetra","savane","crocevia","kadrak","troncorotto","thork","torre di guardia","spiaggia di zoram"},ang={["faction:Horde"]="In quanto membro dell'Orda, passi dalla difesa dei territori abitati delle Savane alla conquista di risorse vitali nelle contese foreste del nord.",["race:Orc"]="In quanto orco, entri in un importante terreno di prova. Il legname di Valtetra può contribuire a fortificare Orgrimmar e a stabilire una dimora duratura su Kalimdor."},sec={{t="La Strada verso Nord",b="Il Crocevia deve affrontare verrospino, centauri e briganti locali. Oltre, l'Orda guarda alle fitte foreste di Valtetra. Thork invia alla torre sul confine settentrionale i combattenti che si sono dimostrati validi nelle Savane centrali, dove è di stanza Kadrak."},{t="Strategia di Frontiera",b="Kadrak sorveglia l'accesso meridionale a Valtetra e organizza rinforzi per il punto d'appoggio dell'Orda oltre il confine. L'Avamposto di Troncorotto e un avamposto lungo la Spiaggia di Zoram contribuiscono a rafforzare la presenza dell'Orda nei boschi ricchi di legname. Gli elfi della notte nativi oppongono una fiera resistenza."}},faq={{q="Chi è Thork?",a="Thork è un ufficiale orco al Crocevia, nelle Savane. Aiuta a organizzare la difesa locale e indirizza i combattenti promettenti verso campagne come l'avanzata a Valtetra.",al={"thork crocevia","chi assegna il rapporto a kadrak","thork savane"}},{q="Dove si trova Kadrak?",a="Kadrak si trova alla torre di guardia settentrionale nelle Savane, accanto alla strada principale che porta a Valtetra.",al={"posizione kadrak","dove si trova kadrak","torre di guardia kadrak"}},{q="Perché l'Orda avanza su Valtetra?",a="L'Orda cerca legname e altre risorse per costruire le sue nuove città a Durotar e nelle Savane. Il legname è fondamentale, ma cercarlo porta l'Orda a scontrarsi direttamente con gli elfi della notte.",al={"perché valtetra","orda a valterra","invasione valtetra"}},{q="Quali avamposti ha fondato l'Orda a Valtetra?",a="L'Orda ha fondato l'Avamposto di Troncorotto lungo la strada centrale di Valtetra e un altro avamposto più a ovest, sulla Spiaggia di Zoram.",al={"basi dell'orda a valterra","base spiaggia di zoram","troncorotto"}},{q="Cosa succede dopo aver fatto rapporto a Kadrak?",a="Dopo che avrai fatto rapporto a Kadrak, lui ti aggiornerà sulla situazione militare locale. Poi ti manderà a raccogliere rapporti dagli avamposti Warsong sparsi per Valtetra.",al={"dopo kadrak","prossima missione dopo kadrak","cosa assegna kadrak"}},{q="Puoi ricevere questo incarico da un luogo diverso dalle Savane?",a="Sì. I combattenti dell'Orda che operano da Malaka'jin, nelle Vette di Petrartiglio, ricevono una convocazione quasi identica per fare rapporto a Kadrak.",al={"missione alternativa kadrak","missione kadrak vette di petrartiglio"}}},fx={d049fa98={q="Perché Thork vuole che io riferisca a Kadrak?",a="L'Orda sta consolidando attivamente la propria presa su Valtetra e di recente ha fondato avamposti come quello sulla Spiaggia di Zoram. Thork sovrintende alla difesa di Crocevia, ma le linee del fronte a nord richiedono continuamente nuove reclute per proteggere questi territori appena conquistati. Indirizza i guerrieri capaci da Kadrak, che coordina la campagna dalla torre di guardia settentrionale e stabilisce dove servono maggiormente i rinforzi.",al={"perché riferire a kadrak","motivo di thork per riferire a kadrak","perché thork mi manda da kadrak"}}},fp="16,159,14.255.0,17.286.0,13.174.0,24.90.0,40.190.0,53.128.0,37.154.0,69.129.0"}
P.entries["quest:6542"] = {n="Fare rapporto a Kadrak",s="A Malaka'jin, Darn Morsartiglio invia guerrieri dell'Orda a nord, verso il posto di guardia di Kadrak. Il viaggio va dalle vette delle Vette di Petrartiglio a Valtetra, dove l'Orda tiene avamposti all'Avamposto di Troncorotto e alla Spiaggia di Zoram.",h="A Malaka'jin, Darn Morsartiglio invia guerrieri dell'Orda a nord, verso il posto di guardia di Kadrak.",kw={"valtetra","savane","darn morsartiglio","kadrak","troncorotto","vette di petrartiglio","rapporti cantaguerra","spiaggia di zoram"},ang={["faction:Horde"]="Come guerriero dell'Orda, partecipi allo sforzo bellico generale del Capoguerra. Lasci la frontiera per unirti alla lotta per le risorse di Valtetra.",["race:Orc"]="Come orco, entri in una campagna fondamentale per il clan dei Cantaguerra e la sopravvivenza di Durotar. Il posto di Kadrak è un terreno di prova per i giovani guerrieri orchi.",["race:Tauren"]="Come tauren, viaggi sotto la guida di vedette dell'Orda come Darn Morsartiglio. Aiutano i viaggiatori ad attraversare i confini montani e mantengono aperte le comunicazioni tra le terre di Bloodhoof e il fronte settentrionale del Capoguerra."},sec={{t="Una chiamata al fronte settentrionale",b="Darn Morsartiglio sorveglia le frontiere meridionali e montuose dell'Orda da Malaka'jin. L'orco invia i combattenti più capaci che passano per le Vette di Petrartiglio verso la torre di guardia delle Savane settentrionali. Valtetra è il punto di maggiore pressione. Lì le sentinelle elfo della notte si scontrano con i raccoglitori di legname dei Cantaguerra, e all'Orda servono combattenti mentre la lotta per la foresta continua."},{t="La guardia di Kadrak",b="Kadrak sovrintende agli spostamenti delle truppe dell'Orda da una torre di guardia nelle Savane settentrionali, dove la savana incontra Valtetra. L'Orda tiene avamposti alla Spiaggia di Zoram, a ovest, e all'Avamposto di Troncorotto, a nord. Kadrak coordina rifornimenti e truppe e invia rapporti urgenti attraverso la foresta contesa."}},faq={{q="Chi ti invia da Kadrak dalle Vette di Petrartiglio?",a="Darn Morsartiglio, un orco dell'avamposto dell'Orda di Malaka'jin nelle Vette di Petrartiglio, invia combattenti capaci verso il confine della foresta.",al={"datore di missione report to kadrak","chi inizia report to kadrak vette di petrartiglio","missione darn morsartiglio"}},{q="Dove si trova Kadrak?",a="Kadrak si trova alla torre di guardia settentrionale delle Savane, a guardia della strada principale che conduce a nord, verso Valtetra.",al={"posizione kadrak","dove si trova kadrak","trovare kadrak"}},{q="Perché l'Orda sta reclutando guerrieri per Valtetra?",a="All'Orda serve legname per sostenere Orgrimmar e mantiene posizioni fortificate alla Spiaggia di Zoram e all'Avamposto di Troncorotto. La resistenza degli elfi della notte spinge i comandanti a chiedere rinforzi per assicurarsi il territorio.",al={"perché andare a valtetra","campagna dell'orda a valtetra","perché combattere a valtetra"}},{q="Cosa succede dopo aver fatto rapporto a Kadrak?",a="Kadrak ti informa su Valtetra e ti affida rapporti da consegnare e ritirare negli avamposti contesi in The Warsong Reports.",al={"cosa fare dopo kadrak","i rapporti cantaguerra","missione successiva kadrak"}},{q="Questa missione è diversa dalla versione delle Savane?",a="Entrambi i dispacci ti mandano da Kadrak, al confine di Valtetra. Uno arriva dal Crocevia, nelle Savane, e l'altro dalle Vette di Petrartiglio. Entrambi conducono alla campagna di Valtetra.",al={"savane o vette di petrartiglio kadrak","due missioni report to kadrak","duplicato collegamento kadrak"}},{q="Cos'è la Spiaggia di Zoram menzionata nel briefing?",a="La Spiaggia di Zoram è una regione costiera nel nord-ovest di Valtetra, lungo il Mar Velato. L'Orda vi tiene un avamposto fortificato sulla spiaggia per sostenere gli spostamenti militari e assicurarsi l'accesso navale.",al={"cos'è la spiaggia di zoram","avamposto spiaggia di zoram","base spiaggia valtetra"}}},fx={f0da3cc6={q="Perché Darn Morsartiglio vuole che tu riferisca a Kadrak?",a="Di recente l'Orda ha fondato un avamposto sulla Spiaggia di Zoram, a Valtetra, e ha bisogno di reclute per difendere i nuovi fronti. Darn Morsartiglio, di stanza a Malaka'jin, indirizza gli avventurieri capaci da Kadrak, alla torre di guardia settentrionale delle Savane, per ricevere ulteriori ordini.",al={"perché darn mi manda da kadrak","motivo di darn morsartiglio","perché riferire a kadrak"}}},fp="16,210,28.358.0,14.304.0,40.135.0,24.98.0,51.199.0,39.129.0,49.188.0,51.187.0"}
P.entries["quest:6543"] = {n="I Rapporti dei Cantaguerra",s="I corrieri dalle Savane settentrionali portano gli ordini di Kadrak e raccolgono i Rapporti Cantaguerra in tutta Valtetra. Le loro osservazioni sul campo arrivano dai Predoni Cantaguerra vicino ad Azshara, all'Avamposto di Troncorotto e alla Spiaggia di Zoram.",h="I corrieri dalle Savane settentrionali portano gli ordini di Kadrak e raccolgono i Rapporti Cantaguerra in...",kw={"valtetra","savane","kadrak","avamposto di troncorotto","predone cantaguerra","rapporti cantaguerra","messaggero cantaguerra","esploratrice cantaguerra","spiaggia di zoram","avamposto di zoram'gar"},ang={["class:Hunter"]="Come cacciatore, metti alla prova le tue abilità di orientamento e sopravvivenza sulle pericolose strade di Valtetra, dove i predatori selvatici e gli arcieri elfi nascosti sono una minaccia.",["faction:Horde"]="Consegnare questi rapporti offre a un giovane guerriero dell'Orda un primo ruolo nella lotta contro gli Elfi della Notte nel Kalimdor settentrionale.",["race:Orc"]="Come orco, rendi onore al clan Cantaguerra e contribuisci a fornire il legname necessario per costruire Orgrimmar."},sec={{t="Logistica di Frontiera",b="Kadrak sorveglia da una torre fortificata il passo montano tra le Savane settentrionali e Valtetra. L'Orda ha bisogno di questa via perché le Savane non possono fornire il legname richiesto da Orgrimmar. Perciò il clan Cantaguerra si è spinto nell'antica foresta degli elfi per raggiungere quelle risorse. I corrieri portano gli ordini tra le pattuglie sparse e le aiutano a coordinarsi. Ma le imboscate degli Elfi della Notte minacciano i sentieri selvaggi."},{t="Occhi su Valtetra",b="Gli esploratori Cantaguerra sorvegliano tre zone di Valtetra. Sulla costa occidentale, un Messaggero Cantaguerra all'Avamposto di Zoram'gar tiene d'occhio l'attività dei naga e le altre minacce costiere lungo la Spiaggia di Zoram. All'Avamposto di Troncorotto, un'Esploratrice Cantaguerra coordina la difesa contro le incursioni delle Sentinelle. Più a est, un Predone Cantaguerra sorveglia la strada verso le rovine distrutte di Azshara. I loro rapporti offrono a Kadrak una panoramica degli spostamenti e delle debolezze degli Elfi della Notte lungo la frontiera."}},faq={{q="Dove inizia questa missione?",a="I rapporti partono da Kadrak, un ufficiale orco nella torre di guardia di legno che sorveglia il passo montano tra le Savane settentrionali e Valtetra meridionale.",al={"datore di missione","posizione di kadrak","chi fornisce i rapporti cantaguerra","dove iniziare"}},{q="Perché l'Orda spia Valtetra?",a="L'Orda cerca il fitto legname di Valtetra per costruire e rinforzare insediamenti come Orgrimmar. Gli Elfi della Notte difendono ferocemente i loro boschi sacri, quindi la ricognizione costante aiuta l'Orda a mantenere gli avamposti e le linee di rifornimento nel conflitto.",al={"perché valtetra","catasta di legno dei cantaguerra","conflitto di valtetra"}},{q="Dove si possono trovare i tre esploratori Cantaguerra?",a="Il Messaggero Cantaguerra si trova all'Avamposto di Zoram'gar, all'estremità nord-occidentale della Spiaggia di Zoram. L'Esploratrice Cantaguerra è all'Avamposto di Troncorotto, lungo la strada principale. Il Predone Cantaguerra pattuglia la strada orientale verso il confine di Azshara.",al={"posizioni degli esploratori","dove sono gli esploratori","posizione di predone messaggero ed esploratrice"}},{q="Chi sono i Predoni Cantaguerra?",a="I Predoni Cantaguerra sono esploratori e razziatori del clan degli orchi Cantaguerra. La loro cavalleria e le loro scaramucce aiutano l'Orda a espandersi, raccogliere legname e difendere il territorio nelle foreste di Valtetra.",al={"clan cantaguerra","chi sono i predoni cantaguerra","clan cantaguerra a valtetra"}},{q="Cosa succede dopo aver consegnato i rapporti?",a="Quando riceve i rapporti, Kadrak li usa per pianificare gli spostamenti delle truppe, rinforzare gli avamposti vulnerabili come Zoram'gar e Troncorotto e consolidare la presenza dell'Orda più in profondità nella foresta.",al={"consegna rapporti","prossima mossa","cosa fa kadrak"}},{q="La strada attraverso Valtetra è sicura per i corrieri di basso livello?",a="No. Le Sentinelle degli Elfi della Notte tendono spesso imboscate ai viaggiatori sulla strada principale di Valtetra. Anche i predatori, gli orsi e le pattuglie dell'Alleanza provenienti da insediamenti come Astranaar minacciano i corrieri.",al={"pericolo di valtetra","la strada è sicura","imboscate degli elfo della notte"}}},fx={["197774e3"]={q="Perché Kadrak vuole che vengano raccolti i rapporti?",a="Kadrak sorveglia il confine tra le Savane e le contese foreste di Valtetra. L'Orda cerca attivamente di estendere la propria presenza sotto la volta della foresta, ma marciare alla cieca nel territorio degli elfi della Notte porta al disastro. Kadrak ha inviato esploratori in ricognizione nelle profondità della regione per sorvegliare le attività nemiche e il terreno. Ha bisogno che questi aggiornamenti vengano consegnati e restituiti con urgenza, affinché i comandanti dell'Orda possano valutare con precisione la situazione tattica e coordinare le prossime mosse nella campagna in corso.",al={"motivo di kadrak","perché kadrak vuole i rapporti","perché raccogliere i rapporti dei cantaguerra"}},["649e115c"]={q="Che cos'è l'Aggiornamento dal Predone Cantaguerra?",a="L'Aggiornamento dal Predone Cantaguerra è un documento di intelligence tattica compilato dal predone dell'Orda che pattuglia le zone orientali di Valtetra, verso il confine con Azshara. Contiene osservazioni sugli spostamenti dell'Alleanza, sulle pattuglie delle Sentinelle e sulla geografia locale lungo questa via di comunicazione vitale, fornendo a Kadrak una panoramica del confine orientale necessaria per pianificare le manovre delle truppe.",al={"aggiornamenti dal predone cantaguerra","cos'è l'aggiornamento dal predone","rapporto del predone"}},f6b4d8ea={q="Che cos'è l'Aggiornamento dal Messaggero dei Cantaguerra?",a="L'Aggiornamento dal Messaggero dei Cantaguerra contiene informazioni di ricognizione raccolte ai margini occidentali della foresta, da una postazione presso l'Avamposto di Zoram'gar sulla Spiaggia di Zoram. Questo dispaccio descrive le minacce costiere, le forze ostili locali e gli approcci navali, informando Kadrak sulla sicurezza delle posizioni dell'Orda molto a ovest della strada principale.",al={"aggiornamenti dal messaggero dei cantaguerra","cos'è l'aggiornamento dal messaggero","rapporto del messaggero"}},["92e54885"]={q="Che cos'è l'Aggiornamento dall'Esploratore Cantaguerra?",a="L'Aggiornamento dall'Esploratore Cantaguerra è un rapporto strategico inviato dall'Avamposto di Troncorotto, la principale roccaforte dell'Orda nel centro di Valtetra. Compilato dall'esploratore avanzato di stanza lì, tiene traccia delle incursioni nemiche degli Elfi della Notte, delle scorte logistiche e della prontezza dell'avamposto a sostenere un'ulteriore espansione dell'Orda nelle terre selvagge circostanti.",al={"aggiornamenti dall'esploratore dei cantaguerra","cos'è l'aggiornamento dell'esploratore","rapporto dell'esploratore"}}},fp="19,205,18.410.0,21.421.0,30.150.0,37.236.0,44.214.0,30.179.0,41.195.0,58.169.0"}
P.entries["quest:6544"] = {n="L'assalto di Torek",s="All'Avamposto degli Alargentea, Torek guida un attacco contro gli Elfi della Notte. Inviato dall'Avamposto di Troncorotto, l'incursore orco vuole spezzare la resistenza delle Sentinelle e uccidere la loro comandante, Duriel Moonfire, nella guerra di confine di Valtetra.",h="All'Avamposto degli Alargentea, Torek guida un attacco contro gli Elfi della Notte.",kw={"valtetra","duriel moonfire","ertog zannacrudele","incursori","sentinelle","avamposto degli alargentea","avamposto di troncorotto","torek"},ang={["class:Warrior"]="Una brutale battaglia frontale mette alla prova la tua resistenza contro arcieri e maestri di spada delle Sentinelle, esperti nel combattimento.",["faction:Alliance"]="La caduta di Duriel Moonfire lascia l'Avamposto degli Alargentea esposto e minaccia gli antichi territori boschivi degli Elfi della Notte.",["faction:Horde"]="Per l'Orda, sfondare le difese dell'Avamposto degli Alargentea mette alla prova la tua forza e indebolisce il blocco degli Elfi della Notte attorno all'Avamposto di Troncorotto.",["race:NightElf"]="L'incursione colpisce il comando in prima linea delle Sentinelle e versa sangue elfico sotto le fronde di Valtetra."},sec={{t="Un attacco dall'ombra",b="In tutta Valtetra, i campi di taglialegna dell'Orda e gli Elfi della Notte nativi sono coinvolti in una guerra di confine sempre più aspra. Torek raduna incursori di Troncorotto appena fuori dall'Avamposto degli Alargentea, con l'obiettivo di spezzare le difese dell'Alleanza. Carica prima che gli Elfi della Notte possano contrattaccare o raccogliere le forze per una campagna di rinforzi contro l'Avamposto di Troncorotto."},{t="Prendere gli Alargentea",b="L'Avamposto degli Alargentea è una guarnigione boschiva presidiata dalle Sentinelle Alargentea e da fieri guerrieri elfici. Torek punta alla loro leader, Duriel Moonfire. Se cade, il comando locale degli Elfi della Notte rimane decapitato e gli incursori possono riferire la loro sanguinosa vittoria a Ertog Zannacrudele all'Avamposto di Troncorotto."}},faq={{q="Chi è Torek?",a="Torek è un incursore orco di stanza all'Avamposto di Troncorotto, a Valtetra. Fiero e impaziente di combattere, guida una banda contro le forze degli Elfi della Notte nella foresta.",al={"npc torek","chi è torek","orco torek"}},{q="Cos'è l'Avamposto degli Alargentea?",a="L'Avamposto degli Alargentea è un insediamento fortificato degli Elfi della Notte a Valtetra. Sentinelle d'élite e guerrieri lo sorvegliano, tenendo d'occhio i movimenti dell'Orda lungo i sentieri boschivi.",al={"avamposto degli alargentea","cos'è gli alargentea"}},{q="Chi è Duriel Moonfire?",a="Duriel Moonfire comanda gli Elfi della Notte che difendono l'Avamposto degli Alargentea. Guida le sue Sentinelle contro gli attacchi dell'Orda, finché gli incursori di Torek non irrompono nell'accampamento e la abbattono.",al={"duriel moonfire","duriel"}},{q="Chi è Ertog Zannacrudele?",a="Ertog Zannacrudele è un ufficiale dell'Orda all'Avamposto di Troncorotto. È il superiore di Torek, dirige le operazioni militari nella regione e riceve i resoconti delle vittorie contro l'Alleanza.",al={"ertog zannacrudele","ertog"}},{q="Perché l'Orda attacca l'Avamposto degli Alargentea?",a="L'Orda e gli Elfi della Notte combattono per il territorio in tutta Valtetra. Attaccando l'Avamposto degli Alargentea, l'Orda allevia la pressione sulle proprie linee di rifornimento e indebolisce le difese delle Sentinelle che proteggono le profondità della foresta.",al={"perché attaccare gli alargentea","conflitto di valtetra alargentea"}},{q="Dove si svolge questo attacco?",a="L'attacco comincia appena fuori dall'Avamposto degli Alargentea, sul lato orientale del Fiume Falfarren controllato dall'Orda, a Valtetra. Termina all'interno dell'accampamento degli Elfi della Notte.",al={"posizione assalto torek","dove si trova torek"}}},fx={["6e6dcd55"]={q="Perché Torek ha bisogno del mio aiuto per l'assalto?",a="Torek comanda già una squadra di razziatori di Troncorotto, ma i suoi esploratori riferiscono che l'Avamposto degli Alargentea è pesantemente fortificato e difeso da sentinelle e guerrieri esperti degli Elfi della Notte. Sapendo che i difensori non cederanno facilmente, accoglie volentieri un campione in forze che rinforzi la prima linea e assicuri che l'attacco contro Duriel Moonfire si concluda con una vittoria decisiva dell'Orda.",al={"perché torek ha bisogno di me","perché torek recluta il giocatore","perché aiutare torek"}}},fp="15,215,25.343.0,17.299.0,13.152.0,27.159.0,23.179.1,22.179.0,45.210.0,34.159.0"}
P.entries["quest:6545"] = {n="Aggiornamenti dal Messaggero dei Cantaguerra",s="In tutta Valtetra, Aggiornamenti dal Messaggero dei Cantaguerra avverte della crescente pressione sul confine del clan Cantaguerra. Il rapporto mette in guardia i comandanti dagli attacchi sempre più audaci dei naga agli avamposti dell'Orda.",h="In tutta Valtetra, Aggiornamenti dal Messaggero dei Cantaguerra avverte della crescente pressione sul confine...",kw={"valtetra","kadrak","mor'shan","naga","bastione","rapporto","messaggero","esploratore","cantaguerra"},ang={["faction:Horde"]="Lungo il confine della foresta, ogni soldato conta. Mantenere aperte le comunicazioni tra le Savane e gli avamposti avanzati è vitale per sopravvivere.",["race:Orc"]="Da orco, sai che il clan Cantaguerra dipende dalla tenacia e dalla vigilanza dei suoi messaggeri per mantenere il territorio conquistato sotto il comando del Capoguerra Thrall."},sec={{t="Dispacci dal fronte",b="In tutta Valtetra, gli esploratori e i messaggeri Cantaguerra sorvegliano gli scontri e tengono aperte le linee di rifornimento. Le sentinelle degli Elfi della Notte e la foresta rendono pericoloso il loro lavoro, perciò i comandanti di frontiera hanno bisogno di notizie in fretta. I corrieri portano dispacci alle guarnigioni remote e a comandanti come Kadrak, al Bastione di Mor'shan."},{t="La minaccia dei naga",b="I difensori dell'Orda si aspettano di trovare gli Elfi della Notte tra gli alberi, ma le sentinelle degli avamposti segnalano attacchi sempre più audaci dei naga. Gli invasori serpentini colpiscono dai corsi d'acqua e dalle antiche rovine, mettendo alla prova le barricate e allontanando i difensori dalle pattuglie nella foresta e lungo il confine. Un dispaccio al Bastione di Mor'shan avverte di questi assalti coordinati provenienti dall'acqua."}},faq={{q="A chi viene inviato il rapporto?",a="Il rapporto viene inviato a Kadrak, sovrintendente del Bastione di Mor'shan, tra Valtetra e le Savane settentrionali.",al={"chi riceve l'aggiornamento","rapporto di kadrak","dove va il rapporto"}},{q="Quali minacce sono menzionate nell'aggiornamento?",a="Lo scout riferisce di ripetuti assalti all'avamposto locale e di una minaccia crescente da parte dei naga ostili nelle acque vicine.",al={"cosa c'è nel rapporto","contenuto dell'aggiornamento del messaggero","attacchi dei naga"}},{q="Perché qui l'Orda si affida a messaggeri a piedi?",a="La vegetazione fitta, i tiratori scelti degli Elfi della Notte e gli avamposti isolati rendono il volo difficile o pericoloso in alcune zone di Valtetra. I messaggeri portano rapidamente i dispacci, senza farsi notare, lungo sentieri sorvegliati.",al={"perché i messaggeri","storia dei messaggeri cantaguerra","perché non le viverne"}},{q="Chi sono i messaggeri Cantaguerra?",a="I Messaggeri Cantaguerra sono esploratori, corrieri e combattenti d'avanguardia del clan Cantaguerra. Proteggono le linee di rifornimento e sorvegliano i movimenti nemici lungo i confini contesi della foresta.",al={"clan cantaguerra valtetra","chi sono i messaggeri cantaguerra"}},{q="Dove stanno attaccando i naga a Valtetra?",a="I naga attaccano da roccaforti ricavate nelle rovine lungo le coste e i laghi di Valtetra. Tendono imboscate ai viaggiatori e razziano gli accampamenti vicini.",al={"dove sono i naga","naga di valtetra"}},{q="Qual è lo scopo dell'avamposto in quest'area?",a="L'avamposto segnala il pericolo e costituisce un punto fermo per la difesa. Protegge le comunicazioni tra le segherie nel cuore della foresta e le Savane.",al={"perché c'è l'avamposto","scopo dell'accampamento dell'orda"}}},fx={["3fdffadb"]={q="Perché il Messaggero Cantaguerra ha bisogno che questo rapporto venga consegnato?",a="L'avamposto è sottoposto a una pressione crescente per via dei recenti assalti dei naga e il comando ha bisogno di un quadro preciso della prima linea. Il messaggero ha fatto la guardia e respinto diverse ondate di assalitori, ma Kadrak, al Bastione di Mor'shan, deve sapere quanto sia diventata pericolosa la situazione, affinché l'Orda possa coordinare le sue difese in tutta Valtetra.",al={"perché inviare il rapporto","motivo del messaggero","perché consegnare il rapporto dei cantaguerra"}},ae645a70={q="A cosa serve il Rapporto dei Cantaguerra?",a="Il Rapporto dei Cantaguerra contiene informazioni vitali dal campo sulle incursioni sempre più frequenti dei naga contro l'avamposto. Portarlo indietro informa Kadrak sulle difese attuali della prima linea e sulle necessità delle truppe, così che i comandanti dell'Orda siano aggiornati sulle minacce più recenti della regione.",al={"scopo del rapporto dei cantaguerra","cos'è il rapporto dei cantaguerra","cosa dice il rapporto"}},["0f7ad725"]={q="Perché il messaggero ti chiede di consegnare l'aggiornamento invece di andarci di persona?",a="La guarnigione dell'avamposto è già impegnata al massimo per respingere le incursioni dei naga. Essendo un corriere in forze che viaggia già tra le postazioni della prima linea, permetti ai difensori locali di restare ai loro posti, invece di abbandonare i bastioni per portare un messaggio fino al confine di The Barrens.",al={"perché io per il messaggero cantaguerra","perché non lo consegna lui stesso","perché il messaggero ha bisogno di me"}}},fp="21,178,20.299.0,15.325.0,32.115.0,41.113.0,45.185.0,28.168.0,42.118.0,43.139.0"}
P.entries["quest:6546"] = {n="Aggiornamenti dal Predone Cantaguerra",s="L'Aggiornamento dal Predone Cantaguerra porta notizie di un pericolo che incombe sull'Orda nella parte orientale di Valtetra. Il rapporto segnala forze dell'Alleanza, satiri trincerati nella foresta e naga in movimento nella vicina Azshara.",h="L'Aggiornamento dal Predone Cantaguerra porta notizie di un pericolo che incombe sull'Orda nella parte...",kw={"valtetra","azshara","kadrak","bastione di mor'shan","naga","satiri","predone cantaguerra","rapporto dei cantaguerra"},ang={["faction:Horde"]="Come membro dell'Orda, sai che ogni dispaccio lungo la linea di Mor'shan è fondamentale per la fragile posizione dell'Orda nelle foreste di Valtetra.",["race:Orc"]="Come orco, sai che il clan Warsong è fiero di presidiare l'avanguardia. I suoi esploratori sanno anche che il solo coraggio non può fermare i nemici che si avvicinano da ogni lato."},sec={{t="Occhi lungo il limitare della foresta",b="Un solitario Predone Cantaguerra sorveglia il conteso confine orientale di Valtetra. Le linee di rifornimento dell'Orda subiscono continue incursioni, perciò i predoni seguono i movimenti nemici prima che le bande d'incursori possano colpire il Bastione di Mor'shan o l'Avamposto di Troncorotto. Se ne incontri uno di pattuglia, sai che la foresta è sorvegliata. Il suo rapporto può decidere se una fortificazione dell'Orda resisterà o cadrà in un'imboscata."},{t="Minacce su ogni orizzonte",b="Il rapporto di un Predone Cantaguerra racconta dei pericoli nelle foreste centrali di Kalimdor. Gli Elfi della Notte e la più ampia Alleanza restano una minaccia, mentre astuti satiri demoniaci infestano la parte orientale di Valtetra. Gli esploratori hanno inoltre scoperto una massiccia presenza di naga che si diffonde nelle terre costiere in rovina della vicina Azshara. L'Orda affronta poteri ostili da quasi ogni direzione."}},faq={{q="Cos'è il Rapporto dei Cantaguerra?",a="Il Rapporto dei Cantaguerra è un dispaccio di intelligence di un Predone Cantaguerra sulle posizioni nemiche e i pericoli della regione. Segnala le forze dell'Alleanza nelle vicinanze, le congreghe di satiri attive nella parte orientale di Valtetra e i movimenti dei naga scoperti di recente ad Azshara.",al={"oggetto missione rapporto dei cantaguerra","cosa dice il rapporto","rapporto esploratore"}},{q="Chi è Kadrak?",a="Kadrak è un comandante dell'Orda di stanza al Bastione di Mor'shan, la barricata difensiva che protegge il confine settentrionale tra le Savane e Valtetra. Supervisiona gli esploratori in arrivo e coordina le operazioni avanzate nella foresta.",al={"chi è kadrak","dove si trova kadrak","consegna missione kadrak"}},{q="Perché vengono menzionati i naga ad Azshara?",a="Azshara confina con la parte orientale di Valtetra, e i movimenti dei naga potrebbero minacciare il fianco dell'Orda. I predoni sorvegliano le terre vicine, affinché l'Orda non venga colta di sorpresa da una massiccia incursione mentre affronta gli Elfi della Notte.",al={"collegamento naga azshara","perché menzionare azshara","minaccia naga azshara"}},{q="Cosa rende così pericolosa per l'Orda la parte orientale di Valtetra?",a="Nella parte orientale di Valtetra, l'Orda affronta distaccamenti attivi dell'Alleanza, antiche rovine colme di corruzione demoniaca e satiri, oltre a bestie selvatiche dei boschi. Corrieri e pattuglie rischiano imboscate da ogni direzione.",al={"perché valtetra orientale è pericolosa","minacce valtetra","minaccia satiri"}},{q="Chi sono i Predoni Cantaguerra?",a="I Predoni Cantaguerra sono l'avanguardia avanzata e la cavalleria da ricognizione del clan Warsong a Valtetra. Seguono i movimenti degli Elfi della Notte, proteggono i campi di taglio e mettono in sicurezza le rotte commerciali.",al={"cosa sono i predoni","esploratori cantaguerra","lore predoni"}},{q="Perché il predone non può consegnare il rapporto personalmente?",a="Il predone deve sorvegliare il sentiero e seguire i movimenti ostili mentre si sviluppano. Se lascia il suo punto d'osservazione, la prima linea potrebbe non accorgersi di un'avanzata improvvisa dell'Alleanza o dei satiri.",al={"perché consegno il rapporto","perché non lo consegna lui stesso"}}},fx={["43097ba7"]={q="Perché il Predone Cantaguerra ha bisogno che questo rapporto venga consegnato?",a="L'Orda affronta minacce su ogni fronte nella Valtetra orientale. Con l'Alleanza nelle vicinanze, i satiri che corrompono le foreste e i naga che conquistano territori oltre il confine, ad Azshara, Kadrak ha bisogno di informazioni immediate sui movimenti nemici. Consegnare questo rapporto permette ai comandanti dell'avamposto di comprendere i pericoli della regione e rinforzare le posizioni vulnerabili prima che i nemici attacchino.",al={"perché inviare il rapporto","motivo del predone cantaguerra","perché consegnare l'aggiornamento"}}},fp="23,211,26.359.0,24.362.0,27.246.0,14.226.0,38.207.0,56.206.0,30.182.0,50.176.0"}
P.entries["quest:6547"] = {n="Aggiornamenti dall'Esploratore dei Cantaguerra",s="Gli ordini di Kadrak raggiungono gli Aggiornamenti dall'Esploratore dei Cantaguerra mentre le vedette sorvegliano i boschi contesi. L'Orda si affida ai loro rapporti per difendere le proprie posizioni a Valtetra dagli attacchi degli Elfi della Notte.",h="Gli ordini di Kadrak raggiungono gli Aggiornamenti dall'Esploratore dei Cantaguerra mentre le vedette...",kw={"valtetra","savane","kadrak","elfi della notte","rapporto","esploratore","sentinelle","cantaguerra"},ang={["faction:Horde"]="Come membro dell'Orda, contribuisci a consolidare la sua posizione a Valtetra portando gli ordini di Kadrak agli esploratori più lontani, che affrontano le imboscate degli Elfi della Notte.",["race:NightElf"]="Come Elfo della Notte, consideri la presenza degli esploratori Cantaguerra ai confini una continua profanazione delle foreste sacre di Elune. Le Sentinelle si impegnano a scacciarli.",["race:Orc"]="Come orco, erediti la lotta del Clan Cantaguerra per il legname di Valtetra, contro la terra e i suoi antichi difensori."},sec={{t="Occhi nell'ombra",b="Kadrak si affida agli esploratori Cantaguerra sparsi lungo il confine di Valtetra. Le sentinelle degli Elfi della Notte sfruttano la foresta per nascondersi, e gli esploratori rischiano di rimanere isolati. I corrieri trasportano aggiornamenti scritti tra loro, mantenendo i presidi isolati in contatto con il comando dell'Orda e permettendo loro di riferire ciò che vedono."},{t="Tenere la posizione",b="Gli esploratori Cantaguerra sorvegliano la zona per individuare le incursioni degli Elfi della Notte, che vogliono riconquistare la foresta. Il clan ha pagato con molte vite ogni tratto di Valtetra che ha disboscato o occupato. Gli ordini di Kadrak mantengono gli esploratori avanzati in contatto con l'Orda e permettono loro di riferire se le difese resistono alla resistenza elfica."}},faq={{q="Chi è Kadrak?",a="Kadrak comanda le forze dell'Orda lungo il confine tra le Savane e Valtetra. Coordina le ricognizioni, la difesa del confine e i rifornimenti per le operazioni Cantaguerra nella foresta.",al={"kadrak","chi è kadrak","ruolo di kadrak"}},{q="Perché gli esploratori Cantaguerra sono così paranoici riguardo agli Elfi della Notte?",a="Gli Elfi della Notte sanno nascondersi nelle loro foreste ancestrali e sorprendere le pattuglie dell'Orda. Il Clan Cantaguerra disbosca e colonizza terre che gli elfi considerano sacre, esponendo i suoi esploratori ad attacchi improvvisi.",al={"perché temere gli elfi della notte","elfi della notte nell'ombra","pericolo elfico esploratore cantaguerra"}},{q="Perché si combatte per Valtetra?",a="L'Orda ha bisogno del legname e delle altre risorse di Valtetra per costruire Orgrimmar e rifornire gli insediamenti nelle Savane e a Durotar. Gli Elfi della Notte considerano sacra la foresta e combattono per scacciare i taglialegna e le guarnigioni degli orchi.",al={"perché combattere per valtetra","guerra di valtetra","conflitto tra orda e valtetra"}},{q="Qual è il ruolo del Clan Cantaguerra qui?",a="Il Clan Cantaguerra guida gli sforzi dell'Orda per impossessarsi delle risorse di Valtetra. Grom Hellscream li condusse nella foresta durante la Terza Guerra. Sono ancora saldamente insediati, gestiscono campi di legname e combattono contro le Sentinelle.",al={"clan cantaguerra valtetra","ruolo dei cantaguerra"}},{q="Dove va questo rapporto dopo aver raggiunto l'esploratore?",a="Dopo aver ricevuto le istruzioni di Kadrak, l'esploratore riferisce i successi locali contro i contrattacchi degli elfi. Così i capi dell'Orda restano informati sulla situazione al fronte.",al={"chi riceve il rapporto","rapporto kadrak","risultato aggiornamento esploratore"}},{q="A questo punto, i piani dell'Orda a Valtetra stanno avendo successo?",a="Gli esploratori in prima linea credono che le loro difese stiano reggendo. Mantengono le posizioni fortificate e respingono gli attacchi degli elfi, ma Valtetra resta contesa con ferocia e nessuna delle due parti ne ha il pieno controllo.",al={"l'orda sta vincendo a valtetra","progresso cantaguerra"}}},fx={aadbe711={q="Perché l'Esploratrice Cantaguerra vuole che tu lo faccia?",a="Gli esploratori Cantaguerra pattugliano le zone più profonde del territorio ostile di Valtetra, circondati da Elfi della Notte in agguato nell'ombra. L'esploratrice ha bisogno di nuovi ordini da Kadrak per coordinare la difesa della prima linea, mantenere la posizione conquistata a fatica nella foresta e comunicare se stanno riuscendo a respingere gli elfi.",al={"motivo dell'esploratore cantaguerra","perché consegnare il rapporto","perché l'esploratore ha bisogno di ordini"}},ae4f0954={q="A cosa serve il Rapporto dei Cantaguerra?",a="Il Rapporto dei Cantaguerra contiene direttive strategiche e disposizioni delle truppe inviate da Kadrak dal Bastione di Mor'shan. Per gli esploratori che presidiano avamposti isolati a Valtetra, ricevere questo rapporto significa restare aggiornati sulle manovre tattiche dell'Orda mentre difendono le rivendicazioni del clan dalle forze degli Elfi della Notte in agguato.",al={"scopo del rapporto dei cantaguerra","a cosa serve il rapporto dei cantaguerra","storia del rapporto dei cantaguerra"}},f7519c0a={q="Perché Kadrak ha bisogno di un avventuriero che consegni il rapporto?",a="Il confine tra The Barrens e Valtetra è pieno di imboscate. I fanti e le sentinelle di stanza al Bastione di Mor'shan non possono abbandonare facilmente i bastioni senza compromettere la difesa dell'avamposto; per questo un viaggiatore indipendente è il corriere ideale per attraversare i boschi e consegnare direttive militari riservate agli esploratori isolati.",al={"perché mandare a me il rapporto dei cantaguerra","perché le guardie non possono consegnarlo","perché io per l'esploratore cantaguerra"}}},fp="20,173,19.283.0,18.292.0,14.174.0,57.200.0,35.224.0,37.208.0,51.165.0,60.196.0"}
P.entries["quest:6548"] = {n="Avenge My Village",s="Makaba Zoccolo Piatto chiama i viaggiatori dell'Orda a rispondere all'assalto dei Totem Truce nel settore sud-orientale delle Vette di Petrartiglio. È scampato per un soffio, tagliato fuori dai suoi simili e circondato dai morti. Ora cerca vendetta nell'accampamento dei malviventi e dei mercenari assoldati.",h="Makaba Zoccolo Piatto chiama i viaggiatori dell'Orda a rispondere all'assalto dei Totem Truce nel settore...",kw={"avenge my village","totem truce","mercenario totem truce","malvivente totem truce","grundig darkcloud","makaba zoccolo piatto","vette di petrartiglio"},ang={["faction:Horde"]="Come membro dell'Orda, dipendi da passi aperti e sicuri tra le Savane e le Vette di Petrartiglio. Una banda ribelle dei Totem Truce che uccide viaggiatori e abitanti dei villaggi alleati minaccia le linee di rifornimento del Capoguerra attraverso le montagne.",["race:Tauren"]="Come tauren, vedi come il tradimento dei Totem Truce approfondisce la divisione tra gli shu'halo. Il massacro dei loro simili mostra il pericolo che rappresentano per il popolo unito di Cairne."},sec={{t="Sangue nei Crepacci",b="Vicino al confine delle Savane, Makaba Zoccolo Piatto è l'unico sopravvissuto a un massacro nei passi di pietra rossa delle Vette di Petrartiglio. I razziatori Totem Truce hanno colpito senza preavviso e hanno sterminato quasi tutti nel suo insediamento. Makaba ha reagito e ha abbattuto diversi aggressori. Poi lo hanno costretto a nascondersi, lasciandogli poco più della vita e della sua ira."},{t="La minaccia Totem Truce",b="I Totem Truce tormentano da tempo le tribù tauren unite sotto l'Alto Capotribù Cairne Zoccolo Sanguinario. A differenza dei pacifici nomadi di Mulgore, le loro bande guerriere si servono di malviventi spietati e mercenari opportunisti per conquistare territori e colpire insediamenti isolati. Ora Makaba non pensa alla diplomazia né ai legami tribali. Solo sangue ripagato col sangue può rispondere al suo dolore."}},faq={{q="Chi ha assegnato questa missione?",a="Makaba Zoccolo Piatto è un tauren sopravvissuto, accampato vicino al passo sud-orientale delle Vette di Petrartiglio. Il clan Totem Truce ha saccheggiato il suo villaggio lì vicino, e lui cerca vendetta contro i razziatori.",al={"datore di missione","makaba zoccolo piatto","chi è makaba"}},{q="Perché i Totem Truce attaccano altri tauren?",a="Il clan Totem Truce rifiuta l'unità sotto l'Orda e la visione di pace di Cairne Zoccolo Sanguinario. Ferocemente territoriali, xenofobi e aggressivi, razziano gli insediamenti rivali, uccidono gli stranieri e si servono di teppisti armati e mercenari assoldati per conquistare regioni come le Vette di Petrartiglio.",al={"perché i totem truce sono ostili","tauren che attaccano tauren","storia del clan totem truce"}},{q="Dove si trovano gli aggressori Totem Truce?",a="I malviventi e i mercenari Totem Truce sono accampati appena a ovest di Makaba Zoccolo Piatto, nel settore sud-orientale delle Vette di Petrartiglio, tra colline rocciose che dominano il passo.",al={"dove si trovano i nemici","posizione dell'accampamento totem truce","dove trovare i malviventi"}},{q="Chi sono i mercenari Totem Truce?",a="Il clan Totem Truce assolda combattenti spietati e mercenari per rafforzare le sue bande guerriere, terrorizzare gli insediamenti isolati e conquistarli.",al={"mercenari","mercenari totem truce","chi sono i mercenari"}},{q="Cosa succede dopo questa missione?",a="Dopo aver abbattuto i malviventi e i mercenari in prima linea, Makaba ti chiede di colpire il capo responsabile del massacro, Grundig Darkcloud.",al={"missione successiva","cosa segue avenge my village","kill grundig darkcloud"}},{q="Dove si trovava il villaggio di Makaba?",a="L'insediamento di Makaba era un accampamento tauren isolato vicino ai passi di confine del settore sud-orientale delle Vette di Petrartiglio. L'incursione dei Totem Truce lo ha spazzato via, lasciando Makaba tra i pochi sopravvissuti conosciuti.",al={"villaggio di zoccolo piatto","dove si trovava il villaggio","quale villaggio è stato distrutto"}}},fx={ee147ee3={q="Perché Makaba Zoccolo Piatto vuole che i Totem Truce vengano uccisi?",a="Makaba Zoccolo Piatto vuole vendicarsi dopo che il Clan Totem Truce ha lanciato una brutale incursione contro il suo villaggio, massacrando quasi tutti i suoi abitanti. Avendo perso la casa e la sua gente, ora è mosso soltanto dal desiderio di vendicarsi del clan che ha sterminato la sua famiglia e i suoi vicini.",al={"motivo di makaba zoccolo piatto","perché vendicare il villaggio","perché makaba vuole vendicarsi"}},["2ec07636"]={q="Chi stanno prendendo di mira i Totem Truce in questa zona?",a="Ti è stato affidato il compito di affrontare i bruti e i mercenari Totem Truce accampati a ovest. I Totem Truce sono un clan di tauren aggressivo e isolazionista, noto per l'ostilità verso le altre tribù e verso l'Orda; razziano gli insediamenti locali per ampliare la loro presenza nelle Vette di Petrartiglio.",al={"bruti e mercenari totem truce","chi devi uccidere","chi ha attaccato il villaggio di makaba"}},bd5303e7={q="Perché Makaba Zoccolo Piatto ha bisogno del tuo aiuto?",a="Makaba ha combattuto disperatamente durante l'incursione e ha ucciso quanti più Totem Truce poteva, ma è a malapena riuscito a salvarsi. Ferito, isolato e senza alleati né guardie del villaggio da radunare, non può affrontare da solo i razziatori rimasti.",al={"perché makaba non può combattere","perché chiedere a me","perché makaba ha bisogno di aiuto"}}},fp="17,241,18.334.0,20.358.0,20.193.0,45.262.0,42.140.0,34.132.0,30.138.1,35.187.0"}
P.entries["quest:655"] = {n="Requie del Martello",s="A Requie del Martello, l’Orda tiene un accampamento conquistato al prezzo della vita del Capoguerra Orgrim Martelfato. Gor'mul ricorda la fuga dei prigionieri e perché la roccaforte porta quel nome.",h="A Requie del Martello, l’Orda tiene un accampamento conquistato al prezzo della vita del Capoguerra Orgrim...",kw={"altopiani d'arathi","martelfato","gor'mul","requie del martello","campo di internamento","orgrim martelfato","thrall","tor'gan"},ang={["class:Warrior"]="Da guerriero, puoi ricordare Orgrim Martelfato come un combattente leggendario. Il terreno dove cadde porta ancora il peso di quella battaglia.",["faction:Horde"]="Per l’Orda, Requie del Martello ricorda la liberazione dei campi di internamento degli orchi e il sacrificio del Capoguerra Orgrim Martelfato.",["race:Orc"]="Per gli orchi, la caduta di Martelfato ad Arathi resta uno dei momenti più dolorosi della storia. Segnò la fine di un’era e l’ascesa della nuova Orda di Thrall."},sec={{t="Sangue e catene spezzate",b="Negli Altopiani d'Arathi, un tempo l’Alleanza teneva gli orchi prigionieri dietro legno e acciaio. Il giovane Thrall e il Capoguerra Orgrim Martelfato guidarono un assalto alle recinzioni del campo e liberarono i loro compagni. Molti prigionieri riuscirono a fuggire mentre le difese cedevano. Poi una lancia impugnata da un cavaliere a cavallo colpì Martelfato alle spalle. Morì nel luogo dove oggi sorge Requie del Martello."},{t="L'ombra persistente della sconfitta",b="Gor'mul era tra coloro che quel giorno non trovarono la libertà. Nel caos della battaglia e tra i tremori della terra, vide cadere il Capoguerra e perse la volontà di combattere. I suoi fratelli fuggirono, lasciandolo indietro. Per anni, Gor'mul vagò per gli Altopiani in preda al dolore. L’Orda ha riconquistato il luogo e ne ha fatto una base fortificata, ma i sopravvissuti portano ancora il ricordo della morte di Martelfato."}},faq={{q="Chi è Gor'mul?",a="Gor'mul era un orco prigioniero nel campo di internamento dove oggi sorge Requie del Martello. Thrall e Martelfato guidarono un assalto per liberare i prigionieri, ma Gor'mul rimase indietro durante la fuga. Vagò da solo, disperato, per anni.",al={"chi è gormul","storia di gor'mul","cosa è successo a gormul"}},{q="Come morì Orgrim Martelfato?",a="Orgrim Martelfato morì nella battaglia per liberare il campo di internamento degli Altopiani d'Arathi. Un cavaliere dell’Alleanza a cavallo lo colpì alle spalle con una lancia.",al={"come è morto martelfato","chi ha ucciso martelfato","la morte di martelfato"}},{q="Perché l'avamposto si chiama Requie del Martello?",a="Requie del Martello prende il nome dal Capoguerra Orgrim Martelfato, caduto lì mentre liberava il suo popolo dalla prigionia degli umani. L’Orda tornò al campo in rovina e ne fece una base permanente.",al={"perché si chiama requie del martello","origine del nome requie del martello","storia di requie del martello"}},{q="Chi è Tor'gan?",a="Tor'gan è un rappresentante dell’Orda stanziato a Requie del Martello. Si occupa dell’accampamento e comprende il trauma che ancora tormenta ex prigionieri come Gor'mul.",al={"chi è tor'gan","torgan requie del martello","missione di torgan"}},{q="Thrall partecipò alla battaglia combattuta qui?",a="Sì. Thrall combatté al fianco del Capoguerra Orgrim Martelfato nell’assalto al campo di internamento degli Altopiani d'Arathi. Insieme ne abbatterono le difese e liberarono gli orchi prigionieri, ma Martelfato morì nella battaglia.",al={"thrall e martelfato ad arathi","liberazione di requie del martello","thrall combatté a requie del martello"}},{q="Perché Gor'mul è così sconfortato?",a="Gor'mul vide cadere Martelfato e quella scena gli spezzò lo spirito. Quando gli altri prigionieri fuggirono nella natura selvaggia, Gor'mul rimase indietro e vagò senza speranza, finché l’Orda non tornò per costruire Requie del Martello.",al={"perché gormul è così triste","depressione di gormul","perché gormul ha perso la speranza"}}},fp="10,169,23.321.0,30.367.0,15.224.0,30.141.0,36.186.0,15.161.0,40.181.0,29.212.0"}
P.entries["quest:65593"] = {n="Hearts of the Lovers",s="Carendin Halgar cerca i cuori di Avelina Lilly e Isaac Pearson per attirare un incubo. Il loro amore reciproco li rende un’esca particolarmente potente.",h="Carendin Halgar cerca i cuori di Avelina Lilly e Isaac Pearson per attirare un incubo.",kw={"mulino d'ambra","avelina lilly","carendin halgar","cuori degli innamorati","incubo","isaac pearson","innamorati","porto paranco"},sec={{t="Una scelta divinatoria",b="Carendin Halgar cerca due cuori per il suo lavoro al Temple of the Damned. Le sue visioni indicano Avelina Lilly a Mulino d’Ambra e Isaac Pearson a Porto Paranco. Avelina cuce per i maghi caduti, mentre Isaac spera di farsi un nome nella città sul mare. Anche se lavorano lontani, entrambi sentono la mancanza dell’altro. Carendin ti chiede di portargli i loro cuori come esca per un incubo."},{t="I cuori",b="Carendin riceve i cuori di Avelina Lilly e Isaac Pearson. Ne tiene uno in ogni mano e li avvicina con delicatezza, poi dà degli idioti agli innamorati."}},faq={{q="Chi sono Avelina Lilly e Isaac Pearson?",a="Avelina Lilly cuce per i maghi caduti a Mulino d’Ambra, mentre Isaac Pearson spera di farsi un nome a Porto Paranco. I loro cuori anelano l’uno all’altra.",al={"avelina e isaac","chi sono gli innamorati"}},{q="Perché Carendin vuole i loro cuori?",a="Carendin dice che i cuori degli innamorati attirano un incubo e che il desiderio più profondo è l’esca più potente.",al={"cuori degli incubi","perché i cuori"}},{q="Dove si trovano i due innamorati?",a="Avelina Lilly si trova a Mulino d’Ambra, nella Selva Pinargento, mentre Isaac Pearson è a Porto Paranco, nelle Savane.",al={"dov’è avelina","dov’è isaac"}},{q="Chi è Carendin Halgar?",a="Carendin Halgar si trova al Temple of the Damned, dove ti chiede di portargli i cuori di Avelina e Isaac.",al={"carendin","temple of the damned"}}},fp="20,155,18.387.0,10.153.1,40.165.0,36.107.0,25.101.0,23.106.0"}
P.entries["quest:65597"] = {n="The Binding",s="Carendin Halgar, nel Magic Quarter di Sepulcra, ti chiede di usare i Lovers’ Hearts per evocare e soggiogare un incubo. Poi vuole che gli restituisca i cuori.",h="Carendin Halgar, nel Magic Quarter di Sepulcra, ti chiede di usare i Lovers’ Hearts per evocare e soggiogare...",kw={"carendin halgar","incubo","lovers’ hearts","magic quarter","evocazione","the binding","sepulcra"},sec={{t="Un’evocazione a Sepulcra",b="Carendin Halgar chiede il tuo aiuto nel Magic Quarter di Sepulcra. Dovrai usare i Lovers’ Hearts per evocare e soggiogare un incubo, poi riportarglieli. Al tuo ritorno, i cuori restano nelle mani di Carendin."}},faq={{q="Chi chiede aiuto?",a="Carendin Halgar, nel Magic Quarter di Sepulcra, ti chiede aiuto.",al={"chi li vuole","chi li ha dati","carendin halgar"}},{q="A cosa servono i Lovers’ Hearts?",a="Usi i Lovers’ Hearts per evocare e soggiogare un incubo.",al={"uso dei lovers’ hearts","a cosa servono i cuori","cuori per l’incubo"}},{q="Cosa succede dopo l’evocazione?",a="Riporti i Lovers’ Hearts a Carendin Halgar nel Magic Quarter.",al={"dove riportare i cuori","riportare i lovers’ hearts","cosa succede dopo"}}},fp="11,160,28.226.0,23.72.0,34.61.0,33.72.0"}
P.entries["quest:656"] = {n="Summoning the Princess",s="Ai Frammenti di Myzrael evochi Myzrael e la affronti prima che diventi abbastanza forte da sfidare i suoi carcerieri. Theldurin il Perduto vuole che venga sconfitta e che le sue Catene Oniriche siano legate ai Frammenti.",h="Ai Frammenti di Myzrael evochi Myzrael e la affronti prima che diventi abbastanza forte da sfidare i suoi...",kw={"altopiani d'arathi","catene oniriche","myzrael","pergamena di myzrael","frammenti di myzrael","theldurin il perduto"},sec={{t="Perché deve essere fermata",b="Theldurin teme che Myzrael diventi abbastanza forte da ribellarsi ai suoi carcerieri. Alcuni dicono che possa essere controllata. Ma Theldurin si chiede perché i giganti l'avrebbero incatenata, se fosse vero."},{t="Ai Frammenti",b="Porti la Pergamena di Myzrael ai Frammenti, dove le hai parlato per la prima volta, e la evochi. Dopo aver sconfitto Myzrael, leghi le sue Catene Oniriche ai Frammenti e la intrappoli di nuovo."},{t="Quando le catene vengono posizionate",b="Mentre le catene di Myzrael si sistemano attorno ai Frammenti, un lamento si leva da molto in basso, poi si sente un ruggito. I Frammenti non offrono più calore né sicurezza. Pulsano di minaccia, come se la cosa sotto di loro serbasse rancore verso la superficie."}},faq={{q="Chi ti manda a combattere contro Myzrael?",a="Theldurin il Perduto ti manda a sconfiggere Myzrael prima che diventi abbastanza forte da sfidare i suoi carcerieri.",al={"datore di missione","chi dà summoning the princess","missione di theldurin"}},{q="Dove avviene l'evocazione?",a="Evochi Myzrael ai Frammenti di Myzrael, dove le hai parlato per la prima volta.",al={"dove evocare myzrael","posizione frammenti di myzrael","luogo di evocazione"}},{q="Perché Theldurin vuole che Myzrael venga sconfitta?",a="Theldurin teme che Myzrael diventi abbastanza forte da sfidare i suoi carcerieri. Si chiede perché i giganti l'avrebbero incatenata, se davvero potesse essere controllata.",al={"perché uccidere myzrael","motivazione di theldurin","perché evocarla"}},{q="Come viene evocata Myzrael?",a="Evochi Myzrael ai Frammenti di Myzrael con la Pergamena di Myzrael.",al={"come evocarla","uso della pergamena di myzrael","processo di evocazione"}},{q="Cosa fai con le Catene Oniriche?",a="Dopo aver sconfitto Myzrael, leghi le sue Catene Oniriche ai Frammenti e la intrappoli di nuovo.",al={"quale oggetto serve","catene oniriche","catene di myzrael"}}},fp="22,199,23.184.0,13.188.0,28.226.1,31.105.0,36.76.0,41.142.0,24.71.0,42.89.0"}
P.entries["quest:65601"] = {n="Love Hurts",s="Gan'rul ti manda lungo la via principale di Orgrimmar a cercare Magar. Il suo desiderio per Krilge potrebbe rivelare l'oggetto che serve a Gan'rul per attirare un incubo nel mondo.",h="Gan'rul ti manda lungo la via principale di Orgrimmar a cercare Magar.",kw={"spelonca delle ombre","gan'rul","incubo","krilge","l'amore fa male","magar","orgrimmar","sayaad"},sec={{t="La ricerca di Magar",b="A est della Spelonca delle Ombre, Magar attende con nostalgia il ritorno di Krilge. Ti chiede di cercare qualcosa di prezioso. Porta quell'oggetto a Gan'rul, che ha bisogno di un pegno d'amore e devozione per evocare un incubo."}},faq={{q="Chi è Magar?",a="Magar vive lungo la via principale di Orgrimmar e attende con nostalgia il ritorno di Krilge.",al={"chi è magar"}},{q="Chi è Krilge?",a="Krilge è la compagna di Magar, che ne attende con nostalgia il ritorno.",al={"chi è krilge","compagna di magar"}},{q="Che cos'è un incubo?",a="Un incubo è un sayaad maschio, profondamente malvagio e ossessionato da un unico scopo.",al={"significato di incubo","sayaad maschio"}},{q="Di cosa ha bisogno Gan'rul?",a="Gan'rul ha bisogno di un oggetto che rappresenti un grande amore e una profonda devozione per attirare un incubo nel mondo.",al={"di cosa ha bisogno gan'rul","oggetto per evocare un incubo"}},{q="Dove posso trovare Magar?",a="Magar vive a est della Spelonca delle Ombre, lungo la via principale di Orgrimmar.",al={"luogo in cui si trova magar","dove si trova magar"}}},fp="10,154,14.199.0,13.71.0,14.60.0,19.63.0,23.98.0,23.68.0"}
P.entries["quest:65602"] = {n="What Is Love?",s="Gakin il Vincolaombre cerca una statuetta di legno, la cui età e storia la rendono adatta a un rituale per evocare un incubo. La sua devozione potrebbe attirare la creatura.",h="Gakin il Vincolaombre cerca una statuetta di legno, la cui età e storia la rendono adatta a un rituale per...",kw={"valtetra","gakin il vincolaombre","incubo","accampamento di maestra","rituale","roccavento","che cos'è l'amore","statuetta di legno"},sec={{t="Un vecchio ricordo",b="Gakin il Vincolaombre ha individuato una statuetta con la sua chiaroveggenza. Dice che appartenne a una giovane coppia migliaia di anni fa e che i proprietari non ci sono più. Ti chiede di portare il ricordo da una casa oltre l'Accampamento di Maestra a Valtetra fino a Gakin, nel Quartiere dei Maghi di Roccavento."},{t="Il potere della statuetta",b="Quando gli riporti la statuetta di legno, Gakin percepisce che la sua forza emotiva è ancora intensa, nonostante il passare del tempo. Dice che attirerà l'incubo e sarà il reagente di cui ha bisogno per il rituale."}},faq={{q="Che cosa vuole che trovi Gakin?",a="Gakin ti chiede di recuperare una statuetta di legno che, secondo lui, attirerà un incubo al suo rituale.",al={"quale statuetta","statuetta di legno","oggetto di gakin"}},{q="Dov'è la statuetta?",a="Gakin dice che si trova in una casa oltre l'Accampamento di Maestra a Valtetra.",al={"posizione della statuetta","dov'è","casa a valtetra"}},{q="A chi apparteneva la statuetta?",a="La statuetta apparteneva a una giovane coppia, migliaia di anni fa.",al={"vecchi proprietari","statuetta della coppia","chi l'aveva"}},{q="Perché Gakin vuole la statuetta?",a="Gakin percepisce energia emotiva nella statuetta e dice che attirerà un incubo per il suo rituale.",al={"perché la statuetta","reagente per l'incubo","a cosa serve"}}},fp="13,143,15.275.0,20.201.1,32.97.0,22.63.0,23.63.0,33.97.0"}
P.entries["quest:65603"] = {n="The Binding",s="Gakin il Vincolaombre ti chiede di usare una statuetta di legno nelle cripte e affrontare un incubo. Il tuo successo determinerà se potrà insegnarti a invocare il demone.",h="Gakin il Vincolaombre ti chiede di usare una statuetta di legno nelle cripte e affrontare un incubo.",kw={"cripte","gakin il vincolaombre","incubo","invocazione","sayaad","cerchio di evocazione","the binding","statuetta di legno"},ang={["class:Warlock"]="Da stregone, affronti la prova di Gakin per vincolare un sayaad e imparare un'invocazione che richiama l'incubo."},sec={{t="Una prova nelle cripte",b="Gakin il Vincolaombre ha preparato un cerchio di evocazione nelle cripte sotto lo Slaughtered Lamb. Poni una statuetta di legno al centro per aprire un varco a un incubo, un demone sayaad. Potrebbe cercare di sedurti, ma Gakin ti avverte che ogni sua offerta è falsa. Se fallisci, la tua anima è in pericolo."},{t="La lezione del vincolo",b="Dopo aver sconfitto l'incubo, Gakin loda la tua volontà incrollabile. Dice che molti stregoni che tentano di vincolare un sayaad finiscono per diventare il suo pasto. Poi ti insegna l'invocazione per richiamare l'incubo che hai vincolato."}},faq={{q="Cosa vuole che faccia Gakin?",a="Gakin ti chiede di usare una statuetta di legno presso il cerchio di evocazione nelle cripte, sottomettere l'incubo e riportargli la statuetta.",al={"cosa devo fare","compito della statuetta","evocare un incubo"}},{q="Dov'è il cerchio di evocazione?",a="Gakin dice che il cerchio di evocazione si trova nelle cripte sotto lo Slaughtered Lamb.",al={"dove lo evoco","cerchio nelle cripte","sotto il lamb"}},{q="Cos'è un sayaad?",a="Un sayaad è un demone, e Gakin ti avverte di non sottovalutarlo.",al={"demone sayaad","che tipo di demone","tipo di incubo"}},{q="Perché dovrei diffidare dell'incubo?",a="Gakin ti avverte che l'incubo potrebbe ricorrere alla seduzione e all'inganno, e che ogni sua offerta è falsa.",al={"posso fidarmi","inganno dell'incubo","cosa offrirà"}},{q="Cosa mi insegna Gakin dopo la prova?",a="Dopo aver sconfitto l'incubo, Gakin ti insegna l'invocazione per richiamare il demone che hai vincolato.",al={"cosa succede dopo","lezione del vincolo","invocazione dell'incubo"}}},fp="11,159,21.294.0,18.210.1,30.130.0,30.76.0,17.75.0,34.101.0,38.99.0"}
P.entries["quest:65604"] = {n="The Binding",s="Gan'rul Bloodeye ti manda a evocare un incubus con la Withered Scarf e a soggiogarlo. Il vincolo mette alla prova la tua padronanza del fascino e del potere di un demone.",h="Gan'rul Bloodeye ti manda a evocare un incubus con la Withered Scarf e a soggiogarlo.",kw={"gan'rul bloodeye","incubus","magar","tenda di neeru","sayaad","cerchio di evocazione","the binding","withered scarf"},ang={["class:Warlock"]="In quanto stregone, devi dimostrare di saper evocare e soggiogare un incubus. Gan'rul ti avverte che i demoni possono rivoltare il loro fascino contro di te."},sec={{t="Al cerchio",b="Gan'rul Bloodeye legge l'amore nei fili della Withered Scarf e crede che attirerà un incubus. Nella tenda di Neeru a Orgrimmar, devi usarla al cerchio di evocazione e dimostrare il tuo dominio sul demone. Gan'rul ti avverte che un incubus non si arrenderà senza opporre resistenza e ti chiede di riportargli la sciarpa dopo averlo soggiogato."},{t="La sciarpa restituita",b="Gan'rul riceve la sciarpa dopo che l'incubus è stato soggiogato. Dice che ti insegnerà a evocare il demone e a riportare la sciarpa a Magar. Il tessuto gli ricorda che gli stregoni possono brandire l'oscurità demoniaca, ma non devono mai lasciarsi dominare dai demoni."}},faq={{q="Chi ti affida The Binding?",a="Gan'rul Bloodeye ti affida la Withered Scarf e ti chiede di evocare e soggiogare un incubus.",al={"chi è gan'rul","gan'rul vincolo","chi consegna la sciarpa"}},{q="A cosa serve la Withered Scarf?",a="Gan'rul percepisce l'amore intrecciato nei fili della sciarpa e crede che attirerà un incubus.",al={"a cosa serve la sciarpa","withered scarf","perché la sciarpa"}},{q="Dov'è il cerchio di evocazione?",a="Il cerchio di evocazione si trova nella tenda di Neeru a Orgrimmar.",al={"cerchio incubus","dove evocare","tenda di neeru"}},{q="Cos'è un incubus?",a="Un incubus è un sayaad. Gan'rul avverte che i sayaad dominano le menti e torturano le anime, e che un incubus può ammaliare la sua preda.",al={"significato di incubus","sayaad","che demone"}},{q="Cosa ti chiede di fare Gan'rul?",a="Gan'rul ti chiede di evocare un incubus con la Withered Scarf, soggiogarlo e riportargli la sciarpa.",al={"compito del vincolo","cosa devo fare","vincolo dell'incubus"}}},fp="11,148,13.325.0,18.231.1,26.91.0,32.88.0,30.53.0,19.123.0,32.102.0"}
P.entries["quest:6561"] = {n="Blackfathom Villainy",s="Negli Abissi di Fondocupo, un esploratore ferito chiede aiuto contro il culto al servizio di Aku'mai. L'esploratore dell'Alba d'Argento Thaelrid chiede ai campioni dell'Orda di passaggio di porre fine ai sacrifici di sangue del Signore del Crepuscolo Kelris nelle rovine sommerse.",h="Negli Abissi di Fondocupo, un esploratore ferito chiede aiuto contro il culto al servizio di Aku'mai.",kw={"aku'mai","alba d'argento","bashana totem runico","abissi di fondocupo","blackfathom villainy","kelris","pozzo della luna","thaelrid","signore del crepuscolo kelris","martello del crepuscolo"},ang={["class:Druid"]="Per un druido, la profanazione di un antico Pozzo della Luna degli Elfi della Notte da parte dei naga e dei cultisti che adorano il Vuoto ferisce il santuario naturale e spirituale di Kalimdor.",["class:Shaman"]="Per uno sciamano, Kelris e Aku'mai turbano l'equilibrio degli elementi, trasformando pure acque sotterranee in un luogo di ombre e sacrifici.",["faction:Horde"]="Per l'Orda, unirsi a un esploratore dell'Alba d'Argento è un insolito gesto di intenti comuni contro una piaga cosmica. Così ci si guadagna il favore dell'Alba.",["race:Tauren"]="Bashana Totem Runico considera la sconfitta di Kelris una difesa della Madre Terra. Così viene purificata un'abominazione che voleva spingere l'ordine naturale del mondo nel caos primordiale."},sec={{t="Un'ultima resistenza disperata",b="L'esploratore dell'Alba d'Argento Thaelrid giace ferito nel tempio sotterraneo lungo la costa di Valtetra. La sua ricognizione ha svelato orrori ben peggiori delle incursioni dei naga, ma ha esaurito le forze e non può portare a termine la missione da solo. Così chiede ai campioni dell'Orda di passaggio di colpire i capi del culto nelle sale sommerse."},{t="Sacrifici negli abissi",b="Il Signore del Crepuscolo Kelris guida i cultisti del Martello del Crepuscolo nel Temple of the Moon in rovina. Insieme ai naga del luogo, celebra riti oscuri sul Pozzo della Luna profanato. I prigionieri vengono dati in pasto vivi ad Aku'mai, un'idra famelica e bestia degli Dei Antichi. Kelris brama il potere cosmico e il caos primordiale."},{t="Notizie per Picco del Tuono",b="L'Alba d'Argento credeva che Kelris fosse morto o disperso, perciò è importante sapere che fine abbia fatto. Thaelrid affida la prova della morte del capo del culto a Bashana Totem Runico, sull'Altura degli Anziani a Picco del Tuono. In sintonia con l'equilibrio naturale della Madre Terra, Bashana onora la vittoria su una corruzione decisa a trascinare Kalimdor nella rovina primordiale."}},faq={{q="Chi è il Signore del Crepuscolo Kelris?",a="Il Signore del Crepuscolo Kelris guida i cultisti del Martello del Crepuscolo negli Abissi di Fondocupo. L'Alba d'Argento lo credeva morto o disperso, ma ha accumulato potere sacrificando prigionieri all'antica idra Aku'mai nel Pozzo della Luna corrotto.",al={"kelris","chi è kelris","signore del crepuscolo kelris"}},{q="Perché un membro dell'Alba d'Argento si trova all'interno degli Abissi di Fondocupo?",a="L'esploratore dell'Alba d'Argento Thaelrid è entrato nel tempio degli Elfi della Notte in rovina per indagare sulla minaccia crescente. I pericoli del luogo lo hanno ridotto in fin di vita e intrappolato, così deve affidarsi agli avventurieri di passaggio perché portino a termine il suo compito e uccidano Kelris.",al={"argent guard thaelrid","perché thaelrid è qui","alba d'argento negli abissi di fondocupo"}},{q="Che cos'è Aku'mai?",a="Aku'mai è un'antica idra dalle molte teste, considerata una servitrice primordiale degli Dei Antichi. Si è risvegliata quando la corruzione proveniente dalle profondità della terra ha contaminato le acque sacre del tempio. Ora divora i prigionieri condotti lì dal Martello del Crepuscolo.",al={"akumai","chi è akumai","storia di aku'mai"}},{q="Perché consegnare la missione a Bashana Totem Runico?",a="Thaelrid invia i campioni dell'Orda da Bashana Totem Runico, sull'Altura degli Anziani a Picco del Tuono. Custode dell'equilibrio della Madre Terra, Bashana resta in contatto con chi combatte il male antico e considera il culto degli Dei Antichi di Kelris una piaga per Kalimdor.",al={"bashana totem runico","perché picco del tuono","dove consegnare blackfathom villainy"}},{q="Cosa è successo alle rovine degli Abissi di Fondocupo?",a="Gli Abissi di Fondocupo erano un tempo un tempio sotterraneo sacro alla dea della luna Elune. Sconvolgimenti e antiche tenebre che filtravano dalla terra contaminarono il grande Pozzo della Luna. Naga e cultisti dell'apocalisse si impadronirono dei santuari sommersi per il loro oscuro padrone, Aku'mai.",al={"storia degli abissi di fondocupo","rovine del tempio di elune","perché gli abissi di fondocupo sono corrotti"}},{q="Qual è l'obiettivo del Martello del Crepuscolo in questo luogo?",a="Il Martello del Crepuscolo vuole riportare il mondo al caos primordiale adorando gli Dei Antichi. Kelris cerca potere attraverso un'unione oscura e dà in pasto gli innocenti agli abissi per guadagnarsi il favore di esseri antichi.",al={"motivi del martello del crepuscolo","perché il culto negli abissi di fondocupo","obiettivi di kelris"}}},fx={["8c6f2eb7"]={q="Perché Argent Guard Thaelrid vuole che il Signore del Crepuscolo Kelris venga ucciso?",a="Il Signore del Crepuscolo Kelris e i suoi cultisti del Martello del Crepuscolo stanno sacrificando prigionieri innocenti ad Aku'mai, un ripugnante servitore degli Antichi Dei, in cambio di potere oscuro. Thaelrid è stato inviato dall'Alba d'Argento per porre fine a questi orrori e non può permettere che le depravazioni e il culto caotico della setta continuino impuniti.",al={"motivo di thaelrid","perché thaelrid vuole kelris morto","perché uccidere kelris"}},f2efcdf9={q="Perché Thaelrid ha bisogno del tuo aiuto invece di fermare Kelris da solo?",a="Thaelrid è rimasto gravemente ferito nelle profondità del tempio sommerso. Indebolito, esausto e completamente privo di forze, non può affrontare da solo il capo della setta, perciò sei l'unico in grado di portare a termine la sua missione.",al={"perché thaelrid ha bisogno di aiuto","perché thaelrid non può affrontare kelris","thaelrid, perché proprio io"}},["6dbae1c3"]={q="A cosa serve la Testa di Kelris?",a="La testa è una prova inconfutabile della morte del capo della setta. Kelris era sfuggito a lungo all'Alba d'Argento e molti credevano che fosse già morto o scomparso; presentare la sua testa a Bashana Totem Runico a Picco del Tuono conferma che il suo regno di terrore e sacrifici umani è davvero finito.",al={"scopo della testa di kelris","cosa fare con la testa di kelris","perché prendere la testa di kelris"}}},fp="20,210,22.316.0,22.295.0,21.314.1,28.228.0,54.228.0,16.230.0,43.250.0,48.253.0,52.211.0"}
P.entries["quest:65610"] = {n="Wish You Were Here",s="Un tessitore di tela lunare a Valtetra ti chiede di trovare Krilge, scomparso mentre proteggeva i civili. I suoi compagni lo chiamano disertore, ma il tessitore crede che sia rimasto al suo posto.",h="Un tessitore di tela lunare a Valtetra ti chiede di trovare Krilge, scomparso mentre proteggeva i civili.",kw={"valtetra","bestie delle paludi","disertore","lago cielinfranto","gan'rul bloodeye","krilge","scomparso","tela lunare"},sec={{t="Un amico scomparso",b="Il tessitore conobbe Krilge mentre lavorava la tela lunare a Valtetra. Krilge era stato assegnato lì per proteggere i civili, poi scomparve. Si incontravano spesso al Lago Cielinfranto, finché le aggressive bestie delle paludi non invasero la zona. Il tessitore spera ancora di scoprire che cosa gli sia accaduto."},{t="Al lago",b="Ti viene chiesto di cercare al Lago Cielinfranto e riferire ciò che scopri a Gan'rul Bloodeye a Orgrimmar. I compagni di Krilge hanno smesso di cercarlo. Forse il lago conserva ancora una traccia di ciò che gli è accaduto."}},faq={{q="Chi è Krilge?",a="Krilge era stato assegnato a Valtetra per proteggere i civili prima di scomparire. Lui e il tessitore di tela lunare si incontravano spesso al Lago Cielinfranto.",al={"krilge","amico scomparso del tessitore di tela lunare"}},{q="Perché Krilge viene chiamato disertore?",a="Krilge è scomparso dal suo posto. I suoi compagni d'armi hanno smesso di cercarlo e lo chiamano disertore.",al={"krilge disertore","perché hanno smesso di cercare"}},{q="Chi ti chiede di cercare Krilge?",a="Un tessitore di tela lunare che conobbe Krilge a Valtetra ti chiede di cercare una sua traccia.",al={"chi mi ha mandato","tessitore di tela lunare"}},{q="Dove si incontravano Krilge e il tessitore?",a="Krilge e il tessitore si incontravano spesso al Lago Cielinfranto, a Valtetra, prima che le aggressive bestie delle paludi invadessero la zona.",al={"luogo d'incontro di krilge","dov'è il lago cielinfranto"}},{q="A chi dovresti riferire ciò che hai scoperto?",a="Ti viene chiesto di riferire ciò che hai scoperto a Gan'rul Bloodeye a Orgrimmar.",al={"riferire a gan'rul","dove devo riferire"}}},fp="18,169,16.258.0,11.205.0,14.134.0,38.99.0,32.83.0,36.110.0,38.71.0"}
P.entries["quest:6562"] = {n="Trouble in the Deeps",s="Dalle Vette di Petrartiglio, Tsunaman manda i viaggiatori dell'Orda ad aiutare Je'neu Sancrea sulla costa remota di Valtetra. Lo studioso troll attende all'Avamposto di Zoram'gar, dove i pericoli si addensano lungo la riva.",h="Dalle Vette di Petrartiglio, Tsunaman manda i viaggiatori dell'Orda ad aiutare Je'neu Sancrea sulla costa...",kw={"valtetra","abissi di fondocupo","je'neu sancrea","vette di petrartiglio","tsunaman","landa di tagliavento","spiaggia di zoram","avamposto di zoram'gar"},ang={["class:Shaman"]="Come sciamano, puoi percepire il turbamento degli spiriti dell'acqua della Spiaggia di Zoram e aiutare a purificare la corruzione che li minaccia.",["faction:Horde"]="Come membro dell'Orda, aiuti a difendere l'Avamposto di Zoram'gar sul fianco occidentale di Kalimdor dalle forze degli Elfi della Notte e dagli orrori della costa.",["race:Troll"]="Come troll, puoi aiutare Je'neu Sancrea, uno dei più eminenti studiosi dei Darkspears, a svelare gli antichi misteri di Kalimdor."},sec={{t="Una convocazione sulla costa",b="Tsunaman riceve inquietanti notizie dal nord e chiama i viaggiatori dell'Orda ad aiutare Je'neu Sancrea. Lo studioso troll attende all'Avamposto di Zoram'gar, sulla costa occidentale più remota di Valtetra, lungo la Spiaggia di Zoram. Il pericolo cresce e Je'neu ha bisogno di aiuto che arrivi da fuori dell'avamposto."},{t="La strada per la Spiaggia di Zoram",b="La strada per la costa occidentale di Valtetra è pericolosa per i viaggiatori dell'Orda. Puoi attraversare la Landa di Tagliavento, dove i goblin hanno creato scompiglio, oppure viaggiare verso nord dalle Savane. In ogni caso, entrerai in una foresta sorvegliata dalle sentinelle degli Elfi della Notte.\n\nSotto la fitta volta di Valtetra, l'Avamposto di Zoram'gar resiste lungo la Spiaggia di Zoram, sferzata dalle tempeste. L'avamposto si affaccia sulle acque ombrose."},{t="Sussurri sotto le onde",b="Sulla costa, Je'neu Sancrea indica i guai che si celano sotto le maree, nel tempio sommerso degli Abissi di Fondocupo. Antiche corruzioni, nefasti Water Elementals e cultisti del Martello del Crepuscolo si radunano lì, risvegliando antichi mali. Je'neu attende che gli eroi in arrivo entrino nelle sale sommerse e affrontino il terrore che si leva al loro interno."}},faq={{q="Chi fornisce la missione Trouble in the Deeps?",a="Tsunaman, nelle Vette di Petrartiglio, manda i viaggiatori dell'Orda ad aiutare gli alleati lungo la costa di Valtetra.",al={"datore di missione","chi inizia trouble in the deeps","tsunaman"}},{q="Dove si trova Je'neu Sancrea?",a="Je'neu Sancrea attende all'Avamposto di Zoram'gar, sulla Spiaggia di Zoram, lungo la costa più occidentale di Valtetra.",al={"dove si trova je'neu","posizione di jeneu sancrea","avamposto di zoram'gar"}},{q="Come si raggiunge l'Avamposto di Zoram'gar dalle Vette di Petrartiglio?",a="Dalle Vette di Petrartiglio, viaggia verso nord-est attraverso la Landa di Tagliavento fino a Valtetra, oppure verso est attraversando le Savane ed entra nella foresta da sud. Poi dirigiti a ovest dalla Valtetra centrale fino alla Spiaggia di Zoram.",al={"percorso per valtetra","come arrivare alla spiaggia di zoram","rotta dalle vette di petrartiglio a valtetra"}},{q="Quale problema sta indagando Je'neu?",a="Je'neu Sancrea sorveglia le rovine degli Abissi di Fondocupo, dove i cultisti e le creature acquatiche corrotte risvegliano antichi orrori sotto la superficie.",al={"cosa sta succedendo alla spiaggia di zoram","perché jeneu ha bisogno di aiuto"}},{q="Quale missione segue Trouble in the Deeps?",a="Je'neu Sancrea ti manda negli Abissi di Fondocupo a raccogliere i Sapphires of Aku'Mai, carichi di energia elementale, nei tunnel del complesso.",al={"prossima missione","seguito di trouble in the deeps"}},{q="Perché il viaggio attraverso Valtetra è considerato pericoloso?",a="Gli Elfi della Notte difendono Valtetra con ferocia dalle incursioni dell'Orda. Sentinelle ostili e imboscate nascoste minacciano chi viaggia nella foresta.",al={"pericolo a valtetra","minaccia degli elfi della notte"}}},fx={dde1b6c4={q="Perché Tsunaman ti manda da Je'neu Sancrea?",a="Tsunaman sa che Je'neu Sancrea è isolato nel remoto Avamposto di Zoram'gar e ha un disperato bisogno di alleati capaci. Di stanza sulla costa occidentale di Valtetra, Je'neu è sempre più minacciato dai pericoli che si celano nelle misteriose profondità degli Abissi di Fondocupo e non dispone di sostegno sufficiente. Tsunaman ti manda a rinforzarlo prima che le forze ostili travolgano la posizione dell'Orda.",al={"perché tsunaman vuole che venga fatto","perché mandarmi a valtetra","motivo di tsunaman"}}},fp="20,192,22.271.0,24.383.0,24.318.1,41.99.0,32.99.0,51.196.0,37.144.0,40.120.0,57.133.0"}
P.entries["quest:6563"] = {n="L'essenza di Aku'mai",s="All'Avamposto di Zoram'gar, Je'neu Sancrea chiede agli avventurieri dell'Orda di fermare la raccolta di zaffiri dei naga negli Abissi di Fondocupo. Teme che ne usino male il potere.",h="All'Avamposto di Zoram'gar, Je'neu Sancrea chiede agli avventurieri dell'Orda di fermare la raccolta di...",kw={"valtetra","abissi di fondocupo","je'neu sancrea","naga","zaffiro di aku'mai","trouble in the deeps","spiriti dell'acqua","spiaggia di zoram"},ang={["class:Shaman"]="Come sciamano, puoi percepire gli inquieti spiriti dell'acqua vincolati nei cristalli. Mettono in guardia sulle forze elementali corrotte sotto il tempio.",["faction:Horde"]="Come membro dell'Orda, aiuti a difendere la pericolosa testa di ponte dell'Avamposto di Zoram'gar. Impedire ai naga vicini di ottenere potere magico grezzo aiuta a proteggerla.",["race:Troll"]="Come troll, puoi rivolgerti a Je'neu Sancrea, un perspicace mistico dei Puntascura. Per affrontare le strane minacce di Kalimdor, si affida alla comunione con gli spiriti e alla saggezza degli antenati."},sec={{t="Una minaccia negli abissi",b="Dalla Spiaggia di Zoram, Je'neu Sancrea veglia sulle rovine Kaldorei. Ora i naga estraggono grappoli di zaffiri nelle camere sommerse degli Abissi di Fondocupo, dove le gemme crescono lungo le umide pareti delle caverne. Sancrea percepisce che gli invasori serpentini intendono sfruttarne il potere, perciò vuole fermare la raccolta prima che possano usarlo."},{t="Spiriti dell'acqua e potere arcano",b="Gli zaffiri di Aku'mai racchiudono energia elementale dell'acqua e spiriti acquatici che vi aderiscono. Stregoni esperti potrebbero usarli per alimentare pericolosi rituali arcani o rafforzare Aku'mai, l'idra oscura la cui presenza pervade il tempio sotterraneo. Recuperare i grappoli sottrae ai naga questo potente reagente e aiuta a proteggere la costa dalla magia elementale fuori controllo."}},faq={{q="Chi fornisce questa missione?",a="All'Avamposto di Zoram'gar, sulla Spiaggia di Zoram, nel nord-ovest di Valtetra, Je'neu Sancrea, uno sciamano troll dei Puntascura, fa la richiesta.",al={"datore di missione","chi inizia l'essenza di akumai","posizione di jeneu sancrea"}},{q="Perché i naga vogliono gli zaffiri di Aku'mai?",a="Non si conosce lo scopo preciso dei naga. Gli zaffiri racchiudono una potente energia elementale dell'acqua e una forza magica grezza che potrebbe alimentare i loro incantesimi.",al={"perché i naga vogliono gli zaffiri","a cosa servono i cristalli","scopo degli zaffiri"}},{q="Dove si trovano i grappoli di zaffiri?",a="Grappoli di zaffiri ricoprono pareti e pavimenti delle caverne nei tunnel esterni e nei passaggi allagati degli Abissi di Fondocupo. Si trovano appena oltre l'ingresso sotterraneo in rovina, lungo la Spiaggia di Zoram.",al={"dove trovare gli zaffiri","posizione degli zaffiri di akumai","apparizioni dei cristalli"}},{q="Chi è Aku'mai?",a="Aku'mai è una mostruosa idra a tre teste che dimora nelle profondità delle rovine sommerse del tempio. I cultisti del Martello del Crepuscolo lo venerano come servitore degli Dei Antichi.",al={"chi è akumai","cos'è akumai","aku'mai"}},{q="Devo uccidere boss dei sotterranei per questa missione?",a="No. I grappoli di zaffiri crescono nei primi tunnel sommersi, prima che tu incontri i boss principali degli Abissi di Fondocupo.",al={"ho bisogno di un gruppo completo","posso raccogliere gli zaffiri da solo","requisito boss"}},{q="Questa missione si collega a qualche altra trama?",a="Sì. Segue «Problemi negli Abissi» e prosegue le indagini di Je'neu Sancrea sull'oscurità crescente e sulle attività dei cultisti negli Abissi di Fondocupo.",al={"serie di missioni","prerequisiti","trouble in the deeps"}}},fx={["7dd39a86"]={q="Perché Je'neu Sancrea vuole gli Zaffiri di Aku'mai?",a="Je'neu Sancrea ha notato che i naga estraggono sistematicamente questi ammassi cristallini dalle pareti delle caverne degli Abissi di Fondocupo. Anche se il loro piano preciso resta oscuro, percepisce nelle pietre un'immensa energia elementale. Vuole che vengano raccolte prima che i naga possano usarle come potenti componenti arcane.",al={"motivo di je'neu sancrea","perché raccogliere gli zaffiri","perché raccogliere gli zaffiri di aku'mai"}},["644dacf9"]={q="Che cos'è lo Zaffiro di Aku'mai?",a="Questi zaffiri sono formazioni cristalline che rivestono i tunnel sommersi degli Abissi di Fondocupo. Risuonano di pura energia elementale e attirano gli spiriti dell'acqua, che vi si aggrappano. Grazie a questa naturale concentrazione di energia, sono potenti reagenti arcani se incanalati nel modo giusto.",al={"cosa sono gli zaffiri","storia dello zaffiro di aku'mai","potere degli zaffiri di aku'mai"}}},fp="22,160,22.319.0,30.364.0,21.129.0,46.137.0,38.185.0,16.158.0,52.117.0,47.151.0"}
P.entries["quest:6564"] = {n="Allegiance to the Old Gods",s="All’Avamposto di Zoram'gar porti a Je'neu Sancrea un messaggio dei naga proveniente dagli Abissi di Fondocupo. I suoi ordini indicano un complotto rituale tra le rovine allagate.",h="All’Avamposto di Zoram'gar porti a Je'neu Sancrea un messaggio dei naga proveniente dagli Abissi di Fondocupo.",kw={"aku'mai","alleanza","valtetra","abissi di fondocupo","nota bagnata","je'neu sancrea","lorgus jett","antichi dei","wrathscale","avamposto di zoram'gar"},ang={["class:Shaman"]="Da sciamano, sai che costringere gli spiriti elementali dell’acqua dentro cristalli rituali altera l’equilibrio naturale e richiede un intervento immediato.",["faction:Horde"]="In quanto membro dell’Orda, aiuti a scoprire la nota di Lorgus Jett e a proteggere l’Avamposto di Zoram'gar dal Martello del Crepuscolo e dai suoi alleati naga. Minacciano la roccaforte dell’Orda sulla costa occidentale di Valtetra.",["race:Troll"]="In quanto troll, aiuti il tuo parente Puntascura Je'neu Sancrea a scoprire entità cosmiche antiche, il cui ritorno minaccerebbe ogni tribù di Azeroth."},sec={{t="Una Dichiarazione Scarabocchiata",b="Gli esploratori dell’Orda trovano una nota bagnata e accartocciata mentre combattono i naga negli Abissi di Fondocupo. Le parole frenetiche ordinano alle sacerdotesse naga di raccogliere cristalli d’acqua elementale. I cristalli serviranno ad alimentare le evocazioni degli acquamanti naga. Gli acquamanti stanno radunando forze elementali per uno scopo più oscuro."},{t="Sussurri dell'Abisso",b="Gli ordini dicono che i naga useranno l’energia elementale dei cristalli per placare ed evocare pienamente Aku'mai, un’idra mostruosa al servizio degli Antichi Dei. La nota sostiene che questo annuncerà il ritorno della più grande era del mondo: il regno preistorico degli Antichi Dei. All’Avamposto di Zoram'gar, Je'neu Sancrea, un mistico Puntascura, indica l’autore: Lorgus Jett, un cultista del Martello del Crepuscolo."}},faq={{q="Cos'è la Nota Bagnata?",a="La Nota Bagnata contiene ordini di Lorgus Jett, un cultista del Martello del Crepuscolo. Dice alle sacerdotesse naga di raccogliere cristalli intrisi di energia elementale per rafforzare i loro acquamanti ed evocare Aku'mai, un servitore mostruoso.",al={"nota bagnata","cosa dice la nota","storia della nota"}},{q="Chi è Je'neu Sancrea?",a="Je'neu Sancrea è un veggente e studioso troll Puntascura all’Avamposto di Zoram'gar, a Valtetra. Rappresenta The Earthen Ring e indaga sugli squilibri elementali e sulle antiche minacce che emergono dagli Abissi di Fondocupo.",al={"jeneu sancrea","chi è jeneu","datore di missioni avamposto zoram"}},{q="Chi è Lorgus Jett?",a="Lorgus Jett è uno sciamano umano del culto del Martello del Crepuscolo che opera insieme ai naga negli Abissi di Fondocupo. Sovrintende alla raccolta di cristalli elementali per potenziare i rituali dei naga e risvegliare antichi orrori oscuri.",al={"lorgus jett","chi ha scritto la nota","leader naga zoram"}},{q="Cos'è Aku'mai?",a="Aku'mai è un’idra colossale a tre teste che vive nelle profondità sommerse degli Abissi di Fondocupo. Il culto del Martello del Crepuscolo e i naga venerano la creatura, legata all’oscurità primordiale degli Antichi Dei.",al={"akumai","chi è akumai","storia di aku'mai"}},{q="Perché i naga raccolgono cristalli d'acqua?",a="I naga raccolgono cristalli d’acqua per attingere agli spiriti elementali intrappolati al loro interno e potenziare i loro acquamanti. Sperano di placare Aku'mai e accumulare abbastanza potere da riportare gli Antichi Dei.",al={"perché cristalli naga","cristalli elementali naga","cristalli acquamante"}},{q="Dove conduce questa serie di missioni?",a="Portare la nota a Je'neu Sancrea dà il via a una ricerca per trovare e giustiziare Lorgus Jett. Così si ostacolerebbero i piani rituali del culto negli Abissi di Fondocupo.",al={"cosa viene dopo allegiance to the old gods","allegiance to the old gods parte 2","missione successiva"}}},fp="26,141,23.300.0,20.366.1,22.211.0,22.207.0,19.213.0,16.198.0,43.195.0,33.152.1"}
P.entries["quest:6565"] = {n="Allegiance to the Old Gods",s="A Zoram'gar, l'Orda combatte il culto del Martello del Crepuscolo negli Abissi di Fondocupo. Je'neu Sancrea invia dei campioni a caccia di Lorgus Jett, nella speranza di fermare i cultisti che cercano di risvegliare antiche forze distruttive sotto la costa di Valtetra.",h="A Zoram'gar, l'Orda combatte il culto del Martello del Crepuscolo negli Abissi di Fondocupo.",kw={"allegiance to the old gods","valtetra","abissi di fondocupo","je'neu sancrea","lorgus jett","old gods","martello del crepuscolo","zoram'gar"},ang={["class:Shaman"]="Il Martello del Crepuscolo vuole scatenare la furia elementale al servizio degli caotici Old Gods. Sradicare il culto è una priorità per chi, insieme all'Earthen Ring, ha giurato di mantenere l'equilibrio elementale.",["faction:Horde"]="Sconfiggere Lorgus Jett protegge l'Avamposto di Zoram'gar e il suo isolato accampamento dell'Orda dalle trame insidiose dei cultisti.",["race:Troll"]="Aiutare Je'neu Sancrea rende onore alla saggezza di un rispettato veggente dei Puntascura, impegnato lontano dalle Isole dell'Eco a proteggere gli spiriti primordiali di Azeroth."},sec={{t="La minaccia sotto Zoram'gar",b="Dalla costa di Valtetra, l'Avamposto di Zoram'gar sorveglia gli Abissi di Fondocupo. Naga, bestie corrotte e fanatici del Martello del Crepuscolo hanno invaso il complesso del tempio sommerso. Je'neu Sancrea è un veggente dell'Earthen Ring di stanza sulla costa. Vede che i cultisti servono gli Old Gods invece di rispettare l'equilibrio naturale e gli spiriti della terra. Questi esseri mostruosi del caos furono sconfitti in tempi antichi, ma il loro tocco maligno persiste nei luoghi dimenticati di Azeroth."},{t="Porre fine a Lorgus Jett",b="Je'neu invia campioni dell'Orda nelle rovine sotterranee a caccia di Lorgus Jett, un leader affermato tra i cultisti degli Abissi di Fondocupo. Lorgus si aggira nei profondi passaggi di pietra tra la camera di Ghamoo-ra e quella del Barone Aquanis. Je'neu è troppo fragile per addentrarsi da solo nell'umida oscurità. Sconfiggere Lorgus è fondamentale per interrompere i rituali oscuri che cercava di orchestrare sotto le onde di Valtetra."},{t="Argine al caos",b="La morte di Lorgus Jett scongiura l'immediata minaccia rituale per la costa, ma Je'neu sa che il Martello del Crepuscolo è ancora attivo. La sua silenziosa infiltrazione negli antichi luoghi sacri indica una minaccia più ampia, intenzionata a riportare gli Old Gods. A Zoram'gar, la sconfitta di Lorgus fa guadagnare tempo all'Orda contro un nemico nascosto nelle ombre del mondo."}},faq={{q="Chi è Lorgus Jett?",a="Lorgus Jett è un leader affermato dei cultisti del Martello del Crepuscolo negli Abissi di Fondocupo. Dirige rituali volti a riportare gli antichi Old Gods e il loro dominio.",al={"lorgus jett","chi è lorgus","storia lorgus jett"}},{q="Dove si può trovare Lorgus Jett negli Abissi di Fondocupo?",a="Lorgus Jett pattuglia i corridoi allagati degli Abissi di Fondocupo, nei passaggi che collegano la camera di Ghamoo-ra all'area dell'altare del Barone Aquanis.",al={"posizione lorgus jett","dove si trova lorgus","trovare lorgus jett"}},{q="Chi è Je'neu Sancrea?",a="Je'neu Sancrea è un troll veggente dei Puntascura, appartenente all'Earthen Ring, di stanza all'Avamposto di Zoram'gar sulla Spiaggia di Zoram, a Valtetra. Tiene d'occhio i disordini elementali e la corruzione negli Abissi di Fondocupo.",al={"je'neu sancrea","chi dà allegiance to the old gods","jeneu"}},{q="Perché a Je'neu importa del Martello del Crepuscolo?",a="Je'neu è dedito a comprendere la natura e l'equilibrio elementale. Considera il Martello del Crepuscolo una minaccia esistenziale, perché il culto serve gli caotici Old Gods, il cui ritorno distruggerebbe l'armonia del mondo.",al={"perché combattere il martello del crepuscolo","the earthen ring old gods"}},{q="Cosa sono gli Old Gods?",a="Gli Old Gods sono esseri primordiali di caos e distruzione che dominarono Azeroth in un passato remoto, prima di essere sconfitti e sepolti. Il Martello del Crepuscolo li venera e trama per spezzare i loro sigilli e riportare il loro dominio distruttivo.",al={"storia old gods","chi sono gli old gods","creature del caos"}},{q="Perché Je'neu Sancrea non può uccidere Lorgus Jett da solo?",a="Je'neu è troppo fragile per affrontare da solo gli Abissi di Fondocupo. Dall'avamposto segue i disordini spirituali ed elementali, mentre i campioni dell'Orda combattono.",al={"perché jeneu non va","jeneu è debole"}}},fp="26,239,28.446.0,18.398.0,17.332.1,19.168.0,52.141.0,22.201.0,49.212.0,22.243.0,50.156.0"}
P.entries["quest:6568"] = {n="The Testament of Rexxar",s="Rexxar ti manda nelle Terre Infette Occidentali con un messaggio per Myranda la Strega. Gli serve la sua abilità con le illusioni per superare le difese dello Stormo dei Draghi Neri.",h="Rexxar ti manda nelle Terre Infette Occidentali con un messaggio per Myranda la Strega.",kw={"stormo dei draghi neri","desolanda","illusione","maestra dell'inganno","myranda la strega","rexxar","collina del cordoglio","testamento di rexxar","terre infette occidentali"},sec={{t="L'Arte dell'Illusione",b="A Rexxar serve un'illusione per superare le difese dello Stormo dei Draghi Neri. Per questo ti manda da Myranda la Strega, una maestra delle illusioni che vive nelle Terre Infette Occidentali. L'alleanza di Lordaeron l'ha cacciata. In passato ha aiutato la gente di Rexxar, quando una causa le è sembrata meritevole. Ora porti a lei il suo messaggio."},{t="Un Visitatore a Lordaeron",b="Myranda dice che un membro dell'Orda è una vista rara in queste zone di Lordaeron. Poi ti chiede cosa le hai portato."},{t="La Risposta di Myranda",b="Myranda tiene in mano il biglietto, fa una pausa e sorride. Chiede di Rexxar e spiega che la pagina era bianca di proposito. Conteneva i pensieri e le intenzioni di chi l'ha scritta. Capisce perché Rexxar li abbia tenuti lontani dall'inchiostro. Il messaggio sarebbe stato pericoloso se tu fossi stato catturato o ucciso.\n\nMyranda accetta di aiutarti. Deve un favore o due al Capoguerra."}},faq={{q="Chi è Myranda la Strega?",a="Myranda la Strega è una maestra delle illusioni di Lordaeron, cacciata dalla sua alleanza. Vive a Collina del Cordoglio, nelle Terre Infette Occidentali.",al={"chi è myranda","storia di myranda la strega","dove si trova myranda"}},{q="Perché devi cercare un'illusionista?",a="A Rexxar serve un'illusione per superare le difese dello Stormo dei Draghi Neri. Conosce una maestra delle illusioni che potrebbe aiutarti.",al={"perché camuffarsi","perché cercare un'illusionista","ingannare lo stormo dei draghi neri"}},{q="Dove ti manda Rexxar?",a="Rexxar ti manda nelle Terre Infette Occidentali a cercare Myranda la Strega a Collina del Cordoglio.",al={"dove devo andare","dove si trova la collina del cordoglio","destinazione della maestra dell'inganno"}},{q="Myranda ha già aiutato l'Orda?",a="Rexxar dice che Myranda ha già aiutato la sua gente, ogni volta che ha trovato una causa meritevole.",al={"a myranda piace l'orda","myranda è dell'alleanza o dell'orda","favore di myranda al capoguerra"}}},fp="23,150,19.293.0,22.121.0,16.334.1,23.136.0,37.105.0,27.83.0,36.82.0"}
P.entries["quest:657"] = {n="Hints of a New Plague?",s="Kinelory è diretta alla Fattoria di Go'shek, dove continuano i letali esperimenti dell'Apotecario Jorell. Quae li ha scoperti in un dossier, ma è troppo ferita dopo uno scontro con gli orchi per accompagnarla.",h="Kinelory è diretta alla Fattoria di Go'shek, dove continuano i letali esperimenti dell'Apotecario Jorell.",kw={"apotecario jorell","reietti","fattoria di go'shek","kinelory","phin","piaga","quae","mulino di tarren"},sec={{t="Gli esperimenti di Jorell",b="Il dossier mostra che Jorell sta conducendo esperimenti letali alla Fattoria di Go'shek. Quae non sa cosa significhino per Colletorto, ma Phin non vorrebbe che continuassero. Parte delle ricerche di Jorell è già arrivata al Mulino di Tarren."},{t="Il protettore di Kinelory",b="Mentre eri via, Quae ha combattuto contro alcuni orchi e ora non può aiutare Kinelory. Kinelory ha intenzione di andare alla fattoria e prendere le ricerche che Jorell non ha ancora inviato al Mulino di Tarren. Ha bisogno della tua protezione durante il viaggio."},{t="La determinazione di Kinelory",b="Kinelory dice che distruggerà personalmente tutti i Reietti, se questo porterà pace a Phin. Dalla piaga, Phin ha fatto così tanto per Kinelory e gli altri. Non avrebbero mai pensato di poter ritrovare amici o una famiglia. Kinelory ti chiede di avvisarla quando sarai pronto, poi partirete subito insieme."}},faq={{q="Perché Quae non può accompagnare Kinelory?",a="Mentre eri via, Quae ha combattuto contro alcuni orchi e non è in condizioni di aiutare Kinelory.",al={"perché quae resta","perché quae non aiuta","perché scortare kinelory da sola"}},{q="Cosa è stato scoperto nel dossier?",a="Il dossier rivela i letali esperimenti dell'Apotecario Jorell alla Fattoria di Go'shek.",al={"cosa c'era nel dossier","esperimenti di jorell","cosa sta facendo jorell"}},{q="Perché Quae e Kinelory stanno indagando?",a="Quae e Kinelory sono compagne di Phin. Phin guida un gruppo di avventurieri che indaga su strani eventi, e non vorrebbe che gli esperimenti di Jorell continuassero.",al={"chi è phin","perché si preoccupano della piaga","perché aiutare phin"}},{q="Dove vengono spedite le ricerche?",a="Parte delle ricerche di Jorell è già arrivata al Mulino di Tarren. Kinelory ha intenzione di prendere quelle che non ha ancora inviato.",al={"dove finiscono gli appunti","ricerche al mulino di tarren"}}},fp="22,186,20.228.0,20.209.0,18.318.1,34.78.0,34.74.0,45.159.0,33.107.0"}
P.entries["quest:6571"] = {n="Warsong Supplies",s="All'Avamposto di Troncorotto, Locke Okarr ha bisogno di Warsong Supplies per tenere in funzione il campo di taglio. Alcuni rifornimenti sono in città, altri a Baia del Bottino, e altri ancora sono finiti in mani nemiche a Valtetra.",h="All'Avamposto di Troncorotto, Locke Okarr ha bisogno di Warsong Supplies per tenere in funzione il campo di...",kw={"valtetra","baia del bottino","locke okarr","corda per campo di taglio","pixel","lame seghettate","avamposto di troncorotto","campo di taglio dei cantaguerra","olio dei cantaguerra","warsong supplies"},ang={["faction:Horde"]="L'espansione dell'Orda a Durotar dipende dal legname procurato dal Clan Cantaguerra. Recuperare questi attrezzi aiuta a sostenere Orgrimmar.",["profession:Engineering"]="Da ingegnere, puoi vedere come le forniture dei goblin, dalle lame seghettate di Pixel ai lubrificanti per motori a vapore, aiutino a mantenere in funzione i macchinari mentre il Clan Cantaguerra abbatte le antiche foreste di Valtetra.",["race:Orc"]="Da orco, contribuisci a onorare l'eredità del Clan Cantaguerra a Valtetra, mantenendo affilate le sue asce e riforniti i suoi campi, nonostante le molestie degli abitanti della foresta."},sec={{t="Mantenere le Seghe in Funzione",b="Dall'Avamposto di Troncorotto, Locke Okarr si impegna a rifornire il Campo di Taglio dei Cantaguerra. Il Clan Cantaguerra ha bisogno di un flusso costante di strumenti pesanti per raccogliere l'antico legname di Valtetra. Le incursioni di furbolg e satiri hanno disperso o sottratto le scorte locali, lasciando il campo senza attrezzature indispensabili."},{t="Una Catena Logistica Dispersa",b="Raccogli attrezzature in tutta Kalimdor e oltre. Pixel, il corriere goblin all'Avamposto di Troncorotto, ha le lame circolari. A Baia del Bottino, il Capitano del Porto Malattracco custodisce una cassa di asce pesanti. I furbolg Foulweald e Thistlefur hanno preso le corde per campo di taglio, mentre i satiri di Jorxian, Satirnaar e Xavian hanno rubato barili di Olio dei Cantaguerra per i loro riti profani."}},faq={{q="Quali sono le Warsong Supplies richieste?",a="Locke Okarr ha bisogno di quattro oggetti: le Lame Seghettate dei Cantaguerra in possesso di Pixel, una cassa di Warsong Axes in attesa a Baia del Bottino, la Corda per Campo di Taglio sottratta dai furbolg locali e l'Olio dei Cantaguerra rubato dai satiri di Valtetra.",al={"lista warsong supplies","quali oggetti servono","forniture necessarie"}},{q="Chi è Locke Okarr?",a="Locke Okarr è un orco dell'Avamposto di Troncorotto che coordina le consegne di materiali al Campo di Taglio dei Cantaguerra. Ha bisogno di aiuto per recuperare le spedizioni disperse prima che il lavoro al campo subisca ritardi.",al={"storia di locke okarr","chi assegna warsong supplies","datore di missioni avamposto di troncorotto"}},{q="Perché l'Orda spedisce attrezzature da Baia del Bottino?",a="L'Orda usa reti commerciali neutrali come il Cartello degli Spargifumo per importare merci speciali che Durotar e le Savane non possono forgiare facilmente in grandi quantità. I canali dei goblin fanno transitare le pesanti asce da taglio attraverso porti marittimi come Baia del Bottino, dirette a Valtetra.",al={"perché baia del bottino","spedizione asce baia del bottino","strumenti cartello degli spargifumo"}},{q="Perché i satiri vogliono l'Olio dei Cantaguerra?",a="I satiri di Satirnaar, Jorxian e Xavian dirottano l'olio industriale rubato dai macchinari ai loro riti corrotti, dedicati alla Legione Infuocata e alla diffusione della corruzione di Vilbosco.",al={"storia olio dei satiri","perché i satiri hanno l'olio","rituali olio dei cantaguerra"}},{q="Quali furbolg hanno rubato la corda per campo di taglio?",a="Le tribù di furbolg Foulweald e Thistlefur hanno preso la Corda per Campo di Taglio. Entrambe sono ferocemente ostili al disboscamento indiscriminato dell'Orda a Valtetra.",al={"chi ha rubato la corda","storia corda furbolg","corda foulweald thistlefur"}},{q="Perché il Campo di Taglio dei Cantaguerra è così importante per l'Orda?",a="Il Campo di Taglio dei Cantaguerra fornisce il legname necessario all'Orda per le costruzioni e le forniture militari. Le terre aride di Durotar offrono quasi nessun legname utilizzabile, così il Clan Cantaguerra raccoglie gli enormi alberi di Valtetra per costruire Orgrimmar e sostenere la crescente infrastruttura militare dell'Orda.",al={"perché raccogliere legname a valtetra","importanza campo di taglio dei cantaguerra","orchi che tagliano alberi"}}},fx={b7ffa730={q="Perché Locke Okarr ha bisogno che queste scorte vengano raccolte?",a="Locke Okarr è responsabile dei rifornimenti del Campo di Taglio dei Cantaguerra, dove gli attrezzi essenziali sono ormai pericolosamente scarsi. Le spedizioni sono state ritardate, saccheggiate o intercettate in tutta Valtetra e oltre. Se non consegnerà in tempo questi materiali essenziali per il taglio, dovrà affrontare gravi conseguenze da parte dei suoi superiori nel clan Cantaguerra.",al={"perché le scorte per locke okarr","perché raccogliere le scorte per locke okarr","motivo di locke okarr"}},["54c7a3c1"]={q="A cosa servono le Lame Seghettate dei Cantaguerra?",a="Le lame seghettate sono componenti industriali essenziali per i trituratori meccanizzati e le segherie del Campo di Taglio dei Cantaguerra. Senza lame nuove, i macchinari da disboscamento pesante dell'Orda non possono tagliare efficacemente gli enormi alberi antichi di Valtetra per ricavare legname destinato alla costruzione di Orgrimmar e degli accampamenti locali.",al={"a cosa servono le lame seghettate","uso delle lame seghettate dei cantaguerra","lame seghettate del campo di taglio"}},["9c63ad01"]={q="A cosa serve la Spedizione d'Asce dei Cantaguerra?",a="Importate direttamente dalle fonderie dei goblin di Baia del Bottino, queste asce robuste riforniscono i Predoni Cantaguerra e i lavoratori che sgombrano a mano la fitta boscaglia e abbattono gli alberi più imponenti di Valtetra. In una foresta ostile, popolata da elfi della notte e bestie, questi solidi attrezzi fungono anche da affidabili armi da guerra.",al={"a cosa serve la spedizione d'asce","uso della spedizione d'asce dei cantaguerra","spedizione d'asce di baia del bottino"}},["74cafbab"]={q="A cosa serve l'Olio dei Cantaguerra?",a="L'Olio dei Cantaguerra è un lubrificante denso, necessario per mantenere efficienti le macchine a vapore, i trituratori e i complessi macchinari da taglio del campo anche nelle condizioni più dure. Senza, le pesanti strutture in ferro si bloccano e le operazioni di taglio del legname si fermano del tutto.",al={"a cosa serve l'olio dei cantaguerra","scopo dell'olio dei cantaguerra","perché serve l'olio al campo di taglio"}},["76a0db14"]={q="A cosa serve la Corda per Campo di Taglio?",a="Questa corda robusta viene usata dalle squadre del campo di taglio per trascinare, fissare e sollevare gli enormi tronchi dopo averli abbattuti. Gestire gli imponenti alberi di Valtetra senza un'attrezzatura adeguata è quasi impossibile e rischia di schiacciare i lavoratori o danneggiare equipaggiamenti preziosi.",al={"a cosa serve la corda per campo di taglio","scopo della corda per campo di taglio","corda del campo dei cantaguerra"}},["4e02126d"]={q="Perché Locke Okarr chiede aiuto a un avventuriero invece che alle guardie dell'avamposto?",a="La guarnigione dell'Avamposto di Troncorotto è impegnata al massimo a difendersi dalle continue incursioni delle Sentinelle Alargentea e degli abitanti ostili della foresta. Locke non può sottrarre guardie preziose alla difesa del perimetro, né può lasciare di persona il suo posto per perlustrare gli angoli più remoti di Valtetra e spingersi fino a Baia del Bottino.",al={"perché locke okarr ha scelto me","perché le guardie non possono procurare i rifornimenti","perché non mandare le guardie"}}},fp="16,175,25.277.0,27.361.0,39.194.0,19.186.0,51.263.0,35.173.0,38.139.0,53.281.0"}
P.entries["quest:658"] = {n="Hints of a New Plague?",s="Alla Fattoria di Go'shek, Quae e Kin osservano da giorni. Kin ha visto un corriere uscire da una piccola casa a sud. Sospettano che porti appunti al Mulino di Tarren, così Quae ti chiede di seguirla e riportarle i documenti.",h="Alla Fattoria di Go'shek, Quae e Kin osservano da giorni.",kw={"speziale","altopiani d'arathi","corriere dei reietti","fattoria di go'shek","kin","phin odelic","quae","documenti sigillati","mulino di tarren"},sec={{t="Osservare la Fattoria",b="Quae si aspettava che Phin Odelic ti mandasse. Secondo Quae, lui si preoccupa troppo. Quae e Kin osservano la fattoria da giorni, e di recente Kin ha visto un corriere uscire da una piccola casa a sud. Kin parla spesso, ma Quae si fida dei suoi sensi nei luoghi pericolosi."},{t="La Cartella del Corriere",b="Quae ti chiede se sei un abile tracciatore. Il corriere potrebbe portare appunti diretti al Mulino di Tarren, e i documenti potrebbero fare luce su ciò che accade a Colletorto. Trova il Corriere dei Reietti e porta i suoi Documenti Sigillati a Quae, vicino alla Fattoria di Go'shek.\n\nMentre cerchi, Kin avvista uno speziale che esce dalla stessa casa. Quae sospetta che lo speziale abbia cattive intenzioni, ma le servono prove prima che qualcuno agisca avventatamente."}},faq={{q="Chi ti ha mandato a trovare Quae e Kin?",a="Phin Odelic ti ha mandato a controllare Quae e Kin. Quae se lo aspettava, perché Phin si preoccupa troppo.",al={"chi mi ha mandato da quae","chi ha iniziato a new plague","missione di phin odelic"}},{q="Da dove è venuto il corriere?",a="Kin ha visto il corriere uscire da una piccola casa a sud.",al={"da dove viene il corriere","posizione corriere","casa a sud della fattoria"}},{q="Dove è diretto il corriere?",a="Quae e Kin sospettano che il corriere trasporti appunti diretti al Mulino di Tarren.",al={"destinazione corriere","dove sta andando il corriere"}},{q="Quale oggetto ti è stato chiesto di recuperare?",a="Porta i Documenti Sigillati del Corriere dei Reietti a Quae, vicino alla Fattoria di Go'shek.",al={"quale oggetto ha il corriere","documenti sigillati"}},{q="Chi altro è stato avvistato alla casa?",a="Mentre eri via, Kin ha avvistato uno speziale che usciva dalla stessa casa a sud.",al={"speziale alla fattoria","chi è uscito dalla casa"}},{q="Perché Quae vuole i documenti?",a="I documenti potrebbero fare luce su ciò che accade a Colletorto. Quae ha bisogno di prove prima che qualcuno agisca avventatamente.",al={"perché prendere i documenti","a cosa servono gli appunti"}}},fp="22,215,17.252.0,20.399.0,34.93.0,32.53.0,29.69.0,35.69.0,34.83.0,33.109.0"}
P.entries["quest:6581"] = {n="Lame Seghettate dei Cantaguerra",s="All'Avamposto di Troncorotto, i taglialegna dei Cantaguerra aspettano le lame arrivate da Porto Paranco. La loro corriera Pixel scambierà il carico con un'arma per proteggersi sulle pericolose strade di Valtetra. Le lame tengono in funzione i campi di disboscamento dell'Orda.",h="All'Avamposto di Troncorotto, i taglialegna dei Cantaguerra aspettano le lame arrivate da Porto Paranco.",kw={"valtetra","schioppo mortale","pixel","porto paranco","avamposto di troncorotto","predoni cantaguerra","lame seghettate dei cantaguerra","warsong supplies"},ang={["faction:Horde"]="Come membro dell'Orda, dipendi dai campi di disboscamento di Valtetra per ottenere il legname necessario a costruire a Orgrimmar. Ogni consegna di macchinari aiuta a tenere in funzione i campi.",["profession:Engineering"]="Come Ingegnere, puoi fabbricare lo Schioppo Mortale che vuole Pixel. L'Ingegneria fornisce armi e macchinari per lo sforzo bellico dell'Orda.",["race:Orc"]="Come orco, sai che il Clan Cantaguerra mette il suo orgoglio nel disboscare Valtetra sotto il comando di Grommash Hellscream. Tenere le lame in funzione sostiene la presenza del clan nella foresta."},sec={{t="L'astuto baratto di una corriere",b="Pixel ha portato pesanti lame da sega da Porto Paranco all'Avamposto di Troncorotto, ma non le cederà gratis. Nelle terre selvagge di Valtetra, per lei la sicurezza conta più dell'oro. Chiede in cambio uno Schioppo Mortale, così potrà difendersi sulle pericolose strade che attraversano il territorio ostile."},{t="Rifornire lo sforzo bellico",b="L'Orda ha bisogno del legname di Valtetra per alleviare la carenza di scorte in Durotar e nelle Savane. Le asce si smussano in fretta contro gli antichi boschi, perciò i taglialegna dei Cantaguerra si affidano a lame forgiate dai goblin. Il carico di Pixel rifornisce i campi di disboscamento, dove l'Orda taglia alberi per gli avamposti e le macchine da guerra, nonostante la feroce resistenza degli Elfi della Notte."}},faq={{q="Chi è Pixel e perché ha le lame seghettate?",a="Pixel è una corriera all'Avamposto di Troncorotto, dove ha portato lame da sega da Porto Paranco. Trattiene il carico finché non avrà trovato un'arma per proteggersi.",al={"chi è pixel","pixel avamposto di troncorotto","corriere lame seghettate"}},{q="Perché Pixel vuole uno Schioppo Mortale invece dell'oro?",a="Sulla pericolosa strada dalle Savane a Valtetra, Pixel dà più valore alla sicurezza che all'oro. Chiede uno Schioppo Mortale per difendersi durante i suoi viaggi.",al={"perché schioppo mortale","scambio arma pixel","perché vuole un'arma"}},{q="Perché queste lame da sega sono così importanti per l'Orda?",a="Il Clan Cantaguerra ha bisogno di legname per gli avamposti e le macchine da guerra dell'Orda. Le asce si consumano contro gli antichi alberi di Valtetra, perciò i campi di disboscamento si affidano a lame meccaniche importate.",al={"perché servono le lame seghettate","importanza legname cantaguerra","perché warsong supplies"}},{q="Da dove provengono originariamente le lame seghettate?",a="Le lame da sega arrivano da Porto Paranco e sono state trasportate via terra fino all'Avamposto di Troncorotto.",al={"origine lame seghettate","lame porto paranco","da dove vengono le lame seghettate"}},{q="Come si inserisce questa missione nello sforzo di disboscamento dei Cantaguerra?",a="Le lame da sega fanno parte delle scorte necessarie per tenere in funzione i campi di disboscamento dei Cantaguerra a Valtetra.",al={"catena rifornimenti cantaguerra","prerequisito lame seghettate cantaguerra"}},{q="Qualcuno può fabbricare l'arma che Pixel vuole?",a="Gli Ingegneri esperti possono fabbricare uno Schioppo Mortale con tubi di rame, bulloni di rame, un calcio di legno e cuoio. Anche corrieri e guerrieri possono procurarsene uno tramite i mercati locali o altri avventurieri.",al={"come ottenere schioppo mortale","fonte schioppo mortale","arma ingegneria"}}},fx={["496db877"]={q="A cosa serve lo Schioppo Mortale?",a="Pixel ha bisogno di proteggersi mentre è in viaggio. Da corriere che trasporta merci attraverso terre selvagge come Valtetra e The Barrens, viaggiare da sola è pericoloso. Invece di monete, inutili contro le bestie o gli elfi della notte, pretende un'arma da fuoco affidabile, realizzata da un ingegnere, per potersi difendere durante il viaggio.",al={"a cosa serve lo schioppo","pixel e lo schioppo mortale","a cosa serve lo schioppo a pixel"}}},fp="18,235,25.287.0,24.331.0,50.149.0,57.158.0,51.178.0,46.79.0,58.99.0,39.200.0"}
P.entries["quest:659"] = {n="Hints of a New Plague?",s="A Colletorto, il gruppo di Phin Odelic cerca segni di guai. Quae e Kinelory mancano da giorni, dopo essere partite per la Fattoria di Go'shek negli Altopiani d'Arathi.",h="A Colletorto, il gruppo di Phin Odelic cerca segni di guai.",kw={"altopiani d'arathi","fattoria di go'shek","alture di colletorto","kinelory","phin odelic","quae","stanley"},sec={{t="Strani avvenimenti",b="Il cugino di Phin Odelic a Colletorto ha dovuto abbattere il suo cane, Stanley. La bestia era diventata enorme per magia e attaccava chiunque si avvicinasse. Phin sospetta che dietro questi strani avvenimenti ci siano i non morti. Perciò il suo gruppo cerca prove che lo confermino."},{t="I compagni scomparsi",b="Quae e Kinelory si sono dirette alla Fattoria di Go'shek negli Altopiani d'Arathi. Non si fanno sentire da giorni e Phin teme per loro. Ti chiede di trovarle vicino alla fattoria."}},faq={{q="Chi è Phin Odelic?",a="Phin Odelic guida un gruppo che indaga su strani avvenimenti nella zona.",al={"phin odelic","chi fornisce indizi su una nuova piaga","datore di missione"}},{q="Cosa è successo a Stanley?",a="Stanley era il cane del cugino di Phin a Colletorto. La bestia era diventata enorme per magia e attaccava chiunque si avvicinasse, così il cugino ha dovuto abbatterla.",al={"cane stanley","cosa è successo al cane","stanley colletorto"}},{q="Dove dovrebbero essere Quae e Kinelory?",a="Quae e Kinelory sono partite per la Fattoria di Go'shek negli Altopiani d'Arathi. Phin non ha loro notizie da giorni.",al={"dove si trova quae","dove si trova kinelory","posizione di quae","trovare quae"}},{q="Perché Phin sta indagando?",a="Phin sospetta che i non morti siano dietro gli strani avvenimenti. Il suo gruppo cerca prove che lo confermino.",al={"perché fattoria di go'shek","fattoria di go'shek non morti","indagare su go'shek"}}},fp="22,165,14.244.0,22.167.0,19.70.0,25.139.0,43.110.0,26.100.0"}
P.entries["quest:66"] = {n="Leggenda di Stalvan",s="La visione di Dama Eva a Borgoscuro nomina Stalvan e preannuncia la morte della nipote Alyssa. Ti manda al Darkshire Town Hall a cercare nei registri.",h="La visione di Dama Eva a Borgoscuro nomina Stalvan e preannuncia la morte della nipote Alyssa.",kw={"alyssa","cancelliere daltry","borgoscuro","carta della morte","boscovespro","dama eva","stalvan","municipio"},ang={["class:Priest"]="Come sacerdote sulle strade oscure di Borgoscuro, puoi dare ascolto agli avvertimenti spirituali. Il presagio di morte di Dama Eva richiede la tua assistenza pastorale.",["faction:Alliance"]="Poiché Boscovespro non riceve regolarmente il sostegno dell'esercito di Roccavento, gli avventurieri dell'Alleanza aiutano spesso gli anziani della città e proteggono famiglie come quella di Dama Eva."},sec={{t="Una visione di morte",b="A Borgoscuro, Dama Eva legge le carte e i presagi per gli abitanti in difficoltà. Un terribile turbamento la strappa al sonno, e per la giovane nipote Alyssa estrae la carta della Morte. Eva cade in una trance profonda per capire il significato del presagio. Le giunge un indizio: il nome Stalvan. Temendo per la famiglia e la città, ti chiede di seguire quella pista prima che la tragedia colpisca."},{t="Richieste al Municipio",b="Dama Eva ti manda ad attraversare la piazza fino al Darkshire Town Hall. Cerca Stalvan nei registri e parla con il Cancelliere Daltry, che custodisce i registri contabili e gli archivi pubblici della città. Può aiutarti a capire se Stalvan abbia vissuto a Borgoscuro, vi sia passato da viaggiatore o appartenga al passato di Boscovespro."}},faq={{q="Chi è Dama Eva?",a="Dama Eva è una chiromante e veggente che vive a Borgoscuro. Legge le carte e cade in trance per cercare presagi e percepire turbamenti magici in tutta Boscovespro.",al={"dama eva","chi è eva","chiromante di borgoscuro"}},{q="Perché Dama Eva ha bisogno di aiuto?",a="Dama Eva teme per la nipote Alyssa dopo una visione di morte. Le sue carte hanno mostrato la carta della Morte, e la trance le ha rivelato il nome Stalvan, perciò cerca aiuto per indagare.",al={"perché iniziare stalvan","visione di eva","perché aiutare eva"}},{q="Chi è il Cancelliere Daltry?",a="Il Cancelliere Daltry custodisce i registri di Borgoscuro nel Municipio. Si occupa dei registri contabili, degli archivi anagrafici e dei documenti storici della città, e puoi chiedergli informazioni sui nomi sconosciuti.",al={"cancelliere daltry","daltry","chi è il cancelliere comunale"}},{q="Cos'è il Darkshire Town Hall?",a="Il Darkshire Town Hall ospita i funzionari della città, i documenti storici e il comando dei The Night Watch.",al={"darkshire town hall","municipio boscovespro"}},{q="Chi è Alyssa?",a="Alyssa è la giovane nipote di Dama Eva e vive a Borgoscuro. La lettura di Eva le ha predetto un presagio mortale, legato a qualcuno di nome Stalvan.",al={"alyssa","nipote di dama eva"}},{q="Dove porta questa indagine?",a="Parlare con il Cancelliere Daltry ti conduce ai registri cittadini e alle indagini precedenti. Da lì, la ricerca si estende a Boscovespro e alle regioni vicine per svelare la storia e il destino di Stalvan.",al={"prossimo passo stalvan","cosa dice daltry"}}},fx={aeb2106e={q="Chi è Stalvan?",a="A questo punto, Stalvan è poco più di un nome oscuro sussurrato durante la divinazione di Dama Eva. Turbata da una premonizione di pericolo mortale che incombe sulla nipote Alyssa, Eva ha consultato le carte ed è entrata in una profonda trance per trovare risposte. Le carte hanno rivelato la morte e un solo nome: Stalvan. Ti viene chiesto di scoprire chi fosse Stalvan consultando i vecchi registri di Borgoscuro.",al={"chi è stalvan","cos'è stalvan"}},["9e863436"]={q="Perché Dama Eva si rivolge a te invece che alla Night Watch?",a="Dama Eva si affida a presagi e divinazioni, non alle indagini convenzionali: è difficile presentare ufficialmente alla Night Watch un nome oscuro emerso da una lettura delle carte. Borgoscuro è già assediata da lupi, ragni e non morti, e la guarnigione locale è impegnata al massimo a difendere il perimetro della città. Le serve un avventuriero indipendente disposto a consultare con discrezione i vecchi registri comunali per conto suo.",al={"perché chiedere a me","perché non le guardie cittadine","perché non la night watch"}}},fp="21,160,17.366.0,22.301.0,18.166.0,30.180.0,20.166.0,28.109.0,14.145.0,40.185.0"}
P.entries["quest:660"] = {n="Hints of a New Plague?",s="Kinelory è pronta a scendere alla fattoria e ti chiede di accompagnarla. Teme che i non morti possano danneggiare Colletorto mentre aspettano. Ha bisogno che tu la riaccompagni sana e salva da Quae.",h="Kinelory è pronta a scendere alla fattoria e ti chiede di accompagnarla.",kw={"scorta","alture di colletorto","hints of a new plague","kinelory","piaga","quae"},sec={{t="Coprire le spalle a Kinelory",b="Dopo le fasi precedenti dell’indagine, Kinelory è pronta ad agire. Ti chiede di accompagnarla alla fattoria e poi di riaccompagnarla sana e salva da Quae. La gente di Colletorto ha bisogno che tu la protegga."},{t="Un ritorno sicuro",b="Quae ti ringrazia quando Kinelory fa ritorno. Ammette di aver sperato che Kinelory non fosse troppo impegnativa. È amichevole, ma letale con i suoi nemici."}},faq={{q="Chi ti invia a fare questa scorta?",a="Kinelory ti chiede di accompagnarla quando è pronta a partire.",al={"datore di missione","chi assegna la missione","chi inizia hints of a new plague 4"}},{q="Dove deve andare Kinelory?",a="Kinelory scende a una fattoria, poi torna da Quae.",al={"percorso scorta","dove va kinelory","destinazione di kinelory"}},{q="A chi devi fare rapporto una volta terminato?",a="Quando Kinelory è tornata da Quae, vai a riferirle l’accaduto.",al={"consegna","chi completa la missione","dove consegnare"}},{q="Cosa è successo subito prima di questa parte dell'indagine?",a="La terza parte di Hints of a New Plague? conduce a questa fase dell’indagine.",al={"missione precedente","prerequisito","cosa viene prima"}},{q="Cosa segue dopo il ritorno al sicuro?",a="L’indagine prosegue con la sua quinta parte.",al={"prossima missione","what comes next","seguito"}},{q="Perché Kinelory deve essere protetta?",a="Kinelory ha bisogno di protezione per poter tornare sana e salva, mentre i non morti potrebbero danneggiare la gente di Colletorto.",al={"perché proteggere kinelory","perché avere a cuore kinelory"}}},fp="22,168,24.188.0,13.154.1,29.62.0,31.51.0,35.53.0,54.83.0,36.48.0,31.101.0"}
P.entries["quest:6608"] = {n="Sei troppo in gamba",s="Lumak ti manda da Orgrimmar a cercare il suo amico Nat Pagle. La tua abilità ha superato le lezioni ordinarie e Nat si accampa su un isolotto remoto a sud dell’Isola di Theramore.",h="Lumak ti manda da Orgrimmar a cercare il suo amico Nat Pagle.",kw={"pesca artigianale","acquemorte","lumak","nat pagle","orgrimmar","theramore","you too good"},ang={["faction:Horde"]="Anche durante la guerra tra le fazioni, le persone possono stringere legami oltre i confini grazie a un mestiere o a un passatempo condiviso.",["race:Orc"]="Da orco, puoi vedere la pazienza, il buonumore e il rispetto per la natura di Lumak nella sua amicizia con un nemico."},sec={{t="I limiti di Lumak",b="Lumak insegna ai pescatori nella Valle dell’Onore di Orgrimmar. Si accorge che hai imparato tutto ciò che poteva insegnarti su canna e mulinello. Perciò ammette che sei troppo bravo per le lezioni ordinarie. La pesca artigianale richiede conoscenze che vanno oltre la città e l’Orda."},{t="Un'amicizia improbabile",b="Lumak ti manda a cercare il suo amico umano, Nat Pagle. Anche se l’Orda e l’Alleanza si scontrano in tutta Kalimdor, ti avverte di non fare del male a Nat e di non mangiarlo. Nat si accampa su un isolotto ad Acquemorte, a sud dell’Isola di Theramore. Si tiene lontano dalla politica e gli importa solo se i pesci abboccano."}},faq={{q="Chi mi assegna questa missione?",a="Lumak, l’istruttore di pesca nella Valle dell’Onore di Orgrimmar, ti manda da Nat quando la tua abilità supera il livello esperto.",al={"chi inizia you too good","lumak datore di missione","dove ottenere you too good"}},{q="Dove si trova Nat Pagle?",a="Nat Pagle si accampa su un isolotto al largo della costa di Acquemorte, a sud dell’Isola di Theramore.",al={"dove si trova nat pagle","posizione di nat pagle","trovare nat pagle"}},{q="Perché un orco ha un amico umano?",a="Lumak e Nat Pagle sono diventati amici grazie alla pesca. La loro passione comune supera l’accesa rivalità tra orchi e umani.",al={"amicizia tra lumak e nat pagle","perché nat pagle è amico di un orco"}},{q="Cosa succede quando parlo con Nat Pagle?",a="Nat Pagle ti sottopone a una prova impegnativa. Viaggi per Azeroth e catturi pesci rari prima che ti insegni altro.",al={"cosa insegna nat pagle","missione pesca artigianale"}},{q="È sicuro attraversare Theramore per l’Orda?",a="No. Theramore è una città fortificata sorvegliata dall’Alleanza. Per raggiungere l’isola di Nat, costeggia la riva o aggira la città per evitare le guardie.",al={"l’orda può attraversare theramore","come raggiungere nat pagle da orda"}},{q="Perché Lumak non può addestrarmi ulteriormente lui stesso?",a="Lumak ti ha insegnato tutto ciò che sa. Nat Pagle può insegnarti la pesca artigianale e i pescatori di tutto il mondo conosciuto lo considerano una leggenda.",al={"perché lumak smette di addestrare","pesca da esperto ad artigiano per l’orda"}}},fp="13,160,14.234.0,22.281.0,27.109.0,27.87.0,36.124.0,39.115.0,44.139.0,41.134.0"}
P.entries["quest:661"] = {n="Hints of a New Plague?",s="Ad Arathi, Quae e Kinelory restano vicino alla fattoria mentre porti notizie a Riva del Sud. Quae ha gli oggetti della fattoria e Kinelory è tornata sana e salva.",h="Ad Arathi, Quae e Kinelory restano vicino alla fattoria mentre porti notizie a Riva del Sud.",kw={"altopiani d'arathi","reietti","colletorto","kinelory","phin odelic","piaga","quae","riva del sud"},sec={{t="Notizie per Riva del Sud",b="Quae è contenta di come ti sei preso cura di Kinelory. Dice che Kinelory è in condizioni migliori di quelle in cui si trova dopo una notte in taverna. Gli oggetti della fattoria dovrebbero aiutare Phin Odelic a capire cosa sta succedendo ad Arathi.\n\nDopo l'attacco alla fattoria, Quae e Kinelory hanno intenzione di restare lì ancora un po', nel caso qualcuno cerchi vendetta. Ti chiedono di tornare a Riva del Sud e parlare con Phin."},{t="La risposta di Phin",b="Phin è felice di sapere che Quae e Kinelory sono vive e vegete. Le definisce amiche insostituibili e compagne di viaggio. A nome dell'intero gruppo, ti ringrazia con un dono.\n\nPhin spera che, con un po' di fortuna, scoprano cosa stanno pianificando i Reietti e riescano a porvi fine."}},faq={{q="Chi ti manda a parlare con Phin Odelic?",a="Quae ti chiede di andare a Riva del Sud una volta che Kinelory sarà tornata sana e salva dalla fattoria.",al={"chi fornisce indizi su a new plague 5","chi inizia a new plague","missione di quae"}},{q="Perché Quae e Kinelory non tornano personalmente a Riva del Sud?",a="Quae e Kinelory hanno intenzione di restare ad Arathi ancora un po', nel caso qualcuno cerchi vendetta per l'attacco alla fattoria.",al={"perché quae resta ad arathi","perché restare indietro","quae che resta"}},{q="Dove si trova Phin Odelic?",a="Phin Odelic è a Riva del Sud.",al={"posizione di phin odelic","dov'è phin","phin odelic riva del sud"}},{q="Qual è lo scopo di portare notizie a Phin Odelic?",a="Gli oggetti che Kinelory ha portato dalla fattoria dovrebbero aiutare Phin Odelic a capire cosa sta succedendo ad Arathi.",al={"perché visitare phin","scopo di phin odelic","cosa vuole phin"}}},fp="22,144,19.375.0,13.283.1,40.77.0,64.110.0,31.29.0,52.104.0"}
P.entries["quest:6611"] = {n="Verso Meccania!",s="A Orgrimmar, Zamja manda a sud cuochi esperti dell'Orda perché imparino da un eccentrico macellaio goblin.",h="A Orgrimmar, Zamja manda a sud cuochi esperti dell'Orda perché imparino da un eccentrico macellaio goblin.",kw={"cucina da artigiano","cucina","dirge pestacarne","meccania","orgrimmar","tanaris","valle della forza","zamja"},ang={["faction:Horde"]="Orgrimmar si affida a specialisti esterni, tra cui cuochi goblin neutrali, per insegnare agli artigiani oltre le basi delle tribù.",["profession:Cooking"]="Da cuoco, arrivi al punto in cui nella capitale non c'è più nulla da imparare. Allora devi avventurarti nelle pericolose terre selvagge per studiare con un maestro artigiano."},sec={{t="Un cuoco supera Orgrimmar",b="Al Varcolargo, Zamja addestra cuochi e sfama guerrieri e viaggiatori di passaggio per Durotar. Quando un cuoco ha imparato ogni ricetta e tecnica che conosce, Zamja gli ha insegnato tutto ciò che poteva. Manda il suo allievo a Tanaris, dove solo un maestro di carni strane ed esotiche può aiutare un cuoco promettente a fare progressi."},{t="Il Macellaio nel deserto",b="Meccania è un centro commerciale alimentato a vapore a Tanaris, gestito dal Cartello degli Spargifumo. Dirge Pestacarne lavora nella locanda della città. L'eccentrico macellaio goblin ha un palato insolito e non si fa scrupoli sul cibo. In tutto Kalimdor è noto per preparare pasti sostanziosi con mostruose creature del deserto e, a volte, ritagli di cuoio, cibo per avventurieri temprati."}},faq={{q="Chi ti manda a Meccania?",a="Zamja, l'istruttrice troll di cucina presso i fuochi da campo nel Varcolargo di Orgrimmar, manda i cuochi che hanno imparato tutto ciò che sa.",al={"datore di missione","chi inizia questa missione","missione di zamja"}},{q="Perché Zamja ti manda via?",a="Zamja ha insegnato tutte le ricette e le tecniche che poteva. Manda i cuochi promettenti da Dirge Pestacarne a Tanaris, un eccentrico esperto che prepara pasti con ingredienti aspri del deserto.",al={"perché meccania","perché dirge pestacarne","maestro di cucina"}},{q="Chi è Dirge Pestacarne?",a="Dirge Pestacarne è un macellaio goblin e un istruttore di cucina artigiano nella locanda di Meccania. Ha un carattere ruvido, idee bizzarre sull'alimentazione e trova proteine nei vecchi stivali di cuoio. Ha imparato a cucinare con ingredienti esotici della natura selvaggia.",al={"chi è dirge","dirge meccania"}},{q="Questa missione è necessaria per imparare la Cucina da Artigiano?",a="No. Il consiglio di Zamja indirizza i cuochi dell'Orda verso Tanaris. Un cuoco abbastanza esperto può recarsi direttamente a Meccania e parlare con Dirge Pestacarne.",al={"ho bisogno di questa missione","missione di collegamento cucina","è obbligatoria"}},{q="Dove si trova Meccania?",a="Meccania è un centro commerciale nel deserto, circondato da mura e gestito dal Cartello degli Spargifumo, nel nord di Tanaris, molto a sud su Kalimdor, oltre Millepicchi.",al={"posizione di meccania","dove si trova dirge"}},{q="Zamja impara davvero qualcosa quando torni?",a="Zamja ti chiede con aria birichina di tornare a insegnarle quando sarai il cuoco più famoso del quartiere. Rimane un'istruttrice esperta a Orgrimmar e si prende cura dei suoi fuochi da campo per la prossima generazione di viaggiatori.",al={"zamja impara a cucinare","insegnare a zamja"}}},fp="20,95,25.295.0,25.364.0,27.117.0,29.181.0,24.239.0,48.146.0,27.138.0,51.194.0"}
P.entries["quest:662"] = {n="Deep Sea Salvage",s="Dopo Land Ho!, il Primo Ufficiale Nilzlix ti chiede di recuperare le carte nautiche e i registri di due relitti prima che qualcuno lasci la baia.",h="Dopo Land Ho!, il Primo Ufficiale Nilzlix ti chiede di recuperare le carte nautiche e i registri di due...",kw={"altopiani d'arathi","baia del bottino","deep sea salvage","harbinger","maiden's folly","nilzlix","o'breen","corno marino","spirit of silverpine"},sec={{t="Due navi perse nella barriera corallina",b="O'Breen portò tre navi nella baia, certo che lì si trovasse un tesoro. La Harbinger attraccò senza problemi. Ma la Maiden's Folly e la Spirit of Silverpine raggiunsero la barriera corallina mentre la marea cominciava a ritirarsi. Entrambe urtarono una struttura simile a un tempio e affondarono rapidamente."},{t="Cosa vuole recuperare Nilzlix",b="Il Primo Ufficiale Nilzlix vuole che tu recuperi i registri e le carte nautiche di entrambi i relitti. Teme che le informazioni finiscano in mani indiscrete. Se i nemici le trovassero, il Contrammiraglio Corno Marino costringerebbe l'equipaggio a camminare sull'asse."}},faq={{q="Perché la Maiden's Folly e la Spirit of Silverpine sono affondate?",a="La Maiden's Folly e la Spirit of Silverpine entrarono nella baia mentre la marea cominciava a ritirarsi. Entrambe urtarono una struttura simile a un tempio nella barriera corallina e affondarono rapidamente.",al={"perché le navi sono naufragate","come sono affondate le navi","causa naufragio baia di arathi"}},{q="Chi è il Primo Ufficiale Nilzlix?",a="Il Primo Ufficiale Nilzlix parla delle tre navi che O'Breen guidò nella baia. Vuole che tu recuperi i registri e le carte nautiche delle due navi affondate.",al={"nilzlix","chi assegna deep sea salvage"}},{q="Perché le carte nautiche e i registri sono così importanti?",a="Nilzlix teme che occhi indiscreti trovino le informazioni lasciate indietro. Dice che, se i nemici se ne impadronissero, il Contrammiraglio Corno Marino costringerebbe l'equipaggio a camminare sull'asse.",al={"perché recuperare i registri","perché carte nautiche e registri"}},{q="Quale nave si è salvata?",a="Solo la Harbinger attraccò in sicurezza nella baia. Le altre due navi affondarono.",al={"quale nave è sopravvissuta","nave harbinger"}},{q="Chi è il Contrammiraglio Corno Marino?",a="Nilzlix indica il Contrammiraglio Corno Marino come colui che costringerebbe l'equipaggio a camminare sull'asse se i registri finissero in mano ai nemici.",al={"ruolo contrammiraglio corno marino","chi è corno marino"}},{q="Cosa precede questo incarico?",a="Land Ho! viene prima di questa storia.",al={"prerequisito deep sea salvage","missione precedente"}}},fp="16,121,26.247.0,23.206.0,57.158.0,26.142.0,41.157.0,28.71.0,28.117.0,27.26.0"}
P.entries["quest:6621"] = {n="Il Re dei Selvalercia",s="All'Avamposto di Zoram'gar, Karang Amakkar ordina un attacco contro i Selvalercia. I campioni dell'Orda piantano uno Stendardo di Guerra sul tumulo dei totem sacro della tribù, attirando il Capo Murgut e uccidendolo.",h="All'Avamposto di Zoram'gar, Karang Amakkar ordina un attacco contro i Selvalercia.",kw={"valtetra","foulweald","furbolg","villaggio di zampaverde","karang amakkar","murgut","tumulo totemico","zoram'gar"},ang={["class:Shaman"]="Da sciamano, riconosci nei totem distorti e nell'aggressività dei Selvalercia i segni dello squilibrio spirituale che ha colpito le tribù native di Valtetra dopo l'invasione della Legione Infuocata.",["faction:Horde"]="Come membro dell'Orda, vedi Karang Amakkar ricorrere a dimostrazioni di forza per intimidire le tribù ostili e assicurare i sentieri centrali alle carovane di rifornimenti dell'Orda.",["race:Orc"]="Da orco, sai che provocare un capo nemico a un duello è una tattica di guerra classica. Premia la forza e lo scontro decisivo invece delle lunghe schermaglie."},sec={{t="Una dimostrazione di forza",b="Dalla sua postazione all'Avamposto di Zoram'gar, Karang Amakkar considera i Selvalercia corrotti una minaccia per l'Orda. La tribù è più piccola dei Thistlefur del nord, ma i suoi membri sono feroci. Così Karang ordina una dimostrazione di forza per spezzarne la volontà, prima che possano tendere imboscate alle pattuglie dell'Orda."},{t="Profanazione e sfida",b="Il Villaggio di Zampaverde si trova a nord-est del Lago Mystral. Karang prepara uno Stendardo di Guerra tribale da piantare al centro del tumulo dei totem dei Selvalercia, insultando gli spiriti ancestrali e l'orgoglio della tribù. I difensori accorrono per abbatterlo e il Capo Murgut emerge per difendere il proprio onore in combattimento aperto. Sottrargli il totem personale spezza la leadership della tribù e afferma la supremazia dell'Orda nella zona."}},faq={{q="Chi ordina la morte del Capo Murgut?",a="Karang Amakkar, un orco all'Avamposto di Zoram'gar sulla costa occidentale di Valtetra, ordina la morte del Capo Murgut dopo aver indagato sui furbolg Thistlefur vicini.",al={"datore di missione king of the foulweald","chi assegna king of the foulweald","missione karang amakkar"}},{q="Dove si trova il Villaggio di Zampaverde?",a="Il Villaggio di Zampaverde si trova a sud-est di Astranaar, a nord-est del Lago Mystral e appena a sud della strada principale che attraversa Valtetra da est.",al={"dove si trova villaggio di zampaverde","posizione foulweald","dove piantare lo stendardo di karang"}},{q="Perché l'Orda pianta uno stendardo sul tumulo dei totem?",a="Lo stendardo di Karang insulta i Selvalercia sul loro tumulo dei totem sacro. La provocazione li spinge ad attaccare e porta il Capo Murgut a combattere allo scoperto per difendere la propria posizione.",al={"perché posizionare lo stendardo","scopo dello stendardo sul tumulo totemico","perché sfidare murgut"}},{q="Chi sono i furbolg Foulweald?",a="I Selvalercia sono una delle tribù di furbolg di Valtetra, impazziti e corrotti dopo la Terza Guerra. Anche se sono meno numerosi dei Thistlefur, restano violenti e ostili agli estranei.",al={"cosa sono i foulweald","storia tribù foulweald","chi è capo murgut"}},{q="Cosa si ottiene recuperando il Totem di Murgut?",a="Portare il totem del Capo Murgut all'Avamposto di Zoram'gar dimostra la sua sconfitta. Senza il loro capo e con il tumulo sacro profanato, i Selvalercia superstiti vengono intimiditi e rinunciano a nuovi scontri con l'Orda.",al={"scopo del totem di murgut","cosa succede dopo la morte di murgut"}},{q="In che modo questa missione si collega alle precedenti indagini sui furbolg?",a="Dopo aver affrontato i Thistlefur del nord in «Between a Rock and a Thistlefur», Karang si dirige a sud, verso i Selvalercia. Vuole schiacciarli prima che possano lanciare incursioni coordinate.",al={"collegamento between a rock and a thistlefur","prerequisito king of the foulweald"}}},fx={b1528232={q="Perché Karang Amakkar vuole che il Capo Murgut venga sconfitto?",a="Karang Amakkar considera la tribù Foulweald una minaccia crescente per la presenza dell'Orda a Valtetra. Anche se sono meno numerosi dei vicini Thistlefur, la loro estrema ferocia li rende un pericolo imprevedibile. Sfidando apertamente il loro capo e uccidendolo, Karang mira a spezzare la loro volontà e a lanciare un avvertimento inequivocabile: l'Orda non tollererà minacce nella foresta.",al={"motivi di karang","perché uccidere murgut","perché sconfiggere i foulweald"}},["9b8cfe09"]={q="Chi è il Capo Murgut?",a="Il Capo Murgut è il feroce leader dei furbolg Foulweald e vive nel Villaggio di Zampaverde, a sud-est di Astranaar. Domina la tribù dal suo sacro tumulo totemico e la guida con la pura forza e l'aggressività territoriale. Karang ti manda a provocarlo e spingerlo allo scontro aperto, profanando il territorio della tribù con uno stendardo di guerra dell'Orda.",al={"chi è murgut","capo murgut dei foulweald","chi è il re dei foulweald"}}},fp="21,189,15.274.0,25.382.0,37.162.0,34.126.0,53.171.0,31.190.0,47.216.0,64.182.0"}
P.entries["quest:6623"] = {n="Istituto di Traumatologia dell'Orda",s="A Requie del Martello, negli Altopiani d'Arathi, Horde Trauma chiama i guaritori esperti in prima linea. Il Dottor Gregory Victor ha bisogno di mani pronte a salvare vite sotto pressione estrema.",h="A Requie del Martello, negli Altopiani d'Arathi, Horde Trauma chiama i guaritori esperti in prima linea.",kw={"altopiani d'arathi","dottor gregory victor","primo soccorso","requie del martello","horde trauma","arnok","triage"},ang={["class:Priest"]="Come sacerdote, puoi rimarginare le ferite con la magia divina. Il triage non magico ti insegna a decidere chi puoi salvare quando il mana si esaurisce.",["faction:Horde"]="Come membro dell'Orda, fai affidamento su chirurghi da campo temprati, che tengono in piedi i fanti e li rimandano a combattere in brutali conflitti di frontiera come quelli degli Altopiani d'Arathi."},sec={{t="Una convocazione da Requie del Martello",b="Nella Valle degli Spiriti di Orgrimmar, Arnok, l'addestratore di primo soccorso orco, dice ai guaritori esperti che hanno attirato l'attenzione del Dottor Gregory Victor. Victor dirige Horde Trauma da Requie del Martello, sulle colline contese degli Altopiani d'Arathi. Arnok considera la convocazione il più alto traguardo nella carriera di un chirurgo da campo."},{t="Il brutale lavoro del triage da campo",b="A Requie del Martello, le continue scaramucce con le forze di Stromgarde e le fazioni locali ostili sommergono il Dottor Victor di fanti, predoni ed esploratori feriti. Il medico capo salta i convenevoli. Manda i nuovi arrivati a indossare il camice, per dimostrare il loro valore in un triage d'emergenza rapido e brutale."}},faq={{q="Che cos'è Horde Trauma?",a="Horde Trauma è il ramo medico e chirurgico dell'Orda in prima linea. Il Dottor Gregory Victor lo dirige da Requie del Martello, dove i suoi membri curano le ferite di guerra e praticano il triage d'emergenza nel caos.",al={"fazione horde trauma","che cos'è horde trauma","chi fa parte di horde trauma"}},{q="Chi mi manda in questa missione?",a="Arnok, l'addestratore di primo soccorso orco nella Valle degli Spiriti di Orgrimmar, invia la convocazione. Considera il servizio agli ordini del Dottor Gregory Victor il più alto traguardo nella carriera di un aspirante medico da campo.",al={"chi assegna horde trauma","chi avvia horde trauma","krenk choplimb","arnok"}},{q="Dove si trova il Dottor Gregory Victor?",a="Il Dottor Gregory Victor è di stanza nell'infermeria di Requie del Martello, negli Altopiani d'Arathi nordorientali.",al={"posizione dottor gregory victor","dov'è victor","medico di requie del martello"}},{q="Cosa succede dopo essersi presentati a Requie del Martello?",a="Al tuo arrivo, il Dottor Victor ti dice di indossare il camice per l'incarico successivo, Triage. In condizioni di forte stress, devi stabilire le priorità e curare i soldati feriti, le cui condizioni peggiorano rapidamente, prima che le ferite abbiano la meglio su di loro.",al={"cosa viene dopo horde trauma","missione successiva a horde trauma","missione triage"}},{q="Perché Requie del Martello ha così tanto bisogno di medici da campo?",a="Requie del Martello è circondata da ostilità ad Arathi e affronta scontri continui con le forze umane, gli agenti del sindacato e le bestie locali. I feriti affluiscono all'accampamento, mettendo a dura prova il suo piccolo personale medico.",al={"perché requie del martello ha bisogno di medici","situazione medica requie del martello"}},{q="I membri dell'Alleanza possono ricevere questo incarico?",a="No. Horde Trauma è riservato ai membri dell'Orda. L'Alleanza ha una valutazione medica equivalente, diretta dal Dottor Gustaf VanHowzen all'Isola di Theramore.",al={"l'alleanza può fare horde trauma","versione dell'alleanza di horde trauma"}}},fx={ac636cdf={q="Perché Arnok mi manda dal Dottor Gregory Victor?",a="Il Dottor Gregory Victor, primario dell'Horde Trauma di stanza a Requie del Martello, ti ha richiesto personalmente. Arnok ha la massima stima per il Dottor Victor e considera imparare da lui un'occasione irripetibile, che a suo dire darebbe qualsiasi cosa per avere lui stesso. Per profondo rispetto professionale e per l'entusiasmo che nutre per il tuo talento, Arnok vuole assicurarsi che tu non sprechi una convocazione tanto rara.",al={"perché krenk vuole questo","motivi di krenk choplimb","perché mandarmi da victor","perché arnок vuole questo","motivi di arnok"}},b6720468={q="Perché il Dottor Victor ha richiesto proprio me?",a="Il Dottor Gregory Victor sta cercando i soccorritori sul campo più capaci dell'Orda da inserire nelle file dell'Horde Trauma negli Altopiani d'Arathi. La tua comprovata padronanza del pronto soccorso ha attirato la sua attenzione a Requie del Martello, spingendolo a convocarti di persona per farti addestrare da lui, invece di reclutare persone senza esperienza o soldati comuni.",al={"perché io per l'horde trauma","perché victor ha bisogno di me","perché il dottor victor mi vuole"}}},fp="12,171,25.318.0,37.292.0,21.204.0,32.190.0,39.111.0,43.233.0,48.221.0,42.145.0"}
P.entries["quest:6625"] = {n="Traumatologia dell'Alleanza",s="In tutta l'Alleanza, i medici più esperti vengono inviati all'Isola di Theramore per prestare servizio. Qui studi sotto la guida del Dottor Gustaf VanHowzen, medico capo del corpo medico d'élite dell'Alleanza.",h="In tutta l'Alleanza, i medici più esperti vengono inviati all'Isola di Theramore per prestare servizio.",kw={"alliance trauma","acquemorte","primo soccorso","forgiardente","nissa pietrardente","theramore","triage","vanhowzen"},ang={["faction:Alliance"]="Alliance Trauma mette medici esperti a disposizione dei combattenti in prima linea di Kalimdor e dei Regni Orientali. Possono stabilizzare ferite critiche anche sotto il fuoco nemico.",["race:Dwarf"]="Se sei un nano, potresti attirare l'attenzione di istruttrici come Nissa Pietrardente a Forgiardente. Cerca praticanti promettenti provenienti dalla Grande Forgia per il servizio medico a Theramore."},sec={{t="Una chiamata al fronte",b="La tua abilità con ago, bende e triage ha attirato l'attenzione del Dottor Gustaf VanHowzen. Dall'Isola di Theramore, dirige Alliance Trauma e cura i feriti nelle zone di guerra più aspre di Kalimdor e oltre."},{t="La strada per Theramore",b="A Forgiardente, Nissa Pietrardente considera un raro privilegio la convocazione personale di VanHowzen. L'Isola di Theramore affronta minacce locali, schermaglie e una natura selvaggia e ostile, perciò i soldati gravemente feriti arrivano senza sosta.\n\nAttraversi il mare fino ad Acquemorte. Qui VanHowzen mette alla prova la calma con cui valuti i feriti, secondo i suoi rigorosi criteri di triage."}},faq={{q="Che cos'è Alliance Trauma?",a="Alliance Trauma è il corpo medico d'élite dell'Alleanza, dedicato alla medicina da campo e al triage d'emergenza. Il medico capo Gustaf VanHowzen lo dirige e cura ferite critiche che le normali medicazioni da campo non possono trattare.",al={"storia di alliance trauma","chi fa parte di alliance trauma"}},{q="Chi ti assegna questa missione?",a="Gli istruttori di primo soccorso dell'Alleanza inviano i praticanti più promettenti dopo che hanno completato l'addestramento standard nelle loro città. Nissa Pietrardente a Forgiardente è una di questi istruttori.",al={"chi dirige alliance trauma","istruttore di primo soccorso forgiardente"}},{q="Dove devi recarti?",a="Raggiungi l'Isola di Theramore, una fortezza portuale umana sulla costa orientale di Kalimdor, ad Acquemorte.",al={"dove si trova vanhowzen","destinazione di alliance trauma"}},{q="Chi è il Dottor Gustaf VanHowzen?",a="Il Dottor Gustaf VanHowzen dirige Alliance Trauma in qualità di medico capo. Lavora nella clinica militare di Theramore ed è una delle massime autorità dell'Alleanza in materia di medicina d'emergenza e triage chirurgico.",al={"gustaf vanhowzen","medico capo vanhowzen"}},{q="Cosa succede dopo essersi presentati al Dottor VanHowzen?",a="A Theramore, VanHowzen sottopone i candidati a una prova pratica di triage. Devono dimostrare di saper salvare ondate di soldati in fin di vita prima che lui li ammetta ai gradi superiori della medicina da campo.",al={"cosa viene dopo alliance trauma","prossima missione triage"}},{q="Perché la clinica ha sede a Theramore invece che a Roccavento o Forgiardente?",a="Theramore è un presidio di frontiera attivo, tra paludi ostili, bestie pericolose e schermaglie territoriali. I soldati gravemente feriti arrivano di continuo, sottoponendo la clinica alla pressione costante necessaria per l'addestramento avanzato in traumatologia.",al={"perché la clinica di theramore","perché acquemorte per i traumi"}}},fx={a452e047={q="Perché Nissa Firestone ti manda a Theramore?",a="Il Dottor Gustaf VanHowzen, primario dell'Alliance Trauma, ti ha chiesto personalmente di unirti alla sua squadra a Theramore. Nissa Pietrardente nutre la massima stima per il rinomato chirurgo e considera lavorare al suo fianco un onore senza pari. Ti trasmette la convocazione perché vuole assicurarsi che tu non sprechi un'occasione medica tanto rara.",al={"perché nissa vuole che lo faccia","motivi di nissa pietrardente","perché mandarmi a theramore"}},a6ba6381={q="Perché il Dottor VanHowzen ha chiesto proprio te?",a="Il Dottor Gustaf VanHowzen ha bisogno di soccorritori sul campo capaci ed esperti, in grado di gestire gravi feriti sotto pressione. Avendo dimostrato una padronanza eccezionale del pronto soccorso, hai attirato l'attenzione del corpo chirurgico di alto grado dell'Alleanza. VanHowzen ti ha quindi convocato personalmente a Theramore per valutare le tue abilità in condizioni di battaglia.",al={"perché io per l'alliance trauma","perché vanhowzen mi vuole","perché mandare il giocatore a theramore"}}},fp="15,183,19.199.0,21.353.0,24.216.0,28.169.0,28.100.0,31.206.0,49.183.0,71.231.0"}
P.entries["quest:6626"] = {n="A Host of Evil",s="Myriam Moonsinger ti chiede di affrontare i difensori e i cultisti dei Sotterranei di Lamaspina. È la loro presenza il problema che ti manda a risolvere.",h="Myriam Moonsinger ti chiede di affrontare i difensori e i cultisti dei Sotterranei di Lamaspina.",kw={"una schiera di malvagi","death's head cultists","myriam moonsinger","razorfen battleguard","sotterranei di lamaspina","razorfen thornweavers"},sec={{t="La richiesta di Myriam",b="Vicino all'ingresso dei Sotterranei di Lamaspina, Myriam Moonsinger ti chiede di affrontare i Razorfen Battleguard, i Razorfen Thornweavers e i Death's Head Cultists che si trovano all'interno. Si aspetta che tu torni da lei dopo averli sistemati."}},faq={{q="Chi chiede aiuto ai Sotterranei di Lamaspina?",a="Myriam Moonsinger, vicino all'ingresso dei Sotterranei di Lamaspina, ti chiede di affrontare i suoi difensori e cultisti.",al={"chi è myriam","myriam moonsinger"}},{q="Quali nemici nomina Myriam?",a="Myriam nomina i Razorfen Battleguard, i Razorfen Thornweavers e i Death's Head Cultists.",al={"chi devo affrontare","nemici di lamaspina"}},{q="Dove torno da Myriam?",a="Torna da Myriam Moonsinger vicino all'ingresso dei Sotterranei di Lamaspina.",al={"dov'è myriam","posizione di myriam"}}},fp="14,136,18.212.0,36.104.0,31.84.0,28.64.0"}
P.entries["quest:6627"] = {n="Test of Lore",s="Presso il rifugio di Braug Spirito Vago, nelle Vette di Petrartiglio, affronti una prova di storia antica. Dopo aver recuperato il tomo Eredità degli Aspetti, devi dimostrare di averne appreso le lezioni. Una risposta errata ti spedisce lontano, attraverso Kalimdor.",h="Presso il rifugio di Braug Spirito Vago, nelle Vette di Petrartiglio, affronti una prova di storia antica.",kw={"aspetti","braug spirito vago","guardiano della terra","neltharion","vette di petrartiglio","taurajo","test of faith","recesso logoro"},ang={["class:Mage"]="Da mago, potresti riconoscere l'abilità dietro la barriera di teletrasporto di Braug. Gli eremiti delle Vette di Petrartiglio usano la magia antica per disciplinare gli studiosi sbadati.",["faction:Horde"]="Come membro dell'Orda, affronti prove a Kalimdor che richiedono più della forza bruta. Guerrieri e sciamani devono comprendere le antiche cicatrici e i poteri draconici che hanno plasmato il continente.",["race:Tauren"]="Come tauren, onori la saggezza ancestrale e la storia antica. Questa prova chiede ai giovani campioni di comprendere l'equilibrio del mondo prima di marciare incontro al pericolo."},sec={{t="Una Prova di Saggezza",b="La prova di Braug Spirito Vago prosegue quelle iniziate da Dorn Plainstalker al Recesso Logoro. Richiede comprensione, non sopravvivenza in battaglia né fiducia cieca. Braug vive tra le rupi delle Vette di Petrartiglio. Si aspetta che i cercatori recuperino testi antichi e imparino dalle loro pagine."},{t="Eredità degli Aspetti",b="La lezione riguarda la creazione e la divisione degli Aspetti dei Draghi e il patto che strinsero molto prima della Grande Separazione. Braug ti chiede cosa dice il tomo sul Guardiano della Terra, Neltharion. La sua follia e il suo tradimento hanno rimodellato la superficie di Azeroth. Devi comprendere questa storia prima di proseguire sul sentiero della saggezza."},{t="Il Prezzo delle Congetture",b="Braug Spirito Vago allontana con mezzi mistici i cercatori che rispondono in modo errato. Una risposta sbagliata ti porta a Camp Taurajo, nelle Savane Meridionali, lontano dall'eremita. Per affrontare di nuovo il giudizio di Braug, devi tornare nelle Vette di Petrartiglio con un lungo viaggio."}},faq={{q="Qual è la risposta alla domanda di Braug Spirito Vago?",a="Braug ti chiede di nominare il Guardiano della Terra in Eredità degli Aspetti. La risposta è Neltharion, l'Aspetto Nero che si rivoltò contro gli altri draghi.",al={"risposta domanda braug","risposta test of lore","domanda eredità degli aspetti"}},{q="Cosa succede se rispondi in modo errato?",a="Una risposta errata ti bandisce subito per magia a Camp Taurajo, nelle Savane. Per riprovare, devi tornare al rifugio di Braug nelle Vette di Petrartiglio.",al={"risposta sbagliata test of lore","test of lore fallito","teletrasportato a taurajo"}},{q="Chi è Braug Spirito Vago?",a="Braug Spirito Vago è un anziano eremita nelle Vette di Petrartiglio che mette alla prova la conoscenza e il sapere dell'Orda. Prosegue le prove spirituali iniziate da Dorn Plainstalker a Millepicchi.",al={"braug spirito vago","chi offre test of lore"}},{q="Come si collega questo alle prove di Millepicchi?",a="Dorn Plainstalker iniziò le prove al Recesso Logoro, a Millepicchi, con il Test of Faith. Dopo aver messo alla prova la fiducia fisica e spirituale, Dorn manda gli iniziati meritevoli attraverso Kalimdor da anziani che ne mettono alla prova intelletto, determinazione e forza.",al={"collegamento dorn plainstalker","catena test of faith"}},{q="Di quale libro ti sta interrogando Braug?",a="Braug mette alla prova la tua comprensione di Eredità degli Aspetti, un antico trattato sui titani che benedissero i cinque Grandi Aspetti dei Draghi affinché proteggessero Azeroth.",al={"che libro braug","eredità degli aspetti"}},{q="Dove porta questa catena di missioni?",a="Superare la prova di Braug sugli Aspetti dei Draghi apre la strada ad altre indagini sulla storia antica. I cercatori devono esplorare regioni lontane alla ricerca di testimonianze perdute e conoscenze ancestrali.",al={"cosa c'è dopo test of lore","prossima missione in test of lore"}}},fx={a70a9b29={q="Perché Braug Spirito Vago ti sta mettendo alla prova?",a="Braug Spirito Vago fa da esaminatore nelle prove iniziate a Millepicchi. Mentre le altre prove mettono alla prova la tua abilità marziale o la tua fede, il Test of Lore serve a verificare che tu non faccia affidamento soltanto sulla forza bruta. Chiedendoti di recuperare testi antichi e comprenderne il contenuto, Braug mira a coltivare la saggezza e la conoscenza della storia in chi aspira a rappresentare l'Orda.",al={"perché braug ti mette alla prova","scopo di braug spirito vago","perché il test of lore"}}},fp="12,217,17.284.0,21.322.0,22.247.1,49.147.0,39.164.0,23.185.0,56.247.0,38.150.0,38.176.0"}
P.entries["quest:6628"] = {n="Test of Lore",s="A Sepulcra, gli iniziati affrontano una prova di storia con Parqual Fintallas. Hanno setacciato il mondo alla ricerca di testi storici, e questo esame fa parte delle prove spirituali iniziate a Millepicchi.",h="A Sepulcra, gli iniziati affrontano una prova di storia con Parqual Fintallas.",kw={"dorn plainstalker","re dei lich","marchio della vergogna","nerzhul","parqual fintallas","test of lore","millepicchi","sepulcra","recesso logoro"},ang={["faction:Horde"]="Come membro dell'Orda, rafforzi i legami tra le tribù di Kalimdor e il regno sotto Lordaeron, e impari che la saggezza è importante per sopravvivere quanto la forza.",["race:Tauren"]="Come tauren, segui un'antica tradizione che ti manda a conoscere le cupe vicende dei tuoi alleati Reietti del nord e del mondo oltre Kalimdor.",["race:Undead"]="Come non morto, affronti una storia legata all'identità dei Reietti: la tragica trasformazione di Ner'zhul e la maledizione che ti teneva prigioniero, prima che Sylvanas spezzasse la presa del Re dei Lich."},sec={{t="Una Prova di Conoscenza",b="Il Test of Lore è una delle prove spirituali iniziate a Millepicchi. Dorn Plainstalker ha istituito le prove al Recesso Logoro. Questo esame porta i candidati dai canyon scolpiti dal vento di Millepicchi a Sepulcra, dove Parqual Fintallas mette alla prova la loro conoscenza della storia e pretende molto da ogni cercatore."},{t="Le origini del Flagello",b="Parqual Fintallas esamina gli iniziati sul libro «Inizi della Minaccia Non Morta», che racconta come ebbe inizio il Flagello a Lordaeron. Chiede chi fosse l'essere sul Trono di Ghiaccio: Ner'zhul, un tempo anziano sciamano, la cui essenza la Legione Infuocata forgiò nel Re dei Lich. Questa cupa discendenza aiuta a spiegare l'esistenza dei Reietti e i pericoli che minacciano Kalimdor e i Regni Orientali."}},faq={{q="Qual è la risposta alla domanda di Parqual?",a="Parqual Fintallas chiede il nome originale del Re dei Lich: Ner'zhul, l'antico sciamano orco il cui spirito fu legato al Trono di Ghiaccio.",al={"risposta re dei lich","domanda di parqual","risposta test of lore"}},{q="Cosa succede se si risponde male alla domanda?",a="Una risposta sbagliata ti infligge il debuff Marchio della Vergogna. Devi attendere che la penalità svanisca prima che Parqual ti permetta di riprovare l'esame.",al={"marchio della vergogna","risposta sbagliata test of lore"}},{q="Dove inizia questa catena di missioni?",a="Dorn Plainstalker dà inizio alla più ampia serie di prove spirituali al Recesso Logoro, a Millepicchi, tra le sue imponenti guglie.",al={"dove inizia il test of lore","serie di missioni di dorn plainstalker"}},{q="Dove si trova Parqual Fintallas?",a="Parqual Fintallas si trova a Sepulcra, tra le biblioteche sotterranee e i corridoi dei Reietti, dove esamina gli aspiranti studenti.",al={"trovare parqual","posizione di parqual fintallas"}},{q="Su quale testo si basa questa prova?",a="La prova si basa su «Inizi della Minaccia Non Morta», un libro sulle origini della Piaga dei Non Morti e sulla creazione del Re dei Lich.",al={"quale libro per il test of lore","libro degli inizi"}},{q="Perché una missione di Millepicchi manda a Sepulcra?",a="Le prove dei tauren mettono alla prova ogni aspetto di un avventuriero. Per questo esame, i candidati attraversano il mare in cerca di documenti storici custoditi nelle rovine di Lordaeron.",al={"perché andare a sepulcra","millepicchi sepulcra"}}},fx={b37475e3={q="Perché Parqual Fintallas vuole che venga fatto?",a="Parqual Fintallas sta mettendo alla prova la tua dedizione alla ricerca della conoscenza. Ritiene che la conoscenza sia fondamentale per sopravvivere in questo mondo pericoloso: più impari e osservi, più verità riuscirai a scorgere. Dopo averti incaricato di procurarti il tomo sulla Minaccia dei Non Morti, pretende la prova che tu ne abbia davvero studiato e assimilato la cupa storia, invece di esserti limitato a sbrigare una commissione.",al={"motivi di parqual","perché parqual mi mette alla prova","perché il test of lore"}}},fp="12,200,20.332.0,21.381.1,41.135.0,46.131.0,34.131.0,35.136.0,33.135.0,60.163.0"}
P.entries["quest:6629"] = {n="Kill Grundig Darkcloud",s="All'Avamposto dei Totem Truce, Grundig Darkcloud attende dopo aver guidato la forza che ha saccheggiato la casa di Makaba Zoccolo Piatto. Makaba ti manda a cercare Grundig dopo che hai abbattuto i ruffiani e i mercenari.",h="All'Avamposto dei Totem Truce, Grundig Darkcloud attende dopo aver guidato la forza che ha saccheggiato la...",kw={"bruto","darkcloud","zoccolo piatto","totem truce","grundig","makaba","avamposto","vette di petrartiglio"},ang={["faction:Horde"]="Come membro dell'Orda, sai che le Vette di Petrartiglio sono importanti per la tua avanzata a Kalimdor. Condottieri come Grundig minacciano le rotte di rifornimento tra le Savane e il Rifugio Roccia del Sole.",["race:Tauren"]="Come tauren, vedi che il massacro di Grundig approfondisce le divisioni tra la tua gente. I Totem Truce si oppongono all'unità sotto l'Orda con la forza spietata."},sec={{t="Il Macellaio del Sentiero",b="Makaba Zoccolo Piatto è sopravvissuto all'assalto dei Totem Truce al suo insediamento lungo il sentiero delle Vette di Petrartiglio, ma il dolore lo opprime ancora. Hai dimostrato il tuo valore contro i fanti dei Totem Truce. Ora Makaba ti indica Grundig Darkcloud, che ha guidato il massacro che ha raso al suolo il villaggio e comanda una banda di bruti a lui devota."},{t="Colpisci l'Avamposto dei Totem Truce",b="Grundig si accampa all'Avamposto dei Totem Truce, più avanti sulla strada di montagna verso ovest. Sali alla roccaforte per vendicare i parenti di Makaba e proteggere il passo da ulteriori violenze. Lì affronti i bruti di Grundig e lo uccidi prima che i suoi predoni possano assalire altri accampamenti vulnerabili."}},faq={{q="Chi è Grundig Darkcloud?",a="Grundig Darkcloud comanda i Totem Truce all'Avamposto dei Totem Truce, nel sud-est delle Vette di Petrartiglio. Ha guidato l'attacco che ha distrutto il villaggio di Makaba Zoccolo Piatto.",al={"grundig darkcloud","chi è grundig","capo totem truce"}},{q="Dove si può trovare Grundig Darkcloud?",a="Grundig Darkcloud si trova all'Avamposto dei Totem Truce, sul sentiero di montagna a ovest dell'accampamento di Makaba Zoccolo Piatto, vicino al confine delle Savane.",al={"posizione grundig","dove si trova grundig","posizione avamposto totem truce"}},{q="Qual è il motivo di Makaba Zoccolo Piatto per questo incarico?",a="Makaba Zoccolo Piatto ha visto i Totem Truce massacrare la sua famiglia e i suoi compagni di clan. Dopo che hai abbattuto i loro ruffiani e mercenari, ti chiede di uccidere il loro capo, Grundig Darkcloud, per vendetta.",al={"perché uccidere grundig","storia di makaba","vendetta di makaba"}},{q="Perché i Totem Truce stanno attaccando insediamenti pacifici qui?",a="I Totem Truce disprezzano le altre tribù tauren, soprattutto quelle alleate con l'Orda o che seguono vie più pacifiche. Tendono imboscate e razziano i clan rivali per scacciarli dalle terre che vogliono controllare.",al={"perché attaccano i totem truce","ostilità dei totem truce"}},{q="Cosa succede dopo aver ucciso Grundig Darkcloud?",a="Dopo aver ucciso Grundig Darkcloud e i suoi bruti, la vendetta di Makaba Zoccolo Piatto è compiuta. Può piangere il suo villaggio sapendo che è stata fatta giustizia.",al={"cosa fare dopo grundig","continuazione catena zoccolo piatto"}},{q="Qual è la missione prerequisito per questo incarico?",a="Prima, completa Avenge My Village. Lì Makaba Zoccolo Piatto mette alla prova la tua determinazione mandandoti contro ruffiani e mercenari dei Totem Truce accampati poco più a ovest.",al={"prerequisito uccidere grundig","missione prima di grundig"}}},fx={ce2e4f2e={q="Perché Makaba Zoccolo Piatto ha bisogno del tuo aiuto invece di affrontare Grundig da solo?",a="Makaba Zoccolo Piatto è un solitario sopravvissuto, bloccato sulla strada di montagna e devastato dal massacro del suo villaggio. Grundig Darkcloud comanda l'Avamposto dei Totem Truce, protetto da una guardia personale di selvaggi bruti: una difesa troppo imponente perché un tauren ferito e rimasto solo possa affrontarlo direttamente. Avendoti visto abbattere i predoni semplici, Makaba affida ogni speranza di vendetta alla tua abilità in combattimento.",al={"perché io, makaba","perché makaba zoccolo piatto non affronta grundig","perché mandarmi a uccidere grundig darkcloud"}}},fp="22,189,23.315.0,24.279.0,25.156.0,37.117.0,47.190.0,58.198.0,43.147.0,45.159.0"}
P.entries["quest:663"] = {n="Land Ho!",s="Alla Baia di Faldir, Lolo avverte che la breve sosta del Capitano O'Breen potrebbe durare molto più del previsto. La Spirit of Silverpine e la Maiden's Folly sono perdute, e Lolo ti indirizza dal capitano.",h="Alla Baia di Faldir, Lolo avverte che la breve sosta del Capitano O'Breen potrebbe durare molto più del...",kw={"baia del bottino","baia di faldir","harbinger","lolo la vedetta","maiden's folly","seahorn","shakes o'breen","spirit of silverpine"},sec={{t="Il benvenuto di Lolo",b="Lolo ti accoglie alla Baia di Faldir e ti racconta cosa è andato storto. Il Capitano O'Breen aveva promesso all'equipaggio solo poche ore a terra per raccogliere tesori, prima di salpare per tornare alla Baia del Bottino. Lolo dubita che resteranno via così poco.\n\nLa Spirit of Silverpine e la Maiden's Folly, due navi della formazione, ora giacciono sul fondo del mare. Se vuoi restare, Lolo ti dice di parlare con il capitano."},{t="Il resoconto del Capitano",b="Il Capitano O'Breen teme che Seahorn si prenderà la nave se la notizia del disastro si diffonde. Un marchingegno del Professore indicava un tesoro perduto vicino alla Baia di Faldir. Così la Harbinger vi attraccò e segnalò alle altre due navi di seguirla.\n\nPoi il mare rimbombò e l'acqua si ritirò. Entrambe le navi urtarono la barriera corallina. O'Breen dice che non è una barriera come le altre e che qualcosa si nasconde là sotto. Promette un generoso compenso a chiunque aiuti l'equipaggio."}},faq={{q="Cosa è successo alle altre navi?",a="La Spirit of Silverpine e la Maiden's Folly sono andate perdute e ora giacciono sul fondo del mare.",al={"dove sono le altre navi","navi affondate baia di faldir","cosa ha affondato le navi"}},{q="Perché l'equipaggio è venuto alla Baia di Faldir?",a="Il Capitano O'Breen condusse l'equipaggio alla Baia di Faldir per raccogliere tesori. Pensavano di restare solo poche ore prima di salpare per tornare alla Baia del Bottino.",al={"perché sono qui","scopo della spedizione","cosa li ha portati ad arathi"}},{q="Con chi dovresti parlare alla Baia di Faldir?",a="Lolo, la vedetta, ti suggerisce di parlare con il Capitano O'Breen alla Baia di Faldir se hai intenzione di restare.",al={"chi è il capitano o'breen","dov'è shakes o'breen"}}},fp="8,195,14.382.0,21.442.1,33.87.0,39.142.0,40.94.0"}
P.entries["quest:664"] = {n="Drowned Sorrows",s="Alla Baia di Faldir, il Capitano Panciadura piange la Maiden's Folly e ti chiede di uccidere i naga Daggerspine che hanno assassinato i superstiti del naufragio.",h="Alla Baia di Faldir, il Capitano Panciadura piange la Maiden's Folly e ti chiede di uccidere i naga...",kw={"arathi","daggerspine","baia di faldir","maiden's folly","naga","o'breen","razziatore","incantatrice","panciadura"},sec={{t="Un capitano davanti al fuoco",b="Alla Baia di Faldir, il Capitano Panciadura siede accanto al fuoco e vorrebbe che il mare avesse preso anche lui. Il suo equipaggio ha lottato duramente per salvare la Maiden's Folly, ma l'acqua è entrata tutta in una volta e la nave è affondata. O'Breen è riuscito a raggiungere la riva sano e salvo, mentre i naga hanno ucciso gli altri superstiti. Panciadura vuole che muoiano dieci razziatori Daggerspine e tre incantatrici Daggerspine."}},faq={{q="Chi è il Capitano Panciadura?",a="Il Capitano Panciadura comandava la Maiden's Folly. Dopo aver perso la nave, si è seduto accanto a un fuoco alla Baia di Faldir.",al={"capitano panciadura","panciadura","chi è il datore di missione"}},{q="Cosa è successo alla Maiden's Folly?",a="Panciadura dice che il mare ha affondato la Maiden's Folly. La nave era a galla, poi l'acqua è entrata tutta in una volta, nonostante i duri sforzi dell'equipaggio per salvarla.",al={"maidens folly","cosa è successo alla nave","perché panciadura è naufragato"}},{q="Perché il Capitano Panciadura vuole che i naga vengano uccisi?",a="I naga hanno ucciso i superstiti del naufragio, e Panciadura li vuole morti.",al={"perché uccidere i naga","vendetta di panciadura","motivo dei daggerspine"}},{q="Quali naga vuole morti il Capitano Panciadura?",a="Dieci razziatori Daggerspine e tre incantatrici Daggerspine, come chiede Panciadura.",al={"quali naga uccidere","naga bersaglio","bersagli daggerspine"}}},fp="15,134,21.341.0,24.106.0,36.142.0,47.68.0,35.76.0"}
P.entries["quest:6641"] = {n="Vorsha la Sferzatrice",s="All'Avamposto di Zoram'gar, gli attacchi di Vorsha la Frustatrice minacciano la presenza dell'Orda sulla costa di Valtetra. I naga dei dintorni onorano l'idra con un braciere votivo su un'isola al largo. Spaccamusi deve spegnerne la fiamma e attirare Vorsha a riva.",h="All'Avamposto di Zoram'gar, gli attacchi di Vorsha la Frustatrice minacciano la presenza dell'Orda sulla...",kw={"valtetra","braciere","idra","spaccamusi","naga","vorsha","spiaggia di zoram","zoram'gar"},ang={["faction:Horde"]="Difendere l'Avamposto di Zoram'gar preserva la presenza settentrionale dell'Orda a Valtetra e le sue linee logistiche, anche se i rifornimenti sono costantemente sotto attacco.",["race:Orc"]="In quanto orco, potresti condividere il rifiuto di Spaccamusi di rintanarsi dietro palizzate improvvisate. Sceglie di lanciarsi tra i flutti e dare la caccia faccia a faccia alle bestie predatrici."},sec={{t="Un terrore dagli abissi",b="Sulla costa nord-occidentale di Valtetra, la Spiaggia di Zoram è uno dei tratti più pericolosi. L'Avamposto di Zoram'gar presidia una stretta striscia di costa, esposta alla fauna ostile, agli elfi della notte e agli invasori serpentini. Vorsha la Frustatrice è una delle minacce peggiori della spiaggia. L'idra gigantesca assale l'avamposto senza provocazione.\n\nIrrompe tra i flutti per abbatterne le difese e massacrarne i guerrieri. Poi svanisce nelle maree profonde."},{t="Il braciere dei naga",b="I naga dei dintorni onorano la violenza vorace di Vorsha. Su uno sperone roccioso al largo, tengono acceso per lei un braciere votivo. Spaccamusi, un orco deciso a porre fine alle continue aggressioni contro l'avamposto, ha trovato il modo di stanare l'idra.\n\nProfanare la fiamma rituale farà infuriare i naga guardiani e Vorsha. Accecata dalla furia, l'idra emergerà in superficie, dando ai difensori l'occasione di attirarla in un'imboscata invece di attendere un altro massacro."}},faq={{q="Chi è Vorsha la Frustatrice?",a="Vorsha la Frustatrice è un'idra enorme e feroce che infesta le acque al largo della Spiaggia di Zoram. Spesso attacca senza provocazione l'Avamposto di Zoram'gar, distruggendone le difese e massacrando il personale dell'Orda.",al={"vorsha","cos'è vorsha","idra vorsha"}},{q="Perché i naga onorano Vorsha?",a="I naga della Spiaggia di Zoram onorano Vorsha per la sua ferocia implacabile e il suo appetito distruttivo. Tengono acceso al largo un braciere in tributo alla sua natura malvagia.",al={"perché i naga amano l'idra","braciere naga di vorsha","perché venerano vorsha"}},{q="Come viene attirata Vorsha per combattere?",a="Spaccamusi guida l'assalto all'isola dove i naga alimentano il braciere di Vorsha. Spegnere la fiamma sacra fa infuriare i naga guardiani e Vorsha, spingendo l'idra a emergere per vendicarsi.",al={"come evocare vorsha","come chiamare vorsha","isola del braciere vorsha"}},{q="Chi è Spaccamusi?",a="Spaccamusi è un orco di stanza all'Avamposto di Zoram'gar. Stanco degli attacchi costieri senza provocazione di Vorsha, ha intenzione di spegnere il braciere rituale dei naga e affrontare la bestia insieme ad alleati fidati.",al={"chi è spaccamusi","orco spaccamusi","zoram'gar spaccamusi"}},{q="Perché l'Avamposto di Zoram'gar è vulnerabile alle bestie costiere?",a="L'Avamposto di Zoram'gar è un campo isolato di frontiera sulle spiagge esposte di Valtetra. I naga dominano le rovine marine, mentre idre selvagge pattugliano i flutti, lasciando l'avamposto esposto agli attacchi anfibi da ogni direzione.",al={"perché zoram'gar è sotto attacco","pericolo spiaggia di zoram"}},{q="Cosa succede dopo che Vorsha viene uccisa?",a="Dopo l'uccisione di Vorsha, la vittoria viene riferita ai Warsong Runners, che presidiano le linee all'Avamposto di Zoram'gar. Il costante fardello delle guardie di frontiera si alleggerisce e la costa vicina è al sicuro dagli attacchi improvvisi.",al={"consegna missione vorsha","a chi riferire di vorsha"}}},fx={["4cca3bd5"]={q="Perché Muglash vuole che Vorsha venga uccisa?",a="Vorsha è una minaccia costante per l'Avamposto di Zoram'gar. La feroce idra emerge ripetutamente dal mare senza essere provocata, devastando le forze dell'Orda e chiunque altro si trovi lungo il suo cammino sulla costa. Muglash vuole porre fine una volta per tutte a queste incursioni devastanti affrontando la bestia nel suo sacro luogo di evocazione.",al={"motivi di muglash","perché uccidere vorsha","perché affrontare vorsha"}},["23eb1be6"]={q="Perché Muglash ha bisogno del tuo aiuto contro Vorsha?",a="Per uccidere Vorsha bisogna raggiungere un'isola occupata dai naga della costa e spegnere il braciere sacro che tengono in suo onore. Muglash intende combattere al tuo fianco, ma sa che il rituale attirerà non solo l'enorme idra, ma anche ondate di furiosi difensori naga. Un solo guerriero non può tenere a bada tanti nemici da solo.",al={"perché muglash ha bisogno di aiuto","perché le guardie dell'orda non affrontano vorsha","perché io, muglash"}}},fp="17,243,22.435.0,23.448.0,25.200.0,29.163.0,33.193.0,15.192.0,54.209.0,35.213.1"}
P.entries["quest:665"] = {n="Sunken Treasure",s="Il Professor Vitestorta e il Dottor Erbanera aiutano ora i Blackwater Raiders a cercare un tesoro elfico perduto. Prima che la ricerca possa iniziare, il professore ha bisogno della tua protezione mentre carica gli occhiali per il mare oscuro.",h="Il Professor Vitestorta e il Dottor Erbanera aiutano ora i Blackwater Raiders a cercare un tesoro elfico...",kw={"altopiani d'arathi","blackwater raiders","erbanera","pietra incantata","occhiali","o'breen","vitestorta","sunken treasure"},sec={{t="Caricare gli occhiali",b="Il Professor Vitestorta ti chiede di proteggerlo mentre si prepara a cercare sotto il mare oscuro. Il Dottor Erbanera ha costruito degli occhiali per trovare le gemme perdute, ma hanno bisogno dell’energia di una pietra incantata in una grotta poco più in alto. La grotta è maledetta e chi si avvicina subisce un’imboscata. Difendi il professore mentre incanala l’energia della pietra negli occhiali."}},faq={{q="Chi sta chiedendo aiuto?",a="Il Professor Vitestorta ti chiede di proteggerlo durante il tragitto da e verso la grotta, mentre carica gli occhiali del Dottor Erbanera presso la pietra incantata.",al={"chi assegna questa missione","vitestorta","concedente missione"}},{q="Perché gli occhiali devono essere caricati?",a="Il Dottor Erbanera ha costruito gli occhiali per trovare le gemme perdute nel mare oscuro. Prima di poter funzionare, hanno bisogno dell’energia della pietra.",al={"perché caricare occhiali","scopo occhiali","a cosa servono gli occhiali"}},{q="Perché il professore ha bisogno di una scorta?",a="La grotta è maledetta e chi si avvicina subisce un’imboscata. Devi difendere il Professor Vitestorta mentre incanala l’energia della pietra.",al={"perché proteggere vitestorta","cosa c'è nella caverna"}},{q="Per chi lavorano il professore e il dottore?",a="Il Professor Vitestorta dice che lui e il Dottor Erbanera sono ormai membri a tutti gli effetti dei Blackwater Raiders. Il loro compito è aiutare il Sig. O’Breen a trovare il tesoro elfico perduto.",al={"chi stanno aiutando","sig obreen","blackwater raiders"}}},fp="15,226,20.358.0,23.149.0,38.127.0,38.140.0,49.161.0"}
P.entries["quest:666"] = {n="Sunken Treasure",s="A Baia di Faldir, il Dottor Erbanera ti presta i suoi occhialini per trovare dieci gemme elfiche per il Capitano O'Breen. Si aspetta che tu glieli restituisca quando avrai finito.",h="A Baia di Faldir, il Dottor Erbanera ti presta i suoi occhialini per trovare dieci gemme elfiche per il...",kw={"altopiani d'arathi","capitano o'breen","dottor erbanera","gemma elfica","baia di faldir","contrammiraglio corno marino","occhialini della caccia alle gemme","sunken treasure"},sec={{t="Gemme Pietrificate",b="Le gemme elfiche sono rimaste sul fondale marino così a lungo che attorno a esse si è indurita una spessa crosta di pietra. Gli Occhialini della Caccia alle Gemme permettono di trovarle attraverso quei gusci di pietra. Orgoglioso dell'ingegno gnomico che li ha resi possibili, il Dottor Erbanera te li presta. Le gemme sono per il Capitano O'Breen."},{t="Terra Asciutta per il Dottore",b="Il Dottor Erbanera dice che il lavoro scientifico lo tiene sulla terraferma, al sicuro e all'asciutto, anche se potrebbe immergersi lui stesso. Si aspetta che gli restituisca gli occhialini in seguito. Dice che il Capitano O'Breen ne avrà parecchio bisogno."}},faq={{q="Chi ti manda a raccogliere le gemme?",a="Il Dottor Erbanera, in attesa alla Baia di Faldir, ti manda a raccogliere dieci gemme elfiche per il Capitano O'Breen.",al={"chi dà sunken treasure 2","chi dà la missione sunken treasure"}},{q="Perché servono degli occhiali speciali per la ricerca?",a="Dopo anni sul fondale marino, attorno alle gemme si è indurita una spessa crosta di pietra. Il potere degli Occhialini della Caccia alle Gemme ti permette di trovarle facilmente.",al={"perché occhialini della caccia alle gemme","cosa fanno gli occhialini"}},{q="Perché il Dottor Erbanera non si immerge lui stesso per recuperare le gemme?",a="Il Dottor Erbanera dice che importanti ricerche scientifiche lo tengono sulla terraferma, al sicuro e all'asciutto.",al={"perché erbanera non nuota","perché erbanera resta a terra"}},{q="Puoi tenere gli Occhialini della Caccia alle Gemme?",a="No. Il Dottor Erbanera ti presta gli occhialini e si aspetta che tu glieli restituisca quando avrai finito. Il Capitano O'Breen li userà spesso.",al={"tenere occhialini caccia alle gemme","devo restituire gli occhialini"}},{q="Dove si colloca questa parte nella serie di missioni di Sunken Treasure?",a="Questa parte segue la prima parte di Sunken Treasure, in cui il Professor Vitestorta ha caricato gli occhialini. Segue una terza parte.",al={"cosa c'è prima di questo","qual è il prossimo passo"}}},fp="15,140,20.298.0,23.211.0,33.101.0,48.130.0,57.78.0,40.120.0,50.119.0"}
P.entries["quest:6661"] = {n="Raccolta Ratti degli Abissi",s="Al Tram degli Abissi, Monty chiede ai viaggiatori di passaggio di radunare i ratti. La melodia incantevole del suo flauto attira i Ratti degli Abissi vivi.",h="Al Tram degli Abissi, Monty chiede ai viaggiatori di passaggio di radunare i ratti.",kw={"ratto degli abissi","raduno dei ratti degli abissi","tram degli abissi","monty","piffero acchiapparatti","spiedino di ratto","parassiti"},ang={["profession:Cooking"]="Il fratello di Monty usa Ratti degli Abissi appena catturati per preparare spiedini di ratto. I ratti devono restare vivi fino alla cottura, altrimenti la carne si guasta."},sec={{t="Parassiti sotto i binari",b="Monty impedisce ai parassiti di infestare il Tram degli Abissi. Parla con un gergo marinaresco e tratta la linea del tram come il ponte di una nave. I parassiti scorrazzano per la stazione sotterranea. Così Monty chiede ai viaggiatori di passaggio di aiutarlo a radunarli."},{t="Una prelibatezza discutibile",b="Monty dà agli aiutanti un Piffero Acchiapparatti incantato. La sua melodia incantevole attira i Ratti degli Abissi, che la seguono, e devono essere riportati vivi. Il fratello di Monty ha bisogno di ratti freschi per preparare spiedini di ratto prima che la carne vada a male."}},faq={{q="Chi assegna la missione Raduno dei Ratti degli Abissi?",a="Monty chiede ai viaggiatori di passaggio di aiutarlo al Tram degli Abissi. Gli servono altre mani per gestire i parassiti lungo la linea sotterranea.",al={"chi assegna raduno dei ratti degli abissi","monty tram degli abissi","tizio della missione dei ratti"}},{q="Perché Monty ha bisogno che i ratti siano catturati vivi?",a="Il fratello di Monty ha bisogno di Ratti degli Abissi vivi per preparare spiedini di ratto prima che la carne vada a male. Se muoiono troppo presto, la carne si guasta.",al={"perché catturare i ratti vivi","cosa fa monty con i ratti","lore spiedini di ratto"}},{q="Come si incantano e si radunano i ratti?",a="Monty fornisce un Piffero Acchiapparatti incantato. Suona la sua melodia vicino ai ratti e ti seguiranno fino alla stazione di Monty.",al={"come catturare i ratti degli abissi","a cosa serve il flauto","piffero acchiapparatti abissi"}},{q="Dove si svolge questo incarico?",a="Il Tram degli Abissi passa sottoterra tra Roccavento e Forgiardente. Monty è di stanza lungo le banchine.",al={"dove si trova raduno dei ratti degli abissi","posizione di monty","ratti del tram degli abissi"}},{q="Chi è il fratello di Monty?",a="Monty parla di un fratello che cucina spiedini di ratto, ma non ne fa il nome. Suo fratello ha bisogno di una scorta costante di ratti freschi e vivi, perché la carne non diventi rancida.",al={"chi è il fratello di monty","fratello cuoco di monty","fratello spiedini"}},{q="Perché Monty parla come un pirata?",a="Monty parla con un forte gergo marinaresco e tratta il tram come il ponte di una nave. Si è assunto il compito di tenere sotto controllo i parassiti nella ferrovia sotterranea.",al={"perché un pirata nel tram","monty pirata tram degli abissi"}}},fp="19,138,24.241.0,23.220.1,40.128.0,44.129.0,39.133.0,32.106.0,23.152.0,34.142.0"}
P.entries["quest:6662"] = {n="Mio fratello Nipsy",s="Sul Tram degli Abissi, Monty manda ratti vivi a suo fratello Nipsy a Roccavento. Nipsy gestisce una bancarella di spiedini di ratto al capolinea, mentre il comportamento bizzarro di Monty lascia intuire la tragedia di Gnomeregan.",h="Sul Tram degli Abissi, Monty manda ratti vivi a suo fratello Nipsy a Roccavento.",kw={"tram degli abissi","gnomeregan","deposito di forgiaardente","me brother nipsy","monty","carne misteriosa","nipsy","spiedino di ratto","deposito di roccavento"},ang={["faction:Alliance"]="Il Tram degli Abissi collega Roccavento e Forgiardente con un percorso ad alta velocità. I venditori locali servono i viaggiatori in entrambi i depositi.",["profession:Cooking"]="Nipsy infilza ratti freschi del Tram degli Abissi per preparare spiedini destinati ai viaggiatori tra Forgiardente e Roccavento.",["race:Gnome"]="I modi da pirata e i deliri eccentrici di Monty derivano dal trauma dell'incidente di Gnomeregan. Mostrano il prezzo personale che la caduta della città ha avuto sugli gnomi sopravvissuti."},sec={{t="Una Consegna Sotterranea",b="Alla stazione di Forgiardente, Monty ti chiede di trasportare ratti vivi sul Tram degli Abissi fino a suo fratello Nipsy, al deposito di Roccavento. Il breve viaggio collega le capitali dei nani e degli umani sotto le montagne. Lungo il percorso proseguono gli scambi più curiosi."},{t="Il Commercio di Spiedini di Ratto",b="La cassa è etichettata Cassa di Carne Misteriosa, ma contiene ratti vivi del Tram degli Abissi. Nipsy gestisce una bancarella di spiedini di ratto al terminal di Roccavento e ha bisogno dei ratti prima che vadano a male. Quando la cassa arriva intatta e piena di ratti guizzanti, è sollevato di avere cibo per i viaggiatori di passaggio alla stazione."},{t="Le Cicatrici di Gnomeregan",b="Monty parla con un esagerato gergo piratesco e avverte i viaggiatori di tenere gli arti a bordo del tram. Nipsy dice che Monty non ha mai visto un oceano in vita sua. Monty ricorre ai suoi modi da pirata per affrontare il trauma persistente della caduta radioattiva di Gnomeregan."}},faq={{q="Chi assegna la missione Me Brother, Nipsy?",a="Monty è uno gnomo eccentrico sul lato di Forgiardente del Tram degli Abissi. Profondamente segnato dalla catastrofe di Gnomeregan, ha adottato il modo di parlare e i modi di un pirata, pur non avendo mai visto un oceano. Cattura ratti vivi da spedire dall'altra parte della linea del tram.",al={"chi assegna me brother nipsy","chi è monty","monty tram"}},{q="Chi è Nipsy?",a="Nipsy è il fratello di Monty e gestisce una bancarella di cibo al deposito del Tram degli Abissi a Roccavento. Per la sua attività di spiedini di ratto, conta su Monty perché gli mandi ratti vivi attraverso il tunnel del tram.",al={"chi è nipsy","dove si trova nipsy","posizione di nipsy"}},{q="Cosa c'è dentro la Cassa di Carne Misteriosa?",a="La Cassa di Carne Misteriosa contiene ratti vivi del Tram degli Abissi catturati da Monty. Nipsy ha bisogno che arrivino vivi, così non andranno a male prima che li trasformi in spiedini.",al={"cos'è la cassa di carne misteriosa","cassa di carne misteriosa","cosa c'è nella scatola"}},{q="Perché Monty parla come un pirata?",a="Monty parla come un pirata per affrontare il trauma del disastro di Gnomeregan. Nipsy dice che non ha mai visto un oceano, eppure Monty resta legato ai suoi modi da pirata e avverte i viaggiatori del rischio di perdere gli arti sui binari del tram.",al={"perché monty parla come un pirata","monty è un pirata","storia di monty pirata"}},{q="Cosa fa Nipsy con i ratti?",a="Nipsy prepara e vende spiedini di ratto ai viaggiatori al deposito di Roccavento. I ratti freschi del Tram degli Abissi, che arrivano col tram, riforniscono la sua bancarella.",al={"cosa fa nipsy con i ratti","attività di spiedini di ratto","cibo di nipsy"}},{q="Dove devi consegnare la spedizione?",a="Trasporti il carico sul Tram degli Abissi dal deposito di Forgiardente al terminal di Roccavento. Il tram attraversa il tunnel sottomarino fino alla stazione di Nipsy, sul lato di Roccavento.",al={"come arrivare da nipsy","dove porto la carne","giro in tram da nipsy"}}},fp="17,183,23.243.0,19.287.0,19.248.1,38.246.0,13.171.0,42.157.0,35.216.0,33.130.0,34.180.0"}
P.entries["quest:667"] = {n="Death From Below",s="A bordo della nave di Shakes O'Breen negli Altopiani d'Arathi, i naga Spinadaga si radunano per attaccare. Affianca O'Breen, manovra il cannone e aiuta l'equipaggio a tornare a Baia del Bottino.",h="A bordo della nave di Shakes O'Breen negli Altopiani d'Arathi, i naga Spinadaga si radunano per attaccare.",kw={"altopiani d'arathi","baia del bottino","spinadaga","naga","shakes o'breen","cannone della nave"},sec={{t="Difendere il ponte",b="Dopo Sunken Treasure, Shakes O'Breen vede i naga Spinadaga radunarsi per attaccare. Sono spietati e continueranno ad arrivare finché O'Breen non sarà morto. O'Breen mette la sicurezza dell'equipaggio prima della propria e ti chiede di difenderlo. Senza la conoscenza dei mari di O'Breen, l'equipaggio non può raggiungere Baia del Bottino. Così resti a bordo con O'Breen, in attesa che i naga emergano dall'acqua."},{t="In seguito",b="Quando l'attacco finisce, O'Breen dice che la nave partirà non appena la marea salirà. Ti avrebbe offerto un posto nell'equipaggio, ma vede che hai pesci più grossi da friggere."}},faq={{q="Chi sta attaccando Shakes O'Breen?",a="I naga Spinadaga si radunano per attaccare Shakes O'Breen. Arrivano dal mare e continueranno ad arrivare finché O'Breen non sarà morto.",al={"chi attacca shakes","chi sono gli attaccanti","attacco spinadaga"}},{q="Perché proteggere Shakes O'Breen è così vitale per l'equipaggio?",a="Shakes O'Breen mette la sicurezza dell'equipaggio prima della propria. Senza la sua conoscenza dei mari, l'equipaggio non può tornare a Baia del Bottino.",al={"perché proteggere shakes obreen","perché shakes è importante","navigazione di shakes obreen"}},{q="Come si respinge l'assalto dei naga?",a="Rimani a bordo della nave di Shakes O'Breen e manovra il cannone. Respingi i naga mentre arrivano dal mare.",al={"come battere death from below","come difendere shakes","difesa col cannone"}},{q="Dove si svolge questa difesa?",a="Difendi la nave di Shakes O'Breen negli Altopiani d'Arathi mentre i naga arrivano dal mare.",al={"dove si trova death from below","posizione di death from below"}}},fp="16,174,16.372.0,9.176.1,32.120.0,54.138.0,34.108.0,35.87.0"}
P.entries["quest:668"] = {n="Sunken Treasure",s="Il Dottor Erbanera manda te dal Capitano O'Breen, che attende al ponte le gemme elfiche.",h="Il Dottor Erbanera manda te dal Capitano O'Breen, che attende al ponte le gemme elfiche.",kw={"altopiani d'arathi","capitano o'breen","dottor erbanera","gemme elfiche","pirati","shakes o'breen","sunken treasure"},sec={{t="Tesoro per il Capitano",b="Il Dottor Erbanera non vede l'ora di portare le gemme elfiche al Capitano O'Breen. Il capitano attende al ponte e vuole vederle di persona. Dopo settimane tra questi pirati, il dottore e il professore hanno imparato che tenere un tesoro pirata nuoce alla loro salute. Così Erbanera ti affida le gemme da portare a O'Breen."}},faq={{q="Chi ti manda dal Capitano O'Breen?",a="Il Dottor Erbanera ti affida le gemme elfiche da portare al Capitano O'Breen.",al={"chi assegna sunken treasure 3","missione draxlegauge"}},{q="Perché il Dottor Erbanera ha tanta fretta di rinunciare alle gemme?",a="Dopo settimane tra questi pirati, il Dottor Erbanera e il professore hanno imparato che tenere un tesoro pirata nuoce alla loro salute.",al={"perché consegnare gemme elfiche","perché dare gemme a un pirata"}},{q="Dove si colloca nella serie?",a="Questa parte segue la seconda parte di Sunken Treasure e precede una quarta parte.",al={"posizione catena sunken treasure","cosa precede sunken treasure 3"}}},fp="15,215,24.319.0,33.72.0,55.136.0,34.82.0"}
P.entries["quest:669"] = {n="Sunken Treasure",s="In Sunken Treasure, Shakes O'Breen è trattenuto dalla bassa marea e da creature vigili: bisogna avvisare Baia del Bottino.",h="In Sunken Treasure, Shakes O'Breen è trattenuto dalla bassa marea e da creature vigili: bisogna avvisare Baia...",kw={"altopiani d'arathi","blackwater raiders","baia del bottino","contrammiraglio corno marino","gemma elfica campione","shakes o'breen","sunken treasure"},sec={{t="Messaggio per Baia del Bottino",b="Shakes O'Breen ha bisogno che il Contrammiraglio Corno Marino, a Baia del Bottino, venga informato subito del ritrovamento. La marea è troppo bassa perché possa partire, e le creature disturbate dal suo equipaggio sorvegliano ogni loro mossa. Ti chiede di dire a Corno Marino che il tesoro è stato trovato e che ne stanno recuperando altro. Porti con te una gemma elfica campione come prova."}},faq={{q="Perché Shakes O'Breen non può consegnare la gemma di persona?",a="La marea è troppo bassa perché Shakes O'Breen e il suo equipaggio possano partire, e le creature che hanno disturbato sorvegliano i loro movimenti.",al={"perché shakes non può andarsene","perché shakes è bloccato","perché shakes ha bisogno di un corriere"}},{q="Chi è il Contrammiraglio Corno Marino?",a="Il Contrammiraglio Corno Marino si trova a Baia del Bottino, e O'Breen vuole che venga informato subito del ritrovamento.",al={"chi è corno marino","dov'è il contrammiraglio corno marino"}},{q="Quale prova viene portata a Baia del Bottino?",a="Porti con te una gemma elfica campione per dimostrare che il tesoro è stato trovato e che ne stanno recuperando altro.",al={"qual è la prova","quale gemma viene consegnata"}}},fp="15,117,18.301.0,49.117.0,28.88.0,41.90.0"}
P.entries["quest:67"] = {n="Leggenda di Stalvan",s="A Borgoscuro, il Cancelliere Daltry cerca Stalvan Mistmantle nei registri cittadini. Un vecchio indirizzo indica Rivoluna, nelle Marche Occidentali, dove comincia la ricerca sul passato di Stalvan.",h="A Borgoscuro, il Cancelliere Daltry cerca Stalvan Mistmantle nei registri cittadini.",kw={"daltry","boscovespro","forziere","spirito infausto","mistmantle","rivoluna","scuola","stalvan","marche occidentali"},ang={["class:Mage"]="Lo Spirito Infausto che custodisce il baule usa metamorfosi e maledizioni debilitanti. Dovrai affrontare una magia legata al dolore in quella che altrimenti sarebbe una normale aula.",["faction:Alliance"]="Questa ricerca mostra quanto si siano frammentate le città rurali del regno. Per seguire un’annotazione del registro di Borgoscuro, devi attraversare le Marche Occidentali controllate dai Defias."},sec={{t="La richiesta del Cancelliere",b="Dopo le tue indagini a Borgoscuro, il Cancelliere Daltry cerca Stalvan Mistmantle nel registro cittadino. Il registro non viene aggiornato da anni e indica come ultima dimora nota di Stalvan la scuola di Rivoluna, molto a ovest. Daltry considera il vecchio indirizzo una normale operazione d’archivio. Ti chiede di indagare e riportare eventuali documenti che possano aggiornare gli archivi di Borgoscuro."},{t="Le rovine di Rivoluna",b="La pista porta da Boscovespro alle Marche Occidentali, dove la Fratellanza dei Defias controlla Rivoluna. Un tempo fiorente insediamento agricolo, la città è ora in mano ai fuorilegge. Vicino al centro sorge la scuola abbandonata. Al suo interno, un vecchio baule contiene i primi indizi chiari sulla vita passata di Stalvan come insegnante. Attorno al baule aleggia ancora il dolore."},{t="Un'infestazione tragica",b="Aprire il vecchio baule evoca uno Spirito Infausto. Attacca chiunque scopra il passato di Stalvan e usa una magia dolente per maledire gli intrusi. Lo spirito indica una tragedia irrisolta legata alla partenza del maestro dalle Marche Occidentali. La ricerca di vecchi documenti si è trasformata in un’infestazione."}},faq={{q="Chi è il Cancelliere Daltry?",a="Il Cancelliere Daltry custodisce i registri cittadini di Borgoscuro nella Darkshire Town Hall, a Boscovespro. Cerca Stalvan Mistmantle nel registro e trova annotazioni rimaste invariate per anni.",al={"daltry","cancelliere di borgoscuro","chi inizia la leggenda di stalvan 2"}},{q="Dov'è la Moonbrook Schoolhouse?",a="La Moonbrook Schoolhouse sorge al centro di Rivoluna, nel sudovest delle Marche Occidentali. La sua architettura ricorda la Darkshire Town Hall e tutt’intorno si aggirano i Banditi Defias.",al={"posizione moonbrook schoolhouse","dov'è la scuola","dov'è il forziere di stalvan"}},{q="Cosa c'è nel vecchio forziere?",a="Il baule contiene vecchi documenti ed effetti personali del periodo in cui Stalvan Mistmantle insegnava a Rivoluna. Forniscono la prossima pista per scoprire dove si trova.",al={"forziere di stalvan","cosa c'è nel forziere"}},{q="Perché un fantasma attacca quando si apre il forziere?",a="Aprire il baule evoca uno Spirito Infausto, che attacca con metamorfosi e maledizioni. Lo spirito è legato alla tragedia che circonda il passato di Stalvan e la sua partenza da Rivoluna.",al={"spirito infausto","perché appare un fantasma","maledizione del fantasma di stalvan"}},{q="Perché Stalvan ha lasciato le Marche Occidentali?",a="Stalvan era maestro a Rivoluna prima di partire in cerca di lavoro come precettore privato altrove nel regno. I suoi effetti personali rimasero chiusi nella vecchia scuola.",al={"perché stalvan ha lasciato rivoluna","storia di stalvan a rivoluna"}},{q="È sicuro entrare a Rivoluna?",a="No. La Fratellanza dei Defias controlla Rivoluna, quindi per raggiungere la scuola devi affrontare ladri e fuorilegge armati.",al={"rivoluna è pericolosa","nemici a rivoluna"}}},fx={["803ebeb2"]={q="Perché il Cancelliere Daltry vuole che venga fatto?",a="Il Cancelliere Daltry è molto orgoglioso del suo lavoro di custode del registro cittadino di Borgoscuro. Controllando i registri di Stalvan Mistmantle, scopre che l'ultimo indirizzo noto dell'uomo è indicato come la Moonbrook Schoolhouse nelle Marche Occidentali. Sapendo quanto sia obsoleta quell'informazione, vuole che tu visiti la scuola e cerchi notizie recenti, così potrà mantenere i registri ordinati, puliti e accurati.",al={"perché daltry cerca i registri di stalvan","motivi del cancelliere daltry","perché trovare stalvan"}}},fp="21,175,24.393.0,22.351.0,17.289.1,20.167.0,35.166.0,34.182.0,52.182.1,31.165.0,27.114.0"}
P.entries["quest:670"] = {n="Sunken Treasure",s="Il Contrammiraglio Corno Marino aspetta alla Baia del Bottino con una lettera per Shakes O'Breen, al largo della costa d'Arathi. Le sue navi non possono salpare finché non si riforniscono.",h="Il Contrammiraglio Corno Marino aspetta alla Baia del Bottino con una lettera per Shakes O'Breen, al largo...",kw={"altopiani d'arathi","incursori acque nere","baia del bottino","contrammiraglio corno marino","lettera sigillata di corno marino","shakes o'breen","sunken treasure"},sec={{t="Una lettera per O'Breen",b="Il Contrammiraglio Corno Marino vede in te un avventuriero. Le sue navi devono rifornirsi prima di poter lasciare la Baia del Bottino. Qui e altrove si stanno preparando cose gravi, dice, e ha una lettera segreta per Shakes O'Breen, al largo della costa d'Arathi. Può fidarsi di te perché la consegni in sicurezza e mantenga il segreto?"}},faq={{q="Chi ti manda a consegnare questa lettera?",a="Il Contrammiraglio Corno Marino nella Baia del Bottino ti consegna una lettera sigillata per Shakes O'Breen.",al={"chi dà sunken treasure 5","chi inizia questa missione","datore missione lettera di corno marino"}},{q="Perché il Contrammiraglio Corno Marino non consegna la lettera di persona?",a="Le sue navi non possono salpare dalla Baia del Bottino finché non si riforniscono.",al={"perché corno marino non può lasciare la baia del bottino","perché il contrammiraglio corno marino è bloccato"}},{q="Dove si trova Shakes O'Breen?",a="Shakes O'Breen è impegnato al largo della costa degli Altopiani d'Arathi.",al={"dove trovare shakes obreen","posizione shakes obreen","dove si trova shakes"}},{q="Cosa c'è stato prima di questa consegna?",a="Questa consegna segue la quarta parte di Sunken Treasure.",al={"catena sunken treasure","quale missione precede sunken treasure 5"}}},fp="15,136,20.286.0,37.79.0,60.56.0,32.61.0,31.57.0"}
P.entries["quest:671"] = {n="Foul Magics",s="Negli Altopiani d'Arathi, Tor'gan segue una presenza demoniaca fino al Maniero dei Norten. Da Requie del Martello, chiede aiuto per recuperare gli amuleti di pietra del sangue dagli evocatori.",h="Negli Altopiani d'Arathi, Tor'gan segue una presenza demoniaca fino al Maniero dei Norten.",kw={"altopiani d'arathi","pietra del sangue","amuleto di pietra del sangue","evocazione demoniaca","foul magics","requie del martello","maniero dei norten","tor'gan"},ang={["class:Warlock"]="Come stregone, conosci i rituali e i reagenti vincolanti necessari per evocare i demoni. Gli amuleti di pietra del sangue del Maniero dei Norten sono oggetti di particolare interesse.",["faction:Horde"]="Come membro dell'Orda, sai che Requie del Martello è il suo unico avamposto negli Altopiani d'Arathi. Gli evocatori oscuri appena a ovest dell'insediamento rappresentano una minaccia diretta per la sicurezza.",["race:Orc"]="Come orco, porti con te una storia profonda e dolorosa di corruzione demoniaca. La magia vile residua può farti ribollire il sangue e scatenare una rabbia innaturale, come accade a Tor'gan vicino al Maniero dei Norten."},sec={{t="Una rabbia ribollente",b="L'energia demoniaca si agita negli Altopiani d'Arathi e Tor'gan la percepisce dal suo avamposto a Requie del Martello. La forza lo attira a ovest, verso il Maniero dei Norten. Lì trova tracce di evocazioni demoniache, ma la corruzione persistente gli fa ribollire il sangue e scatena una rabbia involontaria, legata alla storia della maledizione del sangue. Si ritira prima che l'influenza sopraffaccia i suoi sensi, poi chiede aiuto ad altri."},{t="Gli amuleti di pietra del sangue",b="Al Maniero dei Norten, Tor'gan ha trovato a terra un amuleto di pietra del sangue. Era la prova che lì si praticavano rituali oscuri. Questi amuleti aiutano a canalizzare e stabilizzare le evocazioni demoniache, ma quello che ha recuperato aveva perso la sua magia. Aveva troppo poco potere per un esame approfondito. Tor'gan chiede ai viaggiatori dell'Orda di recuperare dieci amuleti intatti dai praticanti del maniero, così da poter esaminare i rituali e scoprire quali entità siano state evocate."}},faq={{q="Chi assegna la missione Foul Magics?",a="Tor'gan affida la richiesta da Requie del Martello, roccaforte dell'Orda negli Altopiani d'Arathi. Percependo una presenza demoniaca nelle vicinanze, chiede ai viaggiatori di indagare sul Maniero dei Norten.",al={"assegnatore missione foul magics","chi inizia foul magics","missione torgan arathi"}},{q="Dove si trova il Maniero dei Norten?",a="Il Maniero dei Norten si trova a ovest di Requie del Martello, tra le colline settentrionali degli Altopiani d'Arathi. Un tempo dimora umana, ora è il luogo di evocazioni demoniache clandestine condotte con amuleti di pietra del sangue.",al={"posizione maniero dei norten","dove si trova il maniero dei norten","trovare maniero dei norten arathi"}},{q="A cosa servono gli amuleti di pietra del sangue?",a="Gli amuleti di pietra del sangue aiutano i praticanti a canalizzare la magia oscura durante le evocazioni demoniache. Quando un'evocazione consuma il potere di un amuleto, questo si esaurisce.",al={"cos'è l'amuleto di pietra del sangue","scopo amuleto di pietra del sangue","perché amuleti di pietra del sangue"}},{q="Perché Tor'gan prova rabbia vicino al Maniero dei Norten?",a="Le energie persistenti delle evocazioni demoniache nei pressi del Maniero dei Norten scatenano la rabbia di Tor'gan. La magia vile gli fa ribollire il sangue e accende una rabbia incontrollabile.",al={"perché il sangue di torgan bolle","rabbia di torgan norten","perché torgan si arrabbia"}},{q="Perché Tor'gan si rifiuta di tornare al Maniero dei Norten?",a="Tor'gan teme che il potere demoniaco residuo possa scatenare in lui una rabbia pericolosa. Preoccupato di perdere il controllo o soccombere alla sua influenza corruttrice, chiede ad altri di recuperare gli amuleti.",al={"perché torgan non vuole andare al maniero","perché torgan non torna indietro","perché torgan non può prendere gli amuleti"}},{q="Quanti amuleti di pietra del sangue servono?",a="Tor'gan chiede di recuperare dieci amuleti di pietra del sangue dal Maniero dei Norten. Quello che ha trovato era esaurito, perciò gli servono diversi esemplari carichi di potere per studiare e comprendere i rituali del luogo.",al={"quanti amuleti di pietra del sangue","conteggio amuleti di pietra del sangue","conteggio obiettivi foul magics"}},{q="Chi sta evocando demoni al Maniero dei Norten?",a="I praticanti oscuri del Maniero dei Norten compiono evocazioni demoniache. I loro rituali e i residui di magia vile hanno attirato l'attenzione di Tor'gan da Requie del Martello e dato inizio all'indagine dell'Orda.",al={"chi si trova al maniero dei norten","chi sta evocando demoni al maniero","cultisti del maniero dei norten"}}},fp="11,160,16.391.0,22.436.0,32.173.0,33.184.0,37.149.0,48.145.0,53.182.0,39.174.0,43.178.0"}
P.entries["quest:672"] = {n="Raising Spirits",s="Tor'gan cerca un modo per risollevare il morale di Gor'mul a Requie del Martello, negli Altopiani d'Arathi. I racconti su Orgrimmar e sul Capoguerra Thrall non lo hanno confortato, così Tor'gan si affida alle tradizioni sciamaniche dell'Orda, riscoperte di recente.",h="Tor'gan cerca un modo per risollevare il morale di Gor'mul a Requie del Martello, negli Altopiani d'Arathi.",kw={"altopiani d'arathi","gor'mul","requie del martello","occhi di rapace degli altipiani","orgrimmar","raising spirits","sciamanesimo","thrall","tor'gan"},ang={["class:Shaman"]="Da sciamano, vedi le tradizioni riscoperte dell'Orda all'opera contro lo sconforto di Gor'mul. Tor'gan invoca gli spiriti degli animali per riaccendere in lui la volontà di vivere.",["faction:Horde"]="Come membro dell'Orda, vedi i compagni degli avamposti remoti come Requie del Martello prendersi cura dei fratelli d'armi abbattuti.",["race:Orc"]="Come orco, sai che l'internamento e la perdita delle antiche tradizioni hanno gettato veterani come Gor'mul nella disperazione e nell'apatia. Alcuni faticano ad abbracciare la nuova Orda di Thrall."},sec={{t="Un cuore pesante a Requie del Martello",b="A Requie del Martello, negli Altopiani d'Arathi, Gor'mul è sprofondato in una profonda malinconia. I suoi compagni gli hanno parlato di Kalimdor, della potente città di Orgrimmar e della guida del Capoguerra Thrall. Eppure, nessuno di questi racconti ha alleviato il suo sconforto o gli ha dato speranza."},{t="Spiriti della natura",b="Tor'gan si affida alle tradizioni spirituali riscoperte dell'Orda per aiutare Gor'mul. Raccoglie gli occhi dei rapaci degli altipiani che si aggirano per gli Altopiani d'Arathi e crea un amuleto benedetto dai loro spiriti. Con questo rito, spera che la forza vitale dei predatori risvegli in Gor'mul la volontà di vivere."}},faq={{q="Chi è Tor'gan?",a="Tor'gan è uno sciamano troll di stanza a Requie del Martello, negli Altopiani d'Arathi. Spera di aiutare Gor'mul con un amuleto creato seguendo le tradizioni sciamaniche dell'Orda, riscoperte di recente.",al={"chi è tor'gan","torgan requie del martello","datore di missione raising spirits"}},{q="Chi è Gor'mul e perché ha bisogno di essere tirato su di morale?",a="Gor'mul è un orco di Requie del Martello, sprofondato nello sconforto e nell'apatia. I racconti su Orgrimmar e sul Capoguerra Thrall non gli hanno risollevato il morale.",al={"chi è gormul","perché gormul è triste","orco depresso requie del martello"}},{q="Perché Tor'gan ha bisogno di occhi di rapace degli altipiani?",a="Tor'gan usa gli occhi degli Highland Striders e degli Highland Thrashers per creare un amuleto sciamanico. Spera che i loro spiriti diano a Gor'mul forza e tenacia, e riaccendano il suo spirito combattivo.",al={"perché occhi di rapace","amuleto occhi di rapace","scopo degli occhi di rapace"}},{q="Dove si svolge questa missione?",a="Requie del Martello è l'avamposto dell'Orda negli Altopiani d'Arathi. Prende il nome dal precedente Capoguerra Orgrim Martelfato ed è un rifugio fortificato per gli orchi rimasti nei Regni Orientali.",al={"dove si trova requie del martello","posizione requie del martello","orchi ad arathi"}},{q="Cos'è la magia sciamanica appena trovata menzionata da Tor'gan?",a="Gli orchi persero il legame spirituale con gli elementi e gli spiriti degli antenati durante la corruzione demoniaca e l'internamento. Sotto il Capoguerra Thrall, l'Orda ha ritrovato l'antica via sciamanica, guidata dall'armonia spirituale anziché dalla magia vile.",al={"magia sciamanica orchi","sciamanesimo degli orchi nuova orda","perché nuova magia sciamanica"}},{q="Quali storie non sono riuscite a tirare su di morale Gor'mul?",a="I compagni di Gor'mul gli hanno parlato di Orgrimmar, la nuova capitale oltre il mare, a Kalimdor, e del Capoguerra Thrall, che impugna l'armatura di Orgrim Martelfato e il suo leggendario martello da guerra.",al={"racconti su thrall","quali storie hanno raccontato a gormul","racconti di orgrimmar gormul"}}},fp="15,220,27.248.0,19.268.0,15.179.0,48.134.0,43.190.0,33.175.0,63.236.0,40.170.0"}
P.entries["quest:673"] = {n="Foul Magics",s="A Requie del Martello, Tor'gan teme che uno stregone a Stromgarde evochi demoni con una reliquia arcana. Il tuo primo incarico per lui ti ha portato a dare la caccia allo stregone e alla reliquia.",h="A Requie del Martello, Tor'gan teme che uno stregone a Stromgarde evochi demoni con una reliquia arcana.",kw={"altopiani d'arathi","sanguinite","requie del martello","marez cowl","stromgarde","torgan","stregone"},sec={{t="Uno Stregone a Stromgarde",b="Tor'gan è certo che una stregona, nascosta tra le mura di Stromgarde, usi una reliquia arcana per evocare terribili demoni in gran numero. Il bruciore nel suo sangue cresce di giorno in giorno. Perciò ti manda a trovare e uccidere la stregona, poi a riportargli l'oggetto magico che porta con sé. Vuole distruggerlo prima che il suo potere contamini la terra. La stregona è Marez Cowl e l'oggetto è una Sfera Infame di Sanguinite."},{t="Cosa Rievoca la Sfera",b="Con la sfera distrutta, Tor'gan si aspetta che le sue notti agitate lascino il posto a un sonno tranquillo. La sfera gli ricorda il terribile controllo che un tempo i demoni esercitavano sugli orchi. Quel controllo durò finché Malogrido non li liberò dalla loro maledizione."}},faq={{q="Chi ti invia a dare la caccia allo stregone?",a="Tor'gan, a Requie del Martello, ti manda a Stromgarde per trovare la stregona e riportargli l'oggetto magico che porta con sé.",al={"chi fornisce foul magics","datore missione foul magics","missione di torgan"}},{q="Dove si trova lo stregone?",a="Marez Cowl si nasconde tra le mura di Stromgarde, a ovest del Forte e al di fuori delle sue mura, dietro un edificio. Puoi sentirla mentre canalizza un incantesimo.",al={"dove si trova marez cowl","posizione stregone stromgarde","dove trovare marez cowl"}},{q="Quale reliquia ti viene inviato a recuperare?",a="Devi recuperare la Sfera Infame di Sanguinite di Marez Cowl. Tor'gan vuole che gliela porti perché possa distruggerla.",al={"quale oggetto vuole torgan","sfera infame di sanguinite","oggetto foul magics"}},{q="Perché Tor'gan vuole che lo stregone venga fermato?",a="La stregona ha evocato terribili demoni in gran numero usando una reliquia arcana. Tor'gan vuole che annulli il potere della reliquia e distrugga la sfera prima che possa contaminare la terra.",al={"perché distruggere la sfera","motivazione di torgan","perché fermare lo stregone"}}},fp="11,165,23.399.0,20.219.1,34.123.0,29.129.0,36.111.0,42.176.0"}
P.entries["quest:674"] = {n="Raising Spirits",s="Un emissario dell'Orda spera che Raising Spirits aiuti Gor'mul a ritrovare il suo spirito combattivo. L'Amuleto d'Unghia di Raptor dovrebbe riaccenderlo, ma Gor'mul è ancora amareggiato e dubita che un ninnolo possa restituire all'Orda il suo antico splendore.",h="Un emissario dell'Orda spera che Raising Spirits aiuti Gor'mul a ritrovare il suo spirito combattivo.",kw={"gor'mul","gormul","orda","raising spirits","amuleto di raptor","amuleto d'unghia di raptor","guerriero"},ang={["class:Warrior"]="Da guerriero, vieni a sapere di un orco il cui spirito combattivo è stato spento dalla disperazione e dal dolore per un attacco codardo.",["faction:Horde"]="Da membro dell'Orda, senti Gor'mul piangere la sua potenza perduta e chiedersi se un semplice ninnolo possa restituirle la gloria perduta."},sec={{t="Una scintilla per una fiamma caduta",b="Un emissario porta a Gor'mul un Amuleto d'Unghia di Raptor, sperando che il suo potere possa raggiungerlo. Il talismano incanala la forza selvaggia e la ferocia dei raptor. Dovrebbe riaccendere la fiamma che un tempo ardeva intensamente nel guerriero orco."},{t="Amarezza e disperazione",b="Gor'mul accoglie il dono con amaro dolore. Ricorda i più grandi campioni abbattuti da mani codarde e rifiuta il talismano, definendolo osso lucidato. Dubita che un ninnolo possa restituire all'Orda il suo antico splendore."}},faq={{q="Cos'è Raising Spirits?",a="Un emissario dell'Orda porta a Gor'mul un Amuleto d'Unghia di Raptor, sperando che possa riaccendere lo spirito combattivo del guerriero sconsolato.",al={"cos'è raising spirits","missione raising spirits"}},{q="Chi è Gor'mul?",a="Gor'mul è un guerriero consumato dalla disperazione dopo che i più grandi campioni sono caduti per mano di codardi. Disprezza i simboli e dubita che l'Orda possa riconquistare il suo antico splendore.",al={"chi è gormul","gor mul"}},{q="Perché l'Amuleto d'Unghia di Raptor viene portato a Gor'mul?",a="L'Amuleto d'Unghia di Raptor è realizzato con osso lucidato e artigli di raptor. Viene portato a Gor'mul nella speranza che possa incanalare la forza e la ferocia naturali dei raptor e risvegliare la sua fiamma interiore.",al={"perché portare l'amuleto","cosa fa l'amuleto d'unghia di raptor"}},{q="Perché Gor'mul è sconfortato?",a="Gor'mul è disperato dopo aver visto i più grandi campioni uccisi da mani codarde. La loro caduta lo convince che onore e forza possano essere spenti, spezzando la sua volontà di combattere.",al={"perché gormul è triste","perché gormul è depresso"}},{q="Come reagisce Gor'mul all'amuleto?",a="Gor'mul rifiuta il dono, considerandolo semplice osso lucidato. Crede che non possa restituire la gloria all'Orda né cancellare la tragedia che piange.",al={"a gormul piace l'amuleto","reazione di gormul"}},{q="Cosa dice Gor'mul dell'Orda?",a="Gor'mul dubita che l'Orda possa riconquistare il suo antico splendore: vede poche speranze quando il tradimento può abbattere persino i più grandi eroi.",al={"si può restituire la gloria all'orda","gor'mul gloria dell'orda"}}},fp="15,225,26.231.0,22.218.1,24.120.0,15.164.0,50.191.0,26.182.0,37.119.0,38.130.0"}
P.entries["quest:675"] = {n="Raising Spirits",s="Tor'gan spera che la magia ancestrale possa restituire a Gor'mul l'orgoglio e la voglia di vivere. Lo sciamano vuole risollevare un vecchio veterano orco dalla disperazione.",h="Tor'gan spera che la magia ancestrale possa restituire a Gor'mul l'orgoglio e la voglia di vivere.",kw={"amuleto","gor'mul","pietà","orco","raising spirits","sciamano","tor'gan","veterano","capoguerra"},ang={["class:Shaman"]="Da sciamano, puoi vedere come lo sciamanesimo orco possa risollevare gli spiriti dei veterani ancora oppressi dai traumi.",["faction:Horde"]="Sotto la guida di Thrall, l'Orda cerca di reintegrare e risollevare i veterani amareggiati, invece di abbandonarli alla disperazione.",["race:Orc"]="Da orco, puoi comprendere il disonore che Gor'mul prova per essersi visto negare una morte onorevole al fianco del suo ex Capoguerra."},sec={{t="Uno spirito spezzato",b="Gor'mul si addolora perché è sopravvissuto al suo Capoguerra caduto. Molti veterani orchi portano il peso delle guerre passate, ma Gor'mul crede che il destino gli abbia negato una morte onorevole al fianco del suo condottiero. Tor'gan, uno sciamano, spera di alleviare il suo dolore richiamando la forza spirituale del suo popolo. Prepara un amuleto incantato e si affida al potere ancestrale per riaccendere l'orgoglio del vecchio guerriero."},{t="I limiti dell'amuleto",b="L'amuleto di Tor'gan raggiunge Gor'mul, ma non gli dà conforto. Gor'mul lo getta a terra e chiede perché qualcuno dovrebbe mostrargli pietà, quando il destino gli ha negato una fine onorevole. Tor'gan accetta che un solo talismano non possa superare anni di dolore. Eppure, resta deciso ad aiutare Gor'mul, convinto che la diffusione dello sciamanesimo possa guidarlo verso il suo antico onore."}},faq={{q="Chi è Gor'mul?",a="Gor'mul è un veterano orco amareggiato, sopravvissuto ai conflitti della vecchia Orda dopo la caduta del suo Capoguerra. Crede che il destino gli abbia negato crudelmente una morte onorevole al fianco del suo condottiero e rifiuta la semplice compassione.",al={"chi è gormul","retroscena di gormul","cosa c'è che non va in gormul"}},{q="Chi è Tor'gan e perché sta aiutando Gor'mul?",a="Tor'gan è uno sciamano che cerca di risollevare Gor'mul dalla disperazione. Crede che le vie ancestrali possano risanare gli spiriti affranti e che lo sciamanesimo possa condurre gli antichi guerrieri a una rinascita spirituale. Crea amuleti infusi per ricordare loro la forza del proprio popolo.",al={"chi è torgan","cosa vuole torgan","scopo di torgan"}},{q="Qual era lo scopo dell'amuleto?",a="Tor'gan ha preparato l'amuleto incantato per risvegliare lo spirito guerriero di Gor'mul con l'energia sciamanica. Gor'mul lo ha rifiutato e gettato a terra, convinto che la sua magia non potesse scacciare l'amarezza che provava.",al={"cos'è l'amuleto","perché gormul ha gettato l'amuleto","l'amuleto ha funzionato"}},{q="Quale Capoguerra piange Gor'mul?",a="Gor'mul non rivela il nome del Capoguerra che piange. Maledice il destino per avergli negato la morte in battaglia al fianco del suo condottiero caduto.",al={"quale capoguerra è morto","chi era il capoguerra di gormul","chi serviva gormul"}},{q="Cosa intende fare Tor'gan dopo che l'amuleto fallisce?",a="Tor'gan accetta che l'amuleto, da solo, non avesse abbastanza potere. Ha pazienza e crede che il vero potere dello sciamanesimo possa riaccendere l'orgoglio perduto di Gor'mul.",al={"torgan si arrende","cosa succede dopo raising spirits","gormul si riprenderà"}},{q="Perché Tor'gan usa lo sciamanesimo per aiutare Gor'mul?",a="Tor'gan usa lo sciamanesimo per risanare le menti ferite e l'orgoglio del suo popolo. Gli sciamani curano quelle ferite e incanalano gli elementi in battaglia.",al={"cosa dimostra questo sugli sciamani","perché usare la magia sciamanica qui"}}},fp="15,133,15.376.0,24.363.1,15.207.0,45.240.0,35.198.0,34.118.0,52.153.0,47.132.0"}
P.entries["quest:676"] = {n="The Hammer May Fall",s="Tallow invia combattenti da Mulino di Tarren attraverso le montagne per soccorrere Requie del Martello negli Altopiani d'Arathi. Prima di fare rapporto a Drum Fel, dimostri la tua forza affrontando gli ogre Boulderfist vicino alle rovine di Stromgarde.",h="Tallow invia combattenti da Mulino di Tarren attraverso le montagne per soccorrere Requie del Martello negli...",kw={"altopiani d'arathi","carnefice boulderfist","ogre boulderfist","drum fel","requie del martello","alture di colletorto","stromgarde","tallow","mulino di tarren","the hammer may fall"},ang={["class:Warrior"]="Nei panni di un guerriero, affronti i massicci carnefici Boulderfist per dimostrare il tuo valore a comandanti orchi veterani come Drum Fel.",["faction:Horde"]="Questo incarico ti porta dalle dispute locali di Colletorto alla difesa più ampia degli Altopiani d'Arathi, dove Requie del Martello mantiene una posizione strategica.",["race:Orc"]="Per un orco, Requie del Martello ha un significato profondo e una lunga storia. Fu fondata nel luogo in cui il Capoguerra Orgrim Martelfato perse la vita durante le campagne di liberazione."},sec={{t="Un richiamo brusco",b="A Mulino di Tarren, Tallow ha poca pazienza per chi non ha ancora dimostrato il proprio valore in battaglia. Mentre le reclute restano inattive, alleati lontani sono sotto attacco. Invia a est i combattenti più capaci, oltre il Muro di Thoradin e negli Altopiani d'Arathi, dove Requie del Martello è assediata da più fronti. Prima, devono dimostrare il loro valore affrontando un nemico potente. Solo allora Tallow li invierà all'avamposto."},{t="Prova contro i Boulderfist",b="Tallow pretende una prova di forza presso il tumulo degli ogre a nord-est delle rovine di Stromgarde. Gli ogre Boulderfist e i loro carnefici controllano gran parte di Arathi e minacciano i viaggiatori lungo i sentieri degli altopiani. Combatterli riduce le forze ostili che fiancheggiano la strada. Dimostra anche che sai affrontare il pericolo prima di raggiungere Requie del Martello."},{t="Rapporto a Requie del Martello",b="Dopo aver sgomberato l'accampamento dei Boulderfist, la strada conduce a nord-est, verso Requie del Martello, intitolata al Capoguerra Orgrim Martelfato. Il comandante Drum Fel accoglie i nuovi arrivati con stanco scetticismo. Che Tallow intendesse rafforzare la guarnigione o mandare degli sciocchi a morire, Drum Fel ben presto indirizza i combattenti provati verso le scaramucce che minacciano l'avamposto."}},faq={{q="Dove inizia e finisce questa missione?",a="Tallow affida questo incarico a Mulino di Tarren, nelle Alture di Colletorto. Dopo aver sconfitto gli ogre richiesti negli Altopiani d'Arathi, fai rapporto a Drum Fel a Requie del Martello, l'avamposto dell'Orda.",al={"dove inizio the hammer may fall","dove consegnare la missione","chi dà the hammer may fall"}},{q="Dove si trovano gli ogre Boulderfist?",a="Gli ogre Boulderfist vivono presso un vistoso tumulo di terra e un accampamento a nord-est delle rovine di Stromgarde, negli Altopiani d'Arathi.",al={"posizione ogre boulderfist","dove sono gli ogre ad arathi","tumulo boulderfist"}},{q="Cos'è l'avamposto di Requie del Martello?",a="Requie del Martello è un insediamento fortificato dell'Orda nel nord-est degli Altopiani d'Arathi. Onora l'ex Capoguerra Orgrim Martelfato, caduto nei pressi durante la liberazione dei campi d'internamento degli orchi.",al={"cos'è requie del martello","lore requie del martello","chi ha fondato requie del martello"}},{q="Perché Tallow ti fa combattere gli ogre prima di fare rapporto a Requie del Martello?",a="Requie del Martello subisce attacchi continui e ha bisogno di combattenti capaci. Tallow ti manda contro gli ogre Boulderfist per dimostrare che sai combattere prima di unirti a Drum Fel, senza diventare un peso.",al={"perché uccidere prima gli ogre","movente di tallow","perché mettermi alla prova"}},{q="Chi è Drum Fel?",a="Drum Fel è un veterano guerriero orchesco e comandante a Requie del Martello, negli Altopiani d'Arathi. Organizza le difese contro fauna ostile, ogre, troll e resti dell'Alleanza.",al={"identità di drum fel","comandante di requie del martello","chi è drum fel"}},{q="Cosa segue questo incarico?",a="Fare rapporto a Drum Fel ti porta alla campagna Call to Arms, una serie di operazioni militari contro le minacce circostanti, comprese le tribù di troll Witherbark che minacciano gli altopiani.",al={"missione successiva","seguito di the hammer may fall","cosa viene dopo"}}},fx={b3b0715a={q="Chi sono gli ogri Boulderfist contro cui ti mandano?",a="La tribù Boulderfist è un rozzo clan di ogri che rivendica il territorio degli Altopiani d'Arathi, con il proprio tumulo a nord-est delle rovine di Stromgarde. Feroci, ostinati e imponenti, dominano le colline rocciose degli altopiani e si contendono il territorio circostante. Tallow ti manda al loro tumulo per vedere se riesci a sopravvivere ai loro combattenti di prima linea, assicurandosi che tu abbia la forza necessaria prima di gettarti nel tritacarne della zona di guerra d'Arathi.",al={"ogri boulderfist","chi sono i boulderfist","ogri di arathi"}}},fp="19,217,15.379.0,20.319.0,23.345.1,36.190.0,40.123.0,34.188.0,68.189.0,16.172.0,29.183.0"}
P.entries["quest:677"] = {n="Call to Arms",s="Drum Fel chiama l'Orda a colpire da Requie del Martello, negli Altopiani d'Arathi. Gli Scorzasecca si sono alleati con gli ogre Pugno di Pietra, e l'Orda intende mantenere la propria testa di ponte.",h="Drum Fel chiama l'Orda a colpire da Requie del Martello, negli Altopiani d'Arathi.",kw={"altopiani d'arathi","lanciatore d'asce","pugno di pietra","call to arms","drum fel","requie del martello","cacciatore di teste","sciamano","scorzasecca"},ang={["faction:Horde"]="Requie del Martello è isolata negli Altopiani d'Arathi, circondata da forze ostili. Difendere l'avamposto è importante mentre l'Orda cerca di mantenere una posizione nelle terre degli umani.",["race:Orc"]="Requie del Martello sorge sul terreno di un ex campo di internamento della Seconda Guerra. Da orco, difendere questo nuovo insediamento dai vicini ostili porta con sé il peso della liberazione.",["race:Troll"]="Da troll Puntascura al servizio dell'Orda di Thrall, affronti gli ostili troll della foresta Scorzasecca. Il loro rifiuto della nuova Orda segna una netta divisione tra i tuoi popoli."},sec={{t="Difendere Requie del Martello",b="A Requie del Martello, Drum Fel raduna l'Orda nel suo avamposto fortificato negli Altopiani d'Arathi. Antiche rovine umane e poteri ostili circondano l'insediamento. I troll della foresta Scorzasecca e gli ogre Pugno di Pietra hanno stretto un patto, mettendo a rischio la testa di ponte dell'Orda. Drum Fel chiama i campioni a colpire per primi e impedire ai nemici di decidere l'esito dello scontro."},{t="La minaccia Scorzasecca",b="A sud di Requie del Martello, i primi attacchi dell'Orda raggiungono il territorio degli Scorzasecca. I troll della foresta hanno rifiutato la diplomazia e si sono alleati con gli ogre Pugno di Pietra per scacciare l'Orda dagli altopiani. Requie del Martello prende di mira i loro lanciatori d'asce, cacciatori di teste e sciamani per indebolirne i capi e dimostrare che l'Orda intende restare."}},faq={{q="Chi offre la missione Call to Arms?",a="Drum Fel, un orco a Requie del Martello, nel nord-est degli Altopiani d'Arathi, chiama l'Orda alla battaglia. Dirige attacchi difensivi e offensivi per proteggere l'avamposto dalle minacce vicine.",al={"chi dà call to arms","dove si trova drum fel","chi assegna la missione call to arms"}},{q="Perché Requie del Martello ha preso di mira i troll Scorzasecca?",a="I troll della foresta Scorzasecca si sono alleati con gli ogre Pugno di Pietra per scacciare l'Orda dagli Altopiani d'Arathi. La loro ostilità mette a rischio la testa di ponte di Requie del Martello.",al={"perché uccidere gli scorzasecca","perché attaccare i troll ad arathi","cosa hanno fatto gli scorzasecca"}},{q="Dove si trovano i troll Scorzasecca?",a="I troll Scorzasecca vivono in insediamenti e accampamenti a sud di Requie del Martello, anche nelle profondità del Villaggio degli Scorzasecca, vicino alle montagne.",al={"dove si trovano i troll scorzasecca","posizione accampamento scorzasecca","dove trovare lanciatori d'asce ad arathi"}},{q="Che ruolo svolgono gli ogre Pugno di Pietra in questo conflitto?",a="I Pugno di Pietra sono un brutale clan di ogre degli Altopiani d'Arathi. Drum Fel dice che si sono alleati con i troll Scorzasecca per scacciare l'Orda dagli altopiani.",al={"chi sono i pugno di pietra","ogre ad arathi","alleanza tra troll e pugno di pietra"}},{q="Cos'è Requie del Martello e perché ha bisogno di difesa?",a="Requie del Martello è il principale avamposto dell'Orda negli Altopiani d'Arathi, chiamato così in onore del Capoguerra Orgrim Martelfato. Sorge in un antico campo di internamento dell'Alleanza e offre all'Orda un santuario conquistato a fatica e una base militare nei Regni Orientali.",al={"cos'è requie del martello","storia di requie del martello","perché l'orda è ad arathi"}},{q="I troll Scorzasecca fanno parte dell'Orda?",a="No. Gli Scorzasecca sono troll della foresta nativi dei Regni Orientali, mentre i troll della giungla Puntascura appartengono all'Orda. Gli Scorzasecca rifiutano gli stranieri e hanno respinto con violenza le offerte dell'Orda.",al={"gli scorzasecca fanno parte dell'orda","i troll della foresta sono alleati dell'orda","puntascura contro scorzasecca"}}},fp="12,173,20.364.0,21.332.0,34.181.0,50.170.0,40.129.0,57.165.0,50.229.0,44.202.0"}
P.entries["quest:678"] = {n="Call to Arms",s="A Requie del Martello, Drum Fel manda guerrieri esperti contro gli ogre del Pugno di Pietra. I loro attacchi minacciano la presenza dell'Orda ad Arathi.",h="A Requie del Martello, Drum Fel manda guerrieri esperti contro gli ogre del Pugno di Pietra.",kw={"altopiani d'arathi","pugno di pietra","bruto pugno di pietra","magi pugno di pietra","call to arms","drum fel","requie del martello","ogre","viadotto di thandol"},ang={["class:Mage"]="Da mago, affronti i Magi del Pugno di Pietra, che usano le energie arcane per scopi distruttivi.",["class:Warrior"]="Da guerriero, affronti una prova diretta di resistenza e onore contro la forza bruta e il potere arcano.",["faction:Horde"]="Come membro dell'Orda, contribuisci a proteggere la presenza di Requie del Martello nei Regni Orientali respingendo gli aggressivi ogre del Pugno di Pietra.",["race:Orc"]="Come orco, hai un interesse personale nella difesa di Requie del Martello, che prende il nome dal Capoguerra Orgrim Martelfato, e nell'espellere i bruti rivali che minacciano questa fortezza commemorativa."},sec={{t="Una prova di coraggio",b="A Requie del Martello, Drum Fel chiama a raccolta i viaggiatori che hanno aiutato l'avamposto perché affrontino una minaccia reale. Gli ogre del Pugno di Pietra hanno tormentato la spedizione dell'Orda e messo alla prova i suoi difensori. Fel manda guerrieri contro questi nemici, non contro semplici schermagliatori. Si aspetta che tornino vivi o con onore e promette elogi per la loro tenacia in battaglia."},{t="La minaccia del Pugno di Pietra",b="A sud-ovest di Requie del Martello, il clan Pugno di Pietra si è trincerato vicino al ponte nanico tra Arathi e le Paludi Grigie. I bruti combattono al fianco di astuti magi, unendo forza schiacciante e magia letale. La loro aggressività minaccia le linee di rifornimento dell'Orda e il suo controllo della regione. Drum Fel ordina ai guerrieri di sconfiggere dieci bruti e quattro magi del Pugno di Pietra. La loro sconfitta indebolirà il clan e dimostrerà che Requie del Martello non cederà terreno né tollererà rivali ad Arathi."}},faq={{q="Chi assegna la missione Call to Arms?",a="Drum Fel, un ufficiale di Requie del Martello negli Altopiani d'Arathi nord-orientali, lancia l'appello. Manda combattenti esperti contro nemici pericolosi per proteggere l'avamposto e mettere alla prova la loro forza.",al={"chi assegna call to arms","missione drum fel","datore di missione call to arms"}},{q="Dove si trova il covo del Pugno di Pietra?",a="La tana del Pugno di Pietra si trova a sud-ovest di Requie del Martello, lungo la strada per il Viadotto di Thandol, il ponte nanico verso le Paludi Grigie. Bruti e magi si radunano in tane e tumuli di terra sugli altopiani.",al={"posizione pugno di pietra","dove sono gli ogre","covo pugno di pietra arathi"}},{q="Quali nemici devono essere sconfitti per questo compito?",a="Drum Fel chiede di sconfiggere dieci Bruti del Pugno di Pietra e quattro Magi del Pugno di Pietra prima di tornare a Requie del Martello. I bruti attaccano da vicino, mentre i magi lanciano incantesimi arcani da lontano.",al={"conteggio uccisioni call to arms","quali ogre uccidere","obiettivi call to arms"}},{q="Perché gli ogre del Pugno di Pietra sono considerati una minaccia per Requie del Martello?",a="I Pugno di Pietra si sono trincerati per tutta Arathi e hanno sfidato più volte la guarnigione dell'Orda a Requie del Martello. La loro posizione vicino alle rotte che portano al ponte nanico meridionale minaccia le ricognizioni e le linee di rifornimento dell'Orda, perciò Drum Fel vuole contenerli.",al={"perché combattere i pugno di pietra","i pugno di pietra sono ostili all'orda","minaccia ogre ad arathi"}},{q="Cosa intende Drum Fel per tornare in carne e ossa o nello spirito?",a="Drum Fel si aspetta che i suoi combattenti tornino vivi dopo aver compiuto la missione, ma onora chi cade combattendo valorosamente contro nemici formidabili. Affrontare gli ogre con tenacia e senza paura porta onore, che il guerriero sopravviva o meno.",al={"citazione drum fel","significato di tornare nello spirito","tornare in carne o spirito"}},{q="I giocatori dell'Alleanza possono intraprendere questa missione?",a="No. Drum Fel rivolge questo appello solo all'Orda a Requie del Martello. Le forze dell'Alleanza operano da Fosso dei Rifugiati, a ovest, e considerano ostili i difensori di Requie del Martello e gli ogre del Pugno di Pietra, rivali per il controllo degli Altopiani d'Arathi.",al={"call to arms è solo per l'orda","call to arms alleanza arathi","l'alleanza può fare questa missione"}},{q="Perché Drum Fel prende di mira sia i bruti che i magi?",a="I bruti formano la prima linea e assorbono i colpi, mentre i magi attaccano dalle retrovie con magie distruttive. Sconfiggere entrambi i tipi indebolisce la forza combinata dei Pugno di Pietra e impedisce loro di organizzare un contrattacco contro Requie del Martello.",al={"perché uccidere i magi","importanza magi pugno di pietra","bruto e mago pugno di pietra"}}},fp="12,131,16.330.0,22.452.0,33.184.0,38.185.0,48.185.0,64.242.0,58.230.0,42.231.0,46.249.0"}
P.entries["quest:679"] = {n="Call to Arms"}
P.entries["quest:68"] = {n="Leggenda di Stalvan",s="A Rivoluna, La leggenda di Stalvan ti riporta ai registri di Borgoscuro. Una lettera polverosa mai spedita, trovata in un vecchio baule, dimostra che Stalvan Mistmantle soggiornò lì prima che le sue tracce svanissero.",h="A Rivoluna, La leggenda di Stalvan ti riporta ai registri di Borgoscuro.",kw={"cancelliere daltry","maledizione di stalvan","borgoscuro","boscovespro","lettera polverosa mai spedita","baule","spirito infausto","mistmantle","rivoluna","stalvan"},ang={["class:Mage"]="Da mago, riconosci gli ingannevoli strumenti arcani dello spettro, dalla metamorfo alla maledizione debilitante, tra le forze innaturali che seguono Stalvan.",["class:Priest"]="Da sacerdote, puoi vedere come uno Spirito Infausto legato a un semplice scrigno di ricordi porti con sé un peso emotivo che non si è dissolto con la morte.",["faction:Alliance"]="Da viaggiatore dell'Alleanza, aiuti Borgoscuro a registrare le figure misteriose che hanno attraversato i confini della regione."},sec={{t="Una traccia dimenticata a Rivoluna",b="Mentre ricostruisci il passato di Stalvan Mistmantle, trovi una lettera polverosa mai spedita in un vecchio baule. Rivoluna era un tempo un insediamento agricolo, ma ora giace in rovina, gremita di fuorilegge e spettri inquieti. Pochi ricordano il suo breve soggiorno, ma la lettera lo colloca nel villaggio."},{t="Una presenza inquietante al baule",b="Disturbare il baule fa uscire uno Spirito Infausto dalle ombre, deciso a custodire ciò che resta. Attacca con magie ammalianti e con la debilitante Maledizione di Stalvan. La sofferenza e gli incantesimi oscuri sono ancora legati ai possedimenti di Stalvan."},{t="Aggiornamento del registro cittadino",b="Porti la lettera oltre il confine, a Borgoscuro, dove il Cancelliere Daltry custodisce i registri della città. Gli sembra strano che la lettera non sia mai stata spedita, ma le prove confermano il legame di Stalvan con Rivoluna. Ora i registri possono indicare dove si è diretto Stalvan."}},faq={{q="Cosa c'è dentro il vecchio baule a Rivoluna?",a="Il vecchio baule contiene una Lettera Polverosa Mai Spedita, risalente al soggiorno di Stalvan Mistmantle a Rivoluna. Conferma che visse lì prima di scomparire.",al={"cosa ho trovato","contenuto del baule","lettera di stalvan"}},{q="Perché uno spirito attacca quando si apre il baule?",a="Uno Spirito Infausto custodisce i possedimenti dimenticati di Stalvan e attacca chiunque disturbi il baule. Usa magie inquietanti, tra cui effetti di paura, incantesimi di metamorfo e la Maledizione di Stalvan.",al={"spirito infausto","perché vengo attaccato","fantasma del baule"}},{q="Perché portare la lettera al Cancelliere Daltry?",a="Il Cancelliere Daltry sovrintende ai registri e agli archivi di Borgoscuro. Gli servono prove dei luoghi in cui Stalvan è stato prima di poter aiutarti a rintracciarlo.",al={"chi è il cancelliere daltry","perché daltry","darkshire town hall"}},{q="Perché è significativo che la lettera non sia mai stata spedita?",a="La lettera abbandonata è rimasta nel baule, segno che Stalvan se ne andò in fretta o divenne paranoico. La sua presenza infittisce il mistero dei suoi spostamenti.",al={"mistero della lettera non spedita","perché non è stata spedita"}},{q="Cosa fa la Maledizione di Stalvan?",a="La Maledizione di Stalvan dello Spirito Infausto è una maledizione debilitante che riduce tutti gli attributi primari della vittima per dieci minuti.",al={"debuff maledizione di stalvan","maledizione dello spirito"}},{q="Dove porta la pista dopo aver consegnato la lettera a Daltry?",a="Dopo che il Cancelliere Daltry registra le prove provenienti da Rivoluna, può indicarti la prossima destinazione conosciuta di Stalvan.",al={"cosa fare dopo","dove dopo daltry","indizio successivo"}}},fp="21,187,30.276.0,28.225.1,26.268.0,47.139.0,50.185.0,36.143.0,53.154.0,34.127.0,60.111.0"}
P.entries["quest:680"] = {n="The Real Threat",s="Korin Fel ti chiede di porre fine agli attacchi a Requie del Martello uccidendo Or'Kalar e portandole la sua testa.",h="Korin Fel ti chiede di porre fine agli attacchi a Requie del Martello uccidendo Or'Kalar e portandole la sua...",kw={"altopiani d'arathi","requie del martello","korin fel","mug'thol","or'kalar","stromgarde","torre di arathor"},sec={{t="Un rancore contro suo marito",b="Korin Fel dice che servi bene suo marito, anche se lui non sa perché Requie del Martello sia sotto attacco. Or'Kalar è al servizio di Mug'thol a Stromgarde e vuole la morte di suo marito. Anni fa, suo marito sconfisse l'orco. Ora i presagi di Korin le dicono che Or'Kalar gli ha teso una trappola."},{t="Ciò che Korin nasconde",b="Korin ha nascosto a suo marito ogni segno della presenza di Or'Kalar. Teme che lui si precipiti via avventatamente se sapesse dove si trova l'orco, perciò chiede a te di aiutarla. Or'Kalar è vicino alla Torre di Arathor. Korin si aspetta che la sua morte ponga fine agli attacchi a Requie del Martello."}},faq={{q="Chi sta cercando di proteggere Korin Fel?",a="Korin Fel sta cercando di proteggere suo marito. I suoi presagi le dicono che Or'Kalar gli ha teso una trappola. L'orco lo vuole morto perché anni fa lui lo sconfisse.",al={"marito di korin","perché korin ha bisogno di aiuto"}},{q="Perché Or'Kalar sta attaccando Requie del Martello?",a="Or'Kalar attacca Requie del Martello come pedone di Mug'thol a Stromgarde. Odia il marito di Korin Fel, che lo sconfisse anni fa. Korin dice che la morte di Or'Kalar porrebbe fine agli attacchi.",al={"perché or'kalar odia il marito di korin","chi è or'kalar","movente di or'kalar"}},{q="Dove si trova Or'Kalar?",a="Vicino alla Torre di Arathor.",al={"posizione di or'kalar","dove trovare or'kalar","trovare or'kalar"}},{q="Perché Korin tiene nascosta la minaccia a suo marito?",a="Korin teme che suo marito si precipiti via avventatamente se scoprisse dove si trova Or'Kalar. Perciò gli ha nascosto ogni segno della presenza dell'orco.",al={"perché mantenere il segreto","perché nascondere or'kalar","segreto di korin"}}},fp="15,98,28.274.0,16.266.0,35.158.0,37.171.0,26.30.0,57.135.0"}
P.entries["quest:681"] = {n="Maniero dei Norten",s="Al Fosso dei Rifugiati, il Capitano Nials chiede il tuo aiuto contro la Lega dei Tagliagole al Maniero dei Norten. Il loro controllo tra i difensori di Stromgarde e Riva del Sud rallenta i rifornimenti.",h="Al Fosso dei Rifugiati, il Capitano Nials chiede il tuo aiuto contro la Lega dei Tagliagole al Maniero dei...",kw={"capitano nials","bandito","mercenario","maniero dei norten","fosso dei rifugiati","riva del sud","stromgarde","lega dei tagliagole"},sec={{t="Una difesa in difficoltà",b="Gli ogre, la Lega dei Tagliagole e l'Alleanza si contendono Stromgarde, e le fazioni combattono fino a un sanguinoso stallo. Le forze dell'Alleanza diminuiscono mentre i nemici crescono. I difensori hanno bisogno dell'aiuto di Riva del Sud, ma i rifornimenti tardano ad arrivare."},{t="La Lega dei Tagliagole al maniero",b="La Lega dei Tagliagole controlla il territorio tra i difensori e Riva del Sud. Il Capitano Nials ti chiede di andare al Maniero dei Norten, la base della Lega dei Tagliagole, e fare fuori i suoi banditi e mercenari. Spera che allentare la loro pressione permetta a più convogli di rifornimento di passare."}},faq={{q="Perché il Capitano Nials vuole che la Lega dei Tagliagole venga attaccata al Maniero dei Norten?",a="La Lega dei Tagliagole controlla il territorio tra i difensori e Riva del Sud. Il Capitano Nials spera che ucciderli nella loro base allenti la pressione sui convogli di rifornimento.",al={"perché attaccare il maniero dei norten","obiettivo di nials","scopo della missione maniero dei norten"}},{q="Qual è la situazione attuale a Stromgarde?",a="Gli ogre, la Lega dei Tagliagole e l'Alleanza si sono spartiti Stromgarde, e le fazioni combattono fino a un sanguinoso stallo. Le forze dell'Alleanza diminuiscono mentre i nemici crescono.",al={"stato della guerra a stromgarde","chi controlla stromgarde","stato di stromgarde"}},{q="Da dove arrivano i rifornimenti dell'Alleanza?",a="I difensori sperano di ricevere aiuto da Riva del Sud, ma il controllo della Lega dei Tagliagole sul territorio intermedio rende difficile ricevere rifornimenti.",al={"chi rifornisce fosso dei rifugiati","rifornimenti di riva del sud","da dove provengono le spedizioni"}},{q="Quali nemici devono essere eliminati al maniero?",a="Dieci banditi della Lega dei Tagliagole e sei mercenari della Lega dei Tagliagole al Maniero dei Norten.",al={"chi uccidere a northfold","bersagli di northfold","elenco dei nemici della lega dei tagliagole"}}},fp="15,162,20.224.0,26.254.0,70.163.0,44.162.0,44.124.0,49.74.0"}
P.entries["quest:682"] = {n="Stromgarde Badges",s="A Stromgarde, la Lega dei Tagliagole paga per le mostrine dei miliziani caduti. A Fosso dei Rifugiati, il Capitano Nials vuole che vengano recuperate.",h="A Stromgarde, la Lega dei Tagliagole paga per le mostrine dei miliziani caduti.",kw={"arathi","distintivi","capitano nials","milizia","fosso dei rifugiati","stromgarde","lega dei tagliagole"},sec={{t="Una taglia sui soldati",b="La Lega dei Tagliagole combatte contro un contingente della milizia a Stromgarde. I suoi leader offrono oro per ogni mostrina sottratta a un miliziano ucciso, sperando di spingere i propri seguaci contro i soldati meglio addestrati. Il Capitano Nials chiama la Lega dei Tagliagole tagliagole e non vuole che tengano trofei dei coraggiosi caduti. Ti addentri nella parte di Stromgarde che controllano e riporti le mostrine a Fosso dei Rifugiati. Nials vuole che imparino a non trarre profitto dai morti."},{t="Dopo la caccia",b="Il Capitano Nials promette di dire ai familiari dei miliziani caduti che i loro cari sono morti in battaglia. La notizia è cupa, ma crede sia meglio che lasciare una famiglia a chiedersi che fine abbia fatto una persona scomparsa."}},faq={{q="Perché la Lega dei Tagliagole vuole le mostrine di Stromgarde?",a="I leader della Lega dei Tagliagole offrono oro per ogni mostrina sottratta a un miliziano caduto. Sperano che la ricompensa spinga i loro seguaci a combattere contro le truppe meglio addestrate.",al={"perché la lega dei tagliagole vuole le mostrine","ricompensa della lega dei tagliagole a stromgarde","perché raccogliere distintivi"}},{q="Dove si trovano gli Stromgarde Badges?",a="Trovi le mostrine nella parte di Stromgarde controllata dalla Lega dei Tagliagole.",al={"dove trovare distintivi","posizione distintivo stromgarde","posizione caduta distintivo"}},{q="Chi ordina il recupero degli Stromgarde Badges?",a="Il Capitano Nials a Fosso dei Rifugiati ordina di recuperare le mostrine. Non lascerà che la Lega dei Tagliagole tenga i trofei dei miliziani caduti.",al={"chi fornisce stromgarde badges","missione distintivi capitano nials","datore di missione stromgarde badges"}}},fp="17,132,20.450.0,14.215.1,46.161.0,27.74.0,39.129.0"}
P.entries["quest:683"] = {n="Supplica di Sara Balloo",s="A Forgiardente, Sara Balloo è in lutto per Sully e ti chiede di portare la sua supplica a Re Magni Barbabronzea.",h="A Forgiardente, Sara Balloo è in lutto per Sully e ti chiede di portare la sua supplica a Re Magni...",kw={"a king's tribute","dun morogh","forgiardente","magni barbabronzea","sara balloo","sully balloo","viadotto di thandol"},ang={["faction:Alliance"]="Come membro dell’Alleanza, porti messaggi tra i cittadini in lutto e i leader dell’Alleanza. Sei testimone del costo personale della difesa del regno.",["race:Dwarf"]="Da nano, portare la supplica di una vedova in lutto al tuo re tocca da vicino l’importanza che il tuo popolo attribuisce alla lavorazione della pietra, alla discendenza e all’onore dei sacrifici ancestrali."},sec={{t="La richiesta di una vedova",b="Sara ha ricevuto l’ultima lettera di Sully, recuperata dalle acque del Viadotto di Thandol. Vuole che il re ricordi il suo sacrificio, così gli scrive una supplica. Il dolore le impedisce di presentarsi di persona davanti al trono. Affida la lettera sigillata a te, campione dell’Alleanza, perché la consegni a Re Magni Barbabronzea."},{t="Udienza con il Re",b="Al High Seat di Forgiardente, Re Magni Barbabronzea mette da parte gli affari di stato per leggere la supplica personale di Sara. Prende nota dei coraggiosi difensori di Khaz Modan. La sua attenzione dimostra il legame con i nani comuni che hanno costruito e difendono il suo regno montano."}},faq={{q="Chi è Sara Balloo?",a="Sara Balloo è una nana che vive a Forgiardente. Suo marito, il soldato Sully Balloo, è morto nella tragedia del Viadotto di Thandol, e lei custodisce il suo ricordo.",al={"sara balloo","chi è sara"}},{q="Perché Sara vuole che io veda il Re invece di andarci di persona?",a="Sara è sopraffatta dal dolore dopo aver saputo cos’è accaduto a Sully. Non si sente in grado di mantenere la compostezza richiesta per presentarsi al High Seat davanti a Re Magni Barbabronzea.",al={"perché sara non può andare","dolore di sara"}},{q="Chi era Sully Balloo?",a="Sully Balloo era un soldato nano che difendeva il Viadotto di Thandol. Morì combattendo lungo il ponte, lasciando alla moglie una lettera intrisa d’acqua.",al={"sully balloo","marito di sara"}},{q="Dove consegno la Supplica di Sara Balloo?",a="Consegni la supplica di Sara a Re Magni Barbabronzea, al High Seat, nel centro di Forgiardente.",al={"dov'è magni","posizione di re magni","dove consegnare"}},{q="Cosa succede dopo che Re Magni legge la supplica?",a="Dopo aver letto la supplica di Sara, Re Magni rende onore a Sully Balloo. Da questa vicenda nascono A King's Tribute e la creazione di un monumento duraturo.",al={"continuazione missione","prossima missione"}},{q="Quale fazione può intraprendere questo compito?",a="Solo i membri dell’Alleanza possono portare la supplica di Sara, che riguarda gli affari dei nani e un’udienza con Re Magni Barbabronzea.",al={"l’orda può farlo","requisito di fazione"}}},fx={ca82ce02={q="Perché Sara Balloo vuole che la sua supplica venga consegnata a Re Magni?",a="Sara Balloo è in lutto per la perdita del marito, Sully Balloo, caduto mentre difendeva il Viadotto di Thandol. Dopo aver finalmente ricevuto la sua ultima lettera, recuperata sotto il viadotto, vuole che Re Magni Barbabronzea riconosca ufficialmente il sacrificio di Sully e ne onori la memoria. Consegnare questa supplica è il suo modo per fare in modo che la devozione del defunto marito all'Alleanza venga ricordata a Forgiardente.",al={"perché sara balloo vuole che venga fatto","motivo di sara balloo","perché consegnare la supplica a magni"}}},fp="18,101,17.321.0,22.261.1,19.150.0,63.170.0,21.141.0,38.96.0,45.126.1,37.129.0"}
P.entries["quest:684"] = {n="WANTED: Marez Cowl",s="A Stromgarde, Marez Cowl consiglia i capi della Lega dei Tagliagole e traffica con i demoni. La sua influenza minaccia le forze dell'Alleanza negli Altopiani d'Arathi.",h="A Stromgarde, Marez Cowl consiglia i capi della Lega dei Tagliagole e traffica con i demoni.",kw={"altopiani d'arathi","taglia","capitano nials","marez cowl","fosso dei rifugiati","stromgarde","lega dei tagliagole","stregone"},ang={["class:Paladin"]="Da stregona che traffica apertamente con i demoni tra le rovine di un antico regno umano, Cowl oltraggia la Sacra Luce e la difesa di Stromgarde.",["class:Warlock"]="Marez Cowl appartiene all'ala occulta più oscura della Lega dei Tagliagole. Il suo ricorso alle evocazioni demoniache mostra come i rinnegati politici si rivolgano ai demoni per estendere la propria influenza.",["faction:Alliance"]="La guarnigione dell'Alleanza al Fosso dei Rifugiati, guidata dal Capitano Nials, combatte per riconquistare Stromgarde. I capi di alto rango della Lega dei Tagliagole, come Marez Cowl, sono obiettivi strategici."},sec={{t="Una taglia sui capi della Lega dei Tagliagole",b="Al Fosso dei Rifugiati, i comandanti dell'Alleanza offrono una taglia su una figura di alto rango della Lega dei Tagliagole. Marez Cowl ne è consigliera e dirige le attività del gruppo tra le rovine di Stromgarde come operativa sul campo. La taglia mira a spezzare il comando locale del gruppo."},{t="La stregona di Stromgarde",b="Marez Cowl è una stregona tra i briganti e i nobili spodestati della Lega dei Tagliagole. Si serve apertamente dei poteri demoniaci per imporre la sua volontà e difendere il territorio della Lega. Per raggiungere il suo covo a Stromgarde, dovrai affrontare criminali armati e i demoni che comanda."}},faq={{q="Chi è Marez Cowl?",a="Marez Cowl è una consigliera e operativa di alto rango della Lega dei Tagliagole. Esercita una notevole influenza nell'organizzazione ed è una pericolosa stregona che traffica con i demoni.",al={"chi è marez cowl","background marez cowl","chi è lei"}},{q="Dove si trova Marez Cowl?",a="Marez Cowl si trova nella parte di Stromgarde in rovina controllata dalla Lega dei Tagliagole, negli Altopiani d'Arathi. Le forze criminali sono trincerate lì e dovrai farti strada tra loro per raggiungere il suo covo.",al={"dove trovare marez cowl","posizione marez cowl","dove si trova marez"}},{q="Chi ha affisso la taglia su Marez Cowl?",a="La taglia è offerta dall'esercito dell'Alleanza negli Altopiani d'Arathi. A sovrintendere all'incarico è il Capitano Nials, comandante della roccaforte dell'Alleanza al Fosso dei Rifugiati.",al={"chi ha messo la taglia su marez cowl","chi vuole morta marez cowl","chi paga la taglia"}},{q="Perché c'è una taglia sulla sua testa?",a="Marez Cowl è ricercata per il suo ruolo ai vertici della Lega dei Tagliagole e per il ricorso alle evocazioni demoniache a Stromgarde. Minaccia la guarnigione dell'Alleanza che cerca di riconquistare il regno in rovina.",al={"perché marez cowl è ricercata","perché taglia su marez cowl","perché uccidere marez cowl"}},{q="Che tipo di magia usa Marez Cowl?",a="Marez Cowl usa la magia degli stregoni per evocare i demoni e stringere patti con loro. Affronta lei e i demoni che comanda con estrema cautela.",al={"cosa rende pericolosa marez cowl","poteri marez cowl","marez cowl è forte"}},{q="Dove si consegna la taglia per Marez Cowl?",a="Dopo aver ucciso Marez Cowl, porta la sua testa al Capitano Nials al Fosso dei Rifugiati, l'avamposto dell'Alleanza negli Altopiani d'Arathi.",al={"dove consegnare taglia marez cowl","dove si trova il capitano nials","consegnare testa di marez"}}},fp="18,142,31.242.0,25.262.0,18.155.0,28.184.0,36.147.0,34.171.0,39.132.0,47.124.0"}
P.entries["quest:685"] = {n="WANTED: Otto and Falconcrest",s="Negli Altopiani d'Arathi, la Milizia di Stromgarde ha condannato a morte Lord Falconcrest e Otto. Falconcrest guida le forze locali della Lega dei Tagliagole, e Otto lo protegge con abilità letale. La loro morte indebolirebbe il controllo della Lega dei Tagliagole sulla regione. Le prove devono giungere al Capitano Nials a Fosso dei Rifugiati.",h="Negli Altopiani d'Arathi, la Milizia di Stromgarde ha condannato a morte Lord Falconcrest e Otto.",kw={"altopiani d'arathi","taglia","capitano nials","falconcrest","otto","fosso dei rifugiati","milizia di stromgarde","lega dei tagliagole"},ang={["faction:Alliance"]="Lord Falconcrest e i suoi agenti della Lega dei Tagliagole minacciano ciò che resta di Stromgarde. Questa taglia è importante per riconquistare gli altopiani.",["race:Human"]="Essendo umano, combatti anche per una ragione personale. Abbattere i nobili umani traditori della Lega dei Tagliagole aiuta a vendicare il tuo regno caduto."},sec={{t="Una taglia disperata",b="Da Fosso dei Rifugiati, i difensori di Stromgarde cercano di spezzare il controllo della Lega dei Tagliagole sulle loro terre ancestrali. La milizia ha messo una taglia su Lord Falconcrest e Otto, la sua guardia del corpo. Porta le teste di entrambi al Capitano Nials per riscuotere la ricompensa."},{t="Comandante ed esecutore",b="Lord Falconcrest dirige l'avanzata della Lega dei Tagliagole negli Altopiani d'Arathi. La sua morte sconvolgerebbe le attività della rete criminale nella regione. Otto è una guardia del corpo spietatamente efficace. Le sue lame hanno ucciso dozzine di soldati rimasti della milizia di Stromgarde."}},faq={{q="Chi è Lord Falconcrest?",a="Lord Falconcrest è un nobile che comanda le operazioni della Lega dei Tagliagole negli Altopiani d'Arathi. Organizza il loro tentativo di conquistare il regno in rovina di Stromgarde, ed è per questo un obiettivo prioritario della milizia umana locale.",al={"chi è lord falconcrest","storia di falconcrest","chi è falconcrest"}},{q="Chi è Otto?",a="Otto è la letale guardia del corpo personale di Lord Falconcrest. Combattente feroce più che stratega, ha ucciso dozzine di difensori di Stromgarde negli altopiani.",al={"chi è otto","guardia del corpo di falconcrest","otto lega dei tagliagole"}},{q="Perché la Milizia di Stromgarde ha messo una taglia su di loro?",a="La Milizia di Stromgarde vuole decimare i vertici della Lega dei Tagliagole negli Altopiani d'Arathi. La morte di Falconcrest sconvolgerebbe il loro comando regionale, mentre quella di Otto eliminerebbe una minaccia letale che ha ucciso molti combattenti dell'Alleanza.",al={"perché taglia su falconcrest","perché uccidere otto e falconcrest","taglia di stromgarde"}},{q="Chi offre la ricompensa per Otto e Falconcrest?",a="Il Capitano Nials, ufficiale della Milizia di Stromgarde a Fosso dei Rifugiati negli Altopiani d'Arathi, raccoglie le taglie per Lord Falconcrest e Otto.",al={"dove consegnare otto falconcrest","chi è il capitano nials","consegna taglia falconcrest"}},{q="Cosa sta facendo la Lega dei Tagliagole negli Altopiani d'Arathi?",a="La Lega dei Tagliagole è composta da nobili alteracchi decaduti ed elementi fuorilegge in cerca di terre e ricchezze nel crollo di Lordaeron settentrionale. Dagli Altopiani d'Arathi, si sono spinti tra le rovine di Stromgarde per strappare il controllo ai difensori sopravvissuti.",al={"cos'è la lega dei tagliagole ad arathi","ruolo della lega dei tagliagole ad arathi"}},{q="Quale prova è richiesta per riscuotere la taglia?",a="Porta direttamente al Capitano Nials a Fosso dei Rifugiati le teste mozzate di Lord Falconcrest e Otto, come prova della loro morte.",al={"dove portare la testa di otto","prova della taglia"}}},fp="28,291,18.246.0,22.253.0,24.212.0,12.163.0,55.236.0,47.146.0,52.243.0,43.121.0"}
P.entries["quest:686"] = {n="A King's Tribute",s="Re Magni Barbabronzea risponde a Sara Balloo con un tributo duraturo al marito caduto, Sully. Ti manda per Forgiardente con un incarico reale per il Gran Muratore Marmoduro.",h="Re Magni Barbabronzea risponde a Sara Balloo con un tributo duraturo al marito caduto, Sully.",kw={"forgiardente","magni barbabronzea","marmoduro","memoriale","sara balloo","sully balloo","viadotto di thandol"},ang={["faction:Alliance"]="Come combattente dell'Alleanza, sai che i caduti al Viadotto di Thandol hanno dato la vita per proteggere le cruciali linee di rifornimento tra Khaz Modan e i regni settentrionali.",["race:Dwarf"]="Da nano, vedi la dedizione di Re Magni al suo popolo. Il trono ricorda anche il più umile fante nano."},sec={{t="Il Fardello di un Sovrano",b="La supplica di Sara Balloo pesa su Re Magni Barbabronzea. La dura necessità della guerra può essere difficile da comprendere per la gente comune, eppure ogni soldato sotto le insegne dell'Alleanza grava sulla sua coscienza. Non può rimediare a una morte in prima linea. Può fare in modo che il sacrificio di Sully Balloo venga ricordato."},{t="Lo Scalpello del Muratore",b="Re Magni sceglie un memoriale di pietra per Sully, non parole vuote. Ti affida il suo incarico reale e ti manda per Forgiardente dal Gran Muratore Marmoduro. Il maestro muratore riceve l'incarico personale del Re e si prepara a scolpire nella pietra il ricordo del difensore caduto."}},faq={{q="Chi era Sully Balloo?",a="Sully Balloo era un soldato nano morto difendendo il Viadotto di Thandol per l'Alleanza. Dopo aver appreso della sua morte, la vedova, Sara Balloo, presentò una petizione a Re Magni Barbabronzea.",al={"chi è sully","lore di sully balloo","chi è morto"}},{q="Perché Re Magni commissiona un memoriale?",a="Re Magni porta il peso di ogni vita nanica perduta nelle lotte dell'Alleanza. Non può restituire Sully alla vedova, così commissiona un monumento duraturo per rendere onore al coraggio del soldato.",al={"perché costruire un memoriale","motivazione di magni","scopo di a king's tribute"}},{q="Chi è il Gran Muratore Marmoduro?",a="Il Gran Muratore Marmoduro è il maestro scalpellino di Forgiardente. Gli vengono affidati importanti progetti edilizi civili e reali in tutta la città, e Re Magni conta su di lui per scolpire il memoriale di Sully Balloo.",al={"chi è il gran muratore marmoduro","ruolo del gran muratore"}},{q="Dove si svolge questa missione?",a="Ti sposti all'interno di Forgiardente, partendo dall'High Seat con Re Magni Barbabronzea e poi raggiungendo il Gran Muratore Marmoduro in un'altra zona della capitale.",al={"dove si trova questa missione","luogo della missione"}},{q="Cosa precede questa missione?",a="Prima di questo, consegni direttamente a Re Magni Barbabronzea la lettera colma di dolore di Sara Balloo.",al={"prerequisiti","missione precedente"}},{q="Questo memoriale è solo per Sully Balloo?",a="Il tributo porta il nome di Sully Balloo e vuole consolare la vedova, Sara. Rende inoltre onore a ogni combattente nano morto al servizio dell'Alleanza.",al={"chi onora","è solo per sully"}}},fx={["66401eff"]={q="Perché Re Magni sceglie te come custode del tributo?",a="Sei stato tu a portare la sentita supplica di Sara Balloo direttamente all'High Seat, presentando la sua tragedia personale al re. Poiché hai scelto di ascoltare il dolore di una vedova in lutto e di riferire le sue parole al sovrano, Magni ti affida il compito di far sì che l'onore regale venga reso, nominandoti custode del suo incarico invece di delegarlo ai burocrati di palazzo.",al={"perché io per il tributo del re","perché magni manda te","perché ha scelto me"}}},fp="16,177,20.284.0,18.284.0,21.176.0,42.190.0,30.203.0,33.149.0,29.91.0,39.146.0"}
P.entries["quest:687"] = {n="Theldurin il Perduto",s="Nelle Maleterre, il Martello del Crepuscolo dà la caccia a Theldurin il Perduto e alla Pergamena di Myzrael, che ha preso durante la fuga.",h="Nelle Maleterre, il Martello del Crepuscolo dà la caccia a Theldurin il Perduto e alla Pergamena di Myzrael...",kw={"maleterre","gerrig morsaossa","myzrael","pergamena di myzrael","theldurin","theldurin il perduto","martello del crepuscolo","zaruk"},sec={{t="L'uomo che rubò la pergamena",b="Un tempo Theldurin seguiva il Martello del Crepuscolo. Poi la sua mente ha ceduto e ha rinnegato i suoi insegnamenti. È fuggito con la Pergamena di Myzrael e l'ordine non è riuscito a catturarlo."},{t="Voci dalle Maleterre",b="Al Martello del Crepuscolo è giunta voce che Theldurin si nasconda nelle Maleterre, delirante e folle. L'ordine ha bisogno della pergamena per il ritorno della Signora. Per prima cosa, devi trovare l'uomo che l'ha presa."}},faq={{q="Chi è Theldurin il Perduto?",a="Un tempo Theldurin il Perduto seguiva il Martello del Crepuscolo. Dopo che la sua mente ha ceduto, ha rinnegato i suoi insegnamenti ed è fuggito con la Pergamena di Myzrael.",al={"storia di theldurin","chi è theldurin","lore di theldurin"}},{q="Perché il Martello del Crepuscolo gli dà la caccia?",a="Il Martello del Crepuscolo cerca Theldurin perché è fuggito con la Pergamena di Myzrael. L'ordine dice di averne bisogno per riportare indietro la Signora.",al={"perché trovare theldurin","perché i cultisti vogliono theldurin"}},{q="Dove è fuggito Theldurin dopo aver lasciato l'ordine?",a="Le voci collocano Theldurin nelle Maleterre, ma il Martello del Crepuscolo non sa con certezza dove si trovi.",al={"dove si trova theldurin","luogo di theldurin nella lore"}},{q="Cosa precede direttamente questa ricerca?",a="La ricerca segue Myzrael's Allies.",al={"missione precedente theldurin","prerequisito per theldurin il perduto"}}},fp="18,115,28.174.0,22.184.0,26.142.0,45.140.0,49.96.0,39.36.0"}
P.entries["quest:688"] = {n="Myzrael's Allies",s="Attraverso la Chiave di Pietra, Myzrael dichiara di essere libera, anche se è ancora nascosta ai suoi carcerieri. Ti manda da Zaruk a Requie del Martello, che sa come evocarla.",h="Attraverso la Chiave di Pietra, Myzrael dichiara di essere libera, anche se è ancora nascosta ai suoi...",kw={"altopiani d'arathi","giganti","requie del martello","chiave di pietra","myzrael","zaruk"},sec={{t="Libera ma Nascosta",b="Myzrael dichiara di essere libera grazie alla Chiave di Pietra. Deve raccogliere le forze lontano dagli occhi dei suoi carcerieri. La sopraffarebbero e la imprigionerebbero di nuovo se la affrontassero ora. Col tempo, giura, affronterà i giganti che l'hanno tenuta prigioniera e farà loro rimpiangere di averlo fatto."},{t="Zaruk di Requie del Martello",b="Myzrael ti definisce un nobile alleato e dice che avrà ancora bisogno del tuo aiuto in futuro. Quando sarà pronta, ti chiederà di evocarla in superficie. Per ora, ti manda da Zaruk a Requie del Martello, che sa come farlo."}},faq={{q="Chi ti manda da Zaruk?",a="Myzrael stessa parla attraverso la Chiave di Pietra e ti dice di andare da Zaruk a Requie del Martello.",al={"chi assegna gli alleati di myzrael","chi dà la missione gli alleati di myzrael","chi parla attraverso la chiave di pietra"}},{q="Perché Myzrael si nasconde?",a="Myzrael dice che i suoi carcerieri la sopraffarebbero e la imprigionerebbero di nuovo se la affrontassero ora. Si nasconde mentre raccoglie le forze.",al={"perché myzrael non combatte","perché myzrael è debole","perché myzrael si nasconde"}},{q="Dove si trova Zaruk?",a="Zaruk si trova a Requie del Martello.",al={"posizione di zaruk","dove si trova zaruk","trovare zaruk"}},{q="Che ruolo ha Zaruk per Myzrael?",a="Myzrael dice che Zaruk sa come evocarla.",al={"perché parlare con zaruk","cosa sa zaruk","scopo di zaruk"}}},fp="16,157,15.260.0,19.211.0,23.85.0,22.122.0,25.33.0,38.49.0"}
P.entries["quest:689"] = {n="A King's Tribute",s="Re Magni Barbabronzea ha ordinato un memoriale per Sully Balloo, morto difendendo il Viadotto di Thandol. Il Gran Muratore Marmoduro ti manda a nord, a Colletorto, a cercare una pietra degna del soldato caduto.",h="Re Magni Barbabronzea ha ordinato un memoriale per Sully Balloo, morto difendendo il Viadotto di Thandol.",kw={"granito d'alterac","collina di darrow","forgiardente","magni barbabronzea","marmoduro","muratore","sully balloo","viadotto di thandol"},ang={["faction:Alliance"]="Come membro dell'Alleanza, contribuisci a procurare materiali da Colletorto e a rafforzare la presenza dell'Alleanza nel nord diviso. Il memoriale onora un soldato semplice, morto per la causa comune.",["profession:Mining"]="Come minatore, sai che estrarre senza scheggiarle le vene dure e ostinate del Granito d'Alterac richiede mani esperte.",["race:Dwarf"]="Come nano, sai che la lavorazione della pietra, il sacrificio in battaglia e la lealtà a Re Magni Barbabronzea sono strettamente legati. Onorare Sully Balloo parla di tutte e tre le cose."},sec={{t="Una commissione reale",b="Il Gran Muratore Marmoduro ha ricevuto da Re Magni Barbabronzea l'incarico di onorare Sully Balloo. Sully morì nel disastro del Viadotto di Thandol. I sabotatori Ferroscuro hanno attaccato il viadotto, un'arteria vitale tra le terre naniche e i regni settentrionali. Marmoduro creerà una scultura che resista al tempo e alla guerra, perché la Grande Forgia ricordi il sacrificio dei nani."},{t="Pietra del Nord",b="Per scolpire le sembianze di Sully Balloo, Marmoduro ha bisogno di Granito d'Alterac. La sua pietra compatta e resistente, dalla grana fine, è molto apprezzata dai muratori. I giacimenti migliori si trovano intorno alla Collina di Darrow, nelle contese Alture di Colletorto. Il viaggio nel travagliato nord è pericoloso, ma Marmoduro cerca una pietra degna dell'eroismo che onorerà."}},faq={{q="Chi è Sully Balloo?",a="Sully Balloo era un soldato dell'Alleanza, morto difendendo il Viadotto di Thandol durante il suo catastrofico sabotaggio. Dopo aver ricevuto una lettera addolorata dalla vedova, Sara Balloo, Re Magni Barbabronzea ordinò una statua permanente in suo onore.",al={"sully balloo","chi era sully balloo","lore di sully balloo"}},{q="Chi è il Gran Muratore Marmoduro?",a="Il Gran Muratore Marmoduro è il maestro scultore e scalpellino di Forgiardente. Lavora dall'Area del Mercato della città, si occupa degli incarichi reali ed è orgoglioso di usare le pietre regionali più pregiate.",al={"gran muratore marmoduro","marmoduro forgiardente","chi è marmoduro"}},{q="Perché serve il Granito d'Alterac?",a="Il Granito d'Alterac è apprezzato in tutti i Regni Orientali per la sua densità, la grana fine e la resistenza all'erosione. Marmoduro crede che solo una pietra di questa qualità possa far durare nei secoli un tributo reale.",al={"perché granito d'alterac","scopo del granito d'alterac","cos'è il granito d'alterac"}},{q="Dov'è la Collina di Darrow?",a="La Collina di Darrow si trova nella parte settentrionale delle Alture di Colletorto, poco sotto il Promontorio e vicino al confine di Alterac. Le grotte della zona custodiscono Granito d'Alterac.",al={"dov'è la collina di darrow","posizione collina di darrow","trovare collina di darrow"}},{q="Cosa è successo al Viadotto di Thandol?",a="Il Viadotto di Thandol è un enorme ponte sull'abisso tra le Paludi Grigie e gli Altopiani d'Arathi. I sabotatori Ferroscuro piazzarono esplosivi per interrompere le rotte di rifornimento dell'Alleanza, uccidendo molti difensori.",al={"tragedia del viadotto di thandol","catastrofe del viadotto di thandol","cosa è successo al viadotto di thandol"}},{q="Cosa succede dopo aver portato il granito a Marmoduro?",a="Quando porti il Granito d'Alterac a Marmoduro, lui completa il memoriale e ti chiede di riferirlo a Re Magni.",al={"dopo aver consegnato il granito","progresso statua marmoduro"}}},fx={["1680ec58"]={q="Perché Gran Muratore Marmoduro vuole che venga fatto?",a="Re Magni Barbabronzea ha commissionato personalmente un monumento in onore del soldato caduto Sully Balloo. Per Gran Muratore Marmoduro, gli incarichi reali hanno la massima priorità e richiedono il suo lavoro migliore. Pur lamentando l'incessante spargimento di sangue in tutta Azeroth, insiste nell'usare solo la pietra più pregiata per realizzare un tributo davvero epico e duraturo, degno della richiesta del re.",al={"perché marmoduro se ne occupa","motivo di marmoduro","perché costruire il monumento a sully balloo"}}},fp="16,192,18.364.0,18.333.0,20.224.0,30.184.0,30.206.0,21.139.0,34.192.0,54.125.0"}
P.entries["quest:69"] = {n="Leggenda di Stalvan",s="A Borgoscuro, una voce scarabocchiata nel registro indirizza la ricerca di Stalvan Mistmantle verso Borgodoro.",h="A Borgoscuro, una voce scarabocchiata nel registro indirizza la ricerca di Stalvan Mistmantle verso Borgodoro.",kw={"cancelliere daltry","borgoscuro","boscovespro","foresta di elwynn","borgodoro","locandiere farley","locanda del fiero leone","stalvan"},ang={["faction:Alliance"]="Le storie locali e le piste ormai fredde si snodano nel sud dell'Alleanza, tra avamposti di frontiera come Borgoscuro e borghi come Borgodoro.",["race:Human"]="Dalla frontiera infestata di Boscovespro, la pista di Stalvan attraversa il cuore del Regno di Roccavento, fino alla familiare Foresta di Elwynn."},sec={{t="Indizio nel registro",b="Il Cancelliere Daltry trova un'altra destinazione sotto la voce precedente di Stalvan Mistmantle nel registro cittadino di Borgoscuro. La nota frettolosa è in parte cancellata. Qualcuno voleva nascondere il percorso o ha cambiato idea. Indica nord-ovest, verso la Locanda del Fiero Leone nella Foresta di Elwynn."},{t="Attraversando i confini di Elwynn",b="Lasci gli ombrosi boschetti di Boscovespro per le strade soleggiate di Borgodoro, dove arriva anche la pista di Stalvan. La Locanda del Fiero Leone sorge al crocevia della Foresta di Elwynn, dove si radunano viaggiatori, mercanti e soldati. Il Locandiere Farley gestisce la vivace sala comune e potrebbe sapere di un viandante istruito in cerca di una stanza."}},faq={{q="Perché le tracce portano a Borgodoro?",a="Il Cancelliere Daltry ha trovato un secondo indirizzo sotto la prima voce di Stalvan nel registro di Borgoscuro. Anche se in parte cancellato, indica la Locanda del Fiero Leone a Borgodoro.",al={"perché borgodoro","perché andare a borgodoro","stalvan a borgodoro"}},{q="Chi è il Cancelliere Daltry?",a="Il Cancelliere Daltry tiene i registri nel Municipio di Borgoscuro. Si occupa dei registri locali e aiuta a scoprire vecchi documenti sugli abitanti del passato.",al={"daltry","chi è daltry"}},{q="Con chi devo parlare alla Locanda del Fiero Leone?",a="Parla con il Locandiere Farley, che gestisce la Locanda del Fiero Leone e tiene d'occhio i viaggiatori e gli avventori di passaggio a Borgodoro.",al={"con chi parlare","contatto locanda del fiero leone","locandiere borgodoro"}},{q="Perché la voce nel registro è stata cancellata?",a="La voce nel registro è stata cancellata solo in parte. Qualcuno potrebbe aver cercato in fretta di nascondere il percorso di Stalvan verso la Foresta di Elwynn mentre lasciava Boscovespro.",al={"nota cancellata","perché cancellata"}},{q="Questa missione comporta dei combattimenti?",a="No. Vai dal Municipio di Borgoscuro alla sala comune di Borgodoro e chiedi di Stalvan.",al={"ci sono combattimenti","devo combattere qualcosa"}},{q="Cos'è la Locanda del Fiero Leone?",a="La Locanda del Fiero Leone è il principale luogo d'incontro di Borgodoro, nella Foresta di Elwynn. I viaggiatori vi trovano riposo sulle strade tra Roccavento, le Marche Occidentali e Boscovespro.",al={"locanda del fiero leone","locanda di borgodoro"}}},fx={f40d5969={q="Perché il Cancelliere Daltry vuole che Stalvan venga rintracciato?",a="In qualità di cancelliere di Borgoscuro, Daltry si occupa degli archivi e dei registri cittadini. Dopo che Dama Eva ti ha inizialmente messo sulle tracce della figura misteriosa nota come Stalvan Mistmantle, Daltry ha contribuito alla ricerca esaminando i suoi registri. Scoperta una voce trascurata e parzialmente cancellata sotto il primo indirizzo, ti chiede di seguire la nuova pista per ricostruire la storia dell'elusivo uomo.",al={"perché daltry se ne occupa","motivo di daltry per stalvan","perché rintracciare stalvan"}},["136b3a3d"]={q="Perché il Cancelliere Daltry ti manda a Borgodoro invece di andarci di persona?",a="Il Cancelliere Daltry è un impiegato civile legato al municipio di Borgoscuro, incaricato di tenere i registri e servire la popolazione locale in un insediamento assediato dagli orrori. Attraversare il fiume fino alla Foresta di Elwynn per interrogare gli osti non rientra nel suo ruolo e nei suoi doveri; un avventuriero in forze è molto più adatto a seguire piste lontane.",al={"perché mandare me","perché daltry non ci va","perché daltry ha bisogno di un avventuriero"}}},fp="21,98,20.274.0,20.304.0,37.167.0,20.140.0,42.126.0,48.140.0,35.92.0,29.159.0"}
P.entries["quest:690"] = {n="Malin's Request",s="A Roccavento, l'Arcimago Malin chiede aiuto per recuperare reliquie dalla caduta Stromgarde. Invia avventurieri esperti dell'Alleanza a nord, a Fosso dei Rifugiati negli Altopiani d'Arathi, dove una spedizione cerca le reliquie magiche lasciate indietro dopo la caduta di Stromgarde.",h="A Roccavento, l'Arcimago Malin chiede aiuto per recuperare reliquie dalla caduta Stromgarde.",kw={"altopiani d'arathi","malin","fosso dei rifugiati","skuerto","roccavento","stromgarde","torre di arathor","trelane","santuario della magia"},ang={["class:Mage"]="Come mago in visita al Santuario della Magia, puoi aiutare Malin a preservare preziose ricerche e reliquie arcane legate ai maghi di Arathor.",["faction:Alliance"]="Come membro dell'Alleanza, puoi contribuire a rafforzare Fosso dei Rifugiati, la fragile roccaforte che resta all'Alleanza ad Arathi.",["race:Human"]="Come umano, puoi contribuire a recuperare i tesori di Stromgarde, culla della civiltà umana, e a preservare l'eredità di Arathor."},sec={{t="I Beni Perduti di un Maestro",b="L'Arcimago Malin presta servizio nel Santuario della Magia di Roccavento e agisce per conto del suo ex mentore, l'Arcimago Trelane. Quando Stromgarde sprofondò nel caos, Trelane oppose un'ultima, disperata resistenza alla Torre di Arathor. Mentre le forze ostili conquistavano la città, dovette abbandonare la sua postazione e lasciare dietro di sé potenti oggetti incantati. Malin teme che quelle reliquie possano cadere in mani ostili. Invia mercenari capaci a nord per rafforzare i suoi agenti sul campo e recuperare i beni perduti di Trelane."},{t="L'avamposto sotto pressione a Fosso dei Rifugiati",b="Fosso dei Rifugiati si trova sulla strada per le reliquie di Trelane, nel centro degli Altopiani d'Arathi. L'avamposto è un rifugio sotto assedio per i lealisti di Stromgarde, e il principale contatto di Malin è il nano Skuerto. Fuorilegge della Lega dei Tagliagole, troll Scorcororte e ogre Pugno di Roccia premono sull'avamposto da ogni lato. Al tuo arrivo, Skuerto e la guarnigione sono troppo impegnati per accoglierti calorosamente senza un aiuto immediato."}},faq={{q="Chi è l'Arcimago Malin?",a="L'Arcimago Malin è un mago umano nel Santuario della Magia di Roccavento. Un tempo apprendista dell'Arcimago Trelane di Stromgarde, ora dirige da Roccavento gli sforzi per recuperare le ricerche magiche del suo mentore.",al={"arcimago malin","chi è malin","malin roccavento"}},{q="Perché Malin ha bisogno di aiuto ad Arathi?",a="Stromgarde cadde sotto assedio, costringendo l'Arcimago Trelane a fuggire dalla Torre di Arathor. Gli agenti di Malin stanno cercando di recuperare le reliquie abbandonate da Trelane, ma sono sopraffatti e hanno bisogno di rinforzi.",al={"perché andare ad arathi","scopo missione malin","perché altopiani d'arathi"}},{q="Dove si trova Skuerto?",a="Skuerto è uno scout nano di stanza a Fosso dei Rifugiati, un accampamento dell'Alleanza sulla principale via commerciale che attraversa il centro degli Altopiani d'Arathi.",al={"trovare skuerto","posizione skuerto","dove si trova fosso dei rifugiati"}},{q="Cosa è successo alla Torre di Arathor?",a="La Torre di Arathor era una roccaforte arcana a Stromgarde. Quando il regno cadde, l'Arcimago Trelane tentò di difenderla dai furfanti della Lega dei Tagliagole e dagli ogre Pugno di Roccia, ma le difese cedettero e fu costretto a fuggire.",al={"caduta torre di arathor","cosa è successo a stromgarde","torre di trelane"}},{q="Cosa succede dopo essersi presentati a Skuerto?",a="Skuerto è sopraffatto e sbrigativo al tuo arrivo. Ti manda dai suoi compagni a Fosso dei Rifugiati per iniziare a recuperare i beni dispersi di Trelane.",al={"seguito richiesta malin","prossima missione dopo malin","prossima missione skuerto"}},{q="Chi è l'Arcimago Trelane?",a="L'Arcimago Trelane è un importante mago di Stromgarde e il mentore dell'Arcimago Malin. Era tra i principali difensori della capitale degli Altopiani prima della caduta del regno.",al={"arcimago trelane","chi è trelane","trelane stromgarde"}}},fx={["5671e9ba"]={q="Perché l'Arcimago Malin ha bisogno di un avventuriero per questo incarico?",a="L'Arcimago Malin è legato al suo incarico nel Santuario della Magia di Roccavento, molto più a sud. Sebbene abbia già agenti di stanza a Fosso dei Rifugiati, negli Altopiani d'Arathi, questi hanno riferito che la situazione intorno alla città caduta di Stromgarde è disperata e richiede rinforzi. Un avventuriero itinerante ha la libertà di viaggiare rapidamente verso nord e la tempra necessaria per addentrarsi in rovine ostili e contese, difficili da raggiungere per gli emissari ufficiali.",al={"perché mandare un avventuriero","perché io per malin","perché malin non va di persona"}}},fp="15,250,26.467.0,37.407.0,22.199.0,35.198.0,25.136.0,38.207.0,40.154.0,24.154.0"}
P.entries["quest:691"] = {n="Worth Its Weight in Gold",s="Al Fosso dei Rifugiati, l'Apprendista Kryten ha bisogno di reagenti per l'Arcimago Malin. Ti chiede di raccogliere zanne, sacche di medicina e un pugnale da cacciatore dell'ombra dai troll Scorzasecca del sud-est di Arathi.",h="Al Fosso dei Rifugiati, l'Apprendista Kryten ha bisogno di reagenti per l'Arcimago Malin.",kw={"apprendista kryten","altopiani d'arathi","arcimago malin","sacca di medicina","fosso dei rifugiati","pugnale da cacciatore dell'ombra","skuerto","scorzasecca","zanna degli scorzasecca"},sec={{t="Reagenti di Malin",b="L'Arcimago Malin ha mandato Kryten e Skuerto ad Arathi per raccogliere reagenti. Kryten non sapeva come procurarseli finché non sei arrivato tu. Gli servono dieci zanne degli Scorzasecca, quattro sacche di medicina e un pugnale da cacciatore dell'ombra. I troll Scorzasecca vivono nel sud-est di Arathi."},{t="Cosa portano gli Scorzasecca",b="Secondo le ricerche di Kryten, ogni troll Scorzasecca dovrebbe avere zanne. Gli stregoni portano sacche di medicina. Il pugnale appartiene ai più potenti cacciatori dell'ombra, che lo ricevono dopo aver completato i riti di passaggio. Solo la battaglia mostrerà chi lo porta."}},faq={{q="Per chi lavora l'Apprendista Kryten?",a="L'Arcimago Malin ha mandato Kryten e Skuerto ad Arathi per raccogliere reagenti per lui.",al={"chi ha mandato kryten","maestro di kryten","perché kryten è ad arathi"}},{q="Dove si trovano i troll Scorzasecca?",a="Nel sud-est di Arathi, dove vivono gli Scorzasecca.",al={"posizione con gli scorzasecca","dove trovare gli scorzasecca","posizione villaggio degli scorzasecca"}},{q="Quali troll portano le sacche di medicina?",a="Secondo le ricerche di Kryten, gli stregoni Scorzasecca portano sacche di medicina. Ogni troll Scorzasecca dovrebbe avere zanne.",al={"fonte sacca di medicina","chi ha le sacche di medicina","sacca di medicina scorzasecca"}},{q="Come si trova il pugnale da cacciatore dell'ombra?",a="I più potenti cacciatori dell'ombra Scorzasecca portano il pugnale, ricevuto dopo i riti di passaggio. Solo la battaglia rivelerà chi lo possiede.",al={"posizione pugnale da cacciatore dell'ombra","chi lascia cadere il pugnale da cacciatore dell'ombra","pugnale del rito di passaggio"}}},fp="24,195,16.251.0,25.257.0,37.76.0,40.65.0,40.115.0,40.142.0"}
P.entries["quest:692"] = {n="The Lost Fragments",s="Alle spalle di Theldurin, elementali furiosi si contendono i frammenti della Pergamena di Myzrael. Raccogli i pezzi strappati, mentre lui teme cosa possa fare la sua magia.",h="Alle spalle di Theldurin, elementali furiosi si contendono i frammenti della Pergamena di Myzrael.",kw={"maleterre","frammento di pergamena stropicciato","elementali","myzrael","pergamena di myzrael","frammento di pergamena bruciacchiato","theldurin il perduto","frammento di pergamena strappato"},sec={{t="Una pergamena pericolosa",b="Theldurin il Perduto teme che la Pergamena di Myzrael possa far emergere Myzrael in superficie. Poi pensa a un altro pericolo. Potrebbe essere già libera, o star raccogliendo le forze per colpire. In tal caso, la pergamena potrebbe servirti per vincolarla di nuovo."},{t="Fatta a pezzi dagli elementi",b="Elementali furiosi hanno preso la pergamena e l'hanno fatta a pezzi. Ora si contendono i frammenti sulle colline alle spalle di Theldurin. Riporta tre pezzi: uno strappato, uno accartocciato e uno bruciacchiato. Theldurin spera di ripararli."}},faq={{q="Chi ti manda a raccogliere i frammenti della pergamena?",a="Theldurin il Perduto ti chiede di riportargli dei pezzi della pergamena distrutta.",al={"datore di missioni","chi avvia the lost fragments","missione di theldurin"}},{q="Cosa dovrebbe fare la Pergamena di Myzrael?",a="Theldurin dice che la magia della pergamena potrebbe far emergere Myzrael in superficie. Se è già libera, pensa che potrebbe servirti per vincolarla di nuovo.",al={"a cosa serve la pergamena","storia della pergamena di myzrael","perché trovare i frammenti della pergamena"}},{q="Dove si trovano i frammenti della pergamena?",a="Elementali furiosi hanno preso la pergamena, l'hanno fatta a pezzi e ora si contendono i frammenti sulle colline alle spalle di Theldurin.",al={"chi ha i frammenti","dove trovare i pezzi della pergamena","posizione frammento di pergamena"}},{q="Cosa precede questa missione?",a="Segue i tuoi precedenti incontri con Theldurin il Perduto.",al={"missione precedente","prerequisito per the lost fragments"}}},fp="18,147,21.234.0,20.209.0,46.73.0,45.150.0,31.110.0,29.57.0"}
P.entries["quest:6921"] = {n="Amongst the Ruins",s="All’Avamposto di Zoram’gar, Je’neu Sancrea invia campioni dell’Orda nelle profondità degli Abissi di Fondocupo. L’Earthen Ring spera che un Nucleo Profondo riveli cosa sta facendo il Martello del Crepuscolo agli elementi.",h="All’Avamposto di Zoram’gar, Je’neu Sancrea invia campioni dell’Orda nelle profondità degli Abissi di...",kw={"amongst the ruins","valtetra","abissi di fondocupo","the earthen ring","nucleo profondo","pietra profonda","je'neu sancrea","moonshrine ruins","martello del crepuscolo","avamposto di zoram'gar"},ang={["class:Shaman"]="In quanto sciamano, recuperare il Nucleo Profondo aiuta l’Earthen Ring a proteggere gli spiriti dell’acqua e della terra dalla coercizione del Martello del Crepuscolo.",["faction:Horde"]="In quanto membro dell’Orda, eliminare le minacce dagli Abissi di Fondocupo aiuta a proteggere l’Avamposto di Zoram’gar e la posizione dell’Orda sulla costa di Valtetra.",["race:Troll"]="In quanto troll, aiutare Je’neu Sancrea significa dare una mano a un compagno dei Puntascura che fa da tramite tra l’Orda e i custodi degli elementi dell’Earthen Ring."},sec={{t="Una minaccia negli abissi",b="Il Martello del Crepuscolo ha conquistato gli Abissi di Fondocupo, un antico tempio degli elfi della notte un tempo sacro a Elune. Ora i suoi cultisti controllano i passaggi sommersi. All’Avamposto di Zoram’gar, sulla costa di Valtetra, lo sciamano dei Puntascura Je’neu Sancrea osserva la corruzione diffondersi. Teme che il culto rivolti gli elementi locali contro la terra e i suoi difensori."},{t="La Pietra Profonda",b="Je’neu Sancrea invia campioni dell’Orda a recuperare un Nucleo Profondo dalla pietra profonda sotto le acque delle Moonshrine Ruins. Gli sciamani in grado di leggere il nucleo troveranno un resoconto dettagliato delle correnti e delle perturbazioni elementali. L’Earthen Ring spera che quel resoconto sveli le opere del Martello del Crepuscolo e aiuti a proteggere la regione da una catastrofe elementale."}},faq={{q="Chi assegna la missione Amongst the Ruins?",a="Je’neu Sancrea assegna l’incarico. Il troll dei Puntascura serve l’Earthen Ring all’Avamposto di Zoram’gar, sulla Spiaggia di Zoram, nella parte occidentale di Valtetra.",al={"datore di missione","dove prendere la missione","chi inizia amongst the ruins"}},{q="Cos'è un Nucleo Profondo?",a="Un Nucleo Profondo è un artefatto custodito in una pietra profonda sommersa tra le rovine. Gli sciamani possono leggerne il resoconto dell’attività elementale, compreso il modo in cui gli elementi locali vengono costretti e manipolati.",al={"cos'è il nucleo profondo","scopo della pietra profonda","cosa fa il nucleo"}},{q="Perché l’Earthen Ring è preoccupato per gli Abissi di Fondocupo?",a="L’Earthen Ring cerca l’equilibrio tra gli elementi. Il Martello del Crepuscolo ha conquistato le rovine sommerse e sta corrompendo e soggiogando gli elementi, mettendo a rischio la stabilità della regione.",al={"motivo di the earthen ring","perché interessa all’earthen ring","cultisti degli abissi di fondocupo"}},{q="Dove si trova la pietra profonda?",a="La pietra profonda si trova sotto le acque delle Moonshrine Ruins, all’interno degli Abissi di Fondocupo. Per recuperare il nucleo, gli esploratori devono immergersi sotto la superficie.",al={"dove si trova la pietra","posizione del nucleo profondo","nucleo profondo moonshrine ruins"}},{q="I giocatori dell’Alleanza possono accettare questa missione?",a="No. Solo gli avventurieri dell’Orda possono svolgere questo incarico. Je’neu Sancrea si trova all’avamposto dell’Orda di Zoram’gar e sostiene la presenza dell’Orda a Valtetra mentre serve l’Earthen Ring.",al={"è solo per l’orda","versione dell’alleanza","l’alleanza può fare amongst the ruins"}},{q="Quale gruppo occupa gli Abissi di Fondocupo?",a="Il Martello del Crepuscolo occupa gli Abissi di Fondocupo. Il culto serve sinistre entità degli Dei Antichi e piega gli elementi a fini catastrofici.",al={"chi c'è a fondocupo","nemici in bfd","martello del crepuscolo abissi di fondocupo"}}},fx={["139b4a2b"]={q="Perché Je'neu Sancrea vuole che il Nucleo Profondo venga recuperato?",a="Je'neu Sancrea teme che i cultisti del Martello del Crepuscolo che occupano gli Abissi di Fondocupo costringano gli elementali locali a rivoltarsi contro la regione e l'Orda. Senza il Nucleo Profondo, l'Anello della Terra non può sapere quali rituali stia compiendo il culto né quali perturbazioni elementali stiano avvenendo nelle profondità sotto le rovine.",al={"motivo di je'neu sancrea","perché recuperare il nucleo profondo","perché amongst the ruins"}}},fp="17,199,20.341.0,16.355.0,38.137.0,22.197.0,58.188.0,34.152.0,37.186.0,42.139.0"}
P.entries["quest:6922"] = {n="Barone Aquanis",s="Sotto Valtetra, il Barone Aquanis lascia un globo colmo di fluido corrotto. Je'neu Sancrea dell'Earthen Ring sospetta dei cultisti del Martello del Crepuscolo nelle rovine sommerse e spera che il globo riveli cosa ha corrotto l'elementale.",h="Sotto Valtetra, il Barone Aquanis lascia un globo colmo di fluido corrotto.",kw={"valtetra","barone aquanis","abissi di fondocupo","the earthen ring","corruzione elementale","je'neu sancrea","globo d'acqua strano","martello del crepuscolo","spiaggia di zoram"},ang={["class:Shaman"]="Come sciamano, sai che l'Earthen Ring considera la corruzione degli spiriti elementali una grave violazione dell'ordine naturale. Indagare sullo stato corrotto del Barone Aquanis è fondamentale per ristabilire l'equilibrio elementale.",["faction:Horde"]="Come membro dell'Orda, puoi unirti al lavoro di Je'neu Sancrea e degli esploratori dell'Orda all'Avamposto di Zoram'gar. Cercano campioni che purifichino le acque corrotte sotto la costa di Valtetra."},sec={{t="Un Cuore Corrotto",b="Negli Abissi di Fondocupo, una magia immonda ha trasformato il Barone Aquanis in uno spirito dell'acqua. Quando l'elementale viene distrutto, resta un Globo d'Acqua Strano. L'orbe invulnerabile contiene un fluido putrido che sembra aver sostenuto e distorto l'essenza naturale di Aquanis. La forza fisica non può danneggiarlo. Le sue energie turbano chi è in sintonia con l'equilibrio degli elementi."},{t="Studi dell'Earthen Ring",b="Da un accampamento sulla Spiaggia di Zoram, Je'neu Sancrea serve l'Earthen Ring. Riconosce nel Globo d'Acqua Strano la prova di un'interferenza innaturale. L'ordine sospetta che forze oscure abbiano corrotto il Barone Aquanis, e Je'neu sospetta dei cultisti del Martello del Crepuscolo nel tempio sommerso. Studia il globo per verificare i suoi sospetti e scoprire come i cultisti soggiogano e distorcono gli spiriti elementali di Azeroth."}},faq={{q="Chi è il Barone Aquanis?",a="Nelle acque sotterranee degli Abissi di Fondocupo, il Barone Aquanis è un potente elementale dell'acqua. Gli adepti delle arti oscure nel tempio in rovina hanno corrotto e vincolato l'elementale.",al={"chi è aquanis","boss aquanis","storia del barone aquanis"}},{q="Che cos'è il Globo d'Acqua Strano?",a="Il Globo d'Acqua Strano è una sfera invulnerabile che resta dopo la sconfitta del Barone Aquanis. Al suo interno sciaborda un liquido putrido, carico dell'energia corrotta che alimentava lo stato corrotto dell'elementale.",al={"globo d'acqua","globo d'acqua strano","oggetto missione aquanis"}},{q="Perché Je'neu Sancrea vuole il globo?",a="Je'neu Sancrea studia il globo per scoprire se la corruzione è opera del Martello del Crepuscolo e svelare i riti usati per distorcere gli spiriti elementali. In quanto membro dell'Earthen Ring, sorveglia le perturbazioni elementali in tutta Valtetra.",al={"perché portare da jeneu","scopo di jeneu sancrea"}},{q="Chi c'è dietro la corruzione del Barone Aquanis?",a="I cultisti del Martello del Crepuscolo, nel cuore degli Abissi di Fondocupo, sono i principali sospettati della corruzione del Barone Aquanis. La loro presenza nel tempio rispecchia uno schema di profanazione e comunione oscura con esseri innaturali.",al={"chi ha corrotto aquanis","aquanis martello del crepuscolo","cultisti fondocupo"}},{q="Dove si trova Je'neu Sancrea?",a="Je'neu Sancrea è uno sciamano dell'Earthen Ring accampato lungo la Spiaggia di Zoram, sulla costa nordoccidentale di Valtetra, vicino all'ingresso delle caverne degli Abissi di Fondocupo.",al={"dove si trova jeneu","consegnare missione aquanis","dove consegnare il globo d'acqua"}},{q="Cosa segue la consegna di questa missione?",a="Consegnare il globo porta a nuove indagini sulle sofferenze elementali della regione. Gli avventurieri continuano ad aiutare l'Earthen Ring a contrastare la corruzione crescente.",al={"missione successiva","disagio elementale"}}},fp="13,242,17.349.0,27.391.1,22.172.0,32.194.0,39.240.0,46.219.0,32.157.0,39.157.0"}
P.entries["quest:693"] = {n="Wand over Fist",s="A Fosso dei Rifugiati, Skuerto ha scoperto dove è finito il primo oggetto di Trelane. Kor'gresh tiene la Bacchetta dell'Invocazione di Trelane nel Fortilizio dei Rocciadura e Skuerto la rivuole.",h="A Fosso dei Rifugiati, Skuerto ha scoperto dove è finito il primo oggetto di Trelane.",kw={"altopiani d'arathi","fortilizio dei rocciadura","korgresh","fosso dei rifugiati","skuerto","stromgarde","viadotto di thandol","trelane","bacchetta dell'invocazione","wand over fist"},sec={{t="L'orco e la bacchetta",b="Dopo il tuo lavoro per l'Apprendista Kryten, Skuerto ha rintracciato il primo oggetto di Trelane fino a Kor'gresh. L'ogre tiene la bacchetta nel Fortilizio dei Rocciadura e usa scariche di ghiaccio per tenere in riga i suoi simili. Skuerto teme che Kor'gresh sia vicino a scoprirne tutti i poteri. Il Fortilizio dei Rocciadura si trova a sud di Fosso dei Rifugiati e poi a est del Viadotto di Thandol."},{t="La lista di Skuerto",b="Al tuo ritorno, Skuerto conta la bacchetta tra gli oggetti ritrovati. Ne restano altri tre sulla sua lista, e si trovano tutti a Stromgarde."}},faq={{q="Chi assegna la missione Wand over Fist?",a="A Fosso dei Rifugiati, negli Altopiani d'Arathi, Skuerto ti chiede di recuperare la bacchetta.",al={"chi assegna la missione wand over fist","chi inizia wand over fist","dove prendere wand over fist"}},{q="Dove si trova Kor'gresh?",a="Kor'gresh si trova nel Fortilizio dei Rocciadura, a sud di Fosso dei Rifugiati e poi a est del Viadotto di Thandol.",al={"dove si trova korgresh","posizione korgresh","trovare korgresh"}},{q="Quale oggetto deve essere recuperato?",a="La Bacchetta dell'Invocazione di Trelane è il primo degli oggetti di Trelane a essere recuperato. Kor'gresh l'ha usata per scagliare scariche di ghiaccio contro i suoi simili.",al={"quale oggetto possiede kor'gresh","quale bacchetta","bacchetta di trelane"}},{q="Quali prerequisiti sono necessari per questa missione?",a="Puoi affrontare questo incarico dopo Worth Its Weight in Gold, il lavoro che hai svolto per l'Apprendista Kryten.",al={"prerequisiti wand over fist","prerequisiti per wand over fist","missione precedente a wand over fist"}}},fp="14,161,21.321.0,14.123.1,35.79.0,27.87.0,32.134.0,45.91.0"}
P.entries["quest:694"] = {n="Trelane's Defenses",s="Gli ogre ora circondano la Torre di Arathor e Skuerto ha bisogno che le sue difese funzionino. Un'agata azzurra dello sciamano Pugno di Pietra può diventare una chiave dopo che l'Apprendista Kryten a Fosso dei Rifugiati l'avrà incantata.",h="Gli ogre ora circondano la Torre di Arathor e Skuerto ha bisogno che le sue difese funzionino.",kw={"apprendista kryten","agata azzurra","sciamano pugno di pietra","fosso dei rifugiati","skuerto","stromgarde","torre di arathor","trelane's defenses"},sec={{t="Le difese della torre",b="A Stromgarde, gli ogre circondano la Torre di Arathor. Skuerto dice che devi attivarne le difese per avere una possibilità contro di loro. Solo allora potrai raggiungere gli oggetti vivo."},{t="Una gemma come chiave",b="Gli sciamani Pugno di Pietra hanno sottratto alcune gemme alla torre e se ne sono affezionati. Skuerto dice che non le terranno a lungo. Porta un'agata azzurra all'Apprendista Kryten a Fosso dei Rifugiati. Kryten conosce l'incantesimo che la renderà una chiave."}},faq={{q="Perché serve un'agata azzurra?",a="Skuerto vuole attivare le difese della torre, così potrai affrontare gli ogre che circondano la Torre di Arathor e raggiungere gli oggetti vivo. Una volta incantata, la gemma funzionerà come una chiave.",al={"perché agata azzurra","scopo difese di trelane","perché prendere la gemma"}},{q="Da dove provengono le agate azzurre?",a="Gli sciamani Pugno di Pietra hanno sottratto le agate azzurre alla Torre di Arathor e se ne sono affezionati.",al={"chi ha preso le agate","da dove vengono le gemme","origine dell'agata"}},{q="Chi può incantare la gemma?",a="L'Apprendista Kryten a Fosso dei Rifugiati conosce l'incantesimo per incantare la gemma, così che funzioni come una chiave.",al={"chi incanta l'agata","ruolo di kryten","chi la trasforma in una chiave"}}},fp="18,190,20.166.0,15.257.0,29.161.0,37.99.0,24.91.0"}
P.entries["quest:695"] = {n="An Apprentice's Enchantment",s="Al campo, l'Apprendista Kryten incanta l'agata che hai portato dallo sciamano Pugno di Pietra. Può risvegliare le difese della torre e Kryten ti manda da Skuerto prima che tu parta.",h="Al campo, l'Apprendista Kryten incanta l'agata che hai portato dallo sciamano Pugno di Pietra.",kw={"apprendista kryten","altopiani d'arathi","agata incantata","skuerto","torre","trelane"},sec={{t="Una chiave per la torre",b="L'Apprendista Kryten ti consegna la gemma incantata e ti spiega il suo potere. Tocca un piedistallo ai piedi della torre per risvegliarne le difese. Quando sei pronto a entrare e cercare il resto degli oggetti di Trelane, usa la gemma. Kryten ti aspetterà al campo. Prima di andare, parla con Skuerto, che può rispondere a ogni altra domanda."}},faq={{q="Qual è lo scopo dell'agata incantata?",a="Tocca la gemma incantata a un piedistallo ai piedi della torre per risvegliarne le difese. Usala quando sei pronto a entrare e cercare il resto degli oggetti di Trelane.",al={"perché mi serve l'agata","uso dell'agata incantata","cosa fa la gemma"}},{q="Con chi devi parlare prima di lasciare il campo?",a="Parla con Skuerto prima di lasciare il campo. Kryten dice che Skuerto può rispondere a ogni altra domanda.",al={"con chi devo parlare","dove andare dopo","chi è skuerto"}},{q="Dove sarà Kryten?",a="Kryten ti aspetterà al campo al tuo ritorno.",al={"dov'è kryten","kryten in attesa"}}},fp="27,174,19.335.0,43.174.0,47.95.0,21.45.0"}
P.entries["quest:696"] = {n="Attack on the Tower",s="A Fosso dei Rifugiati, Skuerto ti manda a cercare nella torre occupata dagli ogre tre oggetti legati a Trelane. Il filatterio, l'orbe e l'agata di brace dovrebbero trovarsi in dei forzieri all'interno, e Skuerto dice che Malin sarà felice quando glieli riporterai.",h="A Fosso dei Rifugiati, Skuerto ti manda a cercare nella torre occupata dagli ogre tre oggetti legati a...",kw={"altopiani d'arathi","attack on the tower","malin","ogre","fosso dei rifugiati","skuerto","trelane","agata di brace di trelane","orbe di trelane","filatterio di trelane"},sec={{t="Nella Torre",b="Dopo che Kryten incanta la gemma, Skuerto ti manda a cercare il filatterio, l'orbe e l'agata di brace di Trelane. I tre oggetti dovrebbero trovarsi in dei forzieri all'interno della torre, pronti per essere aperti. Ma gli ogre sono pericolosi. Le difese della torre non si occuperanno di loro e ti faranno del male se ti sorprenderanno a rubare."},{t="Il verdetto di Skuerto",b="Quando torni con i tre oggetti, Skuerto dice che Malin non avrebbe potuto chiedere a persona più degna di aiutarli qui. Malin sarà felicissimo di sapere che la loro impresa è riuscita così bene."}},faq={{q="Chi assegna questo compito?",a="Dopo che Kryten incanta la gemma, Skuerto ti manda da Fosso dei Rifugiati, negli Altopiani d'Arathi.",al={"chi dà attack on the tower","chi assegna attack on the tower","dove prendere attack on the tower"}},{q="Quali oggetti devi recuperare?",a="Ti viene chiesto di recuperare il filatterio, l'orbe e l'agata di brace di Trelane. Ognuno dovrebbe trovarsi in un forziere all'interno della torre.",al={"oggetti di attack on the tower","quali reliquie recuperare","oggetti di trelane"}},{q="Cosa faranno gli ogre?",a="Le difese della torre non si occuperanno degli ogre. Se ti sorprendono a rubare, ti faranno del male.",al={"gli ogre sono pericolosi","ogre della torre"}},{q="Cosa viene prima di questa?",a="Segue An Apprentice's Enchantment, in cui Kryten incanta la gemma e ti manda da Skuerto.",al={"prerequisiti di attack on the tower","quale missione viene prima"}}},fp="19,228,14.307.0,17.194.1,22.91.0,36.111.0,23.98.0,23.95.0"}
P.entries["quest:6962"] = {n="Dolcetti per Babbo Inverno",s="Presso lo stand dei Pascoli di Boscoamaro a Orgrimmar, l'attore che interpreta Babbo Inverno è stanco di ascoltare desideri festivi. Ti chiede biscotti allo zenzero e latte.",h="Presso lo stand dei Pascoli di Boscoamaro a Orgrimmar, l'attore che interpreta Babbo Inverno è stanco di...",kw={"biscotto allo zenzero","babbo inverno","spezie festive","latte ghiacciato","orgrimmar","pascoli di boscoamaro","dolcetti per babbo inverno","velo d'inverno"},ang={["faction:Horde"]="A Orgrimmar, i mercanti goblin dei Pascoli di Boscoamaro portano il banchetto e un momento di allegria domestica nella città dei guerrieri.",["profession:Cooking"]="Come cuoco apprendista, puoi esercitarti con una semplice ricetta, trasformando uova selvatiche e spezie stagionali in biscotti allo zenzero festivi."},sec={{t="Un cliente stanco dell'Inverno",b="Babbo Inverno accoglie i visitatori nella Valle della Forza e lavora per i Pascoli di Boscoamaro. Dopo tante ore passate ad ascoltare i cittadini parlare di leccornie festive, gli viene fame. Così chiede ai viaggiatori di passaggio qualcosa di caldo appena sfornato e una bevanda fredda."},{t="Spirito festivo culinario",b="Le Spezie Festive dei mercanti dei Pascoli di Boscoamaro e le uova piccole degli uccelli selvatici servono per preparare i biscotti. Uniscile al Latte Ghiacciato comprato in una locanda locale. Gli organizzatori del banchetto ti offriranno allegria festiva e un piccolo segno di gratitudine."}},faq={{q="Chi è Babbo Inverno a Orgrimmar?",a="A Orgrimmar, Babbo Inverno è un attore ingaggiato dai Pascoli di Boscoamaro per interpretare la figura leggendaria durante la Vigilia di Grande Inverno. Vicino allo stand delle feste nella Valle della Forza, accoglie i cittadini dell'Orda e ascolta le loro richieste festive.",al={"chi è babbo inverno","babbo inverno orgrimmar","è il vero babbo inverno"}},{q="Quali dolcetti chiede Babbo Inverno?",a="Ti chiede cinque biscotti allo zenzero e una porzione di Latte Ghiacciato per sostenersi durante una lunga giornata trascorsa ad accogliere i visitatori della festa.",al={"cosa vuole","dolcetti richiesti","quali biscotti gli servono"}},{q="Come si preparano i Biscotti allo Zenzero?",a="I venditori dei Pascoli di Boscoamaro presso lo stand delle feste vendono la ricetta e le Spezie Festive. Raccogli uova piccole dagli uccelli selvatici, uniscile alle spezie e cuoci i biscotti su un fuoco da cucina.",al={"come ottenere biscotti allo zenzero","ricetta biscotti allo zenzero","ingredienti biscotti"}},{q="Dove si può trovare il Latte Ghiacciato?",a="I venditori di cibo e bevande, gli osti e i baristi vendono Latte Ghiacciato in tutta Orgrimmar e negli altri insediamenti principali.",al={"dove trovare latte ghiacciato","comprare latte","venditore di latte"}},{q="Perché Babbo Inverno chiede cibo personalmente?",a="Ascoltare tutto il giorno bambini e cittadini parlare di cibo, regali e festeggiamenti fa venire fame all'attore che interpreta Babbo Inverno. Poiché non può lasciare facilmente il suo posto nella Valle della Forza, chiede uno spuntino veloce ai viaggiatori di passaggio.",al={"perché vuole dei dolcetti","babbo inverno ha fame"}},{q="Esiste una versione di questa missione per l'Alleanza?",a="Sì. A Forgiardente, Babbo Inverno fa la stessa richiesta ai campioni dell'Alleanza: biscotti allo zenzero e latte freddo durante la festa.",al={"versione dell'alleanza","dolcetti forgiardente"}}},fx={["87543d9b"]={q="A cosa servono i biscotti di pan di zenzero e il Latte Ghiacciato?",a="Babbo Inverno di Smokywood Pastures trascorre l'intera giornata seduto ad accogliere i partecipanti alla festa, e l'allegria delle festività mette appetito. I biscotti di pan di zenzero appena sfornati e una rinfrescante brocca di latte freddo sono semplicemente uno spuntino modesto e confortante per tenergli alto il morale mentre ascolta i desideri dei visitatori a Orgrimmar.",al={"perché latte e biscotti","uso dei biscotti di pan di zenzero","latte ghiacciato per la veglia di grande inverno"}},["1b7dc40f"]={q="Perché Babbo Inverno lo chiede a te invece di procurarsi i dolci da solo?",a="Babbo Inverno è bloccato sul suo trono festivo nella Valle della Forza, dove accoglie gli ospiti e diffonde lo spirito delle feste durante la Veglia di Grande Inverno. Lasciare il suo posto per fare acquisti o preparare dolci deluderebbe i visitatori e interromperebbe i festeggiamenti, perciò si affida agli avventurieri di passaggio per sbrigare la commissione.",al={"perché babbo inverno ha bisogno di me","perché babbo inverno non può procurarsi il latte","perché chiedere a un avventuriero i dolci"}}},fp="30,159,24.234.0,23.236.0,39.254.0,44.137.0,36.196.0,33.117.0,50.238.0,45.141.0"}
P.entries["quest:697"] = {n="Malin's Request",s="A Roccavento, la lettera di Skuerto porta all'Arcimago Malin notizie dagli Altopiani d'Arathi. Ti mandano al Quartiere dei Maghi per annunciare che Kryten e Skuerto torneranno presto a casa.",h="A Roccavento, la lettera di Skuerto porta all'Arcimago Malin notizie dagli Altopiani d'Arathi.",kw={"altopiani d'arathi","arcimago malin","kryten","quartiere dei maghi","malin's request","lettera sigillata","skuerto","roccavento"},sec={{t="Una lettera per l'Arcimago",b="Dopo il tuo lavoro negli Altopiani d'Arathi, Skuerto ti affida una lettera sigillata per l'Arcimago Malin, nel Quartiere dei Maghi di Roccavento. Dice che Kryten e Skuerto torneranno presto a casa. Skuerto confida che Malin ti ricompenserà bene per averli aiutati e ti augura buon viaggio."},{t="Malin legge la lettera",b="L'Arcimago Malin apre la lettera di Skuerto e sgrana gli occhi. Deliziato, dice che Trelane ne sarà felice. Malin immagina che Kryten e Skuerto condividano il suo entusiasmo mentre fanno ritorno a Roccavento."}},faq={{q="Chi ti affida la lettera?",a="Skuerto ti manda da Malin con una lettera. Dice che Kryten e Skuerto torneranno presto a casa.",al={"chi dà la lettera","chi inizia malins request","inizio di malins request"}},{q="Dove si trova l'Arcimago Malin?",a="L'Arcimago Malin si trova nel Quartiere dei Maghi di Roccavento.",al={"dove si trova l'arcimago malin","posizione arcimago malin","dove consegno la missione"}},{q="Chi è Kryten?",a="Kryten è il compagno di Skuerto negli Altopiani d'Arathi. Skuerto dice che torneranno presto a casa.",al={"chi è kryten","kryten arathi"}},{q="Cosa precede questa fase?",a="Questo fa seguito ad Attack on the Tower, il lavoro che Skuerto ti ha chiesto di svolgere alla torre negli Altopiani d'Arathi.",al={"missione precedente","prerequisito","cosa porta a questa missione"}}},fp="15,160,25.243.0,22.193.1,30.88.0,32.46.0,14.91.0,28.90.0"}
P.entries["quest:698"] = {n="Lack of Surplus",s="Dar ha bisogno di altra carne di dente di sega per l'avamposto sulla spiaggia orientale. Tok'Kar ha poco tempo tra i turni di guardia e la cucina per i soldati, così Dar ti chiede di portargliene.",h="Dar ha bisogno di altra carne di dente di sega per l'avamposto sulla spiaggia orientale.",kw={"dar","fianco","carne","avamposto","dente di sega","palude del dolore","tok'kar"},sec={{t="Rifornimenti per la Riva",b="Dar sta raccogliendo rifornimenti per l'avamposto sulla spiaggia orientale. Tok'Kar fa la guardia al posto e cucina per i soldati, così gli resta poco tempo per altro. Quando possono, i soldati apprezzano la carne di dente di sega. Dar non ha avuto tempo di inviare un'altra partita."},{t="Scegliere la Carne",b="Dar dice che i dente di sega più anziani hanno un sapore migliore, quindi lascia in pace i giovani. Hanno bisogno di un anno o due per raggiungere la piena crescita. Porta otto fianchi di dente di sega non preparati a Tok'Kar nella Palude del Dolore."}},faq={{q="Chi sta richiedendo la carne di dente di sega?",a="Dar, che rifornisce l'avamposto sulla spiaggia orientale.",al={"chi assegna lack of surplus","chi inizia lack of surplus","dar palude del dolore"}},{q="Dove è di stanza Tok'Kar?",a="Tok'Kar è di stanza all'avamposto sulla spiaggia orientale, nella Palude del Dolore. Porta lì la carne.",al={"dove si trova tok'kar","posizione tok'kar","avamposto di tok'kar"}},{q="Perché Tok'Kar ha bisogno che altri portino la carne?",a="I turni di guardia e la cucina per i soldati lasciano a Tok'Kar poco tempo durante la giornata.",al={"perché a tok'kar serve carne","perché dar invia cibo"}},{q="Quali dente di sega dovrebbero essere cacciati?",a="Dai la caccia ai dente di sega più anziani. I giovani sono meno saporiti e hanno bisogno di un anno o due per raggiungere la piena crescita.",al={"quali dente di sega","quali dente di sega rilasciano carne","fonte fianco di dente di sega"}},{q="Quanti fianchi sono necessari?",a="Porta a Tok'Kar otto fianchi di dente di sega non preparati.",al={"quanti fianchi","conteggio fianchi di dente di sega non preparati"}},{q="Cosa succede dopo nella catena?",a="Segue un secondo passaggio con lo stesso nome.",al={"prossima missione dopo lack of surplus","seguito di lack of surplus"}}},fp="15,165,22.253.0,17.189.0,36.68.0,27.104.0,43.79.0,33.94.0,27.47.0,29.42.0"}
P.entries["quest:6981"] = {n="The Glowing Shard",s="Nel cuore della Caverna dei Lamenti trovi una scheggia verde, le cui profondità fumose inquietano. Il suo mistero ti spinge a Porto Paranco e oltre.",h="Nel cuore della Caverna dei Lamenti trovi una scheggia verde, le cui profondità fumose inquietano.",kw={"savane","druidi della zanna","incubo di smeraldo","falla vento saggio","scheggia brillante","porto paranco","sputavalvole","caverna dei lamenti"},ang={["class:Druid"]="Da druido, puoi vedere nel riflesso color smeraldo e nel cuore fumoso della scheggia segni funesti dell'Incubo di Smeraldo, che raggiunge il mondo dei viventi attraverso i tuoi fratelli caduti nella Caverna dei Lamenti.",["faction:Alliance"]="Da esploratore dell'Alleanza, lontano da casa a Kalimdor, puoi scorgere il pericolo in un potere oscuro che corrompe la natura sotto le Savane.",["faction:Horde"]="Come membro dell'Orda, puoi contribuire a svelare il mistero della scheggia e a proteggere gli incroci e le rotte commerciali delle Savane dalle minacce che covano nelle sorgenti sotterranee.",["race:Tauren"]="Come tauren, sai quanto l'equilibrio delle Savane conti per gli Shu'halo. Portare questa reliquia innaturale a Falla Vento Saggio può aiutarti a svelare la corruzione che avvelena le tue terre ancestrali."},sec={{t="Una Scoperta Inquietante",b="Porti con te un cristallo verde dalle profondità della Caverna dei Lamenti. Sotto la sua superficie brillante e solida, filamenti d'ombra sembrano agitarsi. Chi lo tocca si sente a disagio, e la sua strana presenza lascia intuire la corruzione che avvolge i druidi dormienti e il loro santuario infestato dagli incubi."},{t="Cercare risposte a Porto Paranco",b="A Porto Paranco, l'origine della scheggia resta un mistero. L'ingegnere Sputavalvole la esamina, ma né i macchinari goblin né la geologia comune ne spiegano la natura. Ti indirizza verso le creste rocciose sopra le caverne, dove Falla Vento Saggio, mistica tauren, veglia sugli spiriti inquieti delle Savane."}},faq={{q="Cos'è la Scheggia Brillante?",a="Hai trovato la Scheggia Brillante nelle profondità della Caverna dei Lamenti. Sotto la sua superficie vitrea turbinano deboli forme fumose che inquietano chi la studia.",al={"oggetto scheggia brillante","cos'è questa gemma verde","scheggia dalla caverna dei lamenti"}},{q="Chi può esaminare la scheggia a Porto Paranco?",a="L'ingegnere Sputavalvole, vicino al maestro di volo di Porto Paranco, può esaminare la scheggia. La sua strana energia lo spinge a indirizzarti da qualcuno esperto di spiritualità.",al={"chi a porto paranco guarda la scheggia","npc di porto paranco per la scheggia","scheggia di sputtervalve"}},{q="Dove si trova Falla Vento Saggio?",a="Falla Vento Saggio tiene il suo accampamento sulle vette montuose proprio sopra l'ingresso della Caverna dei Lamenti, nelle Savane centrali.",al={"posizione di falla vento saggio","dove si trova falla","montagna sopra la caverna dei lamenti"}},{q="Sputavalvole ha un indicatore di missione sopra la testa?",a="No. Sputavalvole non ha un'icona attiva sopra la testa. Parla con lui e scegli l'opzione di dialogo sulla strana scheggia luminosa per proseguire.",al={"sputavalvole nessun punto interrogativo","impossibile consegnare a sputtervalve","sputavalvole bugged"}},{q="Perché la scheggia sembra contenere del fumo?",a="Il vortice simile a fumo riflette la corruzione che si diffonde nella Caverna dei Lamenti. È legato all'Incubo di Smeraldo, che invade i pensieri dei Druids of the Fang addormentati.",al={"perché la scheggia emette fumo","fumo verde nella gemma","corruzione nella scheggia"}},{q="Chi può completare la catena di missioni dopo Falla Vento Saggio?",a="Gli avventurieri dell'Orda e dell'Alleanza possono seguire entrambi la storia. Le scoperte di Falla Vento Saggio conducono a In Nightmares, dove gli eroi cercano consiglio dai propri capi e anziani.",al={"questa missione è solo per l'orda","scheggia brillante alleanza","chi ottiene in nightmares"}}},fx={["8f9c92be"]={q="Perché devi esaminare la Scheggia Brillante?",a="La scheggia brillante è profondamente inquietante. Solida, ma colma di profondità verdi, fumose e vorticose, emana una presenza innaturale che esige una spiegazione. Dopo averla recuperata dal cuore della tormentata Caverna dei Lamenti, devi scoprire quale corruzione porti con sé e quale minaccia possa rappresentare per The Barrens.",al={"perché esaminare la scheggia brillante","motivo della scheggia brillante","perché portare la scheggia a porto paranco"}}},fp="17,128,22.271.0,26.297.1,26.145.0,37.156.0,32.119.0,52.135.0,47.174.0,54.168.1"}
P.entries["quest:6984"] = {n="Un grazie dalla Masseria Buongusto",s="A Orgrimmar, Kaymard Pinzarame ti manda a ricevere i ringraziamenti per i dolci festivi rubati che hai recuperato. Babbo Inverno attende di rendere omaggio a chi ha riportato le provviste della Masseria Buongusto.",h="A Orgrimmar, Kaymard Pinzarame ti manda a ricevere i ringraziamenti per i dolci festivi rubati che hai...",kw={"festino del velo d'inverno","babbo inverno","grinch","kaymard pinzarame","orgrimmar","masseria buongusto","valle della forza","velo d'inverno"},ang={["faction:Horde"]="A Orgrimmar, i festeggiamenti della Vigilia di Grande Inverno dell'Orda uniscono la venerazione sciamanica per il mutare delle stagioni al commercio dei goblin.",["profession:Cooking"]="Da cuoco, puoi affidarti alla Masseria Buongusto per le provviste stagionali, le ricette esotiche e gli ingredienti festivi che tutti attendono con ansia ogni anno."},sec={{t="Una festività aziendale",b="A Orgrimmar, la Masseria Buongusto vende dolci, ricette e allegria stagionale per la Vigilia di Grande Inverno. Una spedizione è stata rubata tra le colline innevate delle Montagne d'Alterac e gli affari si sono fermati. Ora i dolci sono stati recuperati e il Verde Grinch abominevole è stato sconfitto. Kaymard Pinzarame ti manda a ricevere i ringraziamenti dell'azienda."},{t="Udienza con Babbo Inverno",b="Babbo Inverno attende accanto all'albero festivo nella Valle della Forza. I goblin hanno fatto in modo che rendesse omaggio a chi ha salvato le provviste festive. Gli dona una benedizione stagionale e un Regalo Speciale della Masseria Buongusto."}},faq={{q="Chi mi manda a parlare con Babbo Inverno?",a="Dopo aver recuperato i dolci festivi rubati, Kaymard Pinzarame ti manda da Babbo Inverno. Rappresenta la Masseria Buongusto nella Valle della Forza di Orgrimmar.",al={"chi inizia questa missione","datore di missione","ruolo di kaymard"}},{q="Cosa ho fatto per guadagnarmi la gratitudine della Masseria Buongusto?",a="Hai rintracciato il Verde Grinch abominevole nelle Montagne d'Alterac e recuperato i dolci festivi rubati. Così hai salvato le provviste della Masseria Buongusto per la Vigilia di Grande Inverno.",al={"perché mi ringraziano","quali dolcetti sono stati rubati","storia del grinch"}},{q="Dove si trova Babbo Inverno a Orgrimmar?",a="Babbo Inverno attende sotto l'albero addobbato della Vigilia di Grande Inverno, nella Valle della Forza, accanto alle bancarelle della Masseria Buongusto.",al={"posizione di babbo inverno","dov'è babbo natale a org","albero del velo d'inverno a org"}},{q="Chi è Babbo Inverno?",a="Babbo Inverno è un araldo elementale o mitico del mutare delle stagioni, che si dice ricopra la terra di neve invernale. Durante la Vigilia di Grande Inverno, i mortali indossano le sue vesti rosse per diffondere benevolenza e donare dolci ai bambini e agli avventurieri.",al={"chi è babbo inverno","babbo inverno è reale","storia del velo d'inverno"}},{q="Cos'è la Masseria Buongusto?",a="La Masseria Buongusto è un'impresa culinaria e agricola gestita dai goblin. Durante la Vigilia di Grande Inverno fornisce cibi festivi, ingredienti stagionali e decorazioni all'Orda e all'Alleanza.",al={"storia della masseria buongusto","chi è la masseria buongusto","venditore goblin festivo"}},{q="Ricevo qualcos'altro dopo aver parlato con lui?",a="Sì. Babbo Inverno ti dona un Regalo Speciale della Masseria Buongusto a nome dell'azienda. I tuoi sforzi ti fanno anche guadagnare reputazione presso il Cartello degli Spargifumo.",al={"ricompensa missione","kit di travestimento","regalo via posta"}}},fx={["553cdbb2"]={q="Perché Kaymard Pinzarame ti manda da Babbo Inverno?",a="Kaymard Pinzarame e Smokywood Pastures vogliono ricompensarti per aver recuperato i dolci rubati. Mandandoti da Babbo Inverno per ricevere di persona un dono speciale della Veglia di Grande Inverno, i goblin esprimono la loro gratitudine e mantengono vivo lo spirito commerciale e festoso della stagione.",al={"perché kaymard mi ringrazia","motivo di kaymard pinzarame","perché mandare da babbo inverno"}}},fp="32,194,19.327.0,33.232.0,47.166.0,52.175.0,50.136.0,27.240.0,27.200.0,51.155.0"}
P.entries["quest:699"] = {n="Lack of Surplus",s="Lungo la costa, Tok'kar e i suoi soldati sorvegliano i murloc che minacciano Pietrachiusa. Quando sono troppi, danno l'allarme. Per ora, Tok'kar ti chiede di portargli sei chele di dentisega.",h="Lungo la costa, Tok'kar e i suoi soldati sorvegliano i murloc che minacciano Pietrachiusa.",kw={"chele","murloc","dentisega","pietrachiusa","palude del dolore","tok'kar"},sec={{t="Armi per la costa",b="Tok'kar e i soldati proteggono Pietrachiusa dai murloc lungo la costa. Quando sono troppo numerosi da affrontare, avvertono la città. Tok'kar ha poco tempo per riposare e ti chiede aiuto. Se preparate a dovere, le chele di dentisega sono ottime armi. Portagliene sei e, grato per la carne e la compagnia, ti offre in cambio una delle armi dell'avamposto."}},faq={{q="Chi chiede le chele?",a="Tok'kar, di stanza lungo la costa per proteggere Pietrachiusa, ti chiede le chele.",al={"chi assegna lack of surplus","datore di missione","tokkar"}},{q="Perché Tok'kar ha bisogno delle chele di dentisega?",a="Se preparate a dovere, le chele di dentisega sono ottime armi, e Tok'kar ne vuole sei.",al={"perché le chele","scopo dentisega","chele come armi"}},{q="Quale minaccia sta monitorando il posto di guardia costiero?",a="I soldati sorvegliano i murloc lungo la costa. Proteggono Pietrachiusa o avvertono la città se sono troppo numerosi.",al={"pericoli costieri","attacco dei murloc a pietrachiusa","cosa sta guardando tokkar"}},{q="Cosa succede dopo?",a="Segue Threat From the Sea.",al={"what comes next","missione successiva","dopo lack of surplus"}}},fp="15,194,21.347.0,23.78.0,45.82.0,45.112.0,26.28.0"}
P.entries["quest:7"] = {n="Kobold Camp Cleanup",s="Nei boschi settentrionali della Contea del Nord, i kobold minacciano i terreni dell'abbazia. Il Maresciallo McBride ha bisogno che i campi vengano ripuliti e la difesa della valle dipende da nuove reclute.",h="Nei boschi settentrionali della Contea del Nord, i kobold minacciano i terreni dell'abbazia.",kw={"cresta dell'eco","foresta di elwynn","kobold","maresciallo mcbride","contea del nord","abbazia della contea del nord","parassiti"},ang={["faction:Alliance"]="In quanto membro dell'Alleanza, puoi vedere quanto siano sotto pressione i territori di Roccavento. Anche le infestazioni di spazzini richiedono l'intervento urgente della milizia volontaria.",["race:Human"]="In quanto umano della Contea del Nord, respingere i parassiti kobold aiuta a proteggere l'abbazia e i terreni agricoli dall'invasione. È un dovere civico."},sec={{t="Una Valle sotto Pressione",b="Il Maresciallo McBride dirige la difesa della valle dall'Abbazia della Contea del Nord, ma ha pochi soldati. Perciò dipende da nuove reclute come te. Ogni minaccia a cui non riesce a rispondere potrebbe intralciare il lavoro dell'abbazia o diffondersi nei vigneti vicini. I campi dei kobold non possono aspettare."},{t="I Parassiti nei Boschi",b="I kobold sono timidi abitanti delle caverne ossessionati dalle candele, che di solito frugano nelle vene sotterranee, lontano dalla luce diretta del sole. Ora un intero clan ha raggiunto il limite dei boschi settentrionali. Se lasciati soli, potrebbero trasformare la raccolta di cianfrusaglie in incursioni aperte. McBride ti manda a decimare la loro avanguardia e a mettere alla prova la tua determinazione nel difendere il regno."}},faq={{q="Chi ordina l'eliminazione dell'accampamento kobold?",a="Il Maresciallo McBride ordina di decimare i kobold. Dall'Abbazia della Contea del Nord, supervisiona l'arrivo delle reclute e la sicurezza della valle per Roccavento.",al={"chi assegna questa missione","datore di missione","ruolo maresciallo mcbride"}},{q="Perché i kobold si trovano nei boschi settentrionali invece che in una miniera?",a="La popolazione in crescita della Contea del Nord si è estesa nella foresta aperta, dove i kobold hanno allestito campi primitivi tra gli alberi settentrionali, vicino ai confini della terra civilizzata. Di solito vivono in tane e miniere.",al={"perché i kobold sono fuori","kobold in superficie","perché nel bosco"}},{q="Perché questi kobold sono considerati una minaccia per Roccavento?",a="I parassiti kobold sono timidi e deboli da soli. In gruppo, possono tendere imboscate ai viaggiatori, razziare le provviste e sopraffare gli avamposti incustoditi. Roccavento può a malapena permettersi questa minaccia mentre le sue forze sono già impegnate altrove.",al={"i kobold sono pericolosi","perché uccidere i parassiti"}},{q="Dove porta questa missione?",a="Dopo aver decimato i kobold in superficie, le reclute vengono mandate più a fondo nella Miniera Cresta dell'Eco per indagare, là dove si trova il cuore dell'infestazione.",al={"quale missione segue","passo successivo","dopo la pulizia del campo"}},{q="La Contea del Nord riceve regolarmente rinforzi dall'esercito reale?",a="No. Le tensioni politiche e la carenza di truppe dopo la scomparsa di Re Varian costringono comandanti come McBride ad affidarsi a volontari civili, avventurieri e reclute per la sicurezza dei confini.",al={"dove sono le guardie di roccavento","perché i volontari"}},{q="Cosa rende i kobold così attaccati alle loro candele?",a="I kobold venerano le candele, la loro principale difesa contro l'oscurità opprimente dei tunnel sotterranei. Le loro fiamme offrono loro sicurezza, permettono di vedere e danno loro un senso di possesso.",al={"perché le candele","ossessione per le candele"}}},fx={afae4267={q="Perché il Maresciallo McBride vuole che il campo dei koboldi venga ripulito?",a="Un clan di koboldi ha iniziato a infestare i boschi a nord dell'abbazia, e il Maresciallo McBride vuole ridurne il numero prima che invadano la valle. Roccavento è già impegnata a fronteggiare minacce altrove, perciò la Contea del Nord deve difendersi da sola. Presi singolarmente sono codardi, ma in gruppo i koboldi diventano audaci. Eliminarli ora protegge l'insediamento e dà inizio all'opera per scacciarli del tutto dalla Contea del Nord.",al={"perché eliminare i koboldi","motivo di mcbride contro i koboldi","perché ripulire il campo dei koboldi"}},["35967b57"]={q="Quali sono i parassiti koboldi che ti viene chiesto di cacciare?",a="I parassiti koboldi sono esploratori e razziatori di un clan che si è insinuato nella foresta settentrionale. Umanoidi simili a ratti, naturalmente abituati a vivere sottoterra, sono ladri codardi quando sono soli, ma si sono radunati in numero allarmante nei boschi fuori dalla Contea del Nord. Se lasciati indisturbati, i loro accampamenti in espansione minacciano viaggiatori, frutteti e la stessa abbazia.",al={"chi sono i parassiti koboldi","cosa sono i parassiti koboldi","obiettivo dei parassiti koboldi"}},["921e514b"]={q="Perché il Maresciallo McBride manda te invece delle guardie di Roccavento?",a="L'esercito reale di Roccavento ha disperso le proprie forze per affrontare le crisi in tutto il regno, lasciando la Valle della Contea del Nord presidiata da poche guardie. McBride deve mantenere i soldati attorno all'abbazia e sulle strade principali per assicurare il perimetro difensivo. Non avendo truppe di riserva per pattugliare le terre selvagge, si affida a nuove reclute capaci e volontari di passaggio per eliminare i pericoli emergenti.",al={"perché non mandare le guardie","perché mcbride ha bisogno di me","perché reclutare avventurieri contro i koboldi"}}},fp="19,169,23.267.0,23.319.0,42.126.0,56.203.0,55.199.0,34.145.1,50.184.0,48.164.0"}
P.entries["quest:70"] = {n="Leggenda di Stalvan",s="A Borgodoro, una vecchia lettera riaccende la ricerca di Stalvan Mistmantle. Le sue tracce vanno dalla Foresta di Elwynn al Distretto dei Canali di Roccavento.",h="A Borgodoro, una vecchia lettera riaccende la ricerca di Stalvan Mistmantle.",kw={"canali","curato folsom","borgodoro","locandiere farley","locanda del fiero leone","mistmantle","stalvan","roccavento","lettera non consegnata"},ang={["faction:Alliance"]="Per svelare il mistero di Stalvan, attraversi le terre centrali dell'Alleanza. Una vecchia pista va da Borgodoro ai maestosi canali della capitale.",["race:Human"]="Da umano, scopri le correnti oscure che attraversano il Regno di Roccavento. I mali che infestano Boscovespro arrivano fino alle porte della capitale."},sec={{t="Un terrore di mezzanotte",b="Alla Locanda del Fiero Leone, il Locandiere Farley ricorda una notte tempestosa di anni fa. Un corriere di passaggio entrò per ripararsi dalla pioggia. Verso mezzanotte, scese di corsa al piano terra in preda al panico, vestito solo con gli abiti da notte. Scomparve nella tempesta e nessuno lo rivide più."},{t="Il pacco abbandonato",b="Il corriere lasciò la sua borsa e il baule personale nella stanza al piano superiore. Tra il carico dimenticato c'era una Lettera Mai Spedita con il nome Stalvan, indirizzata a qualcuno nel Distretto dei Canali di Roccavento. Il baule rimase intatto ai piedi del letto finché Farley non permise di aprirlo."},{t="Un benvenuto gelido",b="Il Curato Folsom sorveglia le proprietà lungo i Canali di Roccavento, vicino al Parco. Quando gli porti la lettera, ormai in ritardo da tempo, reagisce al nome e alla grafia di Stalvan con disgusto e ostilità, non con gratitudine. La sua reazione fa pensare a vecchi scandali legati al mittente."}},faq={{q="Dove si trova la lettera non consegnata?",a="La lettera mai consegnata è in un baule al piano superiore della Locanda del Fiero Leone, a Borgodoro. Sali le scale, gira a destra ed entra nella camera con il letto. Il baule è ai piedi della struttura del letto.",al={"trovare lettera","posizione baule stalvan","dov'è il baule"}},{q="Perché la lettera non fu mai consegnata in origine?",a="Anni fa, il corriere trovò riparo dalla pioggia battente alla Locanda del Fiero Leone. Poco prima di mezzanotte, qualcosa lo terrorizzò e fuggì nella tempesta in camicia da notte, lasciandosi alle spalle il baule e le consegne.",al={"perché lettera abbandonata","cosa ha spaventato il corriere","perché il messaggero è scappato"}},{q="Dove trovo il Curato Folsom a Roccavento?",a="Il Curato Folsom si trova lungo i Canali di Roccavento, vicino al margine del quartiere del Parco.",al={"posizione folsom","dov'è il curato folsom","consegna canali"}},{q="Perché il Curato Folsom è arrabbiato per aver ricevuto la lettera?",a="Folsom riconosce il nome e la grafia di Stalvan e reagisce con indignazione. Stalvan Mistmantle ha lasciato ricordi amari e rabbia tra le persone legate al suo passato a Roccavento.",al={"perché folsom è arrabbiato","reazione folsom","ci vuole coraggio"}},{q="Come si collega questo ai problemi di Boscovespro?",a="Il consiglio cittadino di Borgoscuro indaga su un male persistente legato a Stalvan Mistmantle. Per scoprire chi fosse, ripercorri i suoi primi viaggi e le sue frequentazioni nella Foresta di Elwynn e a Roccavento.",al={"perché missione boscovespro a borgodoro","come si collega a boscovespro"}},{q="Cosa succede dopo aver dato la lettera al Curato Folsom?",a="La dura reazione del Curato Folsom apre il capitolo dell'indagine a Roccavento. Devi scoprire quale lavoro svolgeva Stalvan e quali eventi funesti coinvolsero la famiglia nobile che serviva.",al={"prossimo passo","cosa segue questa missione"}}},fx={["1a6ccbd1"]={q="Perché il Locandiere Farley vuole che la lettera di Stalvan venga consegnata?",a="Il Locandiere Farley non ha interessi personali nelle vicende di Stalvan né nella vecchia lettera; ti sta semplicemente aiutando a ricomporre il mistero che stai indagando. Quando gli chiedi di Stalvan Mistmantle, Farley ricorda un corriere terrorizzato che anni fa fuggì dalla Locanda del Fiero Leone durante una tempesta, abbandonando al piano di sopra il suo baule per le spedizioni. Ricordando che era stata lasciata una lettera mai consegnata di Stalvan, indirizzata al Distretto dei Canali di Roccavento, te la offre affinché tu possa seguire la pista dell'elusivo uomo.",al={"perché farley aiuta","motivo del locandiere farley","perché consegnare la lettera"}},b7fa74bd={q="Che cos'è la Lettera Mai Consegnata?",a="La lettera è una vecchia missiva scritta anni fa da Stalvan Mistmantle, destinata a un indirizzo nel Distretto dei Canali di Roccavento. Fu lasciata alla Locanda del Fiero Leone quando un messaggero fuggì nella notte in preda al terrore, lasciando i suoi averi chiusi in un baule al piano di sopra. Per la tua indagine, la lettera è un indizio materiale fondamentale: ti conduce dal Curato Folsom a Roccavento per scoprire chi stesse contattando Stalvan e che cosa gli sia accaduto.",al={"cos'è una lettera mai consegnata","lettera mai consegnata di stalvan","cosa dice la lettera"}}},fp="21,134,17.266.0,19.289.0,16.261.1,37.203.0,46.205.0,46.91.0,57.183.0,49.198.0,57.186.1"}
P.entries["quest:700"] = {n="A King's Tribute",s="Magni Barbabronzea dedica a Sully Balloo un memoriale a Forgiardente. Il granito di Lordaeron mantiene vivo il ricordo del nano caduto tra la sua gente.",h="Magni Barbabronzea dedica a Sully Balloo un memoriale a Forgiardente.",kw={"a king's tribute","granito","forgiardente","lordaeron","magni barbabronzea","marmoduro","memoriale","sully balloo"},ang={["class:Warrior"]="Da guerriero, senti Magni rendere onore al valore altruista dei soldati in prima linea come Sully Balloo, che ha dato tutto in battaglia.",["faction:Alliance"]="Il monumento ti ricorda il pesante tributo imposto dai conflitti recenti a Khaz Modan e ai regni settentrionali.",["race:Dwarf"]="Da nano, condividi la tradizione di rendere onore ai guerrieri antenati caduti con monumenti di pietra destinati a durare."},sec={{t="Un monumento scolpito nel dolore",b="Re Magni Barbabronzea ha commissionato un monumento per Sully Balloo, un nano morto al servizio della sua gente. Il Gran Muratore Marmoduro lo ha scolpito in pregiato granito proveniente dalle terre martoriate dalla guerra di Lordaeron. Il monumento sorge a Forgiardente e rende onore ai soldati i cui sacrifici contribuiscono a preservare il regno dei nani."},{t="La riflessione di un sovrano",b="Quando gli annunciano che il monumento è completo, Magni riflette sulla pietra e sulla mortalità. Sa che la roccia scolpita non potrà mai eguagliare la vita di un nano coraggioso, ma spera che il memoriale duri nel tempo. Così, le generazioni che cammineranno su Azeroth potranno ricordare gli eroi che hanno versato il sangue per assicurare loro un domani."}},faq={{q="Chi viene onorato da questo memoriale?",a="Il memoriale rende onore a Sully Balloo, un coraggioso soldato nano che ha dato la vita combattendo per la sua gente e per l'Alleanza.",al={"per chi è questo memoriale","monumento di sully balloo","chi è morto"}},{q="Perché la pietra è stata raccolta a Lordaeron?",a="Il Gran Muratore Marmoduro aveva bisogno di pregiato granito per un tributo reale destinato a durare. Lordaeron è nota per la qualità eccezionale della pietra estratta dalle sue cave, anche se la regione è in rovina dopo il Flagello.",al={"perché la pietra di lordaeron","granito di lordaeron","pietra di marmoduro"}},{q="Dove si svolge questa missione?",a="Incontri il Gran Muratore Marmoduro, poi porti la notizia a Re Magni Barbabronzea nell'High Seat di Forgiardente.",al={"dove consegnare","chi completa la missione"}},{q="Perché Re Magni commissiona personalmente questo tributo?",a="Magni crede che i sovrani debbano rendere onore ai fanti che difendono i loro regni. Vuole che il memoriale ricordi alle generazioni future il prezzo pagato dai soldati comuni per proteggerle.",al={"perché a magni importa","magni barbabronzea sully balloo"}},{q="Cosa succede dopo che il memoriale è finito?",a="Riferire a Re Magni completa la catena del memoriale. La statua rimane a Forgiardente, monumento permanente in onore di Sully Balloo.",al={"what comes next","seguito di a king's tribute"}},{q="Qual è il significato architettonico della statua?",a="Il Gran Muratore Marmoduro è tra gli artigiani nani più esperti di Forgiardente. Ha trasformato il granito importato da Lordaeron in un'opera d'arte nazionale degna del sovrano.",al={"ruolo di marmoduro","lavoro del gran muratore"}}},fx={["964451bf"]={q="Perché Gran Muratore Marmoduro ti manda dal re?",a="Sei stato tu ad affrontare il pericoloso viaggio alle Rovine di Lordaeron per recuperare il pregiato granito destinato alla scultura. Dopo aver messo al sicuro la pietra e reso possibile il tributo, Gran Muratore Marmoduro ti affida il compito di annunciare direttamente a Re Magni Barbabronzea che il monumento a Sully Balloo è completo.",al={"perché mandarmi da magni","perché informare re magni","perché marmoduro manda il giocatore"}}},fp="16,131,26.297.0,24.259.0,38.117.0,42.172.0,33.100.0,55.178.0,44.132.0,47.169.0"}
P.entries["quest:7003"] = {n="Zapped Giants",s="Sulla Costa dell'Oblio di Feralas, Zorbin Saldaleva prova un raggio rimpicciolente sui giganti vicino ai moli. L'ha costruito da un progetto gnomico e migliorato con il know-how goblin, poi ti dà l'Ultra-Shrinker da provare sui giganti di Feralas.",h="Sulla Costa dell'Oblio di Feralas, Zorbin Saldaleva prova un raggio rimpicciolente sui giganti vicino ai moli.",kw={"gigante delle scogliere","feralas","costa dell'oblio","camminatore terrestre","residuo di miniaturizzazione","ultra-shrinker","zapped giants","zorbin saldaleva"},sec={{t="Un raggio rimpicciolente per i giganti",b="Zorbin Saldaleva ha bisogno di liberarsi dei giganti di Feralas per poter restare e mandare avanti i suoi affari. La sua soluzione è un raggio rimpicciolente basato su un progetto gnomico, migliorato con quelli che lui chiama i superiori progressi goblin. Preferisce che sia tu a provarlo, piuttosto che rischiare la vita.\n\nUsa l'Ultra-Shrinker sui Giganti delle Scogliere, sui Camminatori degli Abissi, sui Camminatori delle Onde, sui Camminatori della Riva o sui Camminatori Terrestri. Raccogli il residuo di miniaturizzazione che lasciano quando si rimpiccioliscono, poi riportalo ai moli."},{t="Perché Zorbin vuole il residuo",b="Zorbin definisce il residuo di miniaturizzazione prezioso per l'ingegneria. Aiuta a evitare che uno zapper esploda addosso a chi lo usa. Poi aggiunge che questo vale solo per gli altri zapper, non per quello che hai in mano."},{t="Ritorno ai moli",b="Zorbin è entusiasta quando torni con il residuo e tutti i tuoi arti principali intatti. Insiste che l'Ultra-Shrinker non è mai stato rischioso e ti definisce un amico dei goblin ovunque."}},faq={{q="Chi c'è dietro l'Ultra-Shrinker?",a="Zorbin Saldaleva ha costruito l'Ultra-Shrinker vicino ai moli sulla Costa dell'Oblio di Feralas.",al={"chi assegna zapped giants","zorbin saldaleva datore di missioni","dove iniziare zapped giants"}},{q="Perché Zorbin vuole che i giganti vengano rimpiccioliti?",a="Zorbin dice che i giganti danneggiano i suoi affari, se vuole restare lì. I giganti rimpiccioliti sono molto più facili da gestire.",al={"perché colpire i giganti","perché rimpicciolire i giganti a feralas","motivazioni di zorbin saldaleva"}},{q="Quali giganti possono essere rimpiccioliti?",a="Va bene qualsiasi tipo di gigante di Feralas. Lungo la Costa dell'Oblio trovi Giganti delle Scogliere, Camminatori degli Abissi, Camminatori delle Onde, Camminatori della Riva e Camminatori Terrestri.",al={"quali giganti posso colpire","quali giganti contano","bersagli di zapped giants"}},{q="Cos'è il residuo di miniaturizzazione?",a="Il residuo di miniaturizzazione resta su un gigante dopo che si è rimpicciolito. Zorbin lo definisce prezioso per l'ingegneria, perché aiuta a evitare che uno zapper esploda addosso a chi lo usa.",al={"perché il residuo di miniaturizzazione","a cosa serve il residuo","scopo del residuo di zorbin"}}},fp="13,232,30.457.0,28.193.0,17.182.1,33.84.0,39.108.0,27.154.0,32.159.0"}
P.entries["quest:701"] = {n="Guile of the Raptor",s="Tor'gan vuole risvegliare lo spirito guerriero sopito in Gor'mul usando l'astuzia del raptor. Raccoglie i cuori degli Highland Fleshstalkers per creare un amuleto incantato e restituire a Gor'mul la voglia di combattere.",h="Tor'gan vuole risvegliare lo spirito guerriero sopito in Gor'mul usando l'astuzia del raptor.",kw={"guerriero dormiente","gor'mul","guile of the raptor","highland fleshstalkers","cuori di raptor","tor'gan","guerriero"},ang={["class:Warrior"]="Da guerriero, sai che Tor'gan spera di risvegliare lo spirito guerriero sopito in Gor'mul con l'astuzia e la ferocia dei raptor.",["faction:Horde"]="Come membro dell'Orda, riconosci una tradizione che attinge alle bestie primordiali e agli spiriti della natura per ridare uno scopo a un compagno apatico o tormentato."},sec={{t="Risvegliare il guerriero sopito",b="Tor'gan vuole scuotere Gor'mul dalla sua apatia e ridestare lo spirito guerriero che giace sopito in lui. Si affida alla magia primordiale invece che alla persuasione, sperando che un amuleto intriso dell'essenza di predatori selvaggi spinga Gor'mul ad agire. Con questo amuleto, vuole rinnovare la sua risolutezza marziale e mostrargli la forza di tale potere."},{t="Il cuore del predatore",b="Tor'gan ha bisogno dei cuori degli Highland Fleshstalkers per invocare gli istinti di un cacciatore astuto. Nelle tradizioni sciamaniche e primordiali, il cuore di un predatore racchiude la sua ferocia e la sua astuzia. Tor'gan usa questi trofei per creare un pegno tangibile e intessere un incantesimo. Spera che donino a Gor'mul l'astuzia di un predatore e lo aiutino a riscoprire la sua vocazione."}},faq={{q="Chi è Tor'gan?",a="Tor'gan è una figura spirituale che vuole aiutare Gor'mul. Crede che Gor'mul abbia perso il contatto con la propria forza interiore, così raccoglie reagenti per creare un oggetto intriso di magia ferina e ridestarlo.",al={"chi è tor'gan","tor'gan","datore di missione"}},{q="Chi è Gor'mul?",a="Gor'mul ha perso lo spirito combattivo e il guerriero che è in lui giace sopito. Tor'gan vuole infondergli l'essenza primordiale di un predatore, affinché Gor'mul possa assistere a un nuovo potere e tornare a combattere.",al={"chi è gor'mul","perché aiutare gor'mul","guerriero dormiente"}},{q="Perché Tor'gan ha bisogno di cuori di raptor?",a="Tor'gan ha bisogno di dodici cuori di raptor per creare un talismano tangibile e intessere l'incantesimo che dovrebbe infondere in Gor'mul. La magia primordiale attinge ai cuori dei predatori per incanalarne gli istinti, l'astuzia e la forza.",al={"perché cuori di raptor","a cosa servono i cuori","magia dei raptor"}},{q="Da dove provengono i cuori di raptor?",a="I cuori provengono dagli Highland Fleshstalkers, raptor predatori noti per la caccia incessante e l'astuzia. Tor'gan crede che i loro cuori possano alimentare l'incantesimo che risveglierà Gor'mul.",al={"dove trovare i cuori","quali raptor","highland fleshstalkers"}},{q="Cosa significa l'astuzia del raptor?",a="L'astuzia del raptor è quella di un predatore: astuzia, riflessi fulminei e istinto letale. Tor'gan crede che questa natura possa scuotere Gor'mul dal torpore e ridestare il suo istinto combattivo.",al={"cos'è guile of the raptor","quale potere","significato dell'astuzia del raptor"}},{q="Qual è l'obiettivo finale del rituale?",a="Tor'gan usa i cuori raccolti per creare un oggetto e intessere un incantesimo. Spera di mostrare a Gor'mul un nuovo potere e risvegliare in lui il guerriero sopito, affinché possa ritrovare la sua strada.",al={"gor'mul è guarito","cosa succede dopo il rituale","funziona"}}},fp="19,196,29.335.0,25.336.0,15.190.0,15.194.0,36.199.0,37.179.0,42.187.0,40.176.0"}
P.entries["quest:702"] = {n="Guile of the Raptor",s="A Requie del Martello, Tor'gan manda Gor'mul un globo per risvegliare lo spirito del guerriero. La sua energia porta l'essenza del rapace e può dare a Gor'mul un nuovo scopo.",h="A Requie del Martello, Tor'gan manda Gor'mul un globo per risvegliare lo spirito del guerriero.",kw={"altopiani d'arathi","gor'mul","requie del martello","essenza del rapace","tor'gan","globo di tor'gan"},sec={{t="Globo di Tor'gan",b="Tor'gan ti dà un globo destinato a riempire Gor'mul con l'essenza del rapace. Spera che risvegli lo spirito del guerriero e lo indirizzi verso un nuovo percorso nella vita.\n\nQuando Gor'mul sarà tornato in sé, Tor'gan intende spiegargli la situazione attuale dell'Orda. Spera di ottenere l'aiuto di un grande guerriero nelle sue incessanti battaglie."},{t="L'amarezza di Gor'mul",b="Gor'mul accoglie il tuo ritorno con asprezza. Dice di volere soltanto altra pietà da parte di Tor'gan, poi si prende gioco di te parlando di fili dai colori vivaci."},{t="Uno strano potere",b="Il globo suscita l'interesse di Gor'mul. Commenta lo strano potere che emana."},{t="Il rapace interiore",b="Quando Gor'mul prende il globo, il suo sangue si agita e l'astuzia del rapace scorre attraverso di lui. Si chiede ad alta voce se questo sia lo sciamanesimo di cui parlava Tor'gan. Poi si dichiara rinvigorito, mentre le sue forze ritornano."}},faq={{q="Chi è Gor'mul?",a="A Requie del Martello, Gor'mul è un guerriero sconfortato. Tor'gan spera di risollevarlo e indirizzarlo verso un nuovo percorso, così che l'Orda possa ottenere l'aiuto di un grande guerriero.",al={"chi è gormul","lore di gormul","cosa c'è che non va in gormul"}},{q="Qual è lo scopo del Globo di Tor'gan?",a="Il Globo di Tor'gan porta un'energia destinata a riempire Gor'mul con l'essenza del rapace. Può risvegliare il suo spirito e dargli un nuovo scopo.",al={"cosa fa il globo","scopo del globo di tor'gan","globo dell'astuzia"}},{q="Cosa è successo prima di questo passaggio?",a="Prima viene una precedente Guile of the Raptor. Questo passaggio si basa su ciò che è accaduto lì.",al={"missione precedente","prerequisito"}}},fp="19,160,13.310.0,20.144.0,15.79.1,17.206.1,15.160.0,37.127.0,27.84.0"}
P.entries["quest:7025"] = {n="Dolcetti per Babbo Inverno",s="A Forgiardente, il nano che interpreta Babbo Inverno ti chiede un dolcetto delle feste. Portagli cinque biscotti di pan di zenzero appena sfornati e del Latte Ghiacciato, e ti ringrazierà con un regalo festivo.",h="A Forgiardente, il nano che interpreta Babbo Inverno ti chiede un dolcetto delle feste.",kw={"gran avvento d'inverno","biscotto di pan di zenzero","babbo inverno","latte ghiacciato","forgiardente","masseria buongusto","leccornie per babbo inverno"},ang={["faction:Alliance"]="Da viaggiatore dell'Alleanza, trovi i festeggiamenti del Gran Avvento d'Inverno a Forgiardente. Visitatori da tutti i Regni Orientali si radunano accanto all'albero delle feste nell'Area del Mercato.",["profession:Cooking"]="Da cuoco, prepari biscotti di pan di zenzero con uova piccole e Spezie Festive.",["race:Dwarf"]="Da nano, conosci Babbo Inverno come un'antica leggenda legata ai titani e ai doni dell'inverno. Nell'Area del Mercato, la figura si gode i biscotti e rende il mito più concreto."},sec={{t="Una lunga giornata al seggio",b="La Masseria Buongusto sponsorizza i festeggiamenti del Gran Avvento d'Inverno a Forgiardente. Accanto all'albero delle feste nell'Area del Mercato, siede un attore vestito da Babbo Inverno. Per ore ascolta i desideri dei cittadini e dei bambini impazienti. Indossa i panni di una figura immortale delle antiche leggende dei titani e dei nani."},{t="Preparare l'allegria festiva",b="Dopo aver ascoltato richieste di regali tutto il giorno, l'attore ha fame. Ti chiede cinque biscotti di pan di zenzero appena sfornati e del Latte Ghiacciato. Questo semplice pasto dà un momento di sollievo all esausto lavoratore del festival. La tua gentilezza diffonde benevolenza per tutta Forgiardente."}},faq={{q="Dove trovo Babbo Inverno a Forgiardente?",a="Babbo Inverno siede accanto al grande albero delle feste e all'esposizione della Masseria Buongusto nell'Area del Mercato di Forgiardente, tra le decorazioni festive.",al={"dove si trova babbo inverno","posizione babbo inverno forgiaardente","posizione babbo natale forgiaardente"}},{q="Come si preparano i Biscotti di Pan di Zenzero?",a="I venditori della Masseria Buongusto vicino a Babbo Inverno vendono la ricetta. Ti serve l'abilità di Cucina, le Spezie Festive del mercante del festival e uova piccole raccolte dagli uccelli selvatici per preparare i biscotti.",al={"dove trovare biscotti di pan di zenzero","ricetta pan di zenzero","come cucinare i biscotti"}},{q="Dove prendo il Latte Ghiacciato?",a="I locandieri, i venditori di cibo e quelli di bevande nelle principali città dell'Alleanza vendono Latte Ghiacciato. Puoi trovarlo nelle taverne di Forgiardente.",al={"venditore latte ghiacciato","dove comprare il latte","latte forgiaardente"}},{q="Questo Babbo Inverno è la vera figura mitica?",a="No. Durante il Gran Avvento d'Inverno, la Masseria Buongusto assume un nano per interpretare la figura leggendaria legata ai titani.",al={"babbo inverno è reale","chi è il tizio a forgiaardente","è davvero babbo inverno"}},{q="Cosa ti manda Babbo Inverno dopo aver finito la missione?",a="Dopo aver ricevuto i biscotti e il latte, Babbo Inverno ti ringrazia con un Pacco Regalo della Masseria Buongusto.",al={"ricompensa leccornie per babbo inverno","posta da babbo inverno","assortimento masseria buongusto"}},{q="I personaggi dell'Orda possono completare questa specifica missione?",a="Questa offerta di Forgiardente è per i viaggiatori dell'Alleanza. I membri dell'Orda hanno un'offerta equivalente che li porta da Babbo Inverno a Orgrimmar.",al={"l'orda può fare questa missione","dolcetti dell'orda per babbo inverno"}}},fx={["6bf2696f"]={q="Perché Babbo Inverno ha bisogno di te invece di procurarsi da solo i dolcetti?",a="Babbo Inverno non può abbandonare il suo posto durante i festeggiamenti. È accanto all'albero a Forgiardente per salutare la folla e diffondere allegria per conto dei Pascoli di Lungocampo, quindi è bloccato lì e si affida ai passanti generosi come te per sbrigare commissioni e procurargli del cibo.",al={"perché babbo inverno ha bisogno di me","perché babbo inverno non si procura da solo i biscotti","perché babbo inverno chiede aiuto a un avventuriero"}},["4b1f8d0d"]={q="Perché Babbo Inverno vuole che venga fatto?",a="Babbo Inverno è rimasto seduto a Forgiardente ad ascoltare i desideri per le feste e ad accogliere i visitatori per tutto il giorno, senza mai fare una pausa. Mentre la Veglia di Grande Inverno porta gioia a tutti gli altri, tutti i discorsi sui dolci festivi lo hanno lasciato esausto e affamato, così ti chiede di procurargli uno spuntino di cui ha molto bisogno.",al={"motivo dei biscotti per babbo inverno","perché babbo inverno vuole i biscotti","perché i dolci per babbo inverno"}},a70b2277={q="A cosa serve il Latte Ghiacciato?",a="Il Latte Ghiacciato è semplicemente una bevanda rinfrescante per accompagnare una porzione di caldi biscotti di pan di zenzero. Accogliere viaggiatori e gridare auguri festosi per tutto il giorno mette sete, e nulla accompagna i dolci biscotti delle feste meglio di una bevanda gelata.",al={"perché il latte ghiacciato","latte per babbo inverno","scopo del latte ghiacciato"}},cc125737={q="A cosa servono i biscotti di pan di zenzero?",a="I biscotti di pan di zenzero sono un dolce festivo personale per Babbo Inverno. Dopo aver distribuito dolci e ascoltato le richieste di cittadini su cittadini, desidera una tradizionale leccornia della Veglia di Grande Inverno, preparata con Spezie Festive, per recuperare le energie.",al={"biscotti di pan di zenzero per babbo inverno","perché i biscotti di pan di zenzero","biscotti per babbo inverno"}}},fp="29,183,22.305.0,20.261.0,48.143.0,36.195.0,29.137.0,50.116.0,64.104.1,47.144.0"}
P.entries["quest:703"] = {n="Barbecued Buzzard Wings",s="Razzopazzo ha tutti gli ingredienti per preparare le sue Barbecued Buzzard Wings, tranne le ali.",h="Razzopazzo ha tutti gli ingredienti per preparare le sue Barbecued Buzzard Wings, tranne le ali.",kw={"maleterre","barbecue","avvoltoio","cucina","ricetta","razzopazzo","ali"},ang={["profession:Cooking"]="I cuochi possono imparare da Razzopazzo la ricetta del piatto."},sec={{t="Una specialità locale",b="Razzopazzo va fiero delle sue Barbecued Buzzard Wings. Ricopre la carne dal gusto deciso con una salsa ricca, il cui aroma attira la gente affamata dei dintorni. Ha tutti gli ingredienti per prepararne una porzione, tranne le ali. Portagli quattro ali di avvoltoio e potrebbe condividere la ricetta."}},faq={{q="Chi chiede le ali di avvoltoio?",a="Razzopazzo vuole delle ali di avvoltoio per preparare una porzione delle sue Barbecued Buzzard Wings.",al={"chi fornisce le barbecued buzzard wings","chi è razzopazzo","datore di missione"}},{q="Cosa offre Razzopazzo in cambio delle ali?",a="Razzopazzo potrebbe condividere la ricetta in cambio di abbastanza ali.",al={"qual è la ricompensa","cosa ottengo","ricompensa ricetta"}},{q="Perché Razzopazzo ha bisogno di ali di avvoltoio?",a="A Razzopazzo serve tutto per preparare il piatto, tranne le ali.",al={"perché gli avvoltoi","motivazione di razzopazzo","perché razzopazzo vuole le ali"}},{q="Quante ali vuole Razzopazzo?",a="Razzopazzo vuole quattro ali di avvoltoio.",al={"quante ali di avvoltoio","conteggio ali di avvoltoio"}}},fp="23,92,16.251.0,31.66.0,51.59.0,39.62.0,36.36.0"}
P.entries["quest:705"] = {n="Pearl Diving",s="Nelle Maleterre, Razzopazzo sta finendo la polvere per le sue bombe lampo. Ti manda alla Scogliera Infame, nella Valle di Rovotorto, per raccoglierne altra.",h="Nelle Maleterre, Razzopazzo sta finendo la polvere per le sue bombe lampo.",kw={"maleterre","perla blu","bomba lampo","pearl diving","razzopazzo","valle di rovotorto","scogliera infame"},ang={["profession:Engineering"]="Da ingegnere, hai buoni motivi per interessarti alle bombe lampo di Razzopazzo."},sec={{t="Un piccolo goblin astuto",b="Razzopazzo ammette che le Maleterre lo spaventano. Piccolo goblin, è circondato da predatori e sciacalli. Sa fabbricare bombe lampo e le usa per scacciare la fauna selvatica. Ora sta finendo la polvere di perla blu frantumata."},{t="Perle dalla scogliera",b="Le vongole della Scogliera Infame, nella Valle di Rovotorto, contengono perle blu. Razzopazzo scherza dicendo che faresti meglio a indossare degli stivali robusti, poi ti aspetta nelle Maleterre per ricevere nove perle. Promette di ricompensarti per il tuo impegno."}},faq={{q="Perché Razzopazzo ha bisogno di perle blu?",a="Razzopazzo usa la polvere di perla blu frantumata per fabbricare bombe lampo, ma la sua scorta sta finendo.",al={"perle razzopazzo","perché pearl diving","perché perle blu"}},{q="Dove si trovano le perle blu?",a="Le perle blu si trovano nelle vongole della Scogliera Infame, nella Valle di Rovotorto.",al={"dove sono le perle blu","posizione perla blu","perle scogliera infame"}},{q="Perché Razzopazzo usa le bombe lampo?",a="Predatori feroci e sciacalli audaci popolano le Maleterre, così Razzopazzo usa bombe lampo per spaventare la fauna selvatica e scacciarla.",al={"perché bombe lampo","difesa razzopazzo"}},{q="Quante perle blu vuole Razzopazzo?",a="Razzopazzo vuole che gli porti nove perle blu nelle Maleterre.",al={"conteggio perle blu","quante perle"}}},fp="12,136,22.241.0,20.199.0,37.93.0,32.65.0,36.118.0,42.67.0"}
P.entries["quest:706"] = {n="Fiery Blaze Enchantments",s="Per gli Fiery Blaze Enchantments nelle Maleterre serve il cuore ancora pulsante di un raro cucciolo di drago nero. Sigrun Tagliaferro aspetta notizie da Forgiardente, e i cuccioli della Piana di Lethlor potrebbero fornirle ciò che le serve.",h="Per gli Fiery Blaze Enchantments nelle Maleterre serve il cuore ancora pulsante di un raro cucciolo di drago...",kw={"maleterre","cuore di drago nero","feranor steeltoe","vampata di fuoco","forgiardente","piana di lethlor","scalding whelp","scorched guardian","sigrun tagliaferro"},ang={["faction:Alliance"]="Sigrun Tagliaferro aspetta notizie da Forgiardente, e questo lavoro è destinato all'Alleanza."},sec={{t="L'arte di un apprendista",b="Sigrun Tagliaferro ha imparato ad accendere il fuoco sulle armi mentre era apprendista di Feranor Steeltoe. L'ultima notizia su Feranor lo dava tra i fabbri di una spedizione di caccia a Lordaeron. Sigrun aspetta notizie da Forgiardente nelle Maleterre. Ha ben poco altro da fare."},{t="I cuccioli della Piana di Lethlor",b="Sigrun condivide pochi dettagli sul processo. Serve il sangue del cuore ancora pulsante di un raro cucciolo di drago nero. Portale un cuore di un cucciolo della Piana di Lethlor e ti mostrerà la tecnica. Gli Scalding Whelp e i Scorched Guardian che vivono lì forniscono i cuori."}},faq={{q="Chi ha insegnato a Sigrun Tagliaferro questa tecnica di incantamento?",a="Sigrun ha appreso la tecnica come apprendista di Feranor Steeltoe. L'ultima notizia su Feranor lo dava tra i fabbri di una spedizione di caccia a Lordaeron.",al={"insegnante sigrun","chi ha addestrato sigrun","feranor steeltoe"}},{q="Quale componente è necessario per infondere il fuoco su una lama?",a="L'incantamento richiede il sangue del cuore ancora pulsante di un raro cucciolo di drago nero.",al={"cosa serve a sigrun","requisito cuore di drago nero","materiali per vampata di fuoco"}},{q="Dove si trovano i cuccioli di drago nero?",a="I cuccioli di drago nero si trovano nella Piana di Lethlor, nella parte orientale delle Maleterre.",al={"dove trovare draghi neri","cuccioli piana di lethlor","posizione cuore di drago nero"}},{q="Perché Sigrun Tagliaferro si trattiene nelle Maleterre?",a="Sigrun aspetta notizie da Forgiardente e nel frattempo ha ben poco altro da fare.",al={"perché sigrun è nelle maleterre","scopo sigrun tagliaferro"}},{q="Quali creature forniscono il cuore necessario?",a="Gli Scalding Whelp e i Scorched Guardian della Piana di Lethlor forniscono il cuore necessario.",al={"cosa rilascia il cuore di drago nero","quali cuccioli hanno i cuori"}}},fp="24,208,21.244.0,28.266.0,53.142.0,52.89.0,39.72.0,48.84.0,39.84.0"}
P.entries["quest:708"] = {n="The Black Box",s="Un condor gigante a Maleterre ha inghiottito una scatola nera diretta a Forgiardente.",h="Un condor gigante a Maleterre ha inghiottito una scatola nera diretta a Forgiardente.",kw={"maleterre","scatola nera","scatola nera corrosa","condor gigante","salone delle armi","ironforge siege brigade","pilota barbalunga"},ang={["faction:Alliance"]="La scatola reca il marchio di Forgiardente e le sue tracce conducono a Forgiardente."},sec={{t="Estratta da un condor",b="Dopo essere rimasta per ere nello stomaco del condor, l’acido ha butterato il metallo. Sul lato inferiore, sopra la scritta Engine #19 - Ironforge Siege Brigade, c’è un simbolo. Porti la scatola al Pilota Barbalunga nel Salone delle Armi di Forgiardente."}},faq={{q="Da dove proviene la scatola nera corrosa?",a="Un condor gigante a Maleterre ha inghiottito la scatola, che sembra essere rimasta nel suo stomaco per ere.",al={"da dove viene la scatola","come è arrivata qui la scatola","origine scatola nera"}},{q="Quali marchi sono stampati sulla scatola?",a="Sul lato inferiore, sopra la scritta Engine #19 - Ironforge Siege Brigade, è impresso un simbolo.",al={"cosa c'è scritto sulla scatola","marchi sulla scatola nera","iscrizione scatola"}},{q="Chi dovrebbe ricevere la scatola?",a="Il Pilota Barbalunga, nel Salone delle Armi a Forgiardente.",al={"chi riceve la scatola","dove va la scatola nera","a chi devo portare la scatola"}}},fp="13,74,20.211.0,43.100.0,37.90.0,35.50.0"}
P.entries["quest:71"] = {n="A rapporto da Thomas",s="La Guardia Thomas attende al ponte orientale tra Borgodoro e il Campo di Taglio di Vallevante. La sorte dei suoi uomini scomparsi potrebbe rivelare se i murloc del fiume minacciano altri oltre agli esploratori.",h="La Guardia Thomas attende al ponte orientale tra Borgodoro e il Campo di Taglio di Vallevante.",kw={"ponte","foresta di elwynn","borgodoro","guardia thomas","malakai","medaglioni","murloc","rolf"},ang={["faction:Alliance"]="La morte di Rolf e Malakai mostra quanto siano esposti i confini della Foresta di Elwynn. Anche le normali pattuglie fluviali possono essere sopraffatte quando le guardie scarseggiano.",["race:Human"]="Da umano, recuperare i medaglioni delle guardie cadute dà un po' di onore e una conclusione ai soldati di Roccavento morti difendendo le strade interne del regno."},sec={{t="Una Cupa Conferma",b="Con pochi uomini da assegnare al ponte, Thomas sperava che Malakai e Rolf fossero soltanto isolati o in ritardo nelle terre fluviali. I medaglioni di servizio recuperati non lasciano spazio alla speranza. Entrambe le guardie sono state uccise vicino ai corsi d'acqua."},{t="La Minaccia Lungo l'Acqua",b="Da mesi, i capi di Roccavento considerano i murloc un fastidio, abitanti dei fiumi, e si concentrano invece sui banditi e sui confini più vasti del regno. Ora due guardie armate di Roccavento sono state massacrate lungo i torrenti dell'entroterra. I medaglioni mostrano a Thomas che la frontiera orientale di Elwynn è sotto attacco, e lui chiede una risposta prima che le rotte di disboscamento e gli insediamenti vengano sopraffatti."}},faq={{q="Dove si trova la Guardia Thomas?",a="La Guardia Thomas è di stanza presso il ponte di pietra sul fiume, nella parte orientale della Foresta di Elwynn, lungo la strada tra Borgodoro e il Campo di Taglio di Vallevante.",al={"posizione di thomas","ponte guardia thomas","dov'è la guardia thomas"}},{q="Chi erano Rolf e Malakai?",a="Rolf e Malakai erano guardie di Roccavento inviate a pattugliare la parte orientale della Foresta di Elwynn. I murloc lungo le rive e il Lago Stonecairn li hanno sopraffatti e uccisi.",al={"guardie scomparse elwynn","chi era rolf","chi era malakai"}},{q="Perché i loro medaglioni erano necessari?",a="I medaglioni identificano le guardie cittadine di Roccavento. Restituirli dà alla Guardia Thomas la prova che i suoi uomini scomparsi sono morti in servizio.",al={"perché i medaglioni","scopo medaglioni guardia"}},{q="Perché l'attacco dei murloc è una cosa così grave?",a="I murloc sono spesso liquidati come parassiti primitivi e codardi. La morte di due guardie armate dimostra che le tribù fluviali possono tendere imboscate coordinate e minacciare soldati addestrati.",al={"perché minaccia murloc","i murloc sono pericolosi a elwynn"}},{q="Cosa succede dopo aver fatto rapporto a Thomas?",a="Thomas ti chiede di portare un rapporto sulla morte delle guardie e sulla crescente minaccia dei murloc al Maresciallo Dughan a Borgodoro. Dughan avverte che le difese della regione sono già messe a dura prova.",al={"missione successiva dopo rapporto a thomas","cosa fa thomas dopo"}},{q="Perché la Guardia Thomas è di stanza da sola al ponte?",a="L'esercito di Roccavento è sparso per tutto il regno, con Re Varian Wrynn scomparso e risorse limitate. Al ponte orientale e negli altri avamposti periferici ci sono poche guardie a proteggere le rotte vitali.",al={"perché thomas è solo","guardia ponte roccavento sola"}}},fx={d4d51b05={q="Perché consegnare i medaglioni alla Guardia Thomas?",a="La Guardia Thomas ha mandato delle pattuglie verso il fiume, ma gli uomini sono svaniti senza lasciare traccia. Trovare Rolf e Malakai morti tra i canneti dà la certezza, amara, della loro sorte. Riportare a Thomas i medaglioni recuperati dimostra senza ombra di dubbio cosa è accaduto ai suoi uomini e lo avverte della letale presenza dei murloc lungo la sponda orientale.",al={"perché fare rapporto a thomas","perché portare i medaglioni a thomas","scopo del rapporto a thomas"}},["3744e02c"]={q="Perché sei tu a dover riportare i medaglioni a Thomas?",a="Rolf e Malakai sono morti, uccisi dai murloc nel villaggio ostile sulla riva del fiume. La Guardia Thomas è di stanza da solo a sorvegliare il ponte orientale e non può lasciare incustodito il suo posto. Poiché sei il viandante che ha trovato le guardie cadute e ha affrontato i murloc per recuperare le loro insegne, spetta a te riportare la triste notizia.",al={"perché devo fare rapporto a thomas","perché devo portare i medaglioni"}}},fp="16,179,19.218.0,26.390.0,30.144.0,26.154.1,36.133.1,41.180.1,44.185.1,47.196.0"}
P.entries["quest:710"] = {n="Study of the Elements: Rock",s="Nelle Maleterre, Lotwil Veriatus ha bisogno di frammenti di pietra per collaudare il suo lavoro sui vincoli per gli elementali. Piccoli elementali della roccia vagano sulle colline appena a ovest di lui.",h="Nelle Maleterre, Lotwil Veriatus ha bisogno di frammenti di pietra per collaudare il suo lavoro sui vincoli...",kw={"maleterre","piccoli elementali della roccia","lotwil veriatus","vincoli per gli elementali","piccoli frammenti di pietra","study of the elements: rock"},ang={["class:Mage"]="In quanto mago, fai parte di coloro che i vincoli di Lotwil sono destinati a servire."},sec={{t="Vincoli Elementali",b="Nelle Maleterre, Lotwil Veriatus sta creando vincoli per gli elementali. Una volta terminati, permetteranno ai maghi di evocare elementali più potenti per scopi più importanti. Per collaudare i suoi incantesimi offensivi e alcuni marchingegni assemblati alla meglio, gli servono dieci piccoli frammenti di pietra. Piccoli elementali della roccia vagano sulle colline subito a ovest."}},faq={{q="Chi sta chiedendo i frammenti di pietra?",a="Nelle Maleterre, Lotwil Veriatus sta lavorando e chiede frammenti di pietra.",al={"chi dà questa missione","datore di missione","lotwil veriatus"}},{q="A cosa sta lavorando Lotwil Veriatus?",a="Lotwil Veriatus sta creando vincoli per gli elementali. Permetteranno ai maghi di evocare elementali più potenti.",al={"progetto di lotwil","vincoli per gli elementali","cosa sta costruendo lotwil"}},{q="Perché Lotwil ha bisogno di piccoli frammenti di pietra?",a="Lotwil ha bisogno dei frammenti per collaudare i suoi incantesimi offensivi e alcuni marchingegni assemblati alla meglio.",al={"perché frammenti di pietra","scopo dei frammenti","a cosa servono i frammenti"}},{q="Dove si trovano i frammenti di pietra?",a="I frammenti si trovano sugli elementali della roccia sulle colline subito a ovest di Lotwil.",al={"dove trovare i frammenti","posizione dei piccoli elementali della roccia","fonte dei frammenti di pietra"}}},fp="27,147,18.305.0,35.71.0,35.104.0,40.82.0,33.84.0"}
P.entries["quest:711"] = {n="Study of the Elements: Rock",s="Lotwil Veriatus è pronto a provare pezzi più grandi, dopo che i frammenti piccoli hanno reagito come previsto. Gli servono tre grandi lastre di pietra dagli elementali della roccia.",h="Lotwil Veriatus è pronto a provare pezzi più grandi, dopo che i frammenti piccoli hanno reagito come previsto.",kw={"maleterre","grandi lastre di pietra","lotwil veriatus","elementali della roccia","lastre di pietra","study of the elements: rock"},sec={{t="Pezzi più grandi",b="Lotwil Veriatus ha bisogno di pezzi più resistenti per i suoi prossimi test. Gli elementali della roccia hanno corpi più grandi, quindi i loro resti potrebbero fornire lastre abbastanza grandi.\n\nTi indica di spingerti più a ovest o a sud-est, lungo i margini delle montagne, per raccogliere tre grandi lastre di pietra. Per ora, Lotwil ha bisogno di tempo per esaminare i pezzi più piccoli che hai portato."},{t="Le speranze di Lotwil",b="Gli incantesimi di Lotwil hanno agito sui pezzi più piccoli come aveva previsto. Se il prossimo esperimento andrà come spera, gli elementali che controlla supereranno qualsiasi cosa abbia evocato prima."}},faq={{q="Chi ti manda a cercare le grandi lastre?",a="Lotwil Veriatus, al lavoro nelle Maleterre, ti manda a raccogliere le grandi lastre.",al={"chi assegna questa missione","missione di lotwil","chi dà study of the elements"}},{q="Cosa è successo prima di questa richiesta?",a="Prima di questa richiesta, hai portato a Lotwil piccoli frammenti di pietra durante il precedente Study of the Elements: Rock.",al={"missione precedente","passaggio precedente","cosa ho fatto prima"}},{q="Dove dice Lotwil di trovare gli elementali della roccia?",a="Lotwil ti indica di spingerti più a ovest o a sud-est, lungo i margini delle montagne.",al={"dove sono gli elementali","posizioni degli elementali","dove trovare le lastre"}},{q="Perché Lotwil ha bisogno di lastre di pietra più grandi?",a="Lotwil ha bisogno di pezzi più grandi per i suoi prossimi test. Gli elementali della roccia hanno corpi più grandi e robusti, quindi i loro resti potrebbero fornire pezzi abbastanza grandi.",al={"perché lastre grandi","scopo delle lastre","obiettivo della ricerca di lotwil"}}},fp="27,148,13.306.0,14.177.0,36.78.0,30.106.0,50.77.0,40.140.0"}
P.entries["quest:712"] = {n="Study of the Elements: Rock",s="Nelle Maleterre, Lotwil Veriatus ha bisogno dei bracciali dei grandi elementali della roccia per valutare le sue catene.",h="Nelle Maleterre, Lotwil Veriatus ha bisogno dei bracciali dei grandi elementali della roccia per valutare le...",kw={"maleterre","bracciali del vincolo di roccia","grandi elementali della roccia","kharanos","lotwil veriatus","lucien","ogre","servo"},sec={{t="Valutare le catene",b="Dopo le lastre di pietra, a Lotwil Veriatus serve un ultimo componente dagli elementali delle Maleterre. I bracciali del vincolo di roccia, presi dai grandi elementali della roccia, lo aiuteranno a valutare le catene in costruzione.\n\nLa sua divinazione ha individuato un gruppo a sud-ovest, vicino ad alcuni ogre, se la memoria non inganna. Chiede cinque bracciali per averne di scorta, dato che Servo spesso smarrisce reagenti e ricerche."}},faq={{q="Perché Lotwil ha bisogno dei bracciali?",a="I bracciali del vincolo di roccia permetteranno a Lotwil di valutare la resistenza delle sue catene.",al={"perché bracciali del vincolo di roccia","a cosa servono i bracciali","bracciali del vincolo lotwil"}},{q="Perché Lotwil chiede cinque bracciali?",a="Lotwil chiede cinque bracciali per averne di scorta, dato che Servo spesso smarrisce reagenti e ricerche.",al={"perché cinque bracciali","quanti bracciali","perché degli extra"}},{q="Dove si trovano i grandi elementali della roccia?",a="La divinazione di Lotwil ha individuato un gruppo a sud-ovest, vicino ad alcuni ogre. Le colline intorno a Campo Cagg ospitano i grandi elementali della roccia.",al={"dove sono gli elementali della roccia","posizione grandi elementali della roccia","dove trovare i bracciali"}},{q="Che fine fanno le lastre di pietra raccolte in precedenza?",a="Quando il lavoro qui sarà terminato, Lucien riporterà le lastre in eccesso a Kharanos, dove potrebbero tornare utili.",al={"che fine hanno fatto le lastre di pietra","lastre di pietra lucien","lastre kharanos"}}},fp="27,98,20.369.0,33.79.0,37.100.0,46.126.0,50.115.0"}
P.entries["quest:713"] = {n="Coolant Heads Prevail",s="A Lotwil Veriatus serve Olio del Freddo per le catene che tengono il suo amico evocato. Bro'kin, l'amico goblin di Lotwil ad Alterac, può insegnarti a prepararlo.",h="A Lotwil Veriatus serve Olio del Freddo per le catene che tengono il suo amico evocato.",kw={"maleterre","bro'kin","coolant heads prevail","olio del freddo","lotwil veriatus","rovine d'alterac","vincoli"},sec={{t="Un refrigerante vitale",b="Lotwil Veriatus dice che l'Olio del Freddo impedisce a motori e ingranaggi di surriscaldarsi. Lo definisce un lubrificante impareggiabile. Aiuta anche gli oggetti magici a mantenere i loro incantamenti. L'olio potrebbe rinforzare abbastanza le catene di Lotwil da impedire al suo amico evocato di uccidere tutti."},{t="Bro'kin di Alterac",b="Bro'kin, l'amico goblin di Lotwil, può insegnarti a preparare l'Olio del Freddo. Vende da una postazione sulle mura della vecchia città, nelle Rovine d'Alterac."},{t="Quando arriva l'olio",b="Quando arriva l'olio, Lotwil lo definisce il refrigerante perfetto per i nuovi bracciali. Giura che, se gli incantamenti non dureranno un secolo, tutti i suoi averi andranno a Servo. Lotwil si aspetta che i maghi dell'Assemblea rimangano a bocca aperta quando il lavoro sarà finito."}},faq={{q="Perché Lotwil Veriatus ha bisogno dell'Olio del Freddo?",a="L'Olio del Freddo rinforzerebbe abbastanza le catene di Lotwil Veriatus da impedire al suo amico evocato di uccidere tutti.",al={"perché olio del freddo","a cosa serve l'olio del freddo","olio di lotwil"}},{q="Chi sa come preparare l'Olio del Freddo?",a="Bro'kin, l'amico goblin di Lotwil Veriatus, può insegnarti a preparare l'Olio del Freddo. Vende da una postazione sulle mura della vecchia città, nelle Rovine d'Alterac.",al={"chi insegna olio del freddo","dove imparare olio del freddo","ricetta brokin"}},{q="Cosa c'è di speciale nell'Olio del Freddo?",a="Lotwil Veriatus dice che l'Olio del Freddo impedisce a motori e ingranaggi di surriscaldarsi. Lo definisce un lubrificante impareggiabile e dice che aiuta gli oggetti magici a mantenere i loro incantamenti.",al={"proprietà olio del freddo","perché l'olio del freddo è buono"}}},fp="21,147,15.262.0,18.134.0,20.254.1,40.111.0,32.143.0,32.165.0"}
P.entries["quest:714"] = {n="Gyro... What?",s="A Maleterre, Lotwil Veriatus è ancora al lavoro sul suo marchingegno. Gli hai portato l'Olio del Freddo da Coolant Heads Prevail, ma manca un piccolo pezzo: un girocronatomo.",h="A Maleterre, Lotwil Veriatus è ancora al lavoro sul suo marchingegno.",kw={"maleterre","marchingegno","coolant heads prevail","girocronatomo","kharanos","lotwil veriatus"},ang={["profession:Engineering"]="Da ingegnere, puoi fabbricare un girocronatomo da solo."},sec={{t="Una parte fondamentale",b="Lotwil Veriatus è così preso dal lavoro che ti elogia per aver svolto l'incarico ben oltre ogni aspettativa. Poi dice che puoi candidarti per un lavoro se lo incontri a Kharanos.\n\nSegue una frettolosa ricerca, mentre Lotwil cerca di afferrare qualcosa. Poi ti chiede un girocronatomo. Il pezzo è piccolo ma fondamentale, e con esso il progetto dovrebbe essere pronto per essere completato."},{t="Consegnare l'oggetto",b="Quando gli consegni il girocronatomo, Lotwil Veriatus lo afferra gridando. Dice che il lavoro è quasi finito e che il progetto è la sua massima priorità. La promessa di finire presto si allunga da pochi minuti a forse molto più tempo."}},faq={{q="Chi sta chiedendo il girocronatomo?",a="Lotwil Veriatus sta lavorando a un marchingegno a Maleterre e ti chiede un girocronatomo.",al={"chi dà cosa per il giro","chi dà la missione del giro","lotwil veriatus maleterre"}},{q="Per cosa serve a Lotwil Veriatus il girocronatomo?",a="Il girocronatomo è un pezzo piccolo ma fondamentale del progetto di Lotwil Veriatus. Con esso, dovrebbe essere pronto a completare il lavoro.",al={"perché girocronatomo","cosa sta costruendo lotwil"}},{q="Qual è l'offerta riguardante Kharanos?",a="Lotwil Veriatus dice che puoi candidarti per un lavoro se lo incontri a Kharanos.",al={"lotwil kharanos","offerta di lavoro kharanos"}},{q="Dove si può trovare un girocronatomo?",a="Gli ingegneri fabbricano girocronatomi e i venditori di forniture d'ingegneria li vendono.",al={"come ottenere girocronatomo","fonte girocronatomo","dove comprare girocronatomo"}}},fp="13,180,14.358.0,15.227.1,36.93.0,53.125.0,33.72.0,35.67.0"}
P.entries["quest:716"] = {n="Stone Is Better than Cloth",s="A Maleterre, Lucien Chiavetorta ha un regalo per te, anche se il suo lavoro non è finito. Le pietre in più che hai raccolto sono pronte, ma gli servono ancora patterned bronze bracers.",h="A Maleterre, Lucien Chiavetorta ha un regalo per te, anche se il suo lavoro non è finito.",kw={"maleterre","roccia elementale","bracciali incantati","lotwil veriatus","lucien chiavetorta","bracciali di bronzo lavorati"},ang={["profession:Blacksmithing"]="Da fabbro, puoi creare i bracciali di bronzo che servono a Lucien."},sec={{t="Un ringraziamento per il disturbo",b="Dopo il tuo lavoro per Lotwil sulla sua terza richiesta di Study of the Elements: Rock, Lucien Chiavetorta ammette che Lotwil può essere tirchio. Vuole sdebitarsi con te con raffinati bracciali incantati, forgiati con le pietre in più che hai raccolto. Potrebbero aiutarti a proteggerti dalla futura atrocità della più recente invenzione di Lotwil."},{t="Ciò di cui Lucien ha bisogno",b="Per finire i bracciali, Lucien ha bisogno di patterned bronze bracers, del tipo che fabbrica un fabbro. Ti avverte di non aspettare troppo. Nessuno sa cosa succederà dopo."}},faq={{q="Chi si offre di creare i bracciali?",a="A Maleterre, Lucien Chiavetorta si offre di creare bracciali incantati con le pietre in più che hai raccolto.",al={"chi dà stone is better than cloth","datore di missione","lucien chiavetorta"}},{q="Perché Lucien sta creando questa armatura per te?",a="Lucien sa che Lotwil può essere tirchio e vuole ricompensarti per il disturbo. Dice che i bracciali potrebbero anche proteggerti dalla più recente invenzione di Lotwil.",al={"perché creare bracciali","motivo di lucien","lotwil tirchio"}},{q="Di cosa ha bisogno Lucien per finire di creare i bracciali?",a="Per finire i bracciali incantati, a Lucien servono patterned bronze bracers, del tipo che fabbrica un fabbro.",al={"quale oggetto è necessario","oggetti richiesti","bracciali di bronzo lavorati necessari"}},{q="Cosa precede questa missione?",a="Segue il tuo lavoro sulla terza richiesta di Lotwil di Study of the Elements: Rock.",al={"missione precedente","prerequisito per stone is better than cloth"}}},fp="26,175,28.310.0,17.155.0,32.92.0,40.147.0,53.100.0,29.75.0"}
P.entries["quest:7162"] = {n="Piana del Conflitto",s="Ad Alterac, le reclute affrontano una prova prima di poter entrare nella Guardia dei Piccatonante. Il Tenente Haggerdin le manda nelle Caverne Aladigelo a recuperare uno stendardo da battaglia piazzato lì. Se riescono, ottengono un Fregio dei Piccatonante ufficiale e possono avanzare nei ranghi della spedizione.",h="Ad Alterac, le reclute affrontano una prova prima di poter entrare nella Guardia dei Piccatonante.",kw={"dun baldar","haggerdin","arpie","caverne aladigelo","fregio","prova del novizio","piccatonante","stendardo dei piccatonante"},ang={["faction:Alliance"]="La spedizione dei Piccatonante è la principale operazione militare dell'Alleanza ad Alterac. Unisce le ambizioni archeologiche dei nani alla difesa del territorio dell'Alleanza contro l'Orda.",["race:Dwarf"]="Da nano, entri in una guardia guidata soprattutto da nani di Forgiardente, in cerca di reliquie ancestrali e misteri dei Titani. Questa prova può essere il tuo primo passo in una delle unità militari più fiere della tua razza."},sec={{t="Una Misura del Coraggio",b="La Guardia dei Piccatonante combatte contro il Clan Lupi Bianchi nella Valle d'Alterac. Il Tenente Haggerdin dirige le forze dell'Alleanza dal loro accampamento nelle Montagne d'Alterac. Prima che le reclute raggiungano il campo di battaglia, mette alla prova la loro abilità e il loro coraggio nelle Caverne Aladigelo, a sud-ovest di Dun Baldar."},{t="Le Caverne Aladigelo",b="Nel profondo delle Caverne Aladigelo, uno stendardo dei Piccatonante attende tra i tunnel ghiacciati. Arpie del gelo nidificano negli anfratti gelidi e attaccano gli intrusi incauti. Una recluta che riporta lo stendardo intatto ha attraversato un terreno pericoloso, affrontato i predatori e mantenuto la disciplina sotto pressione."},{t="Il Fregio dei Piccatonante",b="Torna dalle caverne con lo stendardo e otterrai il fregio da iniziato dei Piccatonante e un posto nella forza di spedizione. Haggerdin dice che il fregio può essere migliorato man mano che guadagni maggior onore sul campo di battaglia. L'Occhio del Comando è un obiettivo lontano."}},faq={{q="Chi è il Tenente Haggerdin?",a="Il Tenente Haggerdin è un ufficiale dell'Alleanza nelle Montagne d'Alterac, responsabile del reclutamento e dei riconoscimenti sul campo della Guardia dei Piccatonante. Mette alla prova gli aspiranti combattenti e premia il loro servizio con fregi militari.",al={"tenente haggerdin","haggerdin","chi assegna la prova del novizio"}},{q="Dove si trovano le Caverne Aladigelo?",a="Le Caverne Aladigelo si trovano a sud-ovest di Dun Baldar, la roccaforte dell'Alleanza nella Valle d'Alterac. I loro tunnel tortuosi si snodano sotto ghiaccio e roccia.",al={"posizione caverne aladigelo","dove sono le caverne aladigelo","posizione dello stendardo"}},{q="Quali minacce dimorano all'interno delle Caverne Aladigelo?",a="Arpie feroci del gelo vivono nelle Caverne Aladigelo. Haggerdin avverte che tendono imboscate agli intrusi e gli strappano la gola.",al={"arpie","cosa c'è nelle caverne aladigelo","arpie aladigelo"}},{q="Perché la Guardia dei Piccatonante richiede questo test?",a="La Guardia dei Piccatonante combatte una guerra brutale contro gli orchi del Clan Lupi Bianchi. Haggerdin mette alla prova le reclute prima che si uniscano alle linee principali, così ogni soldato che porta lo stendardo può combattere in condizioni difficili.",al={"perché la prova del novizio","perché fare la prova dello stendardo","iniziazione piccatonante"}},{q="Qual è la ricompensa per aver completato la prova del novizio?",a="Torna con lo stendardo e otterrai il fregio da iniziato dei Piccatonante. Haggerdin può migliorarlo man mano che guadagni onore nella Valle d'Alterac.",al={"fregio dei piccatonante","occhio del comando","ricompensa prova del novizio"}},{q="Chi sono i Lupi Bianchi menzionati da Haggerdin?",a="Il Clan Lupi Bianchi è un clan orchesco che vive nella Valle d'Alterac da quando fu esiliato, decenni fa. La Guardia dei Piccatonante li considera selvaggi ostili che ostacolano gli interessi dell'Alleanza e gli scavi nella valle.",al={"selvaggi lupi bianchi","chi sono i lupi bianchi","clan lupi bianchi"}}},fx={b9e84d22={q="A cosa serve lo Stendardo dei Piccatonante nelle caverne?",a="Piantato nel cuore delle pericolose Caverne di Ala Gelida, lo Stendardo dei Piccatonante funge da segnale di prova per le reclute che vogliono unirsi alla forza di spedizione. Per reclamarlo, devi affrontare le feroci arpie che infestano le caverne e dimostrare il coraggio, l'ingegno e la tenacia richiesti a un vero soldato Piccatonante, prima ancora di mettere piede sul campo di battaglia.",al={"cos'è lo stendardo dei piccatonante","perché lo stendardo è nelle caverne di ala gelida","scopo dello stendardo dei piccatonante"}}},fp="15,256,20.271.0,19.276.0,22.254.0,28.213.0,30.136.0,46.119.0,47.191.0,53.135.0,47.209.0"}
P.entries["quest:717"] = {n="Tremors of the Earth",s="A Lethlor, Garek teme che i draghi possano liberarsi. Ora lì dimorano draghi neri e gli ogre hanno preso il Simbolo della Terra. Perciò ti manda a liberare i draghi e ucciderli.",h="A Lethlor, Garek teme che i draghi possano liberarsi.",kw={"blacklash","garek","hematus","kirin tor","krasus","piana di lethlor","pietre runiche","sigillo della terra","simbolo della terra","tremors of the earth"},ang={["faction:Alliance"]="La richiesta di Garek è rivolta a te, membro dell'Alleanza."},sec={{t="Una prigione che cede",b="A Lethlor, Garek teme che Blacklash e Hematus possano evadere dalla loro prigione. Ora lì dimorano draghi neri e gli ogre hanno preso il Simbolo della Terra. Garek non vede alternative più sicure. I draghi devono morire."},{t="Rompere il sigillo",b="Tre pietre runiche tengono imprigionati i draghi e serve il Simbolo della Terra per liberarli. Usa il Simbolo sui Pilastri di Ametista, Opale e Diamante, poi colloca le pietre runiche nel Sigillo della Terra. Blacklash e Hematus sono liberi, e tu li uccidi. Garek ti chiede di riportargli i Bracciali di Codanera, le Catene di Hematus e il Simbolo della Terra."},{t="Dopo l'impresa",b="Dopo la morte dei draghi, Garek dice che il Kirin Tor non deve più preoccuparsi dei prigionieri di Lethlor. Ha intenzione di riferire il successo al suo maestro, Krasus. Krasus ne sarà sicuramente compiaciuto."}},faq={{q="Chi sono Blacklash e Hematus?",a="Blacklash e Hematus sono draghi imprigionati dietro un sigillo a Lethlor.",al={"blacklash e hematus","chi sono i draghi","cosa è imprigionato a lethlor"}},{q="Perché i draghi devono essere uccisi invece di essere tenuti rinchiusi?",a="Garek non può più essere certo che i draghi resteranno imprigionati. Ora a Lethlor dimorano draghi neri e gli ogre hanno preso il Simbolo della Terra.",al={"perché uccidere blacklash","perché rompere la prigione","perché uccidere hematus"}},{q="Come viene aperta la prigione?",a="Usa il Simbolo della Terra sui Pilastri di Ametista, Opale e Diamante. Poi colloca le tre pietre runiche nel Sigillo della Terra.",al={"come aprire il sigillo della terra","come evocare blacklash","come far uscire i draghi"}},{q="Cosa deve essere riportato a Garek?",a="Porta a Garek i Bracciali di Codanera, le Catene di Hematus e il Simbolo della Terra.",al={"cosa restituire a garek","bracciali di codanera","catene di hematus"}},{q="Cosa precede questa missione?",a="Viene dopo un precedente Tremors of the Earth.",al={"missione precedente","requisito per tremors of the earth"}}},fp="20,175,16.194.0,17.353.0,14.179.1,30.63.0,58.140.0,27.129.0,35.82.0,29.43.0"}
P.entries["quest:718"] = {n="Mirages",s="Nelle Maleterre, il gruppo di Sigrun Tagliaferro è fuggito dagli scavi di Uldaman e ha fame.",h="Nelle Maleterre, il gruppo di Sigrun Tagliaferro è fuggito dagli scavi di Uldaman e ha fame.",kw={"maleterre","campo kosh","scavi","mirages","ogre","sigrun tagliaferro","cassa di rifornimenti","uldaman"},ang={["faction:Alliance"]="In quanto membro dell'Alleanza, puoi aiutare Sigrun Tagliaferro."},sec={{t="Affamati nelle Maleterre",b="Il gruppo di Sigrun è fuggito dagli scavi di Uldaman così in fretta da portare via ben poco. Ha lasciato indietro carri e casse di rifornimenti, che gli ogre di Campo Kosh hanno rovistato. Gli ogre hanno preso il carretto con tutte le armi del gruppo. Da allora il gruppo non ha avuto cibo. Sigrun ammette che la situazione è imbarazzante e ti chiede di recuperare la Cassa di Rifornimenti."},{t="Al tuo ritorno",b="Al tuo ritorno, Sigrun ammette di aver ingoiato una manciata di sabbia mentre eri via. La sera porta una prospettiva migliore. Stanotte il gruppo andrà in cerca di cibo e mangerà come dei re."}},faq={{q="Chi è Sigrun Tagliaferro?",a="Sigrun Tagliaferro è con un gruppo fuggito in fretta dagli scavi di Uldaman e ora senza cibo nelle Maleterre.",al={"sigrun tagliaferro","chi assegna mirages","chi è sigrun"}},{q="Perché il gruppo di Sigrun è affamato?",a="Gli ogre hanno preso il carretto con tutte le armi del gruppo. Da allora il gruppo di Sigrun non ha avuto cibo.",al={"perché sono affamati","perché niente cibo","problema cibo di sigrun"}},{q="Chi ha preso le provviste abbandonate?",a="Gli ogre di Campo Kosh hanno rovistato tra l'equipaggiamento lasciato indietro.",al={"chi ha rubato la cassa","ogre di campo kosh","chi ha preso le armi"}},{q="Cosa spera di recuperare Sigrun?",a="Sigrun spera di recuperare la Cassa di Rifornimenti lasciata indietro quando il gruppo è fuggito dagli scavi.",al={"cassa di rifornimenti","cosa recuperare per sigrun"}}},fp="7,88,22.360.0,14.186.1,22.116.0,31.97.0,32.73.0,34.94.0"}
P.entries["quest:719"] = {n="A Dwarf and His Tools",s="Il Prospettore Ryedol è scampato a un attacco al suo sito di scavo e ora cerca il suo piccone fortunato. I nani Ferroscuro simili al clan Forgiombra sono ovunque.",h="Il Prospettore Ryedol è scampato a un attacco al suo sito di scavo e ora cerca il suo piccone fortunato.",kw={"maleterre","ferroscuro","scavo","hammertoe","piccone fortunato","ryedol","forgiombra"},sec={{t="Incursori allo Scavo",b="I nani Ferroscuro simili al clan Forgiombra hanno attaccato il sito di scavo dove lavorava Ryedol. Quasi tutti sono morti, compreso il suo capo, Hammertoe. Ryedol è scampato per un soffio. Il sito si trova a nord del luogo in cui aspetta."},{t="Un Piccone Fortunato",b="Il Prospettore Ryedol cerca di recuperare le provviste perse durante l'attacco, soprattutto il suo piccone fortunato. Uno dei nani Ferroscuro ce l'ha, ma Ryedol non sa quale. Spera che tu lo aiuti e ti aspetta a sud dello Scavo di Hammertoe."}},faq={{q="Chi è il Prospettore Ryedol?",a="Il Prospettore Ryedol lavorava in un sito di scavo attaccato dai nani Ferroscuro. È scampato per un soffio e ora aspetta a sud dello Scavo di Hammertoe.",al={"chi è ryedol","prospettore ryedol","chi assegna a dwarf and his tools"}},{q="Chi ha attaccato l'accampamento di scavo?",a="I nani Ferroscuro simili al clan Forgiombra hanno attaccato il sito di scavo.",al={"chi ha attaccato lo scavo","chi ha attaccato hammertoe","cosa ha attaccato l'accampamento"}},{q="Che fine ha fatto Hammertoe?",a="Hammertoe era il capo di Ryedol ed è stato ucciso durante l'attacco.",al={"chi è hammertoe","hammertoe è vivo","cosa è successo al capo hammertoe"}},{q="Dove si trova il piccone fortunato?",a="Ryedol crede che uno dei nani Ferroscuro abbia il piccone fortunato, ma non sa quale.",al={"dov'è il piccone fortunato di ryedol","come trovare il piccone","chi ha il piccone di ryedol"}}},fp="21,147,18.228.0,12.234.0,25.140.0,33.79.0,27.69.0,32.99.0"}
P.entries["quest:72"] = {n="Leggenda di Stalvan",s="A Roccavento cerchi Stalvan Mistmantle tra gli averi dei Flintridge. Presso i Canali, casse sigillate custodiscono ciò che resta della famiglia, sorvegliate da spiriti inquieti legati al massacro.",h="A Roccavento cerchi Stalvan Mistmantle tra gli averi dei Flintridge.",kw={"canali","curato folsom","boscovespro","flintridge","spirito infausto","leggenda di stalvan","massacro","cassa sigillata","roccavento","tilloa"},ang={["class:Priest"]="Nel ruolo di sacerdote, affronti lo Spirito Infausto piangente nei Canali della città. Il suo tormento appartiene ad anime innocenti assassinate prima del tempo, e invoca la pace dalla Luce.",["faction:Alliance"]="La tragedia dei Flintridge si consuma a Roccavento, capitale del regno, dove la violenza può annientare anche le casate nobiliari più protette."},sec={{t="Echi di un massacro",b="Segui le tracce di Stalvan da Boscovespro a Roccavento. Accanto ai canali della città, il Curato Folsom sorveglia ciò che resta della famiglia Flintridge. Suo padre aveva servito la tenuta prima di lui e dovette ripulire il sangue dopo che un massacro sterminò la famiglia. In qualche modo, il nome di Stalvan è legato a quella carneficina."},{t="L'asta di una casata in rovina",b="I fondi fiduciari dei Flintridge sono esauriti e gli esattori delle tasse reali fanno pressione sulla tenuta. I cimeli sopravvissuti e gli averi imballati attendono l’asta in casse da spedizione sigillate, lungo l’argine del canale. Cerchi tra loro le tracce di Stalvan prima che i beni rimasti alla famiglia si disperdano tra i collezionisti del regno."},{t="Un'ombra inquieta",b="Uno Spirito Infausto attacca chiunque disturbi le casse dei Flintridge. Il trauma degli omicidi è rimasto aggrappato ai beni di famiglia recuperati. Molti credono che l’apparizione piangente sia lo spettro della giovane Tilloa Flintridge, ancora legata ai cimeli della vita che le è stata strappata."}},faq={{q="Dove posso trovare il Curato Folsom?",a="Il Curato Folsom sorveglia gli averi dei Flintridge accanto ai Canali di Roccavento, vicino a casse da spedizione impilate lungo il corso d’acqua.",al={"posizione del curato folsom","dov'è folsom","dov'è il curato folsom a roccavento"}},{q="Cosa è successo alla famiglia Flintridge?",a="Un improvviso massacro annientò la ricca famiglia Flintridge. Il Curato Folsom dice che suo padre dovette ripulire il sangue in seguito. Non è chiaro chi ne fosse responsabile.",al={"massacro dei flintridge","cos'è stato il massacro","chi ha ucciso la famiglia flintridge"}},{q="Perché gli averi della famiglia sono imballati in casse lungo il canale?",a="Dopo la tragedia, i fondi fiduciari dei Flintridge si esaurirono. Gli averi rimasti furono imballati in casse accanto ai canali, in attesa dell’asta, sotto la pressione degli esattori delle tasse del regno.",al={"perché mettere all'asta gli oggetti dei flintridge","perché ci sono delle casse nei canali","fondo fiduciario flintridge"}},{q="Perché uno spirito attacca quando la cassa viene aperta?",a="Il trauma del massacro legò le anime delle vittime ai loro averi di un tempo. Uno Spirito Infausto attacca per difendere le casse, e molti credono che sia lo spettro di Tilloa Flintridge, una dei bambini assassinati.",al={"spirito infausto roccavento","chi è lo spirito infausto","perché c'è un fantasma nei canali di roccavento"}},{q="Come si collega questo a Boscovespro?",a="L’indagine iniziò a Borgoscuro, con la ricerca di Stalvan Mistmantle. Ricostruire la sua storia ti condusse al periodo in cui fu precettore della famiglia Flintridge a Elwynn e a Roccavento.",al={"collegamento tra stalvan e boscovespro","perché siamo a roccavento per una missione di boscovespro","collegamento della leggenda di stalvan con la città"}},{q="Cosa si trova all'interno della cassa sigillata?",a="La cassa contiene cimeli ammuffiti, tra mobili imballati ed effetti personali. Quasi sul fondo trovi una pagina strappata dal diario di Stalvan: il prossimo indizio.",al={"cosa c'è nella cassa","indizio della cassa sigillata","contenuto delle casse dei flintridge"}}},fx={d6eccd2d={q="Perché il Curato Folsom ti lascia cercare nelle casse?",a="Al Curato Folsom è rimasto ben poco di cui occuparsi. Il fondo fiduciario della famiglia Flintridge si è esaurito del tutto, lasciando in rovina ciò che resta della proprietà e destinando gli ultimi averi alla casa d'aste per saldare le tasse. La sua famiglia ha servito la proprietà per generazioni — suo padre aveva ripulito il sangue dopo il raccapricciante massacro — ma Folsom non ha motivo di nascondere la triste verità e ti lascia semplicemente frugare tra ciò che ne resta.",al={"motivo del curato folsom","perché folsom aiuta","perché mi lascia cercare nelle casse"}}},fp="21,200,20.302.0,29.320.0,16.262.1,34.133.0,39.167.0,66.167.0,50.210.0,39.167.0,41.155.0"}
P.entries["quest:720"] = {n="A Sign of Hope",s="Grez Mazzadito è vivo, e una richiesta d'aiuto scritta col gesso su una mappa sgualcita chiama il Prospettore Ryedol in suo aiuto. Il messaggio dice che stanno portando Mazzadito a Uldaman.",h="Grez Mazzadito è vivo, e una richiesta d'aiuto scritta col gesso su una mappa sgualcita chiama il Prospettore...",kw={"a sign of hope","maleterre","messaggio di gesso","mappa sgualcita","grez mazzadito","prospettore ryedol","uldaman"},sec={{t="Parole nel Gesso",b="Mazzadito lascia una breve richiesta d'aiuto per Ryedol, scritta col gesso su una mappa sgualcita. Il messaggio dice che stanno portando Mazzadito a Uldaman e chiede aiuto. Di' al Prospettore Ryedol che Grez Mazzadito è vivo."}},faq={{q="Cosa c'è scritto sulla mappa sgualcita?",a="Il messaggio di Mazzadito, scritto col gesso, è indirizzato a Ryedol. Dice che stanno portando Mazzadito a Uldaman e chiede aiuto.",al={"cosa dice il messaggio","messaggio di gesso sulla mappa","testo della mappa sgualcita"}},{q="Chi è il Prospettore Ryedol?",a="Il messaggio è indirizzato al Prospettore Ryedol. Trovalo e digli che Grez Mazzadito è vivo.",al={"chi è ryedol","dove portare la mappa sgualcita"}},{q="Dove dice il messaggio che stanno portando Grez Mazzadito?",a="Il messaggio dice che stanno portando Grez Mazzadito a Uldaman.",al={"dove viene portato mazzadito","dove viene portato grez"}}},fp="14,141,14.188.0,36.110.0,25.97.0,57.58.0"}
P.entries["quest:723"] = {n="Prospect of Faith",s="Nelle Maleterre, Grez Mazzadito ti manda dal Prospettore Ryedol con il suo amuleto. Ryedol sa che Grez cercava le origini del loro popolo e vuole impedire al clan Forgiascura di impossessarsi delle pergamene.",h="Nelle Maleterre, Grez Mazzadito ti manda dal Prospettore Ryedol con il suo amuleto.",kw={"a sign of hope","maleterre","grez mazzadito","amuleto di mazzadito","origini","prospettore ryedol","forgiascura"},sec={{t="Un amuleto per Ryedol",b="Ferito nelle Maleterre, Grez Mazzadito ti chiede di portare il suo amuleto a Ryedol. Si fida che Ryedol sappia cosa fare. Grez cercava le origini del loro popolo e intendeva ostacolare il clan Forgiascura. Il clan non deve impossessarsi delle pergamene."},{t="Nelle mani di Ryedol",b="Quando Ryedol riceve l'Amuleto di Mazzadito, dice che il morale era più alto quando credeva che Grez fosse morto. Saperlo per certo non fa che accrescere il suo dolore. Ryedol definisce l'amuleto l'opera di una vita di Grez e giura che la sua morte non sarà vana."}},faq={{q="Chi è il Prospettore Ryedol?",a="Nelle Maleterre, devi portare l'amuleto di Grez Mazzadito al Prospettore Ryedol. Ryedol sa cosa stava cercando Grez.",al={"prospettore ryedol","chi è ryedol","dove si trova ryedol"}},{q="Cosa sta cercando di fermare Grez Mazzadito?",a="Grez intendeva ostacolare il clan Forgiascura, che non deve riuscire a impossessarsi delle pergamene.",al={"scopo di mazzadito","pergamene forgiascura","perché fermare i forgiascura"}},{q="Cosa stava cercando Grez Mazzadito?",a="Grez cercava le origini del loro popolo.",al={"origini di mazzadito","cosa cercava mazzadito"}},{q="Di quale catena fa parte questa fase?",a="Questo passaggio fa parte della catena iniziata con A Sign of Hope.",al={"catena prospect of faith","catena a sign of hope"}}},fp="17,194,20.238.0,17.232.1,25.121.0,38.87.0,32.50.0,33.62.0"}
P.entries["quest:724"] = {n="Prospect of Faith",s="Nelle Maleterre, il Prospettore Ryedol ti manda a Forgiardente con l'Amuleto di Mazzadito. Karnik lo Storico e Mazzadito cercarono insieme i manufatti perduti di Uldaman. Ryedol sospetta che i Forgiardombra abbiano scoperto che loro sapevano più di quanto lasciassero intendere.",h="Nelle Maleterre, il Prospettore Ryedol ti manda a Forgiardente con l'Amuleto di Mazzadito.",kw={"maleterre","mazzadito","amuleto di mazzadito","karnik lo storico","forgiardente","prospect of faith","prospettore ryedol","forgiardombra","uldaman"},sec={{t="Un messaggio per Forgiardente",b="Il Prospettore Ryedol ti manda da Karnik lo Storico, a Forgiardente. Racconta a Karnik cos'è successo a Mazzadito e mettigli l'amuleto in mano. Sarà Karnik a decidere cosa fare dopo."},{t="Il benvenuto di Karnik",b="Karnik lo Storico non ascolterà il racconto di un altro viaggiatore finché non vedrà l'amuleto. Poi mette da parte il lutto per Mazzadito ed evoca il suo spirito per mostrarti il valore dell'amuleto."}},faq={{q="Chi inizia questa missione?",a="Il Prospettore Ryedol, nelle Maleterre, ti manda a Forgiardente con l'Amuleto di Mazzadito.",al={"chi fornisce prospect of faith","datore della missione prospect of faith","dove iniziare prospect of faith"}},{q="Dove si trova Karnik lo Storico?",a="Karnik lo Storico si trova a Forgiardente.",al={"dove si trova karnik","posizione di karnik lo storico","karnik forgiardente"}},{q="Perché è stato scelto Karnik lo Storico?",a="Karnik e Mazzadito cercarono insieme i manufatti perduti di Uldaman, perciò Ryedol si fida che Karnik sappia cosa fare dopo.",al={"perché inviare l'amuleto a karnik","collegamento di karnik"}},{q="Cosa segue questa missione?",a="La storia di Karnik continua con Passing Word of a Threat.",al={"prossima missione dopo prospect of faith","cosa segue prospect of faith"}}},fp="17,228,23.171.0,16.190.1,22.81.0,34.33.0,32.111.0,28.55.0"}
P.entries["quest:725"] = {n="Passing Word of a Threat",s="Karnik lo Storico ti manda dal Consigliere Belgrum con un Messaggio Sigillato. Racconta a Belgrum ciò a cui hai assistito e chiedi come procedere, mentre Karnik cerca risposte dallo spirito di Mazzadito.",h="Karnik lo Storico ti manda dal Consigliere Belgrum con un Messaggio Sigillato.",kw={"consigliere belgrum","maleterre","mazzadito","karnik lo storico","forgiardente","passing word of a threat","ferroscuro"},sec={{t="Parola per il Consigliere Belgrum",b="Karnik lo Storico ha bisogno che tu raggiunga in fretta il Consigliere Belgrum. Digli ciò a cui hai assistito e chiedigli come intende procedere. Il Messaggio Sigillato spiega di più.\n\nNel frattempo, Karnik parla con lo spirito di Mazzadito, sperando di scoprire come porre fine alle azioni dei Ferroscuro nelle Maleterre. Può solo pregare che Mazzadito sappia qualcosa che possa essere d'aiuto."}},faq={{q="Chi ti manda dal Consigliere Belgrum?",a="Karnik lo Storico ti consegna un Messaggio Sigillato e ti chiede di trovare il Consigliere Belgrum il prima possibile.",al={"chi inizia passing word of a threat","chi dà passing word of a threat","missione di karnik"}},{q="Cosa vuole Karnik dal Consigliere Belgrum?",a="Karnik vuole che tu racconti a Belgrum ciò a cui hai assistito e gli chieda come intende procedere. Il messaggio spiega di più.",al={"perché visitare belgrum","scopo del messaggio per belgrum","perché inviare il messaggio"}},{q="Cosa sta facendo Karnik lo Storico mentre consegni il messaggio?",a="Mentre consegni il Messaggio Sigillato, Karnik parla con lo spirito di Mazzadito, sperando di scoprire come fermare i Ferroscuro nelle Maleterre.",al={"cosa fa karnik","piano di karnik","karnik lo storico maleterre"}},{q="Quale missione precede Passing Word of a Threat?",a="Passing Word of a Threat segue Prospect of Faith, quando porti l'Amuleto di Mazzadito a Karnik a Forgiardente.",al={"prerequisito di passing word","missione precedente di passing word of a threat","missione precedente"}}},fp="24,162,24.336.0,33.100.0,43.108.0,58.124.0,49.109.0"}
P.entries["quest:726"] = {n="Passing Word of a Threat",s="Nelle Maleterre, il Consigliere Belgrum ti rimanda da Karnik con l'ordine del re di agire in fretta contro gli Shadowforge.",h="Nelle Maleterre, il Consigliere Belgrum ti rimanda da Karnik con l'ordine del re di agire in fretta contro...",kw={"fortezza di angor","maleterre","belgrum","karnik","shadowforge","uldaman"},sec={{t="La risposta di Belgrum",b="Belgrum legge fino in fondo il messaggio di Karnik. Gli occhi gli si spalancano davanti a quelle notizie funeste. Ti rimanda da Karnik con l'ordine del re: agire in fretta e con decisione sulla base di ciò che si sa. Le attività degli Shadowforge nelle Maleterre devono cessare."},{t="La replica di Karnik",b="Karnik prende l'urgenza come un ordine diretto del re e ha già un piano. Gli Shadowforge operano dalla Fortezza di Angor. Un colpo lì può rallentare le loro attività a Uldaman."}},faq={{q="Chi ti rimanda da Karnik?",a="Dopo aver letto il messaggio di Karnik, il Consigliere Belgrum ti rimanda indietro. Porti l'ordine del re di agire in fretta e con decisione.",al={"chi impartisce l'ordine","ordini di belgrum","autorità reale maleterre"}},{q="Cosa vuole Belgrum che venga fatto riguardo ai Shadowforge?",a="Belgrum vuole che Karnik agisca in fretta e con fermezza per porre fine alle attività degli Shadowforge nelle Maleterre.",al={"cosa vuole belgrum","ordine degli shadowforge maleterre"}},{q="Cosa è successo prima?",a="Hai portato il Messaggio Sigillato di Karnik al Consigliere Belgrum nella precedente missione Passing Word of a Threat, dopo gli incarichi di Prospect of Faith.",al={"fase precedente","missione prima di passing word of a threat","antefatto delle maleterre"}}},fp="24,113,16.229.0,14.154.1,29.119.0,50.99.0,22.127.0"}
P.entries["quest:727"] = {n="To Ironforge for Yagyin's Digest",s="Theldurin il Perduto ti manda a Forgiardente con un sigillo. In un negozio nella Caverna degli Inganni, Gerrig Morsaossa dovrebbe scambiarti per uno di coloro da cui Theldurin è fuggito, così potrai chiedergli il Compendio di Yagyin.",h="Theldurin il Perduto ti manda a Forgiardente con un sigillo.",kw={"maleterre","caverna degli inganni","gerrig morsaossa","forgiardente","sigillo del martello","theldurin il perduto","compendio di yagyin"},sec={{t="Un libro scritto molto tempo fa",b="La Tavoletta ha insegnato molto a Theldurin, ma restano delle domande. Yagyin scrisse un compendio molto tempo fa, e coloro da cui Theldurin è fuggito ne conservano copie in molti luoghi. I più sapienti lo studiano. Theldurin crede che le sue vaste conoscenze possano offrire protezione, perciò vuole che tu lo riporti."},{t="Il negozio nella Caverna degli Inganni",b="Gerrig Morsaossa ha un negozio nella Caverna degli Inganni di Forgiardente. Theldurin ti dà il Sigillo del Martello da mostrare a Gerrig. Così Gerrig dovrebbe scambiarti per uno di coloro da cui Theldurin è fuggito. Chiedigli il Compendio di Yagyin."},{t="Il saluto di Gerrig",b="Gerrig Morsaossa ti avverte di fare attenzione a ciò che tocchi nel negozio. La conoscenza può essere letale. Quando mostri il sigillo, Gerrig ti saluta come fratello o sorella e loda gli abitanti del sottosuolo."}},faq={{q="Perché Theldurin vuole il Compendio di Yagyin?",a="La Tavoletta ha insegnato molto a Theldurin, ma lascia ancora domande senza risposta. Il compendio di Yagyin, scritto molto tempo fa, custodisce vaste conoscenze che possono offrire protezione. Theldurin vuole che tu lo riporti.",al={"perché serve il compendio di yagyin","cos'è il compendio di yagyin","scopo compendio di yagyin"}},{q="Dov'è Gerrig Morsaossa?",a="Nella Caverna degli Inganni di Forgiardente, dove ha un negozio.",al={"dov'è gerrig morsaossa","posizione gerrig morsaossa","chi è gerrig"}},{q="A cosa serve il Sigillo del Martello?",a="Theldurin ti dà il Sigillo del Martello da mostrare a Gerrig Morsaossa. Vuole che Gerrig ti scambi per uno di coloro da cui Theldurin è fuggito.",al={"cosa fa il sigillo","uso sigillo del martello","perché usare il sigillo"}},{q="Dove si colloca questa missione nella catena?",a="Segue Solution to Doom con Theldurin il Perduto. La catena continua con The Next Step.",al={"cosa c'è prima di a forgiardente per il compendio di yagyin","ordine catena yagyin"}}},fp="32,203,23.272.0,30.214.0,17.185.1,40.186.0,25.53.0,41.134.0,33.92.0"}
P.entries["quest:728"] = {n="To the Undercity for Yagyin's Digest",s="Theldurin il Perduto ti manda nella Sepulcra di Lordaeron con un sigillo per il Protettore Bel'dugur. Vuole che il protettore ti scambi per uno dei suoi fuggitivi e ti chiede di trovare il Compendio di Yagyin.",h="Theldurin il Perduto ti manda nella Sepulcra di Lordaeron con un sigillo per il Protettore Bel'dugur.",kw={"maleterre","bel'dugur","compendio","martello","sigillo","theldurin","sepulcra","yagyin"},sec={{t="Un libro scritto molto tempo fa",b="La tavoletta ha risposto a molte domande di Theldurin, ma ne restano ancora. Yagyin scrisse un compendio ere fa, e i fuggitivi di Theldurin ne conservano copie in molti luoghi. I più istruiti studiano le sue pagine. Theldurin crede che la sua vasta conoscenza possa proteggerli, perciò vuole che tu lo riporti."},{t="Il protettore nella Sepulcra",b="Il Protettore Bel'dugur ti aspetta nella Sepulcra di Lordaeron. Theldurin ti dà il Sigillo del Martello da mostrare al protettore, che dovrà scambiarti per uno dei suoi fuggitivi. Chiedi a Bel'dugur il compendio."},{t="Una parola di cautela",b="Il Protettore Bel'dugur ti accoglie come un entusiasta cercatore nella collezione. Il protettore ti avverte che la conoscenza dà potere ai forti, ma fa impazzire i deboli. Dopo che gli mostri il sigillo, Bel'dugur ti esorta a essere discreto con segni simili. Alcuni dubitano che il loro giuramento sia giusto, mentre altri vorrebbero vederli fallire, se ne venissero a conoscenza. Chi condivide il giuramento deve essere prudente, vigile e paziente."}},faq={{q="Chi ti manda alla Sepulcra?",a="Theldurin il Perduto ti manda a cercare il Protettore Bel'dugur e ti dà il Sigillo del Martello da portare con te.",al={"chi inizia questa missione","chi manda alla sepulcra per il compendio di yagyin","datore di missione"}},{q="A cosa serve il Sigillo del Martello?",a="Theldurin ti dà il Sigillo del Martello da mostrare al Protettore Bel'dugur, perché il protettore ti scambi per uno dei fuggitivi di Theldurin.",al={"uso del sigillo del martello","perché mi serve il sigillo","cosa fa il sigillo"}},{q="Cos'è il Compendio di Yagyin?",a="Il Compendio di Yagyin è un libro scritto da Yagyin ere fa. Theldurin dice che custodisce una vasta conoscenza, studiata dai più istruiti tra i suoi fuggitivi.",al={"cos'è il compendio di yagyin","chi è yagyin","libro di yagyin"}},{q="Dov'è il Protettore Bel'dugur?",a="Il Protettore Bel'dugur si trova nella Sepulcra di Lordaeron.",al={"posizione protettore bel'dugur","dove trovare il protettore beldugur","bel'dugur sepulcra"}},{q="Cosa è successo prima di questo?",a="Solution to Doom è venuta prima di questa.",al={"missione precedente","cosa viene prima di questo","connessione con soluzione al destino"}}},fp="36,197,23.281.0,27.197.0,17.375.1,31.101.0,36.135.0,24.142.0,26.50.0,22.34.0"}
P.entries["quest:729"] = {n="The Absent Minded Prospector",s="Nel sud di Rivafosca, golem di pietra ostili hanno invaso un sito di scavo e Archaeologist Hollee cerca aiuto ad Auberdine. Teme per Prospettore Errasogni, il suo collega più esperto, che spesso si lascia accecare dalle ricerche davanti al pericolo mortale.",h="Nel sud di Rivafosca, golem di pietra ostili hanno invaso un sito di scavo e Archaeologist Hollee cerca aiuto...",kw={"auberdine","rivafosca","lega degli esploratori","fossile","golem","greywhisker","hollee","errasogni"},ang={["faction:Alliance"]="Da viaggiatore dell'Alleanza, vedi i ricercatori di Forgiardente studiare le terre antiche e sconosciute dei loro alleati Elfi della Notte a Kalimdor.",["race:Dwarf"]="Da nano, vedi all'opera la curiosità ossessiva di Errasogni: rischia la vita per un fossile non catalogato."},sec={{t="Uno Scavo Pericoloso",b="Archaeologist Hollee attraversò il mare con la Lega degli Esploratori. Il Maestro Greywhisker la mandò a fare da apprendista a Prospettore Errasogni, le cui scoperte lo avevano reso celebre negli ambienti accademici di Forgiardente. La Lega li inviò a studiare antiche rovine lungo la costa selvaggia di Rivafosca. Mentre scavavano in quelli che sembravano i resti di una grande civiltà, golem di pietra violenti irruppero dal terreno e invasero il sito."},{t="All'oscuro del Destino",b="Nel panico, Hollee fuggì nella notte fino ad Auberdine, il porto degli Elfi della Notte, per chiedere aiuto. Errasogni notò a malapena il pericolo. Assorbito dalle sue reliquie, l'anziano prospettore rimase tra le macerie mentre golem barcollanti circondavano il suo accampamento. A sud di Auberdine, chiunque lo raggiunga lo trova a brontolare per pennelli di pietra mancanti e fossili fuori posto."}},faq={{q="Chi è il Prospettore Errasogni?",a="Prospettore Errasogni è un celebre ricercatore nano della Lega degli Esploratori di Forgiardente. Le sue scoperte lo hanno reso famoso negli ambienti accademici dei nani, ma le reliquie preziose possono renderlo cieco ai pericoli vicini.",al={"errasogni","storia del prospettore errasogni","chi è il prospettore"}},{q="Perché l'Archaeologist Hollee è ad Auberdine?",a="Il Maestro Greywhisker assegnò Hollee a Errasogni come assistente. Quando golem pericolosi si levarono dal sito di scavo, lei fuggì in preda al panico verso nord, ad Auberdine, per chiedere aiuto e organizzare un salvataggio.",al={"archaeologist hollee","hollee auberdine","perché hollee è scappata"}},{q="Cosa stavano scavando i nani a Rivafosca?",a="I nani stavano scavando in quelli che sembravano i resti di una grande civiltà antica sotto Rivafosca. Prima che i golem invadessero il sito, Errasogni aveva portato alla luce un Fossile Misterioso e alcuni manufatti di pietra.",al={"cosa stava scavando errasogni","sito di scavo di rivafosca","fossile di errasogni"}},{q="Dove si può trovare il Prospettore Errasogni?",a="Prospettore Errasogni si trova nel sito di scavo nel sud di Rivafosca, tra antiche rovine a sud di Auberdine. Golem pericolosi circondano il suo accampamento mentre cerca il suo pennello di pietra e il fossile.",al={"dov'è errasogni","posizione di errasogni","trovare il prospettore errasogni"}},{q="Chi ha mandato questa spedizione a Rivafosca?",a="La Lega degli Esploratori mandò la spedizione da Forgiardente, per ordine del Maestro Greywhisker. Greywhisker assegnò Hollee come apprendista di Errasogni, perché studiasse le antiche rovine di Rivafosca.",al={"chi ha mandato hollee","maestro greywhisker","lega degli esploratori a rivafosca"}},{q="Errasogni è in pericolo reale?",a="Sì. Golem ostili si aggirano tra le rovine attorno a Errasogni, ma lui è cieco al pericolo. È concentrato sul catalogo dei suoi ritrovamenti e si chiede dove siano finiti i suoi attrezzi e la sua assistente.",al={"errasogni è morto","errasogni vivo","aiutare errasogni"}}},fx={["90475777"]={q="Perché Archaeologist Hollee vuole che venga fatto?",a="Hollee era entusiasta di studiare sotto la guida del Prospettore Errasogni, un celebre ricercatore della Lega degli Esploratori di Forgiardente. Tuttavia, quando dei golem ostili sono emersi dal sito di scavo, la profonda distrazione di Errasogni gli ha impedito di accorgersi del pericolo. Hollee è fuggita ad Auberdine per chiedere rinforzi, terrorizzata all'idea che il suo mentore venga ucciso se qualcuno non lo tira fuori dalle rovine.",al={"perché hollee ha bisogno di aiuto","motivo di hollee","perché cercare errasogni"}},["1b9bcac6"]={q="Perché Hollee ti chiede di controllare come sta Errasogni invece di andare lei stessa?",a="Hollee è a malapena riuscita a fuggire viva dal sito di scavo quando sono apparsi i golem di pietra. Terrorizzata e priva delle capacità marziali necessarie per affrontare da sola quei costrutti ostili, deve restare al sicuro ad Auberdine e affidarsi ad avventurieri di passaggio capaci, perché tornino nella mischia e controllino come sta il suo mentore.",al={"perché hollee manda me","perché hollee non torna indietro","perché auberdine non aiuta"}}},fp="28,221,14.427.0,17.354.0,28.215.0,41.166.0,46.205.0,40.191.0,38.186.0,30.178.0"}
P.entries["quest:730"] = {n="Trouble in Darkshore?",s="Trouble in Darkshore? è una missione introduttiva dell'Alleanza offerta dal Capo Archeologo Baffogrigio a Darnassus. Preoccupato dopo settimane di silenzio da parte di una squadra di scavo inviata oltre il mare, chiede ai viaggiatori di recarsi ad Auberdine per indagare sulla loro scomparsa. Fa da ponte tra la spedizione accademica nanica e la costa selvaggia e tenebrosa di Darkshore.",h="Trouble in Darkshore?",kw={"archeologo","auberdine","darkshore","darnassus","lega degli esploratori","baffogrigio","hollee","trouble in darkshore"},ang={["faction:Alliance"]="Questo compito dimostra la crescente cooperazione tra Forgiardente e Darnassus, collegando i viaggiatori tra Teldrassil e il continente di Kalimdor.",["race:Dwarf"]="Per i nani, questa missione tocca la tradizione della Lega degli Esploratori di scavare nella tradizione dei titani e nella storia antica attraverso nuovi continenti.",["race:NightElf"]="Gli elfi della notte potrebbero guardare all'arrivo dei nani scavatori armati di piccone nelle loro ancestrali rovine costiere con cauto divertimento o silenziosa preoccupazione."},sec={{t="Una spedizione silenziosa",b="Nella grandiosa capitale degli elfi della notte, Darnassus, i ricercatori nanici di Forgiardente perseguono gli antichi misteri di Kalimdor. Il Capo Archeologo Baffogrigio ha inviato una squadra di scavo oltre l'acqua, verso Darkshore, per dissotterrare manufatti dell'antichità. Quando passano settimane senza un solo messaggio o rapporto sui progressi, Baffogrigio diventa ansioso, temendo che la sua squadra sul campo abbia incontrato pericoli che non erano attrezzati per affrontare da soli."},{t="Minacce dissepolte",b="Baffogrigio lamenta che molti nell'Alleanza liquidano l'archeologia nanica come poco più di un hobby eccentrico. Tuttavia, i ritrovamenti a Khaz Modan hanno convinto i suoi colleghi che un'antica e terrificante forza minaccia Azeroth, estendendosi da Lordaeron a Kalimdor. Scavare tra le rovine di Darkshore non è solo un'impresa accademica: è uno sforzo per comprendere i cataclismi storici e le minacce profonde sepolte sotto l'antico suolo."},{t="Contatto ad Auberdine",b="Dopo aver attraversato il canale navigando da Teldrassil verso il rifugio costiero di Auberdine, i viaggiatori trovano l'Archaeologist Hollee ad attenderli in città. Sollievata dal fatto che il Capo Archeologo abbia inviato assistenza, Hollee rivela che la spedizione è effettivamente in gravi difficoltà, essendo incappata in guai più a sud lungo la costa mentre cercava antiche reliquie."}},faq={{q="Chi inizia la missione Trouble in Darkshore?",a="Il Capo Archeologo Baffogrigio offre la missione nella capitale degli elfi della notte, Darnassus, cercando coraggiosi avventurieri disposti a controllare la sua squadra dispersa.",al={"chi fornisce trouble in darkshore","donatore missione trouble in darkshore","dove prendere trouble in darkshore"}},{q="Dove devo andare per completare questa missione?",a="Devi viaggiare da Darnassus oltre il mare fino alla città portuale di Auberdine a Darkshore, dove troverai l'Archaeologist Hollee.",al={"dove devo andare","luogo di consegna","a chi devo consegnare"}},{q="Perché ci sono archeologi nanici a Darnassus e Darkshore?",a="A seguito di recenti scoperte a Khaz Modan, i ricercatori nanici hanno iniziato a indagare su siti antichi in tutta Kalimdor per scoprire indizi su forze antiche che minacciano Azeroth.",al={"perché i nani a darnassus","nani a darkshore","archeologia nanica kalimdor"}},{q="Cosa succede dopo aver trovato l'Archaeologist Hollee?",a="Parlare con l'Archaeologist Hollee ad Auberdine porta direttamente a 'The Absent Minded Prospector', chiedendoti di avventurarti nella natura selvaggia di Darkshore per localizzare il Prospettore Errasogni.",al={"what comes next","missione successiva","prossima missione"}},{q="Perché la squadra di scavo non ha fatto rapporto?",a="La squadra ha incontrato pericoli imprevisti e contrattempi sul campo a Darkshore, lasciando i singoli membri separati e impossibilitati a comunicare con Darnassus.",al={"cosa è successo allo scavo","perché sono scomparsi","squadra dispersa"}},{q="A quale minaccia incombente si riferisce Baffogrigio?",a="Baffogrigio fa riferimento a scoperte portate alla luce a Khaz Modan che suggeriscono un'antica e pervasiva minaccia che dorme nel profondo delle rovine storiche di Azeroth.",al={"quale antica minaccia","avvertimento di baffogrigio","minaccia di khaz modan"}}},fx={["0c1ca2fe"]={q="Perché il Capo Archeologo Baffogrigio vuole che venga fatto?",a="Il Capo Archeologo Baffogrigio non riceve notizie da settimane dalla sua squadra di scavo a Rivafosca. Dopo le inquietanti scoperte fatte a Khaz Modan, che rivelano una grande e antica forza capace di minacciare tutta Azeroth, non può permettersi di perdere i contatti con i suoi ricercatori, soprattutto perché il loro lavoro è fondamentale per svelare i pericoli incombenti.",al={"motivo di baffogrigio","perché mandare a rivafosca","perché trovare la squadra di scavo"}}},fp="21,355,19.426.0,16.439.0,20.335.1,42.153.0,45.134.0,58.172.0,48.181.0,45.167.0,48.149.0"}
P.entries["quest:731"] = {n="The Absent Minded Prospector",s="Tra le rovine meridionali di Rivafosca, il Prospettore Errasogni continua gli scavi, sperando di trovare un tesoro per la Lega degli Esploratori. I trogg ostili e la sua smemoratezza rendono pericolosa la ricerca, e bisogna far sapere alla sua assistente ad Auberdine che è al sicuro.",h="Tra le rovine meridionali di Rivafosca, il Prospettore Errasogni continua gli scavi, sperando di trovare un...",kw={"auberdine","rivafosca","scorta","scavo","lega degli esploratori","fossile","hollee","errasogni","trogg"},ang={["faction:Alliance"]="Come membro dell'Alleanza, aiutare Errasogni e preservare i suoi ritrovamenti sostiene i legami accademici e diplomatici tra la Lega degli Esploratori dei nani e gli Elfi della Notte di Teldrassil.",["race:Dwarf"]="Per i nani, Errasogni incarna la passione ardente e la testardaggine della Lega degli Esploratori. La sua dedizione al sapere sui titani dell'antichità gli impedisce di vedere il pericolo che lo circonda.",["race:NightElf"]="Per te, Elfo della Notte, gli scavi dei nani a Rivafosca potrebbero confermare la diffidenza della tua gente: gli scavi di Errasogni hanno portato alla luce un'orda di violenti trogg sotto un terreno sacro."},sec={{t="Uno scavo pericoloso",b="Molto a sud di Rivafosca, lo Scavo di Errasogni si trova tra antiche rovine. Gli scavatori nani che lavoravano lì hanno dissotterrato dei trogg, che hanno scacciato i lavoratori e assediato il campo. Errasogni non vuole tornare ad Auberdine a mani vuote. Si avventura nel pericolo per recuperare un fossile, sperando di giustificare i costi della spedizione alla Lega degli Esploratori."},{t="Ricordi confusi e imboscate di trogg",b="Tenere Errasogni al sicuro durante gli scavi è pericoloso e frustrante. Gira in tondo per il sito, scambia le spazzole per fossili e inciampa tra impalcature e tende abbandonate. A ogni sosta, trogg aggressivi sbucano dagli oscuri recessi della cava. Dopo che i viaggiatori hanno respinto ondate di bruti sotterranei, Errasogni ricorda dov'è il suo premio: ha già dato il fossile ad Archaeologist Hollee. Poi torna felice al lavoro."}},faq={{q="Chi è il Prospettore Errasogni?",a="Il Prospettore Errasogni è un ricercatore sul campo esperto della Lega degli Esploratori, composta da nani. Di stanza a Rivafosca, è stato inviato a scavare tra antiche rovine costiere, ma la sua estrema smemoratezza mette spesso in pericolo la sua vita.",al={"errasogni","chi è il prospettore","prospettore sbadato"}},{q="Perché Errasogni è ancora nel sito di scavo?",a="Errasogni si rifiuta di tornare a Darnassus senza prove concrete del suo lavoro. Prima di abbandonare il campo, vuole recuperare un Fossile Misterioso da presentare alla Lega degli Esploratori.",al={"perché restare allo scavo","perché errasogni è lì","perché non è fuggito"}},{q="Da dove vengono i trogg?",a="La squadra di Errasogni ha scavato in profondità e raggiunto sacche sotterranee abitate dai trogg. Quelle creature primitive sono sbucate in superficie e hanno sopraffatto macchinari, tende e lavoratori.",al={"perché ci sono trogg a rivafosca","trogg di rivafosca","trogg del sito di scavo"}},{q="Chi è Archaeologist Hollee?",a="Archaeologist Hollee è collega e assistente di Errasogni ad Auberdine. Angosciata per la lunga assenza del suo mentore e abituata alla sua smemoratezza, chiede ai viaggiatori di trovarlo e assicurarsi che torni sano e salvo.",al={"hollee","archaeologist hollee","assistente di errasogni"}},{q="Cosa succede dopo aver trovato il fossile?",a="Dopo aver aiutato Errasogni a cercare nello scavo, riferisci della sua incolumità ad Archaeologist Hollee ad Auberdine.",al={"continuazione missione","cosa fare dopo","dopo la scorta a errasogni"}}},fx={["6ea255c4"]={q="Perché il Prospettore Errasogni vuole trovare il fossile?",a="Errasogni è sotto pressione da parte della sezione della Lega degli Esploratori a Darnassus, che vuole la prova che abbia fatto progressi concreti nel sito di scavo. Anche se è terribilmente confuso e smemorato, sa di dover mostrare risultati tangibili — in particolare il Fossile Misterioso e i suoi appunti — per giustificare la spedizione e soddisfare i suoi superiori.",al={"motivo di errasogni","perché cercare il fossile","perché errasogni cerca il fossile"}},["4634f683"]={q="Perché Errasogni ha bisogno del tuo aiuto per perlustrare lo scavo?",a="Il sito di scavo è stato invaso da trogg ostili e Errasogni è un ricercatore distratto, non un guerriero esperto. È completamente concentrato sul recupero dei suoi artefatti e dei suoi appunti perduti, perciò è del tutto vulnerabile alle imboscate mentre vaga per lo scavo senza qualcuno armato che gli guardi le spalle.",al={"perché errasogni ha bisogno di una scorta","perché errasogni ha bisogno di protezione","perché errasogni non cerca da solo"}}},fp="28,251,21.333.0,35.415.1,28.223.0,39.180.0,31.175.0,28.213.0,38.98.1"}
P.entries["quest:732"] = {n="Tremors of the Earth",s="Garek ti chiede aiuto dopo aver saputo da Sigrun tutto ciò che hai fatto per lei. Il suo maestro, Krasus del Kirin Tor, l'ha mandato nelle Maleterre per fermare i guai che si stanno preparando nella Piana di Lethlor. Per prima cosa, gli serve il Simbolo della Terra rubato.",h="Garek ti chiede aiuto dopo aver saputo da Sigrun tutto ciò che hai fatto per lei.",kw={"fortezza di angor","campo boff","ferroscuro","alamorte","garek","kirin tor","krasus","piana di lethlor","simbolo della terra"},sec={{t="Una questione riservata",b="Krasus del Kirin Tor ha mandato Garek nelle Maleterre per fermare i guai che si stanno preparando nella Piana di Lethlor. Garek non può dirti quale sia l'incarico preciso, soltanto che è molto importante. Gli ogre vagabondi hanno preso il Simbolo della Terra, e Garek ha bisogno che tu lo recuperi prima di poterti dire altro. A volte vengono avvistati nei pressi di Campo Boff."},{t="Gli ogre erranti",b="Gli ogre vagano da un accampamento all'altro attraverso le Maleterre. Il caldo crescente e i venti vorticosi rendono difficile seguirne le tracce. Garek ha sentito dire che a volte passano per Campo Boff, quindi cerca lì se li perdi di vista."},{t="Le spiegazioni di Garek",b="Quando torni con il Simbolo, Garek ti dice che i nani Ferroscuro della Fortezza di Angor lo crearono per vincolare i luogotenenti gemelli di Alamorte, gli spietati Blacklash e Hematus."}},faq={{q="Per chi lavora Garek?",a="Krasus del Kirin Tor è il maestro di Garek. Ha mandato Garek nelle Maleterre per fermare i guai che si stanno preparando nella Piana di Lethlor.",al={"chi ha mandato garek","maestro di garek","krasus maleterre"}},{q="Cos'è il Simbolo della Terra?",a="Gli ogre vagabondi hanno rubato il Simbolo della Terra, e Garek ha bisogno che tu lo recuperi prima di dirti altro.",al={"simbolo della terra","cos'è il simbolo della terra","storia del simbolo della terra"}},{q="Dove si possono trovare gli ogre vagabondi?",a="Gli ogre vagano da un accampamento all'altro attraverso le Maleterre. Garek ha sentito dire che a volte passano per Campo Boff.",al={"dove sono gli ogre","ogre campo boff","dove si trova il simbolo della terra"}},{q="Perché Garek mantiene segreto l'incarico?",a="Garek non vuole rivelarti l'incarico né cosa comporti. Dice soltanto che è molto importante.",al={"perché è segreto","incarico segreto di garek"}}},fp="20,219,19.300.0,19.211.0,14.168.1,25.115.0,30.98.0,39.104.0,42.100.0"}
P.entries["quest:7321"] = {n="Zuppa Cremosa di Tartaruga",s="A Mulino di Tarren, Christoph Jeffcoat spera che Soothing Turtle Bisque dimostri che i Reietti sanno cucinare con cura. Gli servono mascazzanna dalle acque di Colletorto e dalle rive del Lago Lordamere.",h="A Mulino di Tarren, Christoph Jeffcoat spera che Soothing Turtle Bisque dimostri che i Reietti sanno cucinare...",kw={"christoph jeffcoat","cucina","alture di colletorto","lago lordamere","mascazzanna","soothing turtle bisque","mulino di tarren","carne di tartaruga"},ang={["faction:Horde"]="Come membro dell'Orda, aiuti a mantenere salde le provviste e il morale di Mulino di Tarren mentre difendi i suoi confini.",["profession:Cooking"]="Come cuoco, puoi imparare a preparare Soothing Turtle Bisque con i mascazzanna del Lago Lordamere e dei fiumi di Colletorto.",["race:Undead"]="Da non morto, puoi vedere che la morte non ha smorzato la passione di Christoph Jeffcoat per la cucina."},sec={{t="Gastronomia dei Reietti",b="Molti credono che i Reietti abbiano rinunciato alle comodità della vita, compresa la buona cucina. Christoph Jeffcoat, a Mulino di Tarren, la pensa diversamente. Vanta che la sua ricca zuppa di tartaruga potrebbe tentare le anime a tornare dall'oltretomba. Cucinando con cura, vuole dimostrare che mani non morte possono ancora preparare un piatto caldo in una terra segnata dalla piaga e dalla guerra."},{t="A caccia di mascazzanna",b="Un tempo Jeffcoat raccoglieva ingredienti nelle acque di Colletorto e sulle rive orientali del Lago Lordamere, nella vicina Alterac. Ora i suoi doveri a Mulino di Tarren e le vicine forze dell'Alleanza gli impediscono di andare a caccia. Perciò si affida ai cuochi dell'Orda di passaggio, che cacciano i mascazzanna e gli portano la carne. Il loro aiuto mantiene viva la sua ricetta."}},faq={{q="Perché un cuoco Reietto si preoccupa di preparare una zuppa calda?",a="I Reietti hanno meno bisogno di cibo dei mortali viventi, ma Christoph Jeffcoat è fiero della sua arte. Vuole dimostrare che i non morti sanno cucinare con maestria e scherza dicendo che il suo brodo potrebbe riportare in vita i morti.",al={"cucina dei non morti","perché preparare la bisque","i non morti mangiano cibo"}},{q="Dove si può trovare carne di tartaruga per questa ricetta?",a="La carne di mascazzanna si ricava dalle tartarughe aggressive che vivono lungo i fiumi delle Alture di Colletorto, ad Alterac, e sulle rive del Lago Lordamere.",al={"dove sono le tartarughe","posizioni delle tartarughe","posizioni dei mascazzanna"}},{q="Perché Christoph Jeffcoat non può raccogliere da solo gli ingredienti?",a="I doveri di Jeffcoat a Mulino di Tarren lo tengono occupato, mentre le vicine forze dell'Alleanza rendono più pericolose le sue battute di caccia.",al={"perché christoph non va","jeffcoat bloccato in città"}},{q="È necessaria la conoscenza della cucina per accettare questa missione?",a="Sì. Christoph Jeffcoat condivide la sua ricetta solo con i cuochi e non serve alcuna abilità avanzata per iniziare.",al={"serve la cucina","requisito professione cucina"}},{q="Quanto è importante Mulino di Tarren per l'Orda a Colletorto?",a="Mulino di Tarren è la principale roccaforte dell'Orda nelle Alture di Colletorto. Un tempo villaggio umano, ora è una base fortificata dei Reietti e dei loro alleati, che si scontra spesso con la vicina Riva del Sud e l'Alleanza.",al={"cos'è mulino di tarren","lore di mulino di tarren"}},{q="La zuppa di tartaruga è esclusiva dell'Orda?",a="I cuochi dell'Alleanza possono imparare la ricetta della zuppa di tartaruga da cuochi umani a Riva del Sud, che usano anch'essi tartarughe locali. La richiesta personale e il punto di vista di Christoph Jeffcoat appartengono all'Orda.",al={"versione dell'alleanza","l'alleanza può ottenere la zuppa di tartaruga"}}},fx={["7509a6d7"]={q="A cosa serve la carne di tartaruga?",a="Christoph Jeffcoat ha bisogno della carne di tartaruga per preparare la sua celebre zuppa di tartaruga corroborante. Anche se i non morti potrebbero non sentire il freddo o la fame come i vivi, Jeffcoat è immensamente orgoglioso della sua arte culinaria. Sostiene che la sua ricetta segreta sia così buona che la gente tornerebbe dalla morte pur di assaporarne una scodella fumante.",al={"uso della carne di tartaruga","perché serve la carne di tartaruga","a cosa serve la carne di tartaruga"}},["5469f6c5"]={q="Che cosa sono le tartarughe dal morso tenace che cacci per la zuppa?",a="Le tartarughe dal morso tenace sono tartarughe d'acqua dolce feroci e dal guscio duro, originarie dei corsi d'acqua di Lordaeron e particolarmente numerose lungo le rive del Lago Lordamere e sulle sponde dei fiumi locali. Selvatiche e pericolose per i viandanti incauti, hanno una carne tenace e nutriente, fondamentale per la zuppa di Christoph.",al={"tartarughe dal morso tenace a colletorto","tartarughe dal morso tenace del lago lordamere","chi devo cacciare"}}},fp="22,190,19.346.0,20.316.0,54.207.0,47.127.0,56.123.0,49.100.0,59.215.0,37.178.0"}
P.entries["quest:733"] = {n="Scrounging",s="Al campo di Sigrun Tagliaferro, le difese e le provviste dipendono dai rottami metallici. Le servono sette pezzi, e gli ogre nelle vicinanze ne hanno in abbondanza.",h="Al campo di Sigrun Tagliaferro, le difese e le provviste dipendono dai rottami metallici.",kw={"maleterre","grotta dei fendiroccia","lega degli esploratori","forgiardente","ogre","rottami metallici","scrounging","sigrun tagliaferro"},sec={{t="Un accampamento a corto di materiali",b="A Sigrun Tagliaferro servono materiali per le difese del campo e altre necessità. Il Prospettore è preoccupato per le condizioni del campo, perciò Sigrun vuole iniziare presto i lavori. Le mancano rottami metallici."},{t="I rottami degli ogre",b="Gli ogre nelle vicinanze portano rottami metallici, dando più peso alle voci sulle macchine d'assedio a Maleterre. Il loro accampamento principale, la Grotta dei Fendiroccia, si trova a ovest del campo di Sigrun, dopo un lungo viaggio."}},faq={{q="Chi sta chiedendo i rottami metallici?",a="A Sigrun Tagliaferro servono rottami metallici per costruire le difese e rifornire il campo.",al={"datore di missione","chi assegna scrounging","sigrun"}},{q="Perché l'accampamento ha bisogno di rottami metallici?",a="Al campo mancano materiali per le difese e altre necessità. Il Prospettore è preoccupato per le sue condizioni.",al={"perché servono rottami metallici","scopo dei rottami metallici","difese"}},{q="Dove si possono trovare i rottami metallici?",a="Gli ogre nelle vicinanze portano rottami metallici. Il loro accampamento principale, la Grotta dei Fendiroccia, si trova a ovest del campo di Sigrun, dopo un lungo viaggio.",al={"posizione rottami metallici","dove ottenere rottami metallici","accampamento degli ogre"}},{q="Cosa viene prima di questa?",a="Segue Mirages.",al={"missione precedente","prerequisito di scrounging"}}},fp="10,123,25.189.0,16.162.0,34.71.0,35.98.0,35.106.0,23.19.0"}
P.entries["quest:734"] = {n="This Is Going to Be Hard",s="A Maleterre, Lotwil Veriatus ti manda da Lucien Chiavetorta per un ingranaggio n. 5 necessario. Riportalo a Lotwil.",h="A Maleterre, Lotwil Veriatus ti manda da Lucien Chiavetorta per un ingranaggio n.",kw={"maleterre","ingranaggio n. 5","lotwil veriatus","lucien chiavetorta","catene"},sec={{t="Ingranaggio numero cinque",b="Lotwil Veriatus torna a occuparsi delle catene, poi ti manda da Lucien Chiavetorta. Gli serve un ingranaggio n. 5 e ti chiede di riportarglielo."},{t="Il verdetto di Lucien",b="Quando menzioni l'ingranaggio n. 5, Lucien Chiavetorta sembra dubbioso su come andranno le cose."}},faq={{q="Chi assegna questa missione?",a="Lotwil Veriatus ti fa questa richiesta mentre lavora a un paio di catene a Maleterre.",al={"chi inizia questa missione","missione di lotwil veriatus","chi assegna la missione"}},{q="Di cosa ha bisogno Lotwil?",a="Lotwil ha bisogno di un ingranaggio n. 5. Ti chiede di riportarglielo dopo aver parlato con Lucien Chiavetorta.",al={"cosa vuole lotwil","quale ingranaggio","ingranaggio 5"}},{q="Con chi devo parlare dell'ingranaggio?",a="Lotwil ti manda da Lucien Chiavetorta a Maleterre.",al={"dove trovare l'ingranaggio 5","chi è lucien","lucien chiavetorta"}}},fp="24,111,15.147.0,16.86.1,21.76.0,22.92.0,32.56.0"}
P.entries["quest:735"] = {n="The Star, the Hand and the Heart",s="A Forgiardente, Gerrig Morsaossa offre il Compendio di Yagyin in cambio di tre oggetti di potere. I loro nomi restano segreti e vengono scritti su un foglietto.",h="A Forgiardente, Gerrig Morsaossa offre il Compendio di Yagyin in cambio di tre oggetti di potere.",kw={"foglietto di morsaossa","gerrig morsaossa","artiglio di dagun","forgiardente","cuore dell'eredità","stella di xil'yeh","compendio di yagyin"},sec={{t="Uno scambio a bocca chiusa",b="Gerrig Morsaossa ti sente chiedere il Compendio di Yagyin e si domanda se tu voglia fondare un nuovo capitolo dell'ordine da qualche parte. Decide che non spetta a Gerrig chiedertelo. Avendo una copia in più, Gerrig crede che i membri dell'ordine debbano aiutarsi a vicenda. Perciò ti chiede di portare tre oggetti di potere. I loro nomi restano segreti, nel caso qualcuno stia ascoltando, e Gerrig li scrive."},{t="I tre oggetti",b="Il foglietto di Gerrig nomina la Stella di Xil'yeh, l'Artiglio di Dagun e il Cuore dell'Eredità. Gerrig li vuole tutti e tre prima di consegnarti il Compendio di Yagyin."},{t="Il verdetto di Gerrig",b="Con le reliquie in mano, Gerrig ti definisce pieno di risorse. Gerrig crede che, se fondare un nuovo capitolo dell'ordine è davvero il tuo compito, lo gestirai bene."}},faq={{q="Chi chiede i tre oggetti?",a="Gerrig Morsaossa, a Forgiardente, chiede tre oggetti e offre in cambio una copia in più del Compendio di Yagyin.",al={"datore di missione","chi inizia la stella la mano e il cuore","missione di gerrig morsaossa"}},{q="Quali tre oggetti vuole Gerrig Morsaossa?",a="Il foglietto di Gerrig Morsaossa nomina la Stella di Xil'yeh, l'Artiglio di Dagun e il Cuore dell'Eredità.",al={"oggetti richiesti","quali reliquie servono","oggetti del foglietto di morsaossa"}},{q="Perché Gerrig scrive gli oggetti invece di dirli?",a="Gerrig scrive i nomi perché qualcuno potrebbe stare ascoltando.",al={"perché scriverli","perché il messaggio segreto","sussurri di morsaossa"}},{q="Cosa c'era prima nella catena?",a="Segue To Ironforge for Yagyin's Digest, dove Theldurin il Perduto ti ha mandato da Gerrig.",al={"missione prerequisito","missione precedente"}}},fp="32,154,30.392.0,15.140.0,16.158.1,29.104.0,43.89.0,60.62.0,35.89.0"}
P.entries["quest:736"] = {n="The Star, the Hand and the Heart",s="A Sepulcra, il Protettore Bel'dugur mette alla prova chi aspira a guidare un proprio circolo. Per fondare un nuovo capitolo serve il Compendio di Yagyin, ma lui chiede tre oggetti di potere senza nome.",h="A Sepulcra, il Protettore Bel'dugur mette alla prova chi aspira a guidare un proprio circolo.",kw={"nota di bel'dugur","protettore bel'dugur","ordine","the star, the hand and the heart","tre oggetti di potere","sepulcra","compendio di yagyin"},ang={["class:Warlock"]="Da stregone, cerchi il Compendio di Yagyin per radunare un nuovo gregge e accrescere la conoscenza occulta del tuo ordine.",["race:Undead"]="Da non morto, trovi il Protettore Bel'dugur a Sepulcra, dove guida i praticanti Reietti in cerca di riti proibiti."},sec={{t="Una prova di fratellanza",b="Chi aspira a guidare un proprio circolo si reca dal Protettore Bel'dugur a Sepulcra. Per fondare un capitolo e radunare seguaci, serve il Compendio di Yagyin, un'opera di sapere rituale che lui custodisce. Bel'dugur aiuterà un confratello, ma prima gli chiede una prova di valore, prima di affidargli una conoscenza simile."},{t="Le reliquie non nominate",b="Il Protettore Bel'dugur chiede tre oggetti di potere in cambio del Compendio di Yagyin. I loro nomi hanno un peso pericoloso o sacro, perciò non li pronuncia ad alta voce. Li scrive invece su una nota privata. Trovarli tutti e tre dimostra che un praticante è degno di fondare un proprio capitolo."}},faq={{q="Chi è il Protettore Bel'dugur?",a="Il Protettore Bel'dugur vive a Sepulcra e aiuta i membri della sua oscura confraternita. Custodisce un sapere potente e chiede ai candidati di dimostrare il proprio valore prima di affidare loro testi sacri.",al={"chi è il protettore bel'dugur","ruolo di bel'dugur","bel'dugur sepulcra"}},{q="Cos'è il Compendio di Yagyin?",a="Il Compendio di Yagyin è un'opera di sapere rituale necessaria per fondare un nuovo capitolo o radunare seguaci all'interno di un ordine occulto e segreto.",al={"cos'è il compendio di yagyin","scopo del compendio di yagyin","libro compendio di yagyin"}},{q="Quali oggetti richiede il Protettore Bel'dugur?",a="Bel'dugur chiede tre oggetti di potere. Ne scrive i nomi su una nota privata, perché non li pronuncerà ad alta voce.",al={"quali oggetti servono a bel'dugur","oggetti della nota di bel'dugur","tre oggetti di potere"}},{q="Perché i nomi degli oggetti richiesti non vengono pronunciati ad alta voce?",a="Bel'dugur non pronuncia ad alta voce i nomi delle tre reliquie. Il loro potere pericoloso o il loro significato sacro impongono discrezione.",al={"perché bel'dugur non può pronunciare i nomi degli oggetti","non può pronunciare i nomi","nomi di oggetti non pronunciati"}},{q="Cosa significa riunire un altro gregge?",a="Radunare un gregge significa reclutare seguaci e fondare un capitolo indipendente della confraternita, pronto a guidare altri praticanti.",al={"cosa significa riunire un gregge","aprire un capitolo","capitolo del nostro ordine"}},{q="Dove è incentrata questa missione?",a="La storia è incentrata sul Protettore Bel'dugur a Sepulcra, la capitale sotterranea dei Reietti.",al={"dove si svolge questa missione","posizione di bel'dugur","luogo di consegna della missione"}}},fp="32,178,21.311.0,19.280.0,24.186.0,24.123.0,41.118.0,58.118.0,42.136.0,29.90.0"}
P.entries["quest:737"] = {n="Forbidden Knowledge",s="Il Compendio di Yagyin è affidato a te, diretto a Theldurin il Perduto e al riparo da mani ostili.",h="Il Compendio di Yagyin è affidato a te, diretto a Theldurin il Perduto e al riparo da mani ostili.",kw={"maleterre","forbidden knowledge","the star the hand and the heart","theldurin il perduto","compendio di yagyin"},sec={{t="Un libro che scotta",b="Gerrig Morsaossa a Forgiardente o il Protettore Bel'dugur a Sepulcra ti consegna il Compendio di Yagyin. Tienilo al riparo da mani ostili mentre lo porti a Theldurin il Perduto. Contiene molte verità, e la verità ha il potere di scottare."},{t="La speranza di Theldurin",b="Theldurin il Perduto grida che brilla ancora una speranza. Dice che i tuoi sforzi potrebbero ancora salvarli tutti e portare a un monumento e a un santuario, con il tuo nome lodato per generazioni.\n\nQuella speranza regge solo finché LORO restano sotto la superficie. Se LORO riusciranno a risalire liberi, tutti diventeranno cibo per vermi."}},faq={{q="Quale oggetto deve essere consegnato?",a="Il Compendio di Yagyin va consegnato. Contiene molte verità e va tenuto al riparo da mani ostili.",al={"che libro è","cos'è il compendio di yagyin","cosa devo portare"}},{q="Chi riceve il compendio?",a="Il Compendio di Yagyin va consegnato a Theldurin il Perduto.",al={"chi riceve il libro","a chi devo consegnarlo","dove va il compendio"}},{q="Cosa c'era prima?",a="Segue il passaggio in cui hai recuperato tre oggetti in cambio del Compendio di Yagyin.",al={"missione precedente","cosa porta a questo","quale missione precede forbidden knowledge"}}},fp="19,93,17.215.0,16.268.1,32.99.0,24.49.0,22.82.0"}
P.entries["quest:738"] = {n="Find Agmond",s="Da settimane non arrivano notizie del Prospettore Agmond dagli scavi di Maleterre. Il Prospettore Ferrocollo ti chiede di trovare Agmond e riportargli il suo rapporto.",h="Da settimane non arrivano notizie del Prospettore Agmond dagli scavi di Maleterre.",kw={"agmond","fortezza di angor","maleterre","forgiardente","prospettore ferrocollo"},sec={{t="Un prospettore silenzioso",b="Il Prospettore Agmond dirigeva gli scavi di Maleterre, a sud-ovest del Prospettore Ferrocollo. Ferrocollo ormai parla di lui al passato, perché non ne ha notizie da settimane. Ha bisogno che trovi Agmond e recuperi il rapporto. L'ultima notizia di Agmond lo dava allo scavo più meridionale, un piccolo avamposto oltre la Fortezza di Angor. Comincia da lì."},{t="Dove finiscono le tracce",b="Alla fine delle ricerche trovi uno scheletro che dev'essere ciò che resta di Agmond. Il corpo è spezzato e malconcio, e le ossa sono state ripulite."}},faq={{q="Chi è il Prospettore Agmond?",a="Il Prospettore Agmond dirigeva gli scavi di Maleterre, a sud-ovest del Prospettore Ferrocollo.",al={"chi è agmond","chi agmond","storia di agmond"}},{q="Perché il Prospettore Ferrocollo cerca Agmond?",a="Il Prospettore Ferrocollo non riceve notizie di Agmond da settimane e ha bisogno del suo rapporto.",al={"perché trovare agmond","ferrocollo cerca agmond"}},{q="Dove è stato visto l'ultima volta il Prospettore Agmond?",a="L'ultima notizia di Agmond lo dava allo scavo più meridionale di Maleterre, un piccolo avamposto oltre la Fortezza di Angor.",al={"posizione di agmond","dove si trova il sito di scavo di agmond","dove si trovava agmond"}},{q="Cosa viene prima in questa serie di missioni?",a="Segue Ironband Wants You!",al={"missione precedente","prerequisiti per find agmond"}}},fp="11,151,19.307.0,20.154.1,25.92.0,46.80.0,45.98.0,36.30.0"}
P.entries["quest:739"] = {n="Murdaloc",s="Agmond giace morto a Maleterre, con il nome Murdaloc graffiato nell'arenaria accanto alla mano. Uccidi il suo assassino e porta la notizia al Prospettore Ferrocollo a Loch Modan.",h="Agmond giace morto a Maleterre, con il nome Murdaloc graffiato nell'arenaria accanto alla mano.",kw={"agmond","maleterre","loch modan","murdaloc","prospettore ferrocollo","stonevault bonesnapper","trogg"},sec={{t="Un nome nell'arenaria",b="Una scia di sangue segna il percorso di Agmond da ovest, attraversando pietra e sabbia. Mostra fin dove è strisciato il nano prima di morire. Accanto alla sua mano immobile, una parola è graffiata nell'arenaria di Maleterre: Murdaloc. Uccidi l'assassino di Agmond e alcuni Stonevault Bonesnapper, poi porta la notizia al Prospettore Ferrocollo a Loch Modan."},{t="La risposta di Ferrocollo",b="Il Prospettore Ferrocollo accoglie la notizia con aria grave. Ricorda Agmond come un nano dal braccio forte, feroce con il martello e dalla testa dura. Ferrocollo dice che Agmond è stato ucciso da trogg maledetti. Crede che Agmond ne abbia abbattuti parecchi lungo il cammino."}},faq={{q="Chi era Agmond?",a="Agmond era un nano che supervisionava i siti di scavo a Maleterre per il Prospettore Ferrocollo. La tua ricerca finì davanti a uno scheletro.",al={"chi è agmond","storia di agmond"}},{q="Chi è Murdaloc?",a="Murdaloc è il nome graffiato nell'arenaria accanto alla mano morta di Agmond. Uccidi l'assassino di Agmond, Murdaloc.",al={"cos'è murdaloc","storia di murdaloc"}},{q="Dove deve andare il rapporto?",a="Porta il rapporto al Prospettore Ferrocollo a Loch Modan.",al={"a chi devo parlare di murdaloc","dov'è ferrocollo"}}},fp="8,162,23.321.0,16.245.1,15.133.0,16.108.0,33.54.0"}
P.entries["quest:74"] = {n="Leggenda di Stalvan",s="Accanto ai Canali di Roccavento trovi un indizio sul passato di Stalvan Mistmantle nella cassa Flintridge. La Pagina di Diario Strappata indica Marshal Haggard nella Foresta di Elwynn.",h="Accanto ai Canali di Roccavento trovi un indizio sul passato di Stalvan Mistmantle nella cassa Flintridge.",kw={"boscovespro","foresta di elwynn","spirito infausto","marshal haggard","mistmantle","cassa sigillata","stalvan","pagina di diario strappata"},ang={["faction:Alliance"]="Da investigatore dell'Alleanza, scopri come orrori personali nel cuore di Elwynn possano sfuggire ai marshal di Roccavento.",["race:Human"]="Da umano, vedi in Marshal Haggard un esponente della generazione ormai anziana dei veterani di Roccavento. Custodisce ricordi preziosi del regno, di prima che la Prima e la Seconda Guerra separassero le famiglie."},sec={{t="Riportare alla luce il passato",b="Sotto un vaso di ceramica nella Cassa Sigillata si trova una pagina strappata dal diario di Stalvan Mistmantle. Cimeli ammuffiti dei Flintridge, vecchi trofei di caccia e ritratti di famiglia riempiono la cassa. La grafia di Stalvan offre uno scorcio dello studioso schivo prima che la tragedia lo colpisse."},{t="La vista calante di un Marshal",b="Marshal Haggard si sforza di leggere la pergamena malridotta con la vista ormai debole. La grafia inconfondibile gli risveglia i ricordi di documenti e fatti di anni prima, quando ancora non era stato avvolto dall'oscurità."}},faq={{q="Dove si trova la Cassa Sigillata?",a="La Cassa Sigillata si trova accanto ai Canali di Roccavento, proprio dietro al Curato Folsom. Contiene gli effetti personali della famiglia Flintridge, e la pagina che vi trovi va consegnata a Marshal Haggard, nel sud-est della Foresta di Elwynn.",al={"posizione cassa","dove si trova la cassa","cassa haggard"}},{q="Cosa c'è dentro la Cassa Sigillata?",a="La cassa contiene cimeli impolverati, un ritratto di famiglia, vecchi libri, trofei di caccia e un vaso di ceramica. Sotto il vaso si trova una Pagina di Diario Strappata di Stalvan.",al={"contenuto cassa","cosa c'è nella cassa","cassa pagina strappata"}},{q="Chi è il Marshal Haggard?",a="Marshal Haggard è un anziano ufficiale di Roccavento in pensione, che vive da solo nel sud della Foresta di Elwynn. La vista gli si sta indebolendo ed è fragile, ma i suoi ricordi di vecchi documenti e viaggiatori lo rendono un testimone cruciale degli eventi passati.",al={"chi è haggard","lore marshal haggard","vecchio marshal elwynn"}},{q="Perché questa Pagina di Diario è importante?",a="La pagina strappata è una prova diretta, scritta di mano da Stalvan Mistmantle. La sua grafia inconfondibile e i pensieri che vi permangono collegano testimonianze del Boscovespro e di Elwynn alla sua rovina personale.",al={"perché importa la pagina strappata","indizio pagina di diario","diario stalvan"}},{q="Cosa succede quando la cassa viene aperta?",a="Turbare ciò che resta del passato di Stalvan risveglia i Restless Dead. Appare uno Spirito Infausto assetato di vendetta e attacca chi cerca di svelare la tragedia.",al={"apparizione spirito infausto","fantasma dopo la cassa","perché mi ha attaccato un fantasma"}},{q="Dove conduce la prossima fase dell'indagine?",a="Quando la pagina strappata arriva a Marshal Haggard, il ricordo della grafia guida le indagini verso altri frammenti ancora esistenti della storia di Stalvan.",al={"passo successivo","dopo la pagina strappata","dove devo andare dopo"}}},fp="21,171,19.265.0,24.200.1,34.215.0,32.158.0,23.226.0,35.183.0,38.152.0,39.152.0"}
P.entries["quest:741"] = {n="The Absent Minded Prospector",s="Da Rivafosca, Hollee manda il fossile di Errasogni a Darnassus, mentre lei resta a sorvegliare il prospettore errabondo. Il Capo Archeologo Baffogrigio mostra grande interesse per il ritrovamento.",h="Da Rivafosca, Hollee manda il fossile di Errasogni a Darnassus, mentre lei resta a sorvegliare il prospettore...",kw={"archeologo","rivafosca","darnassus","lega degli esploratori","fossile","baffogrigio","hollee","errasogni"},ang={["faction:Alliance"]="Come membro dell'Alleanza, aiuti a tenere unite le sue genti anche a grande distanza. I ricercatori nani si affidano ai viaggiatori perché trasportino al sicuro i ritrovamenti dalle coste remote di Rivafosca a Darnassus.",["race:Dwarf"]="Come nano, trasportare il fossile di Errasogni serve allo scopo principale della Lega degli Esploratori: svelare il passato remoto del mondo e dimostrare il valore della perseveranza nanica.",["race:NightElf"]="Come elfo della Notte, vedere gli scavatori nani riportare alla luce antichi resti dal suolo sacro di Rivafosca può lasciare sconcertati. La collaborazione con la Lega preserva i legami dell'Alleanza."},sec={{t="Un corriere per la capitale",b="Il Prospettore Errasogni ha trovato un curioso fossile sulla costa di Rivafosca. Preferirebbe continuare a scavare invece di seguire il protocollo. Così Archaeologist Hollee resta con lui, tra le bestie pericolose e i cultisti ostili della costa. Ti chiede di portare il reperto a Darnassus, dove si trova una delegazione di studiosi nani."},{t="L'interesse dei nani a Kalimdor",b="I nani di Forgiardente hanno attraversato il Grande Mare sotto la bandiera della Lega degli Esploratori. Cercano antiche reliquie e storie perdute nel suolo di Kalimdor. A Darnassus, il Capo Archeologo Baffogrigio si meraviglia dell'abilità di Errasogni nel trovare antichi tesori. Gli elfi della Notte vedono le loro foreste come santuari viventi, mentre la Lega vede le terre antiche come luoghi da studiare e decifrare."}},faq={{q="Cos'è il Fossile Misterioso?",a="Il Prospettore Errasogni ha trovato un reperto pietrificato non identificato sulla costa di Rivafosca. La sua età e la sua natura insolita ne fanno una scoperta preziosa per gli studiosi della Lega degli Esploratori a Darnassus.",al={"fossile misterioso","che fossile è questo","fossile errasogni"}},{q="perché Hollee resta a Rivafosca?",a="Archaeologist Hollee resta per sorvegliare il Prospettore Errasogni. Lui si allontana e ignora i pericoli mentre scava, perciò lei non vuole lasciarlo solo nelle terre selvagge mentre porta le sue scoperte a Darnassus.",al={"perché hollee non va","hollee resta","perché hollee resta"}},{q="Chi è il Capo Archeologo Baffogrigio?",a="Il Capo Archeologo Baffogrigio è un rappresentante di alto rango della Lega degli Esploratori di Forgiardente. Supervisiona gli scavi archeologici nel nord di Kalimdor da Darnassus, dove studia le reliquie riportate dai nani scavatori.",al={"baffogrigio","chi è baffogrigio","capo baffogrigio"}},{q="Perché la Lega degli Esploratori opera a Darnassus?",a="Re Magni Barbabronzea fondò la Lega degli Esploratori per scoprire le origini della razza nanica e la storia antica di Azeroth. I rapporti amichevoli con gli elfi della Notte permettono agli studiosi nani di organizzare spedizioni da Darnassus e di studiare le terre dimenticate di Kalimdor.",al={"nani a darnassus","lega degli esploratori darnassus","perché i nani sono qui"}},{q="Dove finisce questo fossile dopo Darnassus?",a="Il Capo Archeologo Baffogrigio esamina il fossile a Darnassus. Ritrovamenti di questa portata devono essere catalogati o inviati tramite i canali della Lega al grande museo di Forgiardente.",al={"dove va il fossile","passo successivo fossile"}},{q="Dove ha trovato il reperto Errasogni?",a="Errasogni ha trovato il reperto sulla costa selvaggia di Rivafosca, tra relitti, antiche rovine e forme di vita marina fossilizzate risalenti a prima del Grande Cataclisma.",al={"dove è stato trovato il fossile","sito di scavo errasogni"}}},fx={c70c2c67={q="Perché Archaeologist Hollee vuole che il fossile venga consegnato a Darnassus?",a="Il Prospettore Errasogni vuole che la sua scoperta venga esaminata subito, ma qualcuno deve portarla ai suoi superiori. Hollee è determinata a non abbandonare Rivafosca mentre Errasogni è ancora nella natura selvaggia, quindi si affida a te per trasportare direttamente a Darnassus il prezioso reperto e consegnarlo al Capo Archeologo Baffogrigio per conto loro.",al={"perché mandare il fossile a darnassus","motivo di hollee","perché consegnare il fossile"}}},fp="28,180,24.315.0,29.381.0,30.181.0,41.202.0,39.222.0,52.261.0,46.181.0,38.151.0"}
P.entries["quest:742"] = {n="Caccia a Valtetra",s="A Picco del Tuono, The Ashenvale Hunt manda i giovani campioni dell'Orda a nord, a servire negli avamposti della foresta. Gli araldi li invitano a presentarsi a Senani Cuore Tonante all'Avamposto di Troncorotto per una caccia di prova.",h="A Picco del Tuono, The Ashenvale Hunt manda i giovani campioni dell'Orda a nord, a servire negli avamposti...",kw={"valtetra","caccia","senani","troncorotto","picco del tuono","cuore tonante","passo fulgido","spiaggia di zoram"},ang={["class:Hunter"]="Come cacciatore, puoi affinare le tue capacità di seguire le tracce nei fitti boschi di Valtetra, dove i predatori si muovono in un ambiente diverso dalle aride e aperte savane meridionali.",["faction:Horde"]="Come membro dell'Orda, fai affidamento sull'Avamposto di Troncorotto e sulla Spiaggia di Zoram per sostenere le linee di rifornimento settentrionali. Le nuove reclute aiutano a tenere a bada le bestie selvagge e gli abitanti ostili.",["race:Tauren"]="Da tauren cresciuto nelle pianure aperte di Mulgore, affronti una sfida insolita sotto la fitta volta arborea di Valtetra. Parenti come Senani vegliano sulla caccia."},sec={{t="Una Convocazione da High Rise",b="Corridore del Picco Passo Fulgido porta un invito aperto per gli avventurieri che hanno già dato prova di sé, attraversando Picco del Tuono. A nord delle Savane, l'Orda ha stabilito delle basi in un'antica foresta, i cui avamposti hanno bisogno di giovani guerrieri. Chi risponde dovrà affrontare terre più impervie e mettere alla prova le proprie capacità di sopravvivenza oltre Mulgore."},{t="La Frontiera Settentrionale",b="Valtetra offre all'Orda risorse preziose e gravi pericoli. L'Avamposto di Troncorotto sorge lungo la strada principale, mentre un avamposto isolato si trova sulla costa occidentale, alla Spiaggia di Zoram. All'Avamposto di Troncorotto, Senani Cuore Tonante è una veterana dei boschi che organizza una grande caccia. Qui, le reclute domano la natura selvaggia e conquistano gloria per l'Orda."}},faq={{q="Chi offre questa missione a Picco del Tuono?",a="Corridore del Picco Passo Fulgido offre l'appello agli avventurieri di passaggio a Picco del Tuono. Avvisa i combattenti capaci degli sforzi dell'Orda per espandersi e indica loro gli avamposti che hanno bisogno di aiuto.",al={"chi inizia the ashenvale hunt","chi dà la missione the ashenvale hunt","corridore del picco passo fulgido"}},{q="Dove si trova l'Avamposto di Troncorotto?",a="L'Avamposto di Troncorotto è un insediamento fortificato dell'Orda nella parte orientale di Valtetra. Attraversa il confine delle Savane verso nord, poi segui il sentiero nella foresta orientale che si inoltra tra gli alberi.",al={"posizione avamposto di troncorotto","come raggiungere avamposto di troncorotto","dove si trova l'avamposto di troncorotto"}},{q="Chi è Senani Cuore Tonante?",a="Senani Cuore Tonante è un'esperta esploratrice tauren di stanza all'Avamposto di Troncorotto. Organizza cacce a Valtetra, mettendo alla prova le reclute dell'Orda contro i predatori locali.",al={"senani cuore tonante","chi è senani","npc cuore tonante"}},{q="Perché l'Orda dà la caccia alle prede a Valtetra?",a="L'Orda caccia a Valtetra per raccogliere legname e assicurarsi il territorio. La caccia riduce il numero di bestie selvagge che minacciano i suoi accampamenti e permette ai giovani avventurieri di dimostrare il proprio valore in territori sconosciuti.",al={"perché cacciare a valtetra","scopo della caccia a valtetra","obiettivi orda valtetra"}},{q="Cos'è la Spiaggia di Zoram menzionata nel briefing?",a="La Spiaggia di Zoram è un accampamento dell'Orda sulla costa occidentale più remota di Valtetra, affacciato sul mare. È una base navale secondaria e un baluardo contro i naga e gli abitanti ostili della foresta.",al={"cos'è la spiaggia di zoram","avamposto spiaggia di zoram","avamposto di zoram"}},{q="Cosa succede dopo essersi presentati a Senani?",a="Quando ti presenti a Senani Cuore Tonante, lei ti dà il benvenuto all'avamposto e ti affida la grande caccia. Ti manda a inseguire e sconfiggere le bestie più feroci di Valtetra.",al={"cosa segue the ashenvale hunt","missione successiva dopo senani","continuazione della caccia"}}},fx={af70e220={q="Perché Corridore del Picco Passo Fulgido vuole che tu vada a Valtetra?",a="Corridore del Picco Passo Fulgido è un araldo dell'Orda che indirizza i giovani campioni capaci là dove servono di più. L'Orda sta consolidando con decisione i suoi avamposti di frontiera nelle foreste selvagge a nord delle Savane, e cacciatori come Senani Cuore Tonante hanno bisogno di nuove reclute per rafforzare la loro presenza e conquistare gloria nella natura selvaggia.",al={"perché andare a valtetra","motivo di corridore del picco passo fulgido","perché passo fulgido vuole questo"}}},fp="18,197,28.293.0,21.333.0,39.191.0,35.171.0,27.166.0,38.189.0,51.173.0,39.171.0"}
P.entries["quest:743"] = {n="I pericoli delle Furie del Vento",s="Ruul Unghia Lunga mette alla prova la tua preparazione contro le arpie Vento Furente a Mulgore. La loro velocità e i loro artigli ti sfideranno sulle scogliere sud-orientali, prima che tu lasci la terra natale dei tauren.",h="Ruul Unghia Lunga mette alla prova la tua preparazione contro le arpie Vento Furente a Mulgore.",kw={"villaggio di zoccolo sanguinario","dangers of the windfury","arpie","mulgore","ruul unghia lunga","prova tauren","vento furente","artigli di vento furente"},ang={["class:Warrior"]="Da guerriero, la prova di Ruul Unghia Lunga ti insegna a parare i rapidi attacchi in picchiata. Ti allena ad affrontare da terra gli attaccanti feroci che piombano dall'aria.",["faction:Horde"]="In quanto alleato dei tauren, affrontare la prova di Ruul dimostra la tua dedizione a proteggere il cuore dell'Orda. Può farti guadagnare il rispetto del Villaggio di Zoccolo Sanguinario.",["race:Tauren"]="Da giovane tauren, ripulire i nidi delle arpie Vento Furente aiuta a difendere le pianure. Sotto lo sguardo degli anziani del villaggio, segna il tuo ingresso nell'età adulta riconosciuta."},sec={{t="La valutazione di un insegnante",b="Dal Villaggio di Zoccolo Sanguinario, Ruul Unghia Lunga osserva i viaggiatori attraversare Mulgore. Chiede a chi sta raggiungendo la maggiore età o si prepara a viaggiare più lontano di dimostrare i propri istinti di combattimento. Oltre le valli riparate di Mulgore, sopravvivere richiede sangue freddo contro nemici astuti. Ruul misura il tuo valore contro i predatori nativi più feroci della terra."},{t="La minaccia delle Vento Furente",b="Le arpie Vento Furente nidificano lungo il confine montuoso sud-orientale di Mulgore, lontano dai sentieri battuti. Minacciano la fauna errante e i viaggiatori isolati. Si gettano in picchiata con rapidità e colpiscono con artigli affilati come rasoi mentre cercano carne fresca. Sconfiggile e riportane gli artigli per dimostrare che sai sventare una minaccia radicata e rispondere a un attacco dall'aria."}},faq={{q="Chi è Ruul Unghia Lunga?",a="Ruul Unghia Lunga è un guerriero tauren veterano e un maestro nel Villaggio di Zoccolo Sanguinario. Mette alla prova i giovani avventurieri prima che si avventurino nelle zone più pericolose di Kalimdor.",al={"ruul unghia lunga","chi assegna dangers of the windfury","ruul"}},{q="Dove si trovano le arpie Vento Furente a Mulgore?",a="Le arpie Vento Furente nidificano sulle montagne sud-orientali di Mulgore, in nidi rozzi in alto, su dirupi e pendii ai piedi delle colline. I loro nidi si trovano lontano dalla strada principale che attraversa la valle.",al={"posizione arpie vento furente","dove sono le arpie vento furente","posizione nidi vento furente"}},{q="Perché le arpie Vento Furente sono considerate nemici naturali dei tauren?",a="Le arpie Vento Furente sono saprofaghe aggressive e territoriali che attaccano chiunque si avvicini ai loro nidi. La loro fame di carne fresca e gli attacchi ai viaggiatori e agli animali al pascolo le rendono una minaccia costante per le pianure.",al={"perché i tauren combattono le arpie","minaccia arpie mulgore","lore vento furente"}},{q="Quale prova richiede Ruul Unghia Lunga dalla caccia?",a="Ruul ti chiede di riportargli otto artigli Vento Furente strappati alle arpie uccise. Gli artigli sono le loro principali armi naturali.",al={"prova dangers of the windfury","cosa raccogliere per ruul","obiettivi missione vento furente"}},{q="Perché gli avventurieri devono sottoporsi a questa prova prima di lasciare Mulgore?",a="Per Ruul, le arpie Vento Furente sono una prova della preparazione marziale. La loro velocità, ferocia e i loro artigli mettono alla prova chi si prepara ad affrontare i pericoli oltre le rupi difensive di Mulgore.",al={"scopo della prova","perché fare dangers of the windfury","test di ruul"}},{q="Dove si trova il Villaggio di Zoccolo Sanguinario?",a="Il Villaggio di Zoccolo Sanguinario si trova nel centro di Mulgore, vicino al Lago Toro di Pietra, a sud del Grande Cancello e del Picco del Tuono. I viaggiatori tauren vi trovano cultura, commercio e addestramento.",al={"posizione villaggio di zoccolo sanguinario","dov'è villaggio di zoccolo sanguinario","posizione ruul"}}},fx={d8522cbd={q="Perché Ruul Unghia Lunga vuole che vengano cacciate le arpie Furia del Vento?",a="Ruul Unghia Lunga è un guerriero e mentore incaricato di preparare i giovani avventurieri prima che si avventurino oltre i confini sicuri di Mulgore. Considera le feroci arpie Furia del Vento una prova naturale: un vero banco di prova per la tua abilità marziale e per la tua preparazione ad affrontare le minacce più pericolose del mondo.",al={"perché cacciare le arpie","motivo di ruul","motivo di ruul unghia lunga"}},["1789ad72"]={q="Chi sono le arpie Furia del Vento?",a="Le arpie Furia del Vento sono feroci necrofaghe alate che nidificano sulle cenge montane a sud-est del Villaggio di Zoccolo Sanguinario. Spietate e astute, da tempo predano viandanti e animali selvatici in tutta Mulgore, spinte da un'insaziabile fame di carne fresca e dalla loro naturale ostilità verso i tauren.",al={"arpie furia del vento","chi sono le furia del vento","arpie furia del vento a mulgore"}},["29c303b8"]={q="Perché Ruul Unghia Lunga non caccia le arpie di persona?",a="Ruul è un insegnante e il suo dovere al Villaggio di Zoccolo Sanguinario è preparare la prossima generazione di difensori, non combattere al posto loro. Questa missione è esplicitamente un rito di passaggio: devi dimostrare la tua forza contro i predatori di Mulgore prima di essere ritenuto pronto a viaggiare oltre le pianure.",al={"perché io","perché mandano me","perché ruul non se ne occupa"}}},fp="23,183,22.325.0,19.354.0,23.162.0,48.176.0,70.210.0,53.112.0,63.172.0,35.163.0"}
P.entries["quest:744"] = {n="Preparativi per la cerimonia",s="Eyahn Eagletalon prepara un copricapo per suo fratello, che presto si presenterà al Capo Cairne Zoccolo Sanguinario. Ti chiede di raccogliere le piume vivaci dalle arpie oltre Picco del Tuono mentre conci le fasce di cuoio.",h="Eyahn Eagletalon prepara un copricapo per suo fratello, che presto si presenterà al Capo Cairne Zoccolo...",kw={"cairne zoccolo sanguinario","cerimonia","piume","arpia","copricapo","mulgore","preparazione alla cerimonia","tauren","picco del tuono"},ang={["faction:Horde"]="Come membro dell'Orda, onori le usanze dei tuoi alleati tauren sulle mesa di Picco del Tuono quando li aiuti nei loro compiti cerimoniali.",["race:Tauren"]="Come tauren, sai che i copricapi naturali sono legati all'onore e ai riti di passaggio davanti a The High Chieftain. Aiutare a realizzare queste insegne dimostra l'orgoglio e lo spirito condivisi dalle tribù."},sec={{t="Onorare il Capotribù",b="Per i tauren, presentarsi al Capo Cairne Zoccolo Sanguinario è motivo di orgoglio e reverenza. Le famiglie onorano l'occasione preparando un abito adeguato. Il copricapo tradizionale è fatto di cuoio trattato e piumaggio simbolico, scelto in ogni sua parte per mostrare dignità e rispetto al capo delle tribù unite."},{t="Piume delle Creste",b="Un copricapo cerimoniale richiede una fascia di cuoio e piume per la corona. Mentre le cinghie di cuoio vengono conciate, bisogna raccogliere piume lunghe e intatte. Le arpie nidificano sulle colline rocciose a nord e a nord-ovest di Picco del Tuono, perciò dovrai avventurarti nei loro nidi ostili per trovare piume della dimensione e del colore adatti."}},faq={{q="Per quale cerimonia ci si sta preparando?",a="La cerimonia segna il momento in cui un tauren si presenta al Capo Cairne Zoccolo Sanguinario. Suo fratello prepara per l'occasione un copricapo di cuoio conciato e piume vivaci.",al={"di che cerimonia si tratta","cos'è la cerimonia","chi si presenta davanti a zoccolo sanguinario"}},{q="Chi è il Capo Zoccolo Sanguinario?",a="Il Capo Cairne Zoccolo Sanguinario guida le tribù tauren unite da Picco del Tuono. Presentarsi al suo cospetto è un onore per ogni tauren.",al={"chi è il capo zoccolo sanguinario","cairne zoccolo sanguinario","chi è zoccolo sanguinario"}},{q="Perché le piume di arpia sono necessarie per il copricapo?",a="Il copricapo richiede piume di una particolare dimensione e colore. Il disegno prevede piumaggio azzurro e bronzeo, mentre le cinghie di cuoio vengono conciate.",al={"perché servono le piume di arpia","perché le piume di arpia","perché le piume"}},{q="Dove si trovano le arpie?",a="Le arpie vivono nelle terre impervie a nord e a nord-ovest di Picco del Tuono, a Mulgore.",al={"dove vivono le arpie","dove trovare le arpie","dove sono le piume azzurre e bronzo"}},{q="Che ruolo svolgono le arpie a Mulgore?",a="Le arpie sono creature feroci, metà uccello e metà umanoide, che nidificano nelle gole rocciose di Mulgore. Minacciano viaggiatori e tribù, mentre il loro piumaggio grande e colorato offre materiale per ornamenti cerimoniali.",al={"perché le arpie vengono cacciate","cosa sono le arpie"}},{q="Chi sta creando il copricapo cerimoniale?",a="Eyahn Eagletalon concia le cinghie di cuoio e prepara il copricapo per suo fratello, che si appresta a presentarsi al capo.",al={"chi realizza il copricapo","chi crea il copricapo"}}},fp="24,212,22.307.0,21.314.0,36.161.0,23.121.0,48.143.0,30.82.0,37.203.0,41.130.0"}
P.entries["quest:745"] = {n="Sharing the Land",s="A Mulgore, Baine Zoccolo Sanguinario ti chiede di fermare gli gnoll Mantopallido, che uccidono la fauna delle pianure. Aiuti a proteggere le mandrie e lo stile di vita dei tauren, in armonia con la Madre Terra.",h="A Mulgore, Baine Zoccolo Sanguinario ti chiede di fermare gli gnoll Mantopallido, che uccidono la fauna delle...",kw={"baine zoccolo sanguinario","villaggio di zoccolo sanguinario","gnoll","mulgore","mantopallido","bracconieri","sharing the land","scuoiatori","conciatori"},ang={["class:Druid"]="Da druido, sai che il bracconaggio incontrollato danneggia lo spirito delle pianure. L'armonia della terra ha bisogno del tuo aiuto.",["class:Hunter"]="Gli scuoiatori e i bracconieri Mantopallido cacciano con crudeltà e spreco. Non hanno il rispetto per le creature selvatiche proprio di un vero cacciatore.",["faction:Horde"]="Come membro dell'Orda, rafforzi il tuo legame con i capi della giovane nazione tauren aiutando Baine Zoccolo Sanguinario.",["race:Tauren"]="Come giovane tauren, rispondi alla chiamata di Baine per difendere Mulgore e onorare l'equilibrio della Madre Terra."},sec={{t="Una terra fuori equilibrio",b="I tauren prendono dalla terra solo ciò di cui hanno bisogno e onorano la Madre Terra in ogni cosa. Gli gnoll Mantopallido si sono stabiliti a sud del Villaggio di Zoccolo Sanguinario e in una caverna a ovest. Per tutte le pianure, massacrano la fauna selvatica e lasciano carcasse. Le loro cacce sprecone danneggiano l'equilibrio delle praterie e minacciano la dimora pacifica che i tauren stanno costruendo a Mulgore."},{t="Quando le parole non bastano",b="Baine Zoccolo Sanguinario ha cercato di risolvere la questione pacificamente parlando con gli gnoll Mantopallido. Hanno respinto ogni tentativo e continuato a uccidere la fauna selvatica. Ora invia giovani guerrieri ai loro accampamenti di caccia per fermare bracconieri, conciatori e scuoiatori prima che le praterie subiscano danni permanenti."},{t="Il cerchio della Vita e Morte",b="Al tuo ritorno, Baine ti insegna che non si dovrebbe mai togliere la vita per malizia, anche se può essere necessario per mantenere l'armonia. Vita e Morte formano un cerchio. Ogni guardiano di Mulgore deve portare con sé questa verità."}},faq={{q="Chi assegna questa missione?",a="Baine Zoccolo Sanguinario, figlio dell'Alto Capo Cairne Zoccolo Sanguinario, ti affida questo compito nel Villaggio di Zoccolo Sanguinario, nel centro di Mulgore.",al={"datore di missione","chi inizia sharing the land","missione di baine"}},{q="Perché i tauren hanno preso di mira gli gnoll Mantopallido?",a="Gli gnoll Mantopallido cacciano senza criterio la fauna selvatica di Mulgore e decimano le mandrie. Hanno anche respinto i tentativi dei tauren di parlare pacificamente.",al={"perché uccidere gli gnoll","problema mantopallido","cosa hanno fatto gli gnoll"}},{q="Dove si trovano questi gnoll?",a="I Mantopallido si accampano a sud del Villaggio di Zoccolo Sanguinario e vivono nel sistema di caverne della Roccia dei Mantopallido, a ovest.",al={"posizioni degli gnoll","accampamento mantopallido","dove trovare i mantopallido"}},{q="I tauren hanno provato prima a cercare la pace?",a="Sì. Baine dice che i tauren hanno provato più volte a parlare con gli gnoll e a condividere la terra, ma i Mantopallido hanno respinto le loro offerte pacifiche.",al={"i tauren hanno parlato con gli gnoll","diplomazia mantopallido"}},{q="Quale lezione sta cercando di insegnare Baine qui?",a="Baine vuole che i giovani difensori capiscano che Vita e Morte formano un cerchio indissolubile. Togliere la vita può essere necessario per proteggere l'equilibrio, ma va fatto con rispetto per la Madre Terra.",al={"lezione di baine","significato di sharing the land"}},{q="Chi sono gli gnoll Mantopallido?",a="Gli gnoll Mantopallido sono una tribù primitiva di Mulgore, simile alle iene. Hanno il pelo chiaro, difendono aggressivamente il loro territorio e ignorano l'armonia delle pianure.",al={"chi sono i mantopallido","tribù mantopallido"}}},fx={["901e0c5d"]={q="Contro chi ti manda la missione Sharing the Land?",a="Baine ti manda contro i gnoll Crinopallido che si sono insediati nelle pianure a sud del Villaggio di Zoccolo Sanguinario e hanno trovato rifugio in una caverna a ovest. Questi bracconieri, scuoiatori e conciatori stanno massacrando senza criterio gli animali selvatici di Mulgore, senza alcun rispetto per l'equilibrio o per la Madre Terra. Poiché hanno respinto con violenza ogni tentativo pacifico dei tauren, la forza è l'unico mezzo rimasto per fermare il loro bracconaggio.",al={"bersagli di sharing the land","chi devo uccidere in sharing the land","gnoll crinopallido in sharing the land"}}},fp="16,178,21.364.0,15.287.0,28.197.0,21.117.0,49.139.0,31.100.0,39.141.0,42.194.0,28.170.0"}
P.entries["quest:746"] = {n="Scavi nanici",s="Al Villaggio di Zoccolo Sanguinario, Baine Zoccolo Sanguinario teme che i cercatori facciano infuriare le bestie di Mulgore e feriscano la sua terra sacra. Chiede ai giovani difensori dell'Orda di spezzare i picconi e fermare gli scavi.",h="Al Villaggio di Zoccolo Sanguinario, Baine Zoccolo Sanguinario teme che i cercatori facciano infuriare le...",kw={"baine zoccolo sanguinario","villaggio di zoccolo sanguinario","nano","fucina","kodo","mulgore","picconi","cercatore"},ang={["class:Shaman"]="Da sciamano, sai che scavare senza cura turba il substrato roccioso, agita gli elementi e inquieta gli spiriti e le creature della terra.",["faction:Horde"]="Come membro dell'Orda, vedi nei nani dell'Alleanza che penetrano nelle terre dell'Orda una minaccia alla fragile pace che dura dalla Terza Guerra. Ignorano i confini tribali.",["profession:Mining"]="Da minatore, potresti apprezzare ciò che si cela nella pietra, ma i nani, a Mulgore, lavorano senza rispetto né armonia e si affidano alla distruzione sconsiderata.",["race:Tauren"]="Da tauren, sai che il corpo della Madre Terra è sacro. Gli stranieri che perforano le steppe di Mulgore esigono una risposta decisa."},sec={{t="Intrusione tra le colline",b="A nord-ovest del Villaggio di Zoccolo Sanguinario, dei cercatori nanici hanno segnato un sito sulle colline di Mulgore. La Lega degli Esploratori cerca in tutto Kalimdor reliquie dei titani e segreti degli earthen. Spesso, presta poca attenzione alle terre e alle usanze di chi le abita. Per i tauren, la terra è una madre vivente, da venerare anziché scavare in cerca di pietre e metalli."},{t="Difendere la terra sacra",b="Baine Zoccolo Sanguinario vede nelle macchine e nelle esplosioni dei nani una minaccia al fragile equilibrio delle pianure. Il rumore agita la fauna locale e fa infuriare i kodo. Perciò i tauren intendono distruggere i picconi dei cercatori nelle forge. Gli attrezzi rotti avvertiranno i nani e fermeranno gli scavi prima che causino danni duraturi."}},faq={{q="Perché i nani stanno scavando a Mulgore?",a="Dei cercatori nanici esplorano Mulgore in cerca di segreti e artefatti nascosti sotto terra. Le loro miniere ignorano il territorio e le usanze dei tauren, entrando così in conflitto con loro.",al={"nani a mulgore","perché i cercatori sono qui","scavi nanici a mulgore"}},{q="Chi assegna la missione Dwarven Digging?",a="Baine Zoccolo Sanguinario ti affida l'incarico al Villaggio di Zoccolo Sanguinario, nel centro di Mulgore. È il giovane figlio dell'Alto Capo Cairne Zoccolo Sanguinario.",al={"chi assegna dwarven digging","chi inizia dwarven digging"}},{q="Perché Baine vuole che i loro attrezzi vengano distrutti invece di essere semplicemente rubati?",a="Baine vuole che i picconi vengano spezzati, così da fermare subito gli scavi. Distruggerli nelle forge avvertirà i nani che la forza bruta non svelerà i segreti della terra.",al={"perché rompere i picconi","frantumare attrezzi nanici"}},{q="In che modo gli scavi influenzano la fauna di Mulgore?",a="Gli scavi e le ferite nella terra agitano le creature native di Mulgore, soprattutto i kodo che vagano per le colline. Le mandrie pacifiche diventano irritabili e aggressive.",al={"kodo arrabbiati","perché le bestie sono furiose"}},{q="Dove possono essere distrutti i picconi?",a="Puoi distruggere i picconi in una forgia funzionante. Ce n'è una nel campo di scavo dei nani e un'altra nelle fucine di Picco del Tuono.",al={"dove si trova la fucina","distruggere picconi cercatori fucina"}},{q="Questa missione è legata alla più ampia presenza della Lega degli Esploratori a Kalimdor?",a="Sì. Le spedizioni naniche da Forgiardente hanno avamposti in tutto Kalimdor, anche a Mulgore, nelle Savane e a Southern Kalimdor. Le loro rivendicazioni sulle terre e sui luoghi sacri spesso causano scontri con i popoli dell'Orda.",al={"lega degli esploratori mulgore","forgiardente in kalimdor"}}},fx={["755e231a"]={q="A cosa servono gli Utensili Rotti?",a="Gli Utensili Rotti sono la prova tangibile che hai fermato le operazioni dei nani. Invece di limitarsi a scacciare i prospettori o a sottrarre loro l'attrezzatura, Baine Zoccolo Sanguinario vuole che i loro picconi vengano spezzati a una forgia e riportati a lui, così da assicurarsi che il loro lavoro venga interrotto e che il messaggio contro la profanazione della terra sacra sia chiaro.",al={"utensili rotti","perché gli utensili rotti","scopo degli utensili rotti"}},["95107d94"]={q="Chi sono i nani che scavano a Mulgore?",a="Sono prospettori nani che hanno allestito un campo di scavo sulle colline nord-occidentali di Mulgore. Attirati da voci secondo cui sotto le pianure sarebbero sepolti antichi segreti, cercano reliquie storiche e conoscenze sui Titani, senza curarsi della profanazione spirituale che le loro cave infliggono alla terra e alla fauna selvatica.",al={"nani a mulgore","chi sono i nani che scavano","prospettori a mulgore"}}},fp="15,187,24.365.0,26.324.0,35.185.0,36.130.0,63.159.0,52.156.0,31.131.0,75.217.0"}
P.entries["quest:747"] = {n="The Hunt Begins",s="Al Campo Narache, i giovani cacciatori raccolgono cibo e piume per il loro popolo. Grull Vento Agile ti manda a cacciare zampalunga delle pianure sulla Mesa Nuvola Rossa, dove il villaggio conta su ciò che i suoi giovani possono procurare.",h="Al Campo Narache, i giovani cacciatori raccolgono cibo e piume per il loro popolo.",kw={"campo narache","capo vento agile","piume","grull vento agile","the hunt begins","mulgore","zampalunga delle pianure","mesa nuvola rossa"},ang={["class:Hunter"]="Da cacciatore, ti eserciti nella mira e nel seguire le tracce mentre dai la caccia ai veloci zampalunga delle pianure della Mesa Nuvola Rossa. Impari anche a onorare le bestie che ti sostengono.",["race:Tauren"]="Da giovane shu'halo, la tua prima caccia agli zampalunga delle pianure sulla mesa ti lega alla terra e al tuo dovere di sfamare il Campo Narache."},sec={{t="Il sostentamento di una tribù",b="I tauren cacciano sulla Mesa Nuvola Rossa per sfamare e vestire il loro popolo. Considerano l'inseguimento una prova di disciplina e uno sport. Quando le scorte del Campo Narache scarseggiano, i giovani cacciatori raccolgono carne di zampalunga delle pianure per cucinare e piume per gli abiti tribali."},{t="Guadagnarsi il riconoscimento",b="Grull Vento Agile giudica i nuovi arrivati che sperano di lasciare la Mesa Nuvola Rossa per raggiungere le vaste pianure di Mulgore. Prima che possano incontrare suo padre, il Capo Vento Agile, chiede loro di dimostrare le proprie capacità. Una caccia riuscita dimostra autosufficienza e aiuta a sostenere la tribù."}},faq={{q="Chi assegna questa missione?",a="Grull Vento Agile ti affida questo incarico al Campo Narache. Figlio del Capo Vento Agile, guida i giovani cacciatori sulla Mesa Nuvola Rossa.",al={"datore di missione","chi inizia the hunt begins","grull vento agile"}},{q="Perché vengono cacciati gli zampalunga delle pianure invece di altre bestie?",a="Sulla mesa gli zampalunga delle pianure abbondano. La loro carne rimpingua le scorte di cibo, mentre le loro piume vengono usate per gli abiti e gli ornamenti tradizionali dei tauren.",al={"perché gli zampalunga delle pianure","carne di zampalunga delle pianure e piume","cacciare zampalunga delle pianure"}},{q="Perché devo dimostrare il mio valore prima di vedere il Capo Vento Agile?",a="Grull Vento Agile ti chiede di dimostrare le tue abilità di sopravvivenza e la tua lealtà al villaggio prima di incontrare il Capo Vento Agile e assumerti responsabilità maggiori.",al={"perché dimostrare il valore al capo vento agile","approvazione del capo vento agile","perché cacciare per primi"}},{q="Qual è l'obiettivo più ampio di queste prove sulla Mesa Nuvola Rossa?",a="La Mesa Nuvola Rossa mette alla prova i giovani tauren prima che scendano verso le vaste pianure di Mulgore e raggiungano Picco del Tuono, la capitale.",al={"scopo delle prove della mesa","perché sono sulla mesa nuvola rossa","lasciare la mesa nuvola rossa"}},{q="Cosa succede dopo questa caccia?",a="Dopo che gli avrai riportato carne e piume, Grull approverà la tua caccia e ti manderà a seguire le tracce di selvaggina più grossa, difficile da trovare per la mesa.",al={"prossima missione","seguito","cosa c'è dopo the hunt begins"}},{q="I tauren cacciano solo per sopravvivenza?",a="I tauren cacciano per procurarsi cibo e materiali come pelle, ossa e piume. Cacciano anche per sport e per entrare in comunione spirituale. La caccia affina gli istinti che mantengono le loro tribù vigili e forti.",al={"filosofia di caccia tauren","caccia per sport","perché i tauren cacciano"}}},fx={["395288c5"]={q="Perché Grull Vento Agile vuole che venga fatto?",a="Grull Vento Agile vede del potenziale in te e vuole che tu dimostri il tuo valore alla tribù e a suo padre, Capo Vento Agile. Le scorte di carne del Campo Narache sono quasi esaurite e al campo servono piume fresche. Mandandoti a procurarle, mette alla prova il tuo istinto di cacciatore e rifornisce le provviste essenziali del villaggio.",al={"perché grull vuole cacciare gli zampalunga delle pianure","motivazioni di grull vento agile","perché cacciare gli zampalunga per grull"}},f26a5c4f={q="A cosa serve la Carne di Zampalunga delle Pianure?",a="La carne viene raccolta per rifornire le scorte di cibo in esaurimento del Campo Narache. Sopravvivere sulla Mesa Nuvola Rossa richiede provviste affidabili e cacciare gli zampalunga delle pianure fornisce la carne fresca necessaria a nutrire i giovani cacciatori e gli anziani che vivono al campo.",al={"a cosa serve la carne di zampalunga delle pianure","perché raccogliere carne di zampalunga delle pianure","uso della carne di zampalunga delle pianure"}},fb1052a7={q="A cosa serve la Piuma di Zampalunga delle Pianure?",a="I tauren del Campo Narache usano le piume degli zampalunga delle pianure per creare abiti e ornamenti. La tribù sfrutta ogni parte delle bestie che caccia, trasformando il robusto piumaggio in abiti pratici e ornamenti adatti alla vita sulla mesa.",al={"a cosa servono le piume di zampalunga delle pianure","perché raccogliere piume di zampalunga delle pianure","uso delle piume di zampalunga delle pianure"}}},fp="15,195,20.251.0,19.245.0,21.116.0,53.151.0,59.149.0,59.122.0,27.139.0,33.193.0"}
P.entries["quest:748"] = {n="Poison Water",s="I pozzi contaminati di Mulgore minacciano l’acqua che sostiene i tauren e la fauna locale. Mull Corno Tonante, nel Villaggio di Zoccolo Sanguinario, chiede ai giovani difensori dell’Orda di raccogliere i componenti per un totem purificatore.",h="I pozzi contaminati di Mulgore minacciano l’acqua che sostiene i tauren e la fauna locale.",kw={"villaggio di zoccolo sanguinario","totem della purificazione","mulgore","mull corno tonante","strider di pianura","poison water","lupo della prateria","pozzo degli zoccolo artico"},ang={["class:Druid"]="Da druido, sai che i goblin che avvelenano le sorgenti d’acqua dolce minacciano l’equilibrio naturale di Mulgore. Proteggi la sua fragile flora e fauna.",["class:Shaman"]="Da sciamano, ripristini l’acqua inquinata con un totem ricavato da parti di bestie, rendendo onore allo sciamanesimo tauren e al suo legame con la fauna locale.",["race:Tauren"]="Da tauren, sai che l’acqua dolce avvelenata profana i doni della Madre Terra. Purificare i pozzi è tuo dovere mentre raggiungi la maggiore età a Mulgore."},sec={{t="Una terra profanata",b="Gli intrusi goblin e i loro tirapiedi hanno contaminato i pozzi di Mulgore. L’inquinamento minaccia l’acqua che sostiene le tribù tauren e la fauna locale. Mull Corno Tonante, un anziano del Villaggio di Zoccolo Sanguinario, ha scoperto il danno. I tauren si sono stabiliti qui di recente e questi pozzi sono vitali per la vita sulle loro pianure sacre."},{t="Raccogliere l'essenza della natura",b="Mull ricorre allo sciamanesimo tauren per purificare il Pozzo degli Zoccolo Artico. Gli serve un totem rituale, realizzato con la forza delle bestie native di Mulgore. Raccogli zampe di lupo della prateria e artigli di strider di pianura adulti nelle pianure sud-occidentali. La forza stessa della terra verrà usata contro l’inquinamento."}},faq={{q="Chi ha avvelenato i pozzi d'acqua a Mulgore?",a="Gli intrusi goblin e i loro tirapiedi hanno contaminato i pozzi sacri di Mulgore, minacciando l’acqua che sostiene i tauren e la fauna locale.",al={"chi ha contaminato i pozzi","chi ha avvelenato mulgore","chi ha inquinato l'acqua"}},{q="Perché Mull Corno Tonante ha bisogno di zampe di lupo e artigli di strider di pianura?",a="Mull usa zampe di lupo della prateria e artigli di strider di pianura per creare un totem purificatore che attinge alla forza delle bestie native di Mulgore.",al={"perché le zampe di lupo","perché gli artigli di strider di pianura","materiali per il totem"}},{q="Quale pozzo prepara a purificare questa missione?",a="I componenti raccolti serviranno a creare un totem purificatore per il Pozzo degli Zoccolo Artico.",al={"per quale pozzo è","quale pozzo d'acqua"}},{q="Dove si trova Mull Corno Tonante?",a="Mull Corno Tonante si trova nel Villaggio di Zoccolo Sanguinario, il principale insediamento tauren nel centro di Mulgore, vicino al Lago Toro di Pietra.",al={"posizione di mull corno tonante","dov'è mull","dove consegnare poison water"}},{q="Dove si possono trovare i lupi e gli strider di pianura necessari?",a="I lupi della prateria e gli strider di pianura adulti vagano per le pianure a sud-ovest del Villaggio di Zoccolo Sanguinario.",al={"dove trovare i lupi della prateria","posizione degli strider di pianura","zone di caccia"}},{q="Cosa succede dopo che Mull riceve le zampe e gli artigli?",a="Mull lega le zampe e gli artigli in un Totem Purificatore degli Zoccolo Artico, poi ti manda al Pozzo degli Zoccolo Artico per compiere il rito di purificazione.",al={"prossima missione dopo poison water","cosa devo fare dopo"}}},fx={["50414ce1"]={q="Perché Mull Corno Tonante vuole che venga fatto?",a="I goblin e i loro mercenari hanno contaminato i sacri pozzi di Mulgore, colpendo il cuore stesso della terra natale dei tauren. Per Mull Corno Tonante e gli abitanti del Villaggio di Zoccolo Sanguinario, lasciare i pozzi contaminati significa esporre la gente alle malattie e profanare il sacro equilibrio della terra. Purificarli è un dovere spirituale e pratico urgente.",al={"motivazioni di mull corno tonante","perché purificare i pozzi d'acqua","perché la missione poison water"}}},fp="12,192,17.320.0,26.311.0,40.142.0,65.130.0,46.77.0,34.109.0,58.86.0,53.143.0"}
P.entries["quest:749"] = {n="La Carovana Depredata",s="Vicino al Lago Toro di Pietra, la Carovana Depredata attira ancora gli sciacalli della S.P.R. & Co. I guerrieri tauren hanno incendiato il convoglio dopo aver perso dei compagni in una scaramuccia. Le casse intatte mostrano la portata delle operazioni della S.P.R. & Co. a Mulgore.",h="Vicino al Lago Toro di Pietra, la Carovana Depredata attira ancora gli sciacalli della S.P.R.",kw={"morin bracca nubi","mulgore","carovana depredata","lago toro di pietra","cassa di rifornimenti","s.p.r. & co."},ang={["faction:Horde"]="L'espansione incontrollata delle compagnie a Mulgore minaccia la stabilità del Picco del Tuono, perciò gli esploratori dell'Orda devono interrompere le operazioni logistiche della S.P.R. & Co.",["profession:Mining"]="Le robuste casse e le note logistiche mostrano le aggressive operazioni di prospezione ed estrazione mineraria della S.P.R. & Co. in tutta Mulgore.",["race:Tauren"]="Le macchine della S.P.R. & Co. profanano le pianure, e il disboscamento colpisce direttamente la tua terra ancestrale. Recuperare e distruggere i suoi rifornimenti aiuta a difendere Mulgore."},sec={{t="Ritorsione al Lago",b="I guerrieri tauren hanno incendiato un convoglio della S.P.R. & Co. dopo aver perso due compagni in una scaramuccia precedente. Morin Bracca Nubi e i suoi guerrieri hanno attaccato rapidamente, poi hanno dato fuoco ai carri per scacciare gli intrusi armati. Hanno lasciato indietro il relitto, convinti che le fiamme avrebbero consumato tutto ciò che i goblin erano venuti a trasportare."},{t="Affari in Sospeso",b="Gli sciacalli della S.P.R. & Co. sono tornati tra i resti anneriti, segno che l'incendio non ha distrutto tutto il carico. Morin manda degli esploratori a ispezionare i resti, invece di rischiare altre vite alla cieca. Tra le macerie macchiate di fuliggine, alcune casse intatte recano l'insegna della Venture Company Mining. Sono imballate per la spedizione agli impianti di lavorazione centrali."}},faq={{q="Perché la carovana è stata distrutta?",a="Morin Bracca Nubi e i suoi guerrieri tauren hanno teso un'imboscata alla carovana e l'hanno incendiata per vendicare la morte di due loro esploratori, uccisi in una precedente scaramuccia con la S.P.R. & Co.",al={"chi ha distrutto la carovana","perché la carovana è bruciata","attacco alla carovana"}},{q="Dov'è situata la Carovana Depredata?",a="I carri bruciati giacciono lungo la sponda settentrionale del Lago Toro di Pietra, a est del Villaggio di Zoccolo Sanguinario, a Mulgore.",al={"posizione della carovana","dov'è la carovana","luogo della carovana depredata"}},{q="Perché i goblin stanno tornando al relitto?",a="La S.P.R. & Co. ha inviato degli sciacalli perché il fuoco non ha distrutto tutto il suo carico. Vogliono recuperare robuste casse di rifornimenti destinate ai suoi impianti centrali di lavorazione.",al={"perché ci sono gli sciacalli","sciacalli della s.p.r. & co.","cosa vogliono i goblin"}},{q="Cosa c'è dentro le casse di rifornimenti?",a="Le casse recano l'insegna della Venture Company Mining e contengono risorse minerarie destinate alla raffinazione e alla lavorazione nei principali impianti industriali della compagnia.",al={"contenuto delle casse","cosa c'è nella cassa","cassa di rifornimenti sigillata"}},{q="Chi è Morin Bracca Nubi?",a="Morin Bracca Nubi è un esploratore e segugio tauren di stanza a est del Villaggio di Zoccolo Sanguinario. Sorveglia le incursioni nemiche nell'entroterra di Mulgore, in particolare quelle della S.P.R. & Co.",al={"chi è morin","ruolo di morin bracca nubi"}},{q="Cosa rivela questa carovana sulla S.P.R. & Co.?",a="La carovana dimostra che la presenza della S.P.R. & Co. a Mulgore va ben oltre una semplice squadra esplorativa. Si tratta di un'attività organizzata di estrazione industriale, con linee di rifornimento armate e reti di raffinazione centralizzate.",al={"presenza della s.p.r. & co. a mulgore","perché i goblin sono a mulgore"}}},fx={["89fc7cfd"]={q="Perché Morin Bracca Nubi vuole che le casse del carico siano esaminate?",a="Morin e i suoi guerrieri hanno teso un'imboscata alla carovana della S.P.R. & Co. presso il Lago Toro di Pietra per vendicare i compagni caduti, bruciando i carri e credendo che il fuoco avrebbe distrutto tutto ciò che poteva essere utile. Quando ha visto i goblin recuperare oggetti tra i rottami, ha capito che qualcosa di prezioso o pericoloso era sopravvissuto alle fiamme. Ha bisogno che tu esamini le casse per scoprire cosa trasportava la S.P.R. & Co. attraverso Mulgore e perché i suoi membri siano così ansiosi di recuperarlo.",al={"perché esaminare la carovana","motivazioni di morin bracca nubi","perché cercare le casse dei rifornimenti"}}},fp="19,223,23.315.0,19.356.0,30.176.0,37.100.0,46.185.0,33.171.0,26.185.0,56.206.0"}
P.entries["quest:7493"] = {n="Il viaggio è appena cominciato",s="\"Il viaggio è appena iniziato\" è una missione dell'Orda offerta a Orgrimmar ai conciatori esperti dopo la sconfitta di Onyxia. Il Sovrano Runthak riconosce l'abilità dell'eroe e trasmette la rara tecnica necessaria per forgiare mantelli protettivi dalle scaglie della madre della nidiata. Questo mestiere vitale prepara l'Orda alle fiamme mortali dei Bastioni di Roccianera.",h="\"Il viaggio è appena iniziato\" è una missione dell'Orda offerta a Orgrimmar ai conciatori esperti dopo la...",kw={"roccianera","madre della nidiata","mantello","concia pelli","runthak","nefarian","onyxia","scaglia"},ang={["faction:Horde"]="Per l'Orda, assicurarsi equipaggiamento protettivo forgiato dai nemici caduti è vitale per salvaguardare le proprie forze contro ulteriori devastazioni draconiche."},sec={{t="L'eredità di una madre",b="La caduta di Onyxia rappresenta un trionfo per l'Orda, ma non segna la fine della minaccia posta dal volo dei draghi neri. La pelle squamosa della madre della nidiata possiede una notevole resistenza contro la fiamma draconica. Invece di lasciare che tali materiali vadano sprecati, la leadership dell'Orda cerca artigiani capaci di trasformare i resti del drago in armature difensive."},{t="Scudo contro la Fiamma d'Ombra",b="Il Sovrano Runthak insegna ai conciatori dotati come cucire il Mantello di Scaglie di Onyxia. Questa conoscenza non è destinata solo all'esibizione o al prestigio. Nel profondo del Massiccio Roccianera, il fratello di Onyxia, Nefarian, brandisce un devastante soffio incendiario. Senza la protezione incantata offerta dalle scaglie della loro stessa madre, qualsiasi avanguardia che affrontasse il Signore di Roccianera verrebbe ridotta in cenere."}},faq={{q="Chi offre questa missione e dove si trova?",a="La missione è fornita dal Sovrano Runthak a Orgrimmar. Egli riconosce i campioni dell'Orda che possiedono una maestria nella concia delle pelli e che hanno contribuito alla caduta di Onyxia.",al={"runthak datore missione","dove si trova il sovrano runthak","inizio missione"}},{q="Quale requisito è necessario per ricevere questa missione?",a="Questa missione è offerta solo ai conciatori esperti che hanno completato le trionfali conseguenze della sconfitta di Onyxia, come 'Vittoria per l'Orda' o 'Una circostanza alquanto sconcertante'.",al={"requisito concia pelli","come ottenere missione","prerequisiti"}},{q="Cosa insegna il Sovrano Runthak?",a="Il Sovrano Runthak istruisce il conciatore nella tecnica necessaria per forgiare il Mantello di Scaglie di Onyxia usando le scaglie raccolte dalla madre della nidiata caduta.",al={"ricetta ricompensa missione","cartamodello mantello di onyxia","cosa imparo"}},{q="Perché il Mantello di Scaglie di Onyxia è importante?",a="Il mantello protegge chi lo indossa dal soffio mortale e incendiario di Nefarian, il Signore di Roccianera. Senza le sue proprietà protettive uniche, affrontare il padrone della nidiata si rivelerebbe fatale.",al={"perché creare il mantello","scopo del mantello","mantello di nefarian"}},{q="Chi è il Signore di Roccianera?",a="Il Signore di Roccianera è Nefarian, un potente drago nero e fratello di Onyxia, che trama dalle vette del Massiccio Roccianera per dominare le razze mortali.",al={"chi è il signore di roccianera","identità di nefarian","signore roccianera"}},{q="Perché la missione afferma che il viaggio è appena iniziato?",a="Sebbene Onyxia sia stata uccisa, la guerra più ampia contro il volo dei draghi neri e le macchinazioni di Nefarian all'interno del Massiccio Roccianera si è solo intensificata.",al={"significato del titolo","perché il viaggio è appena iniziato"}}},fx={cb1b5404={q="Perché Overlord Runthak vuole che venga fatto?",a="Overlord Runthak vuole annientare completamente la Stirpe dei Draghi Neri. La sconfitta di Onyxia è stata una vittoria memorabile, ma la sua progenie infesta ancora il regno agli ordini di suo fratello, Nefarian. Insegnando l'antica tecnica per forgiare mantelli protettivi dalle scaglie della madre della covata, Runthak fa sì che i campioni dell'Orda dispongano della protezione indispensabile per resistere alla letale Fiamma d'Ombra di Nefarian e porre fine alla guerra.",al={"perché runthak assegna questa missione","motivazioni di overlord runthak","obiettivo di runthak"}}},fp="26,347,22.359.0,27.396.1,49.178.0,49.183.0,33.152.0,40.186.0,29.159.0,57.145.0"}
P.entries["quest:7497"] = {n="Il viaggio è appena cominciato",s="A Roccavento, il Maggiore Mattingly rende onore all'artigiano che ha sconfitto Onyxia. Gli insegna a creare un mantello dalle sue scaglie.",h="A Roccavento, il Maggiore Mattingly rende onore all'artigiano che ha sconfitto Onyxia.",kw={"volo dei draghi neri","roccianera","conceria","maggiore mattingly","nefarian","onyxia","mantello di scaglie di onyxia","roccavento"},ang={["faction:Alliance"]="Come eroe dell'Alleanza, porti la vittoria di Roccavento su Onyxia nella prossima offensiva contro suo fratello Nefarian al Massiccio Roccianera."},sec={{t="Una Maestria Rara",b="Pochi tra coloro che hanno sconfitto Onyxia sanno lavorare la sua pelle. Quando un maestro conciatore si presenta al Maggiore Mattingly a Roccavento, l'ufficiale capisce quanto questa abilità potrà contare nelle battaglie future."},{t="Protezione contro il Volo dei Draghi Neri",b="La morte di Onyxia lascia il volo dei draghi neri come una minaccia. Il Maggiore Mattingly insegna all'artigiano a trattare e cucire le sue scaglie per creare un Mantello di Scaglie di Onyxia. Protegge dal respiro infuocato di suo fratello, Nefarian, il Signore di Roccianera."}},faq={{q="Chi offre la missione Il Viaggio è Appena Iniziato?",a="Il Maggiore Mattingly a Roccavento offre queste conoscenze agli eroi dell'Alleanza che hanno combattuto nella campagna contro Onyxia e padroneggiano la lavorazione delle pelli.",al={"chi offre il viaggio è appena iniziato","dove trovare il viaggio è appena iniziato","chi dà la missione il viaggio è appena iniziato"}},{q="Cosa insegna questa missione?",a="Il Maggiore Mattingly insegna ai maestri conciatori a creare un Mantello di Scaglie di Onyxia dalle scaglie di Onyxia.",al={"quale ricetta ottengo","ricetta mantello di onyxia","ricompensa per il viaggio è appena iniziato"}},{q="Perché il Mantello di Scaglie di Onyxia è necessario?",a="Il Mantello di Scaglie di Onyxia protegge chi lo indossa dal respiro infuocato di Nefarian, il Signore di Roccianera.",al={"perché ho bisogno del mantello di onyxia","a cosa serve il mantello di scaglie di onyxia","protezione da fiamma d'ombra"}},{q="Chi è il Signore di Roccianera citato dal Maggiore Mattingly?",a="Nefarian è il Signore di Roccianera, un potente drago nero e fratello di Onyxia. Governa i Bastioni di Roccianera e porta avanti i piani del volo dei draghi neri.",al={"chi è il signore di roccianera","chi è nefarian","avvertimento di mattingly sui draghi"}},{q="Perché l'eroe deve essere un conciatore per ricevere questa conoscenza?",a="Un maestro conciatore possiede l'abilità avanzata necessaria per lavorare le scaglie di drago senza distruggerne la protezione magica.",al={"perché solo conceria","chiunque può ottenere questa missione","requisito conceria"}},{q="La morte di Onyxia risolve la minaccia dei draghi neri a Roccavento?",a="No. Onyxia è morta, ma suo fratello Nefarian controlla ancora il Massiccio Roccianera e trama contro l'Alleanza e le razze mortali.",al={"roccavento è al sicuro ora","onyxia morta cosa succede dopo","volo dei draghi neri dopo onyxia"}}},fx={b42a6800={q="Perché il Maggiore Mattingly ti trasmette questa conoscenza?",a="Il Maggiore Mattingly sa che uccidere Onyxia è stato solo il primo attacco. La madre della covata è morta, ma i suoi parenti minacciano ancora Azeroth dalle alture del Massiccio Roccianera. Per eliminare i draghi neri rimasti, i campioni devono sopravvivere alle fiamme ardenti di Nefarian. Mattingly condivide questa tecnica speciale affinché gli eroi dell'Alleanza possano fabbricare mantelli protettivi con le scaglie di Onyxia e porre fine alla guerra.",al={"perché mattingly ti insegna","motivazioni del maggiore mattingly","motivo di mattingly"}}},fp="26,129,14.184.0,41.232.1,48.150.0,27.97.0,40.99.0,58.153.0,63.116.0,65.131.1"}
P.entries["quest:75"] = {n="Leggenda di Stalvan",s="A Elwynn, la tua ricerca di The Legend of Stalvan ti conduce alla casa di Marshal Haggard. La vista sempre più debole del veterano ha lasciato il baule al piano di sopra, pieno di carte, senza che nessuno ne leggesse il contenuto.",h="A Elwynn, la tua ricerca di The Legend of Stalvan ti conduce alla casa di Marshal Haggard.",kw={"boscovespro","foresta di elwynn","pagina di diario sbiadita","spirito infausto","marshal haggard","stalvan"},ang={["faction:Alliance"]="Ripercorrere il passato di Stalvan ti porta a scoprire la storia più oscura nascosta tra le pacifiche fattorie di Elwynn.",["race:Human"]="Da umano, segui Stalvan attraverso insediamenti familiari e scopri come l'isolamento e la malvagità possano celarsi sotto gli occhi di tutti."},sec={{t="La Soffitta di un Veterano",b="Marshal Haggard vive vicino al margine sud-orientale della Foresta di Elwynn, nei pressi di Boscovespro e Redridge. Al piano di sopra, un vecchio baule custodisce pergamene che trovò quando si trasferì nella sua casa isolata. La vista sempre più debole gli impedì di leggerle, e sono rimaste intatte finché non hai chiesto di Stalvan."},{t="Ombre Persistenti",b="Le carte nel baule al piano di sopra di Haggard risvegliano una forza inquieta legata al passato di Stalvan. Quando disturbi i suoi effetti personali, appare uno Spirito Infausto. Tra le carte, una Pagina di Diario reca le parole di Stalvan e rivela che lo studioso recluso lasciò il segno a Elwynn prima di scomparire."}},faq={{q="Chi è il Marshal Haggard?",a="Marshal Haggard è un veterano anziano che vive in una baita isolata nella parte sud-orientale della Foresta di Elwynn. La sua casa custodisce vecchie carte appartenute a Stalvan Mistmantle.",al={"marshal haggard","haggard elwynn","chi è haggard"}},{q="Perché le tracce portano alla Foresta di Elwynn?",a="Gli indizi raccolti a Borgoscuro e Rivoluna ripercorrono i viaggi di Stalvan attraverso i territori meridionali di Roccavento. La casa di Haggard custodisce le carte che Stalvan ha lasciato.",al={"perché foresta di elwynn","stalvan elwynn","perché andare da haggard"}},{q="Cosa c'è dentro il baule al piano di sopra?",a="Tra le pergamene che Haggard non riuscì mai a esaminare per bene, il baule al piano di sopra custodisce una Pagina di Diario Sbiadita scritta da Stalvan Mistmantle.",al={"baule al piano di sopra","pagina di diario sbiadita","cosa c'è nel baule"}},{q="Perché uno spirito attacca quando il baule viene aperto?",a="Uno Spirito Infausto infesta i cimeli del passato di Stalvan. Attacca quando un estraneo disturba i suoi scritti e i suoi ricordi.",al={"spirito infausto","perché il fantasma attacca","fantasma nella casa di haggard"}},{q="Come fa questo a far avanzare l'indagine su Stalvan?",a="La pagina sbiadita offre una testimonianza diretta, scritta di pugno da Stalvan, che ti aiuta a ricostruire il suo passato.",al={"mistero di stalvan","cosa rivela la pagina","fase della missione di stalvan"}},{q="Perché il Marshal Haggard non riusciva a leggere i documenti da solo?",a="L'età ha indebolito e offuscato la vista di Haggard. Non riusciva a leggere la minuta scrittura sbiadita sulle vecchie carte.",al={"haggard cieco","perché haggard ha bisogno di aiuto"}}},fx={["7284e072"]={q="Perché Marshal Haggard vuole che venga fatto?",a="Marshal Haggard è un vecchio soldato che vive una tranquilla pensione, ma conserva ancora l'istinto di un ufficiale del regno. Quando vai da lui in cerca della verità su Stalvan Mistmantle, ricorda le pergamene abbandonate nel baule quando prese possesso della casa. Anche se il mistero oscuro non lo riguarda personalmente, vuole aiutarti nelle indagini come meglio può, anche se la vista ormai debole gli impedisce di esaminare i documenti da sé.",al={"perché aiutare haggard","motivazioni di marshal haggard","perché haggard vuole il diario"}}},fp="21,157,17.291.0,17.283.1,23.159.0,45.144.0,34.136.0,50.115.0,48.100.1,53.117.0"}
P.entries["quest:750"] = {n="The Hunt Continues",s="Grull Vento Agile manda giovani cacciatori sulle colline meridionali della Mesa Nuvola Rossa a caccia di pelli di puma di montagna. Le pelli vestiranno i bambini della tribù e aiuteranno a rammendare le tende.",h="Grull Vento Agile manda giovani cacciatori sulle colline meridionali della Mesa Nuvola Rossa a caccia di...",kw={"campo narache","capo vento agile","grull vento agile","pelli di puma di montagna","mesa nuvola rossa","caccia tauren","the hunt continues"},ang={["class:Hunter"]="Da cacciatore impari il modo di cacciare delle pianure: seguire le bestie con uno scopo, prendere solo ciò che serve e non trattarle mai come un passatempo o un trofeo.",["race:Tauren"]="Da giovane tauren che raggiunge la maturità sulla Mesa Nuvola Rossa, impari a usare ogni parte di una bestia per la tribù, dal cibo ai vestiti e al riparo. È un rito di passaggio essenziale."},sec={{t="Lo scopo della caccia",b="A Campo Narache, Grull Vento Agile manda giovani cacciatori a sud, sulle colline della Mesa Nuvola Rossa, a caccia di puma di montagna. Non si cercano trofei. La caccia insegna ai giovani a provvedere alla comunità."},{t="Rifugio per la tribù",b="A Campo Narache servono le pelli per confezionare vestiti per i bambini della tribù e rammendare le tende di pelle logore. Quando le riporterai, gli anziani ti saranno grati per il tuo contributo. Grull promette di raccontare a suo padre, il Capo Vento Agile, ciò che hai fatto."}},faq={{q="Perché la tribù ha bisogno di pelli di puma di montagna?",a="Alla tribù servono pelli di puma di montagna per confezionare vestiti per i bambini e riparare le tende del villaggio a Campo Narache. Grull Vento Agile dice che servono per entrambe le cose.",al={"perché cacciare i puma","a cosa servono le pelli di puma","uso pelli di puma di montagna"}},{q="Chi offre questa missione?",a="Grull Vento Agile propone la caccia a Campo Narache. È un cacciatore di spicco e il figlio del Capo Vento Agile, e guida i giovani cacciatori nel sostegno all'insediamento.",al={"chi dà the hunt continues","datore di missioni campo narache"}},{q="Dove si trovano i puma di montagna?",a="I puma di montagna vagano per le colline a sud di Campo Narache, sulla Mesa Nuvola Rossa.",al={"dove sono i puma","posizione puma di montagna","dove trovare il puma di montagna"}},{q="Qual è il legame tra Grull Vento Agile e il Capo Vento Agile?",a="Grull Vento Agile è il figlio del Capo Vento Agile, il capo tribù di Campo Narache. Grull promette di parlare a suo padre delle tue imprese, se porterai le pelli necessarie.",al={"come impressionare il capo vento agile","figlio del capo vento agile"}},{q="Cosa insegna questa caccia sulla tradizione dei tauren?",a="Tra i tauren, la caccia non è uno sport né una ricerca di trofei. Usare la pelle, la carne e le ossa di una bestia per sostenere la comunità onora le pianure e aiuta la tribù a sopravvivere.",al={"filosofia di caccia tauren","perché cacciare a mulgore"}},{q="Perché le pelli di puma di montagna sono considerate molto preziose?",a="Le pelli di puma di montagna sono spesse e resistenti, adatte a proteggere dalle intemperie delle pianure. Scaldano i bambini e aiutano a rattoppare le abitazioni, perciò gli anziani del villaggio le apprezzano molto.",al={"le pelli di puma sono preziose","perché le pelli di puma sono apprezzate"}}},fp="18,171,23.211.0,21.244.0,46.168.0,22.161.0,37.72.0,54.165.0,49.173.0,55.171.0"}
P.entries["quest:751"] = {n="La Carovana Depredata",s="A Mulgore, la Carovana Depredata lascia ai Corridori di Zoccolo Sanguinario la prova di una presenza illegale nel territorio dei tauren. La S.P.R. & Co. sta depredando le ricchezze minerarie della terra e i Corridori si preparano a difendere le loro pianure ancestrali.",h="A Mulgore, la Carovana Depredata lascia ai Corridori di Zoccolo Sanguinario la prova di una presenza illegale...",kw={"villaggio di zoccolo sanguinario","morin bracca nubi","mulgore","corridori","carovana depredata","cassa di rifornimenti","s.p.r. & co.","documenti s.p.r. & co."},ang={["class:Druid"]="Come druido, consideri sacro l'equilibrio della terra. Le miniere a cielo aperto della S.P.R. & Co., distruttive e avvolte dal fumo, sono una profanazione da purificare.",["faction:Horde"]="Come membro dell'Orda, sai che la sua sicurezza dipende dalla lealtà e dalla stabilità di Mulgore. I cartelli mercantili stranieri che devastano le sue colline minacciano lo stesso Picco del Tuono.",["profession:Mining"]="Come minatore, puoi capire che i minerali di alta qualità stipati nella cassa provano l'esistenza di ricchi filoni sotterranei sotto le colline orientali di Mulgore, che attirano stranieri desiderosi di sfruttarli.",["race:Tauren"]="Come tauren, potresti vedere nei macchinari rozzi che scavano nelle pianure ancestrali di Mulgore un affronto alla Madre Terra e un atto di guerra contro la pace appena conquistata."},sec={{t="Prove di Sfruttamento",b="A est del Villaggio di Zoccolo Sanguinario, una carovana depredata giace accanto alla strada. In una Cassa di Rifornimenti sigillata ci sono minerali estratti e una fascina di documenti della S.P.R. & Co. Le carte provano che la compagnia ha iniziato a scavare in profondità nelle tranquille valli di Mulgore senza permesso."},{t="La Veglia dei Corridori",b="Morin Bracca Nubi e i suoi compagni Corridori sorvegliano con attenzione i confini di Mulgore. Temono che fazioni esterne sfruttino la loro pacifica patria. Quando Morin riceve i documenti recuperati, questi confermano i suoi peggiori timori. Il fumo che si leva sulle colline orientali segnala un'invasione commerciale sempre più grave. I tauren devono respingere i Profanatori prima che le loro colline vengano completamente sventrate."}},faq={{q="Cosa c'è dentro la Cassa di Rifornimenti sigillata?",a="La Cassa di Rifornimenti sigillata contiene minerali estratti e grezzi accanto a una fascina di documenti della S.P.R. & Co. che ne descrivono le operazioni.",al={"bottino cassa di rifornimenti","cosa c'è nella cassa","contenuto della cassa"}},{q="Chi è Morin Bracca Nubi?",a="Morin Bracca Nubi è un Corridore tauren di stanza sulla strada a est del Villaggio di Zoccolo Sanguinario, verso il confine con le Savane. Pattuglia Mulgore e tiene traccia delle minacce straniere.",al={"chi è morin","ruolo di morin bracca nubi","corridore morin"}},{q="Perché la S.P.R. & Co. è a Mulgore?",a="La S.P.R. & Co. vuole sfruttare le risorse naturali e i filoni minerari di Mulgore, scavando nelle colline senza riguardo per la terra o per chi la abita.",al={"perché i goblin sono qui","obiettivo s.p.r. & co. mulgore","cosa vogliono i goblin"}},{q="Da dove veniva la carovana?",a="La carovana apparteneva alla S.P.R. & Co. Trasportava minerali estratti e documenti operativi dalle attività della compagnia ai piedi delle colline, prima di essere distrutta lungo il sentiero.",al={"di chi era la carovana","origine della carovana","chi ha attaccato la carovana"}},{q="Dove porta questa indagine?",a="Con i documenti alla mano, Morin Bracca Nubi ordina ai guerrieri di affrontare i capi della S.P.R. & Co. e smantellarne le attività minerarie nelle colline orientali.",al={"what comes next","prossima missione dopo carovana depredata","seguire le tracce della carovana"}},{q="Perché questo minaccia i tauren?",a="I tauren considerano sacra la terra e venerano la Madre Terra. Le irresponsabili miniere a cielo aperto e l'inquinamento industriale della S.P.R. & Co. deturpano il paesaggio incontaminato di Mulgore.",al={"perché ai tauren importa","minaccia s.p.r. & co.","minaccia per mulgore"}}},fp="19,239,24.279.0,21.389.0,39.132.0,26.162.0,38.150.0,32.175.0,40.169.1,34.170.0"}
P.entries["quest:752"] = {n="A Humble Task",s="Sulla Mesa Nuvola Rossa, Capo Vento Agile chiede a un giovane avventuriero di cercare sua madre. Le urgenti questioni tribali lo trattengono a Campo Narache, così ti manda a sud-est, al pozzo dove Madre Anziana Vento Agile è andata a prendere acqua.",h="Sulla Mesa Nuvola Rossa, Capo Vento Agile chiede a un giovane avventuriero di cercare sua madre.",kw={"a humble task","campo narache","capo vento agile","madre anziana vento agile","mulgore","mesa nuvola rossa","pozzo d'acqua"},ang={["faction:Horde"]="I tranquilli doveri pastorali di Narache mostrano la vita comunitaria dei tauren, in contrasto con la dura lotta per la sopravvivenza che si trova nell'Orda nascente.",["race:Tauren"]="Per i giovani guerrieri tauren, rispondere alla chiamata del capo dimostra rispetto per gli anziani e dedizione al benessere comune della tribù, secondo gli insegnamenti della Earth Mother."},sec={{t="Armonia e dovere comunitario",b="Ogni membro della tribù deve contribuire alla sua armonia e fare la propria parte. Per i giovani tauren, il dovere inizia prendendosi cura della comunità, non solo dimostrando prodezza contro i quilboar o i predatori. Capo Vento Agile è vincolato al suo posto dal compito di guidare e difendere il campo. Perciò affida ai giovani avventurieri la custodia degli anziani."},{t="Il pozzo a sud-est di Campo Narache",b="I pozzi oltre l'accampamento forniscono acqua alla Mesa Nuvola Rossa. Madre Anziana Vento Agile ha lasciato Campo Narache di buon mattino per attingere acqua fresca da una sorgente a sud-est dell'accampamento. La fauna selvatica territoriale e i quilboar Spinacollo si aggirano per la regione. Quando un'anziana resta lontana per ore, Capo Vento Agile si preoccupa e ti manda a verificare che non le sia successo nulla."}},faq={{q="Chi offre questa missione e dove posso trovarlo?",a="Capo Vento Agile, guida di Campo Narache sulla Mesa Nuvola Rossa, a Mulgore, propone l'incarico. Si trova nel padiglione centrale del campo, dove si occupa degli affari locali.",al={"chi assegna a humble task","dove prendere la missione","posizione capo vento agile"}},{q="Dove si trova Madre Anziana Vento Agile?",a="Madre Anziana Vento Agile si trova al pozzo appena a sud-est di Campo Narache, nella parte bassa della mesa.",al={"posizione madre anziana vento agile","dove si trova la madre","posizione pozzo d'acqua"}},{q="Perché il Capo Vento Agile non controlla sua madre di persona?",a="Capo Vento Agile deve restare a Campo Narache per occuparsi delle urgenti questioni tribali e guidare i giovani guerrieri. Come capo, si fida della tribù perché si prenda cura dei suoi membri e affida ai giovani avventurieri gli affari del villaggio.",al={"perché il capo non può andare","perché vento agile non controlla","capo vento agile occupato"}},{q="Madre Anziana Vento Agile è in pericolo al pozzo?",a="Aggressivi puma di montagna e strider si aggirano per le pianure circostanti, ma Madre Anziana Vento Agile è al sicuro accanto al pozzo. È piacevolmente sorpresa che qualcuno si sia preso la briga di controllare come sta un'anziana.",al={"è al sicuro","madre anziana è attaccata","pericolo al pozzo d'acqua"}},{q="Quale significato culturale ha questa missione per i tauren?",a="La cultura tauren dà valore alla famiglia, a una comunità unita e al rispetto per gli anziani. I giovani eroi imparano che la forza sta nel servire con umiltà e proteggere i propri cari, non nel cercare la gloria personale.",al={"cultura tauren a humble task","perché è un compito umile","anziani tauren"}},{q="Cosa succede dopo aver trovato Madre Anziana Vento Agile?",a="Dopo aver parlato con Madre Anziana Vento Agile, ti chiede un altro favore: aiutarla a riportare al campo la Brocca d'Acqua piena.",al={"missione successiva","seguito di a humble task","cosa fare dopo aver trovato la madre"}}},fx={b1d313d3={q="Perché Capo Vento Agile vuole che tu controlli come sta sua madre?",a="Sua madre anziana ha lasciato il Campo Narache di prima mattina per attingere acqua dal pozzo a sud-est e manca da parecchio tempo. La vita dei tauren si fonda sulla responsabilità condivisa e sull'aiuto reciproco, quindi Vento Agile è preoccupato per lei, ma i suoi doveri di capo lo trattengono al campo.",al={"perché vento agile vuole che venga fatto","motivazioni di capo vento agile","perché controllare come sta madre anziana vento agile"}}},fp="13,221,25.328.0,29.371.0,47.153.0,38.101.0,55.229.0,46.204.0,64.185.0,48.116.0"}
P.entries["quest:753"] = {n="A Humble Task",s="A Mesa Nuvola Rossa, i giovani tauren portano l'acqua del pozzo a Campo Narache su richiesta di Madre Anziana Vento Agile. Il lavoro insegna loro l'umiltà e la cura per la tribù.",h="A Mesa Nuvola Rossa, i giovani tauren portano l'acqua del pozzo a Campo Narache su richiesta di Madre Anziana...",kw={"campo narache","capo vento agile","madre anziana vento agile","a humble task","mulgore","mesa nuvola rossa","rites of the earthmother","brocca d'acqua"},ang={["faction:Horde"]="Come membro dell'Orda, vedi come la famiglia Vento Agile insegna ai tauren la solidarietà e la sopravvivenza a Mulgore, una regione pacifica ma risoluta dell'Orda di Thrall.",["race:Tauren"]="Come tauren, portare acqua agli anziani dimostra il tuo spirito di comunità e la tua prontezza a seguire il cammino della Madre Terra."},sec={{t="Vitalità della Gioventù",b="Madre Anziana Vento Agile si occupa dei suoi doveri accanto al pozzo, sul margine meridionale di Mesa Nuvola Rossa. L'età l'ha rallentata, anche se ha percorso molti sentieri attraverso le pianure. Quando incontra giovani tauren che sperano di difendere il proprio popolo, indirizza le loro energie verso i bisogni della comunità. Servire gli altri permette loro di dimostrare il proprio valore prendendosene cura."},{t="Servire la tribù",b="Porti una brocca piena verso nord-ovest, fino a Campo Narache, e la consegni a Capo Vento Agile, guida dell'insediamento e figlio di Madre Anziana Vento Agile. Nelle aride pianure di Mulgore, la vita dipende dal lavoro condiviso e da scorte costanti di acqua fresca. Farsi carico di un peso per un anziano dimostra rispetto per chi, prendendosi cura della tribù, la tiene unita."},{t="Un cammino verso Picco del Tuono",b="Quando porti l'acqua di sua madre a Campo Narache, Capo Vento Agile vede più di una semplice faccenda portata a termine. L'usanza tauren vuole che chi desidera difendere il proprio popolo in terre lontane cominci con umiltà e disponibilità ad aiutare. La tua silenziosa disciplina colpisce il capo. Ti raccomanda per i Rites of the Earthmother, prove spirituali che aprono le porte di Picco del Tuono."}},faq={{q="Chi è Madre Anziana Vento Agile?",a="Madre Anziana Vento Agile è un'anziana della famiglia Vento Agile e si occupa del pozzo a Mesa Nuvola Rossa. È la madre di Capo Vento Agile e insegna ai giovani tauren l'umiltà e la cura per la tribù.",al={"madre anziana vento agile","chi assegna a humble task","anziana vento agile"}},{q="Dove si trova il pozzo d'acqua?",a="Il pozzo si trova a sud-est di Campo Narache, nelle pianure erbose di Mesa Nuvola Rossa. Accanto al pozzo ci sono brocche d'acqua fresca che viaggiatori e custodi dell'accampamento possono portare con sé.",al={"posizione del pozzo d'acqua","dove si trova il pozzo","trovare la brocca d'acqua"}},{q="Chi è Capo Vento Agile?",a="Capo Vento Agile guida Campo Narache a Mesa Nuvola Rossa. Dirige l'addestramento e i riti spirituali dei giovani tauren mentre si preparano a servire la tribù più ampia a Mulgore.",al={"capo vento agile","chi è il capo","leader di campo narache"}},{q="Perché questa faccenda è trattata come una prova importante?",a="I tauren danno valore all'umiltà, alla cura della comunità e al rispetto per gli anziani. I doveri quotidiani dimostrano che hai a cuore il tuo popolo tanto quanto la gloria in battaglia.",al={"perché trasportare acqua","perché a humble task","questa missione è importante"}},{q="Cosa viene dopo aver completato A Humble Task?",a="Dopo aver portato l'acqua, Capo Vento Agile ti indirizza ai Rites of the Earthmother, prove tradizionali per i tauren che raggiungono la maggiore età.",al={"what comes next","missione successiva","dopo a humble task"}},{q="Dove porta alla fine questo sentiero?",a="Il rispetto degli anziani ti prepara a lasciare Mesa Nuvola Rossa e ad attraversare Mulgore in direzione di Picco del Tuono, sulle alte mesa della capitale.",al={"destinazione futura","dove stiamo andando","obiettivo picco del tuono"}}},fx={["57bce500"]={q="Perché Madre Anziana Vento Agile vuole che venga fatto?",a="Madre Anziana Vento Agile ammette che le sue gambe, ormai anziane, non hanno più il vigore di un tempo, perciò le semplici faccende quotidiane sulla Mesa Nuvola Rossa sono lente e faticose. Soprattutto, considera questa commissione di routine un'importante lezione morale per te. Portare acqua potabile a suo figlio, Capo Vento Agile, è una prima prova per capire se possiedi l'umiltà, la pazienza e lo spirito comunitario che ci si aspetta da chi serve davvero la tribù.",al={"motivazioni di madre anziana vento agile","perché portare acqua a capo vento agile","perché la missione a humble task"}},b511fd77={q="A cosa serve la Brocca d'Acqua?",a="La Brocca d'Acqua è un semplice recipiente di terracotta riempito d'acqua fresca al pozzo sulla Mesa Nuvola Rossa per fornire acqua pulita al Campo Narache. Trasportarla mette alla prova la tua dedizione alle faccende della comunità e insegna anche agli avventurieri alle prime armi l'importanza di provvedere ai propri simili prima di perseguire imprese marziali più ambiziose.",al={"a cosa serve la brocca d'acqua","perché la brocca d'acqua","cos'è la brocca"}},["19ad5d96"]={q="Perché Madre Anziana Vento Agile te lo chiede invece di farlo da sé?",a="Madre Anziana Vento Agile è anziana e ammette che le sue gambe non hanno più la forza di un tempo, perciò impiega molto più tempo a trasportare brocche pesanti. Quando ti vede arrivare, un novizio in buona salute, coglie l'occasione per alleggerire il proprio carico e mettere alla prova la tua volontà di svolgere lavori quotidiani e poco appariscenti per il campo.",al={"perché non ci va madre anziana","perché mi chiede di portare l'acqua","perché vento agile non può prendere l'acqua"}}},fp="13,149,21.336.0,20.330.0,27.367.0,28.184.0,32.172.0,22.165.0,47.158.0,42.134.0,37.130.0"}
P.entries["quest:754"] = {n="Winterhoof Cleansing",s="Il Pozzo degli Zoccolo Artico a Mulgore è stato contaminato. Mull Corno Tonante ti affida un totem consacrato nel Villaggio di Zoccolo Sanguinario per purificarlo. Le attività dei goblin hanno inquinato le sorgenti vicine, e ripulire il pozzo è il primo passo per risanare le acque di Mulgore centrale.",h="Il Pozzo degli Zoccolo Artico a Mulgore è stato contaminato.",kw={"villaggio di zoccolo sanguinario","purificazione","mulgore","mull corno tonante","veleno","totem","s.p.r. & co.","pozzo d'acqua","zoccolo artico"},ang={["class:Druid"]="Da druido, vedi la fauna assetata tornare alla sorgente purificata. Il suo ritorno mostra perché la natura ha bisogno di essere risanata ovunque la civiltà la minacci.",["class:Shaman"]="Da sciamano, incanali gli spiriti attraverso i totem per purificare la corruzione industriale e onorare il tuo legame con le acque elementali.",["faction:Horde"]="Come membro dell'Orda, contribuisci a garantire acqua fresca alla terra natia dei tauren, uno dei pilastri meridionali della giovane Orda.",["race:Tauren"]="Come tauren, sai che i pozzi di Mulgore sono sacri doni della Madre Terra, fonte di vita. Proteggerli dall'avidità dei goblin è un dovere verso il tuo popolo e un obbligo sacro."},sec={{t="Una terra devastata",b="Le pianure erbose di Mulgore dipendono da pozzi ancestrali per sostenere la fauna selvatica e le tribù sparse di tauren. Di recente, la S.P.R. & Co. ha portato i suoi mercenari industriali sulle colline a sud-est del Villaggio di Zoccolo Sanguinario. Le loro attività hanno contaminato le falde acquifere locali e reso tossico il Pozzo degli Zoccolo Artico. Le bestie selvatiche evitano la sua acqua e gli accampamenti vicini sono in pericolo se la corruzione si diffonde nel terreno."},{t="Il rituale delle acque purificatrici",b="Mull Corno Tonante intaglia un totem purificatore e lo benedice nel nome della Madre Terra. Gli scagnozzi armati della S.P.R. & Co. si sono impadroniti della sorgente, quindi devi affrontarli per raggiungere il pozzo. Pianta il totem alla sorgente e scaccerà le acque di scarico nocive. Allora l'acqua pulita potrà risalire dalle profondità della terra."}},faq={{q="Dove si trova il Pozzo degli Zoccolo Artico?",a="Il Pozzo degli Zoccolo Artico si trova sulle colline a sud-est del Villaggio di Zoccolo Sanguinario, a Mulgore. Nei dintorni pattugliano lavoratori goblin e mercenari della S.P.R. & Co.",al={"posizione pozzo zoccolo artico","dove si trova il pozzo zoccolo artico","come trovare il pozzo zoccolo artico"}},{q="Perché il pozzo è stato avvelenato?",a="La S.P.R. & Co. ha avviato attività minerarie e scavi nelle vicinanze. Gli scarichi tossici e i rifiuti si sono infiltrati nella falda acquifera, rendendo la sorgente pericolosa da bere per la fauna selvatica e i tauren della zona.",al={"chi ha avvelenato l'acqua","perché il pozzo è sporco","pozzo s.p.r. & co."}},{q="Chi è Mull Corno Tonante?",a="Mull Corno Tonante è un anziano spirituale del Villaggio di Zoccolo Sanguinario, profondamente in sintonia con la salute della terra. Crea totem cerimoniali per rimediare ai danni causati dagli invasori stranieri.",al={"chi è mull","ruolo di mull corno tonante"}},{q="Cosa succede dopo che il pozzo viene purificato?",a="Dopo che l'acqua del Pozzo degli Zoccolo Artico sarà tornata limpida e la fauna selvatica potrà berla senza pericolo, Mull Corno Tonante ti manderà ad altri pozzi in difficoltà a Mulgore, a cominciare dal Thunderhorn Totem.",al={"what comes next","dopo winterhoof cleansing","cosa fa mull dopo"}},{q="Chi sono le guardie al pozzo?",a="Il pozzo è presidiato da lavoratori e mercenari al servizio della S.P.R. & Co. Questo sindacato guidato dai goblin depreda le risorse naturali della terra senza curarsi dell'ecosistema locale.",al={"chi protegge il pozzo zoccolo artico","quali nemici ci sono al pozzo"}},{q="Come funziona il totem purificatore?",a="Intagliato secondo i sacri riti e le protezioni dei tauren, il totem attinge agli spiriti della natura e alle benedizioni della Madre Terra per purgare la sorgente dai contaminanti chimici innaturali.",al={"storia totem purificazione","come funziona il totem di mull"}}},fx={["16ee77f0"]={q="Perché Mull Corno Tonante vuole che il Pozzo degli Zoccolo Artico venga purificato?",a="Il Pozzo degli Zoccolo Artico è fondamentale per l'equilibrio e la sopravvivenza di Mulgore. L'acqua è stata contaminata, mettendo a rischio sia la fauna locale sia le tribù che ne dipendono. Mull Corno Tonante ha preparato un totem di purificazione consacrato, ma il suo potere deve essere portato direttamente sul posto per risanare le acque e ristabilire l'armonia della terra.",al={"perché purificare il pozzo degli zoccolo artico","motivazioni di mull corno tonante","perché purificare l'acqua degli zoccolo artico"}}},fp="20,271,16.402.0,30.304.0,43.149.0,32.169.0,24.179.0,40.174.1,31.180.0,34.179.0"}
P.entries["quest:7541"] = {n="Service to the Horde",s="A Orgrimmar, Zor Solaselva ha ricevuto il pendente ingioiellato e ha altro da raccontarti sul tuo servizio all'Orda.",h="A Orgrimmar, Zor Solaselva ha ricevuto il pendente ingioiellato e ha altro da raccontarti sul tuo servizio...",kw={"acquemorte","pendente","report to zor","service to the horde","zor solaselva"},sec={{t="Zor Solaselva a Orgrimmar",b="Il pendente ingioiellato è ora da Zor Solaselva a Orgrimmar. Torna da lui per saperne di più sul tuo servizio all'Orda."},{t="L'Ultima Parola di Zor",b="Zor dice che gli studiosi hanno bisogno di tempo per studiare il pendente. Ti offre un piccolo pegno in riconoscimento del tuo servizio all'Orda. Le tue imprese portano onore a te e all'Orda."}},faq={{q="Chi ha il pendente ora?",a="Zor Solaselva a Orgrimmar ha il pendente. Gliel'hai portato da Nazeer Piccarossa a Felcimura.",al={"chi prende il pendente","chi assegna questa missione","ruolo di zor solaselva"}},{q="Quale missione precede questa?",a="Report to Zor viene prima. Hai portato il pendente ingioiellato a Zor Solaselva.",al={"quale missione è precedente","prerequisito servizio all'orda","missione precedente"}}},fp="20,117,25.121.0,15.174.1,24.109.0,29.75.0"}
P.entries["quest:755"] = {n="Rites of the Earthmother",s="Sulla Mesa Nuvola Rossa, i giovani tauren iniziano il cammino spirituale sotto la guida di Capo Vento Agile. Li manda a sud di Campo Narache dal Veggente Lingua Grigia, che li guida verso le prime prove.",h="Sulla Mesa Nuvola Rossa, i giovani tauren iniziano il cammino spirituale sotto la guida di Capo Vento Agile.",kw={"campo narache","capo vento agile","madre terra","mesa nuvola rossa","rites of the earthmother","veggente lingua grigia","tauren"},ang={["class:Druid"]="Come druido, inizi il tuo cammino verso l'armonia con la natura onorando la guida sacra degli anziani e dei veggenti della tribù.",["class:Shaman"]="Come aspirante sciamano, inizi con riti benedetti dai veggenti della tribù. Sono un primo passo essenziale verso il contatto con gli elementi e gli spiriti di Mulgore.",["faction:Horde"]="Come membro dell'Orda, puoi scorgere il cuore spirituale dei tuoi alleati tauren, entrati da poco nell'Orda, attraverso queste sacre prove.",["race:Tauren"]="Come tauren, inizi un cammino spirituale con i Rites of the Earthmother. Mettono alla prova la tua preparazione a servire la tribù e a venerare la Madre Terra."},sec={{t="La Soglia delle Prove",b="Sulla Mesa Nuvola Rossa, Capo Vento Agile manda i giovani tauren dal Veggente Lingua Grigia, sulle colline a sud di Campo Narache. Il veggente guida i giovani all'inizio del loro cammino spirituale. Questo viaggio li porta oltre la vita quotidiana nell'accampamento, verso i doveri imposti dalle usanze tribali."},{t="Accogliere la Madre Terra",b="La Madre Terra plasma le credenze dei tauren sulla creazione e sulla vita quotidiana. I suoi riti mettono alla prova maturità, resilienza e profondità spirituale. Il Veggente Lingua Grigia avverte chi raggiunge il suo santuario: le prove richiedono piena dedizione alle tradizioni della mesa."}},faq={{q="Chi affida la missione Rites of the Earthmother?",a="Capo Vento Agile manda i giovani tauren da Campo Narache a cercare il Veggente Lingua Grigia sulle colline circostanti.",al={"chi dà inizio ai rites of the earthmother","datore di missione"}},{q="Dove posso trovare il Veggente Lingua Grigia?",a="Il Veggente Lingua Grigia vive sulle colline a sud di Campo Narache, sulla Mesa Nuvola Rossa a Mulgore.",al={"dove si trova il veggente lingua grigia","posizione lingua grigia","trovare lingua grigia"}},{q="Cosa sono i Rites of the Earthmother?",a="I Rites of the Earthmother sono prove sacre e tradizionali in cui i giovani tauren dimostrano la loro saggezza, forza e devozione al loro popolo e alle loro credenze.",al={"cosa sono i rites of the earthmother","tradizioni prove della madre terra"}},{q="Chi è il Veggente Lingua Grigia?",a="Il Veggente Lingua Grigia è un rispettato anziano spirituale che vive a sud di Campo Narache e guida gli iniziati nelle sacre prove della Madre Terra.",al={"chi è il veggente lingua grigia","ruolo lingua grigia"}},{q="Chi è Capo Vento Agile?",a="Capo Vento Agile guida Campo Narache, sulla Mesa Nuvola Rossa, e prepara i giovani tauren prima di mandarli dai veggenti.",al={"chi è capo vento agile","ruolo vento agile"}},{q="Cosa è richiesto per completare questo compito?",a="Vai a sud da Campo Narache, sulle colline, e parla con il Veggente Lingua Grigia per dirgli che sei pronto per le prove.",al={"cosa devo fare","come completare la missione"}}},fp="24,194,27.268.0,25.248.0,45.103.0,33.96.0,38.150.0,23.140.0,22.111.0,39.125.0"}
P.entries["quest:756"] = {n="Thunderhorn Totem",s="Nel Villaggio di Zoccolo Sanguinario, Mull Corno Tonante chiede ai giovani campioni dell’Orda di aiutarlo a creare un totem sacro della purificazione. L’inquinamento della S.P.R. & Co. si diffonde nei pozzi di Mulgore, e gli artigli dei predatori legheranno al legno la forza primordiale delle pianure.",h="Nel Villaggio di Zoccolo Sanguinario, Mull Corno Tonante chiede ai giovani campioni dell’Orda di aiutarlo a...",kw={"villaggio di zoccolo sanguinario","purificazione","artiglio di puma","puma di pianura","mulgore","mull corno tonante","inseguitore della prateria","artiglio di inseguitore","thunderhorn totem","pozzo d'acqua"},ang={["class:Hunter"]="Come cacciatore, impari a conoscere le bestie native delle pianure e onori la preda mentre raccogli i loro artigli per preservare l’ecosistema.",["class:Shaman"]="Come sciamano, invochi gli spiriti viventi della terra per purificare l’acqua contaminata da attività innaturali e sconsiderate.",["race:Tauren"]="Come tauren, difendere le falde acquifere di Mulgore dallo sfruttamento straniero è un sacro dovere tribale. Il volere della Madre Terra richiede che la vita sia in equilibrio, non saccheggiata."},sec={{t="Caccia ai predatori della pianura",b="Mull Corno Tonante ha bisogno di artigli naturali per un totem della purificazione. La S.P.R. & Co. avvelena l’acqua di Mulgore sfruttandone le terre, e Mull cerca un rimedio. Gli inseguitori della prateria e i puma di pianura si aggirano a est e a ovest del Villaggio di Zoccolo Sanguinario. I loro artigli racchiudono l’essenza naturale dei predatori e incanalano nel totem il loro vigore grezzo e incontaminato."},{t="La natura della caccia",b="La tradizione tauren distingue la caccia per procurarsi cibo o mantenere l’equilibrio spirituale dal saccheggio su larga scala dei goblin. Mull crede che il modo puro in cui cacciano i predatori nativi possa contribuire a purificare la terra corrotta. I macchinari goblin contaminano le sorgenti con petrolio e rifiuti industriali. La forza naturale delle bestie può fornire l’energia spirituale necessaria a ripristinare il Pozzo dei Corno Tonante."}},faq={{q="Perché Mull Corno Tonante ha bisogno degli artigli dei predatori?",a="Mull usa gli artigli degli inseguitori della prateria e dei puma di pianura per incanalare in un totem della purificazione lo spirito predatorio puro e primordiale delle pianure. Crede che lo spirito dei cacciatori naturali possa contrastare la corruzione industriale artificiale.",al={"perché gli artigli","scopo degli artigli dell'inseguitore","scopo degli artigli di puma"}},{q="Chi sta corrompendo l'acqua a Mulgore?",a="I goblin della S.P.R. & Co. al lavoro a Mulgore inquinano la terra e l’acqua. Le loro trivelle e le attività minerarie sconsiderate riversano fanghi tossici nelle falde acquifere che alimentano i pozzi tribali.",al={"chi ha contaminato il pozzo","perché il pozzo è avvelenato","cosa ha avvelenato mulgore"}},{q="Dove si trovano gli inseguitori della prateria e i puma di pianura?",a="Gli inseguitori della prateria e i puma di pianura si aggirano nelle pianure aperte di Mulgore centrale, soprattutto nelle savane ondulate a est e a ovest del Villaggio di Zoccolo Sanguinario.",al={"posizione dell'inseguitore","dove trovare i puma","posizioni degli artigli di puma"}},{q="Cosa succede dopo aver creato il Thunderhorn Totem?",a="Dopo aver intagliato il totem e averlo incantato con gli artigli, Mull ti manda al Pozzo dei Corno Tonante contaminato. Lì esegui il rituale di purificazione e scacci il veleno.",al={"cosa fare dopo","dopo il thunderhorn totem","seguito del totem"}},{q="Come si collega questo alla precedente purificazione al Pozzo degli Zoccolo Artico?",a="I tauren si impegnano a preservare le acque sacre di Mulgore. Il Pozzo degli Zoccolo Artico è stato purificato per primo, e ora la contaminazione minaccia il pozzo di Cornotonante, più a nord.",al={"collegamento con zoccolo artico","missione precedente del totem"}},{q="Perché i tauren non usano semplicemente rimedi erboristici invece degli artigli animali?",a="L’arte rituale dei tauren attinge agli aspetti elementali e fisici della natura. La purezza affilata dei predatori al vertice della catena alimentare offre una forza spirituale attiva e combattiva, capace di farsi strada tra gli aggressivi veleni industriali dei goblin.",al={"perché non le erbe","materiali totemici sciamanici"}}},fx={cb047e40={q="Perché Mull Corno Tonante vuole che venga fatto?",a="L'acqua del Pozzo dei Corno Tonante si contamina sempre più, avvelenata dalle sconsiderate attività dei goblin nelle vicinanze. Mull Corno Tonante deve creare un totem sacro di purificazione per purificare il pozzo prima che la corruzione si diffonda ulteriormente nella terra e danneggi il suo popolo.",al={"perché mull vuole che venga fatto","motivazioni di mull corno tonante","perché creare il totem dei corno tonante"}},["43953f1d"]={q="Quali creature devi cacciare per ottenere gli artigli?",a="Devi cacciare i predatori selvatici che si aggirano nelle pianure di Mulgore: i predatori della prateria e i puma delle pianure. Queste bestie vagano naturalmente a est e a ovest del Villaggio di Zoccolo Sanguinario e vivono e cacciano secondo il naturale equilibrio della terra.",al={"quali creature devo cacciare","quali sono i bersagli","prede del thunderhorn totem"}}},fp="17,236,28.346.0,22.354.0,46.210.0,39.176.0,58.144.0,50.174.1,66.166.0,72.198.0"}
P.entries["quest:757"] = {n="Rite of Strength",s="Al Campo Narache, i giovani tauren affrontano il Rite of Strength contro i quilboar Bristleback. Portano le cinture al Capo Vento Agile per dimostrare il loro coraggio e difendere la tribù.",h="Al Campo Narache, i giovani tauren affrontano il Rite of Strength contro i quilboar Bristleback.",kw={"depressione di rovoaguzzo","bristleback","campo narache","capo vento agile","earthmother","mulgore","quilboar","rite of strength","veggente lingua grigia"},ang={["faction:Horde"]="Come membro dell'Orda, aiuti a difendere la Mesa Nuvola Rossa, una delle sue principali aree di reclutamento. Qui i giovani guerrieri e sciamani possono maturare al sicuro e sostenere la nuova unione.",["race:Tauren"]="Da giovane tauren, inizi gli antichi riti dimostrando di saper difendere il tuo popolo dai quilboar prima di lasciare la Mesa Nuvola Rossa."},sec={{t="La prima prova",b="Il Veggente Lingua Grigia chiama i giovani tauren a iniziare i Rites of the Earthmother con il Rite of Strength. Per ottenere il riconoscimento degli anziani della tribù ed essere accolti a Picco del Tuono, ogni iniziato deve affrontare questo compito. La prova stabilisce se sapranno affrontare con coraggio i nemici mortali della tribù e difendere la Mesa Nuvola Rossa."},{t="La minaccia dei Bristleback",b="A est del Campo Narache, la Depressione di Rovoaguzzo è la dimora dei quilboar Bristleback. Invadono le terre ancestrali, tendono imboscate ai gruppi di caccia e razziano le provviste dell'accampamento col favore delle tenebre. Ti viene chiesto di ucciderli e riportare le loro cinture. Le cinture dimostrano il tuo valore e aiutano a proteggere l'insediamento."}},faq={{q="Qual è lo scopo del Rite of Strength?",a="Il Rite of Strength mette alla prova il coraggio di un giovane tauren in combattimento e dà inizio ai Rites of the Earthmother. Sconfiggere le minacce all'accampamento dà all'iniziato il diritto di proseguire il cammino verso il rispetto a Picco del Tuono.",al={"perché fare il rite of strength","storia del rite of strength","scopo del rite of strength"}},{q="Chi assegna e giudica questa prova?",a="Il Veggente Lingua Grigia assegna l'incarico e ne spiega le richieste spirituali e pratiche. Porta dodici cinture dei Bristleback al Capo Vento Agile al Campo Narache come prova del tuo valore.",al={"chi assegna il rite of strength","chi riceve il rite of strength"}},{q="Dove si trova la Depressione di Rovoaguzzo?",a="La Depressione di Rovoaguzzo si trova a est del Campo Narache, sulla Mesa Nuvola Rossa. I feroci quilboar Bristleback vivono nel suo canyon spinoso.",al={"dove si trova depressione di rovoaguzzo","posizione depressione di rovoaguzzo"}},{q="Perché i Bristleback vengono presi di mira?",a="I Bristleback invadono gli antichi terreni di caccia della tribù. Tendono imboscate ai cacciatori tauren e di notte rubano le provviste del Campo Narache, diventando così nemici della tribù.",al={"perché uccidere i bristleback","cosa hanno fatto i quilboar"}},{q="Perché raccogliere cinture invece di altri trofei?",a="Le cinture dimostrano che un iniziato ha affrontato i quilboar e sconfitto i loro guerrieri adulti in combattimento ravvicinato, invece di raccogliere resti da lontano.",al={"perché cinture dei bristleback","perché le cinture"}},{q="Cosa succede dopo aver completato il Rite of Strength?",a="Superare il Rite of Strength dimostra il valore di un iniziato e lo abilita alle prove successive dell'Earthmother. Queste prove proseguono il percorso formale verso l'età adulta e il prestigio spirituale nella tribù.",al={"cosa c'è dopo il rite of strength","prossimo rito della earthmother"}}},fx={f38315d5={q="Perché il Veggente Lingua Grigia ti manda contro i Spinepelle?",a="Il Veggente Lingua Grigia guida i giovani del Campo Narache attraverso i sacri Riti della Madre Terra. Per la tua prima prova, deve mettere alla prova la tua determinazione in combattimento contro un pericolo concreto e pressante per la tribù. I cinghiali quilboar Spinepelle si sono spinti nelle terre dei tauren, tendendo imboscate ai cacciatori e rubando sotto la copertura dell'oscurità. Mandandoti ad affrontarli, Lingua Grigia si assicura che tu protegga il tuo popolo, dimostri la tua forza e guadagni il rispetto della tribù.",al={"perché lingua grigia vuole che venga fatto","motivazioni del veggente lingua grigia","perché il rito della forza"}},e0dd8e68={q="Perché ti mandano da solo a superare questa prova?",a="Il Rito della Forza è un rito di passaggio personale, non una semplice mansione di guarnigione. Mentre i guerrieri del campo sorvegliano il perimetro, ogni giovane tauren deve dimostrare da solo il proprio valore e le proprie capacità marziali prima di essere riconosciuto adulto a Picco del Tuono. La prova richiede che tu affronti da solo i nemici del tuo popolo, così gli anziani sapranno che puoi difendere la tribù quando sarà necessario.",al={"perché tocca a me fare il rito della forza","perché non mandare le guardie contro gli spinepelle","perché devo combattere gli spinepelle"}}},fp="16,165,15.312.0,22.298.0,44.205.0,34.166.0,37.131.0,40.177.0,44.137.0,49.206.0"}
P.entries["quest:758"] = {n="Thunderhorn Cleansing",s="A Mulgore, Thunderhorn Cleansing ti affida la purificazione del Pozzo dei Corno Tonante. Mull Corno Tonante prepara un totem per il rito e gli antenati del clan Cornotonante ti ringraziano quando la sorgente è pulita.",h="A Mulgore, Thunderhorn Cleansing ti affida la purificazione del Pozzo dei Corno Tonante.",kw={"spiriti ancestrali","villaggio di zoccolo sanguinario","totem della purificazione","madre terra","mulgore","mull corno tonante","thunderhorn cleansing","pozzo dei corno tonante"},ang={["class:Druid"]="Come druido, purifichi le acque avvelenate per fermare la corruzione nella terra viva di Mulgore e preservare l'armonia naturale delle pianure.",["class:Shaman"]="Come sciamano, incanali l'energia ancestrale attraverso i totem per guarire le sorgenti corrotte. Questo è il cuore della tua vocazione.",["faction:Horde"]="Come membro dell'Orda, rafforzi il legame con gli orgogliosi Shu'halo aiutando i tauren a proteggere le loro sorgenti sacre.",["race:Tauren"]="Come tauren, rendi onore a Earth Mother e proteggi la tua gente mentre costruisce una dimora pacifica e duratura a Mulgore."},sec={{t="Un'ancora di salvezza contaminata",b="I pozzi d'acqua sostengono le tribù tauren che si sono stabilite nelle praterie di Mulgore. Quando il veleno contamina una sorgente sotterranea, la fauna e gli insediamenti vicini ne risentono. Il Pozzo dei Corno Tonante si trova a nord del Villaggio di Zoccolo Sanguinario e le sue acque hanno bisogno di una purificazione spirituale."},{t="Purificazione ancestrale",b="Mull Corno Tonante crea un Totem della Purificazione per il rito. Portalo alla sorgente avvelenata e incanalaci il potere ancestrale per scacciarne le tossine. Quando la purificazione riesce, gli antenati del clan Cornotonante visitano Mull in sogno e lo ringraziano."}},faq={{q="Dove si trova il Pozzo dei Corno Tonante?",a="Il Pozzo dei Corno Tonante si trova nelle pianure a nord del Villaggio di Zoccolo Sanguinario, a Mulgore. È uno dei vari abbeveratoi che riforniscono i clan tauren locali.",al={"posizione pozzo dei corno tonante","dove si trova il pozzo","dove uso il totem"}},{q="Chi avvia questo rituale di purificazione?",a="Mull Corno Tonante dà inizio al rito. Vive nel Villaggio di Zoccolo Sanguinario e crea totem per guarire la terra sofferente di Mulgore.",al={"chi assegna la missione","posizione mull corno tonante","assegnatore missione"}},{q="Perché i pozzi d'acqua a Mulgore devono essere purificati?",a="Veleno e corruzione minacciano le pianure e le tribù tauren che dipendono dall'acqua pulita.",al={"perché purificare i pozzi","cosa è successo all'acqua","perché il pozzo è avvelenato"}},{q="Come fa Mull a sapere che il rituale è riuscito?",a="Dopo la riuscita del rito, gli antenati del clan Cornotonante visitano Mull in sogno e ti ringraziano per il tuo gesto.",al={"sogno degli antenati","come lo sa mull","risultato purificazione pozzo"}},{q="Cosa succede dopo la purificazione del pozzo dei Cornotonante?",a="Dopo aver purificato il pozzo dei Cornotonante, Mull ti manda ad aiutare un'altra regione in difficoltà creando il Wildmane Totem.",al={"cosa succede dopo","missione successiva a thunderhorn","wildmane totem successivo"}},{q="Cos'è il Totem Purificatore dei Corno Tonante?",a="Il Totem Purificatore dei Corno Tonante è un tramite spirituale che Mull Corno Tonante crea per purificare le acque corrotte del pozzo ancestrale del suo clan.",al={"totem della purificazione","cos'è l'oggetto totem","totem di mull"}}},fx={da3030fe={q="Perché Mull Corno Tonante ha bisogno che tu purifichi il pozzo?",a="Mull Corno Tonante ha creato il fulcro rituale, ma purificare un luogo sacro è un rito di servizio e onore per i campioni tauren e i loro alleati che aspirano a grandi imprese. Portando tu stesso il Totem Purificatore dei Corno Tonante al pozzo contaminato, dimostri la tua dedizione alla Madre Terra e agli spiriti ancestrali del suo clan, guadagnandoti il favore e la guida degli antenati che vegliano sulle acque.",al={"perché io per mull corno tonante","perché mull ti manda","perché compiere il rituale di purificazione"}}},fp="21,203,18.263.0,19.244.0,44.156.0,36.113.0,48.90.0,45.101.0,51.116.0,40.136.0"}
P.entries["quest:759"] = {n="Wildmane Totem",s="Al Pozzo Wildmane, Mull Corno Tonante cerca di risanare le ultime acque avvelenate di Mulgore. Gli servono i denti dei lupi della prateria alfa per creare un totem che le purifichi.",h="Al Pozzo Wildmane, Mull Corno Tonante cerca di risanare le ultime acque avvelenate di Mulgore.",kw={"villaggio di zoccolo sanguinario","mulgore","mull corno tonante","lupo della prateria alfa","picco del tuono","totem","pozzo d'acqua","wildmane"},ang={["class:Hunter"]="Da cacciatore, metti alla prova il tuo rispetto per la natura selvaggia e i suoi predatori più feroci mentre dai la caccia agli astuti lupi alfa attorno agli alti dirupi.",["class:Shaman"]="Da sciamano, conosci la cura necessaria per armonizzare i totem dei predatori e l'acqua elementale contro la contaminazione tossica.",["race:Tauren"]="Da tauren, hai ereditato il dovere di risanare i pozzi ancestrali e onorare ciò che la Madre Terra chiede alla terra di offrire."},sec={{t="Il pozzo finale",b="Il Pozzo Wildmane è l'ultima fonte avvelenata nel Mulgore centrale. Mull Corno Tonante ha raccolto ciò che gli serve per i pozzi Winterhoof e Cornotonante, eppure l'acqua avvelenata continua a danneggiare la fauna migratoria e gli insediamenti delle pianure. Servono potenti ingredienti della terra per ripristinarne l'equilibrio."},{t="La forza del predatore",b="I lupi della prateria alfa si aggirano per le praterie di Mulgore, soprattutto sotto gli alti dirupi ai piedi di Picco del Tuono. Mull Corno Tonante ha bisogno dei loro denti per un totem purificatore destinato alle acque settentrionali. La loro forza e resistenza conferiranno al totem il potere di questi feroci cacciatori."},{t="Sacrificio ed equilibrio",b="Per i tauren, prendere dalle creature della terra è un atto di grande gravità. Mull Corno Tonante considera i denti degli alfa una necessità, non una conquista. Il sacrificio dei predatori potrebbe contribuire a risanare le acque avvelenate della Madre Terra."}},faq={{q="A cosa serve il Wildmane Totem?",a="Mull Corno Tonante crea il totem per purificare il Pozzo Wildmane, l'ultima fonte contaminata che minaccia i tauren di Mulgore.",al={"perché creare il wildmane totem","scopo del wildmane totem"}},{q="Perché sono richiesti specificamente i denti di lupo della prateria alfa?",a="La profonda corruzione del Pozzo Wildmane richiede la feroce forza di un predatore all'apice della catena alimentare. I denti degli alfa infondono quella forza primordiale nel totem.",al={"perché denti di lupo","scopo denti alfa della prateria"}},{q="Dove si trovano i lupi della prateria alfa a Mulgore?",a="I lupi della prateria alfa si aggirano per le pianure settentrionali di Mulgore, soprattutto nelle praterie attorno alla base di Picco del Tuono.",al={"posizione lupi della prateria alfa","dove trovare alfa della prateria"}},{q="Chi crea il totem?",a="Mull Corno Tonante, un anziano spirituale del Villaggio di Zoccolo Sanguinario, crea ogni totem purificatore dopo che un iniziato ha raccolto le offerte.",al={"chi crea il totem","datore missione totem"}},{q="Cosa segue la creazione del Wildmane Totem?",a="Dopo che Mull Corno Tonante crea un totem con i denti degli alfa, lo porti a nord per purificare il Pozzo Wildmane.",al={"what comes next","prossima missione wildmane totem"}},{q="In che modo questo rituale riflette le credenze tauren?",a="I tauren considerano togliere la vita a un animale uno scambio solenne con la natura. Mull piange la morte dei lupi e onora il loro contributo nel risanare la terra.",al={"filosofia tauren totem","credenze di mull corno tonante"}}},fx={["054e923c"]={q="Perché Mull Corno Tonante vuole che venga creato il Wildmane Totem?",a="A Mulgore resta un solo pozzo contaminato da purificare: quello del clan dei Manto Selvaggio. Mull Corno Tonante si è dedicato a purificare i pozzi sacri della Madre Terra e creare questo ultimo totem purificatore usando lo spirito predatorio della terra è fondamentale per completare il rito sacro e restituire acqua pura alla tribù.",al={"perché mull vuole il wildmane totem","motivazioni di mull corno tonante","perché creare il wildmane totem"}},["2aa23a29"]={q="A cosa serve il Dente di Lupo Alfa?",a="I denti del lupo alfa della prateria rappresentano il sacrificio e la feroce vitalità dei predatori dominanti di Mulgore. Mull Corno Tonante incastona otto di queste zanne nel Wildmane Totem, affinché il suo spirito possa placare l'ordine naturale e dare forza al rituale necessario a purificare il Pozzo dei Manto Selvaggio dalla contaminazione.",al={"uso del dente di lupo alfa","a cosa servono i denti del lupo alfa della prateria","denti per il wildmane totem"}},eb5f4bd0={q="Perché stai cacciando i lupi delle praterie alfa?",a="Ti è stato chiesto di cacciare i lupi delle praterie alfa, i capobranco dominanti che vagano per le pianure intorno alla base di Picco del Tuono. La loro forza e ferocia incarnano il naturale equilibrio delle pianure e forniscono la potente essenza di cui Mull Corno Tonante ha bisogno per il rituale finale di purificazione dell'acqua.",al={"perché uccidere i lupi delle praterie alfa","bersaglio lupo delle praterie alfa","chi ti mandano a cacciare"}}},fp="14,153,14.306.0,23.274.0,21.212.0,38.121.0,55.138.0,47.114.0,21.125.0,48.106.0,44.146.0"}
P.entries["quest:76"] = {n="La Miniera Venarossa",s="Gli esploratori sono diretti alla Miniera Venarossa, a est, dove potrebbero essersi diffusi i kobold. Il Maresciallo Dughan vuole sapere fin dove sono arrivati.",h="Gli esploratori sono diretti alla Miniera Venarossa, a est, dove potrebbero essersi diffusi i kobold.",kw={"azora","dughan","elwynn","antrocupo","borgodoro","venarossa","kobold","miniera","esploratore"},ang={["faction:Alliance"]="In quanto membro dell'Alleanza, vedi quanto siano diventati fragili i territori di Roccavento senza il sostegno della corona, con la Miniera Antrocupo e la Miniera Venarossa ormai perdute.",["profession:Mining"]="In quanto minatore, vedi i preziosi giacimenti nei tunnel della Miniera Venarossa, ma i kobold che ne hanno preso possesso ti sbarrano la strada verso il minerale.",["race:Human"]="In quanto umano, vedi le infrastrutture rurali di Elwynn cedere mentre le risorse di frontiera vanno perdute a poca distanza dalla capitale."},sec={{t="Una seconda incursione",b="Dopo che i kobold hanno invaso i tunnel della Miniera Antrocupo, a sud di Borgodoro, il Maresciallo Dughan teme che abbiano raggiunto altre miniere. La Miniera Venarossa si trova ai piedi delle colline rocciose, a nord-est della Torre di Azora. Le sue pietre e i suoi metalli riforniscono il regno. Le guardie di Roccavento sono impegnate a pattugliare la città, così Dughan manda avventurieri indipendenti a est per scoprire se anche questa miniera è caduta in mano ai kobold."},{t="Difese allo stremo",b="Gli esploratori che raggiungono le camere della Miniera Venarossa scoprono che i kobold hanno scacciato i minatori umani e fortificato i passaggi bui. La crisi si aggrava e il Maresciallo Dughan subisce un altro duro colpo. Re Varian Wrynn è scomparso e le truppe reali non vengono inviate nei territori periferici. Il presidio locale ha troppo pochi soldati per liberare la miniera. Il cuore del regno resta così a corto di minerali e circondato da minacce."}},faq={{q="Dove si trova la Miniera Venarossa?",a="La Miniera Venarossa si trova ai piedi delle colline settentrionali della Foresta di Elwynn orientale. Da Borgodoro, segui la strada principale verso est, supera la Torre di Azora e poi dirigiti a nord, verso le colline.",al={"dove si trova venarossa","posizione miniera venarossa","come trovare venarossa"}},{q="Perché il Maresciallo Dughan ha bisogno di un esploratore invece di inviare le guardie?",a="Il Maresciallo Dughan ha troppo poche guardie da poter distogliere. Re Varian Wrynn è scomparso e la paralisi politica nella capitale ha lasciato le forze locali a corto di uomini, impegnate a proteggere fattorie e città da banditi e gnoll. Perciò Dughan si affida a esploratori civili.",al={"perché inviare avventurieri","perché non ci sono guardie di roccavento","dove sono le guardie"}},{q="Perché i kobold stanno conquistando le miniere di Elwynn?",a="I kobold scavano gallerie in cerca di vene minerarie e grotte umide. Con l'assottigliarsi della presenza militare di Roccavento, hanno preso coraggio e si sono spinti nelle miniere umane come la Miniera Antrocupo e la Miniera Venarossa, per impadronirsi di oro, minerali e territorio.",al={"perché i kobold sono a venarossa","cosa vogliono i kobold","motivo infestazione kobold"}},{q="Cosa succede dopo aver esplorato la Miniera Venarossa?",a="Dopo che hai riferito della caduta della Miniera Venarossa, il Maresciallo Dughan deve affrontare la perdita delle miniere a est e minacce su più fronti. Rivolge quindi l'attenzione a Elwynn occidentale, dove gli gnoll Zampalesta stanno mettendo sotto forte pressione il Presidio Rivombroso.",al={"cosa succede dopo venarossa","prosieguo venarossa"}},{q="Perché la perdita della Miniera Venarossa è significativa per Roccavento?",a="Le miniere di Elwynn forniscono i minerali e la pietra necessari all'economia di Roccavento e alla forgiatura di armi e armature. La perdita della Miniera Antrocupo e della Miniera Venarossa blocca l'estrazione e indebolisce la ripresa del regno.",al={"perché venarossa è importante","importanza venarossa"}},{q="Chi possiede la Torre di Azora nelle vicinanze?",a="La Torre di Azora è una piccola torre dei maghi lungo la strada orientale della Foresta di Elwynn. Theocritus, l'Arcimago di Azora, vi esercita la sua autorità, mentre i servitori di Azora si occupano della torre. I viaggiatori la usano come punto di riferimento per raggiungere i piedi delle colline orientali.",al={"cosa è la torre di azora","chi vive nella torre di azora"}}},fx={a973508b={q="Perché il Maresciallo Dughan vuole che la Miniera Venarossa venga perlustrata?",a="Dopo aver già confermato che i koboldi hanno invaso la Miniera Antrocupo, il Maresciallo Dughan teme che l'infestazione non sia un caso isolato. Deve sapere se la minaccia si è estesa anche a est, fino alla Miniera Venarossa. Garantire le risorse di Elwynn e comprendere la portata del pericolo incombente è fondamentale per difendere il borgo di Borgodoro e proteggere le vitali rotte commerciali di Roccavento.",al={"motivo di dughan per la miniera venarossa","perché perlustrare la miniera venarossa","perché dughan vuole indagare sulla miniera venarossa"}}},fp="19,146,18.366.0,21.386.0,37.177.0,63.237.0,43.203.0,48.235.0,60.196.0,35.231.0"}
P.entries["quest:760"] = {n="Wildmane Cleansing",s="A Mulgore, il lavoro di purificazione dei tauren raggiunge il suo ultimo pozzo. Mull Corno Tonante, al Villaggio di Zoccolo Sanguinario, ti manda a nord con il Wildmane Totem completato per purificare l'acqua avvelenata e proteggere lo stile di vita dei tauren.",h="A Mulgore, il lavoro di purificazione dei tauren raggiunge il suo ultimo pozzo.",kw={"villaggio di zoccolo sanguinario","purificazione","madre terra","mulgore","mull corno tonante","totem","s.p.r. & co.","pozzo d'acqua","manto selvaggio"},ang={["class:Druid"]="Come druido, contribuisci a contrastare la distruzione dei goblin guarendo gli ecosistemi avvelenati e proteggendo i pascoli di Mulgore.",["class:Shaman"]="Come sciamano, usi i totem rituali per contrastare l'inquinamento meccanico e mantenere l'armonia tra gli elementi naturali e le comunità viventi.",["race:Tauren"]="Come tauren, ripristinare i tre pozzi ancestrali di Mulgore è un rito di passaggio. Dimostra la tua devozione alla salvaguardia dei doni della Madre Terra."},sec={{t="Purificare il Dono della Madre Terra",b="I pozzi di Mulgore sostengono le mandrie, il suolo e le tribù tauren riunite attorno a Picco del Tuono. La S.P.R. & Co. e i goblin che avanzano li hanno contaminati con scarichi industriali tossici. Gli anziani tauren vedono il pericolo che minaccia il loro popolo e la loro terra.\n\nI pozzi degli Zoccolo Artico e dei Cornotonante sono purificati. Ora resta il Pozzo dei Manto Selvaggio, il terzo e ultimo sito corrotto. Le sue acque hanno ancora bisogno di una purificazione spirituale."},{t="Il Wildmane Totem",b="Il Totem Purificatore dei Manto Selvaggio è composto da elementi raccolti in tutta la regione. Attinge al potere rigenerante degli spiriti ancestrali e della terra elementale. Piantalo accanto alle acque contaminate a nord di Picco del Tuono. Il rituale disperde le sostanze chimiche, estrae le tossine e ravviva il flusso naturale.\n\nLa purificazione protegge i tauren dalle malattie. Dimostra anche che non tollereranno la devastazione delle loro terre sacre."}},faq={{q="Perché il Wildmane Water Well è stato avvelenato?",a="Le operazioni dei goblin, spinte dall'avidità industriale, e le imprese di disboscamento hanno avvelenato le acque sotterranee di Mulgore con rifiuti chimici. Questi rifiuti minacciano la fauna e gli insediamenti tribali.",al={"chi ha avvelenato il pozzo","perché il pozzo è sporco","veleno goblin"}},{q="Dove si trova il Wildmane Water Well?",a="Il Pozzo dei Manto Selvaggio si trova nelle pianure, direttamente a nord delle imponenti mesas di Picco del Tuono.",al={"posizione wildmane water well","dove si trova il wildmane water well","trovare il wildmane water well"}},{q="Chi inizia questo rituale di purificazione?",a="Mull Corno Tonante, un anziano del Villaggio di Zoccolo Sanguinario, ti guida nella creazione dei totem e ti manda a purificare i pozzi.",al={"chi assegna wildmane cleansing","datore di missione","dove si trova mull thunderhorn"}},{q="Quali altri pozzi fanno parte di questo sforzo di purificazione?",a="Il Wildmane Well è la terza di tre fonti d'acqua vitali. Prima sono stati purificati il Pozzo degli Zoccolo Artico e il Pozzo dei Corno Tonante, entrambi a sud.",al={"altri pozzi","pozzi del mulgore","pozzi degli zoccolo artico e dei cornotonante"}},{q="Come funziona il totem di purificazione?",a="Realizzato con la magia ancestrale e con elementi naturali purificati, il totem convoglia nel bacino idrico il potere spirituale rigenerante, neutralizzando gli agenti inquinanti dei goblin.",al={"meccanica totem di purificazione","come pulisce l'acqua il totem"}},{q="Cosa significa completare questo rituale per il Villaggio di Zoccolo Sanguinario?",a="Purificare tutti e tre i pozzi garantisce acqua potabile sicura alle tribù della Mulgore centrale. Onora il dovere dei tauren di guarire la Madre Terra dallo sfruttamento industriale.",al={"risultato della missione","perché purificare i pozzi","importanza della tradizione tauren"}}},fx={["119d5a48"]={q="Perché Mull Corno Tonante vuole che il Pozzo dei Manto Selvaggio venga purificato?",a="Mull Corno Tonante veglia sull'equilibrio spirituale e sulle risorse vitali di Mulgore. Le nefaste operazioni della S.P.R. & Co. hanno avvelenato le preziose fonti d'acqua della terra, minacciando la sopravvivenza delle tribù e delle loro mandrie. Il Pozzo dei Manto Selvaggio è l'ultimo dei tre antichi pozzi ancora contaminati, e purificarlo è essenziale per guarire la Madre Terra e garantire acqua potabile sicura al Villaggio di Zoccolo Sanguinario e a Picco del Tuono.",al={"motivo di mull corno tonante","perché purificare il pozzo dei manto selvaggio","perché a mull interessano i pozzi"}},b4cee6a1={q="Cos'è il Totem Purificatore dei Manto Selvaggio?",a="Il Totem Purificatore dei Manto Selvaggio è uno strumento preparato ritualmente da Mull Corno Tonante per incanalare gli spiriti ancestrali e della terra. Attivato presso il contaminato Pozzo dei Manto Selvaggio, a nord di Picco del Tuono, il totem espelle i fanghi tossici lasciati dagli inquinatori goblin, purificando la falda acquifera e riportando la sorgente al suo stato naturale e incontaminato.",al={"uso del totem purificatore dei manto selvaggio","cos'è il wildmane totem","scopo del totem della purificazione"}}},fp="18,219,33.421.0,18.420.0,41.180.0,41.92.0,36.115.0,54.145.0,34.155.0,60.169.0"}
P.entries["quest:761"] = {n="A caccia di avvoltoi",s="Harken Totem Fulgido ti chiede di seguire gli avvoltoi per Mulgore. Le loro penne mettono alla prova pazienza, astuzia e mira, e onorano le prove della Madre Terra.",h="Harken Totem Fulgido ti chiede di seguire gli avvoltoi per Mulgore.",kw={"villaggio di zoccolo sanguinario","harken totem fulgido","mulgore","avvoltoio","caccia all'avvoltoio","prova tauren","penna trofeo d'avvoltoio"},ang={["class:Druid"]="Da druido, seguire gli avvoltoi sulle mesas di Mulgore ti avvicina ai predatori alati che contribuiscono all'equilibrio dei suoi cieli.",["class:Hunter"]="Da cacciatore, seguire gli avvoltoi ti insegna a inseguire prede volanti, interpretarne il comportamento e colpire con precisione predatori all'erta.",["race:Tauren"]="Da tauren, cacciare i veloci avvoltoi di Mulgore è un rito di passaggio. Affina le tue capacità di tracciamento e perpetua le usanze ancestrali."},sec={{t="Una prova di vista acuta",b="Nelle vaste praterie di Mulgore, gli avvoltoi mettono alla prova l'occhio del cacciatore. Questi grandi uccelli si confondono con il cielo e la pianura, volteggiando in alto o sfiorando l'erba alta. Richiedono concentrazione e passi rapidi, a differenza degli striscia-piane goffi o dei kodo al pascolo. I giovani cacciatori li inseguono per dimostrare la propria abilità e guadagnarsi rispetto tra le tribù."},{t="Simboli della caccia",b="Harken Totem Fulgido chiede penne trofeo per insegnare disciplina, non per decimare la fauna. I tauren portano pegni di un inseguimento difficile come segno di astuzia e perseveranza. Presentare penne intatte agli anziani nel Villaggio di Zoccolo Sanguinario dimostra che un cacciatore sa sostenere e difendere la comunità. Zoccoli veloci e sensi acuti li preparano al mondo più vasto."}},faq={{q="Qual è lo scopo della caccia agli avvoltoi per Harken Totem Fulgido?",a="Harken Totem Fulgido ti chiede di seguire gli avvoltoi per Mulgore e mettere alla prova astuzia, velocità e dedizione. Le penne trofeo intatte dimostrano la tua abilità e portano onore tra i tauren del Villaggio di Zoccolo Sanguinario.",al={"perché cacciare gli avvoltoi","scopo missione harken totem fulgido","scopo caccia all'avvoltoio"}},{q="Dove si incontrano solitamente gli avvoltoi?",a="Gli avvoltoi vagano per le vaste pianure di Mulgore, librandosi sopra l'erba o cercando prede lontano dagli insediamenti, come il Villaggio di Zoccolo Sanguinario.",al={"dove sono gli avvoltoi","posizioni avvoltoi mulgore","trovare avvoltoi"}},{q="Perché gli avvoltoi sono considerati difficili da cacciare?",a="Gli avvoltoi sono predatori veloci e attenti, diffusi nelle pianure. Servono occhi acuti per avvistarli e passi rapidi per raggiungerli prima che fuggano.",al={"perché gli avvoltoi sono difficili da prendere","comportamento avvoltoio"}},{q="Cosa significano le penne trofeo per i tauren?",a="Le penne trofeo degli avvoltoi rappresentano pazienza, vista acuta e una caccia riuscita. Dimostrano che hai l'istinto per nutrire e proteggere la tribù.",al={"significato penna trofeo d'avvoltoio","significato delle penne"}},{q="Chi è Harken Totem Fulgido?",a="Harken Totem Fulgido è un tauren rispettato del Villaggio di Zoccolo Sanguinario. Osserva i nuovi arrivati e gli aspiranti cacciatori, valutandone l'ingegno con prove tradizionali nelle pianure.",al={"chi assegna la caccia all'avvoltoio","lore harken totem fulgido"}},{q="Questa caccia influisce sull'equilibrio della natura a Mulgore?",a="I tauren considerano la caccia uno scambio sacro con la Madre Terra, non un massacro insensato. Raccogliere penne mette alla prova la disciplina, onora prede astute e preserva l'equilibrio della tribù.",al={"la caccia all'avvoltoio è eccessiva","avvoltoio equilibrio mulgore"}}},fx={["0d785fcd"]={q="Perché Harken Totem Fulgido manda un forestiero a cacciare i grifalchi invece di farlo lui stesso?",a="Harken Totem Fulgido non ti manda perché non sia in grado di cacciare, ma per mettere alla prova il tuo valore. Per i tauren, seguire le tracce degli astuti grifalchi attraverso le pianure richiede vista acuta, pazienza e zoccoli veloci. Affidandoti il compito di riportare le loro penne, Harken ti offre l'opportunità di dimostrare la tua abilità e determinazione al Villaggio di Zoccolo Sanguinario, mostrando di essere un cacciatore di vero valore.",al={"perché mandarmi a cacciare grifalchi","perché harken ha bisogno di me","perché harken non può cacciare i grifalchi"}}},fp="13,157,19.324.0,18.345.0,59.197.0,39.126.0,41.144.0,48.147.0,24.179.0,55.185.0"}
P.entries["quest:76156"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem vede in te una predisposizione alla furtività e ti chiede di entrare nella miniera della S.P.R. & Co. Vuole che tu recuperi le cariche minerarie di Seaforium dai carri di rifornimenti della miniera.",h="Boarton Shadetotem vede in te una predisposizione alla furtività e ti chiede di entrare nella miniera della...",kw={"esplosivi","boarton shadetotem","maschera","miniera","cariche minerarie di seaforium","furtività","picco del tuono","s.p.r. & co."},ang={["class:Rogue"]="Da ladro, Boarton crede che tu abbia una predisposizione alla furtività e ti chiede di entrare nella miniera della S.P.R. & Co."},sec={{t="Un approccio furtivo",b="Boarton Shadetotem, a Picco del Tuono, crede che tu sappia agire con furtività. Ti dà una maschera e ti chiede di entrare nella vicina miniera della S.P.R. & Co. Lì dovrai prendere le cariche minerarie di Seaforium dai carri di esplosivi e riportargliele."}},faq={{q="Chi mi chiede di entrare nella miniera?",a="Boarton Shadetotem, a Picco del Tuono, ti chiede di entrare nella miniera della S.P.R. & Co.",al={"chi è boarton","boarton shadetotem","chi mi ha dato questo"}},{q="Che cosa devo cercare nella miniera?",a="Ti viene chiesto di prendere le cariche minerarie di Seaforium dai carri di esplosivi.",al={"cosa rubare","rifornimenti della miniera","cariche di seaforium"}},{q="Perché Boarton mi dà una maschera?",a="Boarton ti dà una maschera per entrare nella vicina miniera della S.P.R. & Co.",al={"maschera per travestirsi","perché la maschera","infiltrarsi nella miniera"}},{q="Dov'è la miniera della S.P.R. & Co.?",a="La miniera si trova a sud-est di Picco del Tuono.",al={"posizione della miniera","dov'è la miniera","miniera della s.p.r. & co."}},{q="A chi appartengono i rifornimenti?",a="I rifornimenti si trovano nella miniera della S.P.R. & Co.",al={"chi possiede i rifornimenti","rifornimenti della s.p.r. & co.","miniera della compagnia"}}},fp="26,172,17.257.0,30.79.0,34.79.0,32.70.0,34.39.0,32.45.0"}
P.entries["quest:76160"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem ti chiede di preparare un unguento con le Pigne di Furia del Vento che si trovano a nord di Picco del Tuono. Spera che faccia bruciare le ferite inflitte da una lama con una forza amara.",h="Boarton Shadetotem ti chiede di preparare un unguento con le Pigne di Furia del Vento che si trovano a nord...",kw={"boarton shadetotem","arpie","mortaio e pestello","unguento","caccia con l'earthmother","picco del tuono","pigne di furia del vento"},sec={{t="Un unguento amaro",b="Boarton Shadetotem, a Picco del Tuono, vuole un unguento velenoso, preparato con pigne raccolte vicino ai nidi delle arpie a nord. Devi pestare le Pigne di Furia del Vento con mortaio e pestello, poi portargli il preparato. Ti avverte che l'unguento finito può fare male anche solo a contatto con la pelle."}},faq={{q="Chi ti chiede l'unguento?",a="Boarton Shadetotem, a Picco del Tuono, ti chiede di preparare un unguento con le Pigne di Furia del Vento.",al={"chi vuole l'unguento","richiesta di boarton shadetotem"}},{q="Dove crescono le Pigne di Furia del Vento?",a="Le arpie a nord di Picco del Tuono fanno il nido su un albero che produce la resina tossica. Attorno ai loro nidi si trovano le pigne cadute.",al={"dove trovare le pigne","posizione delle pigne di furia del vento"}},{q="A cosa serve l'unguento?",a="Applicato su una lama, l'unguento dovrebbe far bruciare le ferite di un avversario e trasformarne il sangue in sale.",al={"a cosa serve l'unguento","unguento velenoso per lame"}},{q="Perché Boarton ti avverte di non toccarlo?",a="Boarton dice che anche il semplice contatto dell'unguento finito con la pelle potrebbe essere doloroso.",al={"avvertenza sull'unguento e la pelle","l'unguento è pericoloso"}}},fp="26,156,14.271.0,28.84.0,33.117.0,30.102.0,40.72.0"}
P.entries["quest:762"] = {n="An Ambassador of Evil",s="A Maleterre, Karnik lo Storico ti manda sulle tracce dell'Ambasciatore Infernus. Vuole che porti la prova della sua uccisione al Consigliere Belgrum a Forgiardente.",h="A Maleterre, Karnik lo Storico ti manda sulle tracce dell'Ambasciatore Infernus.",kw={"consigliere belgrum","ambasciatore infernus","fortezza di angor","maleterre","karnik lo storico","forgiardente","ragnaros","shadowforge","uldaman"},sec={{t="L'Ambasciatore nella Fortezza di Angor",b="Ragnaros ha mandato l'Ambasciatore Infernus alla Fortezza di Angor per sorvegliare la ricerca di artefatti perduti a Uldaman da parte del Clan Ferroscuro. La ricerca è già costata la vita a molti nani, e altri stanno morendo. Karnik teme che il Clan Ferroscuro possa usare gli artefatti contro Forgiardente. Perciò ti manda di nuovo a Maleterre per uccidere Infernus e portare a Belgrum la prova della tua vittoria. Il tempo stringe. Ragnaros non aspetterà che il Clan Ferroscuro si prepari."},{t="I ringraziamenti di Belgrum",b="Il Consigliere Belgrum elogia la tua dedizione a Forgiardente e al suo popolo. Manderà a Karnik la notizia del tuo successo, e aiuti verranno inviati a Maleterre per riprendere il sito di scavo. In nome di Re Bronzebeard, Belgrum ha un'altra richiesta da farti."}},faq={{q="Chi è l'Ambasciatore Infernus?",a="Ragnaros ha mandato Infernus alla Fortezza di Angor per sorvegliare la ricerca di artefatti perduti a Uldaman da parte del Clan Ferroscuro.",al={"chi è infernus","lore di infernus","storia dell'ambasciatore infernus"}},{q="Dove si trova l'Ambasciatore Infernus?",a="L'Ambasciatore Infernus si trova alla Fortezza di Angor, a Maleterre.",al={"dove trovare l'ambasciatore infernus","posizione dell'ambasciatore infernus","dove si trova infernus"}},{q="Perché Karnik vuole che l'Ambasciatore Infernus venga distrutto?",a="La ricerca del Clan Ferroscuro a Uldaman è già costata la vita a molti nani. Karnik teme che gli artefatti trovati possano essere usati contro Forgiardente.",al={"perché uccidere l'ambasciatore infernus","cosa sta facendo infernus a uldaman","minaccia forgia ardente maleterre"}},{q="Chi assegna e conclude questa missione?",a="Karnik lo Storico, a Forgiardente, ti manda sulle tracce di Infernus. Porta la prova della tua vittoria al Consigliere Belgrum a Forgiardente.",al={"chi inizia an ambassador of evil","chi riceve an ambassador of evil","datore della missione an ambassador of evil"}},{q="Che prova serve?",a="Il Consigliere Belgrum vuole il Bracciale dell'Ambasciatore Infernus come prova della tua vittoria.",al={"cosa mi serve da infernus","prova dell'ambasciatore infernus","bracciale di infernus"}}},fp="21,143,32.427.0,16.241.1,27.105.0,29.58.0,51.142.0,30.115.0,21.75.0"}
P.entries["quest:76240"] = {n="Stalk With The Earthmother",s="Boarton Shadetotem ti chiede di sfilettare un Raw Brilliant Smallfish a Picco del Tuono. Spera che l'esercizio riveli un talento per le arti sottili.",h="Boarton Shadetotem ti chiede di sfilettare un Raw Brilliant Smallfish a Picco del Tuono.",kw={"boarton shadetotem","knife set","raw brilliant smallfish","caccia con la madre terra","arti sottili","picco del tuono"},sec={{t="Una prova finale",b="Boarton Shadetotem, a Picco del Tuono, ti chiede di dimostrare la tua predisposizione con il suo Knife Set. Portagli un Raw Brilliant Smallfish e sfilettalo davanti a lui. Spera che questa prova meno diretta riveli un talento nascosto."},{t="Parole d'addio",b="Boarton Shadetotem capisce che ti manca la precisione furtiva che cercava. Ti offre un dono d'addio e ti manda per la tua strada, augurando all'Orda eroi come te."}},faq={{q="Chi mi chiede di sfilettare un pesce?",a="Boarton Shadetotem, a Picco del Tuono, ti chiede di sfilettare un Raw Brilliant Smallfish con il suo Knife Set.",al={"chi è boarton","boarton shadetotem","missione del coltello da pesce"}},{q="Perché Boarton vuole che sfiletti un pesce?",a="Boarton spera che l'esercizio riveli un talento nascosto per le arti sottili.",al={"perché sfilettare il pesce","cosa mette alla prova boarton","prova del pesciolino"}},{q="Quale pesce chiede Boarton?",a="Boarton chiede un Raw Brilliant Smallfish.",al={"quale pesce","pesciolino crudo","pesce brillante"}},{q="Dove sfiletto il pesce?",a="Sfiletta il Raw Brilliant Smallfish davanti a Boarton Shadetotem a Picco del Tuono.",al={"dove svolgere l'incarico con il pesce","pesce a picco del tuono","dove usare il knife set"}}},fp="26,141,13.214.0,13.162.1,34.100.0,42.74.0,31.43.0,27.83.0"}
P.entries["quest:763"] = {n="Rites of the Earthmother",s="Al Campo Narache, Capo Vento Agile ti manda oltre la Mesa Nuvola Rossa per proseguire i Rites of the Earthmother. Dopo le prime prove, porti un totem intagliato a nord, al Villaggio di Zoccolo Sanguinario, da Baine Zoccolo Sanguinario.",h="Al Campo Narache, Capo Vento Agile ti manda oltre la Mesa Nuvola Rossa per proseguire i Rites of the...",kw={"baine zoccolo sanguinario","villaggio di zoccolo sanguinario","cairne zoccolo sanguinario","campo narache","capo vento agile","mulgore","rites of the earthmother","totem dei vento agile"},ang={["faction:Horde"]="Come membro dell'Orda, partecipi a tradizioni che rafforzano l'unità delle tribù in tutta Mulgore e preparano nuovi difensori con abilità marziali e salde radici spirituali.",["race:Tauren"]="Da giovane tauren, percorri il sentiero della Madre Terra per dimostrare il tuo valore agli anziani e trovare il tuo posto tra le tribù unite."},sec={{t="Lasciare la Mesa",b="Da generazioni, i giovani tauren mettono alla prova la propria forza al Campo Narache, sulla Mesa Nuvola Rossa. Le prime prove insegnano disciplina e risolutezza. Ma i sacri Rites of the Earthmother richiedono più che sopravvivere alla fauna della mesa. Capo Vento Agile sa quando un iniziato è pronto a lasciare i protetti territori di caccia e a unirsi alla comunità più ampia."},{t="Un Pegno per Baine",b="Capo Vento Agile ti affida un totem intagliato a mano, che ti presenta lungo la strada da Narache agli insediamenti centrali. Portalo lungo il sentiero tortuoso fino al Villaggio di Zoccolo Sanguinario e presentati a Baine Zoccolo Sanguinario, il giovane capo e figlio dell'Alto Capo Cairne Zoccolo Sanguinario. Il totem è la tua credenziale e il tuo segno di approvazione. Dimostra che sei pronto per i riti dello spirito e della saggezza che ti attendono."}},faq={{q="Qual è lo scopo di questa missione?",a="I riti ti conducono dal Campo Narache alla più ampia comunità tauren del Villaggio di Zoccolo Sanguinario, dove cominciano le prove successive.",al={"perché compiere i riti della madre terra","cosa fa questa missione","scopo della missione"}},{q="Chi è Baine Zoccolo Sanguinario?",a="Baine Zoccolo Sanguinario è figlio dell'Alto Capo Cairne Zoccolo Sanguinario e il giovane capo del Villaggio di Zoccolo Sanguinario. Sovrintende alle prove spirituali e marziali dei giovani tauren.",al={"chi è baine","storia di baine","figlio di cairne"}},{q="Cos'è il Totem dei Vento Agile?",a="Il Totem dei Vento Agile è un oggetto di legno intagliato a mano da Capo Vento Agile del Campo Narache. È una credenziale ufficiale e un segno di approvazione, che mostra a Baine Zoccolo Sanguinario che hai la benedizione di Vento Agile per affrontare altri riti.",al={"totem dei vento agile","totem di vento agile","totem intagliato"}},{q="Quali riti seguono questo?",a="Al Villaggio di Zoccolo Sanguinario, Baine ti affida il Rite of Vision. Mette alla prova la tua sintonia spirituale attraverso sacre visioni ancestrali.",al={"prossimi riti","cosa viene dopo","prossima missione"}},{q="Dove si trova il Villaggio di Zoccolo Sanguinario?",a="Il Villaggio di Zoccolo Sanguinario si trova a nord del Campo Narache, sulle rive del Lago Toro di Pietra, nel centro di Mulgore. Segui la strada principale giù dalla mesa e dirigiti a nord.",al={"dove si trova il villaggio di zoccolo sanguinario","come trovare il villaggio di zoccolo sanguinario","sentiero per zoccolo sanguinario"}},{q="Perché bisogna completare i riti della Madre Terra?",a="I Rites of the Earthmother sono sacre tradizioni tauren. Superarne le fasi dimostra tempra fisica, legame spirituale e saggezza, guadagnandoti il riconoscimento degli anziani di Picco del Tuono.",al={"perché riti della madre terra","scopo delle prove tauren","storia dei rites of the earthmother"}}},fx={["4a33bb81"]={q="Perché Capo Vento Agile ti manda al Villaggio di Zoccolo Sanguinario?",a="Capo Vento Agile ti ha guidato nelle prove introduttive della Mesa Nuvola Rossa, ma Campo Narache non può più insegnarti nulla. Per completare i sacri Rites of the Earthmother e ottenere l'accettazione degli anziani di Picco del Tuono, devi fare più esperienza nelle vaste pianure di Mulgore. Mandandoti da Baine Zoccolo Sanguinario con il suo totem intagliato, Vento Agile affida la responsabilità della tua crescita spirituale e fisica a un capo in grado di mettere alla prova la tua preparazione alla vera età adulta.",al={"perché mandarti al villaggio di zoccolo sanguinario","motivo di capo vento agile","perché i rites of the earthmother"}},["9c980781"]={q="Perché devi consegnare il totem di persona?",a="Il viaggio non è una semplice commissione da corriere, ma una parte integrante del tuo rito di passaggio. Lasciare i confini protetti della Mesa Nuvola Rossa e seguire la strada aperta verso Mulgore dimostra la tua indipendenza e resistenza. Consegnando di persona il Totem dei Vento Agile, permetterai a Baine Zoccolo Sanguinario di vederti, riconoscere nel legno la raccomandazione personale di Vento Agile e giudicare direttamente il tuo carattere.",al={"perché devo portare il totem","perché vento agile non può mandare un messaggero","perché io per i rites of the earthmother"}}},fp="24,202,16.337.0,17.388.0,34.120.0,23.170.0,30.223.0,27.128.0,35.156.0,44.193.0"}
P.entries["quest:764"] = {n="La S.P.R. & Co.",s="Sulle colline orientali di Mulgore, i goblin scavano nonostante il rifiuto dei tauren. La S.P.R. & Co. li porta in forze per estrarre minerali dal suolo della Madre Terra, e Morin Bracca Nubi invoca una risposta letale.",h="Sulle colline orientali di Mulgore, i goblin scavano nonostante il rifiuto dei tauren.",kw={"goblin","diritti minerari","morin bracca nubi","mulgore","carovana depredata","s.p.r. & co.","miniera s.p.r. & co."},ang={["faction:Horde"]="Come membro dell’Orda, aiuti a difendere Mulgore dallo sfruttamento commerciale e proteggi il popolo di Cairne Zoccolo Sanguinario mentre mette al sicuro la sua nuova patria.",["profession:Mining"]="La S.P.R. & Co. estrae minerali con la forza bruta, tagliando gli angoli e destabilizzando il territorio senza riguardo per il suo equilibrio naturale o per pratiche minerarie sicure.",["race:Tauren"]="Per i tauren, la Madre Terra è sacra. Le attività minerarie della S.P.R. & Co. profanano la loro patria ancestrale, e i tauren intendono scacciare i goblin con la forza."},sec={{t="Intrusione Industriale",b="I tauren considerano Mulgore parte della Madre Terra. Ne apprezzano le pianure aperte e l’equilibrio della fauna. Quando la S.P.R. & Co. chiede di far saltare in aria e scavare le colline in cerca di minerali, le tribù rifiutano. La compagnia le ignora e porta macchinari, lavoratori e supervisori sulle dorsali orientali per estrarre minerali senza permesso."},{t="Un Messaggio Inconfondibile",b="Morin Bracca Nubi e gli altri esploratori tauren non vedono motivo di fare altri appelli una volta iniziati gli scavi. I documenti recuperati da una carovana depredata della S.P.R. & Co. confermano l’operazione. Morin ti manda contro i supervisori che schioccano le fruste e i lavoratori che azionano i trapani. Vuole che la compagnia paghi caro per aver violato il territorio."}},faq={{q="Perché la S.P.R. & Co. è a Mulgore?",a="La S.P.R. & Co. scava sulle colline orientali di Mulgore in cerca di minerali e altre risorse. I tauren hanno rifiutato la sua richiesta di diritti minerari, ma la compagnia ha avviato comunque le operazioni.",al={"perché i goblin sono a mulgore","motivo spr & co mulgore","cosa vuole la spr & co"}},{q="Chi ha dato l'ordine di attaccare i minatori?",a="Morin Bracca Nubi dà l’ordine. Tiene d’occhio la zona vicino al Villaggio di Zoccolo Sanguinario e considera il rifiuto della compagnia di accettare la decisione dei tauren una violazione che richiede l’uso della forza.",al={"chi assegna questa missione","ruolo di morin bracca nubi","datore di missione"}},{q="Dove si trova la miniera della S.P.R. & Co.?",a="La miniera principale della Venture Company si trova ai piedi dei monti, a est della Carovana Depredata e del Villaggio di Zoccolo Sanguinario. Il personale della compagnia si raduna anche in un avamposto più piccolo, sulle alture a nord-est degli ascensori settentrionali di Picco del Tuono.",al={"posizione miniera spr & co","dove sono i supervisori","dove trovare la spr & co"}},{q="I tauren hanno mai provato a negoziare con i goblin?",a="Sì. La S.P.R. & Co. ha chiesto ai tauren i diritti minerari a Mulgore, ma i capi tribù hanno rifiutato il permesso di estrarre a cielo aperto nelle loro terre ancestrali. I goblin hanno scavato comunque, senza permesso.",al={"i tauren hanno permesso l'estrazione","diritti minerari mulgore","i goblin hanno chiesto il permesso"}},{q="Questi goblin fanno parte del Cartello degli Spargifumo?",a="No. La S.P.R. & Co. è un cartello industriale indipendente e predatorio, separato da gruppi commerciali neutrali come il Cartello degli Spargifumo. È ostile alle popolazioni locali ovunque sfrutti le risorse.",al={"sono questi goblin di porto paranco","la spr & co è amichevole","fazione della venture company"}},{q="Come si collega questo alle carovane depredate?",a="La carovana depredata era un convoglio della S.P.R. & Co. distrutto dai tauren. Le casse e i documenti della sua divisione mineraria hanno rivelato le operazioni della compagnia a Mulgore, spingendo i tauren ad attaccare la miniera.",al={"connessione carovana","la spr & co ha attaccato le carovane","la connessione con la carovana depredata"}}},fx={f6df914e={q="Perché Morin Bracca Nubi vuole che la S.P.R. & Co. venga attaccata?",a="Alla S.P.R. & Co. è stato ufficialmente negato il diritto di estrarre minerali a Mulgore, eppure la compagnia ha ignorato il rifiuto e ha iniziato comunque ad ammassare attrezzature e lavoratori. Morin Bracca Nubi non può permettere che dissacrino la terra e ne depredino impunemente le risorse naturali. Poiché la diplomazia e i rifiuti categorici non sono bastati a frenare la loro avidità, crede che i tauren debbano lanciare un messaggio inequivocabile e deciso: le incursioni e i furti non saranno tollerati.",al={"motivo di morin bracca nubi","perché attaccare la s.p.r. & co.","perché morin vuole uccidere la s.p.r. & co."}},eda5096c={q="Chi ti viene chiesto di affrontare nella miniera?",a="Ti viene chiesto di affrontare i supervisori e i lavoratori della S.P.R. & Co. stanziati nel loro sito minerario nella parte orientale di Mulgore. Questi goblin e lavoratori assoldati scavano in profondità nelle colline sacre per estrarre minerali senza il permesso della tribù, guidati da capisquadra avidi di profitto che impongono l'espansione aggressiva e illegale della compagnia.",al={"bersagli della missione della s.p.r. & co.","chi sono i lavoratori della s.p.r. & co.","chi devo affrontare nella miniera"}}},fp="15,191,20.326.0,23.321.0,38.172.0,40.172.0,42.216.0,54.193.0,50.216.0,46.195.0"}
P.entries["quest:765"] = {n="Il Supervisore Fischiarazzo",s="A Mulgore, Morin Bracca Nubi chiede aiuto contro la miniera della S.P.R. & Co. I documenti della Carovana Depredata rivelano un piano per scacciare i tauren dalla loro terra, e Morin ha bisogno degli appunti del Supervisore Fizsprocket.",h="A Mulgore, Morin Bracca Nubi chiede aiuto contro la miniera della S.P.R.",kw={"appunti","fizsprocket","miniera","morin bracca nubi","mulgore","supervisore","s.p.r. & co."},ang={["faction:Horde"]="Come membro dell'Orda, aiuti i tauren a resistere all'avanzata della S.P.R. & Co. Difendi le terre centrali dell'Orda a Kalimdor.",["race:Tauren"]="Come tauren, difendi il tuo popolo e la tua terra quando colpisci Fizsprocket. La sua compagnia intende scacciare la tua tribù da Mulgore e depredarne le ricchezze."},sec={{t="Un Complotto contro le Pianure",b="Una carovana della S.P.R. & Co. giace distrutta e i suoi documenti rivelano un piano per scacciare i tauren da Mulgore. La compagnia vuole impossessarsi delle pianure e dei filoni sotterranei. Vuole depredarne le risorse senza che i tauren si mettano di traverso."},{t="Colpisci il Caposghigno",b="Morin Bracca Nubi invia dei campioni alla miniera della S.P.R. & Co., a est della Carovana Depredata. Il Supervisore Fizsprocket dirige la miniera, nel profondo dei tunnel sulla destra, tra lavoratori e vicecapi. Morin vuole gli appunti di Fizsprocket per scoprire i prossimi piani della compagnia."}},faq={{q="Chi è il Supervisore Fizsprocket?",a="Il Supervisore Fizsprocket dirige le operazioni della S.P.R. & Co. nella miniera a est di Mulgore. Sorveglia i lavoratori che scavano la terra e mette in atto i piani della compagnia nella regione.",al={"fizsprocket","chi è fizsprocket","lore di fizsprocket"}},{q="Perché Morin Bracca Nubi vuole Fizsprocket morto?",a="I documenti di una carovana saccheggiata mostrano che la S.P.R. & Co. intende scacciare i tauren da Mulgore per profitto. Morin Bracca Nubi vuole Fizsprocket morto perché dirige quei complotti.",al={"perché uccidere fizsprocket","motivazione di morin bracca nubi"}},{q="Dove si trova il Supervisore Fizsprocket?",a="Fizsprocket si trova nella miniera della S.P.R. & Co., a est della Carovana Depredata, a Mulgore. Segui il tunnel sulla destra fino a una sala piena di lavoratori e supervisori.",al={"dove si trova fizsprocket","posizione miniera di fizsprocket","mappa di fizsprocket"}},{q="Quale prova richiede Morin della sconfitta di Fizsprocket?",a="Morin Bracca Nubi vuole gli appunti personali di Fizsprocket. I suoi registri potrebbero rivelare i piani futuri della S.P.R. & Co. a Mulgore.",al={"prova di morte","appunti di fizsprocket"}},{q="Perché la S.P.R. & Co. si trova a Mulgore?",a="La S.P.R. & Co. è a Mulgore per depredarne il legname, i minerali e le ricchezze sotterranee. Non tiene conto degli abitanti né della terra che sfrutta.",al={"s.p.r. & co. mulgore","perché i goblin sono a mulgore"}},{q="Uccidere Fizsprocket caccia via definitivamente la S.P.R. & Co.?",a="No. La morte di Fizsprocket sconvolge la dirigenza locale e fornisce a Morin Bracca Nubi informazioni sui piani della compagnia. La S.P.R. & Co. resta una minaccia sulle colline di Mulgore.",al={"la s.p.r. & co. se n'è andata","dopo la morte di fizsprocket"}}},fp="22,216,25.239.0,21.285.1,30.187.0,50.189.0,40.158.0,54.129.0,38.156.0,67.165.0"}
P.entries["quest:766"] = {n="Mazzranache",s="Nel Villaggio di Zoccolo Sanguinario, il morso di Mazzranache riduce Maur Invoca Pioggia in fin di vita, divorato dalla febbre. Una generazione fa, lo zampalunga infestava i racconti di suo nonno. Ora Maur è tormentato da incubi deliranti mentre il veleno minaccia di ucciderlo.",h="Nel Villaggio di Zoccolo Sanguinario, il morso di Mazzranache riduce Maur Invoca Pioggia in fin di vita...",kw={"villaggio di zoccolo sanguinario","puma delle pianure","maur invoca pioggia","mazzranache","mulgore","zampalunga","lupo della prateria","avvoltoio"},ang={["class:Hunter"]="Da cacciatore, puoi leggere le pianure seguendo le tracce di lupi della prateria, puma, zampalunga e avvoltoi per tutta Mulgore.",["faction:Horde"]="Come membro dell'Orda, aiuti a proteggere il Villaggio di Zoccolo Sanguinario dai pericoli di Mulgore e contribuisci alla pace e alla stabilità della patria dei tauren.",["race:Tauren"]="Come tauren, sai che il rimedio di Maur segue un'antica usanza: ricavare cure dalla flora e dalla fauna di Earth Mother."},sec={{t="Un'eredità delle pianure",b="Maur Invoca Pioggia conosceva Mazzranache solo dai racconti di suo nonno. L'anziano tauren parlava di uno zampalunga selvaggio, con occhi rossi luminosi, artigli affilati come rasoi e un morso tossico, diverso da quello della maggior parte della fauna di Mulgore. Poi Maur incontrò la bestia nella prateria. L'avvertimento di suo nonno si avverò e il morso lo ferì gravemente, mentre cercava di raggiungere un luogo sicuro."},{t="Contro il tempo per l'infezione",b="Il veleno di Mazzranache provoca a Maur febbre alta e deliri da incubo. Gli serve un rimedio prima che l'infezione diventi fatale. La medicina tradizionale tauren attinge alla vitalità delle bestie locali, perciò a Maur servono un Cuore di Lupo della Prateria, un Femore di Puma delle Pianure, una Scaglia di Zampalunga delle Pianure e uno Stomaco dell'Avvoltoio. Queste parti insieme possono formare un infuso che arresta la diffusione necrotica e lo aiuta a ristabilirsi."}},faq={{q="Cos'è Mazzranache?",a="Nelle praterie di Mulgore, Mazzranache è uno zampalunga selvaggio. Il suo piumaggio vivace, gli occhi rossi demoniaci, gli artigli feroci e il morso velenoso terrorizzano i viaggiatori da generazioni.",al={"chi è mazzranache","che tipo di bestia è mazzranache","storia di mazzranache"}},{q="Chi è Maur Invoca Pioggia?",a="Maur Invoca Pioggia vive nel Villaggio di Zoccolo Sanguinario. Mazzranache gli tese un'imboscata e gli morse la spalla mentre attraversava Mulgore, lasciandolo a letto con un'infezione potenzialmente letale.",al={"maur invoca pioggia","chi mi ha dato questa missione","chi è il tauren malato"}},{q="Perché Maur ha bisogno di parti di quattro bestie diverse?",a="I rimedi tauren attingono ai punti di forza e alle essenze spirituali degli animali delle pianure per contrastare le tossine potenti. Un cuore di lupo, il midollo di un femore di puma, una scaglia di zampalunga e uno stomaco di avvoltoio insieme formano un antidoto abbastanza potente da combattere il veleno di Mazzranache.",al={"perché cuore di lupo e femore di puma","perché ingredienti animali","ingredienti per il rimedio di mazzranache"}},{q="Il nonno di Maur ha ucciso Mazzranache?",a="No. Il nonno di Maur affrontò Mazzranache anni fa, ma non riuscì a sconfiggere il feroce zampalunga. Sopravvisse e mise in guardia i suoi discendenti sui suoi colori vivaci e i suoi attacchi feroci.",al={"il nonno ha sconfitto mazzranache","nonno di maur e mazzranache","chi ha combattuto mazzranache prima"}},{q="Questa missione mi chiede di dare la caccia a Mazzranache in persona?",a="No. Maur deve sopravvivere alla febbre, quindi la priorità è procurarsi le parti necessarie per la cura.",al={"devo uccidere mazzranache","dove si trova mazzranache","cacciare mazzranache"}},{q="Dove si trova il Villaggio di Zoccolo Sanguinario?",a="Il Villaggio di Zoccolo Sanguinario si trova nel centro di Mulgore, a sud di Picco del Tuono e a est del Lago Toro di Pietra. Da questo insediamento i giovani tauren coraggiosi iniziano i loro viaggi attraverso le pianure.",al={"dove si trova il villaggio di zoccolo sanguinario","posizione del villaggio di zoccolo sanguinario"}}},fx={["3b88d77e"]={q="Perché Maur Invoca Pioggia vuole che venga fatto?",a="La vita di Maur è direttamente in pericolo. Mentre attraversava le pianure di Mulgore, si è imbattuto in Mazzranache, un leggendario trotarossa famoso per aver terrorizzato suo nonno. La creatura gli ha assestato un morso feroce e velenoso alla spalla. Gli è salita una febbre debilitante, che gli provoca incubi deliranti e si diffonde progressivamente nel corpo. Senza gli ingredienti animali necessari per preparare una cura medicinale, la violenta infezione lo ucciderà presto.",al={"motivo di maur invoca pioggia","perché aiutare maur invoca pioggia","cos'è successo a maur"}},ce37bf7e={q="Perché Maur ha bisogno di un forestiero invece di curarsi da solo?",a="Maur è troppo gravemente ferito e febbricitante per cacciare da solo le bestie di Mulgore. Il morso velenoso di Mazzranache lo ha debilitato, provocandogli delirio e spossatezza, e lo ha costretto a restare al Villaggio di Zoccolo Sanguinario. Con il tempo che stringe prima che l'infezione diventi fatale, deve affidarsi ai viaggiatori di passaggio per rintracciare i veloci felini, i grifalchi, i lupi e i trotarossa necessari al suo rimedio.",al={"perché maur non può procurarsi gli ingredienti","perché maur ha bisogno di te","perché io contro mazzranache"}}},fp="11,227,22.365.0,20.389.0,20.179.0,23.169.0,52.247.0,40.178.0,55.95.0,35.174.0"}
P.entries["quest:767"] = {n="Rite of Vision",s="Baine Zoccolo Sanguinario manda i viaggiatori attraverso Mulgore in cerca di Zarlman Due Lune, prima del Rite of Vision. La prova fa parte dei Rites of the Earthmother e gli anziani sulle alture di Picco del Tuono la considerano un segno di maturità spirituale.",h="Baine Zoccolo Sanguinario manda i viaggiatori attraverso Mulgore in cerca di Zarlman Due Lune, prima del Rite...",kw={"baine zoccolo sanguinario","villaggio di zoccolo sanguinario","mulgore","rite of vision","rites of the earthmother","prova tauren","picco del tuono","zarlman due lune"},ang={["class:Druid"]="Da druido, comunicare con le visioni della Madre Terra rafforza la tua vocazione ad ascoltare la saggezza e i sussurri del mondo vivente.",["class:Shaman"]="Da sciamano, cercare Zarlman Due Lune e percorrere il cammino delle visioni richiama il tuo dovere di bilanciare le questioni terrene con la volontà degli antenati.",["faction:Horde"]="Come membro dell'Orda, intraprendere queste tradizioni sacre dimostra la tua lealtà e il tuo rispetto per gli anziani tauren che contribuiscono a guidare l'Orda.",["race:Tauren"]="Come tauren, con il Rite of Vision raggiungi una tappa culturale fondamentale. Segna il tuo cammino verso il ruolo di difensore fidato e guida spirituale delle tribù."},sec={{t="Un sacro trampolino di lancio",b="Per generazioni, i tauren nomadi hanno seguito la guida della Madre Terra attraverso le pianure di Kalimdor. Ora si sono riuniti entro i confini sicuri di Mulgore, dove le tradizioni spirituali sono ancora al centro della loro società. Le prove precedenti mettono alla prova la forza di un iniziato e il suo legame con la caccia. Il Rite of Vision invita i giovani tauren e gli alleati onorati a rivolgersi agli spiriti."},{t="La guida del veggente",b="Prima di cercare una visione, un iniziato ha bisogno di una guida nelle antiche usanze. Al Villaggio di Zoccolo Sanguinario, il venerato sciamano Zarlman Due Lune offre i suoi consigli. Baine Zoccolo Sanguinario affida i viaggiatori alle sue cure. Zarlman riconosce chi segue il cammino degli antenati, poi gli insegna i primi riti e le preparazioni sacre per guardare oltre il mondo fisico."}},faq={{q="Cos'è il Rite of Vision?",a="Il Rite of Vision è un rito sacro della Madre Terra. Apre la vista spirituale di un avventuriero, permettendogli di comunicare con gli spiriti ancestrali e dimostrare agli anziani di Picco del Tuono di essere pronto sul piano spirituale.",al={"missione rite of vision","cos'è il rite of vision","storia del rite of vision"}},{q="Chi inizia questa missione?",a="Baine Zoccolo Sanguinario manda i viaggiatori a intraprendere il Rite of Vision. Figlio dell'Alto Capo Cairne Zoccolo Sanguinario, veglia sul Villaggio di Zoccolo Sanguinario e indirizza i viaggiatori meritevoli ai suoi anziani spirituali.",al={"chi assegna il rite of vision","chi dà la missione rite of vision"}},{q="Chi è Zarlman Due Lune?",a="Zarlman Due Lune è uno sciamano tauren esperto e la guida spirituale del Villaggio di Zoccolo Sanguinario. Prepara viaggiatori e iniziati per prove sacre come il Rite of Vision.",al={"chi è zarlman","storia di zarlman due lune"}},{q="Perché i Rites of the Earthmother sono importanti per i tauren?",a="I Rites of the Earthmother segnano il tradizionale passaggio all'età adulta per i tauren. Completarli dimostra abilità fisica, sintonia spirituale e un profondo rispetto per la terra, e fa guadagnare l'onore degli alti anziani.",al={"significato dei rites of the earthmother","perché fare i rites of the earthmother"}},{q="I non-tauren possono intraprendere il Rite of Vision?",a="Sì. Gli alleati dell'Orda che attraversano Mulgore possono seguire il cammino della Madre Terra, se conquistano la fiducia della tribù Zoccolo Sanguinario. Rendono onore alle tradizioni tauren e sperano di ottenere il favore degli anziani.",al={"gli orchi possono fare il rite of vision","non tauren madre terra"}},{q="Dove si svolge questa prova?",a="La prova inizia al Villaggio di Zoccolo Sanguinario, vicino alle rive del Lago Toro di Pietra, nel centro di Mulgore. Il villaggio si trova a sud di Picco del Tuono.",al={"dove si trova il rite of vision","posizione del rite of vision"}}},fx={["1fa313da"]={q="Perché Baine Zoccolo Sanguinario vuole che tu intraprenda il Rite of Vision?",a="Baine Zoccolo Sanguinario ti prepara a seguire il cammino dei tuoi antenati e a dimostrare il tuo valore al popolo tauren. Raggiunta la maggiore età a Mulgore, devi affrontare i sacri Rites of the Earthmother per entrare in comunione con gli spiriti, imparare a rispettare la terra e infine guadagnarti il rispetto degli anziani di Picco del Tuono. Baine ti manda dal mistico del villaggio Zarlman Due Lune, così potrai iniziare come si deve la prova spirituale.",al={"perché baine ti manda al rite of vision","motivo di baine zoccolo sanguinario per il rite of vision","perché fare il rite of vision"}}},fp="14,235,23.398.0,19.348.0,27.208.0,22.192.0,25.171.0,61.213.0,44.187.0,33.132.0"}
P.entries["quest:768"] = {n="Procurati la pelle",s="A Picco del Tuono, Veren Passo Alto chiede ai cacciatori Cuoio Leggero per la capitale. Scambia beni artigianali con le pelli, seguendo la tradizione tauren di ricavare vestiti e armature dalla caccia nelle pianure.",h="A Picco del Tuono, Veren Passo Alto chiede ai cacciatori Cuoio Leggero per la capitale.",kw={"cuoio da raccolta","conciatura","cuoio leggero","mulgore","caccia tauren","picco del tuono","veren passo alto"},ang={["class:Hunter"]="Come cacciatore, sei adatto a seguire le prede attraverso le pianure di Mulgore e a raccogliere le pelli leggere di cui Veren ha bisogno.",["faction:Horde"]="Come membro dell'Orda, contribuisci a rifornire gli artigiani di Picco del Tuono mentre la giovane capitale rafforza le sue difese e le sue reti commerciali.",["race:Tauren"]="Come cacciatore tauren, onori una bestia caduta trasformandone la pelle in beni utili. Questa disciplina si tramanda da generazioni."},sec={{t="Sostenere Picco del Tuono",b="Picco del Tuono ha bisogno di mani esperte per realizzare vestiti e armature per la popolazione in crescita. Veren Passo Alto lavora le pelli per ricavarne beni utili e chiede ai giovani cacciatori di portargli le prede al ritorno dalle pianure. Le loro battute di caccia aiutano a rifornire la capitale e a sfamare la tribù."},{t="La Via della Caccia",b="I tauren cacciano nelle praterie per sfamare, vestire e proteggere la tribù. Veren Passo Alto chiede ai cacciatori che vogliono portare onore al proprio clan Cuoio Leggero ricavato dalla fauna locale. In cambio, scambia beni artigianali con dodici pelli ben tenute, sostenendo i legami che uniscono la società tauren."}},faq={{q="Chi è Veren Passo Alto?",a="Veren Passo Alto è un conciatore a Picco del Tuono. Realizza vestiti e armature per i tauren e scambia i suoi manufatti con pelli delle pianure.",al={"veren passo alto","chi dà cuoio da raccolta","committente di missione di cuoio a picco del tuono"}},{q="Di cosa ha bisogno Veren Passo Alto?",a="Veren ha bisogno di dodici pezzi di Cuoio Leggero ricavato dagli animali di Mulgore e dei territori vicini. Usa le pelli per realizzare beni destinati a Picco del Tuono.",al={"requisiti cuoio da raccolta","cosa portare a veren","materiali cuoio da raccolta"}},{q="Dove si svolge questa missione?",a="Incontri Veren Passo Alto in cima a Picco del Tuono. Per portargli ciò di cui ha bisogno, caccia le bestie selvatiche nelle praterie sottostanti.",al={"dove si trova veren passo alto","luogo cuoio da raccolta"}},{q="Perché i tauren danno così tanta importanza alla caccia alle bestie?",a="La caccia tauren onora l'equilibrio con la Earth Mother. La tribù usa ogni parte della bestia abbattuta: la carne come cibo, le ossa e le pelli conciate per attrezzi, tende e armature.",al={"cultura della caccia tauren","perché cacciare per il cuoio","lore cuoio tauren"}},{q="Qualsiasi avventuriero dell'Orda può svolgere questo incarico?",a="Sì. Qualsiasi viaggiatore leale all'Orda può aiutare a raccogliere pelli, se Veren crede che abbia voglia di mettere alla prova il proprio valore nelle pianure.",al={"chi può fare cuoio da raccolta","la raccolta di cuoio è riservata all'orda"}},{q="Cosa succede una volta consegnato il cuoio?",a="Dopo che consegni le pelli, Veren ne controlla la qualità e si congratula con te per il lavoro. In cambio equo, ti dà un pezzo di equipaggiamento artigianale.",al={"consegna cuoio da raccolta","ricompensa veren passo alto"}}},fx={["1249c214"]={q="Perché Veren Passo Alto vuole del Cuoio Leggero?",a="Veren Passo Alto è un conciatore che crea abiti e armature per gli abitanti di Picco del Tuono. Per rifornire la città e mandare avanti il suo mestiere, si affida ai cacciatori affinché gli portino pelli di qualità dalle pianure di Mulgore.",al={"perché veren vuole il cuoio","motivo di veren passo alto","perché il cuoio leggero per veren"}},cd30155e={q="A cosa serve il Cuoio Leggero?",a="Il cuoio viene trasformato in indumenti essenziali, armature protettive e oggetti utili per i tauren che abitano sulle alture di Picco del Tuono, oltre che in equipaggiamento realizzato in cambio di merci per i cacciatori di passaggio.",al={"a cosa serve il cuoio leggero","uso del cuoio leggero","come usa veren il cuoio leggero"}}},fp="17,203,24.268.0,19.288.0,25.146.0,33.146.0,33.116.0,61.180.0,45.129.0,43.133.0"}
P.entries["quest:769"] = {n="La Sacca di Pelle di Kodo",s="Veren Passo Alto insegna agli apprendisti conciatori di Picco del Tuono un'arte nata nelle pianure. Chiede Cuoio Leggero conciato e filo resistente.",h="Veren Passo Alto insegna agli apprendisti conciatori di Picco del Tuono un'arte nata nelle pianure.",kw={"filo grezzo","kodo","borsa di pelle di kodo","conciatura","cuoio leggero","mulgore","picco del tuono","veren passo alto"},ang={["faction:Horde"]="In quanto membro dell'Orda, fai affidamento sugli artigiani di Picco del Tuono per fornire ai cacciatori, agli esploratori e ai guerrieri ciò che serve per affrontare Kalimdor centrale.",["race:Tauren"]="In quanto Shu'halo, onori i doni della Madre Terra e preservi le tradizioni ancestrali imparando a creare equipaggiamento affidabile dalla pelle del possente kodo."},sec={{t="Una lezione sulle alture",b="Veren Passo Alto insegna Conciatura sulle terrazze artigianali di Picco del Tuono. Segue la tradizione nomade di non sprecare nulla della caccia. Portagli Cuoio Leggero conciato e filo resistente, e ti insegnerà. Con questi materiali di base, gli apprendisti dimostrano di saper creare beni capaci di trasportare l'attrezzatura per sopravvivere nelle aspre distese di Kalimdor."},{t="Spirito del Kodo",b="Per i tauren, il kodo è un simbolo di resistenza, forza e ferma risolutezza. La sua spessa pelle protegge dai rovi, dai venti pungenti e dagli artigli delle bestie. Creare borse e indumenti con la pelle di kodo è un lavoro utile e rende onore all'animale che per generazioni ha nutrito e trasportato gli Shu'halo attraverso le pianure di Mulgore."}},faq={{q="Chi offre la missione Borsa di Pelle di Kodo?",a="Veren Passo Alto, un addestratore di Conciatura tauren e mercante a Picco del Tuono, offre questo addestramento.",al={"datore di missioni","dove prendere la missione borsa di pelle di kodo","posizione di veren passo alto"}},{q="Chi può intraprendere questo compito?",a="I conciatori con almeno dieci punti nell'abilità da apprendista possono ricevere questo addestramento da Veren Passo Alto.",al={"chi può accettare questa missione","requisiti della missione","requisito di professione"}},{q="Quali materiali richiede Veren Passo Alto?",a="Veren Passo Alto chiede quattro pezzi di Cuoio Leggero e quattro matasse di Filo Grezzo per rifornire le sue scorte commerciali prima di condividere il suo modello.",al={"quali oggetti servono","materiali borsa di pelle di kodo","oggetti per completare la missione"}},{q="Perché la pelle di kodo è considerata significativa per gli artigiani tauren?",a="I kodo incarnano la resilienza e la forza fisica, qualità che i tauren hanno a cuore. L'equipaggiamento ricavato dalle loro pelli rende onore allo spirito della creatura e aiuta i viaggiatori ad attraversare le pianure.",al={"perché pelle di kodo","significato kodo tauren","importanza del kodo"}},{q="Cosa insegna Veren Passo Alto al completamento?",a="Dopo aver ricevuto i rifornimenti, Veren insegna all'artigiano a cucire una Sacca di Pelle di Kodo.",al={"ricompensa della missione","cosa ottengo","modello di borsa"}},{q="Dove si possono reperire i materiali necessari?",a="Puoi scuoiere bestie di basso livello in tutta Mulgore e nelle terre vicine per ottenere Cuoio Leggero. I mercanti di merci e i sarti vendono Filo Grezzo.",al={"dove trovare cuoio leggero","dove trovare filo grezzo"}}},fx={c94273ea={q="Perché Veren Passo Alto vuole che venga fatto?",a="Veren Passo Alto è orgoglioso di aiutare la prossima generazione di conciatori tauren. I kodo di Mulgore sono venerati per la loro forza e resistenza, e creare una borsa tradizionale con le loro pelli è una competenza fondamentale. Chiedendoti di raccogliere materiali per il suo mestiere, Veren mette alla prova la tua dedizione e la tua intraprendenza prima di tramandarti le tecniche artigianali.",al={"perché veren passo alto vuole il cuoio","motivo di veren passo alto","perché la missione della borsa di pelle di kodo"}},["1f62e959"]={q="A cosa serve il Cuoio Leggero?",a="Il Cuoio Leggero è il materiale fondamentale che Veren Passo Alto richiede in cambio dei suoi insegnamenti. Lavorare le pelli conciate è il cuore della lavorazione del cuoio tauren, e fornire cuoio di qualità dimostra che hai appreso le basi della concia prima di imparare a cucire contenitori specializzati come le borse di pelle di kodo.",al={"a cosa serve il cuoio leggero","perché portare il cuoio leggero","scopo del cuoio leggero"}},["7d0f7d7f"]={q="A cosa serve il Filo Grezzo?",a="Il Filo Grezzo è un materiale essenziale per la sartoria e la lavorazione del cuoio, usato per unire pelli spesse. Per costruire zaini resistenti, in grado di sopportare le pianure di Mulgore, un artigiano ha bisogno di una corda robusta che non si spezzi sotto forti sollecitazioni o con il maltempo.",al={"perché il filo grezzo","scopo del filo grezzo","a cosa serve il filo grezzo"}}},fp="13,149,20.327.0,18.307.0,35.102.0,39.105.0,46.150.0,59.171.0,50.82.0,46.132.0"}
P.entries["quest:77"] = {n="A Sticky Situation",s="Dran Droffers cerca l'imballaggio originale del Vino Dolce delle Entroterre. Gilveradin Calcasole ce l'ha e chiede due bottiglie in più; dieci bottiglie sono nelle casse attorno alla base abbandonata dell'Orda vicino al Tumulo Strisciante.",h="Dran Droffers cerca l'imballaggio originale del Vino Dolce delle Entroterre.",kw={"dran droffers","gilveradin calcasole","entroterre","vino dolce delle entroterre","melme","tumulo strisciante"},sec={{t="Questione di imballaggio",b="Dran Droffers cerca il Vino Dolce delle Entroterre e Gilveradin Calcasole ha il suo imballaggio originale. Gilveradin si offre di aiutare in cambio di due bottiglie in più. Raccogli dieci bottiglie e riportale all'accampamento."},{t="Rovine del Tumulo Strisciante",b="Le casse di Vino Dolce delle Entroterre sono sparse attorno alla base abbandonata dell'Orda vicino al Tumulo Strisciante. Melme e fanghi ripugnanti infestano le rovine. Si dice che una melma suprema li guidi."}},faq={{q="Chi vuole che il Vino Dolce delle Entroterre venga impacchettato?",a="Dran Droffers cerca il Vino Dolce delle Entroterre. Gilveradin Calcasole ha il suo imballaggio originale, destinato al padre di Malton.",al={"chi ha bisogno del vino","dran droffers vino","per chi è l'imballaggio"}},{q="Qual è il prezzo richiesto da Gilveradin per l'imballaggio?",a="Gilveradin chiede due bottiglie in più del vino come compenso. Dieci bottiglie sono nelle casse.",al={"perché 10 bottiglie","compenso di gilveradin","perché così tanto vino"}},{q="Dove si trovano le casse di Vino Dolce delle Entroterre?",a="Le casse si trovano attorno alla base abbandonata dell'Orda vicino alle Entroterre, presso il Tumulo Strisciante.",al={"posizione del vino","dove si trova il vino dolce","casse tumulo strisciante"}},{q="Cosa si trova nell'accampamento abbandonato al Tumulo Strisciante?",a="Melme e fanghi ripugnanti infestano le rovine, e si dice che una melma suprema li guidi.",al={"mostri tumulo strisciante","cosa c'è al tumulo strisciante","melme tumulo strisciante"}}},fp="18,208,21.209.0,19.176.0,48.121.0,46.94.0,54.82.0,44.82.0"}
P.entries["quest:770"] = {n="Il manto straziato dal demone",s="A Mulgore, il Manto Straziato dal Demone porta i segni del tormento di Ghost Howl. La pelle apparteneva a un leggendario lupo bianco, sfregiato dalla Legione Infuocata. Il suo arrivo al Villaggio di Zoccolo Sanguinario chiude la tormentata storia della bestia.",h="A Mulgore, il Manto Straziato dal Demone porta i segni del tormento di Ghost Howl.",kw={"legione infuocata","manto straziato dal demone","ghost howl","mulgore","skorn nube bianca","lupo bianco"},ang={["class:Druid"]="Da druido, vedi il manto segnato dai demoni come un cupo promemoria: la terra e i suoi abitanti selvaggi portano ancora ferite mai rimarginate dall'invasione demoniaca di Kalimdor.",["class:Hunter"]="Da cacciatore, sai che rintracciare un alfa solitario e sfregiato come Ghost Howl è un rito di passaggio. L'anziano Skorn Nube Bianca loda la tua abilità e ti dona un dono degno di un maestro cacciatore.",["race:Tauren"]="Da Shu'halo, puoi vedere la caccia a Ghost Howl come un rito solenne, che libera una creatura agonizzante dalla persistente contaminazione della Legione Infuocata."},sec={{t="Una reliquia di ferite demoniache",b="Ghost Howl è un leggendario lupo bianco, il cui ululato malinconico echeggia per Mulgore. La pelle lasciata dalla bestia porta i segni della corruzione demoniaca. Quelle ferite risalgono alle disperate battaglie contro i demoni invasori della Legione Infuocata. Rimasero impresse nella carne e nello spirito di Ghost Howl molto tempo dopo la Terza Guerra."},{t="Pace per uno spirito tormentato",b="I tauren di Mulgore venerano le bestie selvatiche della loro patria come figli della Madre Terra. Al Villaggio di Zoccolo Sanguinario, Skorn Nube Bianca riceve il manto sfregiato come prova della morte del predatore tormentato. Riconosce l'abilità necessaria per rintracciare e sconfiggere Ghost Howl. Con tristezza, spera che lo spirito torturato del lupo abbia trovato pace."}},faq={{q="Cos'è il Manto Straziato dal Demone?",a="Il Manto Straziato dal Demone è la pelle lacera lasciata da Ghost Howl, un leggendario lupo bianco di Mulgore. Le energie vili la sfregiarono durante un'antica battaglia contro la Legione Infuocata.",al={"cos'è il manto straziato dal demone","oggetto manto straziato dal demone","pelle di ghost howl"}},{q="Da dove provengono le cicatrici demoniache sul manto?",a="Ghost Howl fu ferito negli scontri con i demoni invasori della Legione Infuocata durante la Terza Guerra, mentre avanzavano attraverso Kalimdor.",al={"perché ghost howl è sfregiato","come si è procurato le cicatrici ghost howl","ghost howl legione"}},{q="A chi devo portare il manto?",a="Porta il manto a Skorn Nube Bianca, un anziano cacciatore tauren che vive al Villaggio di Zoccolo Sanguinario, a Mulgore.",al={"dove consegno il manto straziato dal demone","chi vuole il manto straziato dal demone","consegna skorn nube bianca"}},{q="Perché Skorn Nube Bianca si interessa a Ghost Howl?",a="Skorn Nube Bianca è un cacciatore in pensione, consapevole della profonda sofferenza di Ghost Howl a causa della corruzione demoniaca. Rispetta l'abilità necessaria per abbattere la bestia e spera che il suo spirito possa finalmente riposare.",al={"storia di skorn nube bianca","perché skorn vuole ghost howl"}},{q="Dove si trova Ghost Howl?",a="Ghost Howl vaga per la Piana Ondulata di Mulgore, di solito nei campi aperti settentrionali o centrali tra la Mesa Nuvola Rossa e il Picco del Tuono.",al={"dove trovare ghost howl","posizione di ghost howl","spawn di ghost howl"}},{q="Perché i tauren sperano che lo spirito del lupo trovi pace?",a="I tauren venerano gli spiriti selvaggi e cercano l'armonia con la natura. La corruzione demoniaca tormentava Ghost Howl, perciò i tauren vedono la sconfitta del lupo come una liberazione misericordiosa, che lo ricongiunge alla Madre Terra.",al={"credenza tauren ghost howl","spirito di ghost howl"}}},fp="23,231,21.317.0,27.329.0,32.166.0,49.129.0,28.102.0,48.185.0,26.131.0,53.181.0"}
P.entries["quest:7701"] = {n="WANTED: Overseer Maltorius",s="Nella Caldera Magmatica, una taglia chiede la morte del Soprintendente Maltorius. Lo indica come agente rinnegato della Fratellanza del Torio e nuovo comandante della squadra dei Ferroscuro della Fossa delle Scorie. Il Soprintendente Oilfist ordina di portare la sua testa al Capitano di Vedetta Lolo Colpolungo come prova.",h="Nella Caldera Magmatica, una taglia chiede la morte del Soprintendente Maltorius.",kw={"taglia","caldera magmatica","lolo colpolungo","soprintendente maltorius","soprintendente oilfist","gorgia rovente","fossa delle scorie","fratellanza del torio"},sec={{t="Una taglia su un traditore",b="Nella Fossa delle Scorie della Caldera Magmatica, devi trovare e uccidere il Soprintendente Maltorius. L'avviso lo definisce un nano Ferroscuro traditore. Porta la sua testa al Capitano di Vedetta Lolo Colpolungo per riscuotere la taglia."}},faq={{q="Chi è il Soprintendente Maltorius?",a="Il Soprintendente Maltorius è un nano Ferroscuro traditore. L'avviso lo definisce un agente rinnegato della Fratellanza del Torio e il nuovo comandante della squadra dei Ferroscuro nella Fossa delle Scorie della Caldera Magmatica.",al={"lore maltorius","chi è maltorius","storia del soprintendente maltorius"}},{q="Dove si può trovare il Soprintendente Maltorius?",a="Il Soprintendente Maltorius si trova nella Fossa delle Scorie, dentro la Caldera Magmatica.",al={"posizione di maltorius","dove si trova maltorius","come trovare il soprintendente maltorius"}},{q="Chi ha ordinato la morte del Soprintendente Maltorius?",a="Il Soprintendente Oilfist ha ordinato la morte del Soprintendente Maltorius.",al={"chi ha pubblicato la taglia","chi vuole morto maltorius","chi ha ordinato l'uccisione"}},{q="Chi riceve la prova della morte di Maltorius?",a="Il Capitano di Vedetta Lolo Colpolungo, nella Gorgia Rovente, riceve la prova della morte di Maltorius: la sua testa.",al={"a chi consegnare la testa di maltorius","dove portare la testa di maltorius","posizione di lolo colpolungo"}}},fp="26,259,20.200.0,26.184.0,38.69.0,44.52.0,40.96.0"}
P.entries["quest:7704"] = {n="Look at the Size of It!",s="Nella Gorgia Rovente hai un cuscino gigantesco e ornato, un tempo custodito dalla Cameriera Pillaclencher. Evonice Sootsmoker lo vorrà sicuramente.",h="Nella Gorgia Rovente hai un cuscino gigantesco e ornato, un tempo custodito dalla Cameriera Pillaclencher.",kw={"cameriera pillaclencher","evonice sootsmoker","guarda che dimensioni","cuscino","gorgia rovente"},sec={{t="Un cuscino per Evonice",b="Evonice Sootsmoker vorrà sicuramente il cuscino gigantesco e ornato della Cameriera Pillaclencher. Portaglielo nella Gorgia Rovente e scopri cosa ti offre per il disturbo."}},faq={{q="Chi vuole il cuscino della Cameriera Pillaclencher?",a="Evonice Sootsmoker, nella Gorgia Rovente, vorrà sicuramente il cuscino della Cameriera Pillaclencher.",al={"a chi porto il cuscino","cuscino evonice sootsmoker","dove va il cuscino"}},{q="Da dove viene questo cuscino?",a="Il cuscino gigantesco e ornato apparteneva un tempo alla Cameriera Pillaclencher.",al={"bottino cuscino","chi lascia cadere il cuscino","cuscino cameriera"}},{q="Dove si può trovare Evonice Sootsmoker?",a="Evonice Sootsmoker si trova nella Gorgia Rovente.",al={"posizione evonice","dov'è evonice sootsmoker","evonice gorgia rovente"}}},fp="23,135,20.166.0,45.91.0,33.71.0,38.43.0"}
P.entries["quest:771"] = {n="Rite of Vision",s="A Mulgore, i giovani tauren raccolgono offerte per il Rite of Vision. Nel Villaggio di Zoccolo Sanguinario, Zarlman Due Lune li guida nella preparazione dell'Acqua dei Veggenti e nella ricerca dei consigli degli spiriti ancestrali.",h="A Mulgore, i giovani tauren raccolgono offerte per il Rite of Vision.",kw={"granambra","villaggio di zoccolo sanguinario","madre terra","mulgore","rite of vision","acqua dei veggenti","pietre del pozzo","zarlman due lune"},ang={["class:Druid"]="Da druido, veneri la granambra e le pietre dei pozzi come simboli delle piante e dei corsi d'acqua vitali che sostengono l'equilibrio di Mulgore.",["class:Shaman"]="Da sciamano, riconosci l'Acqua dei Veggenti come un rituale tradizionale di radicamento. Ti sintonizza con gli elementi invisibili prima che tu parli direttamente con gli spiriti.",["race:Tauren"]="Da tauren, raggiungi una tappa importante della tua cultura, che ti lega all'eredità spirituale della Madre Terra e degli antenati, che tu sia un guerriero, un cacciatore o un mistico."},sec={{t="I reagenti della terra",b="Zarlman Due Lune ti manda per Mulgore a raccogliere pietre dei pozzi e granambra. Le pietre si trovano presso i sacri pozzi comuni, mentre la granambra cade ai piedi degli alberi antichi. Per i tauren, questi sono più che doni della terra. Racchiudono la magia latente e la linfa vitale della Madre Terra, pronte per il rito."},{t="Preparare l'Acqua dei Veggenti",b="Zarlman unisce le pietre dei pozzi e la granambra per preparare l'Acqua dei Veggenti. La bevi accanto al fuoco tribale del villaggio. La bevanda ti schiarisce la mente e richiama una guida eterea. Poi la segui attraverso le pianure, mettendo alla prova la tua capacità di camminare tra il mondo fisico e i sussurri spirituali della terra."}},faq={{q="Qual è lo scopo del Rite of Vision?",a="Il Rite of Vision mette alla prova i tauren che raggiungono la maggiore età e cercano la propria strada. Prepari e bevi l'Acqua dei Veggenti, poi impari a comunicare con gli spiriti e a seguire gli auspici ancestrali per le pianure di Mulgore.",al={"cos'è il rite of vision","perché fare il rite of vision","scopo del rite of vision"}},{q="Chi è Zarlman Due Lune?",a="Zarlman Due Lune è uno sciamano e veggente tauren del Villaggio di Zoccolo Sanguinario. Supervisiona le prove spirituali dei giovani avventurieri, prepara bevande rituali come l'Acqua dei Veggenti e interpreta i segni della Madre Terra.",al={"chi è zarlman","ruolo di zarlman due lune","zarlman dispensatore di missioni"}},{q="Dove si trovano le pietre del pozzo e la granambra?",a="Le pietre dei pozzi si trovano presso le sorgenti d'acqua dolce sparse per Mulgore. La granambra cade ai piedi dei grandi alberi che punteggiano le praterie circostanti.",al={"dove trovare la granambra","posizione pietre del pozzo","reagenti per il rite of vision"}},{q="Cosa succede dopo aver bevuto l'Acqua dei Veggenti?",a="Bere l'Acqua dei Veggenti vicino al fuoco tribale apre la tua vista spirituale e rivela una guida animale spettrale. Segui lo spirito attraverso le pianure per raggiungere la fase successiva del tuo sacro viaggio.",al={"cosa succede dopo il rite of vision","effetto dell'acqua dei veggenti","proseguimento della missione visione"}},{q="Perché i tauren venerano così profondamente i pozzi d'acqua?",a="L'acqua è la linfa vitale di Mulgore e un dono prezioso della Madre Terra. I tauren considerano sacri i pozzi, luoghi di ritrovo comuni che nutrono la terra e le mandrie. Le pietre raccolte accanto a essi racchiudono potere spirituale.",al={"pozzi d'acqua tauren","perché i pozzi sono sacri","acqua di mulgore"}},{q="Questa missione conduce ad altri riti?",a="Sì. La cerimonia si svolge in diverse fasi. Dopo che Zarlman prepara l'Acqua dei Veggenti, la bevi, segui la visione che appare e ti presenti agli anziani che guidano Mulgore.",al={"prossima missione nel rite of vision","il rite of vision è una serie di missioni","serie di riti tauren"}}},fx={["6b13f1a7"]={q="Perché Zarlman Due Lune vuole che venga fatto?",a="In quanto sciamano della tribù, Zarlman Due Lune ha il compito di guidare i giovani avventurieri promettenti attraverso le sacre tradizioni dei tauren. Non può semplicemente donarti la saggezza spirituale: devi guadagnarti il favore della Madre Terra e dei tuoi antenati partecipando direttamente al rituale, a cominciare dal raccogliere tu stesso gli elementi sacri della terra.",al={"motivo di zarlman due lune","perché zarlman ti manda","motivo di zarlman per il rite of vision"}},cc7474fb={q="A cosa servono le Pietre del Pozzo?",a="Le Pietre del Pozzo si raccolgono presso i pozzi sacri sparsi per Mulgore. Infuse della magia naturale delle sorgenti più pure della Madre Terra, sono uno degli ingredienti chiave di cui Zarlman Due Lune ha bisogno per preparare l'Acqua dei Veggenti.",al={"scopo delle pietre del pozzo","perché servono le pietre del pozzo","uso della pietra del pozzo"}},["4efb8f2d"]={q="A cosa serve la Ghianda d'Ambra?",a="Caduta dai possenti alberi sparsi per Mulgore, la Ghianda d'Ambra racchiude l'essenza naturale della flora locale. Unita alle Pietre del Pozzo e lasciata in infusione da Zarlman Due Lune, fornisce le proprietà magiche necessarie per preparare l'Acqua dei Veggenti, che ti donerà visioni ancestrali.",al={"scopo della ghianda d'ambra","a cosa serve la ghianda d'ambra","perché procurarsi la ghianda d'ambra"}},["761f0189"]={q="Perché devi raccogliere tu gli ingredienti invece di Zarlman Due Lune?",a="Il Rite of Vision è una prova individuale di crescita spirituale, non una semplice incombenza. Per entrare in comunione con gli spiriti, devi dimostrare riverenza e armonia con la terra cercandone con le tue mani le benedizioni naturali. Se qualcun altro raccogliesse gli ingredienti, verrebbe meno il sacro scopo della prova.",al={"perché devo raccogliere il granoturco ambrato","perché zarlman non raccoglie le pietre del pozzo","perché proprio io per il rite of vision"}}},fp="14,198,24.309.0,30.322.0,42.203.0,25.218.0,42.143.0,51.203.1,47.212.0,38.183.1"}
P.entries["quest:772"] = {n="Rite of Vision",s="Nel Villaggio di Zoccolo Sanguinario, i giovani tauren bevono l'Acqua dei Veggenti e intravedono il cammino che li attende. Accanto al falò tribale appare una guida spettrale.",h="Nel Villaggio di Zoccolo Sanguinario, i giovani tauren bevono l'Acqua dei Veggenti e intravedono il cammino...",kw={"villaggio di zoccolo sanguinario","lupo fantasma","mulgore","rite of vision","veggente passo saggio","fuoco tribale","acqua dei veggenti","zarlman due lune"},ang={["class:Druid"]="Come druido, approfondisci la tua reverenza per il mondo naturale e la tua umiltà spirituale di fronte alla guida delle forme animali.",["class:Shaman"]="Come sciamano, impari fin da subito a camminare tra i mondi seguendo uno spirito ancestrale dall'aspetto di lupo. Il rito rafforza il tuo legame con gli spiriti che guidano l'Orda.",["race:Tauren"]="Da giovane tauren, entri nell'età adulta attraverso il sacro Rite of Vision. Il rito dimostra la tua comunione con gli antenati e la tua obbedienza alla guida spirituale."},sec={{t="L'Acqua dei Veggenti",b="Dopo aver raccolto le erbe rituali e superato le prime prove di fede, ricevi l'Acqua dei Veggenti da Zarlman Due Lune. La bevi davanti al fuoco tribale, nel cuore del Villaggio di Zoccolo Sanguinario. Mantieni la mente concentrata e rispettosa, e l'acqua sacra ti permette di vedere oltre il mondo fisico. Essa unisce il regno materiale a quello spirituale."},{t="Seguendo il Lupo Fantasma",b="Dopo aver bevuto l'infuso, tra le fiamme appare un lupo fantasma ancestrale. Non parla né combatte, ma trotta verso nord-ovest attraverso la Piana Ondulata di Mulgore. Segui il suo silenzioso cammino, allontanandoti dal villaggio e inoltrandoti tra le colline rocciose. Lì, l'eremita Veggente Passo Saggio attende in meditazione solitaria."},{t="Un Cammino verso la Saggezza",b="La visione termina quando raggiungi il Veggente Passo Saggio all'ingresso della sua caverna montana. Il cammino attraverso le colline erbose mette alla prova la tua pazienza, la tua fiducia nella guida ancestrale e la tua sintonia con la Madre Terra. Supera il rito e otterrai il diritto di affrontare il Rite of Wisdom, la prova suprema dell'età adulta."}},faq={{q="Cosa succede quando bevo l'Acqua dei Veggenti?",a="Quando bevi l'Acqua dei Veggenti vicino al fuoco tribale del Villaggio di Zoccolo Sanguinario, i tuoi sensi spirituali si risvegliano. Poco dopo, un lupo fantasma appare davanti alle fiamme per guidarti.",al={"come funziona l'acqua dei veggenti","bere l'acqua dei veggenti","cosa fa l'acqua"}},{q="Dove mi conduce lo spirito guida?",a="Il lupo spettrale ti conduce verso nord-ovest dal Villaggio di Zoccolo Sanguinario, attraverso le colline di Mulgore, fino a una grotta rocciosa dove dimora il Veggente Passo Saggio.",al={"dove va il lupo fantasma","da chi conduce il lupo","destinazione del lupo"}},{q="Chi è Zarlman Due Lune?",a="Zarlman Due Lune è uno sciamano tauren del Villaggio di Zoccolo Sanguinario che prepara gli iniziati all'età adulta spirituale con riti ancestrali e pozioni sacre.",al={"chi conferisce il rite of vision","ruolo di zarlman due lune"}},{q="Chi è il Veggente Passo Saggio?",a="Il Veggente Passo Saggio è un anziano mistico tauren che vive in contemplazione tra le scogliere a nord-ovest del Villaggio di Zoccolo Sanguinario. Gli iniziati che seguono la loro visione spirituale lo trovano e completano la prova.",al={"chi è il veggente passo saggio","veggente nella caverna a mulgore"}},{q="Perché l'acqua deve essere bevuta vicino al fuoco tribale?",a="Il falò tribale del Villaggio di Zoccolo Sanguinario è il fulcro degli spiriti ancestrali. Le sue fiamme consacrate e l'acqua sacra permettono insieme alla visione di raggiungere il mondo dei viventi.",al={"perché il fuoco tribale","falò rite of vision"}},{q="Quale rito segue il Rite of Vision?",a="Dopo aver completato il Rite of Vision con il Veggente Passo Saggio, affronti il Rite of Wisdom, l'ultima prova spirituale del tuo primo viaggio a Mulgore.",al={"prossima missione dopo il rite of vision","what comes next"}}},fx={["659b3713"]={q="Perché Zarlman Due Lune vuole che affronti il Rite of Vision?",a="Come sciamano del Villaggio di Zoccolo Sanguinario, Zarlman Due Lune guida i giovani tauren lungo i sacri sentieri degli antenati. Dopo aver raccolto i componenti per l'Acqua dei Veggenti, ora ti offre la mistura affinché tu possa entrare direttamente in comunione con gli spiriti, assistere alla tua visione e compiere il passo successivo per scoprire il tuo destino all'interno della tribù.",al={"perché il rite of vision","motivo di zarlman due lune","scopo del rite of vision"}},b8c8221c={q="Perché devo affrontare questo rito da solo?",a="I riti della Madre Terra sono prove profondamente personali di maturità e risveglio spirituale. Nessuna guardia o anziano può percorrere per te il sentiero degli spiriti: solo il tuo spirito può ricevere la guida destinata a rivelarti il tuo posto e il tuo scopo tra i tauren.",al={"perché devo fare il rito","perché proprio io per il rite of vision","perché non può fare il rito qualcun altro"}}},fp="14,147,22.349.0,24.288.0,16.306.0,49.162.0,36.134.0,25.152.0,23.189.0,49.160.0,41.153.0"}
P.entries["quest:7721"] = {n="Fuel for the Zapping",s="Sulla Costa dell'Oblio, Zorbin Saldaleva mette al lavoro la sua officina di ingegneria in un luogo desolato. Gli elementali lo infastidiscono, ma i loro nuclei d'acqua possono alimentare la raffinazione dell'Ultra-Shrinker.",h="Sulla Costa dell'Oblio, Zorbin Saldaleva mette al lavoro la sua officina di ingegneria in un luogo desolato.",kw={"feralas","costa dell'oblio","sea elemental","sea spray","ultra-shrinker","nucleo degli elementali dell'acqua","zorbin saldaleva"},sec={{t="Energia dal risucchio",b="Zorbin Saldaleva maledice il potere incontrollato dell'elementalismo e definisce parassiti gli elementali della costa. Eppure considera i loro nuclei degli elementali dell'acqua una fonte di energia grezza per la raffinazione dell'Ultra-Shrinker. Ti chiede di combattere i Sea Elemental e i Sea Spray lungo la costa. Tieni i loro nuclei e portaglieli al molo."},{t="I ringraziamenti di Zorbin",b="Zorbin è entusiasta dei nuclei. Gli permetteranno di continuare il suo lavoro ancora per un po', e ora ci sono meno elementali sulla costa. Ammette che aprire l'officina in quello che potrebbe essere il posto peggiore immaginabile gli dava motivo di piangere la notte. Il pagamento mette a dura prova le sue finanze, ma te lo offre in segno di gratitudine."}},faq={{q="Chi sta chiedendo i nuclei degli elementali?",a="Zorbin Saldaleva ti chiede di procurargli i nuclei degli elementali. La sua officina di ingegneria si trova vicino al molo, sulla Costa dell'Oblio di Feralas.",al={"chi fornisce fuel for the zapping","zorbin saldaleva quest giver","chi inizia fuel for the zapping"}},{q="Perché Zorbin Saldaleva ha bisogno dei nuclei degli elementali dell'acqua?",a="Zorbin Saldaleva ha bisogno dei nuclei degli elementali dell'acqua come fonte di energia grezza per la raffinazione dell'Ultra-Shrinker. Considera gli elementali locali una riserva ideale.",al={"perché i nuclei degli elementali dell'acqua","a cosa servono i nuclei","carburante per ultra-shrinker"}},{q="Dove si raccolgono i nuclei degli elementali?",a="Raccogli i nuclei dai Sea Elemental e dai Sea Spray lungo la Costa dell'Oblio di Feralas.",al={"dove trovare i nuclei","posizione dei sea elemental","dove si trovano i sea spray"}}},fp="20,187,19.309.0,15.293.1,38.122.0,53.141.0,39.89.0"}
P.entries["quest:7722"] = {n="What the Flux?",s="Il Maestro Fabbro Ardirabbia cerca i progetti del flussante infuocato nella Fossa delle Scorie. Maltorius lasciò il clan portando con sé la ricetta, che Ardirabbia considera più preziosa di un cristallo arcano incontaminato, e crede che i progetti siano vicino a lui.",h="Il Maestro Fabbro Ardirabbia cerca i progetti del flussante infuocato nella Fossa delle Scorie.",kw={"ardirabbia","caldera magmatica","flussante infuocato","maltorius","progetto","gorgia rovente","fossa delle scorie"},sec={{t="La ricetta rubata",b="Il Maestro Fabbro Ardirabbia dice che Maltorius tradì il loro clan quando se ne andò con la ricetta del flussante infuocato. Ardirabbia sospetta che quella ricetta abbia aiutato Maltorius a ottenere la nuova promozione tra i Ferroscuro. Ora vuole che i progetti segreti vengano restituiti."},{t="Nella Fossa delle Scorie",b="Il Maestro Fabbro Ardirabbia crede che i progetti si trovino vicino a Maltorius, nel profondo della Fossa delle Scorie. Vuole che tu gli riporti il Progetto Segreto: Flussante Infuocato."}},faq={{q="Chi ha rubato la ricetta del flussante infuocato?",a="Secondo il Maestro Fabbro Ardirabbia, Maltorius ha rubato la ricetta del flussante infuocato. Ardirabbia lo definisce un traditore del loro clan.",al={"chi ha rubato la ricetta","chi ha preso il progetto","traditore flussante infuocato"}},{q="Dove si trova il progetto segreto?",a="Ardirabbia crede che i progetti segreti si trovino vicino a Maltorius, nel profondo della Fossa delle Scorie della Caldera Magmatica.",al={"dove si trova il progetto","posizione progetto segreto flussante infuocato","dove trovare il progetto del flussante infuocato"}},{q="Chi chiede di recuperare il progetto?",a="Il Maestro Fabbro Ardirabbia, un fabbro, vuole che gli vengano restituiti i progetti.",al={"chi assegna che flussante","chi dà la missione che flussante"}},{q="Perché il progetto è importante per Ardirabbia?",a="Ardirabbia dice che la ricetta segreta del flussante infuocato del clan vale più di un cristallo arcano incontaminato.",al={"perché il flussante infuocato è importante","importanza ricetta flussante infuocato"}}},fp="14,202,17.238.0,17.147.0,36.120.0,27.92.0,39.58.0,37.96.0"}
P.entries["quest:7723"] = {n="Curse These Fat Fingers",s="Nella Gorgia Rovente, Hansel Maniforti non riesce più a distribuire pestaggi come prima. Le dita gonfie lo costringono a chiederti di prendere a pugni i golem da guerra pesanti al suo posto.",h="Nella Gorgia Rovente, Hansel Maniforti non riesce più a distribuire pestaggi come prima.",kw={"caldera magmatica","dita gonfie","hansel maniforti","golem da guerra pesanti","gorgia rovente","thelsamar blood sausages"},sec={{t="Dita come salsicce",b="Hansel Maniforti dà la colpa al clima della Gorgia Rovente e alla sua aria rarefatta per le dita gonfie. Sembrano enormi Thelsamar Blood Sausages. Con dita così, Hansel non riesce più a distribuire pestaggi come prima, quindi ha bisogno che tu ti occupi dei suoi affari."},{t="Primo nella lista",b="Hansel vuole che tu prenda a pugni con forza i golem da guerra pesanti della Gorgia. Devi distruggerne venti. Si aggirano nelle zone attorno alla Caldera Magmatica e, una volta abbattuti abbastanza, torna da Hansel."}},faq={{q="Chi è Hansel Maniforti?",a="Hansel Maniforti si trova nella Gorgia Rovente, dove le dita gonfie gli impediscono di combattere. Ti chiede di prendere a pugni i nemici al suo posto.",al={"hansel maniforti","chi assegna curse these fat fingers","chi è il dispensatore della missione"}},{q="Perché Hansel non può combattere i golem personalmente?",a="Hansel dà la colpa al clima della Gorgia Rovente e all'aria rarefatta per le dita gonfie. Le paragona a enormi Thelsamar Blood Sausages.",al={"perché le dita di hansel sono gonfie","storia delle dita gonfie","mani gonfie di hansel"}},{q="Quali nemici devono essere affrontati?",a="Devi distruggere venti golem da guerra pesanti.",al={"quali nemici devo combattere","cosa vuole che venga ucciso hansel"}},{q="Dove si trovano i golem da guerra pesanti?",a="I golem da guerra pesanti si aggirano nelle zone attorno alla Caldera Magmatica, nella Gorgia Rovente.",al={"dove sono i golem","posizione dei golem da guerra pesanti"}}},fp="23,160,21.257.0,17.177.0,25.133.0,47.130.0,29.41.0,39.77.0"}
P.entries["quest:7724"] = {n="Fiery Menace!",s="Hansel Maniforti ha un altro incarico per te nella Gorgia Rovente. I ragni lavici maggiori stanno creando problemi.",h="Hansel Maniforti ha un altro incarico per te nella Gorgia Rovente.",kw={"minaccia ardente","ragni lavici maggiori","hansel maniforti","oilfist","gorgia rovente","ragni"},sec={{t="Un altro lavoro per Hansel",b="Hansel Maniforti ha poco tempo per riposare o riflettere sulla sua vita. I potenti continuano ad affidargli altro lavoro. I ragni lavici maggiori stanno creando scompiglio, quindi Hansel preferirebbe che te ne occupassi tu."},{t="I ragni lavici maggiori",b="Oilfist dice che i ragni lavici maggiori sparano fuoco da un punto imbarazzante. Le loro fiamme turbano i bambini. Hansel vuole che tu uccida venti ragni sugli altopiani e vicino alle pozze di lava della Gorgia Rovente."}},faq={{q="Chi ti manda a caccia dei ragni?",a="Hansel Maniforti ti manda a caccia dei ragni nella Gorgia Rovente. Sperava di avere un momento di quiete.",al={"datore di missione","chi assegna la missione","hansel"}},{q="Perché bisogna uccidere i ragni?",a="I ragni lavici maggiori stanno creando scompiglio. Oilfist dice che il modo in cui sparano fuoco turba i bambini.",al={"perché uccidere i ragni","cosa hanno fatto i ragni","problema dei ragni"}},{q="Chi ha parlato a Hansel dei ragni?",a="Oilfist ha detto a Hansel che i ragni sparano fuoco da un punto imbarazzante.",al={"chi si è lamentato dei ragni","oilfist"}},{q="Quanti ragni lavici maggiori devono essere uccisi?",a="Hansel ti chiede di uccidere venti ragni lavici maggiori.",al={"quanti ragni","conteggio ragni"}}},fp="13,104,22.191.0,24.204.0,32.100.0,37.100.0,34.70.0,45.52.0"}
P.entries["quest:7725"] = {n="Again With the Zapped Giants",s="Ai moli della Costa dell'Oblio, Zorbin Saldaleva ha un'altra proposta per te. Portagli altro residuo dei giganti di Feralas rimpiccioliti con l'Ultra Riduttore di Zorbin. Stavolta può pagarti molto meno, ma promette di spargere la voce sul tuo operato.",h="Ai moli della Costa dell'Oblio, Zorbin Saldaleva ha un'altra proposta per te.",kw={"feralas","costa dell'oblio","giganti","residuo di miniaturizzazione","cartello degli spargifumo","ultra riduttore","zorbin saldaleva"},sec={{t="Un bis per l'Ultra Riduttore",b="Zorbin Saldaleva ti chiede di rimpicciolire di nuovo i giganti di Feralas e di portare dieci residui di miniaturizzazione ai moli della Costa dell'Oblio. C'è sempre spazio per altro, anche dopo il tuo primo carico.\n\nStavolta non può offrirti neanche lontanamente altrettanto. In cambio, promette di tessere le lodi del tuo operato tra i suoi amici goblin, che hanno orecchie piuttosto grandi."},{t="I ringraziamenti di Zorbin",b="Zorbin Saldaleva è felicissimo che tu abbia portato a termine di nuovo l'incarico, anche se la ricompensa è inferiore a quella a cui sei abituato. Dice che la voce delle tue grandi gesta per il goblinismo sta già echeggiando tra i centri di potere del Cartello degli Spargifumo."}},faq={{q="Chi chiede altro residuo?",a="Zorbin Saldaleva ti aspetta ai moli della Costa dell'Oblio, a Feralas, e ti chiede altro residuo.",al={"datore di missione","posizione di zorbin","chi assegna again with the zapped giants"}},{q="Cosa precede questa missione?",a="Questo fa seguito a Zapped Giants, il tuo primo giro di raccolta del residuo per Zorbin Saldaleva.",al={"prerequisito","missione precedente","cosa devo fare prima"}},{q="Come viene raccolto il residuo?",a="Usa l'Ultra Riduttore di Zorbin su un gigante qualsiasi a Feralas per rimpicciolirlo. Poi raccogli il residuo dai giganti rimpiccioliti.",al={"come ottenere il residuo","residuo di miniaturizzazione","come rimpicciolire i giganti"}},{q="Dove si trovano i giganti?",a="I giganti si trovano lungo la costa occidentale di Feralas.",al={"posizione dei giganti","dove si trovano i giganti di feralas","giganti della costa dell'oblio"}},{q="Zorbin accetterà altro residuo in futuro?",a="Zorbin dice che gli serve sempre altro residuo, quindi puoi tornare con un altro lotto di dieci.",al={"è ripetibile","posso ripetere again with the zapped giants","missione ripetibile dei giganti"}}},fp="28,224,32.327.0,15.225.1,26.93.0,22.87.0,28.119.0,27.45.0,43.88.0"}
P.entries["quest:7726"] = {n="Refuel for the Zapping",s="Sulla Costa dell'Oblio, Zorbin Saldaleva ha bisogno di altri nuclei di elementali dell'acqua. Aprire un negozio è difficile, quindi la paga è bassa. Zorbin promette comunque di raccontare alla gente dei dintorni del tuo aiuto e dice di avere amici nel Cartello degli Spargifumo.",h="Sulla Costa dell'Oblio, Zorbin Saldaleva ha bisogno di altri nuclei di elementali dell'acqua.",kw={"feralas","costa dell'oblio","elementale marino","spruzzo marino","cartello degli spargifumo","nucleo di elementale dell'acqua","zorbin saldaleva"},sec={{t="Ancora la stessa cosa",b="Zorbin Saldaleva scherza sull'eroica impresa di raccogliere melma da esseri elementali. Poi ti chiede se ne vuoi ancora. Sotto lo scherzo, Zorbin ha bisogno di altri nuclei di elementali dell'acqua.\n\nAprire un negozio sulla Costa dell'Oblio è un'impresa disperata, quindi c'è poco da offrire in cambio. Zorbin promette di raccontare a tutti quelli dei dintorni come hai aiutato, e dice che puoi fidarti perché conosce gente nel Cartello degli Spargifumo. Porta a Zorbin, vicino al molo, sei nuclei presi dagli Elementali Marini e dagli Spruzzi Marini sulla Costa dell'Oblio."},{t="Il ringraziamento di Zorbin",b="Zorbin è soddisfatto del tuo lavoro, anche se la ricompensa in monete potrebbe non essere la più alta che riceverai mai per un incarico simile. Zorbin racconterà ai compagni del Cartello degli Spargifumo dei tuoi sforzi. C'è altro da fare, se vuoi: Zorbin ha ancora bisogno di altri nuclei e oggetti simili."}},faq={{q="Chi richiede i nuclei di elementali dell'acqua?",a="Zorbin Saldaleva ti aspetta vicino al molo sulla Costa dell'Oblio, a Feralas.",al={"chi assegna questa missione","chi è zorbin saldaleva","dove si trova zorbin"}},{q="Da dove provengono i nuclei di elementali dell'acqua?",a="I nuclei si ottengono dagli Elementali Marini e dagli Spruzzi Marini sulla Costa dell'Oblio, a Feralas.",al={"dove si trovano i nuclei","posizione nucleo di elementale dell'acqua","quali nemici lasciano i nuclei"}},{q="Perché Zorbin Saldaleva ha bisogno di altri nuclei?",a="Zorbin dice che servono altri nuclei di elementali dell'acqua mentre cerca con fatica di aprire un negozio sulla costa.",al={"perché zorbin vuole i nuclei","motivo zorbin saldaleva","a cosa servono i nuclei"}},{q="Cosa precede questa missione?",a="Segue Fuel for the Zapping, quando hai raccolto per la prima volta i nuclei elementali per Zorbin.",al={"missione precedente","requisiti della missione","quale missione viene prima"}}},fp="22,224,16.533.0,15.258.1,44.76.0,45.84.0,42.100.0,22.84.0"}
P.entries["quest:7727"] = {n="Incendosaurs? Whateverosaur is More Like It",s="Hansel Maniforti non può combattere con i piedi ridotti in quello stato. Perciò ti manda a uccidere venti incendosauri nella Fossa delle Scorie, dove Scrange e Burninate vogliono liberare le pozze di lava per le squadre di spedizione.",h="Hansel Maniforti non può combattere con i piedi ridotti in quello stato.",kw={"burninate","caldera magmatica","hansel maniforti","incendosauro","scrange","gorgia rovente","fossa delle scorie"},sec={{t="Calli su Calli",b="Hansel Maniforti non può combattere con i calli ridotti in quello stato. Scrange e Burninate gli hanno detto di uccidere gli incendosauri, così le squadre di spedizione potranno esplorare le pozze di lava della Fossa delle Scorie. Ora manda te al suo posto."},{t="Le Pozze di Lava",b="Gli incendosauri occupano le pozze di lava della Fossa delle Scorie, all'interno della Caldera Magmatica. Hansel ne vuole venti uccisi prima che tu faccia ritorno."}},faq={{q="Chi è Hansel Maniforti?",a="Hansel Maniforti ti affida un incarico nella Gorgia Rovente. Scrange e Burninate gli hanno detto di occuparsi degli incendosauri, ma i suoi calli gli impediscono di combattere.",al={"hansel maniforti","chi assegna la missione","chi dà questa missione"}},{q="Perché gli incendosauri devono essere eliminati?",a="Scrange e Burninate vogliono che le squadre di spedizione esplorino le pozze di lava della Fossa delle Scorie. A quanto pare, gli incendosauri laggiù stanno causando ogni sorta di problema.",al={"perché uccidere gli incendosauri","scopo degli incendosauri","perché liberare la fossa delle scorie"}},{q="Dove si trovano gli incendosauri?",a="Gli incendosauri vivono nelle pozze di lava della Fossa delle Scorie, all'interno della Caldera Magmatica.",al={"posizione degli incendosauri","dove si trova la fossa delle scorie","dove sono le pozze di lava"}},{q="Perché Hansel non dà loro la caccia personalmente?",a="Hansel dice che i suoi calli hanno i calli. I suoi piedi sono ridotti talmente male che non riesce a uccidere nulla.",al={"perché hansel non combatte","piedi di hansel","calli di hansel"}}},fp="43,204,20.220.0,14.121.0,25.156.0,47.155.0,33.77.0,35.97.0"}
P.entries["quest:7728"] = {n="STOLEN: Smithing Tuyere and Lookout's Spyglass",s="Nella Gorgia Rovente, la Fratellanza del Torio cerca due attrezzi rubati: un tubo per fucine e un Cannocchiale della Vedetta. La Fratellanza è certa che li abbiano presi nani Ferroscuro gelosi e senza scrupoli, e chiede a chiunque li trovi di portarli al Coordinatore Scrange in cambio di una ricompensa.",h="Nella Gorgia Rovente, la Fratellanza del Torio cerca due attrezzi rubati: un tubo per fucine e un...",kw={"ferroscuro","scrange","gorgia rovente","fabbricazione","cannocchiale","fratellanza del torio","tubo per fucine"},sec={{t="Merci Rubate",b="La Fratellanza del Torio cerca un Cannocchiale della Vedetta e un tubo per fucine, entrambi rubati. Il cannocchiale è un ottimo strumento per le vedette, e il tubo per fucine è un attrezzo da fabbro insostituibile. La Fratellanza è certa che li abbiano presi nani Ferroscuro. Chiunque trovi gli attrezzi dovrebbe portarli al Coordinatore Scrange."}},faq={{q="Chi ha affisso l'avviso?",a="L'avviso parla a nome della Fratellanza del Torio, certa che i nani Ferroscuro abbiano preso gli oggetti.",al={"chi vuole gli oggetti rubati","chi ha dato questa missione","datore di missione tubo per fucine rubato"}},{q="Chi ha rubato gli attrezzi?",a="La Fratellanza del Torio è certa che nani Ferroscuro senza scrupoli e gelosi della Gorgia Rovente abbiano rubato gli attrezzi.",al={"chi ha preso il tubo","chi ha rubato il cannocchiale","chi ha gli oggetti rubati"}},{q="Chi riceve gli oggetti recuperati?",a="Il Coordinatore Scrange riceve gli oggetti recuperati.",al={"dove devo consegnare","chi è il coordinatore scrange","chi riceve il cannocchiale"}},{q="A cosa servono gli oggetti rubati?",a="Il tubo per fucine è un attrezzo da fabbro insostituibile, e il Cannocchiale della Vedetta aiuta le vedette a sorvegliare.",al={"cos'è un tubo per fucine","perché la fratellanza vuole il tubo","cosa fa il cannocchiale"}}},fp="46,261,12.299.0,22.97.0,20.112.0,33.48.0,30.89.0"}
P.entries["quest:7729"] = {n="JOB OPPORTUNITY: Culling the Competition",s="Nella Gorgia Rovente, il Coordinatore Scrange vuole che tu riduca la concorrenza con un lavoro sanguinoso.",h="Nella Gorgia Rovente, il Coordinatore Scrange vuole che tu riduca la concorrenza con un lavoro sanguinoso.",kw={"eliminare la concorrenza","schiavista ferroscuro","sorvegliante ferroscuro","opportunità di lavoro","gorgia rovente","coordinatore scrange"},sec={{t="Una posizione aperta",b="Il Coordinatore Scrange ti manda nella gola a uccidere quindici Sorveglianti Ferroscuro e quindici Schiavisti Ferroscuro. Torna quando i tuoi abiti saranno abbastanza insanguinati. Capirai quando sarà il momento, e non devi chiedere."}},faq={{q="Chi offre questo lavoro?",a="Il Coordinatore Scrange, nella Gorgia Rovente, ha bisogno di aiuto per eliminare la concorrenza.",al={"chi offre questa missione","chi vuole che i sorveglianti vengano uccisi","chi è il coordinatore scrange"}},{q="Quali nemici devono essere uccisi?",a="Uccidi quindici Sorveglianti Ferroscuro e quindici Schiavisti Ferroscuro.",al={"cosa devo uccidere","bersagli per opportunità di lavoro","chi è la concorrenza"}},{q="Come fa Scrange a sapere che il lavoro è finito?",a="Scrange giudica dallo stato dei tuoi abiti, pesandoti con e senza per esserne certo.",al={"come dimostrare le uccisioni","requisito abiti insanguinati","come controlla scrange"}}},fp="40,95,16.211.0,25.75.0,28.65.0,39.96.0"}
P.entries["quest:773"] = {n="Il Rituale della Saggezza",s="Ai Massi Rossi, il Rite of Wisdom porta i Rites of the Earthmother alla prova finale. Dopo che il Rite of Vision ha rischiarato la tua vista, viaggi per entrare in comunione con uno Spirito Ancestrale e cercare la benedizione dei defunti.",h="Ai Massi Rossi, il Rite of Wisdom porta i Rites of the Earthmother alla prova finale.",kw={"spirito ancestrale","mulgore","massi rossi","rite of wisdom","rites of the earthmother","veggente passo saggio","picco del tuono","acqua dei veggenti"},ang={["class:Druid"]="Come druido, vedi l'equilibrio tra il mondo dei viventi e il ciclo eterno vegliato dalla Madre Terra. Il tuo dovere è verso la terra.",["class:Shaman"]="Come sciamano, onori i defunti entrando in comunione con uno Spirito Ancestrale. Resti fedele agli spiriti che vegliano su Mulgore.",["race:Tauren"]="Come shu'halo, ricevere il manto degli antenati ai Massi Rossi segna il tuo ingresso nell'età adulta e la tua accettazione tra gli anziani della tribù."},sec={{t="La Prova dei Massi Rossi",b="Dopo che il Rite of Vision ha rischiarato la tua vista, viaggi a est di Picco del Tuono, fino ai Massi Rossi. Qui riposano coloro che hanno combattuto e sono morti perché Mulgore potesse vivere in pace, e i loro spiriti ancora indugiano. Avvicinati al loro luogo di riposo con riverenza e cerca la comunione. Mentre cerchi consiglio dagli onorati defunti, le colline sono sorvegliate da minacce."},{t="Il Passaggio del Mantello",b="Sulla cima dei Massi Rossi, entri in comunione con uno Spirito Ancestrale. L'incontro mette alla prova la tua preparazione spirituale e il tuo posto tra le generazioni, non la tua forza in battaglia. Questi spiriti combatterono al fianco di Cairne Zoccolo Sanguinario per fondare Picco del Tuono e proteggere le tribù. La loro benedizione ti riconosce come adulto e difensore. Ti viene affidato il compito di proteggere la città e puoi entrare a Picco del Tuono con orgoglio."}},faq={{q="Qual è lo scopo del Rite of Wisdom?",a="Il Rite of Wisdom è la prova finale dei Rites of the Earthmother. La benedizione ancestrale unisce la visione della giovinezza ai doveri dell'età adulta e ti riconosce pronto a difendere Picco del Tuono.",al={"perché fare il rite of wisdom","cosa fa il rite of wisdom","scopo del rite of wisdom"}},{q="Chi ti invia a compiere il Rite of Wisdom?",a="Dopo che hai completato il Rite of Vision e bevuto l'Acqua dei Veggenti, Veggente Passo Saggio ti manda dalla sua caverna, a nord-ovest del Villaggio di Zoccolo Sanguinario.",al={"chi assegna il rite of wisdom","dove inizio il rite of wisdom"}},{q="Dove si trova lo Spirito Ancestrale?",a="Trovi lo Spirito Ancestrale ai Massi Rossi, un antico luogo di sepoltura dei tauren tra le alture rocciose direttamente a est di Picco del Tuono.",al={"posizione dello spirito ancestrale","dove si trova lo spirito","dove trovare lo spirito ancestrale"}},{q="Perché il Rite of Vision è richiesto per primo?",a="Il Rite of Vision purifica la tua vista spirituale con l'Acqua dei Veggenti. Così puoi percepire gli antichi spiriti ai Massi Rossi e ricevere la loro benedizione.",al={"perché fare prima la visione","prerequisito rite of vision","requisito acqua dei veggenti"}},{q="Cosa succede dopo aver completato il Rite of Wisdom?",a="Dopo aver ottenuto l'approvazione degli antenati, ti viene chiesto di raggiungere le alture di Picco del Tuono.",al={"cosa fare dopo il rite of wisdom","prossima missione dopo il rite of wisdom"}},{q="Quali creature minacciano i terreni dei Massi Rossi?",a="I gnoll Palemane, aggressivi, si sono spinti fino al cimitero sacro dei Massi Rossi. Si nascondono lungo i sentieri rocciosi che portano all'antico luogo di sepoltura.",al={"nemici ai massi rossi","cosa protegge i massi rossi","gnoll ai massi rossi"}}},fx={["740e2883"]={q="Perché il Veggente Passo Saggio ti manda al Rite of Wisdom?",a="Il Veggente Passo Saggio guida i giovani tauren più promettenti attraverso i tradizionali Rites of the Earthmother. Dopo averti visto resistere alla visione concessa dall'Acqua dei Veggenti, ti indirizza ai Massi Rossi affinché tu riceva la benedizione degli antenati. Per Passo Saggio e gli anziani, questo rito assicura che solo chi è spiritualmente preparato e riconosciuto dagli antenati venga accolto a Picco del Tuono come protettore della tribù.",al={"motivo del veggente passo saggio","perché il rite of wisdom","perché mandare me al rite of wisdom"}},["8728f84f"]={q="Perché il Veggente Passo Saggio ha bisogno che ci vada tu invece di andarci lui?",a="Il Rite of Wisdom è una prova personale di passaggio, non una commissione che qualcun altro può sbrigare al posto tuo. Per ottenere l'accettazione degli anziani e il diritto di entrare a Picco del Tuono, devi cercare di persona lo Spirito Ancestrale ai Massi Rossi e dimostrare la chiarezza spirituale acquisita grazie all'Acqua dei Veggenti. Il compito di proteggere la città può essere affidato solo direttamente a te.",al={"perché proprio io per il rite of wisdom","perché il veggente passo saggio non va","perché devo cercare lo spirito ancestrale"}}},fp="14,213,22.325.0,18.396.0,42.196.0,36.147.0,39.127.0,41.161.0,49.108.0,49.137.0"}
P.entries["quest:7730"] = {n="Zukk'ash Infestation",s="All'Accampamento Mojache, Hadoken Passo Lesto sospetta che gli Zukk'ash a sud degli gnoll li stiano spingendo alla frenesia. Ti manda alla Fossa Fremente per decimarli e tornare con venti carapaci.",h="All'Accampamento Mojache, Hadoken Passo Lesto sospetta che gli Zukk'ash a sud degli gnoll li stiano spingendo...",kw={"accampamento mojache","carapace","feralas","gnoll","hadoken passo lesto","insetti","fossa fremente","zukk'ash"},sec={{t="Il nemico a sud degli gnoll",b="Hadoken Passo Lesto crede che a sud degli gnoll vivano creature simili a insetti. Che siano capaci di pensare gli importa poco. Se spingono gli gnoll alla frenesia contro l'Accampamento Mojache, minacciano l'accampamento tanto quanto gli gnoll. Perciò ti addentri nella loro dimora, la Fossa Fremente, per decimarli. Porta indietro venti carapaci degli Zukk'ash come prova e racconta a Hadoken cosa scopri."},{t="Il verdetto di Hadoken",b="Hadoken Passo Lesto è soddisfatto quando fai ritorno. Solo un'invasione su larga scala può porre fine alla presenza degli Zukk'ash, ma il tuo lavoro ha dato all'Accampamento Mojache il tempo di elaborare una strategia adeguata. L'accampamento studierà i carapaci e imparerà tutto il possibile su queste creature. Il pericolo è molto più grande di quanto chiunque si aspettasse."}},faq={{q="Chi ti manda a caccia degli Zukk'ash?",a="Hadoken Passo Lesto ti manda dall'Accampamento Mojache, a Feralas.",al={"datore di missione","hadoken passo lesto","chi avvia infestazione zukkash"}},{q="Cosa sono gli Zukk'ash?",a="Hadoken crede che gli Zukk'ash siano creature simili a insetti, a sud degli gnoll. Che siano capaci di pensare gli importa poco; teme che stiano spingendo gli gnoll alla frenesia.",al={"cosa sono gli zukkash","insetti zukkash","insetti fossa fremente"}},{q="Dov'è la Fossa Fremente?",a="La Fossa Fremente, dimora degli Zukk'ash, si trova a sud degli gnoll.",al={"posizione fossa fremente","dove si trova la fossa fremente","dove sono gli insetti"}},{q="Perché Hadoken vuole i carapaci degli Zukk'ash?",a="Hadoken vuole i carapaci come prova del tuo lavoro contro gli Zukk'ash.",al={"perché i carapaci","uso carapaci zukkash","scopo dei carapaci"}}},fp="20,201,27.379.0,17.310.1,33.60.0,22.177.0,27.66.0,41.71.0"}
P.entries["quest:7731"] = {n="Stinglasher",s="Nella Fossa Fremente, l'esploratrice di Hadoken Passo Lesto ha trovato un insetto molto più grande degli altri.",h="Nella Fossa Fremente, l'esploratrice di Hadoken Passo Lesto ha trovato un insetto molto più grande degli...",kw={"accampamento mojache","feralas","ghiandole","hadoken passo lesto","insetto","stinglasher","fossa fremente","zukk'ash"},sec={{t="Un gigante tra gli insetti",b="Un'esploratrice ha trovato un insetto gigante che vaga nel terreno contorto della Fossa Fremente. Sembra emanare un'aura diversa da quella degli altri, e Hadoken Passo Lesto l'ha chiamato Stinglasher. Hadoken vuole che le ghiandole secernenti vengano portate direttamente all'Accampamento Mojache. Studiandone le interiora, spera di capire come affrontare questa nuova minaccia."},{t="I ringraziamenti di Hadoken",b="Hadoken Passo Lesto è colpito dal tuo lavoro. Se Stinglasher è tra gli insetti più forti, studiarlo potrebbe rivelarsi prezioso. Hadoken deve difendere l'accampamento abbastanza a lungo da poterne trarre beneficio. Per ringraziarti a nome di tutto l'accampamento, ti dà una ricompensa in monete."}},faq={{q="Chi ti manda a caccia di Stinglasher?",a="Hadoken Passo Lesto, all'Accampamento Mojache in Feralas, ti manda a caccia di Stinglasher.",al={"datore di missioni","chi assegna stinglasher","hadoken passo lesto"}},{q="Dove si trova Stinglasher?",a="Stinglasher vaga nel terreno contorto della Fossa Fremente.",al={"posizione stinglasher","dove si trova stinglasher","posizione fossa fremente"}},{q="Cosa rende Stinglasher diverso dagli altri insetti?",a="Un'esploratrice riferisce che Stinglasher è molto più grande degli altri insetti e sembra emanare un'aura che a loro manca.",al={"perché stinglasher","cos'è stinglasher","aura di stinglasher"}},{q="Perché Hadoken vuole le ghiandole di Stinglasher?",a="Hadoken vuole le ghiandole di Stinglasher per studiarne le interiora e trovare un piano contro questa nuova minaccia.",al={"perché raccogliere ghiandole","scopo ghiandole stinglasher"}}},fp="11,98,25.343.0,16.250.1,32.76.0,27.61.0,56.110.0,43.116.0"}
P.entries["quest:7732"] = {n="Zukk'ash Report",s="All'Accampamento Mojache, Hadoken Passo Lesto dice che hai ottenuto un doppio successo contro gli Zukk'ash, anche se il pericolo rimane. Ti chiede di portare il rapporto dell'accampamento a Zilzibin Suonapelli a Orgrimmar.",h="All'Accampamento Mojache, Hadoken Passo Lesto dice che hai ottenuto un doppio successo contro gli Zukk'ash...",kw={"accampamento mojache","varcolargo","feralas","hadoken passo lesto","orgrimmar","silithid","zilzibin suonapelli","zukk'ash report"},sec={{t="Un documento per il Varcolargo",b="Hadoken Passo Lesto ha un documento su ciò che l'Accampamento Mojache ha scoperto sugli insetti Zukk'ash. La minaccia persiste, quindi ti chiede di portare il rapporto a Orgrimmar. Zilzibin Suonapelli vive nel Varcolargo e conosce creature aliene come queste. Hadoken spera che le scoperte dell'accampamento si rivelino utili."},{t="Il verdetto dell'esperto",b="Zilzibin Suonapelli aspettava il rapporto. Definisce le creature che hai affrontato un'antica minaccia che l'Orda continua a scegliere di ignorare. Hadoken è stato saggio a inviare sia il documento sia te. Zilzibin chiama gli Zukk'ash silithid. Alcuni li liquidano come un fastidio privo di intelletto, ma secondo lui minacciano l'Orda più di quanto potrebbe fare l'Alleanza."}},faq={{q="Chi invia il rapporto a Orgrimmar?",a="Hadoken Passo Lesto ti consegna il documento all'Accampamento Mojache, a Feralas.",al={"chi dà il rapporto zukkash","chi inizia il rapporto zukkash","datore di missione"}},{q="A chi viene consegnato il rapporto?",a="Consegni il rapporto a Zilzibin Suonapelli, che vive nel Varcolargo di Orgrimmar.",al={"dove va il rapporto","chi riceve il rapporto zukkash","posizione di drumlore"}},{q="Perché il documento viene portato a Orgrimmar?",a="Hadoken spera che Zilzibin Suonapelli possa usare le scoperte dell'accampamento. Zilzibin è un esperto di creature aliene come gli Zukk'ash.",al={"perché inviare a orgrimmar","scopo del rapporto"}},{q="Cosa precede questa consegna?",a="La consegna segue i tuoi sforzi contro gli insetti Zukk'ash in Zukk'ash Infestation e Stinglasher.",al={"missioni precedenti","prerequisiti"}}},fp="15,192,23.293.0,20.336.1,34.71.0,32.80.0,39.127.0,31.103.0"}
P.entries["quest:7733"] = {n="Qualità Migliorata",s="Nel nord di Feralas, Pratt McGrubben vuole pelli di yeti più resistenti dalla Tana degli Artiglio Selvaggio. Ti chiede di portarne dieci alla Roccaforte di Piumaluna.",h="Nel nord di Feralas, Pratt McGrubben vuole pelli di yeti più resistenti dalla Tana degli Artiglio Selvaggio.",kw={"roccaforte di piumaluna","feralas","qualità migliorata","pratt mcgrubben","tana degli artiglio selvaggio","torio","pelle di yeti","yeti"},sec={{t="Una mandria di yeti più resistente",b="Dopo la missione Mark of Quality, Pratt McGrubben ha trovato pelli più pregiate. Una mandria di yeti più resistente vive nella Tana degli Artiglio Selvaggio, nel nord di Feralas. Porta dieci pelli a Pratt alla Roccaforte di Piumaluna e ti pagherà profumatamente. Se queste pelli eguagliano quelle di Feral Scar, potrebbero rivelarsi resistenti quanto il torio."},{t="I ringraziamenti di Pratt",b="Le pelli della Tana degli Artiglio Selvaggio sono migliori di quanto Pratt McGrubben sperasse. Capisce che diventeranno molto più dure una volta conciate a dovere. Per ringraziarti, ti consegna una delle sue ultime creazioni."}},faq={{q="Chi richiede le pelli di yeti della Tana degli Artiglio Selvaggio?",a="Pratt McGrubben ti chiede pelli di yeti della Tana degli Artiglio Selvaggio alla Roccaforte di Piumaluna, a Feralas.",al={"chi assegna qualità migliorata","committente di qualità migliorata","pratt mcgrubben"}},{q="Dove vivono gli yeti della Tana degli Artiglio Selvaggio?",a="Gli yeti della Tana degli Artiglio Selvaggio vivono al suo interno, nel nord di Feralas.",al={"posizione yeti della tana degli artiglio selvaggio","dove si trova la tana degli artiglio selvaggio","dove ottenere pelli della tana degli artiglio selvaggio"}},{q="Quante pelli sono richieste?",a="Pratt McGrubben vuole dieci pelli di yeti della Tana degli Artiglio Selvaggio.",al={"quante pelli di yeti","oggetti necessari per qualità migliorata"}},{q="Cosa precede questa missione?",a="Questa missione segue The Mark of Quality, in cui ti sei occupato della prima mandria di yeti.",al={"missione prerequisito","quale missione precede qualità migliorata","missione precedente"}}},fp="16,134,25.303.0,14.171.1,38.87.0,34.67.0,26.47.0,22.80.0"}
P.entries["quest:7734"] = {n="Qualità Migliorata",s="All'Accampamento Mojache, Jangdor Passo Lesto cerca pelli più pregiate dagli yeti più robusti della Tana degli Artiglio Selvaggio.",h="All'Accampamento Mojache, Jangdor Passo Lesto cerca pelli più pregiate dagli yeti più robusti della Tana...",kw={"accampamento mojache","feralas","qualità migliorata","jangdor passo lesto","tana degli artiglio selvaggio","yeti della tana degli artiglio selvaggio","pelli di yeti"},sec={{t="Una mandria di yeti più resistente",b="Dopo The Mark of Quality, Jangdor Passo Lesto ha trovato una fonte migliore di pelli. Gli yeti più robusti si aggirano nella Tana degli Artiglio Selvaggio, nel nord di Feralas. Porta dieci pelli all'Accampamento Mojache e Jangdor ti pagherà profumatamente. Se eguagliano le pelli di Feral Scar, potrebbero rivelarsi resistenti quanto il torio."},{t="I ringraziamenti di Jangdor",b="Jangdor Passo Lesto trova le pelli migliori di quanto sperasse. Una volta conciate a dovere, capisce che diventeranno molto più resistenti. Per ringraziarti, ti regala una delle sue ultime creazioni."}},faq={{q="Chi richiede le pelli di yeti della Tana degli Artiglio Selvaggio?",a="Jangdor Passo Lesto chiede dieci pelli di yeti della Tana degli Artiglio Selvaggio all'Accampamento Mojache, a Feralas.",al={"chi dà qualità migliorata","committente della missione qualità migliorata","jangdor passo lesto"}},{q="Dove vivono gli yeti della Tana degli Artiglio Selvaggio?",a="Gli yeti della Tana degli Artiglio Selvaggio vivono all'interno della tana, nel nord di Feralas.",al={"posizione yeti della tana degli artiglio selvaggio","dove si trova la tana degli artiglio selvaggio","dove ottenere pelli di artiglio selvaggio"}},{q="Quante pelli sono richieste?",a="Jangdor Passo Lesto vuole dieci pelli di yeti della Tana degli Artiglio Selvaggio.",al={"quante pelli di yeti","oggetti richiesti per qualità migliorata"}},{q="Cosa c'era prima di questa?",a="Segue The Mark of Quality, quando hai affrontato la prima mandria di yeti.",al={"missione prerequisito","quale missione porta a qualità migliorata","missione precedente"}}},fp="16,101,25.287.0,16.172.1,38.82.0,34.68.0,26.52.0,22.78.0"}
P.entries["quest:7735"] = {n="Pelle di Yeti Intatta",s="A Feralas, una pelle degli yeti di Rage Scar potrebbe attirare l'attenzione di Pratt McGrubben. È insolitamente spessa e resistente, e Pratt vuole comprare pelli di yeti.",h="A Feralas, una pelle degli yeti di Rage Scar potrebbe attirare l'attenzione di Pratt McGrubben.",kw={"roccaforte di piumaluna","feralas","pratt mcgrubben","pristine yeti hide","rage scar","pelle di yeti"},sec={{t="Una pelle fuori dal comune",b="Tra le pelli degli yeti di Rage Scar, questa è insolitamente spessa e robusta. Pratt McGrubben vuole comprare pelli di yeti alla Roccaforte di Piumaluna, a Feralas, quindi questa pelle potrebbe interessargli."},{t="La reazione di Pratt",b="Pratt è stupito dalla pelle e si chiede se possa esisterne una migliore. Offre più di quanto si ricavi di solito da una singola pelle, convinto che se ne possa ricavare qualcosa di speciale."}},faq={{q="Chi cerca la Pristine Yeti Hide?",a="Pratt McGrubben vuole comprare pelli di yeti alla Roccaforte di Piumaluna, a Feralas.",al={"chi prende pristine yeti hide","dove porto la pristine yeti hide","pratt mcgrubben pristine yeti hide"}},{q="Cosa rende speciale questa pelle?",a="Rispetto alle pelli degli yeti di Rage Scar, questa è insolitamente spessa e resistente.",al={"provenienza pristine yeti hide","cosa rende speciale la pelle","pelle yeti feralas"}},{q="Dov'è Pratt McGrubben?",a="Pratt McGrubben si trova alla Roccaforte di Piumaluna, a Feralas.",al={"dove si trova pratt mcgrubben","dove portare pristine yeti hide"}}},fp="18,147,26.188.0,16.174.1,33.82.0,29.82.0,25.56.0"}
P.entries["quest:7736"] = {n="Restoring Fiery Flux Supplies via Kingsblood",s="Nella Gorgia Rovente, il Maestro Fabbro Ardirabbia ha bisogno di altro flusso ardente dopo What the Flux?. Ti chiede scaglie di incendosauro, Sanguesacro e carbone, e accetta tutto ciò che puoi offrirgli.",h="Nella Gorgia Rovente, il Maestro Fabbro Ardirabbia ha bisogno di altro flusso ardente dopo What the Flux?.",kw={"ardirabbia","carbone","flusso ardente","incendosauro","sanguesacro","gorgia rovente","fratellanza del torio"},sec={{t="Flusso ardente cercasi",b="Il Maestro Fabbro Ardirabbia ha poco tempo per parlare. Il suo flusso ardente sta finendo, quindi ti chiede due scaglie di incendosauro, quattro Sanguesacro e carbone. Accetterà tutto ciò che puoi offrirgli."}},faq={{q="Chi richiede questi beni?",a="Il Maestro Fabbro Ardirabbia chiede i beni nella Gorgia Rovente e li riceve di persona.",al={"chi assegna questa missione","ardirabbia flusso ardente","dove consegnare"}},{q="Quali materiali vuole Ardirabbia?",a="Ardirabbia vuole due scaglie di incendosauro, quattro Sanguesacro e carbone.",al={"quali oggetti servono","materiali per flusso ardente","consegna oggetti ad ardirabbia"}},{q="Cosa precede questa richiesta?",a="What the Flux? precedeva questa richiesta, e Ardirabbia te l'ha affidata.",al={"prerequisiti per questa missione","missione precedente flusso ardente","prerequisito what the flux"}},{q="Perché Ardirabbia vuole questi beni?",a="Ardirabbia afferma che la scorta di flusso ardente sta diminuendo e vuole reintegrarla.",al={"perché flusso ardente","motivazione ardirabbia"}}},fp="44,177,17.181.0,25.91.0,35.66.0,30.70.0,36.78.0"}
P.entries["quest:7738"] = {n="Pelle di Yeti Perfetta",s="All'Accampamento Mojache, Jangdor Passo Lesto compra pelli di yeti. Quella che hai trovato potrebbe essere perfetta. È più spessa e resistente delle pelli degli yeti di Rage Scar.",h="All'Accampamento Mojache, Jangdor Passo Lesto compra pelli di yeti.",kw={"accampamento mojache","feralas","jangdor passo lesto","perfect yeti hide","rage scar","pelle di yeti"},sec={{t="Una pelle che vale la pena mostrare",b="La pelle è più spessa e robusta di quelle degli yeti di Rage Scar. Jangdor Passo Lesto compra pelli di yeti all'Accampamento Mojache, a Feralas. Vale la pena portargliela."},{t="Il verdetto di Jangdor",b="Jangdor Passo Lesto è entusiasta della pelle e la definisce la più bella che abbia mai visto. Ti offre più di quanto paghi di solito per una pelle, sicuro di poterci creare qualcosa di speciale."}},faq={{q="A chi interessa la Perfect Yeti Hide?",a="Jangdor Passo Lesto, all'Accampamento Mojache a Feralas, vuole comprare pelli di yeti.",al={"chi vuole la pelle","chi consegna la perfect yeti hide","jangdor pelle di yeti"}},{q="Perché questa pelle è considerata speciale?",a="Lo spessore e la resistenza insoliti la distinguono dalle pelli degli yeti di Rage Scar.",al={"perché è perfetta","cosa rende speciale la pelle"}},{q="Dove si trova Jangdor Passo Lesto?",a="Jangdor Passo Lesto si trova all'Accampamento Mojache, a Feralas.",al={"dove si trova jangdor passo lesto","dove portare la perfect yeti hide"}}},fp="17,163,20.175.0,17.177.1,43.72.0,36.92.0,30.51.0"}
P.entries["quest:775"] = {n="Viaggio a Picco del Tuono",s="Dopo i Rites of the Earthmother, gli spiriti ti mandano da Mulgore a Picco del Tuono. Cairne Zoccolo Sanguinario, High Chieftain dei tauren, ti attende lì.",h="Dopo i Rites of the Earthmother, gli spiriti ti mandano da Mulgore a Picco del Tuono.",kw={"spirito ancestrale","cairne zoccolo sanguinario","high rise","viaggio a picco del tuono","mulgore","rites of the earthmother","picco del tuono"},ang={["faction:Horde"]="Come membro dell'Orda, vedi il rispetto reciproco tra i suoi popoli quando i tauren accolgono le razze alleate che completano le loro tradizioni sacre.",["race:Tauren"]="Per un giovane tauren, presentarsi al cospetto di Cairne Zoccolo Sanguinario dopo i riti della Madre Terra segna il passaggio all'età adulta e gli procura onore tribale."},sec={{t="La Conclusione di un Rito di Passaggio",b="In tutta Mulgore, i Rites of the Earthmother mettono alla prova la tua forza, la tua visione e la tua saggezza. Le prove attraversano le pianure e i siti ancestrali della terra. Quando lo Spirito Ancestrale riconosce il tuo rito finale, hai dimostrato di meritare l'ingresso a Picco del Tuono come difensore del popolo tauren."},{t="Ascensione verso l'High Rise",b="Dal terreno sacro dove vagano gli spiriti, sali fino a Picco del Tuono. La città domina le mesas di pietra rossa, collegate da ponti di corda e grandi ascensori di legno. Cairne Zoccolo Sanguinario, High Chieftain dei tauren, ti attende sull'High Rise, pronto ad accogliere chi ha seguito il sentiero degli antenati."}},faq={{q="Chi ti invia in questo viaggio?",a="Uno Spirito Ancestrale ti manda da Cairne dopo che completi il Rite of Wisdom, l'ultima tappa dei tradizionali Rites of the Earthmother.",al={"chi assegna la missione","missione spirito ancestrale","chi dà la missione"}},{q="Dove posso trovare Cairne Zoccolo Sanguinario?",a="Cairne Zoccolo Sanguinario ti attende sull'High Rise, la mesa centrale di Picco del Tuono, sopra gli altopiani rossi e le pianure.",al={"posizione cairne","dove si trova cairne","capo di picco del tuono"}},{q="Qual è il significato del completamento di questa missione?",a="Raggiungere Cairne segna ufficialmente la fine delle avventure iniziali a Mulgore. I capi tauren ti riconoscono e sei pronto ad assumerti incarichi in tutta l'Orda.",al={"perché visitare cairne","significato dei riti","significato del viaggio a picco del tuono"}},{q="Solo i tauren completano questo viaggio?",a="Il viaggio è un tradizionale rito di passaggio dei tauren. Ogni membro dell'Orda che dimostra la propria dedizione attraverso i Rites of the Earthmother riceve lo stesso onore e viene mandato a incontrare l'High Chieftain.",al={"gli orchi possono farlo","chi può fare il viaggio a picco del tuono","razze"}},{q="Cosa succede dopo aver parlato con Cairne?",a="Cairne ti accoglie nella sua dimora e riconosce le tue imprese. Ti indica i conflitti più ampi che attendono l'Orda in tutta Kalimdor.",al={"prossima missione","cosa fare dopo cairne","dopo il viaggio a picco del tuono"}},{q="Come si raggiunge l'High Rise a Picco del Tuono?",a="Prendi i grandi ascensori meccanici dalle pianure sottostanti fino alle mesas. Poi attraversa i ponti di corda e legno fino alla piattaforma centrale dell'High Rise, dove si trova la dimora del Chieftain.",al={"come arrivare all'high rise","come arrivare da cairne","ascensori di picco del tuono"}}},fx={["74afb15b"]={q="Perché lo Spirito Ancestrale ti manda a Picco del Tuono?",a="Superando le prove in tutta Mulgore ed entrando in comunione con gli spiriti, hai dimostrato saggezza, forza e devozione attraverso i Rites of the Earthmother. Lo Spirito Ancestrale ti manda a Picco del Tuono affinché il popolo tauren e il suo più grande condottiero, Cairne Zoccolo Sanguinario, riconoscano le tue imprese. Presentarti al Gran Capo segna la tua formale accettazione nella loro società come campione onorato.",al={"perché lo spirito ancestrale ti manda","motivo dello spirito ancestrale","perché andare da cairne"}},c86a41a9={q="Perché devi riferire la notizia a Cairne Zoccolo Sanguinario di persona?",a="I Rites of the Earthmother sono una sacra prova personale. Lo Spirito Ancestrale è una guida ultraterrena legata ai luoghi sacri di Mulgore, incapace e non disposto a portare messaggi terreni. Poiché sono stati messi alla prova il tuo spirito e la tua determinazione, solo tu hai l'onore di presentarti al Gran Capo Cairne Zoccolo Sanguinario.",al={"perché proprio io da cairne","perché devo visitare cairne","perché devo vedere cairne zoccolo sanguinario"}}},fp="26,152,27.307.0,26.303.0,30.128.0,34.111.0,50.174.0,37.205.0,38.135.0,48.183.0"}
P.entries["quest:776"] = {n="Rites of the Earthmother",s="L'Alto Capotribù Cairne Zoccolo Sanguinario ti manda per Mulgore sulle tracce del grande kodo Arra'chea. Anche dopo gli antichi riti, chiede al suo popolo di dimostrare di nuovo forza, capacità di seguire le tracce e devozione. Il corno di Arra'chea dimostra a Cairne che sei pronto a servire l'intera Orda.",h="L'Alto Capotribù Cairne Zoccolo Sanguinario ti manda per Mulgore sulle tracce del grande kodo Arra'chea.",kw={"arra'chea","arrachea","zoccolo sanguinario","cairne","madre terra","corno","caccia","kodo","mulgore","picco del tuono"},ang={["class:Hunter"]="Da cacciatore, dai la caccia a un colosso solitario e vagabondo per la Piana Dorata. I maestri tauren nell'arte di seguire le tracce tramandano questo antico metodo di caccia di generazione in generazione.",["faction:Horde"]="Come membro dell'Orda, abbattendo Arra'chea contribuisci a procurare cibo, cuoio e materiali a Picco del Tuono. La caccia riflette la lotta condivisa per la sopravvivenza che sostiene la giovane Orda.",["race:Tauren"]="Come giovane shu'halo, ti presenti a Cairne Zoccolo Sanguinario per portargli il corno di Arra'chea. Il rito dimostra che il tuo valore onora i tuoi antenati e le mandrie di Mulgore."},sec={{t="La misura di un Capotribù",b="A Picco del Tuono, l'infanzia di un giovane tauren lascia il posto al dovere. L'Alto Capotribù Cairne Zoccolo Sanguinario chiede ai giovani cacciatori di continuare a dimostrare il proprio valore. Raggiungere le alte rupi segna l'inizio di una vita al servizio delle Tribù Tauren Unite. Cairne chiede più di una caccia a piccoli parassiti: vuole la prova delle tue abilità sul campo, dimostrate seguendo le tracce e scuoiando con cura una delle famose bestie erranti di Mulgore."},{t="La caccia ad Arra'chea",b="Arra'chea è un kodo enorme e leggendario, il cui percorso circolare attraversa le erbe dorate a nord-est di Picco del Tuono. Abbattere questa grande bestia richiede di seguirla con pazienza nella savana aperta, non solo di usare la forza bruta. Riporta il corno di Arra'chea all'High Rise e Cairne manderà scuoiatori e raccoglitori a utilizzare ogni parte della bestia sacra per rifornire la città."}},faq={{q="Chi assegna questa missione?",a="L'Alto Capotribù Cairne Zoccolo Sanguinario ti affida questa caccia dal suo seggio sull'High Rise di Picco del Tuono.",al={"chi assegna la missione","chi affida i rites of the earthmother","missione di cairne"}},{q="Cos'è Arra'chea?",a="Arra'chea è un famoso kodo che vaga per le pianure di Mulgore. Il suo grande corno dimostra l'abilità di un cacciatore nel seguire le tracce e il suo valore marziale.",al={"chi è arrachea","cos'è arrachea","storia di arrachea"}},{q="Dove posso trovare Arra'chea?",a="Arra'chea percorre un ampio tragitto circolare a nord-est delle rupi di Picco del Tuono, girando in senso orario per le pianure aperte.",al={"dove si trova arrachea","posizione di arrachea","percorso di arrachea"}},{q="Perché Cairne mi affida questa caccia se ho già completato i riti precedenti?",a="Per i tauren, ottenere un posto iniziale è solo l'inizio del dovere. Cairne ti chiede di continuare a dimostrare la tua forza, umiltà e abilità nella caccia al servizio della tribù.",al={"perché fare questa missione","perché uccidere arrachea","scopo dei riti"}},{q="Cosa succede al corpo di Arra'chea dopo che il corno è stato preso?",a="Cairne manda una squadra di raccoglitori a recuperare la carne e la pelle di Arra'chea. La preda fornisce cibo e vestiti a Picco del Tuono, secondo la tradizione tauren che insegna a onorare le proprie prede.",al={"carne di arrachea","cosa succede al kodo","cosa succede alla carcassa"}},{q="È la stessa missione dei primi riti per gli iniziati?",a="No. Le prime prove al Campo Narache insegnano a un iniziato i Rites of the Earthmother fondamentali. Questa caccia a Picco del Tuono è la prova personale di Cairne per verificare che tu sia ancora un cacciatore degno.",al={"differenze tra i rites of the earthmother","quale missione dei riti","riti di campo narache"}}},fx={d7a516d7={q="A cosa serve il Corno Arra'chea?",a="Il corno è la prova concreta della tua caccia riuscita. La tradizione tauren attribuisce grande onore all'abilità di seguire le tracce e abbattere bestie possenti. Presentare il corno di Arra'chea direttamente al Gran Capo Cairne Zoccolo Sanguinario dimostra che possiedi la maestria necessaria per provvedere al tuo popolo e proteggerlo.",al={"uso del corno arra'chea","perché portare il corno di arra'chea","scopo del corno arra'chea"}},a7e696eb={q="Perché Cairne Zoccolo Sanguinario manda te invece delle guardie cittadine?",a="Questa caccia non è una missione di difesa o una semplice raccolta di risorse: è una prova tradizionale. Anche se potresti aver superato i primi Rites of the Earthmother per raggiungere Picco del Tuono, Cairne si aspetta che ogni cacciatore della tribù dimostri continuamente il proprio valore e la propria autosufficienza con grandi imprese, senza adagiarsi sui successi passati.",al={"perché mandare me","perché non mandare le guardie da arra'chea","perché cairne ha bisogno di me"}}},fp="24,265,21.386.0,22.362.0,21.97.0,18.127.0,27.110.0,78.161.0,57.165.0,50.188.0"}
P.entries["quest:777"] = {n="This Is Going to Be Hard",s="Al riparo, Lucien Chiavetorta ti aspetta mentre porti l'ingranaggio numero cinque a Lotwil Veriatus.",h="Al riparo, Lucien Chiavetorta ti aspetta mentre porti l'ingranaggio numero cinque a Lotwil Veriatus.",kw={"maleterre","ingranaggio 5","lotwil veriatus","lucien chiavetorta","catene","this is going to be hard"},sec={{t="Al riparo",b="Lucien Chiavetorta ti consegna l'ingranaggio per Lotwil Veriatus. Poi ti aspetta al riparo e ti invita a raggiungerlo. Lotwil è ancora chino sui ceppi quando arrivi. Senza alzare lo sguardo, tende la mano e agita le dita per avere l'ingranaggio."},{t="Fare la storia",b="Lotwil prende l'ingranaggio e lo definisce perfetto. Ti dice di fare un passo indietro mentre si prepara a fare ancora la storia. Poi riprende a lavorare febbrilmente."}},faq={{q="Chi consegna l'ingranaggio per Lotwil?",a="Lucien Chiavetorta ti dà l'ingranaggio n. 5 da portare a Lotwil Veriatus.",al={"chi dà l'ingranaggio","dove prendo l'ingranaggio 5","ingranaggio lucien"}},{q="Dove va Lucien?",a="Lucien si dirige al riparo e ti invita a raggiungerlo.",al={"perché lucien si nasconde","riparo lucien"}},{q="Cosa sta facendo Lotwil quando porti l'ingranaggio?",a="Lotwil sta lavorando a una serie di ceppi. Senza alzare lo sguardo, tende la mano e agita le dita impaziente per avere l'ingranaggio.",al={"cosa fa lotwil","catene lotwil","progresso lotwil"}}},fp="24,82,12.250.0,14.145.1,34.65.0,21.55.0,44.130.0"}
P.entries["quest:778"] = {n="This Is Going to Be Hard",s="Nelle Maleterre, Lotwil Veriatus è pronto a evocare un potente elementale.",h="Nelle Maleterre, Lotwil Veriatus è pronto a evocare un potente elementale.",kw={"maleterre","elementale","guardiano fam'retor","lotwil veriatus","lucien","servo","vincoli di legame elementale"},sec={{t="Una giornata rivoluzionaria",b="Lotwil annuncia che i vincoli sono pronti. Il momento è arrivato. Chiede a Lucien e Servo di assistere all'evocazione insieme a te. Alchimia, ingegneria e arcano si fondono nei vincoli, e Lotwil si aspetta che un potente elementale risponda in questo giorno rivoluzionario."},{t="Dopo l'evocazione",b="L'evocazione finisce diversamente da come Lotwil si aspettava. Dopo che sconfiggi il Guardiano Fam'retor, Lotwil ti chiede di riportargli i Vincoli di Legame Elementale. Non sa dire cosa sia andato storto. È comunque contento che le magie fossero pronte a rimandare la creatura sul proprio piano."}},faq={{q="Chi è Lotwil Veriatus?",a="Lotwil Veriatus ha creato i Vincoli di Legame Elementale unendo alchimia, ingegneria e arcano. Lucien e Servo sono con lui nelle Maleterre.",al={"chi è lotwil","lotwil veriatus"}},{q="Cosa sono i Vincoli di Legame Elementale?",a="I Vincoli di Legame Elementale combinano alchimia, ingegneria e arcano. Lotwil li ha appena finiti per il potente elementale che intende evocare.",al={"cosa sono i vincoli","vincoli di legame elementale"}},{q="Chi chiama Lotwil a far da testimoni?",a="Lotwil invita Lucien e Servo ad assistere all'evocazione insieme a te.",al={"chi è lucien","chi è servo"}},{q="Cosa viene prima di questo passaggio?",a="Prima di allora, hai portato la ruota dentata numero cinque a Lotwil.",al={"missione precedente","cosa ha portato a questo"}}},fp="24,73,20.272.0,19.273.1,23.149.0,43.155.0,37.67.0,28.42.0"}
P.entries["quest:7781"] = {n="Il Signore di Roccianera",s="La Testa Mozzata di Nefarian arriva al Forte di Roccavento dopo la sua sconfitta nella Fortezza dell'Ala Nera. Il Gran Signore Bolvar Domadraghi la riceve come prova della caduta del padrone del Massiccio Roccianera. La vittoria è tra i più grandi trionfi militari dell'Alleanza nella storia recente.",h="La Testa Mozzata di Nefarian arriva al Forte di Roccavento dopo la sua sconfitta nella Fortezza dell'Ala Nera.",kw={"massiccio roccianera","fortezza dell'ala nera","gran signore bolvar domadraghi","testa di nefarian","il signore di roccianera","nefarian","forte di roccavento"},ang={["faction:Alliance"]="Per l'Alleanza, presentare la testa di Nefarian è un trionfo militare supremo. Spezza i complotti del Volo dei Draghi contro le terre umane.",["race:Human"]="Da umano, sai che dal Massiccio Roccianera sono partite innumerevoli incursioni e trame contro Roccavento. La sconfitta del suo padrone porta al regno la tanto attesa rivalsa e un senso di sollievo."},sec={{t="Un monumento alla vittoria",b="Nefarian, capo della covata del Volo dei Draghi Neri e sovrano dei Bastioni di Roccianera Superiori, minaccia da tempo i regni umani circostanti. La sua sconfitta pone fine ai suoi esperimenti contorti e ai suoi complotti. La sua testa, segnata dalla battaglia, viene riportata a Roccavento: prova che i più grandi eroi dell'Alleanza hanno sconfitto il Signore di Roccianera."},{t="Udienza al Forte di Roccavento",b="Il Gran Signore Bolvar Domadraghi governa il regno dalla sala del trono del Forte di Roccavento. La testa mozzata del drago sconvolge la corte reale e impone rispetto. Il regno affronta conflitti politici interni e minacce esterne. Questa vittoria risolleva il morale e conquista un posto nella storia dell'Alleanza."}},faq={{q="Di cosa parla la missione Il Signore di Roccianera?",a="Raccogli la Testa Mozzata di Nefarian nella Fortezza dell'Ala Nera e la porti a Roccavento. Lì presenti il trofeo al Gran Signore Bolvar Domadraghi a nome del regno.",al={"missione il signore di roccianera","missione testa di nefarian alleanza","testa di nefarian roccavento"}},{q="Chi è Nefarian?",a="Nefarian è un possente drago nero e figlio di Alamorte. Governa dalla Fortezza dell'Ala Nera, sul Massiccio Roccianera, comanda gli orchi Roccianera e conduce sinistri esperimenti per creare il chromatic dragonflight.",al={"chi è nefarian","il signore di roccianera","storia di nefarian"}},{q="Chi è il Gran Signore Bolvar Domadraghi?",a="Il Gran Signore Bolvar Domadraghi è il paladino che governa Roccavento come reggente durante l'assenza di re Varian Wrynn. Tiene corte nella sala del trono del Forte di Roccavento e veglia sul giovane principe Anduin Wrynn.",al={"bolvar fordragon","chi è bolvar","gran signore bolvar"}},{q="Perché questo trofeo viene portato al Forte di Roccavento?",a="Il dominio di Nefarian sul Massiccio Roccianera minaccia Roccavento e tutto il continente meridionale. Portare la sua testa ai comandanti militari del regno conferma la sua sconfitta e dà al reame una vittoria attorno a cui raccogliersi.",al={"perché roccavento","perché portare la testa al forte","perché bolvar"}},{q="Cosa succede dopo aver dato la testa a Bolvar?",a="Il Gran Signore Bolvar Domadraghi è sbalordito e dichiara che il trionfo sarà consegnato alla storia. Poi la testa viene esposta in pubblico, perché tutti a Roccavento possano vederla.",al={"cosa succede dopo","il signore di roccianera parte due","consegna testa di nefarian"}},{q="Consegnare questa testa influenza l'intera città?",a="Sì. La testa di Nefarian viene portata nella capitale ed esposta sopra le porte della città. Annuncia la morte del drago a cittadini e soldati e rafforza la determinazione dei difensori di Roccavento.",al={"potenziamento città","grido di battaglia","potenziamento testa di nefarian"}}},fx={["150c64a2"]={q="Perché è importante portare la Testa di Nefarian a Roccavento?",a="Nefarian era il drago nero che orchestrava le minacce provenienti dai Bastioni di Roccianera, manipolava i regni mortali e creava eserciti mostruosi alle porte di Roccavento. Consegnare la sua testa mozzata al Gran Signore Bolvar Domadraghi è una prova inconfutabile che il terrore della progenie è stato infranto; offre all'Alleanza una vittoria straordinaria da celebrare e mostrare al regno.",al={"perché portare la testa di nefarian a roccavento","motivo della testa di nefarian","perché consegnare la testa di nefarian"}},["7e2ee731"]={q="Perché devi portare la testa a Roccavento invece delle guardie reali?",a="Tu e i tuoi compagni vi siete fatti strada combattendo attraverso la Fortezza dell'Ala Nera e avete abbattuto personalmente il signore dei draghi. Riportare il macabro trofeo al Forte di Roccavento è un tuo diritto, in quanto campione che lo ha sconfitto, e fa sì che il Gran Signore Bolvar Domadraghi riceva la notizia direttamente dagli eroi che hanno ucciso la bestia.",al={"perché devo consegnare la testa di nefarian","perché non le guardie reali per la testa di nefarian","perché proprio io per il trofeo di nefarian"}}},fp="21,264,21.326.0,26.287.0,42.168.0,16.211.0,33.197.0,45.214.0,45.152.0,48.190.0"}
P.entries["quest:7782"] = {n="Il Signore di Roccianera",s="Alle porte di Roccavento, l'Alleanza si raduna per celebrare la vittoria su Roccianera. Dopo aver fatto rapporto all'Ammiraglio Jes-Tereth nel Forte di Roccavento, gli eroi si dirigono verso la Valle degli Eroi. Il Primo Maresciallo Ponteforte è pronto a guidare la commemorazione pubblica della città.",h="Alle porte di Roccavento, l'Alleanza si raduna per celebrare la vittoria su Roccianera.",kw={"roccianera","ammazzadraghi","nefarian","grido di radunata","ponteforte","roccavento","valle degli eroi"},ang={["class:Warrior"]="Il Grido di Radunata dell'Ammazzadraghi infonde forza ai combattenti in partenza per difendere il regno.",["faction:Alliance"]="La testa di Nefarian nella Valle degli Eroi unisce le razze dell'Alleanza. I cittadini di Forgiardente, Darnassus e Gnomeregan vedono che le forze oscure che affliggono i Regni Orientali possono essere sconfitte.",["race:Human"]="Per il regno di Roccavento, sconfiggere il signore di Roccianera elimina una grave minaccia draconica dal confine settentrionale."},sec={{t="Il Trionfo di una Città",b="La campagna contro il clan Roccianera e la progenie dello Stormo dei Draghi Neri giunge alla sua conclusione pubblica. La Testa Mozzata di Nefarian viene esposta all'interno del Forte di Roccavento. Poi il Gran Signore Bolvar Domadraghi manda i campioni attraverso la città, verso la Valle degli Eroi. Il Primo Maresciallo Ponteforte li attende per ricevere il trofeo e dare inizio ai festeggiamenti."},{t="Radunare l'Alleanza",b="Il Primo Maresciallo Ponteforte solleva la Testa Mozzata di Nefarian sopra i grandi archi dell'ingresso principale di Roccavento. La vista si diffonde per tutta la città e il Grido di Radunata dell'Ammazzadraghi ispira i difensori, i dignitari in visita e i cittadini. Sanno che la progenie di Alamorte ha subito un colpo durissimo."}},faq={{q="Cosa succede quando completi questa missione?",a="Il Primo Maresciallo Ponteforte appende in alto la Testa Mozzata di Nefarian sull'arco di pietra della Valle degli Eroi. Poi il Grido di Radunata dell'Ammazzadraghi infonde forza ai combattenti alleati e alle guardie di tutta Roccavento.",al={"consegna missione testa di nefarian","cosa fa il primo maresciallo ponteforte","attivazione grido di radunata"}},{q="Chi è il Primo Maresciallo Ponteforte?",a="Il Primo Maresciallo Ponteforte è un ufficiale di alto grado dell'esercito di Roccavento, di stanza nella Valle degli Eroi, vicino all'ingresso della città. Organizza le commemorazioni pubbliche delle vittorie militari, compresa l'esposizione delle teste dei nemici draconici sconfitti.",al={"ponteforte","primo maresciallo ponteforte"}},{q="Perché il Gran Signore Bolvar Domadraghi ti manda qui?",a="Dopo aver ricevuto notizia della sconfitta di Nefarian nella sala del trono, il Gran Signore Bolvar Domadraghi ti manda alle porte della città. Lì, l'esercito dell'Alleanza può esibire apertamente la vittoria e risollevare il morale in tutta la capitale.",al={"bolvar","perché andare alla valle degli eroi"}},{q="Questa consegna ha effetto su tutta la città?",a="Sì. Quando Ponteforte riceve il trofeo, un proclama risuona per Roccavento e il Grido di Radunata dell'Ammazzadraghi raggiunge tutti coloro che si trovano entro i confini della città.",al={"bonus mondiale nefarian","roccavento riceve il bonus"}},{q="Dove si trova la Valle degli Eroi?",a="La Valle degli Eroi è il grandioso viale che conduce a Roccavento. Statue imponenti lo costeggiano, in onore degli eroi della Seconda Guerra che attraversarono il Portale Oscuro.",al={"posizione valle degli eroi","dove si trova il primo maresciallo ponteforte"}},{q="Chi era il «Signore di Roccianera»?",a="Il drago nero Nefarian era il Signore di Roccianera. È figlio di Alamorte e governa le guglie superiori del Massiccio Roccianera.",al={"chi è il signore di roccianera","identità di nefarian"}}},fx={["3a42f3f3"]={q="Perché Bolvar manda te invece di andare di persona?",a="Tu e i tuoi compagni siete stati i campioni che hanno affrontato le alture della Fortezza dell'Ala Nera e abbattuto Nefarian. Da vincitore, spetta di diritto a te presentare la testa mozzata del drago ai capi militari di Roccavento e dare inizio ai festeggiamenti in tutta la città.",al={"perché mandare me","perché non bolvar","perché devo consegnare la testa"}}},fp="21,261,16.338.1,21.299.0,42.221.1,33.240.0,49.213.1,40.162.1,38.164.0,32.124.2"}
P.entries["quest:7783"] = {n="Il Signore di Roccianera",s="A Orgrimmar, la Testa Mozzata di Nefarian viene portata al cospetto di Thrall come prova della vittoria. Il suo arrivo segna la caduta di un grande nemico dell'Orda.",h="A Orgrimmar, la Testa Mozzata di Nefarian viene portata al cospetto di Thrall come prova della vittoria.",kw={"roccianera","fortezza dell'ala nera","alamorte","ammazzadraghi","thrall","nefarian","orgrimmar","grido di battaglia"},ang={["class:Warrior"]="Da guerriero, ottieni grande fama marziale portando al Capoguerra il massiccio teschio mozzato di un signore dei draghi.",["faction:Horde"]="La caduta di Nefarian restituisce onore all'Orda e libera la regione di Roccianera dal drago che aveva schiavizzato la ribelle Dark Horde.",["race:Orc"]="Da orco, quando presenti la testa di Nefarian a Thrall, ti vendichi della bestia che manovrava Rend Blackhand e schiavizzava i clan orcheschi per i suoi esperimenti."},sec={{t="Un trofeo di rovina",b="Nefarian è finalmente caduto. Ha orchestrato le attività della Fortezza dell'Ala Nera e guidato la stirpe dei draghi neri nei Regni Orientali. La sua testa segnata dalla battaglia ne prova la morte. Per i guerrieri dell'Orda, portare questo trofeo dalle alture ardenti del Massiccio Roccianera attraverso il Grande Mare fino a Durotar è un grande onore."},{t="Il giudizio del Capoguerra",b="Il trofeo viene portato al cospetto del Capoguerra Thrall, che conosce bene la corruzione del Massiccio Roccianera. Ha liberato il suo popolo dai campi di internamento e lo ha guidato lontano dalla sete di sangue demoniaca della vecchia Orda. Ora il figlio di Alamorte è caduto e gli orchi del clan Roccianera sono liberi dal crudele dominio del drago nero."},{t="Ombre del padre",b="La morte di Nefarian pone fine ai contorti esperimenti della stirpe dei draghi neri, ma il pericolo rimane. Quando Thrall vede la Testa Mozzata, dice che Alamorte si starà sicuramente agitando alla notizia della distruzione di suo figlio. La vittoria è reale, ma terrori ancora più grandi dormono sotto il mondo."}},faq={{q="Chi è Nefarian?",a="Nefarian è un grande drago nero e il figlio di Alamorte. Dalla sua tana in cima al Massiccio Roccianera, conduceva contorti esperimenti per creare la stirpe dei draghi cromatici. Manipolava anche le razze mortali, soprattutto la Dark Horde, per indurle a eseguire i suoi ordini.",al={"retroscena nefarian","chi è nefarian","signore del drago nero"}},{q="Perché il trofeo viene consegnato a Thrall?",a="Thrall è il Capoguerra dell'Orda. Ha guidato gli orchi fuori dai campi di internamento e lontano dalla sete di sangue demoniaca della vecchia Orda. La prova che il drago che ha schiavizzato gli orchi del clan Roccianera e la Dark Horde è caduto deve finire nelle sue mani.",al={"perché thrall","chi riceve la testa"}},{q="Cosa succede a Orgrimmar quando la testa viene consegnata?",a="Quando la testa di Nefarian viene riportata a Orgrimmar e appesa in città, gli abitanti festeggiano. I membri dell'Orda nelle vicinanze ricevono il Grido di Battaglia dell'Ammazzadraghi, che accresce la loro abilità in combattimento.",al={"bonus della testa","bonus mondiale orgrimmar","bonus grido di battaglia"}},{q="Questa missione ha una controparte per l'Alleanza?",a="Sì. Gli eroi dell'Alleanza portano la testa di Nefarian al Gran Signore Bolvar Domadraghi nel Forte di Roccavento, conferendo alla loro città la stessa benedizione.",al={"versione dell'alleanza","controparte dell'alleanza"}},{q="Perché Alamorte è una preoccupazione?",a="Alamorte è il padre di Nefarian e il patriarca del Drago Nero. Sconfiggere suo figlio non rimuove il pericolo rappresentato dal padre dei draghi.",al={"il malvagio si agita","chi è il malvagio"}},{q="Da dove viene la testa?",a="La Testa di Nefarian si ottiene dal cadavere di Nefarian, in cima alla Fortezza dell'Ala Nera, dopo averlo sconfitto.",al={"come ottenere testa di nefarian","oggetto avvio missione"}}},fx={d14146dc={q="Perché la Testa di Nefarian deve essere portata a Orgrimmar?",a="Recidere l'enorme testa, segnata dalla battaglia, del drago caduto fornisce una prova inconfutabile che il padrone dei Bastioni di Roccianera è stato sconfitto. Riportare un trofeo così mostruoso a Orgrimmar dimostra la supremazia dell'Orda, celebra una vittoria straordinaria contro la Stirpe dei Draghi Neri e permette al consiglio del Capoguerra di verificare che i contorti esperimenti di Nefarian all'interno della montagna siano finalmente terminati.",al={"perché portare la testa di nefarian","motivo della testa di nefarian","perché dare la testa a eitrigg"}}},fp="21,141,16.296.0,23.303.0,21.263.1,16.248.0,38.235.0,53.181.0,44.129.0,27.147.0,30.106.0"}
P.entries["quest:7784"] = {n="Il Signore di Roccianera",s="Davanti all’Orda, a Orgrimmar, la Testa Mozzata di Nefarian testimonia la sua sconfitta. Thrall conferma la morte del drago nero, poi ti manda dal Gran Supremo Faucisaure, nella Valle della Forza, per mostrare il trofeo a tutti.",h="Davanti all’Orda, a Orgrimmar, la Testa Mozzata di Nefarian testimonia la sua sconfitta.",kw={"fortezza dell'ala nera","thrall","testa di nefarian","faucisaure","orgrimmar","nefarian","valle della forza"},ang={["faction:Horde"]="Per l’Orda, l’esposizione pubblica della testa di Nefarian dimostra la forza della nuova Orda contro il drago nero che manipolava gli orchi del Massiccio Roccianera. Rafforza il nuovo ordine di Thrall.",["race:Orc"]="Da orco, potresti provare un profondo sollievo per la caduta del drago che teneva in schiavitù il clan Roccianera. La sua sconfitta solleva il tuo popolo da un’ombra disonorevole."},sec={{t="Un trofeo per l’Orda",b="La testa di Nefarian arriva a Orgrimmar dopo la caduta del drago nero in cima alla Fortezza dell’Ala Nera. Il Capoguerra Thrall conferma che il figlio di Alamorte è morto, poi ti manda dal Gran Supremo Faucisaure, nella Valle della Forza. Lì, i resti vengono preparati perché tutti possano vederli. Il trofeo mette in guardia i nemici dell’Orda e raduna la vera Orda."},{t="Rivendicare l'eredità",b="Nefarian governava le vette del Massiccio Roccianera, piegando al suo volere gli orchi Roccianera e l’Orda Oscura. Abbattendolo e innalzando la sua testa nella Valle della Forza, l’Orda di Thrall infligge un duro colpo al Volo dei Draghi Neri. Faucisaure chiama tutta Orgrimmar a gioire per il Grido di Battaglia dell’Ammazzadraghi."}},faq={{q="Qual è lo scopo di questa missione?",a="Dopo aver dimostrato a Thrall che Nefarian è morto, ti presenti dal Gran Supremo Faucisaure nella Valle della Forza di Orgrimmar. La testa mozzata viene esposta al pubblico e ricevi degli onori.",al={"cosa fa questa missione","consegna della missione il signore di roccianera","perché andare da faucisaure"}},{q="Chi è il Gran Supremo Faucisaure?",a="Il Gran Supremo Faucisaure è un veterano guerriero orco e uno dei più grandi campioni dell’Orda. È di stanza nella Valle della Forza di Orgrimmar, dove riceve la testa e la fa esporre perché tutti possano vederla.",al={"chi è faucisaure","ruolo del gran supremo faucisaure"}},{q="Perché la testa di Nefarian viene esposta?",a="La testa esposta di Nefarian dimostra che il signore del Massiccio Roccianera è caduto. La sua esposizione risolleva il morale dei difensori di Orgrimmar e tutti gli abitanti della città ricevono il Grido di Battaglia dell’Ammazzadraghi.",al={"perché montare la testa di nefarian","esposizione testa nefarian orgrimmar"}},{q="Chi era Nefarian?",a="Nefarian era un grande drago nero e figlio di Alamorte. Dalla Fortezza dell’Ala Nera, in cima al Massiccio Roccianera, comandava gli orchi Roccianera e l’Orda Oscura e allevava il Volo dei Draghi Cromatici.",al={"chi era nefarian","lore di nefarian"}},{q="Dove si trova il Gran Supremo Faucisaure?",a="Faucisaure si trova nella Valle della Forza, il quartiere all’ingresso centrale di Orgrimmar.",al={"dove si trova faucisaure","posizione di faucisaure"}},{q="Che ruolo ha Thrall in questa vicenda?",a="Il Capoguerra Thrall riceve per primo la testa di Nefarian. Dopo aver confermato la morte del drago, ti manda da Faucisaure perché il trofeo venga esposto ufficialmente.",al={"perché thrall","coinvolgimento di thrall"}}},fp="21,219,22.320.0,19.328.1,34.182.0,30.203.0,38.203.0,17.190.0,40.77.0,35.148.0"}
P.entries["quest:7792"] = {n="A Donation of Wool",s="A Darnassus si raccoglie Tessuto di Lana per rifornire le scorte della città. Con sessanta pezzi ti guadagni il riconoscimento per la tua generosità.",h="A Darnassus si raccoglie Tessuto di Lana per rifornire le scorte della città.",kw={"darnassus","donazione","riconoscimento","scorte","lana","tessuto di lana"},sec={{t="Scorte di lana",b="Darnassus ha bisogno che tu fornisca sessanta pezzi di Tessuto di Lana. Ci si aspetta che gli altri abitanti del regno forniscano il resto delle scorte. La tua donazione ti farà ottenere pieno riconoscimento per la tua generosità."}},faq={{q="Di cosa ha bisogno Darnassus?",a="Darnassus ha bisogno di Tessuto di Lana per rifornire le sue scorte.",al={"donazione di lana","quale tessuto vuole darnassus"}},{q="Quanta lana devo donare?",a="Devi donare sessanta pezzi di Tessuto di Lana.",al={"quanta lana","sessanta pezzi di lana"}},{q="Perché Darnassus raccoglie lana?",a="Darnassus sta raccogliendo Tessuto di Lana per rifornire i suoi magazzini.",al={"perché la lana","raccolta di lana"}},{q="Cosa ottengo donando lana?",a="La tua donazione di sessanta pezzi ti farà ottenere pieno riconoscimento da Darnassus per la tua generosità.",al={"riconoscimento per la donazione di lana","ricompensa per donazione di lana"}}},fp="18,122,11.182.0,25.49.0,34.46.0,33.56.0,32.88.0"}
P.entries["quest:78"] = {n="Leggenda di Stalvan",s="Marshal Haggard ti manda da Taverniere Smitts, che potrebbe conoscere la mano dietro una pagina del diario di Stalvan.",h="Marshal Haggard ti manda da Taverniere Smitts, che potrebbe conoscere la mano dietro una pagina del diario di...",kw={"borgoscuro","boscovespro","elwynn","diario","marshal haggard","mistmantle","taverna del corvo scarlatto","stalvan","taverniere smitts"},ang={["faction:Alliance"]="Da difensore dell'Alleanza, vedi i legami tra gli ex membri della Guardia di Roccavento e i custodi della storia locale nel Regno di Roccavento.",["race:Human"]="Da umano, vedi come le tragedie della Foresta di Elwynn e di Borgoscuro restino nella memoria degli abitanti."},sec={{t="Una traccia dal Marshal",b="Marshal Haggard non riesce a leggere la scrittura sbiadita sulla pagina di diario strappata che hai recuperato dal suo baule nella Foresta di Elwynn. La vista che gli si sta indebolendo gli impedisce di distinguere le parole. Ricorda di aver prestato servizio nella Guardia di Roccavento e di aver trascorso le serate alla Taverna del Corvo Scarlatto a Borgoscuro. Così ti manda oltre il fiume da Taverniere Smitts, i cui anni dietro al bancone ne hanno fatto un custode della storia e delle voci locali."},{t="Ritorno al Corvo Scarlatto",b="Attraversi i cupi boschi di Boscovespro e mostri la pagina sbiadita a Smitts dietro al bancone. È lieto di avere notizie del suo vecchio conoscente Haggard, anche se si rammarica per la salute cagionevole del veterano. Poi Smitts vede la pergamena e il suo atteggiamento disinvolto lascia il posto all'allarme. Riconosce senza dubbio la calligrafia inconfondibile, avvicinando la ricerca alla verità sulla follia di Stalvan."}},faq={{q="Perché il Marshal Haggard mi rimanda a Borgoscuro?",a="Marshal Haggard è anziano e quasi cieco, perciò non può esaminare la pagina di diario recuperata. Ricorda Taverniere Smitts come un custode della tradizione locale dai tempi in cui prestava servizio nella Guardia di Roccavento, e ti manda a chiedergli della scrittura.",al={"perché andare a borgoscuro","haggard verso borgoscuro","perché smitts"}},{q="Dove si trova il Taverniere Smitts?",a="Taverniere Smitts serve al bancone della Taverna del Corvo Scarlatto, nella parte orientale di Borgoscuro, a Boscovespro.",al={"dove si trova smitts","posizione di smitts","posizione della taverna del corvo scarlatto"}},{q="Che oggetto porti al Taverniere Smitts?",a="Hai con te una Pagina di Diario Sbiadita, un estratto del diario perduto di Stalvan Mistmantle, ritrovato al sicuro nel baule di Marshal Haggard.",al={"quale oggetto","pagina di diario sbiadita","pagina del diario di stalvan"}},{q="Il Taverniere Smitts riconosce la calligrafia?",a="Sì. Smitts riconosce la calligrafia non appena vede la pagina sbiadita, e il suo allarme offre una nuova pista nella ricerca di Stalvan.",al={"smitts riconosce la scrittura","reazione di smitts al diario"}},{q="Come conosce il Marshal Haggard, Smitts?",a="Smitts ospitò Haggard anni fa, quando Haggard guidava le pattuglie della Guardia di Roccavento a Boscovespro e andava a bere alla Taverna del Corvo Scarlatto.",al={"relazione tra smitts e haggard","come smitts conosce haggard"}},{q="Cosa succede dopo nella ricerca di Stalvan?",a="Porta la pagina di diario sbiadita a Smitts, alla Taverna del Corvo Scarlatto, e segui la pista che ti indicherà.",al={"cosa succede dopo","prossimo passo stalvan","continua la catena di stalvan"}}},fx={bf062962={q="Perché Marshal Haggard vuole che venga fatto?",a="Marshal Haggard non riesce a leggere la pagina di diario sbiadita perché la sua vista sta peggiorando. Si ricorda di Taverniere Smitts, un vecchio conoscente esperto di storia locale, e ti chiede di portargli la pagina a Borgoscuro.",al={"perché haggard vuole che venga fatto","motivo di marshal haggard","perché aiutare a trovare stalvan"}},c297959a={q="Perché Marshal Haggard manda te invece di andarci di persona?",a="Haggard è un vecchio maresciallo in pensione che vive isolato e sta perdendo rapidamente la vista. Le strade nei boschi sono pericolose e gli mancano la giovinezza e la resistenza fisica necessarie per attraversare di nuovo il confine fino a Boscovespro. Si affida a un viaggiatore capace come te per sbrigare la commissione e mostrare la pagina di diario al suo vecchio conoscente.",al={"perché haggard non può andare","perché haggard ha bisogno di me","perché haggard non va da smitts"}}},fp="21,112,23.409.0,27.374.1,51.223.0,35.110.0,44.133.0,49.131.0,37.136.0,42.99.0"}
P.entries["quest:780"] = {n="The Battleboars",s="A Campo Narache, i giovani tauren cacciano i Battleboars per difendere le loro terre e nutrire i piccoli della tribù.",h="A Campo Narache, i giovani tauren cacciano i Battleboars per difendere le loro terre e nutrire i piccoli...",kw={"cinghiale da battaglia","depressione di rovoaguzzo","bristleback","campo narache","grull vento agile","mulgore","quillboar","mesa nuvola rossa"},ang={["class:Hunter"]="Come cacciatore, impari a distinguere la fauna selvatica dalle bestie che i Bristleback hanno trasformato in armi da guerra.",["profession:Cooking"]="Come cuoco, sai che anche la carne dura e coriacea può diventare uno stufato sostanzioso che nutre la tribù.",["race:Tauren"]="Come tauren, difendi i territori di Madre Terra e non sprechi nulla di ciò che conquisti in battaglia. Le bestie da guerra dei Bristleback diventano cibo per i piccoli del campo."},sec={{t="Una minaccia ai confini",b="A est della Mesa Nuvola Rossa si trova la Depressione di Rovoaguzzo, nelle mani dei quilboar Bristleback. Le tensioni tra gli Shu'halo e i quilboar sono sfociate in una guerra aperta. I Bristleback addestrano feroci Battleboars per mettere alla prova i confini tauren e minacciare i loro antichi territori di caccia. Se non vengono fermate, queste bestie mettono in pericolo sia i sentieri della selvaggina sia Campo Narache."},{t="Nutrire la tribù",b="La caccia protegge i tauren e nutre la tribù. Grull Vento Agile chiede ai giovani cacciatori di riportare musi e fianchi dei Battleboars. Anche queste bestie, addestrate dai quilboar, vengono sfruttate. La loro carne e la cartilagine finiscono nello stufato per i giovani della tribù, trasformando un'arma dei quilboar in cibo per la prossima generazione di difensori tauren."}},faq={{q="Perché i cinghiali da battaglia attaccano la mesa?",a="I quilboar Bristleback della Depressione di Rovoaguzzo hanno allevato e addestrato i Battleboars. Usano queste bestie per tormentare i tauren e invadere i territori di caccia tribali della Mesa Nuvola Rossa.",al={"aggressività dei cinghiali da battaglia","perché i cinghiali da battaglia sono ostili","attacchi dei cinghiali da battaglia"}},{q="Chi invia i giocatori in questa caccia?",a="Grull Vento Agile, cacciatore e anziano di Campo Narache, guida i giovani tauren nelle prove finali del loro addestramento iniziale.",al={"datore di missione dei cinghiali da battaglia","chi assegna la missione dei cinghiali da battaglia","ruolo di grull vento agile"}},{q="Dove si trovano i cinghiali da battaglia?",a="I Battleboars si aggirano vicino alla Depressione di Rovoaguzzo e al suo interno, a est di Campo Narache, sul margine orientale della Mesa Nuvola Rossa.",al={"posizione dei cinghiali da battaglia","dove sono i cinghiali da battaglia","cinghiali della depressione di rovoaguzzo"}},{q="Cosa succede alla carne raccolta dai cinghiali?",a="I fianchi e i musi dei Battleboars vengono riportati a Campo Narache per preparare lo stufato destinato ai bambini e agli anziani dell'insediamento. I tauren usano tutto ciò che cacciano.",al={"uso dei fianchi di cinghiale","a cosa serve la carne di cinghiale","stufato di cinghiale"}},{q="Come si inserisce questa missione nel conflitto locale con i quillboar?",a="La caccia introduce la guerra aperta tra i tauren e la tribù Bristleback. Abbattere i loro animali da guerra riduce il numero delle bestie che tormentano i territori di caccia tauren e invia un messaggio chiaro ai Bristleback della Depressione di Rovoaguzzo.",al={"guerra tra tauren e quillboar","conflitto con i bristleback","storia dei quillboar"}},{q="Quale missione precede The Battleboars?",a="The Hunt Continues viene prima. Grull Vento Agile manda i giovani cacciatori a conoscere i territori di caccia della Mesa Nuvola Rossa.",al={"prerequisito di the battleboars","missione precedente di the battleboars","catena di the hunt continues"}}},fx={b70ec92c={q="Perché Grull Vento Agile vuole che i cinghiali da guerra vengano uccisi?",a="I cinghiali da guerra sono usciti dalla Depressione di Rovoaguzzo e si sono spinti nei terreni di caccia ancestrali della tribù Nuvola Rossa. Allevati e addestrati alla ferocia dai quilboar Spinepungenti, con la loro crescente aggressività minacciano direttamente Campo Narache. Grull Vento Agile intende mandare un chiaro messaggio ai quilboar decimando le loro bestie da guerra e trasformando la caccia in cibo per i giovani della tribù.",al={"perché grull vento agile vuole morti i cinghiali da guerra","motivo di grull vento agile per i cinghiali da guerra","perché uccidere i cinghiali da guerra a mulgore"}},["58a19c3f"]={q="Cosa sono i cinghiali da guerra?",a="I cinghiali da guerra sono bestie feroci allevate e addestrate dai quilboar Spinepungenti della Depressione di Rovoaguzzo. A differenza dei puma montani selvatici e dei corridori delle pianure originari della Mesa Nuvola Rossa, questi cinghiali vengono deliberatamente preparati alla guerra e alla crudeltà e usati come armi viventi nella lotta continua degli Spinepungenti contro i tauren.",al={"chi sono i cinghiali da guerra","cosa sono i cinghiali da guerra","storia dei cinghiali da guerra"}}},fp="15,95,22.329.0,17.340.0,43.182.0,31.117.0,32.113.0,50.140.0,57.224.0,36.114.0"}
P.entries["quest:7802"] = {n="A Donation of Wool",s="A Forgiardente, le donazioni di Tessuto di Lana aiutano a rifornire le sue scorte. Sessanta pezzi ti faranno ottenere pieno riconoscimento per la tua generosità.",h="A Forgiardente, le donazioni di Tessuto di Lana aiutano a rifornire le sue scorte.",kw={"donazione","forgiardente","riconoscimento","sessanta pezzi","scorte","lana","tessuto di lana"},ang={["faction:Alliance"]="In quanto viaggiatore dell'Alleanza, la tua donazione di Tessuto di Lana ti farà guadagnare il riconoscimento di Forgiardente."},sec={{t="Scorte di lana",b="Forgiardente ti chiede sessanta pezzi di Tessuto di Lana. Per le sue scorte le basta questa quantità. Ci si aspetta che gli altri donino abbastanza da sostenere la raccolta."}},faq={{q="Quanta lana serve a Forgiardente?",a="Sessanta pezzi di Tessuto di Lana, per Forgiardente.",al={"quantità donazione lana","quanta lana","sessanta pezzi di lana"}},{q="Cosa ottengo donando lana?",a="Dona a Forgiardente sessanta pezzi di Tessuto di Lana e otterrai pieno riconoscimento per la tua generosità.",al={"ricompensa donazione lana","cosa si ottiene per la lana","riconoscimento forgiardente"}},{q="Perché Forgiardente raccoglie lana?",a="Forgiardente raccoglie Tessuto di Lana per rifornire le sue scorte.",al={"raccolta di lana","perché donare lana","lana forgiardente"}}},fp="18,110,11.148.0,42.42.0,32.93.0,33.51.0"}
P.entries["quest:7807"] = {n="A Donation of Wool",s="In tutto il regno, A Donation of Wool chiede aiuto per gli Esuli di Gnomeregan. Scacciati da Gnomeregan, hanno bisogno di Tessuto di Lana per sostenere il loro popolo disperso. Sessanta pezzi ti fanno ottenere un riconoscimento ufficiale tra gli gnomi.",h="In tutto il regno, A Donation of Wool chiede aiuto per gli Esuli di Gnomeregan.",kw={"raccolta di stoffa","a donation of wool","gnomo","gnomeregan","esuli di gnomeregan","tessili","tessuto di lana"},ang={["faction:Alliance"]="Contribuire con materie prime rafforza la solidarietà dell'Alleanza e aiuta a sostenere un alleato fondamentale, costretto a lasciare la propria dimora montana.",["profession:Tailoring"]="I sarti che raccolgono o tessono Tessuto di Lana hanno a disposizione molti tessuti di cui i profughi hanno bisogno per abiti e forniture di base.",["race:Gnome"]="Per gli gnomi esuli, raccogliere lana aiuta a rifornire i tuoi parenti dispersi mentre sopravvivono e ricostruiscono la loro vita fuori da Gnomeregan."},sec={{t="I bisogni di un popolo in esilio",b="La caduta di Gnomeregan per mano degli invasori trogg e la contaminazione radioattiva costrinsero gli gnomi sopravvissuti a fuggire dalla loro città tecnologica. Ora vivono da profughi, ospitati soprattutto dai loro cugini nani a Forgiardente.\n\nLontano dalle loro sale ancestrali, gli Esuli di Gnomeregan faticano a rifornire il proprio popolo. Le raccolte regolari di tessuti e altri beni essenziali li aiutano a mantenersi vestiti, riforniti e organizzati."},{t="La raccolta tessile",b="La raccolta chiede a ogni volontario esattamente sessanta pezzi di Tessuto di Lana. Raccogliendo modesti contributi da tutto il regno, gli esuli possono procurarsi i tessuti necessari per lenzuola, bende e abiti senza gravare troppo su un singolo fornitore. Chi li aiuta a riprendersi riceve un riconoscimento ufficiale dal loro popolo."}},faq={{q="Perché gli Esuli di Gnomeregan hanno bisogno di Tessuto di Lana?",a="Gli Esuli di Gnomeregan stanno raccogliendo materiali tessili di prima necessità. Scacciati dalla loro città natale, i profughi hanno bisogno di Tessuto di Lana per sostenere il loro popolo e le attività quotidiane.",al={"perché la lana","a cosa serve la lana","scopo della donazione di lana"}},{q="Quanto Tessuto di Lana serve?",a="La raccolta chiede a ogni donatore sessanta pezzi di Tessuto di Lana. Gli organizzatori contano sui contributi da tutto il regno per soddisfare il loro fabbisogno.",al={"quanta lana","quantità della donazione","lana richiesta"}},{q="Chi sta organizzando questa raccolta di donazioni?",a="I rappresentanti degli Esuli di Gnomeregan organizzano la raccolta e ricevono le donazioni per gli gnomi dispersi che trovano rifugio tra i loro alleati.",al={"chi prende la donazione","chi accetta la lana","destinatario della donazione"}},{q="Puoi donare Tessuto di Lana più di una volta?",a="A ogni donatore viene chiesto un contributo di sessanta pezzi. Gli esuli hanno bisogno di quella quantità da parte tua e contano sui donatori di tutto il regno per raggiungere la quota.",al={"posso donare ancora","è ripetibile","altre donazioni di lana"}},{q="Che tipo di riconoscimento offrono gli Esuli di Gnomeregan?",a="Donare sessanta pezzi ti fa guadagnare il riconoscimento e la gratitudine degli Esuli di Gnomeregan. Dimostra la tua lealtà e il tuo sostegno al loro popolo disperso in un momento di crisi.",al={"reputazione esuli di gnomeregan","reputazione gnomi","riconoscimento esuli"}},{q="Perché gli gnomi sono attualmente in esilio?",a="Gli gnomi fuggirono dalla loro dimora sotterranea a Gnomeregan dopo una catastrofe e l'invasione dei trogg. Da profughi, dipendono da accampamenti temporanei, dagli aiuti degli alleati e dalle raccolte di materiali.",al={"perché gli gnomi sono in esilio","dov'è gnomeregan","crisi dei profughi gnomi"}}},fp="18,211,26.391.0,17.324.0,45.176.0,30.151.0,38.142.0,41.163.0,48.163.0,38.192.0"}
P.entries["quest:781"] = {n="Attack on Camp Narache",s="Al Campo Narache, porti un avvertimento che può dare ai tauren il tempo di chiedere aiuto. I quilboar Mantotergo preparano un assedio e Capo Vento Agile deve saperlo.",h="Al Campo Narache, porti un avvertimento che può dare ai tauren il tempo di chiedere aiuto.",kw={"piani d'attacco","villaggio di zoccolo sanguinario","depressione di rovoaguzzo","mantotergo","campo narache","capo vento agile","mappa sporca di terra","quilboar","mesa nuvola rossa"},ang={["faction:Horde"]="Proteggendo la presenza dei tauren a Mulgore, aiuti l'Orda a mantenere il suo vitale baluardo meridionale nel cuore di Kalimdor.",["race:Tauren"]="Da giovane guerriero tauren, all'inizio dei tuoi primi riti sulla mesa, dimostri la tua lealtà intercettando la mappa e proteggendo la tua gente da un massacro improvviso."},sec={{t="Un complotto tra i rovi",b="Nella Depressione di Rovoaguzzo, trovi una rozza mappa sul pavimento della caverna. I segni macchiati di terra rivelano che i quilboar Mantotergo pianificano un lungo assedio al Campo Narache. Non si tratta di una serie di attacchi isolati."},{t="Avvertire il Capo",b="Porti i piani d'attacco a Capo Vento Agile al Campo Narache. Pochi difensori sorvegliano il campo, che ospita giovani iniziati, così Vento Agile si prepara a mandare un messaggio al Villaggio di Zoccolo Sanguinario per chiedere rinforzi. Grazie al tuo avvertimento, il campo ha il tempo di prepararsi all'assedio."}},faq={{q="Dove si trovano i piani d'attacco dei Mantotergo?",a="I piani dei Mantotergo sono segnati su una mappa macchiata di terra, dentro una grotta nella Depressione di Rovoaguzzo. La grotta si trova poco più avanti, lungo il sentiero a destra della capanna di Chief Sharptusk.",al={"posizione mappa","dove si trova la mappa sporca di terra","trovare i piani"}},{q="Chi riceve i piani d'attacco dei Mantotergo?",a="Capo Vento Agile riceve i piani d'attacco dei Mantotergo al centro del Campo Narache.",al={"a chi consegnare","chi riceve la mappa","consegna missione"}},{q="Perché i quilboar Mantotergo prendono di mira Campo Narache?",a="La tribù dei Mantotergo vuole scacciare i tauren dalla Mesa Nuvola Rossa e reclamare per la propria gente le terre di caccia e le pianure sacre di Mulgore.",al={"perché attaccare campo narache","motivi dei quilboar mulgore","assedio dei mantotergo"}},{q="Come intende contrastare l'assedio il Capo Vento Agile?",a="Avvertito dalla mappa, Capo Vento Agile intende chiedere aiuto ai loro fratelli del Villaggio di Zoccolo Sanguinario per rinforzare la mesa e respingere l'assalto.",al={"piano di vento agile","rinforzi campo narache"}},{q="Questa missione richiede di parlare con qualcuno prima di raccogliere la mappa?",a="No. Trovi la Dirt-stained Map sul pavimento di una grotta nella Depressione di Rovoaguzzo. Una volta recuperata, diventa il piano di battaglia.",al={"inizio missione","mappa sporca di terra inizio","come iniziare attack on camp narache"}},{q="Cosa succede se Campo Narache cade?",a="Il Campo Narache è il principale rifugio per i giovani guerrieri tauren e i loro riti di passaggio. La sua perdita minaccerebbe la sicurezza della Mesa Nuvola Rossa e interromperebbe i luoghi sacri d'addestramento di Mulgore.",al={"rischi di campo narache","perché difendere narache"}}},fp="22,166,22.212.0,21.257.0,45.146.0,42.83.0,56.143.0,50.133.0,69.125.0,35.180.0"}
P.entries["quest:7810"] = {n="Signore dell'Arena",s="Nell'Arena di Rovotorto, Short John Mithril potrebbe sapere cos'altro serve per padroneggiarne le gare.",h="Nell'Arena di Rovotorto, Short John Mithril potrebbe sapere cos'altro serve per padroneggiarne le gare.",kw={"maestro dell'arena","gurubashi","pirata","short john mithril","arena di rovotorto","valle di rovotorto"},sec={{t="Alla ricerca del pirata",b="Hai ottenuto qualcosa a Gurubashi, ma per padroneggiare l'arena serve altro. Short John Mithril organizza le gare e potrebbe sapere cosa occorre. Trovalo all'interno dell'Arena di Rovotorto."},{t="La parola di Short John",b="Short John Mithril ti dice che un solo ninnolo non basta per padroneggiare l'arena. Ora comincia la vera prova del tuo valore."}},faq={{q="Con chi devo parlare?",a="Parla con Short John Mithril, il pirata dietro l'evento di Gurubashi.",al={"con chi parlo","consegna maestro dell'arena","dove andare"}},{q="Dove si trova Short John Mithril?",a="Trova Short John Mithril nell'Arena di Rovotorto a Gurubashi, nella Valle di Rovotorto.",al={"posizione gurubashi","dove si trova arena di rovotorto","posizione arena"}},{q="Cosa si dice riguardo al diventare maestri dell'arena?",a="Hai fatto qualcosa a Gurubashi, ma padroneggiare l'arena sembra richiedere di più. Short John Mithril, il pirata dietro l'evento, potrebbe sapere cosa occorre.",al={"come diventare maestro dell'arena","sono già maestro dell'arena"}}},fp="12,98,18.190.0,17.123.1,28.69.0,28.86.0,47.158.0"}
P.entries["quest:78124"] = {n="Nar'thalas Almanac",s="Gli studiosi cercano il Nar'thalas Almanac per preservare gli antichi studi magici. Il suo recupero porta conoscenze dimenticate in una biblioteca, dove i ricercatori possono studiarle.",h="Gli studiosi cercano il Nar'thalas Almanac per preservare gli antichi studi magici.",kw={"almanacco","arcano","libro","biblioteca","opere magiche","nar'thalas","narthalas","tomo"},ang={["class:Mage"]="Come mago, conosci il valore accademico dei testi sulle antiche tradizioni arcane. Aggiungere opere recuperate alla collezione magica di una biblioteca è molto importante.",["faction:Alliance"]="Come avventuriero dell'Alleanza, puoi aiutare studiosi e curatori degli archivi dell'Alleanza a cercare manoscritti rari e ad ampliare le conoscenze raccolte nel regno.",["race:NightElf"]="Come Elfo della Notte, conosci Nar'thalas come antico centro degli studi arcani Kaldorei, prima che il Grangorgo sconvolgesse il vecchio mondo. Un almanacco che porta quel nome ti lega all'antica storia degli elfi della notte."},sec={{t="Una reliquia di studi antichi",b="Il Nar'thalas Almanac è una rara opera di studi arcani, radicata nelle antiche tradizioni erudite degli elfi della notte, risalenti a prima del Grangorgo. Per i custodi dei grandi archivi, assicurarsi il volume significa salvare dall'oblio conoscenze secolari e aggiungere un importante tassello di storia ai propri scaffali. Chi porta alla luce opere trascurate contribuisce a colmare il divario tra l'antichità dimenticata e gli studi moderni."},{t="Espansione degli archivi",b="In tutta Azeroth, archivisti e ricercatori cercano trattati, appunti di campo e cronache perdute. Portare il Nar'thalas Almanac in una biblioteca dedicata permette ai suoi custodi di salvaguardarlo, catalogarlo e studiarlo, invece di lasciarlo marcire tra le rovine o finire in mani negligenti. Ogni volume recuperato offre nuovi spunti sulle arti arcane delle epoche passate."}},faq={{q="Cos'è il Nar'thalas Almanac?",a="Il Nar'thalas Almanac è un raro manoscritto antico di studi magici, ricercato dai curatori per i loro archivi storici. Chi lo recupera affida le sue conoscenze alle cure degli studiosi, che possono preservarlo e catalogarlo.",al={"cos'è il narthalas almanac","missione narthalas almanac","informazioni sull'almanacco"}},{q="Chi sta collezionando il Nar'thalas Almanac?",a="Gli studiosi di biblioteca interessati agli antichi testi magici e agli archivi storici collezionano l'almanacco. I curatori cercano attivamente nuove opere per ampliare la conoscenza condivisa del patrimonio arcano del mondo.",al={"chi vuole l'almanacco","dove finisce l'almanacco","consegna almanacco"}},{q="A cosa si riferisce il nome Nar'thalas?",a="Nar'thalas era un antico centro Kaldorei di apprendimento e studi magici prima del Great Sundering. I testi che portano il suo nome conservano frammenti delle arti arcane e delle conoscenze elfiche precedenti al Grangorgo.",al={"cos'è narthalas","tradizioni di narthalas","dove si trova narthalas"}},{q="Perché i testi magici vengono collezionati per la biblioteca?",a="Documenti storici e trattati magici furono dispersi, perduti o sepolti tra le rovine di Azeroth. Gli studiosi esaminano gli scritti recuperati per ampliare la loro comprensione delle correnti arcane e impedire che documenti fragili vadano perduti per sempre.",al={"perché collezionare opere magiche","scopo della biblioteca","perché i libri sono importanti"}},{q="Si possono portare altre opere magiche in biblioteca?",a="Trattati, tomi e manoscritti dimenticati possono far luce sulla teoria arcana e sulla storia antica. Gli studiosi cercano continuamente nuove opere per arricchire i propri scaffali.",al={"altri libri magici","altri tomi","altri testi"}},{q="Il Nar'thalas Almanac è pericoloso da maneggiare?",a="L'almanacco è una raccolta di studi, non un artefatto proibito e instabile. Storici e praticanti possono usarlo come preziosa fonte di riferimento sulla magia del passato.",al={"l'almanacco è pericoloso","l'almanacco contiene magia oscura","è sicuro da leggere"}}},fp="18,153,24.370.0,22.342.0,31.226.0,41.195.0,39.191.0,54.236.0,50.157.0,46.162.0"}
P.entries["quest:78127"] = {n="The Dalaran Digest",s="Il bibliotecario ti chiede di portare opere magiche per la collezione. Ogni libro aggiunge conoscenze alla biblioteca.",h="Il bibliotecario ti chiede di portare opere magiche per la collezione.",kw={"collezione","compendio di dalaran","conoscenze","bibliotecario","biblioteca","opere magiche"},sec={{t="La collezione",b="Il bibliotecario accoglie opere magiche che potrebbero giovare alla biblioteca. Porti un libro da aggiungere alla collezione, contribuendo ad accrescerne le conoscenze."}},faq={{q="Che cosa vuole il bibliotecario?",a="Il bibliotecario ti chiede di portare opere magiche che potrebbero giovare alla collezione.",al={"cosa portare","libro della biblioteca","opere magiche"}},{q="Dove porto il libro?",a="Porta il libro al bibliotecario che ti ha chiesto di aggiungerlo alla collezione.",al={"dov'è il bibliotecario","ubicazione della biblioteca"}},{q="Perché il bibliotecario raccoglie opere magiche?",a="Il tuo contributo arricchisce la collezione di nuove conoscenze.",al={"perché raccogliere libri","scopo della biblioteca"}}},fp="18,106,14.135.0,29.78.0,26.74.0,46.58.0"}
P.entries["quest:78142"] = {n="Bewitchments and Glamours",s="A Forgiardente, la biblioteca cerca opere magiche da aggiungere ai suoi scaffali. Puoi aiutare i suoi custodi ad ampliare le loro conoscenze portando libri che potrebbero arricchire la collezione.",h="A Forgiardente, la biblioteca cerca opere magiche da aggiungere ai suoi scaffali.",kw={"incantesimi e illusioni","libri","collezione","forgiardente","biblioteca","opere magiche"},sec={{t="Una collezione in crescita",b="Porta opere magiche alla biblioteca di Forgiardente: ogni nuova aggiunta può ampliare le conoscenze dei suoi custodi."}},faq={{q="Cosa vuole la biblioteca?",a="La biblioteca cerca opere magiche che potrebbero arricchire la sua collezione.",al={"cosa vogliono","libri della biblioteca","opere magiche"}},{q="Dove porto le opere magiche?",a="Porta le opere magiche alla biblioteca.",al={"dove portare i libri","dov'è la biblioteca","biblioteca di forgiardente"}},{q="Perché collezionano opere magiche?",a="La biblioteca dice che le opere ne amplieranno il sapere.",al={"perché collezionare libri di magia","a cosa serve la collezione"}}},fp="25,168,20.103.0,27.64.0,35.39.0,38.53.0"}
P.entries["quest:78143"] = {n="Secrets of the Dreamers",s="Gli studiosi di una biblioteca cercano scritti legati ai Dreamers e ad altre tradizioni magiche. I viaggiatori portano opere dimenticate da ogni parte del regno, perché siano studiate e conservate negli archivi.",h="Gli studiosi di una biblioteca cercano scritti legati ai Dreamers e ad altre tradizioni magiche.",kw={"arcano","sognatori","biblioteca","opere magiche","studiosi","secrets of the dreamers","tomi"},ang={["class:Druid"]="Se sei un druido, gli scritti legati alla magia della natura e al Sogno di Smeraldo hanno un profondo significato nelle arti Cenarion.",["class:Mage"]="Se sei un mago, puoi cercare tomi poco conosciuti e testi magici per arricchire gli archivi accademici.",["faction:Alliance"]="Gli studiosi dell'Alleanza, soprattutto quelli che custodiscono grandi raccolte, dipendono dai campioni per recuperare conoscenze perdute in luoghi pericolosi."},sec={{t="Recuperare il sapere dimenticato",b="Gli studiosi di tutto il regno dipendono dai viaggiatori per recuperare rari testi magici e trattati storici. Queste opere si trovano in antiche rovine o collezioni private, lontano dagli archivi. Perciò gli avventurieri le trasportano al sicuro a chi studia i misteri arcani di Azeroth e ne preserva il sapere."},{t="Espandere gli archivi",b="Quando i viaggiatori consegnano i trattati, gli archivisti li aggiungono alla collezione permanente della biblioteca. I ricercatori cercano scritti poco conosciuti sul Sogno di Smeraldo e sulla teoria arcana. Il loro lavoro prosegue e accolgono volentieri altri testi magici trovati sul campo."}},faq={{q="Qual è lo scopo della missione Secrets of the Dreamers?",a="I viaggiatori recuperano scritti magici e conoscenze poco note, poi li portano agli studiosi di una biblioteca per arricchirne gli archivi.",al={"cosa è secrets of the dreamers","missione secrets of dreamers","cosa si fa in questa missione"}},{q="Chi colleziona questi testi magici?",a="Uno studioso che sovrintende alla collezione di una biblioteca raccoglie i testi e chiede ai viaggiatori di portargli opere magiche.",al={"chi vuole secrets of the dreamers","chi assegna questa missione","dove consegnare secrets of the dreamers"}},{q="Dove vengono conservate le opere recuperate?",a="Gli scritti entrano negli archivi in crescita di una biblioteca istituzionale, dove gli studiosi e i ricercatori dell'Alleanza possono catalogare e preservare rare conoscenze e scoperte magiche.",al={"cosa è la collezione","per quale biblioteca è","dove vanno i libri"}},{q="A cosa si riferisce il titolo con \"i Sognatori\"?",a="I Dreamers indica i druidi in sintonia con il Sogno di Smeraldo o antiche entità dormienti legate al sonno della natura. Gli scritti che ne custodiscono i segreti preservano un misterioso potere primordiale.",al={"chi sono i sognatori","sapere sui sognatori","perché si chiama sognatori"}},{q="È possibile portare altre opere magiche dopo aver terminato la missione?",a="Gli archivisti accolgono volentieri altri contributi. Quando trovi scritti magici che potrebbero arricchire la collezione, puoi portarli perché proseguano le ricerche.",al={"posso consegnare altri libri","è ripetibile","altre opere magiche"}},{q="Perché raccogliere questi scritti magici è importante per gli studiosi?",a="Gli studiosi cercano di ampliare la propria comprensione delle tradizioni arcane, naturali e poco conosciute. Trattati perduti o dispersi potrebbero contenere indizi sulla storia più remota e sui misteri del mondo.",al={"perché raccogliere libri magici","perché la biblioteca ha bisogno di tomi magici"}}},fp="23,186,25.278.0,22.248.0,57.121.0,33.106.0,37.165.0,47.179.0,59.151.0,63.173.0"}
P.entries["quest:78145"] = {n="Arcanic Systems Manual",s="Il Arcanic Systems Manual è un'opera magica ricercata per la collezione di una biblioteca. Aggiungerla aiuta la biblioteca ad ampliare le sue conoscenze.",h="Il Arcanic Systems Manual è un'opera magica ricercata per la collezione di una biblioteca.",kw={"arcanico","arcanic systems manual","collezione","forgiardente","biblioteca","opere magiche","manuale"},sec={{t="Un posto in biblioteca",b="La biblioteca accoglie opere magiche che possono arricchire la sua collezione. Ne porti una da aggiungere e il tuo contributo aiuta a far crescere le sue conoscenze."}},faq={{q="Che cos'è l'Arcanic Systems Manual?",a="È un'opera magica ricercata per la collezione di una biblioteca.",al={"manuale arcanico","quale manuale"}},{q="Chi vuole il manuale?",a="Un bibliotecario ti chiede di portare opere magiche che possano arricchire la collezione.",al={"chi l'ha chiesto","manuale per chi"}},{q="Perché portare il manuale in biblioteca?",a="Le conoscenze della biblioteca crescono grazie alle opere magiche donate.",al={"perché donarlo","a cosa serve"}}},fp="22,129,22.137.0,35.55.0,21.76.0,36.69.0"}
P.entries["quest:78146"] = {n="Goaz Scrolls",s="Il bibliotecario ti chiede di portare i Goaz Scrolls per la collezione. Il tuo contributo arricchisce il sapere della biblioteca.",h="Il bibliotecario ti chiede di portare i Goaz Scrolls per la collezione.",kw={"collezione","goaz scrolls","sapere","biblioteca","opere magiche","pergamene"},sec={{t="Una collezione in crescita",b="Il bibliotecario ti ringrazia per aver contribuito con i Goaz Scrolls. Anche altre opere magiche potrebbero aiutare la biblioteca, che sarà lieta di accoglierle."}},faq={{q="A cosa servono i Goaz Scrolls?",a="I Goaz Scrolls arricchiscono la collezione e il sapere della biblioteca.",al={"scopo dei goaz scrolls","perché portare pergamene","pergamene per la biblioteca"}},{q="Chi ti chiede i Goaz Scrolls?",a="Un bibliotecario ti chiede di portare i Goaz Scrolls per la collezione.",al={"chi vuole i goaz scrolls","chi riceve le pergamene","persona della biblioteca"}},{q="Dove finiranno le pergamene?",a="I Goaz Scrolls sono destinati alla collezione della biblioteca.",al={"dove portare le pergamene","luogo dei goaz scrolls","pergamene della biblioteca"}},{q="Cos'altro potrebbe giovare alla biblioteca?",a="Il bibliotecario accoglie volentieri altre opere magiche che potrebbero giovare alla biblioteca.",al={"altre opere magiche","altri libri per la biblioteca","cos'altro portare"}}},fp="12,117,20.135.0,26.61.0,30.62.0,28.52.0,36.74.0"}
P.entries["quest:78147"] = {n="Crimes Against Anatomy",s="Un bibliotecario ti chiede di aggiungere opere magiche alla collezione di una biblioteca. Le tue scoperte contribuiscono ad ampliare le conoscenze della biblioteca.",h="Un bibliotecario ti chiede di aggiungere opere magiche alla collezione di una biblioteca.",kw={"raccolta","crimini contro l'anatomia","forgiardente","bibliotecario","biblioteca","opere magiche"},sec={{t="Per la raccolta",b="Qualsiasi opera magica utile alla biblioteca è benvenuta. Puoi portare le tue scoperte al bibliotecario, che amplia le proprie conoscenze grazie a questi contributi. Altre opere potrebbero ancora rivelarsi utili alla biblioteca."}},faq={{q="Chi chiede opere magiche?",a="Un bibliotecario ti chiede di portargli opere magiche che potrebbero arricchire la collezione.",al={"chi vuole libri","richiesta della biblioteca"}},{q="Dove porto le opere?",a="Portale al bibliotecario. I bibliotecari raccolgono queste opere a Roccavento e a Sepulcra.",al={"dov'è la biblioteca","dove portare i libri"}},{q="Perché raccogliere opere magiche?",a="Le opere contribuiscono ad ampliare le conoscenze della biblioteca.",al={"perché i libri","a cosa servono le opere magiche"}}},fp="22,124,18.204.0,27.78.0,27.92.0,26.48.0"}
P.entries["quest:78148"] = {n="Runes of the Sorcerer-Kings",s="Una biblioteca accoglie opere magiche nella propria collezione. Le tue scoperte contribuiscono ad ampliarne il sapere.",h="Una biblioteca accoglie opere magiche nella propria collezione.",kw={"collezione","forgiardente","conoscenze","biblioteca","opere magiche","rune","re-stregoni"},sec={{t="La collezione",b="Il custode della biblioteca ti ringrazia mentre la collezione cresce grazie ai tuoi sforzi. Altre opere magiche possono arricchirne le conoscenze, e il custode le accoglie volentieri per la biblioteca."}},faq={{q="Cosa vuole la biblioteca?",a="La biblioteca accoglie opere magiche che possono arricchire la sua collezione.",al={"cosa vogliono","libri della biblioteca","opere magiche"}},{q="Dov'è la biblioteca?",a="I bibliotecari raccolgono opere di questo tipo a Roccavento e a Sepulcra.",al={"posizione della biblioteca","dov'è la biblioteca","biblioteca di forgiaardente"}},{q="Perché portare opere magiche?",a="I tuoi sforzi ampliano le conoscenze della biblioteca.",al={"perché i libri","a che scopo","aiutare la biblioteca"}}},fp="27,96,14.168.0,27.67.0,21.63.0,24.44.0"}
P.entries["quest:78149"] = {n="Fury of the Land",s="Una biblioteca cerca opere magiche per la sua collezione. Ciò che trovi contribuisce ad ampliare le sue conoscenze.",h="Una biblioteca cerca opere magiche per la sua collezione.",kw={"collezione","furore della terra","forgiardente","conoscenza","biblioteca","opere magiche"},sec={{t="Un luogo di conoscenza",b="Un bibliotecario ti chiede se hai portato qualcosa da aggiungere alla collezione. Accoglie con piacere ciò che hai trovato e ti invita a portargli altro, se ne scopri."}},faq={{q="Cosa vuole la biblioteca?",a="La Biblioteca cerca opere magiche che possano arricchire la sua collezione.",al={"di cosa hanno bisogno","libri della biblioteca","opere magiche"}},{q="Dove devo portare le opere magiche?",a="Portali al bibliotecario. I bibliotecari raccolgono opere simili a Roccavento e a Sepulcra.",al={"dove portare i libri","posizione della biblioteca","portare opere"}},{q="Perché raccolgono opere magiche?",a="Il bibliotecario dice che ogni contributo amplia le loro conoscenze.",al={"perché raccogliere libri di magia","collezione della biblioteca","a cosa serve"}}},fp="16,90,21.153.0,27.64.0,35.92.0,38.61.0"}
P.entries["quest:7815"] = {n="Snapjaws, Mon!",s="Nel Villaggio degli Zannatorta, Katoom il Pescatore ti chiede di occuparti degli azzannatori d'acqua salata che rovinano la sua pesca. Vuole che vengano uccise quindici tartarughe.",h="Nel Villaggio degli Zannatorta, Katoom il Pescatore ti chiede di occuparti degli azzannatori d'acqua salata...",kw={"pescatore","esca","pesca","entroterre","katoom","revantusk","azzannatori","tartarughe"},sec={{t="Guai con la lenza",b="Katoom il Pescatore ti chiede di aiutare lui e i suoi vicini nel Villaggio degli Zannatorta. Gli azzannatori d'acqua salata possono sembrare innocui, ma rendono difficile pescare. Uno gli strappa la lenza e gli ruba l'esca prima che riesca a pescare per cinque minuti. Katoom vuole che tu uccida quindici di queste tartarughe."}},faq={{q="Chi ti chiede di cacciare le tartarughe?",a="Katoom il Pescatore, un pescatore del Villaggio degli Zannatorta nelle Entroterre, ti chiede di cacciare le tartarughe.",al={"chi assegna snapjaws mon","datore missione snapjaws mon","katoom il pescatore"}},{q="Perché Katoom vuole che gli azzannatori d'acqua salata vengano uccisi?",a="Katoom dice che gli azzannatori d'acqua salata gli strappano la lenza e gli rubano l'esca. Riesce a pescare a malapena per cinque minuti prima che uno lo interrompa.",al={"perché uccidere gli azzannatori","fastidio tartarughe","perché uccidere tartarughe revantusk"}},{q="Quanti azzannatori devono essere uccisi?",a="Devi uccidere quindici tartarughe della specie degli azzannatori d'acqua salata.",al={"quante tartarughe","conteggio azzannatori","conteggio snapjaws mon"}}},fp="14,134,19.270.0,33.98.0,51.141.0,35.51.0"}
P.entries["quest:7816"] = {n="Gammerita, Mon!",s="Al Villaggio degli Zannatorta, Katoom il Pescatore vuole riavere la sua esca migliore da Gammerita, Mon!, capo delle testuggini azzannatrici d'acqua salata. Trovala e recuperala.",h="Al Villaggio degli Zannatorta, Katoom il Pescatore vuole riavere la sua esca migliore da Gammerita, Mon!...",kw={"pescatore","gammerita","entroterre","katoom","esca","zannatorta","azzannatrice","testuggine"},sec={{t="Una ladra tra le testuggini",b="Katoom dice che Gammerita, Mon! non è una testuggine qualunque. È a capo delle testuggini azzannatrici d'acqua salata, e lui la definisce una ladra. Gli ha strappato dalla lenza la sua esca migliore. Da allora i pesci non abboccano più come una volta."},{t="Recuperare l'esca",b="Katoom vuole che tu trovi Gammerita, Mon! e recuperi l'esca dal suo stomaco. Se ne sta lungo la costa, in mezzo alle altre testuggini."},{t="Le speranze di Katoom",b="Con l'esca di nuovo in mano e qualche azzannatrice in meno in giro, Katoom si aspetta che i pesci tornino ad abboccare a bizzeffe."}},faq={{q="Chi è Katoom il Pescatore?",a="Katoom il Pescatore pesca al Villaggio degli Zannatorta, nelle Entroterre. Ti chiede di dare la caccia a Gammerita, Mon!.",al={"chi è katoom","katoom zannatorta","posizione katoom"}},{q="Cos'è Gammerita?",a="Gammerita, Mon! non è una testuggine qualunque. È a capo delle testuggini azzannatrici d'acqua salata, e Katoom la definisce una ladra.",al={"chi è gammerita","cos'è gammerita","testuggine gammerita"}},{q="Perché Katoom vuole morta Gammerita?",a="Gammerita, Mon! ha strappato dalla lenza di Katoom la sua esca migliore, e da allora i pesci non abboccano più come una volta. Lui vuole recuperarla dal suo stomaco.",al={"perché uccidere gammerita","cosa ha rubato gammerita","motivo di katoom"}},{q="Dove si può trovare Gammerita?",a="Gammerita, Mon! se ne sta sulla costa, in mezzo alle altre testuggini azzannatrici d'acqua salata.",al={"dov'è gammerita","posizione gammerita","trova gammerita"}}},fp="15,145,25.205.0,21.130.0,14.92.1,25.96.0,18.96.0,36.132.0,29.71.0"}
P.entries["quest:782"] = {n="Broken Alliances",s="Gorn ti manda da Kargath a riprendere ciò che hanno preso gli ogre. Vuole riscattare l’onore dell’Orda dopo l’alleanza con Alamorte. Il boss Tho'grun, ingaggiato per trovare il Simbolo della Terra, ha tradito l’Orda e se l’è tenuto.",h="Gorn ti manda da Kargath a riprendere ciò che hanno preso gli ogre.",kw={"maleterre","blacklash","campo boff","alamorte","gorn","hematus","kargath","piana di lethlor","simbolo della terra","tho'grun"},sec={{t="Una banda di mercenari traditori",b="Durante la Seconda Guerra, l’Orda combatté al fianco di Alamorte. I suoi luogotenenti Blacklash e Hematus furono poi imprigionati molto a est, nella Piana di Lethlor. Gorn crede che questi vecchi e depravati alleati debbano essere messi a tacere per riscattare l’onore dell’Orda.\n\nL’Orda aveva bisogno del Simbolo della Terra per aprire la prigione dei draghi, così assunse mercenari ogre guidati dal boss Tho'grun perché trovassero il simbolo. Tho'grun si ribellò all’Orda, sopraffece le sue forze e se lo tenne."},{t="Campo Boff",b="Gorn ti manda a sud-est di Kargath, a Campo Boff. Uccidi Tho'grun e riportagli il Simbolo della Terra. Gorn sarà felice di sapere che Tho'grun è morto. Gli ogre non fanno più parte dell’Orda."},{t="Cosa apre il Simbolo",b="Gorn si aspetta che gli ogre cadano nel disordine dopo la morte di Tho'grun. Sarà una piccola vittoria, che potrebbe portarne una più grande.\n\nCon il Simbolo della Terra nelle mani dell’Orda, si potrà aprire la prigione dei draghi neri nella Piana di Lethlor. Saranno liberati da una prigionia senza fine, solo per andare incontro al loro destino."}},faq={{q="Chi è Gorn?",a="Gorn è una figura dell’Orda a Kargath, e ti manda a cercare il Simbolo della Terra. Vuole riscattare l’onore dell’Orda mettendo a tacere i suoi depravati alleati di un tempo.",al={"chi assegna alleanze spezzate","gorn kargath","lore di gorn"}},{q="Perché Gorn vuole morto il boss Tho'grun?",a="L’Orda assunse il boss Tho'grun e i suoi mercenari ogre per ottenere il Simbolo della Terra. Tho'grun li tradì, li sopraffece e si tenne il simbolo.",al={"perché uccidere thogrun","tradimento di thogrun","lore del boss thogrun"}},{q="Dov'è Campo Boff?",a="Campo Boff si trova a sud-est di Kargath.",al={"posizione campo boff","dove si trova thogrun","trovare il boss thogrun"}},{q="A cosa serve il Simbolo della Terra?",a="Il Simbolo della Terra è una chiave necessaria per aprire la prigione dei draghi nella Piana di Lethlor.",al={"simbolo della terra","a cosa serve il simbolo della terra"}},{q="Quali draghi sono imprigionati nella Piana di Lethlor?",a="Blacklash e Hematus sono due luogotenenti di Alamorte. Furono imprigionati nella Piana di Lethlor dopo che l’Orda combatté al fianco di Alamorte durante la Seconda Guerra.",al={"chi si trova nella piana di lethlor","blacklash e hematus","luogotenenti di alamorte"}}},fp="16,220,18.455.0,9.186.0,19.300.1,12.157.0,38.151.0,19.36.0,30.85.0,47.161.0"}
P.entries["quest:7820"] = {n="Donazione di lana",s="Picco del Tuono cerca Tessuto di Lana e puoi ottenere il pieno riconoscimento donandone sessanta pezzi. Ci si aspetta che gli altri donatori portino provviste sufficienti a sostenere la raccolta.",h="Picco del Tuono cerca Tessuto di Lana e puoi ottenere il pieno riconoscimento donandone sessanta pezzi.",kw={"raccolta di stoffa","donazione","riconoscimento","sessanta pezzi","picco del tuono","lana","tessuto di lana"},sec={{t="Una donazione di stoffa",b="Picco del Tuono sta raccogliendo Tessuto di Lana. Dona sessanta pezzi per ottenere il pieno riconoscimento per la tua generosità. Ci si aspetta che gli altri donatori del regno ne portino abbastanza da sostenere la raccolta."}},faq={{q="Che cosa vuole ricevere in donazione Picco del Tuono?",a="Picco del Tuono accetta donazioni di Tessuto di Lana.",al={"donazione di lana","quale stoffa serve","donare lana"}},{q="Quanto Tessuto di Lana dovrei donare?",a="Dona sessanta pezzi di Tessuto di Lana per ottenere il pieno riconoscimento da Picco del Tuono.",al={"quanta lana","sessanta pezzi di stoffa","quantità da donare"}},{q="Cosa ottengo donando lana?",a="Il tuo dono di sessanta pezzi di Tessuto di Lana ti farà ottenere il pieno riconoscimento da Picco del Tuono.",al={"riconoscimento per la donazione di lana","qual è il riconoscimento","ricompensa per la donazione"}},{q="Perché Picco del Tuono raccoglie lana?",a="Picco del Tuono si aspetta che gli altri donatori del regno forniscano Tessuto di Lana a sufficienza per sostenere la raccolta.",al={"perché raccogliere lana","a cosa serve la lana","perché raccogliere stoffa"}}},fp="18,166,16.179.0,37.48.0,34.76.0,32.82.0,37.107.0"}
P.entries["quest:7826"] = {n="Donazione di lana",s="A Orgrimmar, A Donation of Wool chiede aiuto per raccogliere tessuto. La città ha già del tessuto di lana nelle scorte e si aspetta che altri donatori ne portino abbastanza per la raccolta.",h="A Orgrimmar, A Donation of Wool chiede aiuto per raccogliere tessuto.",kw={"a donation of wool","donazione","orgrimmar","riconoscimento","sessanta pezzi","lana","tessuto di lana"},sec={{t="Lana per Orgrimmar",b="Orgrimmar ti chiede di donare sessanta pezzi di Tessuto di Lana. In cambio, la città promette un riconoscimento. Nelle sue scorte c'è già un po' di tessuto, e si aspetta che altri donatori contribuiscano alla raccolta."}},faq={{q="Che cosa chiede Orgrimmar?",a="Orgrimmar accetta donazioni di Tessuto di Lana.",al={"cosa vogliono","donazione di lana"}},{q="Quanta lana devo donare?",a="Orgrimmar chiede sessanta pezzi di Tessuto di Lana.",al={"quanta lana","sessanta pezzi di lana"}},{q="Che cosa ottengo donando lana?",a="Riceverai pieno riconoscimento da Orgrimmar per aver donato sessanta pezzi di Tessuto di Lana.",al={"riconoscimento per la donazione","ricompensa per la lana"}},{q="Perché Orgrimmar raccoglie lana?",a="Orgrimmar raccoglie lana per sostenere la campagna di donazioni.",al={"raccolta di lana","perché la lana"}},{q="Orgrimmar ha già della lana?",a="Sì. Orgrimmar ha del tessuto di lana nelle sue scorte e si aspetta che altri donatori ne portino abbastanza per la raccolta.",al={"scorte di lana","quanta lana"}}},fp="18,153,18.188.0,29.47.0,34.46.0,32.81.0,33.58.0,33.96.0"}
P.entries["quest:78261"] = {n="The Horn of Xelthos",s="Un biglietto di C ti chiede di recuperare The Horn of Xelthos da Forte di Zannascura da solo. Veenix, nelle Vette di Petrartiglio, potrebbe aiutarti a superare il cancello del cortile.",h="Un biglietto di C ti chiede di recuperare The Horn of Xelthos da Forte di Zannascura da solo.",kw={"c","nascondiglio","the horn of xelthos","rovonero","forte di zannascura","vette di petrartiglio","veenix","xelthos"},sec={{t="Un approccio discreto",b="C lascia il biglietto vicino a Rovonero e indica Veenix come contatto nelle Vette di Petrartiglio. The Horn of Xelthos si trova da qualche parte dentro Forte di Zannascura, dove di solito serve aiuto per entrare. C vuole che il lavoro resti segreto, quindi devi andarci da solo e riportare il corno al nascondiglio."}},faq={{q="Chi ti chiede The Horn of Xelthos?",a="C lascia un biglietto in cui ti chiede di recuperare The Horn of Xelthos e riportarlo al nascondiglio vicino a Rovonero.",al={"chi è c","chi vuole il corno","incarico del corno di c"}},{q="Dov'è The Horn of Xelthos?",a="The Horn of Xelthos si trova da qualche parte dentro Forte di Zannascura.",al={"dove si trova il corno","posizione del corno","trovare xelthos"}},{q="Perché devo andarci da solo?",a="C dice che il lavoro richiede discrezione, quindi devi entrare da solo a Forte di Zannascura.",al={"perché da solo","perché andare da solo","senza aiuto"}},{q="Chi è Veenix?",a="Veenix è il contatto di C nelle Vette di Petrartiglio e potrebbe aiutarti a superare il cancello del cortile di Forte di Zannascura.",al={"aiuto di veenix","chi è veenix","contatto al cancello"}},{q="Dove devo riportare il corno?",a="Riporta il corno al nascondiglio di C vicino a Rovonero.",al={"dove riportare il corno","posizione del nascondiglio","consegnare il corno"}}},fp="19,158,16.292.0,38.112.0,29.56.0,26.82.0,14.110.0,27.55.0"}
P.entries["quest:78270"] = {n="Goblin Lockpicks",s="Un contatto della Venture Co. ti offre esplosivi per superare il cancello di Zannascura, ma prima ti chiede di trovare un ordine di lavoro. Un altro lavoratore della Venture Co. qui vicino dovrebbe averne uno.",h="Un contatto della Venture Co.",kw={"esplosivi","cancello","grimaldelli goblin","zannascura","venture co.","ordine di lavoro"},sec={{t="Un ordine di lavoro",b="Un contatto della Venture Co. ha saputo che vuoi entrare da solo a Zannascura. Gli esplosivi potrebbero aiutarti a superare il cancello, ma gli serve un ordine di lavoro per giustificarli nei registri contabili della compagnia. Uno degli altri lavoratori della Venture Co. qui vicino dovrebbe avere il documento."}},faq={{q="Perché gli serve un ordine di lavoro?",a="Al contatto della Venture Co. serve un ordine di lavoro per giustificare gli esplosivi nei registri contabili della compagnia.",al={"perché ordine di lavoro","perché documenti","grimaldelli goblin"}},{q="A cosa servono gli esplosivi?",a="Gli esplosivi servono a farti superare il cancello di Zannascura.",al={"a cosa servono gli esplosivi","cancello di zannascura","superare il cancello"}},{q="Chi potrebbe avere l'ordine di lavoro?",a="Un altro lavoratore della Venture Co. qui vicino dovrebbe avere un ordine di lavoro.",al={"chi ha l'ordine di lavoro","trovare i documenti","ordine di lavoro venture co."}},{q="Entrerò da solo a Zannascura?",a="Il contatto della Venture Co. sa che hai intenzione di entrare da solo a Zannascura.",al={"zannascura da solo","entrare da solo","entrare a zannascura"}}},fp="16,176,12.268.0,30.103.0,28.61.0,30.66.0,33.76.0"}
P.entries["quest:7828"] = {n="Stalking the Stalkers",s="A Revantusk, il Predatore Markhor indica i lupi che minacciano i cacciatori del villaggio. Ti chiede di dar loro la caccia.",h="A Revantusk, il Predatore Markhor indica i lupi che minacciano i cacciatori del villaggio.",kw={"lupi delle entroterre","predatore markhor","revantusk","villaggio degli zannatorta","urlatore crinargenteo","predatore crinargenteo","stalking the stalkers"},sec={{t="Lupi in agguato",b="Le terre selvagge delle Entroterre hanno già reclamato molti troll. Markhor annovera i lupi Crinargenteo tra i maggiori pericoli per i cacciatori di Revantusk. Si nascondono tra i cespugli e nella conformazione del terreno, poi balzano al momento giusto. Ti esorta a pensare come un Crinargenteo e a dare la caccia ai cacciatori. Devi abbatterli tutti."},{t="Cosa chiede Markhor",b="Markhor ti chiede di uccidere quindici Predatori Crinargenteo e quindici Urlatori Crinargenteo. Si annidano nelle terre selvagge delle Entroterre."},{t="I ringraziamenti di Revantusk",b="Terminata la caccia, Markhor ti ringrazia a nome dei Revantusk per ciò che hai dato loro."}},faq={{q="Chi chiede di dare la caccia ai lupi?",a="Il Predatore Markhor, di Revantusk nelle Entroterre, ti chiede di dare la caccia ai lupi.",al={"chi assegna stalking the stalkers","datore di missione stalking the stalkers","missione markhor"}},{q="Perché i lupi Crinargenteo sono una minaccia così grande?",a="I lupi Crinargenteo si nascondono tra i cespugli e nella conformazione del terreno, poi colpiscono appena se ne presenta l'occasione. Markhor li considera tra i maggiori pericoli per i cacciatori di Revantusk, e molti troll sono già andati perduti nelle terre selvagge.",al={"perché uccidere i lupi crinargenteo","minaccia dei lupi crinargenteo","perché abbattere i lupi nelle entroterre"}},{q="Quali lupi devono essere abbattuti?",a="Ti viene chiesto di dare la caccia a quindici Predatori Crinargenteo e quindici Urlatori Crinargenteo.",al={"quali lupi uccidere","obiettivi di stalking the stalkers","tipi di lupi nelle entroterre"}},{q="Dove si trovano questi lupi?",a="I lupi si annidano nelle terre selvagge delle Entroterre.",al={"dove si trovano i lupi crinargenteo","posizione predatore crinargenteo","posizione urlatore crinargenteo"}}},fp="21,120,16.321.0,17.120.0,18.80.1,37.79.0,44.218.0,31.81.0,29.41.0"}
P.entries["quest:7829"] = {n="Hunt the Savages",s="Nelle Entroterre, il Predatore Markhor ti manda a caccia di creature gufo selvagge. Te ne chiede venti.",h="Nelle Entroterre, il Predatore Markhor ti manda a caccia di creature gufo selvagge.",kw={"entroterre","hunt the savages","predatore markhor","creature gufo","revantusk","villaggio degli zannatorta","selvaggia creatura gufo"},sec={{t="Artigli e becchi",b="Il Predatore Markhor ti avverte che le creature gufo selvagge sono tra le più ostinate delle Entroterre. I loro artigli e becchi sono costati molti valorosi guerrieri ai Revantusk. Vuole che uccidi ogni creatura gufo che incontri, finché non ne potrai più dello spargimento di sangue. Poi peserà e giudicherà il tuo contributo. Devono cadere in venti."},{t="Schiarire la mente",b="Markhor ti consiglia di liberare la mente dai pensieri impuri e unirti alla natura selvaggia. Le creature gufo selvagge vagano per le terre selvagge delle Entroterre."},{t="Il giudizio di Markhor",b="Dopo la caccia, il Predatore Markhor ti proclama degno amico dei Revantusk."}},faq={{q="Chi offre questa caccia?",a="Il Predatore Markhor, cacciatore del villaggio dei Revantusk nelle Entroterre, ti propone la caccia.",al={"chi assegna hunt the savages","datore di missione hunt the savages","missione del predatore markhor"}},{q="Perché Markhor vuole che le selvagge creature gufo vengano uccise?",a="Markhor definisce ostinate le creature gufo selvagge. I loro artigli e becchi sono costati molti valorosi guerrieri ai Revantusk.",al={"perché uccidere le selvagge creature gufo","motivo della caccia alle creature gufo","perché cacciare le bestie selvagge"}},{q="Dove si possono trovare le selvagge creature gufo?",a="Markhor dice che le creature gufo selvagge vagano per le terre selvagge delle Entroterre.",al={"posizione delle selvagge creature gufo","dove sono le selvagge creature gufo","creature gufo nelle entroterre"}},{q="Quante selvagge creature gufo devono essere uccise?",a="Devono cadere venti creature gufo selvagge.",al={"quante creature gufo uccidere","requisito di hunt the savages"}}},fp="16,106,15.300.0,17.128.0,18.76.1,21.95.0,50.100.0,40.57.0,40.34.0"}
P.entries["quest:783"] = {n="A Threat Within",s="Nella Valle della Contea del Nord, i volontari rispondono alla chiamata di Roccavento mentre le difese locali cedono. All'Abbazia della Contea del Nord, il Maresciallo McBride dirige la risposta e tu inizi a servire nei territori minacciati.",h="Nella Valle della Contea del Nord, i volontari rispondono alla chiamata di Roccavento mentre le difese locali...",kw={"a threat within","abbazia","foresta di elwynn","maresciallo mcbride","contea del nord","reclutamento","guardia di roccavento","volontari"},ang={["faction:Alliance"]="In quanto membro dell'Alleanza, vedi come i doveri svolti in terre lontane lascino esposte alle minacce interne persino le sue terre centrali.",["race:Human"]="Come difensore umano della Contea del Nord, rispondere alla chiamata del Maresciallo McBride è il tuo primo impegno ufficiale a proteggere la tua patria e il Regno di Roccavento."},sec={{t="Un regno sotto pressione",b="Un tempo la Valle della Contea del Nord offriva quiete per pregare, coltivare la terra e dedicarsi allo studio monastico. Ora è la prima linea di difesa della Foresta di Elwynn contro i disordini interni. Le guardie rimaste nelle vicinanze sono poche, così la Guardia di Roccavento chiama a raccolta ogni volontario disposto a raggiungere l'abbazia. I problemi si diffondono per le campagne circostanti."},{t="La chiamata del Maresciallo",b="Dall'Abbazia della Contea del Nord, il Maresciallo McBride dirige le difese della valle mentre il pericolo cresce. Banditi, parassiti e creature nocive provenienti dal sottosuolo minacciano gli abitanti della zona. Inizi ripulendo il terreno attorno all'abbazia, dove queste minacce incalzano i difensori della valle e il luogo che proteggono."}},faq={{q="Qual è lo scopo di questa missione?",a="Il Maresciallo McBride chiama i nuovi arrivati nella Valle della Contea del Nord ad aiutarlo a difenderla. Entri nell'Abbazia della Contea del Nord e ti presenti a lui.",al={"missione a threat within","cos'è questa missione","missione introduttiva contea del nord"}},{q="Chi è il Maresciallo McBride?",a="Il Maresciallo McBride è l'ufficiale di grado più alto della Guardia di Roccavento all'Abbazia della Contea del Nord. Dirige la difesa della valle e assegna alle reclute il compito di affrontare le minacce nelle campagne vicine.",al={"maresciallo mcbride","chi è mcbride","comandante dell'abbazia"}},{q="Perché Roccavento sta reclutando volontari invece di inviare soldati regolari?",a="Le forze regolari di Roccavento prestano servizio all'estero per proteggere l'Alleanza. Con le guarnigioni delle terre centrali a corto di soldati, i comandanti locali si affidano ai volontari per difendere le loro case.",al={"perché i volontari","dove sono le guardie","perché roccavento è a corto di personale"}},{q="Quali minacce stanno attualmente piagando la Valle della Contea del Nord?",a="I Kobolds infestano le miniere e le colline vicine, mentre parassiti malati o predatori infestano i vigneti. Anche briganti e fuorilegge approfittano della guarnigione ridotta della valle.",al={"minacce della valle","cosa sta attaccando la contea del nord","problemi contea del nord"}},{q="Dove porta questo incarico?",a="Dopo esserti presentato al Maresciallo McBride, ti viene chiesto di scacciare i Kobolds dalle colline, aiutare i contadini e i lavoratori del posto e indagare sulla crescente presenza di banditi organizzati.",al={"prossima missione","cosa viene dopo a threat within","prosieguo di mcbride"}},{q="Perché l'Abbazia della Contea del Nord viene utilizzata come posto di comando militare?",a="L'Abbazia della Contea del Nord è un luogo sacro di studio e fede, ma le sue mura di pietra e la posizione centrale la rendono una base pratica per la valle. Con l'autorità locale sotto pressione, la Guardia di Roccavento ha stabilito il proprio comando nell'abbazia.",al={"perché l'esercito nell'abbazia","esercito della chiesa della contea del nord","soldati dell'abbazia sacra"}}},fx={["2039075b"]={q="Perché il vice Willem ti manda dal Marshal McBride?",a="Il vice Willem è di stanza fuori dall'Abbazia della Contea del Nord e deve valutare il più rapidamente possibile i nuovi arrivati in grado di combattere. Con le forze del regno sotto pressione e numerose crisi che incombono sui confini della Contea del Nord, ha bisogno che ogni volontario capace venga arruolato regolarmente. Invece di assegnare lui stesso le missioni, Willem ti manda direttamente dal suo comandante, Marshal McBride, affinché ti informi ufficialmente e ti invii dove le difese della valle sono più deboli.",al={"perché parlare con mcbride","motivo di willem"}}},fp="15,190,24.301.0,18.295.0,34.129.0,23.170.0,75.167.0,54.175.0,37.171.0,62.230.0"}
P.entries["quest:7830"] = {n="Avenging the Fallen",s="Al Villaggio degli Zannatorta, Markhor rivolge la sua rabbia contro i Lord del Cielo. Ti chiede di uccidere un Lord del Cielo Beccoaffilato e portargli la sua piuma.",h="Al Villaggio degli Zannatorta, Markhor rivolge la sua rabbia contro i Lord del Cielo.",kw={"avenging the fallen","grifone","entroterre","predatore markhor","lord del cielo beccoaffilato","villaggio degli zannatorta","piuma del lord del cielo","granmartello"},sec={{t="Uccidere i Lord del Cielo",b="Il Predatore Markhor del Villaggio degli Zannatorta è amareggiato perché i Granmartello addestrano i grifoni a uccidere i troll. Promette giustizia per i troll, ma prima vuole che tu colpisca i Lord del Cielo, i grifoni più anziani delle Entroterre.\n\nUccidi un Lord del Cielo Beccoaffilato e riportane la piuma a Markhor. Questa razza rara vive nelle zone selvagge delle Entroterre. Markhor la accusa di generare piccoli assassini."},{t="La piuma esaminata",b="Markhor esamina la piuma e si chiede quanti cacciatori la bestia abbia divorato prima che tu le facessi giustizia."}},faq={{q="Chi offre questa caccia?",a="Il Predatore Markhor offre questa caccia al Villaggio degli Zannatorta, nelle Entroterre.",al={"datore di missione","chi dà avenging the fallen","posizione di markhor"}},{q="Perché il Predatore Markhor vuole che un Lord del Cielo venga ucciso?",a="Markhor dice che i Granmartello addestrano i grifoni a uccidere i troll. Vuole sterminare i grifoni più anziani della regione, i Lord del Cielo, e accusa il raro Lord del Cielo Beccoaffilato di generare piccoli assassini.",al={"perché uccidere lord del cielo beccoaffilato","perché uccidere un lord del cielo","perché cacciare i grifoni"}},{q="Dove si può trovare un Lord del Cielo Beccoaffilato?",a="Markhor dice che il raro Lord del Cielo Beccoaffilato vive nelle zone selvagge delle Entroterre.",al={"posizione dei lord del cielo","dove si trova il lord del cielo beccoaffilato","posizione piuma del lord del cielo"}},{q="Cosa bisogna riportare a Markhor?",a="La piuma di un Lord del Cielo Beccoaffilato, che prima dovrai uccidere.",al={"quale oggetto serve","obiettivo di avenging the fallen","bottino del lord del cielo"}}},fp="19,131,20.383.0,18.110.1,21.73.0,47.190.0,39.78.0,37.64.0"}
P.entries["quest:7833"] = {n="Donazione di lana",s="Un troll Lanciascura raccoglie donazioni di lana. I tuoi sessanta pezzi di Tessuto di Lana aiuteranno a completare la raccolta insieme a quelli degli altri.",h="Un troll Lanciascura raccoglie donazioni di lana.",kw={"raccolta","lanciascura","donazione","scorte","troll","lana","tessuto di lana"},sec={{t="Una raccolta condivisa",b="I Troll Lanciascura raccolgono Tessuto di Lana, e il raccoglitore può accettare subito i tuoi sessanta pezzi. Le loro scorte hanno bisogno di quella quantità da parte tua; si conta sull'aiuto degli altri per completare la raccolta."}},faq={{q="Che cosa stanno raccogliendo?",a="I Troll Lanciascura raccolgono Tessuto di Lana.",al={"di cosa hanno bisogno","donazione di lana"}},{q="Quanto Tessuto di Lana serve?",a="Il raccoglitore ti chiede sessanta pezzi di Tessuto di Lana.",al={"quanta lana","60 pezze di stoffa"}},{q="Perché i troll raccolgono lana?",a="La raccolta serve a rifornire le loro scorte.",al={"perché lana","a che serve"}},{q="Posso consegnare la stoffa adesso?",a="Il raccoglitore può accettare subito i tuoi sessanta pezzi di Tessuto di Lana.",al={"dove consegnare la lana","donare subito"}}},fp="18,138,19.196.0,24.47.0,41.59.0,35.50.0,25.61.0"}
P.entries["quest:7839"] = {n="Vilebranch Hooligans",s="Nel Villaggio degli Zannatorta, Fabbro Selvarotta cerca gli attrezzi rubati dai troll Vilebranch. Uno gnomo di buon cuore glieli regalò dopo avergli salvato la vita quand'era un giovane orco.",h="Nel Villaggio degli Zannatorta, Fabbro Selvarotta cerca gli attrezzi rubati dai troll Vilebranch.",kw={"agol'watha","entroterre","markhor","villaggio degli zannatorta","shaol'watha","tumulo strisciante","attrezzi perduti di selvarotta","fabbro selvarotta","vilebranch"},sec={{t="Un regalo da uno gnomo",b="I troll Vilebranch hanno rubato gli attrezzi di Fabbro Selvarotta durante l'invasione del Villaggio degli Zannatorta. Ha degli attrezzi di riserva, ma il set rubato gli fu donato da uno gnomo di buon cuore che gli salvò la vita quand'era un giovane orco. Per Selvarotta quel regalo significa tutto, così ti chiede di recuperarlo."},{t="Dove sono stati visti gli attrezzi",b="Markhor ha visto gli attrezzi vicino ai templi di Agol'watha e Shaol'watha, nel nord-est delle Entroterre. Selvarotta dice anche di controllare Tumulo Strisciante. I troll Vilebranch che vivono lì sono spietati e assassini."}},faq={{q="Perché questi attrezzi rubati sono così importanti per il Fabbro Selvarotta?",a="Uno gnomo di buon cuore regalò gli attrezzi a Selvarotta dopo avergli salvato la vita quand'era un giovane orco. Selvarotta ha degli attrezzi di riserva, ma dice che il set ricevuto in dono significa tutto per lui.",al={"perché a selvarotta stanno a cuore i suoi attrezzi","storia attrezzi perduti di selvarotta","perché gli attrezzi di selvarotta sono speciali"}},{q="Chi ha rubato gli attrezzi dal Villaggio degli Zannatorta?",a="I troll Vilebranch hanno rubato gli attrezzi di Fabbro Selvarotta durante l'invasione del Villaggio degli Zannatorta.",al={"chi ha preso gli attrezzi","chi ha rubato gli attrezzi di selvarotta"}},{q="Dove sono stati portati gli attrezzi mancanti?",a="Vicino ai templi di Agol'watha e Shaol'watha, nel nord-est delle Entroterre, dove li ha visti Markhor. Selvarotta indica anche Tumulo Strisciante.",al={"dove sono gli attrezzi di selvarotta","dove trovare gli attrezzi","posizione attrezzi di selvarotta"}},{q="Chi ha riferito di aver visto gli attrezzi dopo l'incursione?",a="Markhor ha detto a Fabbro Selvarotta dove erano stati visti gli attrezzi.",al={"chi ha visto gli attrezzi","chi ha riferito degli attrezzi rubati"}}},fp="20,162,19.259.0,25.201.0,58.163.0,43.90.0,35.144.0,45.58.0"}
P.entries["quest:784"] = {n="Vanquish the Betrayers",s="Al Forte di Tiragarde, le forze di Kul Tiras mantengono ancora un punto d'appoggio sulla costa di Durotar. Gar'thok chiama l'Orda a colpire la guarnigione del Tenente Benedict, la cui presenza ha spezzato la fragile pace con Theramore.",h="Al Forte di Tiragarde, le forze di Kul Tiras mantengono ancora un punto d'appoggio sulla costa di Durotar.",kw={"daelin marefiero","durotar","gar'thok","kul tiras","tenente benedict","fanti","tranciacolle","marinai","forte di tiragarde","vanquish the betrayers"},ang={["faction:Horde"]="Le forze di Kul Tiras occupano ancora il Forte di Tiragarde, alle porte di Durotar. Scacciare le forze di Benedict dimostra che l'Orda sa difendere la propria patria appena colonizzata dalle flotte straniere.",["race:Orc"]="Gli orchi onorano la tregua con Jaina sul Monte Hyjal, ma Kul Tiras rievoca i ricordi amari della Seconda Guerra. Combattere i fanti di Benedict è una questione di sopravvivenza e orgoglio ancestrale.",["race:Troll"]="Il Forte di Tiragarde è scomodamente vicino al Villaggio di Sen'jin, insediamento dei Puntascura. Scacciare i marinai ostili aiuta a proteggere la nuova e vulnerabile dimora dei troll."},sec={{t="Una Tregua Infranta",b="Thrall guidò l'Orda attraverso il Grande Mare fino a Kalimdor. Lì, lui e Dama Jaina Marefiero combatterono la Legione Infuocata sul Monte Hyjal. La pace si spezzò quando il padre allontanato di Jaina, il Gran Ammiraglio Daelin Marefiero, portò la marina di Kul Tiras a Durotar. Incolpò ogni orco delle atrocità della Vecchia Orda e conquistò roccaforti costiere, tra cui il Forte di Tiragarde. Daelin morì a Theramore, ma i resti della sua flotta rifiutano ancora qualsiasi patto e conservano il loro odio."},{t="La Rinascita di Benedict",b="Il Forte di Tiragarde cadde per un periodo dopo la sconfitta del Gran Ammiraglio. Poi le riserve di Kul Tiras guidate dal Tenente Benedict lo riconquistarono. La fortezza si trova tra Tranciacolle e il Villaggio di Sen'jin. Da lì, marinai e fanti molestano i viaggiatori e minacciano gli accessi marittimi orientali di Durotar. Gar'thok considera la loro presenza un pericolo immediato per la sicurezza di Durotar. Perciò chiama i guerrieri dell'Orda a colpire il comando di Benedict."}},faq={{q="Perché gli umani di Kul Tiras stanno attaccando Durotar?",a="Sono i resti della flotta di spedizione del Gran Ammiraglio Daelin Marefiero. Daelin rifiutò la pace tra umani e orchi e cercò di distruggere Durotar. Anche dopo la sua morte, i suoi lealisti mantengono roccaforti costiere come il Forte di Tiragarde e sfidano l'Orda.",al={"perché gli umani sono a durotar","attacco di kul tiras","storia degli umani del forte di tiragarde"}},{q="Chi è il Tenente Benedict?",a="Il Tenente Benedict comanda le riserve di Kul Tiras che occupano il Forte di Tiragarde. Dopo la sconfitta del Gran Ammiraglio Marefiero, Benedict radunò i fanti e i marinai sopravvissuti. Riconquistò la fortezza costiera e avviò operazioni continue contro gli orchi.",al={"chi è benedict","storia del tenente benedict","capo del forte di tiragarde"}},{q="Jaina Marefiero sostiene questi umani?",a="No. Jaina strinse un patto con il Capoguerra Thrall per garantire la sopravvivenza di entrambi e si oppose alla campagna aggressiva di suo padre per preservare la pace. Le truppe al Forte di Tiragarde sono resti di Kul Tiras che rifiutano la diplomazia di Theramore e considerano un tradimento la tregua di Jaina.",al={"jaina li sostiene","theramore kul tiras alleanza","jaina marefiero forte di tiragarde"}},{q="Perché sono chiamati 'traditori'?",a="Gar'thok li chiama traditori perché la loro invasione ha infranto l'intesa stretta da Thrall e Jaina Marefiero per sconfiggere Archimonde durante la Seconda Guerra. La loro persistente presenza militare nel territorio dell'Orda sfida i confini stabiliti a Kalimdor dopo la guerra.",al={"perché traditori","chi ha tradito chi","significato di traditori"}},{q="Dove si trova il Forte di Tiragarde?",a="Il Forte di Tiragarde si trova sulla costa orientale di Durotar, a sud di Tranciacolle e appena a nord-est del Villaggio di Sen'jin. Le sue alte mura di pietra dominano le acque costiere e offrono agli invasori una base strategica vicino agli insediamenti dell'Orda.",al={"posizione del forte di tiragarde","dove si trova il forte di tiragarde","dove trovare benedict"}}},fx={["6a077d02"]={q="Perché Gar'thok vuole che il Forte di Tiragarde venga liberato?",a="Gar'thok sovrintende alla difesa di Tranciacolle e della Durotar orientale. La rioccupazione del Forte di Tiragarde da parte di ostili forze Kul Tiran minaccia direttamente la sicurezza della patria orchesca e viola la pace stipulata tra Thrall e Jaina Marefiero. Lasciare che una fortezza umana armata si consolidi sulla costa della Durotar mette gli insediamenti e le linee di rifornimento vicini a immediato rischio d'invasione.",al={"motivo di gar'thok","perché liberare il forte di tiragarde","gar'thok perché attaccare gli umani"}},["902328ad"]={q="Chi ti viene mandato a eliminare al Forte di Tiragarde?",a="Il tuo compito è sbaragliare le forze navali Kul Tiran ancora stanziate al Forte di Tiragarde: marinai, fanti di marina e il loro comandante, il Tenente Benedict. Questi soldati sono ciò che resta della flotta del Gran Ammiraglio Daelin Marefiero e mantengono una testa di ponte armata non autorizzata nel cuore del territorio sovrano dell'Orda.",al={"chi uccidere al forte di tiragarde","chi sono i bersagli","bersagli da sconfiggere"}}},fp="22,207,17.452.0,21.420.0,43.256.0,27.249.0,43.253.0,32.259.0,32.216.0"}
P.entries["quest:7840"] = {n="Lard Lost His Lunch",s="Nelle Entroterre, Lard è corso a Revantusk lasciando indietro il pranzo al sacco. Un Vilebranch ha colpito Lard durante un picnic privato, e ora Lard ti chiede di recuperare il cibo su un'isola a nord.",h="Nelle Entroterre, Lard è corso a Revantusk lasciando indietro il pranzo al sacco.",kw={"entroterre","isola","lard","pranzo","picnic","villaggio degli zannatorta","vilebranch"},sec={{t="Un picnic interrotto",b="Un Vilebranch ha colpito Lard con un grosso bastone in un luogo segreto per i picnic. Secondo Lard, il troll era brutto e cattivo. Lard è fuggito a Revantusk, lasciando indietro il pranzo e temendo di tornare."},{t="L'isola a nord",b="Il luogo del picnic di Lard si trova su un'isola a nord. Lard spera che tu trovi il pranzo e glielo riporti. Fai attenzione ai troll Vilebranch."},{t="I ringraziamenti di Lard",b="Il pranzo di Lard è un enorme cosciotto di carne. Lard lo divora, ti ringrazia e promette di darti uno speciale cestino da picnic per il tuo aiuto."}},faq={{q="Chi è Lard?",a="Lard vive a Revantusk, nelle Entroterre. Affamato e spaventato, è fuggito dopo che un Vilebranch lo ha colpito con un grosso bastone.",al={"lard entroterre","chi è lard","lard revantusk"}},{q="Dove ha perso il pranzo Lard?",a="Lard ha lasciato il pranzo in un luogo segreto per i picnic, su un'isola a nord.",al={"dov'è il pranzo di lard","luogo del picnic di lard","luogo segreto di lard"}},{q="Perché Lard ha lasciato lì il cibo?",a="Un Vilebranch ha colpito Lard con un grosso bastone durante il picnic. Lard è corso a Revantusk senza il pranzo.",al={"perché è fuggito lard","chi ha attaccato lard"}},{q="Cosa dovresti tenere d'occhio sull'isola?",a="Lard indica i troll Vilebranch come un pericolo sull'isola.",al={"vilebranch sull'isola","pericoli sull'isola di lard"}}},fp="19,194,20.185.0,20.144.0,13.122.1,12.125.0,30.70.0,35.106.0,44.59.0"}
P.entries["quest:7841"] = {n="Message to the Wildhammer",s="Al Villaggio degli Zannatorta, Otho Moji'ko vuole che un messaggio venga recapitato ai nani Wildhammer. Tra i loro nuovi alleati ci sono gli alti elfi, e Otho vuole che il suo avvertimento sia scritto col sangue degli alti elfi di Alta Valle al Padiglione Quel'Danil.",h="Al Villaggio degli Zannatorta, Otho Moji'ko vuole che un messaggio venga recapitato ai nani Wildhammer.",kw={"alta valle","entroterre","message to the wildhammer","otho mojiko","padiglione quel'danil","villaggio degli zannatorta","wildhammer"},sec={{t="Un messaggio col sangue",b="I Wildhammer stringono alleanze con i nemici dei troll, e ora gli alti elfi sono al loro fianco. Otho Moji'ko sputa per terra al solo pensiero. Vuole avvertire i nani col sangue dei loro nuovi amici. Massacra ogni alto elfo di Alta Valle che trovi e lascia i corpi come monito.\n\nI Corridori, gli Esploratori, i Tiratori Scelti e i Ranger di Alta Valle si radunano al Padiglione Quel'Danil, nel nord-ovest delle Entroterre."},{t="Voci al Villaggio degli Zannatorta",b="Quando torni al Villaggio degli Zannatorta, Otho dichiara che anche gli Zannatorta stanno stringendo nuove alleanze. Si complimenta per il tuo lavoro."}},faq={{q="Chi offre questa missione?",a="Otho Moji'ko la propone dal Villaggio degli Zannatorta.",al={"chi fornisce message to the wildhammer","missione otho mojiko"}},{q="Dove si trovano gli alti elfi di Alta Valle?",a="Gli alti elfi di Alta Valle si radunano al Padiglione Quel'Danil, nel nord-ovest delle Entroterre.",al={"posizione padiglione quel danil","dove si trovano gli elfi di alta valle","dove trovare gli esploratori di alta valle"}},{q="Perché Otho Moji'ko vuole che gli alti elfi vengano attaccati?",a="Otho dice che i Wildhammer stanno stringendo accordi con i nemici dei troll, e ora collaborano con gli alti elfi. Vuole che un messaggio venga recapitato ai nani Wildhammer, scritto col sangue degli alti elfi.",al={"perché attaccare il padiglione quel danil","perché uccidere gli alti elfi nelle entroterre"}},{q="Quali elfi di Alta Valle vuole che vengano massacrati Otho?",a="Otho vuole che i Corridori, gli Esploratori, i Tiratori Scelti e i Ranger di Alta Valle al Padiglione Quel'Danil vengano massacrati.",al={"quali elfi di alta valle","tiratore scelto di alta valle","ranger di alta valle"}}},fp="25,222,18.393.0,25.122.1,22.46.0,42.88.0,51.209.0,48.97.0"}
P.entries["quest:7842"] = {n="Another Message to the Wildhammer",s="Al Villaggio degli Zannatorta, Otho Moji'ko manda un altro messaggio ai Granmartello. Vede che il loro legame con i grifoni è forte quanto quello tra un troll e la sua compagna, e vuole usarlo contro di loro.",h="Al Villaggio degli Zannatorta, Otho Moji'ko manda un altro messaggio ai Granmartello.",kw={"grifone","entroterre","lunga piuma elegante","otho moji'ko","villaggio degli zannatorta","granamartello"},sec={{t="Un messaggio di piume",b="Dopo gli alti elfi di Alta Valle, Otho Moji'ko ha un altro messaggio per i Granmartello. La loro vicinanza ai grifoni lo disgusta, ma vede come sfruttarla. Uccidi i grifoni che incontri nelle Entroterre e raccogli le loro Lunghe Piume Eleganti. I grifoni vivono in ogni regione della zona. Otho comporrà il suo messaggio finale con le piume."},{t="Il piacere di Otho",b="Otho si aspetta che il suo messaggio finale spaventi i Granmartello e li faccia fuggire, oppure li faccia infuriare. È entusiasta: manca un solo passo perché scoprano che non si può sfidare impunemente un troll."}},faq={{q="Chi assegna questa missione?",a="Otho Moji'ko consegna il messaggio dal Villaggio degli Zannatorta.",al={"chi assegna un altro messaggio ai granmartello","assegnatore missione un altro messaggio","otho mojiko"}},{q="Perché Otho Moji'ko vuole le piume di grifone?",a="Otho dice che i Granmartello e i loro grifoni sono legati quanto un troll e la sua compagna. Vuole sfruttare quel legame contro di loro e comporre il suo messaggio finale con le piume.",al={"perché piume di grifone","perché uccidere grifoni entroterre"}},{q="Dove si possono trovare i grifoni?",a="I grifoni vivono in ogni regione delle Entroterre.",al={"posizioni grifoni entroterre","dove si trovano grifoni entroterre"}},{q="Cosa c'è prima di questo messaggio?",a="Questa missione segue Message to the Wildhammer, in cui Otho fece massacrare gli alti elfi di Alta Valle per mettere in guardia i nani.",al={"cosa precede un altro messaggio ai granmartello","catena missioni message to the wildhammer"}}},fp="33,175,21.332.0,15.167.1,21.54.0,44.165.0,28.49.0,30.118.0"}
P.entries["quest:7843"] = {n="The Final Message to the Wildhammer",s="Al Villaggio degli Zannatorta, Otho Moji'ko ti manda a ovest con una lancia intrisa di sangue e legata con piume di grifone. I nani Wildhammer la troveranno conficcata accanto al pozzo nel cuore del Picco dell'Aquila.",h="Al Villaggio degli Zannatorta, Otho Moji'ko ti manda a ovest con una lancia intrisa di sangue e legata con...",kw={"picco dell'aquila","piume di grifone","entroterre","otho moji'ko","villaggio degli zannatorta","lancia","wildhammer"},sec={{t="Una lancia per il Picco dell'Aquila",b="Dopo Another Message to the Wildhammer, Otho Moji'ko ti consegna una lancia intrisa di sangue e legata con piume di grifone. Portala a ovest, fino al Picco dell'Aquila, e piantala accanto al pozzo nel cuore della città. I nani Wildhammer capiranno che i troll fanno sul serio. Là ti aspettano nani furiosi e gente turbolenta dell'Alleanza, e Otho spera che tu torni vivo."},{t="La speranza di Otho",b="Otho si chiede come reagiranno i nani quando vedranno la lancia. Avrebbe voluto vedere le loro facce. Stanno facendo le valigie per lasciare la città? Per aver compiuto l'impresa, Otho ti promette un grande mojo."}},faq={{q="Chi ti manda a piantare la lancia?",a="Otho Moji'ko ti manda dal Villaggio degli Zannatorta.",al={"datore di missione","chi assegna la missione","otho mojiko"}},{q="Dove deve essere piantata la lancia?",a="Pianta la lancia accanto al pozzo, nel cuore del Picco dell'Aquila, a ovest delle Entroterre.",al={"posizione lancia","dove posiziono la lancia","pozzo picco dell'aquila"}},{q="Di cosa è fatto il messaggio finale?",a="Il messaggio finale è una lancia intrisa di sangue e legata con piume di grifone.",al={"cos'è la lancia","lancia con piume di grifone","oggetto il messaggio finale"}},{q="Cosa c'era prima nella catena?",a="Prima è arrivato Another Message to the Wildhammer. Per preparare questo messaggio finale, Otho ha chiesto delle piume di grifone.",al={"missione precedente","prerequisiti","catena messaggio wildhammer"}}},fp="35,185,22.351.0,11.208.1,33.46.0,32.91.0,34.77.0,35.106.0"}
P.entries["quest:7844"] = {n="Cannibalistic Cousins",s="Nelle Entroterre, la Mistica Yayo'jin ti chiede di colpire i Vilebranch vicino ai loro templi. Li definisce una stirpe depravata che preda altri troll e umanoidi. Zul'jin è lontano e gli Zannatorta sono lasciati a se stessi.",h="Nelle Entroterre, la Mistica Yayo'jin ti chiede di colpire i Vilebranch vicino ai loro templi.",kw={"agol'watha","cannibalistic cousins","mistica yayo'jin","villaggio degli zannatorta","scalper","shaol'watha","soothsayer","vilebranch","zul'jin"},sec={{t="Tre tribù, una terra",b="Tre tribù di troll condividono le Entroterre, anche se la Mistica Yayo'jin dice che ben poco le lega. I Vilebranch predano altri troll e umanoidi. Zul'jin potrebbe spazzarli via con facilità, ma è lontano. Così gli Zannatorta sono lasciati a se stessi."},{t="Dove si radunano i Vilebranch",b="Yayo'jin ti chiede di distruggere gli Scalpers e i Soothsayers Vilebranch vicino ai templi di Shaol'watha e Agol'watha. I templi si trovano a nord-nord-est delle Entroterre."},{t="Le lodi di Yayo'jin",b="Al tuo ritorno, Yayo'jin dice che nemmeno Zul'jin avrebbe potuto fare di meglio."}},faq={{q="Chi offre questa missione?",a="La Mistica Yayo'jin la offre dal Villaggio degli Zannatorta.",al={"datore di missione cannibalistic cousins","chi fornisce cannibalistic cousins","mistica yayojin"}},{q="Perché Yayo'jin vuole che i Vilebranch vengano distrutti?",a="Yayo'jin definisce i Vilebranch una stirpe depravata che preda altri troll e umanoidi. Dice che spetta a te distruggere la feccia della regione.",al={"perché gli zannatorta combattono i vilebranch","cannibalismo dei vilebranch","conflitto zannatorta vilebranch"}},{q="Dove si possono trovare i troll Vilebranch?",a="I Vilebranch si radunano attorno ai templi di Shaol'watha e Agol'watha, a nord-nord-est delle Entroterre.",al={"posizione di shaolwatha","posizione di agolwatha","dove si trovano i soothsayers vilebranch"}},{q="Quali Vilebranch Yayo'jin vuole che vengano distrutti?",a="Yayo'jin vuole che tu distrugga gli Scalpers e i Soothsayers Vilebranch.",al={"obiettivi di cannibalistic cousins","chi devo uccidere per cannibalistic cousins"}},{q="Dov'è Zul'jin?",a="Zul'jin non si trova nelle Entroterre. Yayo'jin dice che potrebbe spazzare via i Vilebranch con facilità, ma è lontano e gli Zannatorta sono lasciati a se stessi.",al={"zuljin è qui","dov'è zuljin nelle entroterre","stato di zul'jin"}}},fp="21,226,22.242.0,27.169.0,17.71.1,22.49.0,48.137.0,41.108.0,46.76.0,17.152.0"}
P.entries["quest:7845"] = {n="Kidnapped Elder Torntusk!",s="Al Villaggio degli Zannatorta, la Primalista Zannaculea ti chiede di salvare il suo compagno dopo un'audace incursione notturna. Le sue spie dicono che l'Anziano Zannaculea è vivo in cima a Jintha'alor.",h="Al Villaggio degli Zannatorta, la Primalista Zannaculea ti chiede di salvare il suo compagno dopo un'audace...",kw={"anziano zannaculea","hakkar","hexx","hinterland","jintha'alor","primalista zannaculea","zannatorta","zannaculea","vilebranch"},sec={{t="Un'incursione notturna",b="I selvaggi Vilebranch hanno colpito il Villaggio degli Zannatorta a mezzanotte e hanno rapito l'Anziano Zannaculea, compagno della Primalista Zannaculea. Le sue spie dicono che è vivo, prigioniero in cima a Jintha'alor, capitale dei Vilebranch nelle Hinterland meridionali. La Primalista Zannaculea teme che il villaggio non riuscirebbe a sopportare la sua perdita."},{t="Il Dio del Sangue senza volto",b="Si dice che la Vile Sacerdotessa Hexx stia preparando l'Anziano Zannaculea per il sacrificio a Hakkar, il Dio del Sangue senza volto."},{t="Una volta raggiunto",b="L'Anziano Zannaculea è a portata di mano, ma le guardie sanno sicuramente che sei arrivato. Muoviti in fretta."}},faq={{q="Chi ha rapito l'Anziano Zannaculea?",a="I selvaggi Vilebranch hanno rapito l'Anziano Zannaculea con un'audace incursione notturna al Villaggio degli Zannatorta.",al={"chi ha rapito l'anziano zannaculea","chi ha preso zannaculea","rapitori di zannaculea"}},{q="Dove è tenuto prigioniero l'Anziano Zannaculea?",a="Le spie della Primalista Zannaculea dicono che l'Anziano Zannaculea è prigioniero in cima a Jintha'alor, capitale dei Vilebranch nelle Hinterland meridionali.",al={"posizione anziano zannaculea","dov'è l'anziano zannaculea","dov'è tenuto prigioniero zannaculea"}},{q="Quale destino attende l'Anziano Zannaculea in cima a Jintha'alor?",a="Sacrificio. Si dice che la Vile Sacerdotessa Hexx stia preparando l'Anziano Zannaculea come offerta a Hakkar, il Dio del Sangue senza volto.",al={"perché zannaculea è stato catturato","cosa vogliono i vilebranch da zannaculea","hexx sacrificio zannaculea"}},{q="Chi è la Primalista Zannaculea?",a="La Primalista Zannaculea è la compagna dell'Anziano Zannaculea e ti chiede di salvarlo.",al={"chi è la primalista zannaculea","compagna primalista zannaculea"}}},fp="25,147,15.279.0,22.107.0,18.90.1,24.84.0,35.126.0,49.120.0,23.71.0"}
P.entries["quest:7846"] = {n="Recover the Key!",s="A Jintha'alor, l'Anziano Zannaculea è incatenato e ti chiede di liberarlo. Hitah'ya la Custode tiene la Chiave Infernale in una caverna sorvegliata lì vicino.",h="A Jintha'alor, l'Anziano Zannaculea è incatenato e ti chiede di liberarlo.",kw={"anziano zannaculea","hinterland","hitah'ya la custode","jintha'alor","recupera la chiave","revantusk","chiave dei ceppi"},sec={{t="La caverna della Custode",b="Dopo Kidnapped Elder Torntusk!, trovi l'Anziano Zannaculea incatenato a Jintha'alor. Hitah'ya la Custode custodisce la Chiave Infernale che lo tiene legato in una caverna vicina, ben sorvegliata. L'Anziano Zannaculea ti chiede di ucciderla e riportargli la chiave. Così potrà allentare le catene e tornare a casa."},{t="I ringraziamenti dell'Anziano Zannaculea",b="Con la chiave, l'Anziano Zannaculea si rialza. Ti ringrazia e dice che i Revantusk verranno a sapere delle tue imprese."}},faq={{q="Chi possiede la chiave per i vincoli dell'Anziano Zannaculea?",a="Hitah'ya la Custode tiene la Chiave Infernale che incatena l'Anziano Zannaculea. Lui dice che si trova in una caverna vicina, ben sorvegliata.",al={"chi possiede la chiave","hitahya la custode","dove si trova la chiave dei ceppi"}},{q="Dove è tenuto l'Anziano Zannaculea?",a="L'Anziano Zannaculea è tenuto a Jintha'alor.",al={"dove si trova l'anziano zannaculea","posizione di zannaculea","zannaculea jintha'alor"}},{q="Perché l'Anziano Zannaculea ha bisogno della chiave?",a="La Chiave Infernale apre le catene dell'Anziano Zannaculea. Dice che potrà tornare a casa una volta libero.",al={"perché la chiave dei ceppi","a cosa serve la chiave"}}},fp="16,128,17.285.0,23.108.1,47.123.0,29.38.0,37.84.0"}
P.entries["quest:7847"] = {n="Return to Primal Torntusk",s="L'Anziano Zannaculea è libero e ti manda al Villaggio degli Zannatorta con un messaggio per la sua compagna, Primalista Zannaculea.",h="L'Anziano Zannaculea è libero e ti manda al Villaggio degli Zannatorta con un messaggio per la sua compagna...",kw={"anziano zannaculea","entroterre","jintha'alor","primalista zannaculea","zannatorta","villaggio degli zannatorta"},sec={{t="Notizie per la sua compagna",b="L'Anziano Zannaculea è libero dai suoi vincoli e ti chiede di tornare al Villaggio degli Zannatorta. Di' alla sua compagna, Primalista Zannaculea, che sta tornando a casa."},{t="Il villaggio è riconoscente",b="Primalista Zannaculea ti ringrazia per aver servito gli Zannatorta. Il villaggio ti deve un profondo debito di gratitudine."}},faq={{q="Chi ti manda in questo viaggio?",a="L'Anziano Zannaculea ti manda a portare alla sua compagna la notizia del suo salvataggio.",al={"chi inizia return to primal torntusk","anziano zannaculea datore di missione"}},{q="Dove si trova Primalista Zannaculea?",a="Primalista Zannaculea si trova al Villaggio degli Zannatorta nelle Entroterre.",al={"dove si trova primalista zannaculea","posizione primalista zannaculea","dove consegnare return to primal torntusk"}},{q="Cosa devo dire a Primalista Zannaculea?",a="Di' a Primalista Zannaculea che l'Anziano Zannaculea sta tornando a casa.",al={"cosa dire a primalista zannaculea","messaggio zannaculea"}},{q="Cosa precede questo viaggio?",a="Questo fa seguito a Recover the Key!, dopo il tentativo precedente iniziato con Kidnapped Elder Torntusk!.",al={"missione precedente","catena missioni primalista zannaculea"}}},fp="25,98,17.139.0,23.100.1,30.65.0,33.59.0,43.56.0,30.96.0"}
P.entries["quest:7849"] = {n="Separation Anxiety",s="Il Predatore Markhor piange il suo gemello Malkhor nel Villaggio degli Zannatorta. I Vilebranch rapirono Malkhor durante l'incursione in cui presero anche la compagna di Zannatorta. Markhor crede che la sua anima possa ancora essere salvata, anche se la sua vita non lo è più. Per questo ti chiede di recuperare i resti.",h="Il Predatore Markhor piange il suo gemello Malkhor nel Villaggio degli Zannatorta.",kw={"ossa","hinterland","jintha'alor","malkhor","markhor","revantusk","teschio","vilebranch","yayo'jin"},sec={{t="La perdita di un gemello",b="Molti nel Villaggio degli Zannatorta hanno perso persone care nelle terre selvagge, dice Markhor. Lui piange il suo fratello gemello, Malkhor. I Vilebranch rapirono Malkhor durante l'incursione in cui presero anche la compagna di Zannatorta. I suoi rapitori lo uccisero in modo rapido e brutale; non era destinato a sopravvivere."},{t="Dove giacciono i resti",b="I Vilebranch diedero in pasto i resti di Malkhor alle loro melme e ai loro lupi. Vicino alla sommità del tempio di Jintha'alor si trovano una discarica piena di melme e una tana di lupi. Le sue ossa riposano in una fossa di fanghiglia vicino al terrazzamento superiore, mentre il suo teschio giace sul terrazzamento stesso. Markhor intende portare i resti a Yayo'jin, che li preparerà per una degna sepoltura."}},faq={{q="Chi era il Predatore Malkhor?",a="Malkhor era il fratello gemello del Predatore Markhor. I Vilebranch lo rapirono durante l'incursione in cui presero anche la compagna di Zannatorta, poi lo uccisero in modo rapido e brutale.",al={"chi è malkhor","fratello di markhor","storia di malkhor"}},{q="Dove sono stati portati i resti di Malkhor?",a="I Vilebranch diedero in pasto i resti di Malkhor alle loro melme e ai loro lupi. Il suo teschio giace sul terrazzamento superiore di Jintha'alor, mentre le sue ossa riposano in una fossa di fanghiglia nei pressi.",al={"dove sono le ossa","dov'è il teschio di malkhor","resti di jintha'alor"}},{q="Chi preparerà Malkhor per la sepoltura?",a="Markhor porterà i resti di Malkhor a Yayo'jin, che li preparerà per una degna sepoltura.",al={"sepoltura per malkhor","chi è yayojin","yayo'jin"}},{q="Perché Markhor vuole che le ossa vengano restituite?",a="Markhor dice che la vita di Malkhor non può più essere salvata, ma la sua anima sì. Vuole che i resti vengano recuperati affinché l'anima di Malkhor possa essere salvata.",al={"perché recuperare i resti","salvare l'anima di malkhor","salvare la sua anima"}}},fp="18,263,13.260.0,21.338.0,25.150.0,35.158.0,36.91.0,41.148.0"}
P.entries["quest:7850"] = {n="Dark Vessels",s="Nel Villaggio degli Zannatorta, il Primalista Zannaculea dice che i Vilebranch combattono con una furia innaturale. Incolpa la magia immonda della Vile Priestess Hexx e ti chiede di prendere i recipienti di sangue corrotto da Jintha'alor, così potrà purificarli.",h="Nel Villaggio degli Zannatorta, il Primalista Zannaculea dice che i Vilebranch combattono con una furia...",kw={"dio del sangue","dark vessels","jintha'alor","primalista zannaculea","villaggio degli zannatorta","sangue corrotto","vile priestess hexx","vilebranch"},sec={{t="La furia dei Vilebranch",b="Per tutta Jintha'alor, i recipienti di sangue corrotto recano il potere del dio del sangue senza volto. Quel potere rafforza i Vilebranch e li fa impazzire. Zannaculea crede che allontanare i recipienti e purificarli allenterà la presa del dio del sangue sui troll."},{t="Dopo il ritorno dei contenitori",b="Restituire i recipienti libera i Vilebranch dall'energia oscura che li costringe, anche se solo per ora. Zannaculea ti avverte di stare in guardia dal male, perché una sacerdotessa caduta viene presto sostituita da un'altra."}},faq={{q="Chi assegna la missione Dark Vessels?",a="Il Primalista Zannaculea ti chiede aiuto nel Villaggio degli Zannatorta, nelle Entroterre.",al={"chi dà dark vessels","chi assegna dark vessels"}},{q="Dove si trovano i contenitori corrotti?",a="I recipienti di sangue corrotto si trovano per tutta Jintha'alor, nelle Entroterre.",al={"dove sono i dark vessels","posizione contenitori di sangue corrotto","trovare sangue corrotto"}},{q="Perché i troll Vilebranch sono così feroci?",a="Il Primalista Zannaculea incolpa la magia immonda della Vile Priestess Hexx. I recipienti di sangue corrotto recano anche il potere del dio del sangue senza volto, che rafforza i Vilebranch e li fa impazzire.",al={"perché i vilebranch sono pazzi","follia dei vilebranch","ferocia dei vilebranch"}},{q="Cosa intende fare il Primalista Zannaculea con i contenitori?",a="Zannaculea intende purificare i recipienti e allentare la presa del dio del sangue senza volto sui Vilebranch.",al={"perché raccogliere i contenitori","cosa succede ai contenitori di sangue"}}},fp="12,227,19.251.0,24.181.1,33.66.0,38.72.0,43.184.0,54.97.0"}
P.entries["quest:786"] = {n="Thwarting Kolkar Aggression",s="Lar Zannacelata ha scoperto un piano per colpire gli insediamenti di Durotar e Orgrimmar. I centauri Kolkar hanno diviso i piani d'invasione tra tre capi a Kolkar Crag, a ovest del Villaggio di Sen'jin.",h="Lar Zannacelata ha scoperto un piano per colpire gli insediamenti di Durotar e Orgrimmar.",kw={"durotar","kolkar","kolkar crag","lar zannacelata","orgrimmar","villaggio di sen'jin","thwarting kolkar aggression","valle delle sfide"},ang={["faction:Horde"]="Fermare l'offensiva dei Kolkar risparmia alla giovane Orda una battaglia estenuante su più fronti, alle soglie della sua nuova casa.",["race:Orc"]="Se sei un orco, sai che la Valle delle Sfide è il luogo in cui i giovani orchi affrontano i riti di passaggio all'età adulta. L'aggressione dei centauri è un insulto alla cultura guerriera degli orchi.",["race:Troll"]="Se sei un troll Puntascura, sai che il Villaggio di Sen'jin non può cadere sotto un attacco dei centauri, dopo che il tuo popolo ha perso la sua antica isola."},sec={{t="Un'invasione incombente",b="Lar Zannacelata è un inseguitore troll che esplora la parte occidentale di Durotar. Col favore delle tenebre, si è introdotto a Kolkar Crag e ha scoperto che i centauri Kolkar preparavano qualcosa di più di sporadiche incursioni costiere. Tre capi sono in possesso dei piani d'invasione. I loro obiettivi sono la Valle delle Sfide, il Villaggio di Sen'jin e i Gates of Orgrimmar."},{t="Colpire i canyon",b="I capi Kolkar custodiscono tre pergamene d'attacco nei loro accampamenti, tra gli aridi canyon di Kolkar Crag. Ti viene affidato il compito di distruggerle prima che i centauri possano colpire. Lar Zannacelata crede che l'Orda potrebbe sconfiggere un'invasione su vasta scala, ma bruciare i piani può risparmiare ai difensori di Durotar combattimenti costosi mentre la loro giovane nazione muove i primi passi."}},faq={{q="Chi offre la missione Thwarting Kolkar Aggression?",a="Lar Zannacelata, esploratore troll Puntascura, ti affida l'incarico appena fuori dal Villaggio di Sen'jin, lungo le scogliere meridionali di Durotar.",al={"datore di missione","chi assegna la missione","posizione di lar zannacelata"}},{q="Quali obiettivi pianificano di attaccare i centauri Kolkar?",a="I piani Kolkar indicano come obiettivi la Valle delle Sfide, il Villaggio di Sen'jin e Orgrimmar.",al={"obiettivi dei centauri","cosa sono i piani d'attacco","tre obiettivi"}},{q="Dove si trova Kolkar Crag?",a="Kolkar Crag si trova a ovest del Villaggio di Sen'jin, oltre le creste rocciose nella parte meridionale di Durotar.",al={"posizione di kolkar crag","dove si trova il crag","minaccia centaura a durotar"}},{q="Dove si trovano i piani d'attacco all'interno del crag?",a="Tre capi Kolkar custodiscono le pergamene d'invasione nei loro accampamenti sparsi per il promontorio.",al={"posizione dei piani d'attacco","dove sono le pergamene","leader centauri"}},{q="Perché i Kolkar vogliono invadere Durotar?",a="I Kolkar sono un clan di centauri aggressivo, originario delle terre aride di Kalimdor. Considerano gli orchi e i troll Puntascura appena arrivati degli intrusi nel loro territorio e nei loro terreni di caccia.",al={"perché i centauri attaccano","motivo dei centauri","folclore kolkar"}},{q="Cosa succede dopo che i piani vengono distrutti?",a="Distruggere i piani intralcia l'attacco coordinato dei Kolkar e protegge gli insediamenti di Durotar da un assedio improvviso.",al={"conseguenze della missione","fine dell'attacco centauro"}}},fx={a839716d={q="Perché Lar Zannacelata vuole che i piani d'attacco vengano distrutti?",a="Lar Zannacelata ha esplorato Kolkar Crag e scoperto che i centauri stanno preparando un'invasione su tre fronti, diretta contro il Villaggio di Sen'jin, la Valle delle Sfide e Orgrimmar stessa. Sebbene l'Orda finirebbe per schiacciare un simile attacco, Zannacelata vuole che i loro piani operativi vengano bruciati per fermare l'invasione prima che cominci, risparmiando ai difensori di Durotar inutili spargimenti di sangue e disordini.",al={"perché distruggere i piani d'attacco","motivazioni di lar zannacelata","perché fermare l'aggressione dei kolkar"}},["4d134dbe"]={q="Chi sono i centauri Kolkar di Kolkar Crag?",a="I Kolkar sono un clan brutale di centauri che ha stabilito una roccaforte nelle rupi lungo il crinale occidentale di Durotar. Fieri e territoriali, nutrono un profondo odio per gli orchi appena arrivati e i Troll Lanciascura, lanciando regolarmente incursioni dal loro accampamento e tramando per cacciare completamente l'Orda dalla regione.",al={"chi sono i kolkar qui","centauri di kolkar crag","perché i kolkar sono a durotar"}}},fp="27,194,18.307.0,20.334.0,49.118.0,55.86.0,29.86.0,49.80.0,41.174.0,43.117.0"}
P.entries["quest:7861"] = {n="Wanted: Vile Priestess Hexx and Her Minions",s="Il Primalista Zannaculea ti ha mandato a Jintha'alor per consegnare alla giustizia Vile Priestess Hexx e i suoi servitori. Offre un ricco premio per aver ucciso Hexx e la sua guardia d'élite Aman'zasi.",h="Il Primalista Zannaculea ti ha mandato a Jintha'alor per consegnare alla giustizia Vile Priestess Hexx e i...",kw={"aman'zasi","hexx","entroterre","jintha'alor","primalista zannaculea","villaggio degli zannatorta","vile priestess hexx","vilebranch"},sec={{t="Un colpo a Jintha'alor",b="Il Primalista Zannaculea ti manda a caccia di Vile Priestess Hexx e dei suoi servitori. Si trovano in cima a Jintha'alor, nelle Entroterre, dove Hexx è affiancata dalle sue guardie d'élite Aman'zasi. Uccidili, poi fai rapporto a Zannaculea al Villaggio degli Zannatorta."}},faq={{q="Chi ha offerto la taglia per la Vile Priestess Hexx?",a="Il Primalista Zannaculea ha ordinato la taglia e offre un ricco premio per aver ucciso la sacerdotessa e la sua guardia.",al={"chi vuole hexx morta","chi ha offerto questa taglia","datore missione sacerdotessa hexx"}},{q="Dove si possono trovare la Vile Priestess Hexx e le sue guardie?",a="Vile Priestess Hexx e le sue guardie si trovano in cima a Jintha'alor, nelle Entroterre.",al={"dove si trova hexx","posizione vile priestess hexx","posizione guardie amanzasi"}},{q="Chi deve essere ucciso per completare la taglia?",a="Uccidi Priestess Hexx e la sua guardia d'élite Aman'zasi dei Vilebranch.",al={"obiettivi taglia hexx","chi uccidere per hexx"}},{q="Dove viene consegnata la taglia?",a="Dopo aver ucciso la sacerdotessa e la sua guardia, fai rapporto al Primalista Zannaculea al Villaggio degli Zannatorta.",al={"dove consegnare la taglia di hexx","posizione primalista zannaculea"}}},fp="43,172,23.223.0,46.100.0,54.75.0,40.68.0,30.90.0"}
P.entries["quest:7862"] = {n="Job Opening: Guard Captain of Revantusk Village",s="Il Villaggio degli Zannatorta cerca un nuovo capitano della guardia. I candidati devono dimostrare il proprio valore contro quattro tipi di Vilebranch e presentare una candidatura al Primalista Zannaculea.",h="Il Villaggio degli Zannatorta cerca un nuovo capitano della guardia.",kw={"berserker","bevitore di sangue","capitano della guardia","malkhor","villaggio degli zannatorta","cacciatore dell'ombra","divoratore di anime","zannaculea","vilebranch"},sec={{t="Un posto vacante",b="Il Capitano della Guardia Malkhor è andato perduto, lasciando ancora una volta la guardia del Villaggio degli Zannatorta senza un capitano. L'avviso invita chiunque voglia guidarla a svolgere il compito e a inviare una candidatura al Primalista Zannaculea."},{t="Dimostrare il proprio valore",b="Per candidarti al ruolo di capitano, sconfiggi i Berserker, i Cacciatori dell'Ombra, i Bevitori di Sangue e i Divoratori di Anime dei Vilebranch. Poi torna dal Primalista Zannaculea al Villaggio degli Zannatorta."}},faq={{q="Perché la posizione di Capitano della Guardia è libera?",a="Il Capitano della Guardia Malkhor è andato perduto, lasciando di nuovo vacante il posto di capitano.",al={"perché la posizione di capitano della guardia è libera","cosa è successo a malkhor","chi era il precedente capitano"}},{q="Chi riceve la candidatura una volta uccisi i nemici?",a="Porta la candidatura al Primalista Zannaculea al Villaggio degli Zannatorta.",al={"a chi devo consegnare la missione","dove inviare la candidatura","chi valuta i candidati"}},{q="Quali nemici devono essere sconfitti per qualificarsi?",a="I candidati devono sconfiggere i Berserker, i Cacciatori dell'Ombra, i Bevitori di Sangue e i Divoratori di Anime dei Vilebranch.",al={"quali vilebranch uccidere","obiettivi offerta di lavoro","chi devo uccidere per capitano della guardia"}}},fp="47,162,13.211.0,13.153.0,42.67.0,56.62.0,42.93.0"}
P.entries["quest:787"] = {n="La Nuova Orda",s="Nella Valle delle Sfide, Eitrigg raduna le nuove reclute dell'Orda all'Antro del Tirocinio. Ti manda da Gornek per addestrarti e ti spiega perché è tornato nell'Orda e cosa Thrall spera che diventi.",h="Nella Valle delle Sfide, Eitrigg raduna le nuove reclute dell'Orda all'Antro del Tirocinio.",kw={"legione infuocata","durotar","eitrigg","gornek","nuova orda","antro del tirocinio","thrall","valle delle sfide"},ang={["faction:Horde"]="Per l'Orda, il governo di Thrall segna la fine della servitù demoniaca e il ritorno all'onore, alla sopravvivenza e all'identità ancestrale.",["race:Orc"]="Da orco appena giunto nella Valle delle Sfide, incontri Eitrigg, che ricorda il tragico passato del tuo popolo e la sua redenzione sotto Thrall.",["race:Troll"]="Da troll dei Puntascura, ti addestri al fianco degli orchi nella Valle delle Sfide e condividi la visione di Thrall, fondata sulla sopravvivenza e sull'onore."},sec={{t="Il ritorno di un veterano",b="Agli ordini del Capoguerra Thrall, Eitrigg sorveglia le nuove promesse nella Valle delle Sfide. Dopo la Seconda Guerra, lasciò la Vecchia Orda, disgustato dalla corruzione causata dalla Legione Infuocata. Visse in esilio tranquillo finché gli umani non lo catturarono. Thrall liberò Eitrigg, e il veterano tornò quando seppe del sogno del giovane Capoguerra: un'Orda onorevole, radicata nello sciamanesimo ancestrale e libera dai padroni demoniaci."},{t="Presentarsi all'Antro del Tirocinio",b="Prima di lasciare gli aspri canyon della Valle delle Sfide, Eitrigg ti manda alla caverna ombreggiata chiamata Antro del Tirocinio per parlare con Gornek. Gornek parla senza mezzi termini di quanto siano grezzi i nuovi aspiranti. Sorveglia il loro addestramento affinché solo chi padroneggia la disciplina e la sopravvivenza raggiunga le terre più vaste di Durotar."}},faq={{q="Chi è Eitrigg?",a="Eitrigg è un veterano orco ormai anziano che ha visto la Vecchia Orda soccombere alla corruzione della Legione Infuocata. Disilluso, si ritirò in un tranquillo esilio a Lordaeron. Gli umani lo catturarono, ma Thrall in seguito lo liberò. Eitrigg giurò fedeltà all'Orda riformata di Thrall e ora aiuta ad addestrare le reclute nella Valle delle Sfide.",al={"chi è eitrigg","storia di eitrigg","lore di eitrigg"}},{q="Perché Eitrigg parla della «Nuova Orda»?",a="L'Orda originale soccombette alla sete di sangue demoniaca e all'influenza della Legione Infuocata. La Nuova Orda di Thrall rifiutò il controllo demoniaco, ripristinò le antiche tradizioni sciamaniche e cercò un futuro onorevole e indipendente per gli orchi e i loro alleati a Kalimdor.",al={"cos'è la nuova orda","differenza tra vecchia e nuova orda","significato di nuova orda"}},{q="Dove si trova Gornek?",a="Gornek attende appena dentro l'ingresso dell'Antro del Tirocinio, in una caverna ben visibile scavata nella parete rocciosa settentrionale della Valle delle Sfide.",al={"dove si trova gornek","trovare gornek","posizione di gornek"}},{q="Cosa succede dopo essersi presentati a Gornek?",a="Dopo aver riferito a Gornek, lui ti accetta tra gli allievi di Eitrigg e ti assegna le prime missioni sul campo. Difendi la valle e dimostra di essere pronto a servire l'Orda.",al={"missione successiva a la nuova orda","cosa fa gornek","missione di gornek"}},{q="Perché Eitrigg è stato esiliato?",a="Eitrigg lasciò l'Orda, disgustato dalla sua corruzione demoniaca e dalle stragi insensate compiute durante le guerre precedenti dagli stregoni al servizio della Legione Infuocata.",al={"perché eitrigg se n'è andato","motivo dell'esilio di eitrigg","corruzione demoniaca di eitrigg"}},{q="Perché le reclute vengono addestrate nella Valle delle Sfide?",a="La Valle delle Sfide offre ai giovani orchi e ai nuovi arrivati alleati un luogo isolato e impervio a Durotar, dove affrontare bestie pericolose e scorpidi sotto la supervisione di addestratori veterani, prima di avventurarsi nel mondo più vasto.",al={"perché la valle delle sfide","scopo della valle delle sfide","addestramento nella valle delle sfide"}}},fx={["42eb0b46"]={q="Perché Eitrigg ti manda da Gornek?",a="Il Capoguerra Thrall ha incaricato Eitrigg di supervisionare l'addestramento di tutte le nuove reclute che arrivano nella Valle delle Sfide. Eitrigg dà il benvenuto ai nuovi arrivati e infonde loro gli ideali di un'Orda libera dalla corruzione demoniaca, mentre Gornek si occupa delle prove pratiche necessarie a metterti alla prova e temprarti. Eitrigg ti manda da lui affinché le tue prove e il tuo addestramento possano ufficialmente cominciare.",al={"perché andare da gornek","motivazioni di eitrigg","perché fare rapporto a gornek"}}},fp="13,193,18.420.0,20.300.0,15.309.0,44.243.0,24.115.0,39.181.0,23.158.0,49.204.0"}
P.entries["quest:789"] = {n="Sting of the Scorpid",s="All’Antro del Tirocinio, nella Valle delle Sfide, Gornek manda le nuove reclute dell’Orda a cacciare scorpidi a nord-ovest dell’accampamento. Dieci code dimostreranno che sanno affrontare i pericoli in battaglia.",h="All’Antro del Tirocinio, nella Valle delle Sfide, Gornek manda le nuove reclute dell’Orda a cacciare scorpidi...",kw={"antidoto","durotar","gornek","scorpide","scorpide operaio","sting of the scorpid","antro del tirocinio","valle delle sfide","veleno"},ang={["class:Warrior"]="Da guerriero, impari da Gornek che colpi decisi possono superare carapaci resistenti. L’arroganza verso i nemici più piccoli porta alla sconfitta.",["race:Orc"]="Da giovane orco che raggiunge la maggiore età nella Valle delle Sfide, affronti una prova fondamentale di resistenza e attenzione sul campo di battaglia sotto lo sguardo di Gornek.",["race:Troll"]="Da troll dei Puntascura che si addestra al fianco dell’Orda nella Valle delle Sfide, dimostri la tua abilità contro gli scorpidi locali prima di avventurarti più a fondo nel Durotar."},sec={{t="Prova del Pungiglione",b="Gornek mette alla prova le reclute inesperte dell’Orda contro la fauna della Valle delle Sfide. Gli scorpidi operai si aggirano tra le rocce a nord-ovest dell’Antro del Tirocinio. Il loro veleno ha umiliato tanto guerrieri esperti quanto iniziati maldestri. Le reclute devono affrontarli e riportare dieci code come prova della loro abilità."},{t="Veleno e Vigilanza",b="Gli scorpidi sono pericolosi, ma il loro veleno aiuta anche a salvare gli iniziati feriti. All’Antro del Tirocinio si prepara un antiveleno dal veleno estratto dagli scorpidi, per curare i novizi caduti. Gornek insegna alle reclute a restare vigili in battaglia. Anche un nemico piccolo può avere abbastanza veleno da abbattere un possente guerriero."}},faq={{q="Chi assegna Sting of the Scorpid?",a="Gornek supervisiona l’addestramento dei novizi all’Antro del Tirocinio, nella Valle delle Sfide. Affida la caccia ai giovani guerrieri e avventurieri.",al={"chi assegna sting of the scorpid","chi dà la missione degli scorpidi","missione di gornek"}},{q="Dove si trovano gli scorpidi?",a="Gli scorpidi operai si aggirano a nord-ovest dell’Antro del Tirocinio, nella Valle delle Sfide.",al={"dove trovare gli scorpidi","posizione degli scorpidi","scorpidi della valle delle sfide"}},{q="Cosa richiede Gornek dalla caccia?",a="Gornek richiede dieci code di scorpidi operai come prova che una recluta ha affrontato e sconfitto le bestie velenose.",al={"cosa lasciano gli scorpidi","oggetto della missione degli scorpidi","code di scorpide"}},{q="Come viene creato l'antidoto per il veleno di scorpide?",a="All’Antro del Tirocinio si prepara un antiveleno dal veleno estratto dai pungiglioni degli scorpidi. Se ne tengono scorte per curare i novizi che sottovalutano la preda.",al={"cura per il veleno di scorpide","lore dell'antidoto","come viene fatto l'antidoto per scorpidi"}},{q="Quale lezione vuole che imparino le reclute da Gornek?",a="Gornek insegna alle reclute che qualsiasi avversario, grande o piccolo, può essere letale. L’eccessiva sicurezza contro un nemico che sembra insignificante può rivelarsi fatale.",al={"lezione di gornek","perché cacciare gli scorpidi","scopo della prova degli scorpidi"}},{q="Gornek offre ulteriore addestramento dopo questa caccia?",a="Dopo aver consegnato le code, Gornek dice che non ha più nulla da insegnarti all’Antro del Tirocinio. Ti manda a proseguire nel Durotar al servizio dell’Orda.",al={"cosa succede dopo sting of the scorpid","prossima missione di gornek","gornek offre altro addestramento"}}},fp="20,154,20.271.0,19.277.0,33.122.0,31.66.0,39.103.0,46.138.0,47.135.0,51.138.0"}
P.entries["quest:79"] = {n="Leggenda di Stalvan",s="A Borgoscuro, La leggenda di Stalvan si fonda su pagine infangate e nuove prove. Il Taverniere Smitts ti consegna le pagine e ti manda dalla Comandante Althea Serranero.",h="A Borgoscuro, La leggenda di Stalvan si fonda su pagine infangate e nuove prove.",kw={"borgoscuro","boscovespro","serranero","indagine","mistmantle","diario infangato","the night watch","smitts","stalvan"},ang={["class:Paladin"]="Da paladino, riporti alla luce omicidi sepolti da tempo e chiedi giustizia per le vite innocenti strappate nelle ombre di Boscovespro.",["class:Rogue"]="Da ladro, ricomponi i campioni di calligrafia raccolti nelle taverne e nei bauli polverosi, seguendo una preda sfuggente con paziente lavoro investigativo.",["faction:Alliance"]="Da eroe dell'Alleanza, aiuti i territori meridionali a perseguire la giustizia quando manca il sostegno ufficiale di Roccavento."},sec={{t="Una svolta a Borgoscuro",b="Il Taverniere Smitts e Marshal Haggard indagarono un tempo sul massacro di una famiglia nobile in visita a Boscovespro. Haggard guidava allora la Guardia di Roccavento. Sul luogo del delitto trovarono pagine di diario strappate e infangate, ma non avevano campioni di calligrafia né altri documenti per confermare chi le avesse scritte. Perciò, gli appunti non potevano incriminare ufficialmente il recluso che si diceva vivesse nella natura selvaggia.\n\nOra, le prove raccolte a Elwynn, nelle Marche Occidentali e a Boscovespro collegano la calligrafia a Stalvan Mistmantle. Le vecchie voci sono diventate prove di omicidio."},{t="Portare la questione alla Guardia",b="La Comandante Althea Serranero guida la Night Watch mentre Borgoscuro affronta non morti, bestie feroci e orrori ancora peggiori nella foresta. Con la sopravvivenza della città in gioco, ha poco tempo per storie fantasiose o sospetti senza prove. Le porti le pagine infangate di Smitts, affidando un caso irrisolto alla Night Watch. Le pagine raccontano un massacro avvenuto a Boscovespro e danno alla Guardia motivo di considerare Stalvan Mistmantle un pericoloso fuggitivo che deve essere consegnato alla giustizia."}},faq={{q="Quali prove aveva il Taverniere Smitts fin dall'inizio?",a="Anni fa, il Taverniere Smitts e Marshal Haggard trovarono pagine di diario strappate e infangate sul luogo del massacro di alcuni nobili in visita. Fino a oggi, non avevano campioni di calligrafia per provare che le avesse scritte Stalvan Mistmantle.",al={"pagine di diario smitts","pagine di diario infangate","cosa ha trovato smitts"}},{q="Perché Smitts non lo ha riferito prima al Comandante Serranero?",a="Smitts e Haggard non avevano prove che collegassero la calligrafia sulle pagine infangate al tutor recluso. Senza quel legame, potevano portare alla Comandante Serranero solo indizi circostanziali.",al={"perché aspettare così tanto","perché tenere segrete le pagine","perché smitts non l'ha detto alla guardia"}},{q="Chi è il Comandante Althea Serranero?",a="La Comandante Althea Serranero guida la Night Watch, la milizia di Borgoscuro. Le sue guardie proteggono la città e pattugliano le strade di Boscovespro contro i non morti e i predatori dei boschi.",al={"chi è serranero","ruolo di althea serranero","comandante di borgoscuro"}},{q="Quale massacro ha avuto luogo a Boscovespro?",a="Diversi anni fa, una famiglia nobile in visita fu massacrata a Boscovespro. Sebbene le voci accusassero il loro ex tutor, Stalvan Mistmantle, gli investigatori locali non avevano prove per incriminarlo.",al={"quale massacro","massacro dei nobili","chi è stato ucciso"}},{q="Dove si colloca questa fase nell'indagine generale?",a="Dopo aver cercato nei registri, nei documenti scolastici e nelle casse delle famiglie in tre territori, porti le prove alle autorità locali. L'indagine passa così alla giustizia formale e loro hanno motivo di agire contro Stalvan.",al={"fase della catena di missioni di stalvan","a che punto siamo","è la fine della missione"}},{q="Perché la The Night Watch è così riluttante a indagare sui vecchi crimini?",a="Borgoscuro affronta ogni giorno minacce da abomini erranti, branchi di worgen e ragni. La Comandante Serranero deve impiegare le sue guardie per difendere la città, quindi i vecchi crimini richiedono prove inconfutabili prima che possa occuparsene.",al={"perché serranero è occupata","priorità di difesa di borgoscuro","priorità della the night watch"}}},fx={["3928db26"]={q="Perché il Taverniere Smitts vuole che parli con la Comandante Ebonlocke?",a="Smitts segue in silenzio la leggenda di Stalvan da anni, da quando alcuni nobili in visita furono massacrati fuori da Borgoscuro. Quando lui e Haggard ispezionarono la macabra scena, trovarono delle pagine di diario infangate, ma non avevano campioni di calligrafia per collegarle all'eremita dei boschi. Ora che le tue indagini hanno portato alla luce dei campioni che provano la paternità di Stalvan, Smitts possiede finalmente prove inconfutabili dell'identità dell'assassino. Vuole che tu presenti subito la verità, così che i difensori della città possano affrontare ufficialmente l'assassino.",al={"perché smitts ti manda da ebonlocke","motivazioni del taverniere smitts","perché informare subito ebonlocke"}},["225fd2ad"]={q="Perché Smitts manda te invece di fare rapporto di persona?",a="Smitts gestisce il bancone della Taverna del Corvo Scarlatto e aveva soltanto pochi frammenti sconnessi del massacro originale. Sei tu ad aver seguito le tracce attraverso Elwynn, le Marche Occidentali e Boscovespro, recuperando le lettere e i diari che collegano la calligrafia a Stalvan. Poiché hai scoperto gli indizi fondamentali che collegano tutti i pezzi del puzzle, la Comandante Ebonlocke deve ascoltare l'intero resoconto direttamente dall'investigatore che ha dimostrato la colpevolezza di Stalvan.",al={"perché smitts non parla con ebonlocke","perché devo riferire di stalvan","perché devo fare rapporto a ebonlocke"}}},fp="21,154,27.512.0,22.452.1,51.215.0,61.186.0,34.169.0,37.179.0,56.226.0,62.210.0"}
P.entries["quest:79007"] = {n="... and that note you found",s="In un accampamento recente restano solo braci morenti e provviste sparse. Una pergamena bruciacchiata reca un indovinello su come trovare una terra gemella, l’unico indizio rimasto.",h="In un accampamento recente restano solo braci morenti e provviste sparse.",kw={"... e quella nota che hai trovato","nota bruciacchiata","nota carbonizzata","braci","fuoco recente","provviste sparse","terra gemella"},sec={{t="Braci nella natura selvaggia",b="Un falò recente si sta spegnendo accanto a provviste sparse e a un pezzo di carta bruciacchiato. Chiunque si sia fermato qui è partito da poco, e la pergamena è sfuggita per un soffio alle fiamme. Le provviste sono rimaste esposte, come se il viaggiatore fosse partito in fretta o fosse stato interrotto."},{t="Un indovinello criptico",b="Il frammento sopravvissuto reca un’unica istruzione: «Non tutto ciò che brucia è perduto. Trova la terra gemella, trova il luogo.» Il fuoco non ha risparmiato firme, coordinate o altri dettagli. L’indovinello è l’unica traccia rimasta per chi lo trova."}},faq={{q="Cosa dice la nota trovata all'accampamento?",a="La nota bruciacchiata e gonfia recita: «Non tutto ciò che brucia è perduto. Trova la terra gemella, trova il luogo.» È l’unico indizio rimasto nell’accampamento abbandonato.",al={"cosa dice la nota","testo della nota","nota bruciacchiata"}},{q="Chi ha lasciato la nota?",a="L’autore della nota è sconosciuto. È stata trovata tra provviste sparse, accanto alle braci morenti di un falò recente: chi l’ha scritta o portata con sé è partito da poco o è stato costretto ad andarsene in fretta.",al={"da dove viene la nota","chi ha scritto la nota","chi ha acceso il fuoco"}},{q="A cosa si riferisce la 'terra gemella'?",a="La «terra gemella» della nota indica un luogo corrispondente o speculare. Il frammento bruciacchiato non offre altre spiegazioni, e spetta ai viaggiatori svelarne il significato.",al={"cos'è la terra gemella","indizio terra gemella"}},{q="Come segui gli indizi sulla nota?",a="La nota bruciacchiata è la tua unica guida: sulla mappa non è segnata alcuna destinazione. Il suo indovinello ti invita a cercare una terra o un luogo che riecheggi la sua descrizione.",al={"cosa fare con la nota","dove porta questa missione"}},{q="Perché l'accampamento è stato abbandonato?",a="L’accampamento mostra segni di una partenza improvvisa o di un disordine. Accanto alle braci che si spengono giacciono provviste sparse, e non resta altro equipaggiamento o segno identificativo, a parte il frammento bruciacchiato.",al={"chi ha abbandonato le provviste","accampamento con provviste sparse"}},{q="Ci sono altri indizi al fuoco?",a="Al falò non restano altre scritte o segni intatti. Le fiamme hanno distrutto quasi tutto, lasciando solo il foglio bruciacchiato come prova di chi aveva trovato riparo lì.",al={"il fuoco rivela altro","indizi accampamento"}}},fp="27,170,18.258.0,16.233.0,45.156.0,25.202.0,35.159.0,40.148.0,31.183.0,38.169.0"}
P.entries["quest:79008"] = {n="... and that note you found",s="Una nota bruciacchiata giace accanto a un falò morente nelle Marche Occidentali. Il suo breve messaggio indica un luogo chiamato la terra gemella.",h="Una nota bruciacchiata giace accanto a un falò morente nelle Marche Occidentali.",kw={"nota bruciacchiata","falò","nota carbonizzata","braci","nota","terra gemella","marche occidentali"},ang={["class:Rogue"]="Da ladro, sai decifrare gli indizi criptici lasciati negli accampamenti nascosti. Questo lavoro ti viene naturale, perché vivi di sussurri, segreti e messaggi celati.",["faction:Alliance"]="Da avventuriero dell'Alleanza intento a ristabilire l'ordine nelle Marche Occidentali, affronti un altro mistero alla frontiera del regno: un accampamento sconosciuto e un codice enigmatico."},sec={{t="Un fuoco morente",b="Chi attraversa i campi abbandonati e le pianure spazzate dal vento delle Marche Occidentali trova accampamenti lasciati da vagabondi, fuorilegge o viandanti disperati. Questo piccolo accampamento è stato abbandonato in fretta o di nascosto. Le provviste sono state lasciate lì, le braci brillano ancora e tra i detriti sparsi riposa un lembo di pergamena bruciacchiato."},{t="Il messaggio criptico",b="La nota bruciacchiata reca due brevi frasi: «Non tutto ciò che brucia è perduto. Trova la terra gemella, trova il luogo». Le sue parole indicano una direzione lontana dalle Marche Occidentali, ma non danno indicazioni precise. Quale luogo condivide un nome, una geografia o un destino con questa terra?"}},faq={{q="Cosa dice la nota?",a="La nota bruciacchiata recita: «Non tutto ciò che brucia è perduto. Trova la terra gemella, trova il luogo». È l'unico indizio nell'accampamento abbandonato.",al={"testo della nota","cosa c'è scritto sulla nota","parole della nota bruciacchiata"}},{q="Dove si trova questa nota?",a="La nota giace tra i resti di un fuoco e le provviste sparse nelle terre selvagge delle Marche Occidentali.",al={"posizione della nota","dov'è la nota","posizione del falò"}},{q="Chi ha lasciato il falò?",a="Nessuno sa chi abbia lasciato l'accampamento. Chi ha acceso il fuoco se n'è andato da poco, lasciando provviste sparse e il messaggio bruciacchiato tra le braci.",al={"chi ha lasciato la nota","proprietario del falò","autore della nota"}},{q="A cosa si riferisce \"la terra gemella\"?",a="«La terra gemella» indica un'altra regione legata alla terra in cui è stata trovata la nota, ma il messaggio carbonizzato non offre altre spiegazioni.",al={"significato di terra gemella","cos'è la terra gemella","dov'è la terra gemella"}},{q="Perché la nota è stata bruciata?",a="La nota è stata bruciata e carbonizzata dalle braci. Qualcuno potrebbe aver cercato di distruggerla in fretta, oppure averla lasciata lì con noncuranza mentre le fiamme si spegnevano.",al={"perché è stata bruciata","qualcuno ha provato a bruciare la nota","nota carbonizzata"}},{q="È collegata alla Fratellanza dei Defias?",a="Le Marche Occidentali sono invase dalla Fratellanza dei Defias e da occupanti indigenti, ma il messaggio enigmatico suggerisce qualcosa di più oscuro delle solite comunicazioni tra banditi.",al={"nota dei defias","sono i defias","falò della fratellanza"}}},fp="27,115,12.296.0,19.240.0,23.142.0,25.97.0,22.142.0,35.146.0,24.143.0,44.163.0"}
P.entries["quest:7905"] = {n="The Darkmoon Faire",s="Porti un Free Ticket Voucher a Gelvas Grimgate, all'interno del luna park della Darkmoon Faire. Il voucher è per lui.",h="Porti un Free Ticket Voucher a Gelvas Grimgate, all'interno del luna park della Darkmoon Faire.",kw={"luna park","darkmoon faire","free ticket voucher","gelvas grimgate","voucher"},sec={{t="Un voucher per Gelvas",b="Gelvas Grimgate si trova nel luna park della Darkmoon Faire e tu porti un Free Ticket Voucher per lui. Il voucher attende di essere consegnato."}},faq={{q="Per chi è il voucher?",a="Il Free Ticket Voucher è per Gelvas Grimgate, che si trova nel luna park della Darkmoon Faire.",al={"voucher per chi","voucher di gelvas"}},{q="Dov'è Gelvas Grimgate?",a="Gelvas Grimgate si trova nel luna park della Darkmoon Faire.",al={"dov'è gelvas","posizione di gelvas"}},{q="Cosa devo portare a Gelvas?",a="Porta il Free Ticket Voucher a Gelvas Grimgate.",al={"quale voucher","voucher del biglietto"}}},fp="18,116,20.128.0,23.90.0,25.54.0,26.49.0"}
P.entries["quest:79091"] = {n="Archmage Antonidas: The Unabridged Autobiography",s="A Forgiardente cerchi Archmage Antonidas: The Unabridged Autobiography. Questo raro volume contiene il resoconto personale del defunto leader del Kirin Tor e offre uno sguardo sulla storia di Dalaran e sull'alta erudizione arcana.",h="A Forgiardente cerchi Archmage Antonidas: The Unabridged Autobiography.",kw={"antonidas","arcano","arcimago antonidas","autobiografia","dalaran","salone degli esploratori","forgiardente","kirin tor","biblioteca","mago"},ang={["class:Mage"]="L'Arcimago Antonidas fu uno dei più grandi leader del Kirin Tor e un modello di erudizione arcana. La sua vita e i suoi scritti personali offrono preziose informazioni a chiunque pratichi le arti arcane.",["faction:Alliance"]="Antonidas fu un pilastro dell'Alleanza di Lordaeron contro l'Orda degli Orchi e il Flagello. Le sue memorie personali sono una preziosa testimonianza storica in tutte le terre dell'Alleanza.",["race:Dwarf"]="Il tomo proviene dalla grande biblioteca del Salone degli Esploratori di Forgiardente. Gli studiosi che lo ricevono sembrano poco preoccupati di privare gli archivisti nani di un volume così raro.",["race:Human"]="Antonidas era un venerato arcimago umano che guidò il Kirin Tor e Dalaran durante la Seconda e la Terza Guerra. La sua autobiografia integrale è un prezioso frammento della storia umana."},sec={{t="Le Parole del Grande Mago",b="L'Arcimago Antonidas guidò il Kirin Tor per decenni e governò Dalaran. Una delle menti più brillanti di Azeroth, scalò i ranghi della Cittadella Violacea e padroneggiò l'arcano. La sua autobiografia integrale racconta la sua guida durante la Seconda e la Terza Guerra. Per studiosi e praticanti della magia, offre una testimonianza diretta del funzionamento interno di Dalaran e delle arti arcane."},{t="Dalla Grande Biblioteca di Forgiardente",b="Prima di raggiungere la sua nuova dimora, il raro manoscritto riposava nella grande biblioteca di Forgiardente. Nel Salone degli Esploratori, gli archivisti nani lo custodivano accanto ad antichi cimeli dei Titani e alle storie dei nani. Le loro vaste collezioni contengono testi raccolti da rovine e regni stranieri di tutta Azeroth. Eppure, gli studiosi arcani di altri luoghi cercano opere simili per le proprie collezioni, certi che gli indaffarati archivisti non noteranno mai un volume mancante."}},faq={{q="Chi era l'Arcimago Antonidas?",a="L'Arcimago Antonidas guidò il Kirin Tor per molti anni e governò la città-stato magica di Dalaran. Maestro leggendario dell'arcano, fu un consigliere di spicco dell'Alleanza di Lordaeron durante la Seconda Guerra. Mise in guardia Re Terenas sulla piaga, prima di cadere in difesa di Dalaran durante la Terza Guerra.",al={"chi era antonidas","lore dell'arcimago antonidas","storia di antonidas"}},{q="Cos'è l'autobiografia integrale?",a="L'Arcimago Antonidas scrisse personalmente questa autobiografia completa, raccontando la propria vita, i propri studi e il proprio ruolo a Dalaran. A capo del Kirin Tor, i suoi scritti sono una testimonianza preziosa di storia e magia.",al={"cos'è questo libro","libro autobiografia integrale","tomo di antonidas"}},{q="Da dove proviene questo libro?",a="Il volume proviene dalla biblioteca del Salone degli Esploratori di Forgiardente. Esploratori e archivisti nani raccolgono spesso testi storici e magici da tutti i continenti orientali.",al={"da dove viene il libro","viene da forgiardente","libro biblioteca forgiardente"}},{q="Perché questo libro è così ricercato?",a="Studiosi e bibliotecari cercano testi magici potenti o storici per ampliare i propri archivi e preservare il sapere arcano. Le opere dei maghi leggendari sono particolarmente ricercate, per evitare che vadano perdute o finiscano nascoste in collezioni straniere.",al={"perché collezionare libri magici","chi vuole il libro di antonidas","perché la biblioteca vuole questo"}},{q="Cosa è successo all'Arcimago Antonidas?",a="L'Arcimago Antonidas perì durante la Terza Guerra, quando il principe caduto Arthas Menethil e il Flagello invasero Dalaran. Antonidas eresse una potente barriera magica per difendere la città e i suoi segreti. Arthas infranse le difese e lo uccise per impadronirsi del Libro di Medivh.",al={"antonidas è morto","come è morto antonidas","cosa è successo ad antonidas"}},{q="La biblioteca di Forgiardente si accorgerà che il libro è sparito?",a="Il destinatario non si preoccupa che i nani notino l'assenza del libro. Gli archivi di Forgiardente sono così vasti che probabilmente nessuno si accorgerà della scomparsa di un singolo tomo.",al={"forgiardente noterà la mancanza del libro","rubare dalla biblioteca di forgiardente"}}},fp="48,205,28.382.0,35.417.0,27.304.0,37.216.0,30.178.0,36.224.0,36.278.0,51.163.0"}
P.entries["quest:79092"] = {n="Archmage Theocritus' Research Journal",s="Alla Torre di Azora, l'Arcimago Theocritus annota le sue indagini in un diario. Ora ne porti le intuizioni magiche agli studiosi della Biblioteca di Forgiardente, dove potranno arricchire l'archivio nanico.",h="Alla Torre di Azora, l'Arcimago Theocritus annota le sue indagini in un diario.",kw={"conoscenza arcana","arcimago theocritus","forgiardente","biblioteca di forgiardente","diario delle ricerche","theocritus","torre di azora"},ang={["class:Mage"]="Da mago, sai che gli appunti di figure illustri come l'Arcimago Theocritus aiutano a proteggere le opere magiche storiche negli archivi di Forgiardente.",["faction:Alliance"]="Come membro dell'Alleanza, contribuisci ad arricchire il grande deposito di conoscenza di Forgiardente per gli studiosi dell'Alleanza."},sec={{t="Appunti da campo di un maestro",b="L'Arcimago Theocritus è un incantatore stimato, conosciuto in tutta l'Alleanza. È di stanza alla Torre di Azora, nella parte orientale della Foresta di Elwynn, dove studia da solo da anni. Le sue indagini spaziano da curiosi artefatti e anomalie delle linee di ley alle minacce magiche nelle vicinanze.\n\nRegistra le sue scoperte in diari dettagliati. Questo volume offre una rara occasione di studiare le osservazioni personali di un arcimago anziano del Kirin Tor."},{t="Espansione degli archivi di Forgiardente",b="La Lega degli Esploratori e i custodi della Biblioteca di Forgiardente mantengono uno dei più grandi archivi del continente. Porti loro Archmage Theocritus' Research Journal, contribuendo a preservarne e catalogarne le intuizioni arcane accanto ai volumi storici di Khaz Modan. I bibliotecari accolgono nuove scoperte magiche che possano ampliare la loro conoscenza condivisa."}},faq={{q="Cos'è Archmage Theocritus' Research Journal?",a="Archmage Theocritus' Research Journal è un resoconto erudito delle sue ricerche. Lo porti alla Biblioteca di Forgiardente per preservare il sapere arcano e arricchirne gli archivi.",al={"consegna diario di theocritus","cos'è il diario di theocritus"}},{q="Chi è l'Arcimago Theocritus?",a="L'Arcimago Theocritus è un rinomato mago umano di stanza alla Torre di Azora, nella Foresta di Elwynn. Studia antiche perturbazioni magiche e artefatti.",al={"chi è theocritus","lore arcimago theocritus"}},{q="Dove viene portato questo diario?",a="Porti il diario agli archivisti della Biblioteca di Forgiardente. Raccolgono documenti rari e manoscritti magici.",al={"dove consegno il diario di theocritus","chi vuole il diario di theocritus"}},{q="Perché la biblioteca vuole questo diario?",a="Gli studiosi della Biblioteca di Forgiardente vogliono preservare il sapere arcano e studiare opere rare di maestri incantatori. Queste opere arricchiscono i loro documenti storici.",al={"perché collezionare diari magici","scopo del diario di theocritus"}},{q="Si possono consegnare altre opere magiche alla biblioteca?",a="Sì. I curatori ti incoraggiano a cercare altre opere magiche e testi storici per i loro archivi.",al={"altri diari da consegnare","ci sono altri libri per la biblioteca"}},{q="Che tipo di ricerca è contenuta nel diario?",a="Il diario contiene appunti e osservazioni sulle approfondite indagini dell'Arcimago Theocritus sui fenomeni magici e sul sapere arcano.",al={"cosa c'è nel diario di theocritus","contenuti del diario di theocritus"}}},fp="37,199,22.424.0,32.354.0,46.168.0,27.150.0,30.121.0,39.156.0,51.99.0,50.131.0"}
P.entries["quest:79093"] = {n="Rumi of Gnomeregan: The Collected Works",s="Si cerca un'opera raccolta da Rumi of Gnomeregan per la collezione di una biblioteca. Le sue pagine custodiscono scritti e conoscenze gnomiche che altrimenti potrebbero andare perduti.",h="Si cerca un'opera raccolta da Rumi of Gnomeregan per la collezione di una biblioteca.",kw={"opere raccolte","tradizione di gnomeregan","scritti gnomici","biblioteca","opere magiche","rumi of gnomeregan"},ang={["class:Mage"]="Da mago, apprezzi gli scritti rari provenienti da ogni angolo di Azeroth, che approfondiscono la comprensione della teoria e della storia della magia.",["faction:Alliance"]="Come membro dell'Alleanza, puoi aiutare studiosi e curatori a proteggere opere letterarie e testi magici preziosi per il sapere condiviso dell'Alleanza.",["race:Gnome"]="Da gnomo, preservare gli scritti raccolti di pensatori come Rumi aiuta a mantenere vive la tua cultura e la tua eredità intellettuale dopo la caduta di Gnomeregan."},sec={{t="Preservare il pensiero gnomico",b="Gli scritti gnomici furono dispersi, sepolti o lasciati in pericolo quando i trogg invasero Gnomeregan. Ora studiosi e archivisti cercano manoscritti, trattati e opere raccolte sopravvissuti. Sperano di mantenere viva la saggezza e l'ingegno dei pensatori gnomici."},{t="Recupero d'archivio",b="Quando i viaggiatori trovano opere raccolte sul campo e le portano agli archivi, i curatori le aggiungono alle loro collezioni in crescita. Ogni manoscritto recuperato amplia ciò che gli studiosi possono approfondire. Gli archivisti accolgono altri testi magici e storici, mantenendoli a disposizione di studiosi, maghi e storici che custodiscono il sapere di Azeroth."}},faq={{q="Cos'è Rumi of Gnomeregan: The Collected Works?",a="Rumi of Gnomeregan: The Collected Works è una raccolta di scritti gnomici ricercata da una biblioteca. Un avventuriero la porta a uno studioso affinché le sue conoscenze siano conservate e approfondite.",al={"missione rumi of gnomeregan","cos'è rumi of gnomeregan","chi è rumi"}},{q="Dove vengono consegnate queste opere raccolte?",a="Le opere raccolte vanno a un curatore o a uno studioso che si occupa della collezione di una biblioteca. Cercano scritti importanti e trattati magici da custodire negli archivi.",al={"dove consegno le opere di rumi","chi prende i libri di rumi","consegna collezione rumi"}},{q="Perché la biblioteca vuole queste opere raccolte?",a="La biblioteca vuole preservare con queste opere importanti studi. Studiosi e archivisti raccolgono testi rari, trattati storici e manoscritti magici, soprattutto scritti provenienti da Gnomeregan.",al={"perché collezionare i libri di rumi","scopo di rumi of gnomeregan","perché la biblioteca vuole rumi"}},{q="Chi è Rumi of Gnomeregan?",a="Rumi of Gnomeregan è un autore erudito o esperto di magia, le cui opere raccolte sono ricercate dagli archivisti. Poiché gran parte di Gnomeregan è stata invasa, le opere sopravvissute preservano le tradizioni di studio degli gnomi.",al={"chi era rumi of gnomeregan","tradizione di rumi","autore rumi"}},{q="Si possono portare altri libri alla biblioteca dopo questo?",a="Sì. Gli archivisti accolgono nuove scoperte e i curatori invitano i viaggiatori a portare alla biblioteca rari trattati magici e opere storiche.",al={"ci sono altri libri da trovare","posso portare altri testi","altre opere magiche biblioteca"}},{q="Chi può completare questo compito?",a="Gli avventurieri dell'Alleanza possono aiutare gli studiosi a proteggere gli scritti storici e arcani. Chiunque recuperi questi testi può portarli agli archivi e contribuire alla ricerca.",al={"requisiti missione rumi","chi può consegnare le opere di rumi","solo alleanza rumi"}}},fp="39,157,26.247.0,17.333.0,48.182.0,42.153.0,48.189.0,26.191.0,52.147.0,27.160.0"}
P.entries["quest:79094"] = {n="The Lessons of Ta'zo",s="Un bibliotecario ti chiede di portare in biblioteca opere magiche come The Lessons of Ta'zo. Ogni nuova opera arricchisce la collezione e il sapere.",h="Un bibliotecario ti chiede di portare in biblioteca opere magiche come The Lessons of Ta'zo.",kw={"collezione","forgiardente","sapere","lezioni","biblioteca","opere magiche","ta'zo"},sec={{t="La collezione di una biblioteca",b="Un bibliotecario ti chiede se hai portato qualcosa per la collezione della biblioteca. Sono benvenute le opere magiche che potrebbero giovarle, e il tuo impegno ne accresce il sapere."}},faq={{q="Chi chiede opere magiche?",a="Un bibliotecario ti chiede di portare opere magiche che potrebbero giovare alla biblioteca. The Lessons of Ta'zo è una di queste opere.",al={"chi è ta'zo","biblioteca di ta'zo","ta'zo"}},{q="Che cosa chiede il bibliotecario di portare in biblioteca?",a="Il bibliotecario chiede opere magiche che possano arricchire la collezione della biblioteca.",al={"cosa portare a ta'zo","libri magici","collezione della biblioteca"}},{q="Dove si trova la collezione?",a="I bibliotecari raccolgono opere simili a Roccavento e a Sepulcra.",al={"dov'è ta'zo","biblioteca di forgiaardente","posizione della biblioteca"}},{q="Perché il bibliotecario chiede opere magiche?",a="Il bibliotecario dice che il tuo impegno accresce il sapere della biblioteca.",al={"perché opere magiche","ampliare il sapere","aiutare la biblioteca"}}},fp="20,145,22.183.0,32.114.0,52.81.0,29.63.0,45.72.0"}
P.entries["quest:79095"] = {n="The Apothecary's Metaphysical Primer",s="I curatori cercano The Apothecary's Metaphysical Primer per arricchire i loro archivi. La sua consegna aiuta a preservare rare teorie alchemiche e arcane per ricercatori e incantatori.",h="I curatori cercano The Apothecary's Metaphysical Primer per arricchire i loro archivi.",kw={"alchimia","farmacista","sepulcra","biblioteca","opere magiche","manuale di metafisica","tomo"},ang={["class:Mage"]="Come mago, apprezzi i manuali di metafisica per ciò che rivelano sulla teoria magica, le interazioni alchemiche e le basi dell'arte degli incantesimi.",["faction:Horde"]="Come membro dell'Orda, puoi aiutare Owen Thadd a Sepulcra a recuperare rari trattati per le raccolte arcane della biblioteca."},sec={{t="Un'acquisizione erudita",b="I curatori accolgono volentieri The Apothecary's Metaphysical Primer per il suo studio dei principi esoterici e magici. Owen Thadd aggiunge il testo direttamente alla sua raccolta di riferimenti magici."},{t="Espandere gli archivi",b="La raccolta di Owen Thadd a Sepulcra conserva trattati specialistici. Portandogli rari manuali di teoria arcana e alchemica, aiuti a custodire negli archivi le intuizioni metafisiche e a renderle accessibili ai ricercatori, invece di lasciarle andare perdute nelle terre selvagge."}},faq={{q="Cos'è The Apothecary's Metaphysical Primer?",a="I curatori cercano The Apothecary's Metaphysical Primer come raro testo accademico per la loro raccolta di letteratura magica e lo studio delle scienze metafisiche.",al={"cos'è the apothecaries metaphysical primer","missione metaphysical primer","cos'è questo libro"}},{q="Chi vuole che questo manuale gli venga consegnato?",a="Owen Thadd a Sepulcra vuole che gli venga consegnato il manuale. Cerca opere magiche e trattati arcani per preservare le conoscenze a beneficio di ricercatori e incantatori.",al={"chi vuole questo libro","dove consegno il manuale","chi prende il manuale"}},{q="Perché la biblioteca colleziona opere come questa?",a="Biblioteche e archivi raccolgono opere metafisiche e magiche per ampliare le proprie conoscenze. Queste opere aiutano studiosi, alchimisti e arcanisti a studiare i principi arcani.",al={"perché la biblioteca vuole il manuale","scopo della raccolta del manuale","perché collezionare libri magici"}},{q="Puoi portare altre opere magiche alla biblioteca?",a="Gli studiosi che catalogano la letteratura magica accolgono volentieri altre scoperte arcane e accademiche che trovi per i loro archivi.",al={"ci sono altri libri da consegnare","posso portare altri libri","altri libri della biblioteca"}},{q="Che tipo di nozioni sono contenute in un manuale di metafisica?",a="Nello studio della magia, la metafisica riguarda la natura delle energie magiche, le forze invisibili che governano la realtà e il modo in cui i reagenti fisici interagiscono con le forze arcane.",al={"cosa significa metafisico wotlk classic","nozioni di metafisica wow","cos'è la metafisica dei farmacisti"}},{q="Chi ha scritto The Apothecary's Metaphysical Primer?",a="I documenti non indicano il nome dello speziale che ha scritto il manuale. Speziali e studiosi spesso compilano manuali sull'alchimia pratica, le miscele di erbe e le formule mistiche.",al={"chi ha scritto il manuale del farmacista","autore del manuale del farmacista","chi è il farmacista"}}},fp="36,172,23.186.0,22.266.0,45.154.0,40.158.0,45.160.0,48.117.0,56.168.0,47.170.0"}
P.entries["quest:79096"] = {n="Ataeric: On Arcane Curiosities",s="Ataeric cerca rari scritti magici per arricchire la collezione di una biblioteca. Gli studiosi sperano che queste opere approfondiscano i loro studi arcani e preservino il sapere arcano.",h="Ataeric cerca rari scritti magici per arricchire la collezione di una biblioteca.",kw={"arcano","curiosità arcane","ataeric","biblioteca","opere magiche","studiosi"},ang={["class:Mage"]="Da mago, nutri un interesse naturale per gli studi arcani. Recuperare trattati magici e contribuire alle biblioteche degli studiosi si addice alla tua arte.",["race:Dwarf"]="Da nano, conosci il valore dei documenti scritti, degli artefatti e del sapere oscuro. Gli studiosi nanici e la Lega degli Esploratori li stimano."},sec={{t="Preservare la Conoscenza Arcana",b="In tutta Azeroth, gli studiosi si affidano ai viaggiatori per recuperare tomi rari e trattati da luoghi pericolosi. Ataeric cerca scritti magici per ampliare gli studi arcani di un’istituzione. Ogni volume può aiutare gli studiosi a ricostruire pratiche che altrimenti potrebbero disperdersi o andare perdute."},{t="Un Archivio in Espansione",b="Il curatore aggiunge ogni curiosità all’archivio. La biblioteca è ancora alla ricerca di altri scritti magici trovati in giro per il mondo, così la sua collezione può crescere insieme alla ricerca."}},faq={{q="Qual è lo scopo di questa missione?",a="Ataeric cerca scritti magici da aggiungere alla collezione di sapere arcano di una biblioteca.",al={"cos'è questa missione","missione ataeric","consegna curiosità arcane"}},{q="Chi colleziona questi scritti arcani?",a="Ataeric ha scritto il trattato. Un ricercatore o un curatore raccoglie opere magiche e volumi rari per gli archivi di una biblioteca.",al={"chi lo vuole","chi riceve il libro","chi è ataeric"}},{q="Quale biblioteca beneficia di queste curiosità?",a="Le curiosità sono destinate a una collezione accademica conservata in una biblioteca di studiosi.",al={"che biblioteca è","dove vanno questi libri"}},{q="Ci sono altre opere magiche da collezionare?",a="Sì. Lo studioso accoglie qualsiasi altra opera magica trovata durante i tuoi viaggi, per ampliare il sapere della biblioteca.",al={"si può consegnarne di più","opere magiche ripetibili","altri libri per la biblioteca"}},{q="Perché la biblioteca cerca curiosità arcane?",a="La biblioteca cerca trattati rari per approfondire lo studio dell’arcano e preservare la conoscenza mistica.",al={"cosa studia la biblioteca","perché collezionare libri arcani"}},{q="Perché è importante recuperare le opere arcane?",a="Recuperare opere arcane porta conoscenze oscure in una biblioteca, dove possono essere conservate e studiate invece di restare perdute sul campo.",al={"è pericoloso","rischio magia arcana"}}},fp="30,158,27.279.0,20.179.0,34.79.0,35.116.0,46.77.0,40.108.0,45.99.0,41.136.0"}
P.entries["quest:79097"] = {n="Baxtan: On Destructive Magics",s="In biblioteca, Baxtan: On Destructive Magics si aggiunge alle opere che gli studiosi raccolgono per comprendere il pericoloso potere arcano.",h="In biblioteca, Baxtan: On Destructive Magics si aggiunge alle opere che gli studiosi raccolgono per...",kw={"arcano","baxtan","libro","magie distruttive","biblioteca","magia","tomo"},ang={["class:Mage"]="Se sei un mago, potresti apprezzare i trattati sulla magia distruttiva mentre studi il potere arcano e i suoi pericoli.",["class:Warlock"]="Se sei uno stregone, potresti capire perché gli studiosi cercano di comprendere i poteri instabili o proibiti.",["faction:Alliance"]="Come membro dell'Alleanza, trai beneficio dal sapere custodito per tutti nelle biblioteche dell'Alleanza."},sec={{t="Un tomo di arti rovinose",b="Gli studiosi cercano di preservare ciò che si sa sul sapere arcano. Quando trovi un testo sulla magia distruttiva, va custodito con cura dagli studiosi. Così se ne possono comprendere il potere e i pericoli, invece di perderlo."},{t="Curare la conoscenza della biblioteca",b="La biblioteca custodisce opere di storia, scienza e arcano. Il suo studioso accoglie i viaggiatori che recuperano trattati dimenticati dagli angoli pericolosi del mondo. Ogni volume arricchisce il sapere della biblioteca."}},faq={{q="Cos'è la missione \"Baxtan: On Destructive Magics\"?",a="Porti il trattato di Baxtan sulle magie distruttive a uno studioso della biblioteca, aggiungendo un'opera di magia alla collezione.",al={"cos'è baxtan on destructive magics","cos'è questa missione","missione baxtan"}},{q="Chi è Baxtan?",a="Baxtan scrisse On Destructive Magics. Lo studioso che lo riceve raccoglie importanti tomi e trattati magici per la biblioteca.",al={"chi è baxtan","npc baxtan","dove si trova baxtan"}},{q="Che tipo di libri cerca Baxtan?",a="Lo studioso della biblioteca cerca opere di studio e magia per la collezione, compresi i trattati che trovi in giro per il mondo.",al={"che tipo di libri vuole baxtan","collezione di libri di baxtan","altri libri per baxtan"}},{q="Dove finisce questa conoscenza magica?",a="I testi raccolti entrano nella collezione della biblioteca, dove gli studiosi li preservano per studiare l'arcano e i suoi pericoli.",al={"dove va il libro","quale biblioteca","collezione della biblioteca di forgiardente"}},{q="Perché la biblioteca colleziona opere sulla magia distruttiva?",a="Gli studiosi catalogano la magia distruttiva per comprenderne i pericoli, il funzionamento e le forme delle potenti energie arcane.",al={"perché studiare la magia distruttiva","conoscenza magie distruttive"}},{q="Puoi portare altre opere magiche a Baxtan?",a="Sì. Lo studioso accoglie altre opere magiche che scopri, nell'ambito di un impegno costante per raccogliere il sapere.",al={"ci sono altre missioni per baxtan","posso consegnare altri libri"}}},fp="29,115,22.202.0,27.205.0,50.113.0,14.126.0,42.122.0,41.120.0,56.108.0,43.101.0"}
P.entries["quest:791"] = {n="Carry Your Weight",s="In cima alla torre di guardia che domina Tranciacolle, Furl Sprezzaciglio chiede ai giovani avventurieri dell'Orda di raccogliere canovaccio dai nemici umani e centauri. L'età e le vecchie ferite gli impediscono di combattere in prima linea, così prepara rifornimenti per aiutarli nel loro cammino.",h="In cima alla torre di guardia che domina Tranciacolle, Furl Sprezzaciglio chiede ai giovani avventurieri...",kw={"brandelli di canovaccio","carry your weight","durotar","furl sprezzaciglio","kolkar","tranciacolle","torre di guardia di tranciacolle","tiragarde"},ang={["faction:Horde"]="Da giovane soldato dell'Orda a Durotar, fai affidamento su veterani esperti come Furl Sprezzaciglio. Ricordano ai nuovi arrivati che onorare l'Orda significa compiere ogni dovere richiesto dalla patria, che si tratti di sorvegliare un avamposto o cucire canovaccio.",["profession:Tailoring"]="Da sarto, puoi riconoscere in ogni borsa la dura arte di frontiera di Furl. Trasforma il pesante canovaccio scartato dagli invasori umani e dai centauri razziatori in equipaggiamento resistente, utile per sopravvivere nella natura selvaggia.",["race:Orc"]="Da orco, vedi in Furl un anziano che si è liberato dalla corruzione demoniaca e ha attraversato il mare con Thrall. Come altri della sua generazione, dedica i suoi ultimi anni a coltivare il futuro della sua giovane nazione."},sec={{t="La Chiamata di un Veterano",b="Furl Sprezzaciglio ha combattuto al fianco del Capoguerra Thrall a Durotar e sul Monte Hyjal. L'età e le vecchie ferite lo hanno rallentato, e ormai non brandisce più l'ascia in battaglia. Dalla torre di guardia sopra Tranciacolle, Furl mantiene una vigilanza costante e dà l'allarme quando arriva il pericolo. Ha lasciato la prima linea, ma dal suo avamposto continua a servire la nuova generazione di difensori."},{t="Canovaccio Recuperato",b="Man mano che la presa dell'Orda sulla regione si rafforza, gli allarmi dei corni di segnalazione si fanno meno frequenti. Furl ha più tempo per fabbricare equipaggiamento utile, ma il canovaccio robusto scarseggia nei canyon aridi di Durotar. Sulla costa orientale, gli intrusi Kul Tirano ne portano in abbondanza. Anche i centauri nomadi Kolkar che vagano per le pianure ne hanno molto. Furl recupera il canovaccio da queste forze ostili e lo cuce per farne borse multiuso destinate agli esploratori in attività."}},faq={{q="Chi è Furl Sprezzaciglio?",a="Furl Sprezzaciglio è un orco veterano ormai anziano, di stanza in cima alla torre di guardia sopra Tranciacolle. Ha combattuto al fianco di Thrall mentre l'Orda fondava Durotar e si è unito ai ranghi che sconfissero Archimonde sul Monte Hyjal. Non può più combattere in prima linea, ma Furl continua a sorvegliare la zona e a fabbricare equipaggiamento da campo per i giovani guerrieri dell'Orda.",al={"chi è furl","storia di furl sprezzaciglio","chi assegna carry your weight"}},{q="Dove si possono trovare i brandelli di canovaccio a Durotar?",a="I brandelli di canovaccio si possono raccogliere dagli umani Kul Tirano lungo la costa orientale di Durotar e dai centauri nomadi Kolkar che vagano per le pianure. Entrambi ne portano in abbondanza, e il robusto canovaccio può essere recuperato dai loro averi.",al={"dove trovare brandelli di canovaccio","chi lascia brandelli di canovaccio","luoghi brandelli di canovaccio"}},{q="Dov'è la torre di guardia in cui si trova Furl?",a="La torre di guardia di Furl sorge sugli alti dirupi rocciosi, appena a nord-ovest di Tranciacolle. Un sentiero tortuoso dietro l'insediamento sale fino alla cima, dove si trova la sua vedetta di legno.",al={"dov'è furl sprezzaciglio","posizione torre di guardia di tranciacolle","trovare torre di guardia di tranciacolle"}},{q="Cosa crea Furl con i brandelli di canovaccio?",a="Furl cuce i brandelli di canovaccio per farne borse multiuso per i giovani avventurieri in viaggio per Durotar. Lo spazio aggiuntivo permette loro di trasportare provviste, razioni e armi recuperate attraverso la dura natura selvaggia.",al={"cosa crea furl","a cosa serve il canovaccio","ricompensa brandelli di canovaccio"}},{q="Perché un vecchio guerriero crea borse invece di combattere?",a="L'età e le vecchie ferite impediscono a Furl di avere la velocità e la forza necessarie sul campo. Trova onore nella pensione, sorvegliando Tranciacolle e fabbricando equipaggiamento per aiutare i combattenti più giovani a difendere il regno.",al={"perché furl lavora","perché furl resta nella torre","perché furl non combatte"}},{q="In quale guerra ha combattuto Furl?",a="Furl ha combattuto agli ordini del Capoguerra Thrall durante la Terza Guerra, contribuendo a insediare l'Orda a Durotar e affrontando la Legione Infuocata sul Monte Hyjal. Si unì alla tregua temporanea e necessaria tra l'Orda, gli Elfi della Notte e l'Alleanza per sconfiggere Archimonde.",al={"storico di battaglia di furl","cosa faceva furl prima","archimonde furl"}}},fp="17,233,19.360.0,16.407.0,22.324.0,44.217.0,46.165.0,44.199.0,56.218.0,27.241.0"}
P.entries["quest:79192"] = {n="Stepping Stones",s="In un accampamento remoto nelle Savane, una nota logora indica Stepping Stones, un rifugio montano vicino a Desolanda. Dice che due corrieri hanno effettuato consegne per The New Plague e definisce le loro morti improvvise semplici incidenti da speziale.",h="In un accampamento remoto nelle Savane, una nota logora indica Stepping Stones, un rifugio montano vicino a...",kw={"desolanda","mercenari","montagne","new plague","nota","lo speziale reale","stepping stones","le savane"},ang={["class:Rogue"]="Da ladro, sai come seguire le tracce di informatori anonimi e valutare i messaggi segreti lasciati tra Desolanda e le Savane.",["faction:Horde"]="Da viandante dell'Orda nelle Savane, valuti se le voci di consegne di una piaga letale sul suolo di Kalimdor minaccino le tue terre e le tue alleanze.",["race:Undead"]="Per i viaggiatori Reietti, un riferimento di un ladro alla Società degli Speziali Reali e alle sue ricerche sul flagello potrebbe essere una questione urgente di sicurezza, o una pericolosa cospirazione interna."},sec={{t="Una nota nelle terre selvagge",b="Un messaggio strappato è appeso a una tavola di legno in un accampamento remoto nelle Savane. Mercenari, tagliagole e vagabondi si fermano in accampamenti simili per trovare un breve riparo, lontano dagli occhi di Crocevia o Porto Paranco. Tra i normali segnali della natura selvaggia, la nota ti dà motivo di guardare oltre l'accampamento, verso le montagne."},{t="Sussurri del New Plague",b="L'autore anonimo dice che due agenti hanno effettuato consegne per The New Plague, poi definisce le loro morti improvvise semplici incidenti da speziale. La nota ti invita a incontrarlo in un rifugio montano tra le Savane e Desolanda, dove potrete discutere della faccenda al sicuro."}},faq={{q="Di cosa parla la nota trovata in Stepping Stones?",a="La nota dice che due corrieri incaricati di consegnare The New Plague sono morti all'improvviso, cosa che l'autore definisce semplici incidenti da speziale. L'autore propone un luogo d'incontro in montagna per discutere di quanto accaduto.",al={"nota di stepping stones","di cosa parla la nota","testo della missione stepping stones"}},{q="Dove ti dice di andare la nota?",a="L'autore ti indirizza verso un rifugio appartato tra le montagne, fra le Savane e Desolanda.",al={"dove andare stepping stones","posticino accogliente tra le montagne","posizione stepping stones"}},{q="Cos'è il New Plague menzionato nella lettera?",a="The New Plague è una mistura letale sviluppata a Sepulcra dalla Società degli Speziali Reali dei Reietti. È destinata a distruggere sia il Flagello sia i nemici viventi. I suoi test e le consegne affidate ai corrieri in tutti i continenti portano segretezza e pericoli mortali.",al={"cos'è il new plague","piaga de lo speziale reale","consegne degli speziali"}},{q="Chi ha scritto la nota affissa alla tavola?",a="La nota è anonima e appuntata a una tavola di legno grezzo in un accampamento remoto. L'autore propone un luogo d'incontro in montagna fra le Savane e Desolanda.",al={"chi ha scritto la nota","autore di stepping stones","chi sta aspettando tra le montagne"}},{q="Perché i corrieri dei Reietti si trovano a Kalimdor?",a="Gli speziali dei Reietti raccolgono veleni esotici, spore e reagenti dalla flora e dalla fauna di Kalimdor. Coordinano le spedizioni tramite gli avamposti dell'Orda e le rotte selvagge.",al={"reietti nelle savane","perché il new plague a kalimdor","speziali nelle savane"}},{q="Perché gli accampamenti remoti vengono usati per note come questa?",a="Le Savane si estendono ben oltre i principali insediamenti e sono governate solo in parte. Stazioni di sosta neutrali, rifugi per mercenari e accampamenti di rinnegati offrono a viaggiatori, contrabbandieri e informatori un luogo discreto dove lasciare messaggi, lontano dall'Orda e dai posti di guardia regionali.",al={"storia degli accampamenti remoti","accampamenti mercenari savane"}}},fp="15,232,19.313.0,26.258.1,56.201.0,35.94.0,47.247.0,39.156.0,51.169.0,51.247.0"}
P.entries["quest:792"] = {n="Vile Familiars",s="Vile Familiars è un compito iniziale affidato da Zureetha Sguardolungo ai campioni appena arrivati nella Valle delle Sfide. Mentre sorvegliava le prove della valle, Zureetha ha scoperto un insidioso covo delle Lame Ardenti nascosto in una caverna vicina. Per controllare la loro improvvisa diffusione, le reclute vengono inviate a dare la caccia ai famigli demoniaci che strisciano sulla terra rossa di Durotar.",h="Vile Familiars è un compito iniziale affidato da Zureetha Sguardolungo ai campioni appena arrivati nella...",kw={"lame ardenti","covo delle lame ardenti","durotar","imp","antro del tirocinio","valle delle sfide","vile familiars","zureetha sguardolungo"},ang={["class:Warlock"]="Gli stregoni orchi e troll devono affrontare la realtà degli incantatori dell'ombra rinnegati che abusano dei patti demoniaci per la distruzione, invece di piegare le energie vili verso la sopravvivenza dell'Orda.",["faction:Horde"]="Le Lame Ardenti rappresentano una delle minacce interne più immediate per Durotar, cercando di corrompere la giovane Orda dall'interno prima che possa stabilire fermamente la sua sovranità.",["race:Orc"]="Per gli orchi che si sforzano di onorare il rifiuto di Thrall verso la schiavitù demoniaca, incontrare la corruzione vile nei loro sacri cortili d'addestramento è un amaro promemoria del fatto che l'eredità del Concilio dell'Ombra è ancora purulenta."},sec={{t="Un'ombra nella valle",b="La Valle delle Sfide deve essere un banco di prova in cui i giovani orchi e i Troll Lanciascura dimostrano la loro forza, disciplina e lealtà all'Orda di Thrall. Doveva servire a testare le reclute contro i predatori nativi come scorpidi e cinghiali, non contro la corruzione demoniaca. Eppure, nascosti in una caverna a nord-est, degli agenti che si fanno chiamare Lame Ardenti hanno stabilito un covo segreto proprio sotto lo sguardo attento dei supervisori della valle."},{t="Eliminazione degli imp",b="Zureetha Sguardolungo, un'istruttrice inviata a guidare i nuovi arrivati vicino all'Antro del Tirocinio, ha notato la sottile corruzione prima che potesse invadere il canyon. Creature demoniache minori note come Vile Familiars hanno iniziato a riversarsi dall'imboccatura della caverna, lanciando fuoco e minacciando chiunque si avvicini troppo. Prima che l'Orda possa stanare i padroni nascosti nell'ombra, le giovani reclute hanno il compito di abbattere questi servitori minori per mantenere la valle al sicuro."}},faq={{q="Chi assegna la missione Vile Familiars?",a="Zureetha Sguardolungo assegna la missione. È di stanza appena fuori dall'ingresso dell'Antro del Tirocinio, nel centro della Valle delle Sfide.",al={"chi assegna la missione vile familiars","chi dà vile familiars","dove prendere vile familiars"}},{q="Cosa sono i Vile Familiars?",a="I Vile Familiars sono piccole creature demoniache simili a imp, evocate e legate dai cultisti delle Lame Ardenti. Fungono da servitori minori e animali da compagnia, usando il fuoco per molestare gli intrusi.",al={"cosa sono i vile familiars","storia dei vile familiars","tipo di creatura dei vile familiars"}},{q="Dove si trova il Covo delle Lame Ardenti?",a="Il covo è annidato all'interno di una caverna nei tratti nord-orientali della Valle delle Sfide, oltre i cinghiali maculati e gli operai scorpidi che vagano nella zona.",al={"posizione del covo delle lame ardenti","dove si trova il covo delle lame ardenti","caverna nella valle delle sfide"}},{q="Perché le Lame Ardenti sono nella Valle delle Sfide?",a="Le Lame Ardenti sono un culto segreto dedicato a minare la nuova Orda di Thrall e a diffondere la corruzione demoniaca. Infiltrarsi nella Valle delle Sfide permette loro di nascondersi in segreto e minacciare la nuova generazione di combattenti dell'Orda.",al={"perché le lame ardenti sono qui","motivi delle lame ardenti","cosa vogliono le lame ardenti"}},{q="Cosa succede dopo aver completato Vile Familiars?",a="Una volta decimati i famigli fuori dalla caverna, Zureetha Sguardolungo ti indirizzerà ad addentrarti nella grotta per affrontare il capo dei cultisti e recuperare un Medaglione delle Lame Ardenti.",al={"seguito di vile familiars","cosa succede dopo vile familiars","missione medaglione delle lame ardenti"}},{q="Devo andare in profondità nella caverna per trovare i famigli?",a="No. Sebbene abitino all'interno della caverna, molti Vile Familiars sciamano intorno all'ingresso e sul suolo del canyon appena fuori dall'imboccatura della grotta.",al={"i vile familiars sono dentro la caverna","dove uccidere i vile familiars","farmare vile familiars"}}},fx={edfaf791={q="Perché Zureetha Sguardolungo vuole che i Famigli Vili vengano uccisi?",a="Zureetha Sguardolungo è arrivata nella Valle delle Sfide per guidare le nuove reclute, ma ha scoperto una corruzione crescente proprio alle porte dell'Orda. Il clandestino culto delle Lame Ardenti ha stabilito un covo segreto nelle caverne vicine, e gli Imp evocati si stanno riversando per tutta la valle. Per proteggere il campo di prova ed estirpare la contaminazione demoniaca prima che si diffonda ulteriormente, deve eliminare la loro avanguardia.",al={"perché uccidere i famigli vili","motivazioni di zureetha sguardolungo","perché zureetha vuole morti i famigli vili"}},["67a24c10"]={q="Perché Zureetha ti manda invece di occuparsi dei famigli da sola?",a="Sei nella Valle delle Sfide per dimostrare di essere degno di servire l'Orda. Mentre Zureetha coordina la risposta contro i cultisti clandestini e sorveglia l'esterno dell'Antro del Tirocinio, mandarti in missione serve a un duplice scopo: argina l'infestazione demoniaca che minaccia la valle e ti sottopone a un battesimo del fuoco fondamentale contro le forze oscure che minano il tuo popolo.",al={"perché mandare me","perché zureetha non combatte","perché devo uccidere i famigli"}}},fp="14,360,22.441.0,16.434.0,35.126.0,24.175.0,41.139.0,49.232.0,45.174.1,57.140.0"}
P.entries["quest:79236"] = {n="Cherry for Your Thoughts?",s="A Baia del Bottino, Tokal offre da bere in cambio della verità sugli attacchi agli avamposti umani e nanici. Le voci accusano l'Orda, ma la sua banda era sotto contratto mercenario privato.",h="A Baia del Bottino, Tokal offre da bere in cambio della verità sugli attacchi agli avamposti umani e nanici.",kw={"baia del bottino","ciliegia per i tuoi pensieri","grog alla ciliegia","sceriffo","mercenario","saccheggio","contratto privato","tokal"},ang={["faction:Alliance"]="Da membro dell'Alleanza, puoi scoprire che un committente privato ha assoldato i razziatori che hanno colpito gli accampamenti umani e nanici. Non li ha assoldati l'Orda.",["faction:Horde"]="Da avventuriero dell'Orda, puoi scoprire da Tokal che gli attacchi agli accampamenti dell'Alleanza sono avvenuti su commissione privata. Non erano un'aggressione ufficiale dell'Orda."},sec={{t="I sussurri a Baia del Bottino",b="Tokal si tiene nascosta a Baia del Bottino e sta in guardia dalle forze dell'ordine. Recenti incursioni hanno devastato gli accampamenti umani e nanici, e le voci accusano l'Orda. Quando arrivano viaggiatori che chiaramente non lavorano per lo sceriffo che indaga, Tokal racconta un'altra versione. Si offre di raccontarla in cambio di un drink."},{t="Mercenari privati",b="Tokal ammette di aver partecipato al saccheggio degli avamposti umani e nanici, ma sostiene che l'Orda non abbia compiuto le incursioni. La sua banda lavorava sotto contratto privato per una terza parte senza nome. Tokal pretende un Grog alla Ciliegia prima di rivelare chi ha pagato l'operazione e perché."}},faq={{q="Chi è Tokal?",a="Tokal è una mercenaria nascosta a Baia del Bottino. Uno sceriffo indaga sulle incursioni contro insediamenti umani e nanici, e Tokal offre di rivelare chi l'ha assunta in cambio di un Grog alla Ciliegia.",al={"chi è tokal","tokal baia del bottino","chi assegna la missione del grog alla ciliegia"}},{q="Perché Tokal vuole un Grog alla Ciliegia?",a="Tokal vuole un Grog alla Ciliegia prima di parlare dei suoi vecchi contratti. Poi spiegherà chi ha finanziato privatamente le incursioni contro gli accampamenti dell'Alleanza.",al={"perché comprare grog alla ciliegia","grog alla ciliegia tokal","cosa vuole tokal"}},{q="L'Orda ha saccheggiato gli accampamenti umani e nanici?",a="Tokal dice che l'Orda non ha ordinato le incursioni contro gli accampamenti umani e nanici. Le voci accusano l'Orda, ma il suo gruppo lavorava sotto un contratto mercenario privato.",al={"chi ha assunto tokal","l'orda ha attaccato gli accampamenti dell'alleanza","l'orda era dietro le incursioni"}},{q="Perché Tokal è preoccupata per uno sceriffo?",a="Tokal teme uno sceriffo che indaga sul saccheggio degli insediamenti umani e nanici. Si assicura che chiunque le si avvicini a Baia del Bottino non sia stato mandato per consegnarla alla giustizia.",al={"chi è lo sceriffo","tokal si nasconde dallo sceriffo","lo sceriffo cerca tokal"}},{q="Dove si trova il Grog alla Ciliegia per Tokal?",a="I locandieri e gli osti di Baia del Bottino vendono Grog alla Ciliegia. Portare un boccale a Tokal soddisfa la sua richiesta e la spinge a raccontare la sua storia.",al={"dove trovare grog alla ciliegia","posizione grog alla ciliegia","grog a baia del bottino"}},{q="Perché Tokal si trova a Baia del Bottino?",a="Baia del Bottino è un porto di pirati, al di fuori della stretta giurisdizione dell'Alleanza e dell'Orda. Offre un rifugio a una mercenaria che si nasconde dopo le incursioni contro gli accampamenti umani e nanici.",al={"perché tokal è a baia del bottino","nascondiglio di tokal"}}},fp="25,167,25.301.0,19.269.1,13.166.0,34.135.0,68.153.0,37.173.0,39.133.0,34.175.0"}
P.entries["quest:793"] = {n="Broken Alliances",s="Gorn ti manda a est, nella Piana di Lethlor, per liberare due draghi neri vincolati dal Sigillo della Terra. È il seguito della prima Broken Alliances.",h="Gorn ti manda a est, nella Piana di Lethlor, per liberare due draghi neri vincolati dal Sigillo della Terra.",kw={"stormo dei draghi neri","blacklash","orchi di roccianera","gorn","hematus","piana di lethlor","sigillo della terra","simbolo della terra"},sec={{t="Tre Pietre Runiche",b="Tre pietre runiche tengono chiuso il Sigillo della Terra, una in ciascuno dei pilastri Diamante, Opale e Ametista della Piana di Lethlor. Gorn ti dà il Simbolo della Terra, che estrae le pietre e apre il sigillo.\n\nInnumerevoli draghi vivono nella piana, e Blacklash ed Hematus sono nemici formidabili. Gorn li vuole entrambi morti, e vuole che tu gli riporti i loro vincoli."},{t="Cosa ne pensa Gorn",b="Gorn dice che lo stormo dei draghi neri è ancora alleato con gli orchi rinnegati di Roccianera. Crede che draghi e orchi debbano essere tenuti a freno o scacciati. Con Blacklash ed Hematus morti, l'Orda potrà guardare a ovest, verso i Bastioni di Roccianera."}},faq={{q="Chi assegna questa missione?",a="Gorn ti manda nella Piana di Lethlor, come passo successivo dopo la prima Broken Alliances.",al={"chi dà la missione broken alliances","posizione di gorn","chi assegna broken alliances"}},{q="Dov'è situata la Piana di Lethlor?",a="La Piana di Lethlor si trova all'estremità orientale delle Maleterre, dove innumerevoli draghi hanno la loro dimora.",al={"posizione della piana di lethlor","come arrivare alla piana di lethlor","dov'è la piana di lethlor"}},{q="Come si liberano Blacklash ed Hematus?",a="Usa il Simbolo della Terra per estrarre una pietra runica da ciascuno dei tre pilastri. Inserisci le pietre nel Sigillo della Terra per liberare entrambi i draghi.",al={"come evocare blacklash","sigillo della terra","pilastri di diamante opale ametista"}},{q="Cosa deve essere riportato a Gorn?",a="Quando entrambi i draghi saranno morti, porta a Gorn i vincoli di Blacklash, le catene di Hematus e il Simbolo della Terra.",al={"oggetti da consegnare per broken alliances","cosa vuole indietro gorn","vincoli di blacklash"}}},fp="16,137,16.354.0,21.228.1,21.86.0,32.99.0,38.140.0,34.113.0"}
P.entries["quest:79360"] = {n="Elemental Aid",s="Una richiesta di ricambiare l’aiuto degli elementi ti manda nelle Gallerie di Lamaspina. I quilboar stanno distorcendo il potere elementale e i loro piani minacciano queste terre.",h="Una richiesta di ricambiare l’aiuto degli elementi ti manda nelle Gallerie di Lamaspina.",kw={"charlga fiancospino","aiuto elementale","elementi","quilboar","piani dei quilboar","gallerie di lamaspina"},ang={["class:Shaman"]="In quanto sciamano, hai padroneggiato gli elementi e ti viene chiesto di ricambiare il loro aiuto proteggendoli dai piani dei quilboar."},sec={{t="Un appello agli elementi",b="Gli elementi ti hanno aiutato e ora ti viene chiesto di ricambiare il favore. I quilboar distorcono il loro potere per i propri fini e sembrano voler estendere la loro influenza oltre questi confini. Ti mandano nelle Gallerie di Lamaspina per fermare i loro piani e proteggere queste terre."}},faq={{q="Perché devo andare nelle Gallerie di Lamaspina?",a="I quilboar stanno distorcendo gli elementi per i propri fini e sembrano voler estendere la loro influenza. Ti viene chiesto di fermare i loro piani e proteggere queste terre.",al={"perché gallerie di lamaspina","perché andare alle gallerie","motivo aiuto elementale"}},{q="Chi è Charlga Fiancospino?",a="Charlga Fiancospino è la quilboar che devi sconfiggere nelle Gallerie di Lamaspina.",al={"chi è charlga","charlga fiancospino","fiancospino"}},{q="Quali informazioni devo raccogliere?",a="Ti viene chiesto di raccogliere informazioni sui piani dei quilboar.",al={"piani dei quilboar","quali informazioni","informazioni sui piani"}},{q="Perché dovrei aiutare gli elementi?",a="Hai ricevuto aiuto dagli elementi e ti viene chiesto di ricambiare il favore proteggendo queste terre dai piani dei quilboar.",al={"perché aiuto elementale","aiutare gli elementi","ricambiare gli elementi"}}},fp="13,154,22.256.0,35.154.0,26.76.0,39.61.0,31.128.0"}
P.entries["quest:79361"] = {n="Storm, Earth, and Fire",s="Prate Scruta Nubi ti chiede di fermare i quilboar, che vogliono inondare Millepicchi con uno sciamanesimo distorto. Un tomo per il tuo addestramento potrebbe aiutarti a dissipare la tempesta in arrivo.",h="Prate Scruta Nubi ti chiede di fermare i quilboar, che vogliono inondare Millepicchi con uno sciamanesimo...",kw={"prate scruta nubi","quilboar","tempesta terra e fuoco","millepicchi","tomo","sciamanesimo distorto","totem distorti"},sec={{t="Si avvicina una tempesta",b="Prate Scruta Nubi aveva in programma di proseguire il tuo addestramento, ma la minaccia a Millepicchi non può attendere. Hai visto che i quilboar non vanno sottovalutati. Prate ti dà un tomo destinato allo studio e ti chiede di raccogliere totem distorti di fuoco, terra, aria e acqua. Il tomo potrebbe contenere un modo per dissipare la tempesta che stanno scatenando."}},faq={{q="Chi chiede aiuto?",a="Prate Scruta Nubi ti chiede di raccogliere totem distorti a Millepicchi.",al={"chi è prate","prate scruta nubi","scruta nubi"}},{q="Che cosa cercano di fare i quilboar?",a="Prate dice che i quilboar vogliono inondare Millepicchi con uno sciamanesimo distorto.",al={"piano dei quilboar","a cosa servono i totem","tempesta dei quilboar"}},{q="Che cosa mi dà Prate?",a="Prate ti dà un tomo destinato allo studio che potrebbe aiutarti a dissipare la tempesta in arrivo.",al={"tomo","cos'è il libro","tomo di studio"}},{q="Quali totem servono a Prate?",a="Prate ti chiede di raccogliere totem distorti di fuoco, terra, aria e acqua.",al={"tipi di totem","fuoco terra aria acqua","quali totem"}}},fp="22,175,18.334.0,23.70.0,35.81.0,24.87.0,29.68.0"}
P.entries["quest:79362"] = {n="Grant's Shield",s="Sirra Von’Indie cerca la mazza di Grant Valor al Cimitero di Collecorvo. Le armi potrebbero aiutarla a scoprire di più sul fiero eroe.",h="Sirra Von’Indie cerca la mazza di Grant Valor al Cimitero di Collecorvo.",kw={"borgoscuro","grant valor","mazza di grant","scudo di grant","cimitero di collecorvo","sirra von’indie","non morti","the valor family"},sec={{t="Un eroe caduto",b="A Borgoscuro, Sirra Von’Indie ti chiede di cercare la mazza di Grant Valor tra gli scheletri del Cimitero di Collecorvo. Il suo spettro ha lasciato lì lo scudo, ma il suo spirito continua a combattere i non morti. La mazza potrebbe indicare la creatura che lo ferì, e Sirra vuole studiare le armi."},{t="Le armi",b="A Borgoscuro, Sirra Von’Indie riflette su come una semplice creatura abbia sconfitto Grant Valor. Dice che un solo passo falso può lasciare una persona invalida per tutta la vita. Secondo lei, le armi rivelano molto del loro proprietario, e si prende il tempo di studiarle."}},faq={{q="Chi era Grant Valor?",a="Grant Valor era il capostipite della The Valor Family e un eroe di Collecorvo. Il suo spettro continua a combattere i non morti.",al={"grant valor","chi è grant","storia di grant"}},{q="Dov’è la mazza di Grant?",a="La mazza di Grant si trova su uno degli scheletri nel Cimitero di Collecorvo.",al={"mazza di grant","trovare la mazza di grant","posizione della mazza"}},{q="Perché cerco la mazza di Grant?",a="Sirra Von’Indie ti chiede di trovare la mazza per poter scoprire di più dalle armi di Grant.",al={"perché cercare la mazza","missione dello scudo di grant","cosa vuole sirra"}},{q="Dove porto la mazza?",a="Riporta la mazza di Grant a Sirra Von’Indie a Borgoscuro.",al={"restituire la mazza","posizione di sirra","dov’è von’indie"}},{q="Che cosa è successo a Grant?",a="Grant fu ferito da una creatura nel Cimitero di Collecorvo. Il suo spirito continua a combattere i non morti lì.",al={"grant ferito","come è stato ferito grant","scudo di grant valor"}}},fp="14,169,13.298.0,11.234.1,20.110.0,22.65.0,34.89.0,25.56.0,23.98.0"}
P.entries["quest:79363"] = {n="Silvia's Sword",s="La spada di Silvia Valor, lasciata dal suo spirito, ti indica i Defias nei pressi di Collecorvo. La lama apparteneva a una guardia che proteggeva i civili e le loro case.",h="La spada di Silvia Valor, lasciata dal suo spirito, ti indica i Defias nei pressi di Collecorvo.",kw={"cascina degli addle","borgoscuro","defias","guardia","collecorvo","silvia valor","spada di silvia","sirra von'indi","incompiuta missione"},sec={{t="La lama di una guardia",b="Lo spirito di Silvia Valor, guardia di Collecorvo, ha lasciato qui la sua spada. Silvia ha trascorso la vita a difendere i civili e le loro case. Il suo spirito visita ancora le fattorie, e i Defias si sono insediati a Cascina degli Addle, a sud di Collecorvo. Scacciarli potrebbe essere l'incompiuta missione di Silvia, e Sirra Von'Indi a Borgoscuro attende di sapere come andrà a finire."},{t="Lo studio della lama",b="A Cascina degli Addle, i Defias sono il primo indizio per risolvere l'incompiuta missione di Silvia Valor. Quando torni da Sirra Von'Indi a Borgoscuro, lei riconosce che Silvia era una brava guerriera e una difensora, anche se aveva una visione ristretta di chi meritasse protezione. Sirra non riesce a capire cosa voglia Silvia dalla spada, così esamina la lama più a fondo."}},faq={{q="Chi era Silvia Valor?",a="Silvia Valor era una guardia a Collecorvo che ha trascorso la vita a proteggere i civili e le loro case.",al={"storia di silvia valor","chi è silvia","silvia, guardia di collecorvo"}},{q="Perché lo spirito di Silvia visita le fattorie?",a="Lo spirito di Silvia visita ancora le fattorie, e la sua incompiuta missione potrebbe riguardare i Defias a Cascina degli Addle.",al={"perché il fantasma di silvia","perché infesta le fattorie","incompiuta missione di silvia"}},{q="Chi chiede della spada di Silvia?",a="Sirra Von'Indi a Borgoscuro si interessa alla storia della spada. Torni da lei per saperne di più su Silvia Valor una volta sistemati i Defias a Cascina degli Addle.",al={"chi ha dato la spada a silvia","spada di sirra von'indi","chi ha dato la spada a borgoscuro"}},{q="Dove si sono insediati i Defias?",a="I Defias si sono insediati a Cascina degli Addle, a sud di Collecorvo.",al={"defias a cascina degli addle","dove si trovano i defias","defias di collecorvo"}},{q="Cosa pensa Sirra di Silvia?",a="Sirra definisce Silvia una brava guerriera e una difensora, ma dice che aveva una visione ristretta di chi meritasse protezione.",al={"opinione di sirra su silvia","silvia guerriera","che tipo di guardia era silvia"}},{q="Cosa fa Sirra con la spada?",a="Sirra esamina più a fondo la lama di Silvia Valor.",al={"che fine fa la lama","sirra studia la spada","cosa succede dopo con la spada di silvia"}}},fp="14,154,15.360.0,17.332.1,21.95.0,43.109.0,30.150.0,41.73.0,32.116.0,34.43.0"}
